        ModelMotionSuggestionModeSetting = Config.Bind("AgentAdapter", "ModelMotionSuggestionMode", "Off",
            "Off, Observe, or Assist. Assist may queue at most one low-risk typed motion suggestion per turn after shared policy review; complex window and walking intents remain observe-only.");
        ModelMotionAssistCooldownSeconds = Config.Bind("AgentAdapter", "ModelMotionAssistCooldownSeconds", 6f,
