            "Evaluate adaptive local memory retrieval and log metadata only. This never changes prompts, replies, actions, or provider usage.");
        LivingContinuityPlayerReplyEnabled = Config.Bind(
            "LivingContinuity",
            "PlayerReplyEnabled",
            false,
            "D-025 Slice F independently Default-Off player-triggered Prompt ownership. The first source path is restricted to one OpenAI-compatible request with no search, tools, agent shadow, model-motion envelope or competing Prompt owner.");
        LivingContinuityPlayerReplyMemoryEnabled = Config.Bind(
            "LivingContinuity",
            "PlayerReplyLongTermMemoryPromptEnabled",
            defaultValue: false,
            "D-025 Slice F independently Default-Off permission to read "
            + "the existing local Memory Core and transmit at most four "
            + "privacy-admitted local.runtime.chat excerpts (maximum "
            + "1,200 Unicode scalars) to the exact player-reply provider. "
            + "Sensitive, legacy-import and full-history data are never "
            + "admitted.");
        LivingContinuityUnifiedPromptOwnershipEnabled = Config.Bind(
            "LivingContinuity",
            "UnifiedPromptOwnershipEnabled",
            false,
            "D-026 independently Default-Off single Prompt root for the "
            + "existing player-reply and Memory inputs. The legacy "
            + "Character slot is retired and remains empty. It requires "
            + "the existing F2 player-reply source and does not enable "
            + "Memory by itself.");
        LivingContinuityUnifiedPlayerReplyProviderEnabled = Config.Bind(
            "LivingContinuity",
            "UnifiedPlayerReplyProviderEnabled",
            false,
            "D-026 independently Default-Off provider-neutral F2 text "
            + "executor. It preserves D-025 OpenAI/DeepSeek admission, "
            + "performs one request, and adds no retry, fallback, tools "
            + "or provider authority.");
        LivingContinuityProactiveNoteEnabled = Config.Bind(
            "LivingContinuity",
            "ProactiveNoteEnabled",
            false,
            "D-025 Slice F independently Default-Off proactive AI Note source. It also requires an explicit per-process Arm and retains the existing AI Note gates. Source/predeployment only until separately deployed.");
        LivingContinuityUnifiedProactiveNoteProviderEnabled = Config.Bind(
            "LivingContinuity",
            "UnifiedProactiveNoteProviderEnabled",
            false,
            "D-026 independently Default-Off provider-neutral F3 Gemini "
            + "text executor. It preserves the existing one-call Note "
            + "admission and provider-start telemetry.");
        ProviderRuntimeRegistryObserveEnabled = Config.Bind(
            "ProviderRuntime",
            "RegistryObserveEnabled",
            false,
            "D-031 Stage E metadata-only route observation. Independently "
            + "Default Off. It compares the exact existing Legacy route "
            + "with the Registry projection and cannot read credentials, "
            + "write Prompt, call a Provider, deliver a Completion, retry, "
            + "fallback or change reply behavior.");
        ProviderRuntimeRegistryObserveStatusVisible = Config.Bind(
            "ProviderRuntime",
            "RegistryObserveStatusVisible",
            false,
            "Show bounded D-031 Stage E route metadata. Visibility grants "
            + "no Provider, Prompt, Completion or behavior authority.");
        ProviderRuntimeGeminiMigrationEnabled = Config.Bind(
            "ProviderRuntime",
            "GeminiMigrationEnabled",
            false,
            "D-031 Stage F Gemini-only Registry migration. Independently "
