    private bool TryCreateAndPatchAll(Type patchType, string harmonyId, string feature)
    {
        try
        {
            Harmony.CreateAndPatchAll(patchType, harmonyId);
            Log.LogInfo($"Initialized {feature}.");
            return true;
        }
        catch (Exception exception)
        {
            try
            {
                Harmony.UnpatchID(harmonyId);
            }
            catch (Exception rollbackException)
            {
                Log.LogError(
                    $"Could not remove partial {feature} patches"
                    + $" after initialization failed: {rollbackException}");
                throw new AggregateException(
                    $"Hard stop: {feature} patch initialization failed and"
                    + " its Harmony identity could not be removed.",
                    exception,
                    rollbackException);
            }
            Log.LogError(
                $"Could not initialize {feature}; patches under this Harmony"
                + $" identity were removed and the remaining MOD features"
                + $" will continue: {exception}");
            return false;
        }
    }

    private void TryInstallNativeDialogueHermesCapturePatches()
    {
        var harmonyId = PluginGuid + ".native-dialogue-memory";
        try
        {
            NativeDialogueHermesCapturePatches.Install(
                harmonyId);
            Log.LogInfo(
                "Initialized native dialogue Hermes memory capture.");
        }
        catch (Exception exception)
        {
            try
            {
                Harmony.UnpatchID(harmonyId);
            }
            catch (Exception rollbackException)
            {
                throw new AggregateException(
                    "Native dialogue Hermes capture failed and its partial Harmony patches could not be removed.",
                    exception,
                    rollbackException);
            }
            Log.LogWarning(
                "Could not initialize native dialogue Hermes memory capture; "
                + "the game remains usable without native-line memory: "
                + exception.GetType().Name
                + ".");
        }
    }

    private void ReloadConfigurationForRequestedD029Isolation()
    {
        var localApplicationData =
            Environment.GetFolderPath(
                Environment.SpecialFolder.LocalApplicationData);
        var environmentProfileId =
            Environment.GetEnvironmentVariable(
                D029IsolatedTestProfile.EnvironmentVariableName);
        var isolationRequested =
            !string.IsNullOrWhiteSpace(environmentProfileId)
            || D029IsolatedTestProfile.HasActivationTicket(
                localApplicationData);
        if (!isolationRequested)
            return;

        try
        {
            // IL2CPP startup can expose bound defaults before the persisted
            // configuration has completed its first load.  The disposable
            // activation ticket never grants authority by itself: reload the
            // same private ConfigFile and keep the independently Default-Off
            // coordinator check in InitializePlayerDataStorage.
            Config.Reload();
            PluginLog.LogInfo(
                "Reloaded persisted configuration before D-029 isolated "
                + "Profile admission; the activation ticket did not enable "
                + "the coordinator.");
        }
        catch (Exception exception)
        {
            D029AggressiveIntegrationEnabled.Value = false;
            PluginLog.LogError(
                "Could not reload persisted configuration for D-029 "
                + "isolation; coordinator remains disabled and activation "
                + "will fail closed: "
                + exception.GetType().Name
                + ".");
        }
    }

    internal static string RetiredLegacyPlaintextProviderCredential(
        ConfigEntry<string>? ignored = null)
        => LegacyPlaintextProviderCredentialSeal.Read(ignored);

    private static ConfigDescription
        RetiredLegacyPlaintextProviderCredentialDescription()
        => new(
            "Retired credential field. Configure provider access in the "
            + "Lilith Control Center.",
            new AcceptableValueList<string>(string.Empty));

    private void MigrateKnownWeatherMojibakeDefault()
    {
        if (MigrateKnownMojibake(
                WeatherLocationName,
                DefaultWeatherLocationNameZhHant,
                "鍙板寳"))
        {
            Config.Save();
            PluginLog.LogInfo(
                "Migrated the known mojibake weather default without "
                + "replacing a custom value.");
        }
    }

    private static bool MigrateKnownMojibake(ConfigEntry<string> entry, string correctedDefault, params string[] knownPrefixes)
    {
        var value = entry.Value ?? string.Empty;
        if (string.IsNullOrWhiteSpace(value) || !knownPrefixes.Any(prefix => value.StartsWith(prefix, StringComparison.Ordinal)))
            return false;

        entry.Value = correctedDefault;
        return true;
    }
}

