    private static IntPtr _loadedPlayerNameArchive;
    private static float _nextPlayerNameObservationAt;

    internal static void ObserveOfficialArchiveLoaded(Archive? archive)
    {
        // Load's successful return is the read barrier. Never invoke the lazy
        // Archive.Instance getter just to discover a player's name.
        if (archive is not null)
            Interlocked.Exchange(ref _loadedPlayerNameArchive, archive.Pointer);
    }

    private static void UpdateOfficialPlayerNameOnMainThread(bool force = false)
    {
        if (!Plugin.RuntimeAuthorityEnabled.Value) return;
        var now = Time.unscaledTime;
        if (!force && now < _nextPlayerNameObservationAt) return;
        _nextPlayerNameObservationAt = now + 1f;
        try
        {
            var loaded = Interlocked.CompareExchange(
                ref _loadedPlayerNameArchive, IntPtr.Zero, IntPtr.Zero);
            if (loaded == IntPtr.Zero || !Archive._sessionInitialized) return;
            var archive = Archive._instance;
            if (archive is null || archive.Pointer != loaded) return;
            var name = archive.playerName;
            if (name is null) return; // An unavailable value is not a clear command.
            if (PlayerNameSync.Observe(true,
                    PlayerNameRule.IsUnsetName(name) ? string.Empty : name))
                _ = PlayerNameSync.SynchronizeAsync();
        }
        catch
        {
            // Optional metadata must never modify a save or break the game.
            // In particular, do not log the private value on an interop fault.
        }
    }
