    internal static void NotifyLivingPlayerReplyConfigurationChanged()
    {
        lock (LivingContinuityPlayerReplyCancellationLock)
        {
            Interlocked.Increment(
                ref _livingContinuityPlayerReplyConfigurationGeneration);
            _livingContinuityPlayerReplyCancellation?.Cancel();
        }
    }

    internal static void NotifyLivingProactiveNoteConfigurationChanged()
        => Interlocked.Increment(
            ref _livingProactiveNoteConfigurationGeneration);

    internal static void NotifyFormalIntegrationConfigurationChanged()
    {
        NotifyLivingPlayerReplyConfigurationChanged();
        NotifyLivingProactiveNoteConfigurationChanged();
        NotifyD031ProviderRuntimeObserveConfigurationChanged();
        NotifyD031ProviderRuntimeGeminiMigrationConfigurationChanged();
        NotifyD031ProviderRuntimeDeepSeekMigrationConfigurationChanged();
        Interlocked.Increment(ref _d022AssistConfigurationGeneration);
        _d022AssistConfigurationFingerprint = string.Empty;
        _controlCenterTelemetryNextCaptureAt = -1f;
        _unifiedProviderTelemetryNextRefreshAt = -1f;
        ReportFormalIntegrationStopBleedAdmission();
        if (Plugin.FormalIntegrationActive)
        {
            lock (MemoryLock)
                RecentConversation.Clear();
            // D058: Formal settings cannot restart the retired Memory Core.
        }
        else
        {
            LoadMemory();
        }
    }

    internal static void NotifyAdvancedComputerActionsConfigurationChanged()
    {
        _controlCenterTelemetryNextCaptureAt = -1f;
        ReportFormalIntegrationStopBleedAdmission();
    }

    internal static void ReportFormalIntegrationStopBleedAdmission()
    {
        var admission = FormalIntegrationStopBleedPolicy.Evaluate(
            Plugin.FormalIntegrationActive,
            Plugin.AdvancedComputerActionsEnabled.Value);
        if (admission.DesktopToolAdmission
                == FormalDesktopToolAdmission.SuppressedByFormalIntegration
            && admission.AdvancedDesktopToolsConfigured)
        {
            Plugin.PluginLog.LogWarning(
                "Formal Integration startup admission suppressed the "
                + "configured legacy Advanced Computer Actions value. "
                + "F6 and F7 remain on the Hermes game bridge.");
            return;
        }

        Plugin.PluginLog.LogInfo(
            "Formal Integration startup admission: legacy desktop tools="
            + admission.DesktopToolAdmission
            + ", legacy rolling context="
            + (admission.LegacyRollingContextEnabled
                ? "enabled"
                : "suppressed")
            + ".");
    }

    private static void UpdateFormalIntegrationObservability(
        DialogueManager manager)
    {
        ObserveFormalInputActivity();
        if (Time.unscaledTime < _controlCenterTelemetryNextCaptureAt)
            return;
        _controlCenterTelemetryNextCaptureAt = Time.unscaledTime + 0.5f;

        try
        {
            var now = DateTimeOffset.UtcNow;
            var provider = Plugin.FormalIntegrationActive
                ? "Gemini"
                : NormalizeAiProvider(Plugin.AiProvider.Value);
            var motionMode = ResolveMotionDirectorMode().ToString();
            var effectiveConfiguration = string.Join(
                "|",
                provider,
                Plugin.FormalIntegrationActive ? "1" : "0",
                Plugin.Effective(Plugin.VoiceEnabled.Value) ? "1" : "0",
                Plugin.Effective(Plugin.ConversationHistoryEnabled.Value)
                    ? "1"
                    : "0",
                Plugin.MotionDirectorEnabled.Value
                    ? "1"
                    : "0",
                motionMode,
                Plugin.Effective(Plugin.GlobalMotionPhysicsEnabled.Value)
                    ? "1"
                    : "0",
                "0", // Retired Character writer compatibility slot.
                Plugin.Effective(
                    Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value)
                    ? "1"
                    : "0",
                Plugin.Effective(
                    Plugin.LivingContinuityPlayerReplyEnabled.Value)
                    ? "1"
                    : "0",
                Plugin.Effective(
                    Plugin.LivingContinuityPlayerReplyMemoryEnabled.Value)
                    ? "1"
                    : "0",
                Plugin.Effective(
                    Plugin.LivingContinuityProactiveNoteEnabled.Value)
                    ? "1"
                    : "0",
                "0", // Retired Orchestrator observer compatibility slot.
                "0");
            if (!string.Equals(
                    effectiveConfiguration,
                    _controlCenterTelemetryConfigurationFingerprint,
                    StringComparison.Ordinal))
            {
                if (_controlCenterTelemetryConfigurationFingerprint.Length > 0)
                    _controlCenterTelemetryConfigurationGeneration++;
                _controlCenterTelemetryConfigurationFingerprint =
                    effectiveConfiguration;
            }

            var projection =
                ControlCenterStageBLegacyProjectionAdapter.Project(
                    new LegacyControlCenterProjectionInput(
                        ControlCenterTelemetryRuntimeIdentity,
                        _controlCenterTelemetryConfigurationGeneration,
                        now,
                        provider,
                        string.Equals(provider, "Gemini", StringComparison.Ordinal)
                            && !string.IsNullOrWhiteSpace(
                                Plugin.RetiredLegacyPlaintextProviderCredential(
                                    Plugin.GeminiApiKey)),
                        Plugin.Effective(Plugin.VoiceEnabled.Value),
                        Plugin.Effective(
                            Plugin.ConversationHistoryEnabled.Value),
                        Plugin.MotionDirectorEnabled.Value,
                        motionMode,
                        Plugin.Effective(
                            Plugin.GlobalMotionPhysicsEnabled.Value),
                        false, // Retired Character writer compatibility slot.
                        Plugin.Effective(
                            Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value),
                        Plugin.Effective(
                            Plugin.LivingContinuityPlayerReplyEnabled.Value),
                        Plugin.Effective(
                            Plugin.LivingContinuityPlayerReplyMemoryEnabled.Value),
                        Plugin.Effective(
                            Plugin.LivingContinuityProactiveNoteEnabled.Value),
                        false, // Retired Orchestrator observer compatibility slot.
                        false));
            if (projection.Admission
                    != LegacyControlCenterProjectionAdmission.Accepted
                || projection.Projection == null)
            {
                return;
            }
            Volatile.Write(
                ref _controlCenterTelemetryProjection,
                projection.Projection.WithRuntimeTelemetry(
                    CaptureFormalIntegrationTelemetry(manager, now)));
            EnsureControlCenterTelemetryServer();
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogDebug(
                "Formal integration telemetry skipped one capture: "
                + exception.GetType().Name);
        }
    }

    private static void ObserveFormalInputActivity()
    {
        if (!Plugin.FormalIntegrationActive)
            return;
        var now = DateTimeOffset.UtcNow;
        var mouseActive = Input.GetMouseButtonDown(0)
            || Input.GetMouseButtonDown(1)
            || Input.GetMouseButtonDown(2);
        var position = Input.mousePosition;
        if (_formalInputMousePositionInitialized
            && (position - _formalInputLastMousePosition).sqrMagnitude > 4f)
        {
            mouseActive = true;
        }
        _formalInputLastMousePosition = position;
        _formalInputMousePositionInitialized = true;
        if (mouseActive)
        {
            _formalInputLastMouseAt = now;
            _formalInputMouseActivitySamples++;
        }
        if (Input.anyKeyDown && !mouseActive)
        {
            _formalInputLastKeyboardAt = now;
            _formalInputKeyboardActivitySamples++;
        }
    }

    private static ControlCenterRuntimeTelemetry
        CaptureFormalIntegrationTelemetry(
            DialogueManager manager,
            DateTimeOffset now)
    {
        var metrics = new List<ControlCenterRuntimeMetric>();
        var stopBleed = FormalIntegrationStopBleedPolicy.Evaluate(
            Plugin.FormalIntegrationActive,
            Plugin.AdvancedComputerActionsEnabled.Value);
        foreach (var metric in
                 ControlCenterFormalTelemetryProjection.AgentRuntime(
                     AgentLanguageRuntime.GetSnapshot()))
        {
            metrics.Add(metric);
        }
        foreach (var metric in
                 ControlCenterFormalTelemetryProjection
                     .UnderstandingEnvelopeShadow(
                         UnderstandingEnvelopeShadowRuntime.GetSnapshot()))
        {
            metrics.Add(metric);
        }
        foreach (var metric in
                 ControlCenterFormalTelemetryProjection.PlayerTurn(
                     PlayerTurnOperations.GetSnapshot()))
        {
            metrics.Add(metric);
        }
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        var directControl = state?.IsDrag == true;
        var conversationBusy = _requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _aiPagesAwaitingAdvance
            || manager.IsBusy;
        var queueSnapshot = MotionProposalIngress.GetSnapshot();
        var pendingExecution = _activeMotionProposalExecution != null
            || queueSnapshot.Count > 0
            || _actionShowcasePendingOperation
                != ActionShowcasePendingOperation.None;
        var quietPeriod = state == null
            || state.IsSleep
            || state.ClothingState == LilithClothingState.Pajamas;
        var idleSeconds = Math.Max(0, GetWindowsIdleSeconds());
        string interruptibility;
        string interruptibilityReason;
        ControlCenterMetricHealth interruptibilityHealth;
        if (directControl)
        {
            interruptibility = "不可打擾";
            interruptibilityReason = "玩家正在直接拖曳莉莉絲";
            interruptibilityHealth = ControlCenterMetricHealth.Blocked;
        }
        else if (conversationBusy)
        {
            interruptibility = "不可打擾";
            interruptibilityReason = "對話或語音回合尚未完成";
            interruptibilityHealth = ControlCenterMetricHealth.Blocked;
        }
        else if (pendingExecution)
        {
            interruptibility = "暫緩";
            interruptibilityReason = "已有動作或提案等待完成";
            interruptibilityHealth = ControlCenterMetricHealth.Attention;
        }
        else if (quietPeriod)
        {
            interruptibility = "安靜時段";
            interruptibilityReason = "睡眠、睡衣時段或身體狀態不可用";
            interruptibilityHealth = ControlCenterMetricHealth.Attention;
        }
        else if (idleSeconds < 3)
        {
            interruptibility = "可能忙碌";
            interruptibilityReason = "系統偵測到玩家正在操作鍵鼠";
            interruptibilityHealth = ControlCenterMetricHealth.Attention;
        }
        else
        {
            interruptibility = "可以被打擾";
            interruptibilityReason = idleSeconds >= 60
                ? "玩家已暫停操作一段時間"
                : "目前沒有對話、拖曳或執行衝突";
            interruptibilityHealth = ControlCenterMetricHealth.Healthy;
        }
        metrics.Add(new ControlCenterRuntimeMetric(
            "situation.interruptibility",
            "situation",
            "打擾判斷",
            interruptibility,
            health: interruptibilityHealth));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "input.system-idle-seconds",
            "input",
            "系統閒置",
            idleSeconds,
            "秒"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "input.keyboard-samples",
            "input",
            "鍵盤活動樣本",
            _formalInputKeyboardActivitySamples,
            "次"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "input.mouse-samples",
            "input",
            "滑鼠活動樣本",
            _formalInputMouseActivitySamples,
            "次"));
        metrics.Add(new ControlCenterRuntimeMetric(
            "input.last-keyboard",
            "input",
            "最近鍵盤活動",
            AgeToken(_formalInputLastKeyboardAt, now)));
        metrics.Add(new ControlCenterRuntimeMetric(
            "input.last-mouse",
            "input",
            "最近滑鼠活動",
            AgeToken(_formalInputLastMouseAt, now)));

        int rememberedTurns;
        lock (MemoryLock)
            rememberedTurns = RecentConversation.Count;
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "memory.recent-turns",
            "memory",
            "近期對話回合",
            rememberedTurns,
            "則"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "memory.rolling-file-kib",
            "memory",
            "近期記憶檔案",
            File.Exists(MemoryPath)
                ? new FileInfo(MemoryPath).Length / 1024d
                : 0,
            "KiB"));
        metrics.Add(
            ControlCenterFormalTelemetryProjection.DesktopTools(stopBleed));
        metrics.Add(new ControlCenterRuntimeMetric(
            "integration.legacy-rolling",
            "integration",
            "Legacy rolling context",
            stopBleed.LegacyRollingContextEnabled
                ? "Legacy / Active"
                : "Formal / Suppressed",
            health: stopBleed.LegacyRollingContextEnabled
                ? ControlCenterMetricHealth.Attention
                : ControlCenterMetricHealth.Healthy));
        foreach (var metric in
                 ControlCenterFormalTelemetryProjection.EffectiveRoles(
                     Plugin.FormalIntegrationActive,
                     ResolveMotionDirectorMode().ToString()))
        {
            metrics.Add(metric);
        }
        // Legacy metric IDs remain compatible, but no host is started.
        metrics.Add(new ControlCenterRuntimeMetric(
            "memory.core-state",
            "memory",
            "舊記憶核心（已退役）",
            "Retired",
            health: ControlCenterMetricHealth.Healthy));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "memory.imported",
            "memory",
            "已匯入事件",
            0,
            "筆"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "memory.mirrored",
            "memory",
            "本次同步事件",
            0,
            "筆"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "memory.rejected",
            "memory",
            "拒絕／損壞事件",
            0,
            "筆",
            ControlCenterMetricHealth.Healthy));

        metrics.Add(new ControlCenterRuntimeMetric(
            "character.psychology-state",
            "character",
            "舊心理數值",
            "Retired",
            health: ControlCenterMetricHealth.Neutral));

        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.status",
            "initiative",
            "舊觀察狀態",
            "Retired"));
        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.latest-disposition",
            "initiative",
            "舊決策預覽",
            "舊觀察已退役"));

        int proactivePending;
        int proactiveSuccessfulInWindow;
        lock (AiNoteLock)
        {
            proactivePending = _aiNoteState.Pending.Count(
                item => item.Status == "pending");
            proactiveSuccessfulInWindow = _aiNoteState.DeliveredAt.Count(
                deliveredAt =>
                    deliveredAt >= now.Subtract(
                        ProactiveRespondPolicy.RollingWindow));
        }
        bool proactiveActive;
        lock (LivingProactiveNoteLock)
            proactiveActive = _livingProactiveNoteActive != null;
        var proactiveFormal = Plugin.FormalIntegrationActive;
        var proactiveAvailable = Plugin.Effective(
            Plugin.LivingContinuityProactiveNoteEnabled.Value);
        var proactiveMode = proactiveFormal
            ? "FormalBounded"
            : proactiveAvailable
                ? "SupervisedArm"
                : "Off";
        var latestProactiveTerminal =
            _livingProactiveNoteCancellationTelemetry?
                .Snapshot()
                .LastOrDefault();
        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.proactive-mode",
            "initiative",
            "主動文字權威",
            proactiveMode,
            health: proactiveFormal
                ? ControlCenterMetricHealth.Healthy
                : proactiveAvailable
                    ? ControlCenterMetricHealth.Attention
                    : ControlCenterMetricHealth.Blocked));
        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.proactive-operation",
            "initiative",
            "主動文字工作",
            proactiveActive ? "Active" : "Idle"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "initiative.proactive-pending",
            "initiative",
            "待處理主動事件",
            proactivePending,
            "件"));
        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.proactive-budget",
            "initiative",
            "七日成功預算",
            proactiveSuccessfulInWindow.ToString(
                CultureInfo.InvariantCulture)
            + "/"
            + ProactiveRespondPolicy.MaximumSuccessfulPerRollingWindow
                .ToString(CultureInfo.InvariantCulture)));
        metrics.Add(new ControlCenterRuntimeMetric(
            "initiative.proactive-last-terminal",
            "initiative",
            "最近主動終態",
            latestProactiveTerminal == null
                ? "None"
                : latestProactiveTerminal.Stage
                    + " / "
                    + latestProactiveTerminal.Reason));

        var motion = D022BaselineAssistLiveRuntime.GetSnapshot();
        metrics.Add(new ControlCenterRuntimeMetric(
            "motion.assist-status",
            "motion",
            "自主動作",
            motion.Status.ToString(),
            health: motion.Status == D022SliceEAssistStatus.Fault
                ? ControlCenterMetricHealth.Blocked
                : ControlCenterMetricHealth.Healthy));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "motion.completed",
            "motion",
            "完成動作",
            motion.CompletedCount,
            "次"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "motion.interrupted",
            "motion",
            "玩家搶占",
            motion.PlayerInterruptedCount,
            "次"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "motion.failed",
            "motion",
            "失敗動作",
            motion.FailedCount,
            "次",
            motion.FailedCount > 0
                ? ControlCenterMetricHealth.Attention
                : ControlCenterMetricHealth.Healthy));

        var provider = D031ProviderRuntimeGeminiMigration.GetSnapshot();
        var effectiveProvider = NormalizeAiProvider(Plugin.AiProvider.Value);
        var effectiveModel = ActiveChatModel(effectiveProvider);
        var effectiveProviderSource = Plugin.FormalIntegrationActive
            ? "FormalPinned"
            : "LegacyConfig";
        metrics.Add(new ControlCenterRuntimeMetric(
            "provider.active",
            "provider",
            "目前模型路由",
            effectiveProvider + " / " + effectiveModel,
            health: string.IsNullOrWhiteSpace(GetActiveChatApiKey())
                ? ControlCenterMetricHealth.Blocked
                : ControlCenterMetricHealth.Healthy));
        foreach (var metric in CaptureUnifiedProviderTelemetry(
                     effectiveProvider,
                     effectiveModel,
                     effectiveProviderSource))
            metrics.Add(metric);
        metrics.Add(new ControlCenterRuntimeMetric(
            "provider.runtime-status",
            "provider",
            "Provider Runtime",
            provider.Status.ToString()));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "provider.calls",
            "provider",
            "本次模型呼叫",
            provider.ProviderCalls,
            "次"));
        metrics.Add(ControlCenterRuntimeMetric.Number(
            "provider.failures",
            "provider",
            "模型失敗／取消",
            provider.Failed + provider.Cancelled,
            "次",
            provider.Failed + provider.Cancelled > 0
                ? ControlCenterMetricHealth.Attention
                : ControlCenterMetricHealth.Healthy));

        metrics.Add(new ControlCenterRuntimeMetric(
            "character.sole-writer",
            "character",
            "舊角色寫入",
            "Retired",
            health: ControlCenterMetricHealth.Neutral));
        metrics.Add(
            ControlCenterFormalTelemetryProjection.CharacterPromptOwner(
                false, false, false, false, false));

        return new ControlCenterRuntimeTelemetry(
            now,
            Plugin.FormalIntegrationActive ? "Running" : "Off",
            interruptibility,
            interruptibilityReason,
            ControlCenterFormalTelemetryProjection
                .PrioritizeForBoundedTransport(metrics));
    }

    private static IReadOnlyList<ControlCenterRuntimeMetric>
        CaptureUnifiedProviderTelemetry(
            string effectiveProvider,
            string effectiveModel,
            string effectiveSource)
    {
        if (Time.unscaledTime < _unifiedProviderTelemetryNextRefreshAt)
            return _unifiedProviderTelemetry;
        _unifiedProviderTelemetryNextRefreshAt = Time.unscaledTime + 5f;

        try
        {
            var desiredResult = UnifiedProviderControlStore.Load();
            var desiredAssignment = desiredResult.Accepted
                ? desiredResult.Snapshot?.TextAssignment
                : null;
            var desiredInstance = desiredAssignment == null
                ? null
                : desiredResult.Snapshot?.Instances.SingleOrDefault(value =>
                    string.Equals(
                        value.InstanceId,
                        desiredAssignment.InstanceId,
                        StringComparison.Ordinal));
            _unifiedProviderTelemetry =
                ControlCenterFormalTelemetryProjection.ProviderBinding(
                    effectiveProvider,
                    effectiveModel,
                    desiredInstance?.ProviderKind.ToString() ?? string.Empty,
                    desiredAssignment?.ModelId ?? string.Empty,
                    desiredInstance != null && desiredAssignment != null,
                    effectiveSource);
            if (_unifiedProviderTelemetryFailure.Length > 0)
            {
                Plugin.PluginLog.LogInfo(
                    "Unified Provider Desired telemetry recovered.");
                _unifiedProviderTelemetryFailure = string.Empty;
            }
        }
        catch (Exception exception)
        {
            var failure = exception.GetType().Name;
            if (!string.Equals(
                    _unifiedProviderTelemetryFailure,
                    failure,
                    StringComparison.Ordinal))
            {
                Plugin.PluginLog.LogWarning(
                    "Could not project Unified Provider Desired state into "
                    + $"read-only telemetry: {failure}. Further identical "
                    + "failures are suppressed until recovery.");
                _unifiedProviderTelemetryFailure = failure;
            }
            _unifiedProviderTelemetry =
                ControlCenterFormalTelemetryProjection.ProviderBinding(
                    effectiveProvider,
                    effectiveModel,
                    string.Empty,
                    string.Empty,
                    desiredAvailable: false,
                    effectiveSource: effectiveSource);
        }
        return _unifiedProviderTelemetry;
    }

    private static string AgeToken(
        DateTimeOffset? occurredAt,
        DateTimeOffset now)
        => occurredAt.HasValue
            ? Math.Max(0, (now - occurredAt.Value).TotalSeconds)
                .ToString("0.0", CultureInfo.InvariantCulture)
                + " 秒前"
            : "尚無";

    private static void EnsureControlCenterTelemetryServer()
    {
        if (_controlCenterTelemetryServerTask != null)
            return;
        _controlCenterTelemetryServerTask = Task.Run(
            RunControlCenterTelemetryServerAsync);
    }

    private static async Task RunControlCenterTelemetryServerAsync()
    {
        var cancellationToken = ControlCenterTelemetryShutdown.Token;
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await ControlCenterStageCNamedPipe.RunSingleSessionAsync(
                        ControlCenterStageCNamedPipe.StablePipeName,
                        () => Volatile.Read(
                            ref _controlCenterTelemetryProjection),
                        cancellationToken)
                    .ConfigureAwait(false);
            }
            catch (OperationCanceledException)
                when (cancellationToken.IsCancellationRequested)
            {
                return;
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogDebug(
                    "Control Center telemetry session ended: "
                    + exception.GetType().Name);
                try
                {
                    await Task.Delay(250, cancellationToken)
                        .ConfigureAwait(false);
                }
                catch (OperationCanceledException)
                    when (cancellationToken.IsCancellationRequested)
                {
                    return;
                }
            }
        }
    }

