    internal static void
        NotifyD031ProviderRuntimeGeminiMigrationConfigurationChanged()
    {
        Interlocked.Increment(
            ref _d031ProviderRuntimeGeminiMigrationConfigurationGeneration);
        D031ProviderRuntimeGeminiMigration.Disable();
        _d031ProviderRuntimeGeminiMigrationWasEnabled = false;
        _d031ProviderRuntimeGeminiMigrationArmKeyWasDown = false;
    }

    internal static void
        NotifyD031ProviderRuntimeDeepSeekMigrationConfigurationChanged()
    {
        Interlocked.Increment(
            ref _d031ProviderRuntimeDeepSeekMigrationConfigurationGeneration);
        D031ProviderRuntimeDeepSeekMigration.Disable();
        _d031ProviderRuntimeDeepSeekMigrationWasEnabled = false;
        _d031ProviderRuntimeDeepSeekMigrationArmKeyWasDown = false;
        _deepSeekProviderControlSnapshot = null;
        _deepSeekProviderControlNextRefreshAt = -1f;
    }

    private static void ReconcileD031ProviderRuntimeGeminiMigration()
    {
        // The literal Off branch precedes clock, hashing, runtime capture,
        // input polling, Registry projection and credential access.
        var enabled = Plugin.Effective(
                Plugin.ProviderRuntimeGeminiMigrationEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityPlayerReplyEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityUnifiedPlayerReplyProviderEnabled.Value)
            && string.Equals(
                NormalizeAiProvider(Plugin.AiProvider.Value),
                "Gemini",
                StringComparison.Ordinal);
        if (!enabled)
        {
            if (_d031ProviderRuntimeGeminiMigrationWasEnabled)
            {
                D031ProviderRuntimeGeminiMigration.Disable();
                _d031ProviderRuntimeGeminiMigrationWasEnabled = false;
            }
            _d031ProviderRuntimeGeminiMigrationArmKeyWasDown = false;
            return;
        }

        var runtime = CurrentCharacterRuntimeIdentity();
        var configurationGeneration = Interlocked.Read(
            ref _d031ProviderRuntimeGeminiMigrationConfigurationGeneration);
        var configurationFingerprint =
            CaptureD031ProviderRuntimeGeminiMigrationConfigurationFingerprint(
                runtime);
        D031ProviderRuntimeGeminiMigration.SetContinuousIntegration(
            Plugin.FormalIntegrationActive);
        D031ProviderRuntimeGeminiMigration.Reconcile(
            D031ProviderRuntimeStageFGeminiConfiguration.Create(
                configurationGeneration,
                configurationFingerprint,
                runtime));
        _d031ProviderRuntimeGeminiMigrationWasEnabled = true;

        if (Plugin.FormalIntegrationActive)
        {
            _d031ProviderRuntimeGeminiMigrationArmKeyWasDown = false;
            return;
        }

        var key = Plugin.ProviderRuntimeGeminiMigrationArmKey.Value;
        var keyDown = (Input.GetKey(KeyCode.LeftControl)
                       || Input.GetKey(KeyCode.RightControl))
                      && (Input.GetKey(KeyCode.LeftShift)
                          || Input.GetKey(KeyCode.RightShift))
                      && Input.GetKey(key);
        if (keyDown && !_d031ProviderRuntimeGeminiMigrationArmKeyWasDown)
        {
            var armed = D031ProviderRuntimeGeminiMigration.ArmForProcess();
            Plugin.PluginLog.LogInfo(
                armed
                    ? "D-031 Stage F Gemini Registry migration armed for "
                        + "one player-triggered reply in this process."
                    : "D-031 Stage F Gemini Registry migration Arm was "
                        + "rejected by the bounded runtime state.");
        }
        _d031ProviderRuntimeGeminiMigrationArmKeyWasDown = keyDown;
    }

    private static string
        CaptureD031ProviderRuntimeGeminiMigrationConfigurationFingerprint(
            CharacterRuntimeIdentity runtime)
        => ProviderRegistryCanonicalHash.Of(
            "D031/STAGE-F-GEMINI-LIVE-CONFIGURATION/1",
            Plugin.GeminiModel.Value.Trim(),
            string.IsNullOrWhiteSpace(
                Plugin.RetiredLegacyPlaintextProviderCredential(
                    Plugin.GeminiApiKey)) ? "0" : "1",
            Plugin.Effective(Plugin.LivingContinuityPlayerReplyMemoryEnabled.Value) ? "1" : "0",
            Plugin.Effective(Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value) ? "1" : "0",
            Plugin.Effective(Plugin.LivingContinuityUnifiedPlayerReplyProviderEnabled.Value) ? "1" : "0",
            ProviderExecutionBinding.RuntimeHash(
                runtime ?? throw new ArgumentNullException(nameof(runtime))));

    private static void ReconcileD031ProviderRuntimeDeepSeekMigration()
    {
        // The literal Off branch precedes clock, hashing, runtime capture,
        // input polling, Registry projection and credential access.
        var snapshot = RefreshDeepSeekProviderControlSnapshot();
        var enabled = Plugin.Effective(
                Plugin.ProviderRuntimeDeepSeekMigrationEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityPlayerReplyEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value)
            && Plugin.Effective(
                Plugin.LivingContinuityUnifiedPlayerReplyProviderEnabled.Value)
            && string.Equals(
                NormalizeAiProvider(Plugin.AiProvider.Value),
                "DeepSeek",
                StringComparison.Ordinal)
            && snapshot != null
            && snapshot.CredentialConfigured;
        if (!enabled)
        {
            if (_d031ProviderRuntimeDeepSeekMigrationWasEnabled)
            {
                D031ProviderRuntimeDeepSeekMigration.Disable();
                _d031ProviderRuntimeDeepSeekMigrationWasEnabled = false;
            }
            _d031ProviderRuntimeDeepSeekMigrationArmKeyWasDown = false;
            return;
        }

        var runtime = CurrentCharacterRuntimeIdentity();
        var configurationGeneration = Interlocked.Read(
            ref _d031ProviderRuntimeDeepSeekMigrationConfigurationGeneration);
        var configurationFingerprint =
            CaptureD031ProviderRuntimeDeepSeekMigrationConfigurationFingerprint(
                runtime,
                snapshot!);
        D031ProviderRuntimeDeepSeekMigration.SetContinuousIntegration(
            Plugin.FormalIntegrationActive);
        D031ProviderRuntimeDeepSeekMigration.Reconcile(
            D031ProviderRuntimeStageFGeminiConfiguration.CreateDeepSeek(
                configurationGeneration,
                configurationFingerprint,
                runtime));
        _d031ProviderRuntimeDeepSeekMigrationWasEnabled = true;

        if (Plugin.FormalIntegrationActive)
        {
            _d031ProviderRuntimeDeepSeekMigrationArmKeyWasDown = false;
            return;
        }

        var key = Plugin.ProviderRuntimeDeepSeekMigrationArmKey.Value;
        var keyDown = (Input.GetKey(KeyCode.LeftControl)
                       || Input.GetKey(KeyCode.RightControl))
                      && (Input.GetKey(KeyCode.LeftShift)
                          || Input.GetKey(KeyCode.RightShift))
                      && Input.GetKey(key);
        if (keyDown && !_d031ProviderRuntimeDeepSeekMigrationArmKeyWasDown)
        {
            var armed = D031ProviderRuntimeDeepSeekMigration.ArmForProcess();
            Plugin.PluginLog.LogInfo(
                armed
                    ? "D-031 Stage F DeepSeek Registry migration armed for "
                        + "one player-triggered reply in this process."
                    : "D-031 Stage F DeepSeek Registry migration Arm was "
                        + "rejected by the bounded runtime state.");
        }
        _d031ProviderRuntimeDeepSeekMigrationArmKeyWasDown = keyDown;
    }

    private static string
        CaptureD031ProviderRuntimeDeepSeekMigrationConfigurationFingerprint(
            CharacterRuntimeIdentity runtime,
            DeepSeekControlPlaneSnapshot snapshot)
        => ProviderRegistryCanonicalHash.Of(
            "D031/STAGE-F-DEEPSEEK-V4-LIVE-CONFIGURATION/1",
            snapshot.SelectedModel,
            snapshot.CredentialConfigured ? "1" : "0",
            ProviderRegistryCanonicalHash.Number(
                snapshot.ConfigurationGeneration),
            Plugin.Effective(Plugin.LivingContinuityPlayerReplyMemoryEnabled.Value) ? "1" : "0",
            Plugin.Effective(Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value) ? "1" : "0",
            Plugin.Effective(Plugin.LivingContinuityUnifiedPlayerReplyProviderEnabled.Value) ? "1" : "0",
            ProviderExecutionBinding.RuntimeHash(
                runtime ?? throw new ArgumentNullException(nameof(runtime))));

    private static DeepSeekControlPlaneSnapshot?
        RefreshDeepSeekProviderControlSnapshot(bool force = false)
    {
        if (!force
            && _deepSeekProviderControlNextRefreshAt >= 0f
            && Time.unscaledTime < _deepSeekProviderControlNextRefreshAt)
        {
            return _deepSeekProviderControlSnapshot;
        }
        var result = DeepSeekProviderControlStore.Load();
        _deepSeekProviderControlSnapshot = result.Accepted
            ? result.Snapshot
            : null;
        _deepSeekProviderControlNextRefreshAt = Time.unscaledTime + 1f;
        return _deepSeekProviderControlSnapshot;
    }

