    private static void PollCodexBridgeEvents()
    {
        if (!Plugin.CodexBridgeEnabled.Value || Time.unscaledTime < _nextCodexBridgePollAt)
            return;
        _nextCodexBridgePollAt = Time.unscaledTime + 0.25f;

        try
        {
            var (fileStore, consumer) = GetCodexBridgeQueueRuntime();
            Directory.CreateDirectory(CodexBridgeEventsDirectory);
            var recoveredClaims =
                fileStore.RecoverAbandonedClaims();
            if (recoveredClaims > 0)
            {
                Plugin.PluginLog.LogWarning(
                    "Codex bridge recovered or retained"
                    + $" {recoveredClaims} abandoned source claim(s).");
            }
            var files = Directory.GetFiles(CodexBridgeEventsDirectory, "*.json")
                .OrderBy(path => path, StringComparer.Ordinal)
                .Take(16)
                .ToArray();

            foreach (var path in files)
            {
                var outcome = consumer.Process(path);
                var receipt = outcome.Receipt;
                if (receipt.QuarantineEligible)
                {
                    var quarantinePermit = consumer
                        .TryCreateQuarantinePermit(receipt);
                    var quarantineDisposition = quarantinePermit == null
                        ? CodexBridgeQueueQuarantineDisposition.Unauthorized
                        : fileStore.TryQuarantineRejected(
                            path,
                            receipt,
                            quarantinePermit);
                    var quarantineFinalized = quarantineDisposition is
                        CodexBridgeQueueQuarantineDisposition.Quarantined
                        or CodexBridgeQueueQuarantineDisposition.Superseded;
                    var rejectedSourceFinalized = quarantineFinalized
                        && consumer
                            .ConfirmRejectedSourceFinalized(
                                quarantinePermit!,
                                receipt);
                    Plugin.PluginLog.LogWarning(
                        "Codex bridge source receipt"
                        + $" sequence={receipt.Sequence}"
                        + $" classification={receipt.Classification}"
                        + $" reason={receipt.RetentionReason}"
                        + $" disposition={quarantineDisposition}"
                        + $" finalized={rejectedSourceFinalized}"
                        + $" fingerprint={ShortFingerprint(receipt.QueueItemFingerprint)}.");
                    if (!rejectedSourceFinalized)
                        _nextCodexBridgePollAt = Time.unscaledTime + 3f;
                }
                else if (receipt.DeleteSucceeded)
                {
                    Plugin.PluginLog.LogInfo(
                        "Codex bridge source receipt"
                        + $" sequence={receipt.Sequence}"
                        + $" classification={receipt.Classification}"
                        + $" kind={receipt.EventKind}"
                        + " admitted=True deleted=True"
                        + $" fingerprint={ShortFingerprint(receipt.QueueItemFingerprint)}.");
                }
                else if (receipt.RetentionReason
                    == CodexBridgeQueueRetentionReason.SourceSuperseded)
                {
                    Plugin.PluginLog.LogInfo(
                        "Codex bridge admitted source revision was superseded"
                        + $" sequence={receipt.Sequence}"
                        + $" kind={receipt.EventKind}"
                        + $" fingerprint={ShortFingerprint(receipt.QueueItemFingerprint)}.");
                }
                else if (receipt.RetentionReason is
                    CodexBridgeQueueRetentionReason.ReadFailed
                    or CodexBridgeQueueRetentionReason.DeleteFailed)
                {
                    if (Time.unscaledTime >= _nextCodexBridgeFaultLogAt)
                    {
                        _nextCodexBridgeFaultLogAt = Time.unscaledTime + 3f;
                        Plugin.PluginLog.LogWarning(
                            "Codex bridge retained one source item"
                            + $" classification={receipt.Classification}"
                            + $" reason={receipt.RetentionReason}"
                            + $" fingerprint={ShortFingerprint(receipt.QueueItemFingerprint)}.");
                    }
                }
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Could not poll Codex bridge events"
                + $" type={exception.GetType().Name}.");
            _nextCodexBridgePollAt = Time.unscaledTime + 3f;
        }
    }

    private static (
        CodexBridgeQueueFileStore FileStore,
        CodexBridgeQueueConsumer Consumer) GetCodexBridgeQueueRuntime()
    {
        lock (CodexBridgeRuntimeGate)
        {
            if (_pendingCodexSignals != null
                && _codexBridgeFileStore != null
                && _codexBridgeConsumer != null)
            {
                return (_codexBridgeFileStore, _codexBridgeConsumer);
            }
            if (_pendingCodexSignals != null
                || _codexBridgeFileStore != null
                || _codexBridgeConsumer != null)
            {
                throw new InvalidOperationException(
                    "Codex Bridge queue runtime is partially initialized.");
            }

            var fileStore = new CodexBridgeQueueFileStore(
                CodexBridgeEventsDirectory,
                Path.Combine(CodexBridgeRootDirectory, "quarantine"));
            var signalQueue = new CodexBridgeBoundedSignalQueue(capacity: 24);
            var consumer = new CodexBridgeQueueConsumer(
                fileStore,
                signalQueue,
                new CodexBridgeProcessClock(),
                maximumAge: TimeSpan.FromMinutes(5),
                maximumFutureSkew: TimeSpan.FromMinutes(1),
                utcMonotonicDriftTolerance: TimeSpan.FromSeconds(2),
                initialUtcTrusted: true,
                receiptCapacity: 64,
                trackingCapacity: 128);
            _pendingCodexSignals = signalQueue;
            _codexBridgeFileStore = fileStore;
            _codexBridgeConsumer = consumer;
            return (fileStore, consumer);
        }
    }

    private static void ProcessPendingCodexSignal(DialogueManager manager)
    {
        var signalQueue = _pendingCodexSignals;
        if (!Plugin.CodexBridgeEnabled.Value
            || Time.unscaledTime < _nextCodexSignalAt
            || _requestInFlight
            || _aiPagesAwaitingAdvance
            || HasActivePublishedPlayerReplySpeech()
            || (_inputBubble != null && _inputBubble.activeSelf)
            || signalQueue == null
            || !signalQueue.TryDequeue(out var signal)
            || signal == null)
        {
            return;
        }

        string traditional;
        string simplified;
        string japanese;
        string english;
        string emotion;
        switch (signal.EventKind)
        {
            case CodexBridgeQueueEventKind.PermissionRequest:
                traditional = "這一步要你點頭，我才能繼續。";
                simplified = "这一步要你点头，我才能继续。";
                japanese = "ここから先は、君の許可が必要みたい。";
                english = "I need your approval before I can continue.";
                emotion = "emoji_daze_1";
                break;
            case CodexBridgeQueueEventKind.Stop:
                traditional = "做好了。你來看看吧。";
                simplified = "做好了。你来看看吧。";
                japanese = "終わったよ。見てみて。";
                english = "It is ready. Come take a look.";
                emotion = "emoji_smile_1";
                break;
            default:
                traditional = "嗯，我看看……";
                simplified = "嗯，我看看……";
                japanese = "うん、ちょっと見てみるね……";
                english = "Mm, let me take a look…";
                emotion = "emoji_calm_1";
                break;
        }

        var displayText = ApiKeyText(traditional, simplified, japanese, english);
        var speechText = IsJapaneseVoiceMode() ? japanese : traditional;
        PlayAiEmotion(emotion);
        ForceSaySynthetic(manager, displayText, string.Empty, 8f);
        if (Plugin.CodexBridgeVoiceEnabled.Value && Plugin.VoiceEnabled.Value)
            _ = RequestSpeechAsync(speechText, CapturePoseContext().VoiceStyle, IsJapaneseVoiceMode());
        _nextCodexSignalAt = Time.unscaledTime + 0.8f;
    }

    private static string ShortOpaqueId(string value)
    {
        return string.IsNullOrWhiteSpace(value) ? "none" : value[..Math.Min(8, value.Length)];
    }

    private static string ShortFingerprint(string value)
    {
        return string.IsNullOrWhiteSpace(value)
            ? "none"
            : value[..Math.Min(12, value.Length)];
    }

    private static void Postfix(DialogueManager __instance)
    {
        UpdateMusicPlayerShortcuts();
        AgentLanguageRuntime.BeginCycle();
        UpdateOfficialPlayerNameOnMainThread();
        LilithNativeNotesBridge.UpdateOnMainThread();
        UpdateNoteInboxToolOnMainThread();
        UpdateDailyNoteOnMainThread();
        RefreshD046GameControlProjection();
        UpdateOldMaid();
        UpdateChess();
        RefreshMiniGameAnswerRepairLifetime();
        UpdateMiniGameDialogue();
        UnityDesktopArtifactPresenter.Update(
            Plugin.DesktopArtifactPreviewEnabled.Value);
        UpdateD022BaselineAssistObserveRuntime();
        UpdateD022BaselineAssistLiveRuntime();
        UpdateD029AggressiveIntegrationRuntime();
        ReconcileD031ProviderRuntimeGeminiMigration();
        ReconcileD031ProviderRuntimeDeepSeekMigration();
        UpdateRuntimeStatusPanel();
        UpdateFormalIntegrationObservability(__instance);
        MonitorAutomaticHiddenRecovery();
        UpdateNativeScreenPeekRecovery();
        MaintainActionShowcaseSitAnchorCorrection();
        EnsureLocalVoiceHost();
        UpdateLocalVoicePreparation();
        UpdatePublishedPlayerReplySpeech();
        ObserveForegroundWindow();
        ProcessPendingForegroundProactiveBridgeResults();
        UpdateForegroundProactiveConversation(__instance);
        ProcessGeminiToolBatches();
        ProcessGeminiCompatibilityFallbacks();
        ProcessQwenToolBatches();
        ProcessWorkbenchProviderToolBatches();
        EnsureGameHermesNotificationListener();
        ProcessPendingGameHermesNotifications();
        ProcessLocalTimers(__instance);
        ProcessPendingReminderSpeech();
        RetireInvalidContinuationPlayback();
        ProcessPendingSystemAction();
        UpdateInputPlaceholderLocalization();
        TryCreateOneTestNote();
        ProcessAiNoteScheduler();
        PollCodexBridgeEvents();
        ProcessPendingCodexSignal(__instance);
        ProcessPendingGameHermesHistoryLoads();
        ProcessPendingGameHermesVoiceBridgeResults();
        if (CanAdmitLegacyVoicePlayback()
                 && !(PendingVoiceAudio.TryPeek(out var waitingVoice)
                     && waitingVoice.Reminder?.Continuation != null && IsOfficialOrQueuedVoicePlaying())
                 && PendingVoiceAudio.TryDequeue(out var sequence))
        {
            if (sequence.Reminder?.Continuation is { } continuation && !ContinuationIsCurrent(continuation))
            {
                ClearVoiceSequenceAudio(sequence);
                RetireReminderSpeech(sequence.Reminder, "its continuation expired or was superseded");
            }
            else if (!IsLegacyVoicePublicationCurrent(
                    sequence.PublicationSequence))
            {
                ClearVoiceSequenceAudio(sequence);
                if (sequence.Reminder != null)
                {
                    RequeueReminderSpeech(
                        sequence.Reminder,
                        countFailure: false);
                    Plugin.PluginLog.LogInfo(
                        "Deferred stale reminder voice until the newer "
                        + "F6/F7 reply finishes.");
                }
                else
                {
                    Plugin.PluginLog.LogInfo(
                        "Dropped stale queued legacy voice after a newer "
                        + "F6/F7 reply publication.");
                }
            }
            else if (sequence.Reminder != null
                     && !Plugin.VoiceEnabled.Value)
            {
                ClearVoiceSequenceAudio(sequence);
                RetireReminderSpeech(
                    sequence.Reminder,
                    "voice was disabled before playback");
            }
            else if (sequence.Reminder != null
                     && !ReminderSpeechLocaleIsCurrent(sequence.Reminder))
            {
                ClearVoiceSequenceAudio(sequence);
                RetireReminderSpeech(
                    sequence.Reminder,
                    "voice locale changed before playback");
            }
            else if (sequence.Reminder != null
                     && !sequence.Reminder.TryBeginPlayback())
            {
                ClearVoiceSequenceAudio(sequence);
                Interlocked.Exchange(
                    ref _reminderSpeechPipelineBusy,
                    0);
            }
            else
            {
                try
                {
                    SetVoicePitch(1f);
                    var played = PlayWav(sequence.Speech, "generated speech");
                    if (sequence.Reminder?.Continuation is { } activeContinuation)
                    {
                        _activeContinuationAudio = played;
                        _activeContinuationSpeech = activeContinuation;
                    }
                    if (sequence.Reminder != null)
                        ConsumeReminderSpeech(sequence.Reminder);
                }
                catch (Exception exception)
                {
                    Plugin.PluginLog.LogError($"Could not play voice sequence: {exception}");
                    if (sequence.Reminder != null)
                    {
                        RequeueReminderSpeech(
                            sequence.Reminder,
                            countFailure: true);
                    }
                }
            }
        }

        if (_requestInFlight && PendingReplies.TryDequeue(out var pendingReply))
        {
            RefreshMiniGameAnswerRepairLifetime();
            var currentPlayerTurnRuntimeGeneration =
                CurrentPlayerTurnRuntimeGeneration();
            var publicationAdmission =
                PlayerTurnOperations.EvaluatePublication(
                    pendingReply.Operation,
                    pendingReply.PublicationKind,
                    currentPlayerTurnRuntimeGeneration);
            if (publicationAdmission
                != PlayerTurnPublicationAdmission.Admitted)
            {
                _aiPagesAwaitingAdvance = false;
                var retiredForRuntimeChange =
                    TryRetireRuntimeChangedPlayerTurn(
                        pendingReply.Operation,
                        publicationAdmission,
                        currentPlayerTurnRuntimeGeneration);
                if (publicationAdmission
                        == PlayerTurnPublicationAdmission.NoActiveOperation
                    || retiredForRuntimeChange)
                {
                    _requestInFlight = false;
                }
                Plugin.PluginLog.LogWarning(
                    "Discarded a stale player-turn completion before "
                    + "DialogueManager publication; no visible text was "
                    + "rebound to another turn; admission="
                    + publicationAdmission
                    + ".");
            }
            else
            {
                var operationEnded = false;
                _aiPagesAwaitingAdvance =
                    HasPendingPageForOperation(pendingReply.Operation);
                _currentAiPageText = pendingReply.Text;
                _currentAiPageOperation = pendingReply.Operation;
                _aiTypingFinishedAt = -1f;
                AgentLanguagePublicationLease? languageLease = null;
                var agentPublicationFinished = false;
                try
                {
                    if (!TryAcquireAgentLanguageOutput(
                            __instance,
                            AgentLanguageSourceKind.OrdinaryPlayerTurn,
                            pendingReply.Operation.OperationId,
                            out languageLease,
                            out var languageArbitration)
                        || languageLease == null)
                    {
                        operationEnded =
                            TryFailAndReleasePlayerTurnPublication(
                                pendingReply.Operation);
                        Plugin.PluginLog.LogWarning(
                            "Player-turn language arbitration rejected "
                            + "publication before DialogueManager: reason="
                            + (languageArbitration?.Reason.ToString()
                                ?? "HostFaulted")
                            + ".");
                    }
                    else
                    {
                        if (pendingReply.Emotion.Length > 0)
                            PlayAiEmotion(pendingReply.Emotion);
                        ForceSaySynthetic(
                            __instance,
                            pendingReply.Text,
                            string.Empty,
                            30f);
                        agentPublicationFinished =
                            TryRecordAgentLanguagePublication(
                                languageLease,
                                published: true);
                        if (!agentPublicationFinished)
                        {
                            operationEnded =
                                TryFailAndReleasePlayerTurnPublication(
                                    pendingReply.Operation);
                            Plugin.PluginLog.LogWarning(
                                "Player-turn shared language publication "
                                + "receipt was rejected after DialogueManager "
                                + "returned.");
                        }
                        else
                        {
                            var publicationCommitGeneration =
                                CurrentPlayerTurnRuntimeGeneration();
                            if (!PlayerTurnOperations.TryPublish(
                                    pendingReply.Operation,
                                    pendingReply.PublicationKind,
                                    publicationCommitGeneration))
                            {
                                var commitAdmission =
                                    PlayerTurnOperations.EvaluatePublication(
                                        pendingReply.Operation,
                                        pendingReply.PublicationKind,
                                        publicationCommitGeneration);
                                operationEnded = commitAdmission
                                        == PlayerTurnPublicationAdmission
                                            .NoActiveOperation
                                    || TryRetireRuntimeChangedPlayerTurn(
                                        pendingReply.Operation,
                                        commitAdmission,
                                        publicationCommitGeneration);
                                if (!operationEnded)
                                {
                                    operationEnded =
                                        TryFailAndReleasePlayerTurnPublication(
                                            pendingReply.Operation);
                                }
                                Plugin.PluginLog.LogWarning(
                                    "Player-turn publication receipt was "
                                    + "rejected after DialogueManager returned; "
                                    + "the visible text was not rebound to "
                                    + "another turn.");
                            }
                            else
                            {
                                StartPublishedPlayerReplySpeech(
                                    pendingReply,
                                    publicationCommitGeneration,
                                    languageLease.CycleSequence);
                                // Hermes owns persistence; publishing is not a second memory write.
                                operationEnded =
                                    CompletePublishedPlayerTurn(pendingReply);
                            }
                        }
                    }
                }
                catch
                {
                    if (languageLease != null && !agentPublicationFinished)
                    {
                        TryRecordAgentLanguagePublication(
                            languageLease,
                            published: false);
                    }
                    TryFailAndReleasePlayerTurnPublication(
                        pendingReply.Operation);
                    throw;
                }
                if (operationEnded)
                {
                    CompleteWorkbenchPublishedTurn(
                        pendingReply.Operation,
                        pendingReply.TerminalDisposition);
                    _requestInFlight = false;
                }
            }
        }

        UpdateMotionIntentRuntime(__instance);
        HandleActionShowcase(__instance);
        UpdateMotionDirector(__instance);
        SynchronizeModelMotionSuggestionMode(ResolveModelMotionSuggestionMode());
        UpdateMotionExecutionAuthority();
        UpdateMotionProposalQueue(__instance);
        UpdateMotionProposalCompletions();
        UpdateAgentMotionSuggestionObservations();
        var suppressD046NewPresses =
            D046GameControlHotkeyAdmission.ShouldSuppressNewPresses(
                D046GameControlCaptureLease.IsActive(),
                _inputBubble != null
                    && _inputField != null
                    && _inputBubble.activeSelf);
        var suppressD046StopNewPresses =
            D046GameControlCaptureLease.IsActive();
        var stopKey = EffectiveD046StopKey();
        var stopTransition = ObserveD046ExactHotkey(
            stopKey,
            StopHotkeyLatch,
            D046GameControlProjection.Effective?.StopPortableKey,
            suppressD046StopNewPresses);
        var historyKey = EffectiveD046ConversationHistoryKey();
        var historyTransition = ObserveD046ExactHotkey(
            historyKey,
            ConversationHistoryHotkeyLatch,
            D046GameControlProjection.Effective?.ConversationHistoryPortableKey,
            suppressD046NewPresses);
        var voiceInputKey = EffectiveD046PushToTalkKey();
        var voiceInputTransition = ObserveD046ExactHotkey(
            voiceInputKey,
            VoiceInputHotkeyLatch,
            D046GameControlProjection.Effective?.PushToTalkPortableKey,
            suppressD046NewPresses);
        var textInputKey = EffectiveD046TextChatKey();
        var textInputTransition = ObserveD046ExactHotkey(
            textInputKey,
            TextInputHotkeyLatch,
            D046GameControlProjection.Effective?.TextChatPortableKey,
            suppressD046NewPresses);
        if (stopTransition.Pressed)
        {
            HandleD046Stop(__instance);
            return;
        }
        if (UpdateGameChatTestEndpoint(__instance))
            return;
        ReconcileGameHermesVoiceCapture(voiceInputTransition);
        if (UpdateConversationHistoryWindow(__instance, historyTransition))
            return;
        HandleGameHermesVoiceInput(
            __instance,
            voiceInputKey,
            voiceInputTransition);
        if (PendingTranscriptionErrors.TryDequeue(out var transcriptionError))
            ForceSaySynthetic(
                __instance,
                transcriptionError,
                string.Empty,
                6f);
        if (PendingTranscripts.TryDequeue(out var transcript))
        {
            _pendingVoiceSubmitText = transcript;
            _pendingVoiceSubmitAt = Time.unscaledTime + 1.5f;
            ForceSaySynthetic(
                __instance,
                ApiKeyText($"我聽見了：「{transcript}」", $"我听见了：“{transcript}”", $"「{transcript}」と聞こえたよ。", $"I heard: “{transcript}”"),
                string.Empty,
                4f);
        }
        if (_pendingVoiceSubmitText != null && Time.unscaledTime >= _pendingVoiceSubmitAt)
        {
            var voiceText = _pendingVoiceSubmitText;
            _pendingVoiceSubmitText = null;
            _pendingVoiceSubmitAt = -1f;
            SubmitAiInput(
                __instance,
                voiceText,
                PlayerTurnInputSurface.PushToTalkTranscript);
        }

        if (textInputTransition.Pressed)
        {
            if (IsGameHermesTextInputBusy())
            {
                Plugin.PluginLog.LogInfo($"Ignored {textInputKey} text input hotkey because a dialogue or AI request is active.");
                return;
            }
            ToggleInputBubble();
            return;
        }

        if (_inputBubble != null && _inputField != null && _inputBubble.activeSelf)
        {
            PositionMiniGameInputBubble();
            if (!IsLilithForeground())
            {
                // TMP_InputField cannot reliably recover after this transparent
                // desktop window loses native focus. Close and dispose the bubble;
                // the next shortcut invocation creates a clean input session.
                CloseInputBubble(clear: true);
                return;
            }

            if (_focusNextFrame)
            {
                _focusNextFrame = false;
                _inputField.ActivateInputField();
                _inputField.Select();
            }

            if (Input.GetKeyDown(KeyCode.Escape))
            {
                CloseInputBubble(clear: false);
                return;
            }

            if (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter))
            {
                var submitted = _inputField!.text.Trim();
                if (submitted.Length > 0)
                {
                    if (IsGameHermesTextInputBusy())
                    {
                        Plugin.PluginLog.LogInfo(
                            "Deferred text input submission while one "
                            + "game Hermes voice or dialogue ingress is "
                            + "still active.");
                        return;
                    }
                    CloseInputBubble(clear: true);
                    SubmitAiInput(
                        __instance,
                        submitted,
                        PlayerTurnInputSurface.TextEntry);
                }
                return;
            }
        }
    }

    private static bool IsGameHermesTextInputBusy()
        => _requestInFlight
            || _aiPagesAwaitingAdvance
            || _activeGameHermesVoiceCapture != null
            || _microphoneRecording
            || _transcriptionInFlight
            || _pendingVoiceSubmitText != null
            || !PendingTranscripts.IsEmpty;

    private static CharacterRuntimeIdentity
        CurrentCharacterRuntimeIdentity()
        => new(
            "profile-current",
            "character-runtime-"
                + Environment.ProcessId
                + "-"
                + CharacterRuntimeProcessEpoch,
            1,
            "local-session-"
                + Environment.ProcessId
                + "-"
                + CharacterRuntimeProcessEpoch,
            "owner-local");

    // Compatibility identity only; no traits, state or projection are constructed.
    private static CharacterProfileIdentity CurrentCharacterProfileIdentity()
    {
        return new CharacterProfileIdentity(
            "profile-current",
            profileVersion: 1,
            schemaVersion: 1,
            Convert.ToHexString(
                SHA256.HashData(
                    Encoding.UTF8.GetBytes(
                        "lilith|core-identity|v1|"
                        + "warmth=.82|autonomy=.78|sensitivity=.66|"
                        + "stubbornness=.52|forgiveness=.72"))),
            minimumCompatibleSchemaVersion: 1,
            maximumCompatibleSchemaVersion: 1);
    }

    private static void UpdateD029AggressiveIntegrationRuntime()
    {
        var enabled = IsD029AggressiveIntegrationOperational();
        if (!enabled && !_d029AggressiveIntegrationWasEnabled)
        {
            _d029AggressiveIntegrationArmKeyWasDown = false;
            return;
        }
        try
        {
            var runtime = CurrentCharacterRuntimeIdentity();
            var fingerprint = ProviderRegistryCanonicalHash.Of(
                "D029/PLUGIN-CONFIGURATION/1",
                enabled ? "1" : "0",
                NormalizeAiProvider(Plugin.AiProvider.Value),
                Plugin.GeminiModel.Value ?? string.Empty,
                "0", // Retired Character projection prerequisite.
                "0", // Retired CG-F ownership prerequisite.
                Plugin.LivingContinuityPlayerReplyEnabled.Value ? "1" : "0",
                Plugin.LivingContinuityUnifiedPromptOwnershipEnabled.Value
                    ? "1"
                    : "0",
                Plugin.MemoryCoreShadowEnabled.Value ? "1" : "0",
                Plugin.MemoryRetrievalShadowEnabled.Value ? "1" : "0",
                Plugin.LivingContinuityProactiveNoteEnabled.Value ? "1" : "0",
                Plugin.LivingContinuityUnifiedProactiveNoteProviderEnabled
                    .Value
                    ? "1"
                    : "0",
                Plugin.D022BaselineAssistEnabled.Value ? "1" : "0",
                Plugin.MotionDirectorEnabled.Value ? "1" : "0",
                Plugin.MotionDirectorModeSetting.Value ?? string.Empty);
            if (!string.Equals(
                    fingerprint,
                    _d029AggressiveIntegrationConfigurationFingerprint,
                    StringComparison.Ordinal))
            {
                if (_d029AggressiveIntegrationConfigurationFingerprint
                    .Length > 0)
                {
                    checked
                    {
                        _d029AggressiveIntegrationConfigurationGeneration++;
                    }
                }
                _d029AggressiveIntegrationConfigurationFingerprint =
                    fingerprint;
            }
            D029AggressiveIntegrationRuntime.Reconcile(
                new D029SourceHostConfiguration(
                    enabled,
                    runtime,
                    fingerprint,
                    _d029AggressiveIntegrationConfigurationGeneration));
            _d029AggressiveIntegrationWasEnabled = enabled;
            if (enabled)
                HandleD029AggressiveIntegrationArmShortcut(runtime);
            else
                _d029AggressiveIntegrationArmKeyWasDown = false;
            LogD029AggressiveIntegrationStateIfChanged(enabled);
        }
        catch (Exception exception)
        {
            // A direct desktop-pet launch can pass through a short-lived
            // Unity/Steam bootstrap process before the durable process takes
            // ownership.  A runtime fault must stop only this process.  Do
            // not assign ConfigEntry.Value here: BepInEx immediately saves
            // that assignment and would silently revoke the independently
            // persisted D-029 authorization for the successor process.
            _d029AggressiveIntegrationRuntimeFaulted = true;
            _d029AggressiveIntegrationWasEnabled = false;
            _d029AggressiveIntegrationArmKeyWasDown = false;
            Plugin.PluginLog.LogWarning(
                "D-029 integration coordinator stopped fail-closed after "
                + exception.GetType().Name
                + "; process-local fault latch set without changing the "
                + "persisted Default-Off configuration"
                + "; it created no Provider, Prompt, Memory, Queue, Motion "
                + "or execution output.");
        }
    }

    private static bool IsD029AggressiveIntegrationOperational()
        => Plugin.D029AggressiveIntegrationEnabled.Value
            && !_d029AggressiveIntegrationRuntimeFaulted;

    private static void HandleD029AggressiveIntegrationArmShortcut(
        CharacterRuntimeIdentity runtime)
    {
        var key = Plugin.D029AggressiveIntegrationArmKey.Value;
        var controlDown =
            IsKeyCurrentlyDown(KeyCode.LeftControl)
            || IsKeyCurrentlyDown(KeyCode.RightControl);
        var shiftDown =
            IsKeyCurrentlyDown(KeyCode.LeftShift)
            || IsKeyCurrentlyDown(KeyCode.RightShift);
        var down = key != KeyCode.None
            && controlDown
            && shiftDown
            && IsKeyCurrentlyDown(key);
        if (!down)
        {
            _d029AggressiveIntegrationArmKeyWasDown = false;
            return;
        }
        if (_d029AggressiveIntegrationArmKeyWasDown)
            return;
        _d029AggressiveIntegrationArmKeyWasDown = true;

        Plugin.PluginLog.LogWarning(
            "D-029 Arm rejected: RetiredCharacterRuntime; the required "
            + "legacy Character projection and CG-F owner have been retired. "
            + "No authority or replacement owner was created.");
    }

    private static D029PluginSignalAdmission RecordD029Signal(
        D029PluginSignal signal,
        CharacterRuntimeIdentity? runtime = null)
    {
        if (!IsD029AggressiveIntegrationOperational())
            return D029PluginSignalAdmission.Disabled;
        var admission = D029AggressiveIntegrationRuntime.Record(
            signal,
            runtime ?? CurrentCharacterRuntimeIdentity(),
            DateTimeOffset.UtcNow);
        var transitioned =
            D029AggressiveIntegrationRuntime.GetSnapshot();
        if (admission == D029PluginSignalAdmission.StepCompleted
            && transitioned.CurrentStep
                == D029IntegrationStep.ProactiveInteraction)
        {
            // This uses the already-accepted D-025 explicit Arm boundary;
            // it does not bypass any due, idle, cooldown, weekly, policy,
            // Prompt, Provider or final-delivery gate.
            _livingProactiveNoteArmed = true;
            Plugin.PluginLog.LogInfo(
                "D-029 armed the existing bounded D-025 proactive source "
                + "for its dedicated step; all original gates remain "
                + "authoritative.");
        }
        if (admission == D029PluginSignalAdmission.StepCompleted
            && transitioned.CurrentStep
                == D029IntegrationStep.MotionAssist)
        {
            var motionArm = D022BaselineAssistLiveRuntime.Arm();
            Plugin.PluginLog.LogInfo(
                "D-029 armed the existing bounded D-022 Motion Assist "
                + "for its dedicated step; result="
                + motionArm
                + ".");
        }
        if (admission is D029PluginSignalAdmission.StepCompleted
            or D029PluginSignalAdmission.RunCompleted
            or D029PluginSignalAdmission.CounterMismatch
            or D029PluginSignalAdmission.RuntimeMismatch
            or D029PluginSignalAdmission.Expired
            or D029PluginSignalAdmission.Terminal)
        {
            Plugin.PluginLog.LogInfo(
                "D-029 signal="
                + signal
                + ", admission="
                + admission
                + ", status="
                + transitioned.Source.Status
                + ", next="
                + (transitioned.CurrentStep?.ToString() ?? "-")
                + ", records="
                + transitioned.Source.RecordCount
                + "/"
                + D029IntegrationCeilings.MaximumSteps
                + ".");
        }
        return admission;
    }

    private static void LogD029AggressiveIntegrationStateIfChanged(
        bool enabled)
    {
        var snapshot =
            D029AggressiveIntegrationRuntime.GetSnapshot();
        if (_d029AggressiveIntegrationLogInitialized
            && enabled
                == _lastLoggedD029AggressiveIntegrationEnabled
            && snapshot.Source.Status
                == _lastLoggedD029AggressiveIntegrationStatus
            && snapshot.Source.RecordCount
                == _lastLoggedD029AggressiveIntegrationRecords)
        {
            return;
        }
        _d029AggressiveIntegrationLogInitialized = true;
        _lastLoggedD029AggressiveIntegrationEnabled = enabled;
        _lastLoggedD029AggressiveIntegrationStatus =
            snapshot.Source.Status;
        _lastLoggedD029AggressiveIntegrationRecords =
            snapshot.Source.RecordCount;
        Plugin.PluginLog.LogInfo(
            "D-029 coordinator status="
            + snapshot.Source.Status
            + ", next="
            + (snapshot.CurrentStep?.ToString() ?? "-")
            + ", records="
            + snapshot.Source.RecordCount
            + "/"
            + D029IntegrationCeilings.MaximumSteps
            + ", providerCeiling=3, authorityOutputs=0.");
    }

    internal static D029PluginRuntimeSnapshot
        GetD029AggressiveIntegrationSnapshot()
        => D029AggressiveIntegrationRuntime.GetSnapshot();

    private static bool D029IsAwaiting(D029IntegrationStep step)
    {
        if (!IsD029AggressiveIntegrationOperational())
            return false;
        var snapshot =
            D029AggressiveIntegrationRuntime.GetSnapshot();
        return snapshot.Source.Status is D029SourceHostStatus.Armed
                or D029SourceHostStatus.Running
            && snapshot.CurrentStep == step;
    }

    private static void UpdateD022BaselineAssistObserveRuntime()
    {
        var enabled = Plugin.D022BaselineAssistObserveEnabled.Value;
        try
        {
            var occurredAt = enabled
                ? DateTimeOffset.UtcNow
                : DateTimeOffset.UnixEpoch;
            var runtimeInstanceId = enabled
                ? "character-runtime-" + Environment.ProcessId
                : string.Empty;
            var sessionId = enabled
                ? "local-session-" + Environment.ProcessId
                : string.Empty;
            D022BaselineAssistObserveRuntime.Reconcile(
                enabled,
                sourceEnabled:
                    Plugin.MotionDirectorEnabled.Value
                    && ResolveMotionDirectorMode()
                        != MotionDirectorMode.Off,
                runtimeInstanceId,
                D022RuntimeGeneration,
                sessionId,
                enabled ? D022RuntimeEpochId : string.Empty,
                occurredAt);
            LogD022BaselineAssistObserveStateIfChanged(enabled);
        }
        catch (Exception exception)
        {
            StopD022BaselineAssistObserveAfterFault(exception);
        }
    }

    private static void ObserveD022BaselineAssistOpportunity(
        MotionDirectorProposal proposal,
        D022SliceBGateResult ownership)
    {
        if (!Plugin.D022BaselineAssistObserveEnabled.Value)
            return;
        if (!D022SliceBGateResult.IsAllowlistedOccurrence(proposal))
            return;
        try
        {
            D022BaselineAssistObserveRuntime.Observe(
                proposal,
                ownership,
                DateTimeOffset.UtcNow);
        }
        catch (Exception exception)
        {
            StopD022BaselineAssistObserveAfterFault(exception);
        }
    }

    private static void StopD022BaselineAssistObserveAfterFault(
        Exception exception)
    {
        try
        {
            D022BaselineAssistObserveRuntime.StopByFault(
                DateTimeOffset.UtcNow);
        }
        catch
        {
        }
        Plugin.PluginLog.LogWarning(
            "D-022 Baseline-only Assist Observe stopped fail-closed after "
            + exception.GetType().Name
            + "; ticketIssues=0, ticketConsumptions=0, queueWrites=0, "
            + "motion=0, execution=0, authority=0.");
    }

    private static void LogD022BaselineAssistObserveStateIfChanged(
        bool enabled)
    {
        var snapshot =
            D022BaselineAssistObserveRuntime.GetSnapshot();
        if (_d022ObserveLogInitialized
            && enabled == _lastLoggedD022ObserveEnabled
            && snapshot.Status == _lastLoggedD022ObserveStatus)
        {
            return;
        }

        _d022ObserveLogInitialized = true;
        _lastLoggedD022ObserveEnabled = enabled;
        _lastLoggedD022ObserveStatus = snapshot.Status;
        Plugin.PluginLog.LogInfo(
            $"D-022 Observe status={snapshot.Status}, "
            + $"source={snapshot.SourceEnabled}, "
            + $"generation={snapshot.ConfigurationGeneration}; "
            + "readOnly=true, ticketIssues=0, ticketConsumptions=0, "
            + "queueWrites=0, motion=0, execution=0, authority=0, "
            + "memoryCalls=0, evidenceCalls=0, reasoningCalls=0, "
            + "providerCalls=0.");
    }

    internal static D022SliceDObserveSnapshot
        GetD022BaselineAssistObserveSnapshot()
        => D022BaselineAssistObserveRuntime.GetSnapshot();

    private static void UpdateD022BaselineAssistLiveRuntime()
    {
        var enabled = Plugin.Effective(
            Plugin.D022BaselineAssistEnabled.Value);
        var sourceEnabled = Plugin.Effective(
                Plugin.MotionDirectorEnabled.Value)
            && ResolveMotionDirectorMode()
                == MotionDirectorMode.LocalRules;
        var fingerprint =
            enabled + "|" + sourceEnabled + "|session:open|epoch:active";
        if (!string.Equals(
                fingerprint,
                _d022AssistConfigurationFingerprint,
                StringComparison.Ordinal))
        {
            if (_d022AssistConfigurationFingerprint.Length > 0)
                _d022AssistConfigurationGeneration++;
            _d022AssistConfigurationFingerprint = fingerprint;
        }

        try
        {
            var previous = D022BaselineAssistLiveRuntime.GetSnapshot();
            if (D022BaselineAssistLiveRuntime.HasActiveExpectation
                && (!enabled || !sourceEnabled))
            {
                CancelD022AssistWork(
                    MotionIntentReason.ExecutionFailed,
                    enabled
                        ? "The Motion Director source was disabled."
                        : "D-022 Assist was switched Off.");
            }

            var runtime = new CharacterRuntimeIdentity(
                "profile-current",
                "character-runtime-" + Environment.ProcessId,
                D022RuntimeGeneration,
                "local-session-" + Environment.ProcessId,
                "owner-local");
            D022BaselineAssistLiveRuntime.Reconcile(
                new D022SliceEConfiguration(
                    enabled,
                    sourceEnabled,
                    sessionOpen: true,
                    epochActive: true,
                    _d022AssistConfigurationGeneration,
                    runtime,
                    D022RuntimeEpochId,
                    continuousIntegration:
                        Plugin.FormalIntegrationActive));

            if (enabled && !Plugin.FormalIntegrationActive)
                HandleD022BaselineAssistArmShortcut();
            else
                _d022AssistArmKeyWasDown = false;
            CancelD022AssistForLiveSafetyGates();
            LogD022BaselineAssistLiveStateIfChanged(
                previous,
                enabled);
        }
        catch (Exception exception)
        {
            CancelD022AssistWork(
                MotionIntentReason.ExecutionFailed,
                "D-022 Assist runtime faulted.");
            D022BaselineAssistLiveRuntime.StopByFault();
            Plugin.PluginLog.LogWarning(
                "D-022 supervised Assist stopped fail-closed after "
                + exception.GetType().Name
                + "; no Legacy fallback was attempted for owned work.");
        }
    }

    private static void HandleD022BaselineAssistArmShortcut()
    {
        var key = Plugin.D022BaselineAssistArmKey.Value;
        var controlDown =
            IsKeyCurrentlyDown(KeyCode.LeftControl)
            || IsKeyCurrentlyDown(KeyCode.RightControl);
        var down = key != KeyCode.None
            && controlDown
            && IsKeyCurrentlyDown(key);
        if (!down)
        {
            _d022AssistArmKeyWasDown = false;
            return;
        }
        if (_d022AssistArmKeyWasDown)
            return;
        _d022AssistArmKeyWasDown = true;

        var result = D022BaselineAssistLiveRuntime.Arm();
        Plugin.PluginLog.LogInfo(
            $"D-022 supervised Assist Arm result={result}; "
            + "maximumCandidatesThisProcess=1, "
            + "binding=lilith-greet-one-shot.v1.");
    }

    private static void CancelD022AssistForLiveSafetyGates()
    {
        if (!D022BaselineAssistLiveRuntime.HasActiveExpectation)
            return;

        var character =
            UnityEngine.Object.FindObjectOfType<
                global::CharacterController>();
        var state =
            UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (character == null || state == null)
        {
            CancelD022AssistWork(
                MotionIntentReason.CharacterUnavailable,
                "Lilith's active runtime became unavailable.");
            return;
        }
        if (state.IsDrag)
        {
            CancelD022AssistWork(
                MotionIntentReason.PlayerInterrupted,
                "The player took direct control.");
            return;
        }
        if (_requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _aiPagesAwaitingAdvance)
        {
            CancelD022AssistWork(
                MotionIntentReason.ConversationBusy,
                "Conversation or voice activity took priority.");
            return;
        }
        if (_actionShowcasePendingOperation
                != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcaseWindowWalkContinuationActive)
        {
            CancelD022AssistWork(
                MotionIntentReason.TransitionPending,
                "A higher-priority character transition began.");
        }
    }

    private static void LogD022BaselineAssistLiveStateIfChanged(
        D022SliceEAssistSnapshot previous,
        bool enabled)
    {
        var snapshot = D022BaselineAssistLiveRuntime.GetSnapshot();
        if (_d022AssistLogInitialized
            && enabled == _lastLoggedD022AssistEnabled
            && snapshot.Status == _lastLoggedD022AssistStatus
            && previous.CandidateCount == snapshot.CandidateCount
            && previous.CompletedCount == snapshot.CompletedCount
            && previous.PlayerInterruptedCount
                == snapshot.PlayerInterruptedCount
            && previous.FailedCount == snapshot.FailedCount)
        {
            return;
        }

        _d022AssistLogInitialized = true;
        _lastLoggedD022AssistEnabled = enabled;
        _lastLoggedD022AssistStatus = snapshot.Status;
        Plugin.PluginLog.LogInfo(
            $"D-022 supervised Assist status={snapshot.Status}, "
            + $"enabled={snapshot.AssistEnabled}, "
            + $"source={snapshot.SourceEnabled}, "
            + $"armed={snapshot.Armed}, "
            + $"candidate={snapshot.CandidateCount}/1, "
            + $"queue={snapshot.QueueSubmissionCount}, "
            + $"started={snapshot.StartedCount}, "
            + $"completed={snapshot.CompletedCount}, "
            + $"interrupted={snapshot.PlayerInterruptedCount}, "
            + $"failed={snapshot.FailedCount}; "
            + "memoryCalls=0, evidenceCalls=0, reasoningCalls=0, "
            + "providerCalls=0.");
    }

    internal static D022SliceEAssistSnapshot
        GetD022BaselineAssistLiveSnapshot()
        => D022BaselineAssistLiveRuntime.GetSnapshot();

    private static OrchestratorObserveStatusLanguage
        GetOrchestratorObserveStatusLanguage()
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            if (language.StartsWith(
                    "ja",
                    StringComparison.OrdinalIgnoreCase))
            {
                return OrchestratorObserveStatusLanguage.Japanese;
            }
            if (language.StartsWith(
                    "zh-CN",
                    StringComparison.OrdinalIgnoreCase)
                || language.StartsWith(
                    "zh-Hans",
                    StringComparison.OrdinalIgnoreCase))
            {
                return OrchestratorObserveStatusLanguage.SimplifiedChinese;
            }
            if (language.StartsWith(
                    "zh",
                    StringComparison.OrdinalIgnoreCase))
            {
                return OrchestratorObserveStatusLanguage.TraditionalChinese;
            }
        }
        catch
        {
        }
        return OrchestratorObserveStatusLanguage.English;
    }

    private static void UpdateRuntimeStatusPanel()
    {
        var isolatedD029ProfileActive =
            _d029IsolatedTestProfile != null;
        if (!D029DiagnosticSurfacePolicy.MayUseUnityStatusSurface(
                isolatedD029ProfileActive))
        {
            // The disposable D-029 Profile is supervised through bounded
            // metadata logs.  It must not retain or refresh a diagnostic
            // Unity object wrapper during the extended coexistence soak.
            // This guard intentionally runs before any access to the
            // existing shared status GameObject or TMP component.
            if (!_d029IsolatedUnityStatusSurfaceSuppressionLogged)
            {
                _d029IsolatedUnityStatusSurfaceSuppressionLogged = true;
                Plugin.PluginLog.LogInfo(
                    "D-029 isolated Profile uses metadata-log diagnostics; "
                    + "the in-game Unity status surface is suppressed for "
                    + "this process.");
            }
            return;
        }
        _d029IsolatedUnityStatusSurfaceSuppressionLogged = false;

        var d029OwnsDiagnosticSurface =
            D029DiagnosticSurfacePolicy.CoordinatorOwnsSurface(
                Plugin.D029AggressiveIntegrationStatusVisible.Value);
        var mayRenderSubordinateStatus =
            D029DiagnosticSurfacePolicy.MayRenderSubordinateStatus(
                Plugin.D029AggressiveIntegrationStatusVisible.Value);
        var visible = Plugin.D022BaselineAssistStatusVisible.Value
            || Plugin.ProviderRuntimeRegistryObserveStatusVisible.Value
            || Plugin.ProviderRuntimeGeminiMigrationStatusVisible.Value
            || Plugin.ProviderRuntimeDeepSeekMigrationStatusVisible.Value
            || Plugin.D029AggressiveIntegrationStatusVisible.Value;
        if (!visible)
        {
            if (_runtimeStatusWindow != null)
                _runtimeStatusWindow.SetActive(false);
            if (_runtimeStatusBody != null)
                _runtimeStatusBody.text = string.Empty;
            _runtimeStatusNextRefreshAt = -1f;
            _runtimeStatusNextCreateAttemptAt = -1f;
            return;
        }

        try
        {
            var now = Time.unscaledTime;
            if (_runtimeStatusWindow == null)
            {
                if (now < _runtimeStatusNextCreateAttemptAt)
                    return;
                _runtimeStatusNextCreateAttemptAt = now + 2f;
                if (!TryCreateRuntimeStatusPanel())
                    return;
            }

            if (!_runtimeStatusWindow!.activeSelf)
                _runtimeStatusWindow.SetActive(true);
            if (_runtimeStatusBody == null
                || now < _runtimeStatusNextRefreshAt)
            {
                return;
            }

            _runtimeStatusNextRefreshAt = now + 0.25f;
            var body = string.Empty;
            if (mayRenderSubordinateStatus
                && Plugin.D022BaselineAssistStatusVisible.Value)
            {
                var d022ObserveBody =
                    D022SliceDObserveStatusFormatter.Format(
                        D022BaselineAssistObserveRuntime.GetSnapshot(),
                        GetD022ObserveStatusLanguage());
                var d022AssistBody =
                    D022SliceELiveStatusFormatter.Format(
                        D022BaselineAssistLiveRuntime.GetSnapshot(),
                        GetD022ObserveStatusLanguage());
                var d022Body = d022ObserveBody
                    + "\n\n"
                    + d022AssistBody;
                body = string.IsNullOrEmpty(body)
                    ? d022Body
                    : body + "\n\n" + d022Body;
            }
            if (mayRenderSubordinateStatus
                && Plugin.ProviderRuntimeRegistryObserveStatusVisible.Value)
            {
                var providerRuntimeBody =
                    D031ProviderRuntimeStageEStatusFormatter.Format(
                        D031ProviderRuntimeObserve.GetSnapshot(),
                        GetOrchestratorObserveStatusLanguage());
                body = string.IsNullOrEmpty(body)
                    ? providerRuntimeBody
                    : body + "\n\n" + providerRuntimeBody;
            }
            if (mayRenderSubordinateStatus
                && Plugin.ProviderRuntimeGeminiMigrationStatusVisible.Value)
            {
                var providerMigrationBody =
                    D031ProviderRuntimeStageFGeminiStatusFormatter.Format(
                        D031ProviderRuntimeGeminiMigration.GetSnapshot(),
                        GetOrchestratorObserveStatusLanguage());
                body = string.IsNullOrEmpty(body)
                    ? providerMigrationBody
                    : body + "\n\n" + providerMigrationBody;
            }
            if (mayRenderSubordinateStatus
                && Plugin.ProviderRuntimeDeepSeekMigrationStatusVisible.Value)
            {
                var providerMigrationBody =
                    D031ProviderRuntimeStageFGeminiStatusFormatter.Format(
                        D031ProviderRuntimeDeepSeekMigration.GetSnapshot(),
                        GetOrchestratorObserveStatusLanguage(),
                        "DeepSeek");
                body = string.IsNullOrEmpty(body)
                    ? providerMigrationBody
                    : body + "\n\n" + providerMigrationBody;
            }
            if (d029OwnsDiagnosticSurface)
            {
                var d029Body =
                    D029AggressiveIntegrationStatusFormatter.Format(
                        D029AggressiveIntegrationRuntime.GetSnapshot());
                body = string.IsNullOrEmpty(body)
                    ? d029Body
                    : body + "\n\n" + d029Body;
            }
            _runtimeStatusBody.text = body;
        }
        catch (Exception exception)
        {
            if (_runtimeStatusWindow != null)
                _runtimeStatusWindow.SetActive(false);
            Plugin.PluginLog.LogWarning(
                "Runtime status panel failed closed after a "
                + exception.GetType().Name
                + " fault. Runtime behavior remains "
                + "unchanged.");
        }
    }

    private static bool TryCreateRuntimeStatusPanel()
    {
        try
        {
            var sourceUi =
                UnityEngine.Object.FindObjectOfType<DialogueBubbleUI>();
            var sourceText =
                sourceUi?.gameObject.GetComponentInChildren<TextMeshProUGUI>();
            if (sourceUi == null || sourceText == null)
                return false;

            _runtimeStatusWindow = new GameObject(
                "LilithRuntimeStatus",
                Il2CppType.Of<RectTransform>(),
                Il2CppType.Of<Canvas>(),
                Il2CppType.Of<CanvasScaler>(),
                Il2CppType.Of<CanvasGroup>());
            _runtimeStatusWindow.transform.SetParent(null, false);

            var canvas =
                _runtimeStatusWindow.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.overrideSorting = true;
            canvas.sortingOrder = 31989;
            canvas.pixelPerfect = false;

            var scaler =
                _runtimeStatusWindow.GetComponent<CanvasScaler>();
            scaler.uiScaleMode =
                CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode =
                CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            var root =
                _runtimeStatusWindow.GetComponent<RectTransform>();
            root.anchorMin = Vector2.zero;
            root.anchorMax = Vector2.one;
            root.pivot = new Vector2(0.5f, 0.5f);
            root.anchoredPosition = Vector2.zero;
            root.sizeDelta = Vector2.zero;
            root.offsetMin = Vector2.zero;
            root.offsetMax = Vector2.zero;

            var panelObject = new GameObject(
                "ReadOnlyRuntimePanel",
                Il2CppType.Of<RectTransform>(),
                Il2CppType.Of<CanvasRenderer>(),
                Il2CppType.Of<Image>());
            panelObject.transform.SetParent(
                _runtimeStatusWindow.transform,
                false);
            var panel = panelObject.GetComponent<RectTransform>();
            panel.anchorMin = new Vector2(0.70f, 0.25f);
            panel.anchorMax = new Vector2(0.985f, 0.955f);
            panel.offsetMin = Vector2.zero;
            panel.offsetMax = Vector2.zero;
            var background = panelObject.GetComponent<Image>();
            background.color =
                new Color(0.025f, 0.026f, 0.042f, 0.88f);
            background.raycastTarget = false;
            var panelSprite = FindSprite("Choise_Bubble");
            if (panelSprite != null)
            {
                background.sprite = panelSprite;
                background.type = Image.Type.Sliced;
            }

            _runtimeStatusBody =
                CreateConversationHistoryText(
                    sourceText,
                    panelObject.transform,
                    "ReadOnlyRuntimeStatusText",
                    new Vector2(0.045f, 0.055f),
                    new Vector2(0.955f, 0.945f),
                    14f,
                    TextAlignmentOptions.TopLeft)
                as TextMeshProUGUI;
            if (_runtimeStatusBody == null)
            {
                throw new InvalidOperationException(
                    "Could not create the runtime status text.");
            }
            _runtimeStatusBody.richText = true;
            _runtimeStatusBody.enableWordWrapping = true;
            _runtimeStatusBody.overflowMode =
                TextOverflowModes.Ellipsis;
            _runtimeStatusBody.raycastTarget = false;

            var canvasGroup =
                _runtimeStatusWindow.GetComponent<CanvasGroup>();
            canvasGroup.alpha = 1f;
            canvasGroup.interactable = false;
            canvasGroup.blocksRaycasts = false;
            _runtimeStatusNextRefreshAt = -1f;
            Plugin.PluginLog.LogInfo(
                "Created non-interactive runtime status panel; "
                + "the panel receives no player or model content.");
            return true;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Could not create runtime status panel: "
                + exception.GetType().Name);
            if (_runtimeStatusWindow != null)
            {
                UnityEngine.Object.Destroy(
                    _runtimeStatusWindow);
            }
            _runtimeStatusWindow = null;
            _runtimeStatusBody = null;
            return false;
        }
    }

    private static RuntimeStatusLanguage
        GetRuntimeStatusLanguage()
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            if (language.StartsWith(
                    "ja",
                    StringComparison.OrdinalIgnoreCase))
            {
                return RuntimeStatusLanguage.Japanese;
            }
            if (language.StartsWith(
                    "zh-CN",
                    StringComparison.OrdinalIgnoreCase)
                || language.StartsWith(
                    "zh-Hans",
                    StringComparison.OrdinalIgnoreCase))
            {
                return RuntimeStatusLanguage.SimplifiedChinese;
            }
            if (language.StartsWith(
                    "zh",
                    StringComparison.OrdinalIgnoreCase))
            {
                return RuntimeStatusLanguage.TraditionalChinese;
            }
        }
        catch
        {
        }
        return RuntimeStatusLanguage.English;
    }

    private static D022SliceDStatusLanguage
        GetD022ObserveStatusLanguage()
        => GetRuntimeStatusLanguage() switch
        {
            RuntimeStatusLanguage.TraditionalChinese =>
                D022SliceDStatusLanguage.TraditionalChinese,
            RuntimeStatusLanguage.SimplifiedChinese =>
                D022SliceDStatusLanguage.SimplifiedChinese,
            RuntimeStatusLanguage.Japanese =>
                D022SliceDStatusLanguage.Japanese,
            _ => D022SliceDStatusLanguage.English
        };

    private static PlayerTurnInputSource PlayerTurnSource(
        PlayerTurnInputSurface inputSurface)
        => inputSurface switch
        {
            PlayerTurnInputSurface.TextEntry =>
                PlayerTurnInputSource.TextEntry,
            PlayerTurnInputSurface.PushToTalkTranscript =>
                PlayerTurnInputSource.PushToTalkTranscript,
            _ => throw new ArgumentOutOfRangeException(nameof(inputSurface))
        };

    private static bool TryAcquireAgentLanguageOutput(
        DialogueManager manager,
        AgentLanguageSourceKind sourceKind,
        string sourceCorrelationId,
        out AgentLanguagePublicationLease? lease,
        out AgentLanguageProposalOutcome? proposalOutcome,
        bool logRejection = true)
    {
        lease = null;
        proposalOutcome = null;
        try
        {
            var runtimeGeneration = CurrentPlayerTurnRuntimeGeneration();
            var proposal = AgentLanguageRuntime.CreateLanguageProposal(
                sourceKind,
                runtimeGeneration,
                sourceCorrelationId);
            var playerTurnActive =
                PlayerTurnOperations.GetSnapshot().Active != null
                || _requestInFlight;
            var playerInputPending =
                (_inputBubble != null && _inputBubble.activeSelf)
                || _pendingVoiceSubmitText != null
                || !PendingTranscripts.IsEmpty
                || _microphoneRecording
                || _transcriptionInFlight;
            var arbitration = AgentLanguageRuntime.ArbitrateLanguage(
                new[] { proposal },
                runtimeGeneration,
                playerTurnActive,
                playerInputPending,
                manager.IsBusy);
            proposalOutcome = arbitration.Find(proposal);
            var claimRuntimeGeneration =
                CurrentPlayerTurnRuntimeGeneration();
            if (proposalOutcome?.Disposition
                    != AgentLanguageArbitrationDisposition.Selected
                || !AgentLanguageRuntime.TryClaimLanguagePublication(
                    arbitration,
                    proposal,
                    claimRuntimeGeneration,
                    out lease)
                || lease == null)
            {
                if (logRejection)
                {
                    Plugin.PluginLog.LogInfo(
                        "Agent language output was not selected: source="
                        + sourceKind
                        + ", disposition="
                        + (proposalOutcome?.Disposition.ToString()
                            ?? "Rejected")
                        + ", reason="
                        + (proposalOutcome?.Reason.ToString()
                            ?? "HostFaulted")
                        + ", noFallback=true.");
                }
                return false;
            }
            return true;
        }
        catch (Exception exception)
        {
            if (logRejection)
            {
                Plugin.PluginLog.LogWarning(
                    "Agent language arbitration failed closed: source="
                    + sourceKind
                    + ", fault="
                    + exception.GetType().Name
                    + ", noFallback=true.");
            }
            lease = null;
            proposalOutcome = null;
            return false;
        }
    }

    private static bool TryRecordAgentLanguagePublication(
        AgentLanguagePublicationLease lease,
        bool published)
    {
        try
        {
            var recorded = AgentLanguageRuntime
                .TryCompleteLanguagePublication(lease, published);
            if (!recorded)
            {
                Plugin.PluginLog.LogWarning(
                    "Agent language publication receipt was rejected: source="
                    + lease.Proposal.SourceKind
                    + ", published="
                    + (published ? "1" : "0")
                    + ".");
            }
            return recorded;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Agent language publication receipt failed closed: source="
                + lease.Proposal.SourceKind
                + ", fault="
                + exception.GetType().Name
                + ".");
            return false;
        }
    }

    private static long CurrentPlayerTurnRuntimeGeneration()
        => Math.Max(1, CurrentCharacterRuntimeIdentity().Generation);

    private static bool TryRetireRuntimeChangedPlayerTurn(
        PlayerTurnOperationHandle operation,
        PlayerTurnPublicationAdmission publicationAdmission,
        long currentRuntimeGeneration)
    {
        if (publicationAdmission
                != PlayerTurnPublicationAdmission.RuntimeGenerationChanged
            || !PlayerTurnOperations.TryCancelForRuntimeGenerationChange(
                operation,
                currentRuntimeGeneration))
        {
            return false;
        }
        HermesNoteCandidates.Retire(operation);
        return true;
    }

    private static void EnqueuePlayerTurnReply(
        PlayerTurnOperationHandle operation,
        string text,
        string emotion,
        PlayerTurnPublicationKind publicationKind,
        PlayerTurnTerminalDisposition terminalDisposition,
        PlayerTurnFailureReason failureReason = PlayerTurnFailureReason.None,
        PlayerTurnCancellationReason cancellationReason =
            PlayerTurnCancellationReason.None,
        string publishedAssistantMemoryText = "",
        string publishedPlayerReplySpeechText = "",
        VoiceStyle publishedPlayerReplyVoiceStyle = VoiceStyle.Calm,
        LilithGameBridgeSpeechLocale?
            publishedPlayerReplySpeechLocale = null,
        string publishedPlayerReplySpeechEmotion = "")
    {
        CaptureWorkbenchTerminalReply(
            operation,
            text,
            terminalDisposition);
        var pages = SplitIntoBubblePages(text);
        if (pages.Length == 0)
            pages = new[] { "……" };
        for (var index = 0; index < pages.Length; index++)
        {
            var terminalPage = index == pages.Length - 1;
            PendingReplies.Enqueue(
                new PendingPlayerTurnReply(
                    operation,
                    pages[index],
                    index == 0 ? emotion : string.Empty,
                    publicationKind,
                    terminalPage
                        ? terminalDisposition
                        : PlayerTurnTerminalDisposition.None,
                    terminalPage
                        ? failureReason
                        : PlayerTurnFailureReason.None,
                    terminalPage
                        ? cancellationReason
                        : PlayerTurnCancellationReason.None,
                    terminalPage,
                    terminalPage
                        ? publishedAssistantMemoryText
                        : string.Empty,
                    index == 0
                        ? publishedPlayerReplySpeechText
                        : string.Empty,
                    publishedPlayerReplyVoiceStyle,
                    index == 0
                        ? publishedPlayerReplySpeechLocale
                        : null,
                    index == 0 ? publishedPlayerReplySpeechEmotion : string.Empty));
        }
    }

    // D058: no legacy memory mirror after a successful Hermes publication.

    private static void ConsiderPublishedHermesNoteEvent(
        PendingPlayerTurnReply reply)
    {
        if (!HermesNoteCandidates.TryTakePublished(
                reply.Operation,
                reply.PublicationKind,
                out var context)
            || context == null
            || !Plugin.AiNotesEnabled.Value)
            return;
        try
        {
            UpdatePendingAiNoteEvents(context.UserText);
            ConsiderAiNoteEvent(context.UserText, context.Reply);
        }
        catch (Exception exception)
        {
            // A note candidate persistence fault cannot fail an already
            // published player reply, and this consumed receipt is not retried.
            Plugin.PluginLog.LogWarning(
                "Hermes note candidate was not saved: "
                + exception.GetType().Name);
        }
    }

    // D058: the uncalled legacy local-clock memory callback is retired.

    private static void EnqueueLocalClockMemoryFailure(
        PlayerTurnOperationHandle operation)
        => EnqueuePlayerTurnReply(
            operation,
            ApiKeyText(
                "這次回覆沒有安全完成，請再試一次。",
                "这次回复没有安全完成，请再试一次。",
                "今回の返答は安全に完了できなかったよ。もう一度試してね。",
                "This reply could not complete safely. Please try again."),
            string.Empty,
            PlayerTurnPublicationKind.FailureNotice,
            PlayerTurnTerminalDisposition.Failed,
            PlayerTurnFailureReason.MemoryOrPromptPreparationRejected);

    private static bool HasPendingPageForOperation(
        PlayerTurnOperationHandle operation)
        => PendingReplies.TryPeek(out var next)
            && next.Operation.Matches(operation);

    private static bool CompletePublishedPlayerTurn(
        PendingPlayerTurnReply reply)
    {
        if (!reply.IsTerminalPage)
            return false;
        var completed = reply.TerminalDisposition switch
        {
            PlayerTurnTerminalDisposition.Completed =>
                PlayerTurnOperations.TryComplete(reply.Operation),
            PlayerTurnTerminalDisposition.Failed =>
                PlayerTurnOperations.TryFail(
                    reply.Operation,
                    reply.FailureReason),
            PlayerTurnTerminalDisposition.Cancelled =>
                PlayerTurnOperations.TryCancel(
                    reply.Operation,
                    reply.CancellationReason),
            _ => false
        };
        if (!completed)
        {
            Plugin.PluginLog.LogWarning(
                "Rejected a stale or duplicate player-turn terminal "
                + "transition after DialogueManager publication.");
            return false;
        }
        if (reply.TerminalDisposition == PlayerTurnTerminalDisposition.Completed)
            ConsiderPublishedHermesNoteEvent(reply);
        else
            HermesNoteCandidates.Retire(reply.Operation);
        ObserveGameChatTest(
            reply.Operation,
            reply.TerminalDisposition == PlayerTurnTerminalDisposition.Completed
                ? GameChatTestEndpointState.Published : GameChatTestEndpointState.Failed,
            reply.TerminalDisposition == PlayerTurnTerminalDisposition.Completed
                ? "dialogue_published" : "failure_notice_published");
        return true;
    }

    private static bool TryFailAndReleasePlayerTurnPublication(
        PlayerTurnOperationHandle operation)
    {
        HermesNoteCandidates.Retire(operation);
        if (!PlayerTurnOperations.TryFail(
                operation,
                PlayerTurnFailureReason.PublicationFailed))
        {
            return false;
        }
        FailWorkbenchTurn(operation, "D045B2.LilithLive.PublicationFailed");
        ObserveGameChatTest(operation, GameChatTestEndpointState.Failed, "dialogue_publication_failed");
        _requestInFlight = false;
        _aiPagesAwaitingAdvance = false;
        _currentAiPageText = string.Empty;
        _currentAiPageOperation = null;
        while (PendingReplies.TryDequeue(out _)) { }
        return true;
    }

    private static void PublishImmediatePlayerTurnFailure(
        DialogueManager manager,
        PlayerTurnOperationHandle operation,
        string text,
        float duration,
        PlayerTurnFailureReason reason)
    {
        var currentRuntimeGeneration =
            CurrentPlayerTurnRuntimeGeneration();
        var publicationAdmission =
            PlayerTurnOperations.EvaluatePublication(
                operation,
                PlayerTurnPublicationKind.FailureNotice,
                currentRuntimeGeneration);
        if (publicationAdmission
            != PlayerTurnPublicationAdmission.Admitted)
        {
            TryRetireRuntimeChangedPlayerTurn(
                operation,
                publicationAdmission,
                currentRuntimeGeneration);
            Plugin.PluginLog.LogWarning(
                "Discarded a stale immediate player-turn failure before "
                + "DialogueManager publication; admission="
                + publicationAdmission
                + ".");
            return;
        }
        AgentLanguagePublicationLease? languageLease = null;
        var agentPublicationFinished = false;
        try
        {
            if (!TryAcquireAgentLanguageOutput(
                    manager,
                    AgentLanguageSourceKind.OrdinaryPlayerTurn,
                    operation.OperationId,
                    out languageLease,
                    out var languageArbitration)
                || languageLease == null)
            {
                TryFailAndReleasePlayerTurnPublication(operation);
                Plugin.PluginLog.LogWarning(
                    "Immediate player-turn failure lost language "
                    + "arbitration before DialogueManager: reason="
                    + (languageArbitration?.Reason.ToString()
                        ?? "HostFaulted")
                    + ".");
                return;
            }
            ForceSaySynthetic(manager, text, string.Empty, duration);
            agentPublicationFinished = TryRecordAgentLanguagePublication(
                languageLease,
                published: true);
            if (!agentPublicationFinished)
            {
                TryFailAndReleasePlayerTurnPublication(operation);
                return;
            }
            var publicationCommitGeneration =
                CurrentPlayerTurnRuntimeGeneration();
            if (!PlayerTurnOperations.TryPublish(
                    operation,
                    PlayerTurnPublicationKind.FailureNotice,
                    publicationCommitGeneration))
            {
                var commitAdmission =
                    PlayerTurnOperations.EvaluatePublication(
                        operation,
                        PlayerTurnPublicationKind.FailureNotice,
                        publicationCommitGeneration);
                if (commitAdmission
                        != PlayerTurnPublicationAdmission.NoActiveOperation
                    && !TryRetireRuntimeChangedPlayerTurn(
                            operation,
                            commitAdmission,
                            publicationCommitGeneration))
                {
                    TryFailAndReleasePlayerTurnPublication(operation);
                }
                Plugin.PluginLog.LogWarning(
                    "Rejected an immediate player-turn failure publication "
                    + "because its operation was stale or terminal.");
                return;
            }
            if (PlayerTurnOperations.TryFail(operation, reason))
            {
                CompleteWorkbenchImmediateFailure(operation, text);
            }
            else
            {
                Plugin.PluginLog.LogWarning(
                    "Rejected an immediate player-turn failure terminal "
                    + "because its operation was stale or terminal.");
            }
        }
        catch
        {
            if (languageLease != null && !agentPublicationFinished)
            {
                TryRecordAgentLanguagePublication(
                    languageLease,
                    published: false);
            }
            TryFailAndReleasePlayerTurnPublication(operation);
            throw;
        }
    }

    private static void FailPlayerTurnBeforeAsyncDispatch(
        DialogueManager manager,
        PlayerTurnOperationHandle operation,
        Exception exception)
    {
        _requestInFlight = false;
        while (PendingReplies.TryDequeue(out _)) { }
        Plugin.PluginLog.LogError(
            "Player-turn preparation failed before async dispatch: "
            + exception);
        try
        {
            PublishImmediatePlayerTurnFailure(
                manager,
                operation,
                ApiKeyText(
                    "這次回覆沒有安全完成，請再試一次。",
                    "这次回复没有安全完成，请再试一次。",
                    "今回の返答は安全に完了できなかったよ。もう一度試してね。",
                    "This reply could not complete safely. Please try again."),
                6f,
                PlayerTurnFailureReason.PreDispatchFaulted);
        }
        catch (Exception publicationException)
        {
            Plugin.PluginLog.LogError(
                "Could not publish the player-turn preparation failure: "
                + publicationException);
        }
    }

    private static void SubmitAiInput(
        DialogueManager manager,
        string submitted,
        PlayerTurnInputSurface inputSurface)
    {
        submitted = submitted.Trim();
        if (submitted.Length == 0)
            return;
        if (_requestInFlight)
        {
            ForceSaySynthetic(
                manager,
                ApiKeyText("先等我說完。", "先等我说完。", "先に話し終えさせて……", "Let me finish speaking first."),
                string.Empty,
                4f);
            return;
        }
        var operationBegin = PlayerTurnOperations.TryBegin(
            PlayerTurnSource(inputSurface),
            Math.Max(1, CurrentCharacterRuntimeIdentity().Generation));
        var operation = operationBegin.Handle;
        if (!operationBegin.Accepted || operation == null)
        {
            ForceSaySynthetic(
                manager,
                ApiKeyText(
                    "先等我說完。",
                    "先等我说完。",
                    "先に話し終えさせて……",
                    "Let me finish speaking first."),
                string.Empty,
                4f);
            return;
        }
        try
        {
            BindGameChatTest(operation);
            RecordForegroundProactivePlayerTurn();
            CancelPublishedPlayerReplySpeech(
                D043SpeechCancellationReason.PublicationRetired);
            SubmitGameHermesTurn(
                manager,
                operation,
                submitted,
                inputSurface);
            return;
        }
        catch (Exception exception)
        {
            FailPlayerTurnBeforeAsyncDispatch(
                manager,
                operation,
                exception);
        }
    }

    private const string GameHermesRouteId = "runtime.game.hermes";
    // game.chat.interrupt requires a non-empty client-turn identity even when
    // F8 is stopping only a Runtime-owned proactive continuation. Reusing one
    // reserved identity prevents repeated out-of-band Stop presses from
    // accumulating unmatched cancellation tombstones. Player turns always use
    // fresh identities and never intentionally use this reserved value.
    private static readonly Guid GameHermesNativeContinuationStopTurnId =
        new("8a0d7e18-954a-4dbe-9e55-a24dc3a8c657");
    private static readonly TimeSpan GameHermesTurnTimeout =
        TimeSpan.FromMinutes(8);

    private static void SubmitGameHermesTurn(
        DialogueManager manager,
        PlayerTurnOperationHandle operation,
        string submitted,
        PlayerTurnInputSurface inputSurface)
    {
        if (!PlayerTurnOperations.TryAdmit(operation, GameHermesRouteId))
        {
            PublishImmediatePlayerTurnFailure(
                manager,
                operation,
                GameHermesUnavailableText(),
                6f,
                PlayerTurnFailureReason.RouteNotAdmitted);
            return;
        }

        var requestId = Guid.NewGuid();
        var turnId = Guid.NewGuid();
        try
        {
            if (!PlayerTurnOperations.TryProviderStarted(
                    operation,
                    GameHermesRouteId,
                    requestId.ToString("N")))
            {
                PublishImmediatePlayerTurnFailure(
                    manager,
                    operation,
                    GameHermesUnavailableText(),
                    6f,
                    PlayerTurnFailureReason.RouteNotAdmitted);
                return;
            }

            _requestInFlight = true;
            ForceSaySynthetic(manager, "……", string.Empty, 30f);
            var voiceStyle = CapturePoseContext().VoiceStyle;
            var displayLocale = ToGameHermesDisplayLocale(
                LilithGamePersonaLocaleProjector.Resolve(
                    GetAgentTurnLocale()).DisplayLocale);
            var speechLocale = IsJapaneseVoiceMode()
                ? LilithGameBridgeSpeechLocale.Japanese
                : LilithGameBridgeSpeechLocale.Chinese;
            Plugin.PluginLog.LogInfo(
                "Submitted one bounded game Hermes turn: surface="
                + inputSurface
                + ", request="
                + requestId.ToString("N")[..8]
                + ".");
            UpdateOfficialPlayerNameOnMainThread(force: true);
            RefreshMiniGameAnswerRepairLifetime();
            var miniGameContext = MiniGameConversationEvents.Shared.Reserve(
                CaptureMiniGamePublicContext(operation), turnId);
            // The snapshot is turn-local companion context, not an answer
            // checklist or a reason to bind an auxiliary repair lifetime.
            _ = RunGameHermesTurnAsync(
                operation,
                requestId,
                turnId,
                inputSurface,
                submitted,
                voiceStyle,
                displayLocale,
                speechLocale,
                miniGameContext,
                CreateGameChatTestDiagnostic(operation),
                miniGameAnswerRepair: null);
        }
        catch
        {
            MiniGameConversationEvents.Shared.Release(turnId);
            _requestInFlight = false;
            _ = PlayerTurnOperations.IsActive(operation)
                && PlayerTurnOperations.TryFail(
                    operation,
                    PlayerTurnFailureReason.PreDispatchFaulted);
            throw;
        }
    }

    private static async Task RunGameHermesTurnAsync(
        PlayerTurnOperationHandle operation,
        Guid requestId,
        Guid turnId,
        PlayerTurnInputSurface inputSurface,
        string submitted,
        VoiceStyle voiceStyle,
        LilithGameBridgeDisplayLocale displayLocale,
        LilithGameBridgeSpeechLocale speechLocale,
        LilithMiniGamePublicContext? miniGameContext,
        LilithMiniGameDiagnosticRequest? miniGameDiagnostic,
        LilithMiniGameAnswerRepair? miniGameAnswerRepair)
    {
        try
        {
            await RunGameHermesTurnCoreAsync(operation, requestId, turnId, inputSurface,
                submitted, voiceStyle, displayLocale, speechLocale, miniGameContext,
                miniGameDiagnostic, miniGameAnswerRepair).ConfigureAwait(false);
        }
        finally
        {
            // Includes failure before the inner transport try (CTS/owner setup).
            MiniGameConversationEvents.Shared.Release(turnId);
        }
    }

    private static async Task RunGameHermesTurnCoreAsync(
        PlayerTurnOperationHandle operation,
        Guid requestId,
        Guid turnId,
        PlayerTurnInputSurface inputSurface,
        string submitted,
        VoiceStyle voiceStyle,
        LilithGameBridgeDisplayLocale displayLocale,
        LilithGameBridgeSpeechLocale speechLocale,
        LilithMiniGamePublicContext? miniGameContext,
        LilithMiniGameDiagnosticRequest? miniGameDiagnostic,
        LilithMiniGameAnswerRepair? miniGameAnswerRepair)
    {
        var operationCancellation =
            PlayerTurnOperations.GetCancellationToken(operation);
        using var timeout = new CancellationTokenSource(
            GameHermesTurnTimeout);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(
            operationCancellation,
            timeout.Token);
        var noteInboxOwner = RegisterNoteInboxToolOwner(turnId, operation, linked.Token);
        try
        {
            using (var nameWait = CancellationTokenSource.CreateLinkedTokenSource(linked.Token))
            {
                nameWait.CancelAfter(TimeSpan.FromSeconds(2));
                try
                {
                    await PlayerNameSync.SynchronizeLatestForPlayerTurnAsync(nameWait.Token)
                        .ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (!linked.IsCancellationRequested)
                {
                    // A name synchronization timeout does not consume the chat.
                }
            }
            var response = await GameHermesClient.SubmitAsync(
                    requestId,
                    turnId,
                    ToGameHermesSurface(inputSurface),
                    submitted,
                    displayLocale,
                    speechLocale,
                    linked.Token,
                    miniGameContext,
                    miniGameDiagnostic,
                    miniGameAnswerRepair)
                .ConfigureAwait(false);
            ObserveGameChatTestDiagnostic(operation, response.MiniGameDiagnostic);
            if (!TryCompleteGameHermesProvider(operation, requestId))
            {
                EnqueueGameHermesTerminalSentinel(operation);
                return;
            }

            if (response.Succeeded)
            {
                if (response.MiniGameEventReceipt is { } receipt)
                    MiniGameConversationEvents.Shared.Acknowledge(turnId, receipt);
                ObserveGameChatTest(operation, GameChatTestEndpointState.ProviderCompleted,
                    "provider_completed", response.AssistantText);
                // Stage only bounded event evidence. The last page's successful
                // publication receipt is the sole candidate persistence entry.
                if (Plugin.AiNotesEnabled.Value
                    && !ContainsSensitiveNoteData(submitted)
                    && !ContainsSensitiveNoteData(response.AssistantText))
                {
                    HermesNoteCandidates.Stage(
                        operation,
                        CompactNoteContext(submitted, 360),
                        CompactNoteContext(response.AssistantText, 360));
                }
                EnqueuePlayerTurnReply(
                    operation,
                    response.AssistantText,
                    string.Empty,
                    PlayerTurnPublicationKind.AssistantReply,
                    PlayerTurnTerminalDisposition.Completed,
                    publishedPlayerReplySpeechText:
                        response.SpeechText,
                    publishedPlayerReplyVoiceStyle: voiceStyle,
                    publishedPlayerReplySpeechLocale: speechLocale,
                    publishedPlayerReplySpeechEmotion: response.SpeechEmotion);
                return;
            }

            var interrupted = response.Terminal
                == LilithGameBridgeTerminal.Interrupted;
            ObserveGameChatTest(operation, GameChatTestEndpointState.Failed, response.Code);
            EnqueuePlayerTurnReply(
                operation,
                GameHermesFailureText(response.Terminal),
                string.Empty,
                PlayerTurnPublicationKind.FailureNotice,
                interrupted
                    ? PlayerTurnTerminalDisposition.Cancelled
                    : PlayerTurnTerminalDisposition.Failed,
                failureReason: interrupted
                    ? PlayerTurnFailureReason.None
                    : PlayerTurnFailureReason.ProviderFaulted,
                cancellationReason: interrupted
                    ? PlayerTurnCancellationReason.Superseded
                    : PlayerTurnCancellationReason.None);
            Plugin.PluginLog.LogWarning(
                "Game Hermes turn returned a terminal failure: terminal="
                + response.Terminal
                + ", committed="
                + (response.UserCommitted ? "1" : "0")
                + ", code="
                + response.Code
                + ".");
        }
        catch (OperationCanceledException)
            when (linked.IsCancellationRequested)
        {
            ObserveGameChatTest(operation, GameChatTestEndpointState.StopRequested,
                "transport_cancelled_reconciliation_pending");
            var interrupt = TryInterruptGameHermesTurnAsync(turnId);
            var expired = timeout.IsCancellationRequested
                && !operationCancellation.IsCancellationRequested;
            if (!TryCompleteGameHermesProvider(operation, requestId))
            {
                EnqueueGameHermesTerminalSentinel(operation);
                await interrupt.ConfigureAwait(false);
                return;
            }
            EnqueuePlayerTurnReply(
                operation,
                GameHermesFailureText(LilithGameBridgeTerminal.Interrupted),
                string.Empty,
                PlayerTurnPublicationKind.FailureNotice,
                PlayerTurnTerminalDisposition.Cancelled,
                cancellationReason: expired
                    ? PlayerTurnCancellationReason.Expired
                    : PlayerTurnCancellationReason.Superseded);
            await interrupt.ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            if (!TryCompleteGameHermesProvider(operation, requestId))
            {
                EnqueueGameHermesTerminalSentinel(operation);
                return;
            }
            ObserveGameChatTest(operation, GameChatTestEndpointState.Failed, "game_transport_failed");
            EnqueuePlayerTurnReply(
                operation,
                GameHermesUnavailableText(),
                string.Empty,
                PlayerTurnPublicationKind.FailureNotice,
                PlayerTurnTerminalDisposition.Failed,
                exception is InvalidDataException
                    ? PlayerTurnFailureReason.ProviderResponseRejected
                    : PlayerTurnFailureReason.ProviderFaulted);
            Plugin.PluginLog.LogWarning(
                "Game Hermes turn failed without retaining its content: "
                + exception.GetType().Name
                + ".");
        }
        finally
        {
            RetireNoteInboxToolOwner(noteInboxOwner);
        }
    }

    private static bool TryCompleteGameHermesProvider(
        PlayerTurnOperationHandle operation,
        Guid requestId)
    {
        if (PlayerTurnOperations.TryProviderCompleted(
                operation,
                requestId.ToString("N")))
        {
            return true;
        }
        _ = PlayerTurnOperations.IsActive(operation)
            && PlayerTurnOperations.TryFail(
                operation,
                PlayerTurnFailureReason.ProviderResponseRejected);
        return false;
    }

    private static void EnqueueGameHermesTerminalSentinel(
        PlayerTurnOperationHandle operation)
        => EnqueuePlayerTurnReply(
            operation,
            GameHermesUnavailableText(),
            string.Empty,
            PlayerTurnPublicationKind.FailureNotice,
            PlayerTurnTerminalDisposition.Failed,
            PlayerTurnFailureReason.ProviderResponseRejected);

    private static async Task TryInterruptGameHermesTurnAsync(Guid turnId)
    {
        using var timeout = new CancellationTokenSource(
            TimeSpan.FromSeconds(3));
        try
        {
            await GameHermesClient.InterruptAsync(
                    Guid.NewGuid(),
                    turnId,
                    timeout.Token)
                .ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogInfo(
                "Game Hermes interrupt reconciliation ended without a "
                + "receipt: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static LilithGameBridgeInputSurface ToGameHermesSurface(
        PlayerTurnInputSurface inputSurface)
        => inputSurface switch
        {
            PlayerTurnInputSurface.TextEntry =>
                LilithGameBridgeInputSurface.Text,
            PlayerTurnInputSurface.PushToTalkTranscript =>
                LilithGameBridgeInputSurface.Voice,
            _ => throw new ArgumentOutOfRangeException(nameof(inputSurface))
        };

    private static LilithGameBridgeDisplayLocale ToGameHermesDisplayLocale(
        LilithGameDisplayLocale displayLocale)
        => displayLocale switch
        {
            LilithGameDisplayLocale.TraditionalChinese =>
                LilithGameBridgeDisplayLocale.TraditionalChinese,
            LilithGameDisplayLocale.SimplifiedChinese =>
                LilithGameBridgeDisplayLocale.SimplifiedChinese,
            LilithGameDisplayLocale.Japanese =>
                LilithGameBridgeDisplayLocale.Japanese,
            LilithGameDisplayLocale.English =>
                LilithGameBridgeDisplayLocale.English,
            _ => throw new ArgumentOutOfRangeException(nameof(displayLocale))
        };

    private static string GameHermesUnavailableText()
        => ApiKeyText(
            "現在暫時連不上。請稍後再和我說一次。",
            "现在暂时连不上。请稍后再和我说一次。",
            "今はうまく接続できないみたい。少ししてから、もう一度話しかけてね。",
            "I cannot connect right now. Please try talking to me again shortly.");

    private static string GameHermesFailureText(LilithGameBridgeTerminal terminal)
    {
        var text = GameHermesFailurePresentation.ForTerminal(terminal);
        return ApiKeyText(text.TraditionalChinese, text.SimplifiedChinese,
            text.Japanese, text.English);
    }

    private static bool ShouldForwardF7TaskToHigherReasoning(
        PlayerTurnInputSurface inputSurface,
        string text)
    {
        if (inputSurface != PlayerTurnInputSurface.TextEntry
            || string.IsNullOrWhiteSpace(text))
        {
            return false;
        }
        return IsLocalComputerActionIntent(text);
    }

    private static bool IsExplicitLocalComputerTask(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return false;
        return IsLocalComputerActionIntent(text)
            || D045CodexTaskPlan.Classify(text).IsExplicit;
    }

    private static LocalActionGoal ClassifyLocalActionGoal(string text)
    {
        if (!IsLocalComputerActionIntent(text))
            return LocalActionGoal.None;
        const RegexOptions options =
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;
        if (NamesExplicitShell(text, options)
            && NamesExplicitElevation(text, options))
        {
            // There is no atomic two-permission elevated-shell executor. Do
            // not let either broad capability impersonate the missing
            // composite authority.
            return LocalActionGoal.UnsupportedEffect;
        }
        if (Regex.IsMatch(
                text,
                "(?:以系統管理員身分|以系統管理員身份|以管理员身份|管理員權限|管理员权限|系統管理員權限|系统管理员权限|管理者として|\\brun\\s+as\\s+administrator\\b|\\belevated\\b|\\bUAC\\b)",
                options))
        {
            return LocalActionGoal.Elevation;
        }
        if (Regex.IsMatch(
                text,
                "(?:PowerShell|pwsh(?:\\.exe)?|cmd(?:\\.exe)?|command\\s+prompt|shell\\s+command|terminal\\s+command|命令提示字元|命令提示符|命令列|命令行|終端機命令|终端命令|シェルコマンド|ターミナルコマンド)",
                options))
        {
            return LocalActionGoal.RawShell;
        }
        var goals = LocalActionGoal.None;
        if (Regex.IsMatch(
                text,
                "(?:關機|关机|シャットダウン|\\bshut\\s+down\\b)",
                options))
        {
            goals |= LocalActionGoal.Shutdown;
        }
        if (Regex.IsMatch(
                text,
                "(?:重開機|重启|重啟|重新啟動|重新启动|再起動|\\b(?:restart|reboot)\\b)",
                options))
        {
            goals |= LocalActionGoal.Restart;
        }
        if (Regex.IsMatch(
                text,
                "(?:截圖|截图|擷取畫面|截取屏幕|スクリーンショット|\\bscreenshot\\b|\\bcapture\\s+(?:the\\s+)?screen\\b)",
                options))
        {
            goals |= LocalActionGoal.Screenshot;
        }
        if (Regex.IsMatch(
                text,
                "(?:建立|新增|創建|创建|產生|生成|作成|作って|新規|\\b(?:create|make|write)\\b)",
                options))
        {
            goals |= LocalActionGoal.Create;
        }
        var permanentDelete = Regex.IsMatch(
            text,
            "(?:永久(?:刪除|删除)|徹底(?:刪除|删除)|不經資源回收筒|不经过回收站|ゴミ箱を使わず|完全に削除|\\b(?:permanently\\s+delete|delete\\s+permanently|skip\\s+the\\s+recycle\\s+bin)\\b)",
            options);
        if (permanentDelete)
        {
            goals |= LocalActionGoal.PermanentDelete;
        }
        else if (Regex.IsMatch(
                text,
                "(?:刪除|删除|資源回收筒|回收站|削除|ごみ箱|\\b(?:delete|remove|recycle)\\b)",
                options))
        {
            goals |= LocalActionGoal.Delete;
        }
        var forceClose = Regex.IsMatch(
            text,
            "(?:強制(?:關閉|关闭|終止|终止|結束|结束)|強制終了|タスクを終了|\\b(?:force\\s+(?:close|terminate|quit)|kill|end\\s+task|terminate)\\b)",
            options);
        if (forceClose)
        {
            goals |= LocalActionGoal.ForceClose;
        }
        else if (Regex.IsMatch(
                text,
                "(?:關閉|关闭|關掉|关掉|結束|结束|閉じ|終了|\\b(?:close|quit|exit)\\b)",
                options))
        {
            goals |= LocalActionGoal.Close;
        }
        if (Regex.IsMatch(
                text,
                "(?:開啟|打开|打開|開|开|(?<!重新)(?:啟動|启动)|運行|运行|執行|执行|開く|開いて|(?<!再)起動|実行|\\b(?:open|launch|start|run)\\b)",
                options))
        {
            goals |= LocalActionGoal.Open;
        }
        if (Regex.IsMatch(
                text,
                "(?:貼上|粘贴|輸入|输入|貼り付け|入力|\\b(?:type|paste)\\b)",
                options))
        {
            goals |= LocalActionGoal.ExternalInput;
        }
        if (Regex.IsMatch(
                text,
                "(?:尋找|查找|搜尋|搜索|找出|找一下|查看|看看|看一下|讀取|读取|閱讀|阅读|列出|枚舉|枚举|探し|検索|見つけ|見て|読む|読み|一覧|列挙|\\b(?:find|locate|search|look\\s+(?:in|on|for)|have\\s+a\\s+look|read|inspect|list|enumerate)\\b)",
                options))
        {
            goals |= LocalActionGoal.ReadOrInspect;
        }
        var effectGoals = goals & ~LocalActionGoal.ReadOrInspect;
        if (effectGoals != LocalActionGoal.None
            && goals.HasFlag(LocalActionGoal.ReadOrInspect)
            && !Regex.IsMatch(
                text,
                "(?:\u8b80\u53d6|\u8bfb\u53d6|\u95b1\u8b80|\u9605\u8bfb|\u8aad\u3080|\u8aad\u307f|\\b(?:read|inspect)\\b)",
                options))
        {
            // Find/locate is discovery for the requested effect, not a
            // separately completed read goal. The effect's own permission
            // owns its bounded target resolution.
            goals &= ~LocalActionGoal.ReadOrInspect;
        }
        else if (goals.HasFlag(LocalActionGoal.ReadOrInspect))
        {
            goals &= ~LocalActionGoal.ReadOrInspect;
            if (Regex.IsMatch(
                    text,
                    "(?:剪貼簿|剪贴板|クリップボード|\\bclipboard\\b)",
                    options))
            {
                goals |= LocalActionGoal.ClipboardRead;
            }
            else if (Regex.IsMatch(
                    text,
                    "(?:狀態|状态|系統資訊|系统信息|ステータス|状態|\\b(?:status|system\\s+info)\\b)",
                    options))
            {
                goals |= LocalActionGoal.StatusRead;
            }
            else if (Regex.IsMatch(
                    text,
                    "(?:資料夾|文件夾|文件夹|目錄|目录|桌面|下載|下载|圖片資料夾|图片文件夹|フォルダ|ディレクトリ|デスクトップ|\\b(?:folder|director(?:y|ies)|desktop|downloads?)\\b|列出|一覧|列挙|\\b(?:list|enumerate|find|locate|search)\\b)",
                    options))
            {
                goals |= LocalActionGoal.EnumerateFolder;
            }
            else if (ExtractExplicitLocalOpenLeaf(text).Length > 0
                || Regex.IsMatch(
                    text,
                    "(?:檔案|文件(?!夾|夹)|文檔|文档|ファイル|文書|\\b(?:file|document)\\b|讀取|读取|閱讀|阅读|読む|読み|\\b(?:read|inspect)\\b)",
                    options))
            {
                goals |= LocalActionGoal.ReadFile;
            }
            else
            {
                goals |= LocalActionGoal.UnsupportedEffect;
            }
        }
        if (goals.HasFlag(LocalActionGoal.Create)
            && goals.HasFlag(LocalActionGoal.Open))
        {
            goals |= LocalActionGoal.CorrelateCreateOpen;
        }
        return goals == LocalActionGoal.None
            ? LocalActionGoal.UnsupportedEffect
            : goals;
    }

    private static bool NamesExplicitShell(
        string text,
        RegexOptions options)
        => Regex.IsMatch(
            text,
            @"(?:PowerShell|pwsh(?:\.exe)?|cmd(?:\.exe)?|command\s+prompt|shell\s+command|terminal\s+command|\u547d\u4ee4\u63d0\u793a\u5b57\u5143|\u547d\u4ee4\u63d0\u793a\u7b26|\u7d42\u7aef\u547d\u4ee4|\u7ec8\u7aef\u547d\u4ee4)",
            options);

    private static bool NamesExplicitElevation(
        string text,
        RegexOptions options)
        => Regex.IsMatch(
            text,
            @"(?:\u7cfb\u7d71\u7ba1\u7406\u54e1|\u7cfb\u7edf\u7ba1\u7406\u5458|\u7ba1\u7406\u54e1\u6b0a\u9650|\u7ba1\u7406\u5458\u6743\u9650|\brun\s+as\s+administrator\b|\belevated\b|\bUAC\b)",
            options);

    private static LocalOpenTargetKind ClassifyLocalOpenTargetKind(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return LocalOpenTargetKind.Any;
        const RegexOptions options =
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;

        var explicitLeaf = ExtractExplicitLocalOpenLeaf(text);
        if (explicitLeaf.Length > 0 && Path.HasExtension(explicitLeaf))
            return LocalOpenTargetKind.File;

        // A file noun wins over a containing-folder noun. For example,
        // "a folder containing a file named X; open it" is a file-open goal.
        if (Regex.IsMatch(
                text,
                "(?:檔案|文件(?!夾|夹)|文檔|文档|圖片|图片|照片|影像|音訊|音频|聲音|声音|影片|视频|音樂|音乐|模型|模組|ファイル|文書|画像|写真|音声|動画|モデル|\\b(?:file|document|image|picture|photo|audio|video|model|data)\\b)",
                options))
        {
            return LocalOpenTargetKind.File;
        }
        if (Regex.IsMatch(
                text,
                "(?:資料夾|文件夾|文件夹|目錄|目录|フォルダ|ディレクトリ|\\b(?:folder|director(?:y|ies))\\b)",
                options))
        {
            return LocalOpenTargetKind.Directory;
        }
        if (Regex.IsMatch(
                text,
                "(?:應用程式|应用程序|應用|应用|程式|程序|軟體|软件|アプリ|ソフト|プログラム|\\b(?:application|app|program|software)\\b)",
                options))
        {
            return LocalOpenTargetKind.Application;
        }
        // A filesystem location/search/selection phrase is not an
        // application name merely because the final referent has no file
        // extension. Keep it on the local-content resolver.
        if (Regex.IsMatch(
                text,
                @"(?:\u684c\u9762|\u4e0b\u8f09|\u4e0b\u8f7d|\u6587\u4ef6\u593e|\u8cc7\u6599\u593e|\u8d44\u6599\u5939|\u76ee\u9304|\u76ee\u5f55|\u6a94\u6848|\u6587\u4ef6|\bdesktop\b|\bdownloads?\b|\bfolders?\b|\bdirector(?:y|ies)\b|\bfiles?\b|known:(?:desktop|documents|downloads|pictures))",
                options)
            && Regex.IsMatch(
                text,
                @"(?:\u627e\u5230|\u5c0b\u627e|\u67e5\u627e|\u641c\u5c0b|\u641c\u7d22|\u53ea|\u50c5|\u6253\u958b|\u6253\u5f00|\u958b\u555f|\u5f00\u542f|\bfind\b|\blocate\b|\bsearch\b|\bonly\b|\bopen\b)",
                options))
        {
            return LocalOpenTargetKind.File;
        }
        if (ExtractExplicitLocalApplicationTarget(text).Length != 0)
            return LocalOpenTargetKind.Application;
        return LocalOpenTargetKind.Any;
    }

    private static string ExtractExplicitLocalApplicationTarget(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return string.Empty;
        const RegexOptions options =
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;
        var patterns = new[]
        {
            @"\b(?:open|launch|start|run)\s+(?:the\s+)?(?<name>[\p{L}\p{N}][\p{L}\p{N} ._+\-]{0,79}?)(?:\s+(?:app|application|program|software))?(?=\s*(?:,|;|\bthen\b|\band\s+(?:find|locate|focus|type|enter|input)\b))",
            @"(?:\u8acb|\u8bf7|\u5e6b\u6211|\u5e2e\u6211|\u66ff\u6211)?\s*(?:\u958b\u555f|\u5f00\u542f|\u6253\u958b|\u6253\u5f00|\u555f\u52d5|\u542f\u52a8)\s*(?<name>[\p{L}\p{N} ._+\-]{1,80}?)(?:\u61c9\u7528\u7a0b\u5f0f|\u5e94\u7528\u7a0b\u5e8f|\u7a0b\u5f0f|\u7a0b\u5e8f)?(?=\s*(?:[\uff0c,\uff1b;]|(?:\u7136\u5f8c|\u7136\u540e|\u63a5\u8457|\u63a5\u7740|\u4e26)\s*(?:\u627e\u5230|\u5c0b\u627e|\u67e5\u627e|\u805a\u7126|\u8f38\u5165|\u8f93\u5165)))",
            @"\b(?:open|launch|start|run)\s+(?:the\s+)?(?<name>[\p{L}\p{N}][\p{L}\p{N} ._+\-]{0,79}?)(?:\s+(?:app|application|program|software))?(?:\s+(?:please|for\s+me))?[.!?]?\s*$",
            @"(?:\u8acb|\u8bf7|\u5e6b\u6211|\u5e2e\u6211|\u66ff\u6211)?\s*(?:\u958b\u555f|\u5f00\u542f|\u6253\u958b|\u6253\u5f00|\u555f\u52d5|\u542f\u52a8|\u57f7\u884c|\u6267\u884c|\u904b\u884c|\u8fd0\u884c)\s*(?<name>[\p{L}\p{N} ._+\-]{1,80}?)(?:\u61c9\u7528\u7a0b\u5f0f|\u5e94\u7528\u7a0b\u5e8f|\u7a0b\u5f0f|\u7a0b\u5e8f)?[\u3002\uff01!\uff1f?]?\s*$",
            @"(?:\u958b\u3044\u3066|\u8d77\u52d5\u3057\u3066|\u5b9f\u884c\u3057\u3066)\s*(?<name>[\p{L}\p{N} ._+\-]{1,80}?)(?:\u30a2\u30d7\u30ea|\u30d7\u30ed\u30b0\u30e9\u30e0)?[\u3002\uff01!\uff1f?]?\s*$"
        };
        foreach (var pattern in patterns)
        {
            var match = Regex.Match(text.Trim(), pattern, options);
            if (!match.Success)
                continue;
            var candidate = match.Groups["name"].Value
                .Trim()
                .Normalize(NormalizationForm.FormKC);
            if (IsConcreteApplicationIdentity(candidate))
                return candidate;
        }
        return string.Empty;
    }

    private static bool TryFreezeExplicitOpenTargetIdentity(
        string playerText,
        LocalActionGoal actionGoal,
        bool requiresHostApplicationLaunch,
        LocalOpenTargetKind openTargetKind,
        string expectedOpenLeaf,
        out string expectedSemanticTarget,
        out D045AgentTaskStopReason stopReason)
    {
        expectedSemanticTarget = string.Empty;
        stopReason = D045AgentTaskStopReason.None;
        if (!actionGoal.HasFlag(LocalActionGoal.Open)
            && !requiresHostApplicationLaunch)
            return true;

        expectedSemanticTarget = expectedOpenLeaf.Length != 0
            ? expectedOpenLeaf
            : openTargetKind == LocalOpenTargetKind.Application
                ? ExtractExplicitLocalApplicationTarget(playerText)
                : string.Empty;
        var identityAccepted = openTargetKind switch
        {
            LocalOpenTargetKind.Application =>
                IsConcreteApplicationIdentity(expectedSemanticTarget),
            LocalOpenTargetKind.File =>
                IsValidExplicitLocalOpenLeaf(
                    expectedSemanticTarget,
                    requireExtension: Path.HasExtension(
                        expectedSemanticTarget)),
            _ => false
        };
        if (identityAccepted)
            return true;

        stopReason = expectedSemanticTarget.Length == 0
            ? D045AgentTaskStopReason.GoalIncomplete
            : D045AgentTaskStopReason.TargetAmbiguous;
        expectedSemanticTarget = string.Empty;
        return false;
    }

    private static bool IsConcreteApplicationIdentity(string value)
    {
        var candidate = (value ?? string.Empty)
            .Trim()
            .Normalize(NormalizationForm.FormKC);
        if (candidate.Length is < 1 or > 80
            || candidate.IndexOfAny(new[]
            {
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar,
                ':', '*', '?', '"', '<', '>', '|', '`', '$'
            }) >= 0
            || !Regex.IsMatch(
                candidate,
                @"^[\p{L}\p{N}][\p{L}\p{N} ._+\-]{0,79}$",
                RegexOptions.CultureInvariant))
        {
            return false;
        }

        // Positive identity grammar: after removing only recognized generic
        // quantifiers and object-type words, at least one concrete name token
        // must remain. This rejects open-ended vague phrases without relying
        // on a finite list of complete sentences.
        var concreteRemainder = Regex.Replace(
            candidate,
            @"\b(?:any|some|whatever|anything|something|either|one|the|an?|app|application|program|software|thing)\b|(?:\u4efb\u610f|\u96a8\u4fbf|\u968f\u4fbf|\u4efb\u4f55|\u67d0(?:\u500b|\u4e2a)?|\u4e00(?:\u500b|\u4e2a)|\u9019(?:\u500b|\u4e2a)|\u8fd9(?:\u500b|\u4e2a)|\u90a3(?:\u500b|\u4e2a)|\u61c9\u7528\u7a0b\u5f0f|\u5e94\u7528\u7a0b\u5e8f|\u61c9\u7528|\u5e94\u7528|\u7a0b\u5f0f|\u7a0b\u5e8f|\u8edf\u9ad4|\u8f6f\u4ef6|\u6771\u897f|\u4e1c\u897f|\u3069\u308c\u3067\u3082|\u4f55\u3067\u3082|\u3069\u308c\u304b|\u4f55\u304b|\u3044\u305a\u308c\u304b|\u305d\u308c|\u3053\u308c|\u3042\u308c|\u30a2\u30d7\u30ea|\u30d7\u30ed\u30b0\u30e9\u30e0|\u30bd\u30d5\u30c8)",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        return concreteRemainder.Any(char.IsLetterOrDigit);
    }

    private static bool TryFreezeHostEffectTarget(
        string playerText,
        LocalActionGoal actionGoal,
        out HostEffectTargetDescriptor? descriptor,
        out D045AgentTaskStopReason stopReason)
    {
        descriptor = null;
        stopReason = D045AgentTaskStopReason.None;
        var targetBoundGoals = new[]
        {
            LocalActionGoal.Create,
            LocalActionGoal.Delete,
            LocalActionGoal.PermanentDelete,
            LocalActionGoal.Close,
            LocalActionGoal.ForceClose,
            LocalActionGoal.Elevation
        }.Where(goal => actionGoal.HasFlag(goal)).ToArray();
        if (targetBoundGoals.Length == 0)
            return true;

        // The bitmask goal ledger cannot represent two independent instances
        // of one destructive/elevated goal. Refuse composite scoped effects
        // rather than letting one receipt impersonate several player targets.
        if (targetBoundGoals.Length != 1)
        {
            stopReason = D045AgentTaskStopReason.TargetAmbiguous;
            return false;
        }

        var goal = targetBoundGoals[0];
        if (CountHostEffectVerbs(playerText, goal) > 1)
        {
            stopReason = D045AgentTaskStopReason.TargetAmbiguous;
            return false;
        }

        if (goal is LocalActionGoal.Close or LocalActionGoal.ForceClose)
        {
            var processIds = ExtractExplicitProcessIds(playerText);
            if (processIds.Count == 1)
            {
                descriptor = HostEffectTargetDescriptor.ForProcess(
                    goal,
                    goal == LocalActionGoal.Close
                        ? D045PermissionCapability.GracefulProcessClose
                        : D045PermissionCapability.ForceTerminateProcess,
                    processIds[0]);
                return true;
            }
            stopReason = processIds.Count > 1
                ? D045AgentTaskStopReason.TargetAmbiguous
                : D045AgentTaskStopReason.GoalIncomplete;
            return false;
        }

        var paths = ExtractExactHostEffectPaths(playerText);
        if (paths.Count != 1)
        {
            stopReason = paths.Count > 1
                ? D045AgentTaskStopReason.TargetAmbiguous
                : D045AgentTaskStopReason.GoalIncomplete;
            return false;
        }
        if (goal == LocalActionGoal.Elevation
            && !string.Equals(
                Path.GetExtension(paths[0]),
                ".exe",
                StringComparison.OrdinalIgnoreCase))
        {
            stopReason = D045AgentTaskStopReason.GoalIncomplete;
            return false;
        }

        descriptor = HostEffectTargetDescriptor.ForPath(
            goal,
            goal switch
            {
                LocalActionGoal.Create =>
                    D045PermissionCapability.LocalDataCreate,
                LocalActionGoal.Delete =>
                    D045PermissionCapability.RecycleBinDelete,
                LocalActionGoal.PermanentDelete =>
                    D045PermissionCapability.PermanentDelete,
                _ => D045PermissionCapability.GeneralElevationAdminAccess
            },
            paths[0]);
        return true;
    }

    private static int CountHostEffectVerbs(
        string text,
        LocalActionGoal goal)
    {
        var pattern = goal switch
        {
            LocalActionGoal.Create =>
                @"\b(?:create|make|write)\b|(?:\u5efa\u7acb|\u65b0\u589e|\u5275\u5efa|\u521b\u5efa|\u4f5c\u6210)",
            LocalActionGoal.Delete or LocalActionGoal.PermanentDelete =>
                @"\b(?:delete|remove|recycle)\b|(?:\u522a\u9664|\u5220\u9664|\u524a\u9664)",
            LocalActionGoal.Close or LocalActionGoal.ForceClose =>
                @"\b(?:close|quit|terminate|kill|end\s+task)\b|(?:\u95dc\u9589|\u5173\u95ed|\u7d42\u6b62|\u7ec8\u6b62|\u7d50\u675f|\u7ed3\u675f|\u7d42\u4e86)",
            LocalActionGoal.Elevation =>
                @"\b(?:elevated|UAC|run\s+as\s+administrator)\b|(?:\u7cfb\u7d71\u7ba1\u7406\u54e1|\u7cfb\u7edf\u7ba1\u7406\u5458|\u7ba1\u7406\u54e1\u6b0a\u9650|\u7ba1\u7406\u5458\u6743\u9650)",
            _ => "(?!)"
        };
        return Regex.Matches(
            text ?? string.Empty,
            pattern,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Count;
    }

    private static IReadOnlyList<int> ExtractExplicitProcessIds(string text)
    {
        var values = new HashSet<int>();
        foreach (Match match in Regex.Matches(
                     text ?? string.Empty,
                     @"\b(?:pid|process\s+id)\s*[:#=]?\s*(?<pid>[1-9][0-9]{0,9})\b",
                     RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
        {
            if (int.TryParse(
                    match.Groups["pid"].Value,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var processId)
                && processId > 0)
            {
                values.Add(processId);
            }
        }
        return values.OrderBy(value => value).ToArray();
    }

    private static IReadOnlyList<string> ExtractExactHostEffectPaths(
        string text)
    {
        var paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var value = text ?? string.Empty;
        foreach (var pattern in new[]
        {
            @"[""'\u201c\u201d\u2018\u2019\u300c\u300d\u300e\u300f](?<path>[A-Za-z]:[\\/][^""'\u201c\u201d\u2018\u2019\u300c\u300d\u300e\u300f\r\n]{1,1022})[""'\u201c\u201d\u2018\u2019\u300c\u300d\u300e\u300f]",
            @"(?<![\p{L}\p{N}])(?<path>[A-Za-z]:[\\/][^\s""'<>|?*\r\n,;\u3002\uff0c\uff1b\uff01\uff1f]+)"
        })
        {
            foreach (Match match in Regex.Matches(
                         value,
                         pattern,
                         RegexOptions.CultureInvariant))
            {
                if (TryNormalizeHostEffectPath(
                        match.Groups["path"].Value,
                        out var path))
                {
                    paths.Add(path);
                }
            }
        }
        if (paths.Count > 0 || !Regex.IsMatch(
                value,
                @"\bdesktop\b|\u684c\u9762|\u30c7\u30b9\u30af\u30c8\u30c3\u30d7",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
        {
            return paths.OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
                .ToArray();
        }

        var leaves = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var explicitFileLeaf = ExtractExplicitLocalOpenLeaf(value);
        if (IsSafeHostEffectLeaf(explicitFileLeaf))
            leaves.Add(explicitFileLeaf);
        foreach (var pattern in new[]
        {
            @"\b(?:named|called)\s+[""']?(?<leaf>[\p{L}\p{N}_.+\- ]{1,120}?)[""']?(?=\s+(?:on|in)\s+(?:(?:the|my)\s+)?desktop\b|[.!?]?\s*$)",
            @"\b(?:folder|directory)\s+(?:named\s+|called\s+)?[""']?(?<leaf>[\p{L}\p{N}_.+\- ]{1,120}?)[""']?(?=\s+(?:on|in)\s+(?:(?:the|my)\s+)?desktop\b|[.!?]?\s*$)",
            @"(?:\u8cc7\u6599\u593e|\u8d44\u6599\u5939|\u6587\u4ef6\u593e)\s*(?:\u53eb\u505a|\u540d\u70ba|\u540d\u4e3a)?\s*[""']?(?<leaf>[\p{L}\p{N}_.+\- ]{1,120}?)[""']?(?=\s*(?:\u5728|\u5230)?\s*\u684c\u9762|[\u3002\uff01\uff1f]?\s*$)"
        })
        {
            foreach (Match match in Regex.Matches(
                         value,
                         pattern,
                         RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
            {
                var leaf = match.Groups["leaf"].Value.Trim();
                if (IsSafeHostEffectLeaf(leaf))
                    leaves.Add(leaf.Normalize(NormalizationForm.FormC));
            }
        }
        if (leaves.Count != 1)
            return Array.Empty<string>();
        var desktop = Environment.GetFolderPath(
            Environment.SpecialFolder.DesktopDirectory);
        if (string.IsNullOrWhiteSpace(desktop))
            return Array.Empty<string>();
        return TryNormalizeHostEffectPath(
                Path.Combine(desktop, leaves.Single()),
                out var desktopPath)
            ? new[] { desktopPath }
            : Array.Empty<string>();
    }

    private static bool IsSafeHostEffectLeaf(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return false;
        var leaf = value.Trim().Normalize(NormalizationForm.FormC);
        return leaf.Length <= 120
            && leaf is not ("." or "..")
            && leaf.IndexOfAny(new[]
            {
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar,
                ':', '*', '?', '"', '<', '>', '|', '\0', ',', ';', '\u3001',
                '\uff0c', '\uff1b'
            }) < 0
            && !Regex.IsMatch(
                leaf,
                @"\b(?:and|or)\b|(?:\u4e26\u4e14|\u4ee5\u53ca|\u9084\u6709|\u8fd8\u6709)",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static bool TryNormalizeHostEffectPath(
        string value,
        out string path)
    {
        path = string.Empty;
        if (string.IsNullOrWhiteSpace(value)
            || value.IndexOfAny(new[] { '\0', '*', '?', '"', '<', '>', '|' }) >= 0)
        {
            return false;
        }
        try
        {
            var candidate = value.Trim()
                .Replace(Path.AltDirectorySeparatorChar, Path.DirectorySeparatorChar)
                .Normalize(NormalizationForm.FormC);
            if (!Path.IsPathFullyQualified(candidate)
                || candidate.StartsWith("\\\\", StringComparison.Ordinal))
            {
                return false;
            }
            var fullPath = Path.GetFullPath(candidate);
            var root = Path.GetPathRoot(fullPath) ?? string.Empty;
            if (root.Length == 0
                || string.Equals(
                    fullPath.TrimEnd(Path.DirectorySeparatorChar),
                    root.TrimEnd(Path.DirectorySeparatorChar),
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            path = fullPath.TrimEnd(Path.DirectorySeparatorChar);
            return true;
        }
        catch (Exception exception) when (exception is ArgumentException
            or NotSupportedException
            or PathTooLongException)
        {
            return false;
        }
    }

    private static string ExtractExplicitLocalOpenLeaf(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return string.Empty;
        const RegexOptions options =
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;
        var value = text.Trim();

        // A quoted filename may contain spaces. An unquoted filename-shaped
        // token is deliberately whitespace-bounded so ordinary prose does not
        // become an authoritative local identity by accident.
        var quoted = Regex.Matches(
            value,
            "[\\\"'“‘「『](?<leaf>[^\\\"'”’」』<>|/\\\\:\\r\\n]{1,160}\\.[\\p{L}\\p{N}]{1,12})[\\\"'”’」』]",
            options);
        for (var index = quoted.Count - 1; index >= 0; index--)
        {
            var candidate = NormalizeExplicitLocalOpenLeaf(
                quoted[index].Groups["leaf"].Value);
            if (IsValidExplicitLocalOpenLeaf(candidate, requireExtension: true))
                return candidate;
        }

        var filenameTokens = Regex.Matches(
            value,
            "(?<leaf>[^\\s\\\"'“”‘’「」『』<>|/\\\\:，,。.!！?？]{1,160}\\.[\\p{L}\\p{N}]{1,12})(?=$|[\\s\\\"'“”‘’「」『』，,。.!！?？])",
            options);
        for (var index = filenameTokens.Count - 1; index >= 0; index--)
        {
            var candidate = Regex.Replace(
                filenameTokens[index].Groups["leaf"].Value,
                "^(?:(?:請|请|幫我|帮我|替我|給我|给我)?(?:打開|打开|開啟|开启|開|开|open|launch|start))+",
                string.Empty,
                options);
            candidate = NormalizeExplicitLocalOpenLeaf(candidate);
            if (IsValidExplicitLocalOpenLeaf(candidate, requireExtension: true))
                return candidate;
        }

        var namedPatterns = new[]
        {
            "(?:(?:檔案|文件)\\s*)?(?:叫|名為|名为)\\s*(?<leaf>[^，,。.!！?？]{1,160}?)(?=\\s*(?:(?:然後|然后)\\s*)?(?:(?:請|请|麻煩|麻烦|幫我|帮我|替我|給我|给我)\\s*)?(?:打開|打开|開啟|开启|開|开)|[，,。.!！?？]|$)",
            "(?:file\\s+)?(?:named|called)\\s+(?<leaf>[^,.;!?]{1,160}?)(?=\\s*(?:(?:and\\s+)?(?:then\\s+)?(?:please\\s+)?(?:open|launch|start)\\b)|[,.;!?]|$)"
        };
        foreach (var pattern in namedPatterns)
        {
            var match = Regex.Match(value, pattern, options);
            if (!match.Success)
                continue;
            var candidate = NormalizeExplicitLocalOpenLeaf(
                match.Groups["leaf"].Value);
            if (IsValidExplicitLocalOpenLeaf(candidate, requireExtension: false))
                return candidate;
        }
        return string.Empty;
    }

    private static string NormalizeExplicitLocalOpenLeaf(string value)
    {
        var candidate = value.Trim().Trim(
            '\"', '\'', '“', '”', '‘', '’', '「', '」', '『', '』');
        candidate = Regex.Replace(
            candidate,
            @"^(?:\u5728)?(?:\u684c\u9762|\u4e0b\u8f09|\u4e0b\u8f7d|\u6587\u4ef6|\u5716\u7247|\u56fe\u7247)(?:\u4e0a|\u88e1|\u91cc|\u5167|\u5185|\u4e2d)?(?:\u7684)?",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Trim();
        candidate = Regex.Replace(
            candidate,
            "(?:這個|这个|這一個|这一个|該檔案|该文件|the\\s+file)$",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Trim();
        return candidate.Normalize(NormalizationForm.FormKC);
    }

    private static string NormalizeSemanticTargetIdentity(string value)
    {
        var candidate = (value ?? string.Empty)
            .Trim()
            .Normalize(NormalizationForm.FormKC);
        var separator = candidate.LastIndexOfAny(new[] { '/', '\\' });
        if (separator >= 0 && separator + 1 < candidate.Length)
            candidate = candidate[(separator + 1)..];
        if (candidate.StartsWith("**/", StringComparison.Ordinal))
            candidate = candidate[3..];
        try
        {
            var extension = Path.GetExtension(candidate);
            if (extension.Length is >= 2 and <= 17)
                candidate = Path.GetFileNameWithoutExtension(candidate);
        }
        catch (ArgumentException)
        {
            return string.Empty;
        }
        candidate = Regex.Replace(
            candidate,
            @"\b(?:app|application|program|software|file|folder|directory)\b|(?:\u61c9\u7528\u7a0b\u5f0f|\u5e94\u7528\u7a0b\u5e8f|\u7a0b\u5f0f|\u7a0b\u5e8f|\u6a94\u6848|\u6587\u4ef6|\u8cc7\u6599\u593e|\u8d44\u6599\u5939|\u30a2\u30d7\u30ea|\u30d7\u30ed\u30b0\u30e9\u30e0)$",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        return new string(candidate
            .Where(char.IsLetterOrDigit)
            .Select(char.ToUpperInvariant)
            .ToArray());
    }

    private static bool IsValidExplicitLocalOpenLeaf(
        string candidate,
        bool requireExtension)
    {
        if (candidate.Length is < 1 or > 160
            || candidate is "." or ".."
            || candidate.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0
            || !string.Equals(
                Path.GetFileName(candidate),
                candidate,
                StringComparison.Ordinal))
        {
            return false;
        }
        if (!requireExtension)
            return true;
        var extension = Path.GetExtension(candidate);
        return extension.Length is >= 2 and <= 13
            && extension[1..].All(char.IsLetterOrDigit);
    }

    private static bool IsLocalComputerActionIntent(string text)
    {
        var value = text.Trim();
        const RegexOptions options =
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant;
        if (IsExplicitShellOrElevationRequest(value, options))
            return true;
        var hasAction = Regex.IsMatch(
            value,
            "(?:開啟|打开|打開|開|开|啟動|启动|運行|运行|執行|执行|關閉|关闭|關掉|关掉|關|关|結束|结束|終止|尋找|查找|搜尋|搜索|找出|找一下|找|查看|看看|看一下|看|讀取|读取|閱讀|阅读|讀|读|列出|枚舉|枚举|建立|新增|創建|创建|產生|生成|刪除|删除|移動|移动|複製|复制|重新命名|重命名|貼上|粘贴|輸入|输入|關機|关机|重新啟動|重新启动|重開機|重启|截圖|截图|擷取畫面|截取屏幕|開く|開いて|起動|実行|閉じ|終了|探し|検索|見つけ|見て|読む|読み|一覧|列挙|作成|作って|新規|削除|移動|コピー|名前を変更|貼り付け|入力|シャットダウン|再起動|スクリーンショット|\\b(?:open|launch|start|run|close|quit|terminate|find|locate|search|look\\s+(?:in|on|for)|have\\s+a\\s+look\\s+(?:in|on|at)|read|inspect|list|enumerate|create|make|write|delete|remove|recycle|move|copy|rename|type|paste|shut\\s+down|restart|reboot|capture|take\\s+(?:a\\s+)?screenshot)\\b)",
            options);
        if (!hasAction)
            return false;

        var hasLocalObject = Regex.IsMatch(
            value,
            "(?:桌面|本機|本地|電腦|电脑|下載|下载|文件|文檔|文档|資料夾|文件夹|目錄|目录|檔案|圖片|图片|照片|文件|文件檔|應用程式|应用程序|程式|程序|軟體|软件|視窗|窗口|剪貼簿|剪贴板|處理程序|进程|資源回收筒|回收站|デスクトップ|ローカル|パソコン|コンピュータ|ダウンロード|ドキュメント|フォルダ|ディレクトリ|ファイル|画像|写真|文書|アプリ|ソフト|プログラム|ウィンドウ|クリップボード|プロセス|ごみ箱|\\b(?:desktop|computer|pc|local|download(?:s)?|document(?:s)?|folder|director(?:y|ies)|file|path|picture|photo|image|audio|video|application|app|program|software|window|clipboard|process|recycle\\s+bin|trash|known:(?:desktop|documents|downloads|pictures)(?:[/\\\\][^\\s]+)?)\\b)",
            options);
        var hasInherentlyLocalAction = Regex.IsMatch(
            value,
            "(?:關機|关机|重新啟動|重新启动|重開機|重启|截圖|截图|擷取畫面|截取屏幕|シャットダウン|再起動|スクリーンショット|\\b(?:open|launch|start|run|close|quit|terminate|shut\\s+down|restart|reboot|capture|take\\s+(?:a\\s+)?screenshot)\\b|開啟|打开|打開|開|开|啟動|启动|運行|运行|關閉|关闭|關掉|关掉|關|关|開く|開いて|起動|閉じ|終了)",
            options);
        if (!hasLocalObject && !hasInherentlyLocalAction)
            return false;

        var directImperative = Regex.IsMatch(
                value,
                "(?:^|[，,。.!！?？]\\s*)(?:(?:莉莉絲|莉莉丝|lilith)[,，：:\\s]*)?(?:(?:請|请|麻煩|麻烦|幫我|帮我|替我|給我|给我|可以(?:幫我|帮我)?|能不能|我要你|我想請你|我想请你)\\s*)?(?:開啟|打开|打開|開|开|啟動|启动|運行|运行|執行|执行|關閉|关闭|關掉|关掉|關|关|結束|结束|終止|尋找|查找|搜尋|搜索|找出|找一下|找|查看|看看|看一下|看|讀取|读取|閱讀|阅读|讀|读|列出|枚舉|枚举|建立|新增|創建|创建|產生|生成|刪除|删除|移動|移动|複製|复制|重新命名|重命名|貼上|粘贴|輸入|输入|關機|关机|重新啟動|重新启动|重開機|重启|截圖|截图|擷取畫面|截取屏幕)",
                options)
            || Regex.IsMatch(
                value,
                "(?:請|请|麻煩|麻烦|幫我|帮我|替我|給我|给我|可以(?:幫我|帮我)?|能不能|我要你|我想請你|我想请你)\\s*(?:把|將|将)?[^。.!！?？]{0,80}?(?:開啟|打开|打開|開|开|啟動|启动|運行|运行|執行|执行|關閉|关闭|關掉|关掉|關|关|結束|结束|終止|尋找|查找|搜尋|搜索|找出|找一下|找|查看|看看|看一下|看|讀取|读取|閱讀|阅读|讀|读|列出|枚舉|枚举|建立|新增|創建|创建|產生|生成|刪除|删除|移動|移动|複製|复制|重新命名|重命名|貼上|粘贴|輸入|输入|關機|关机|重新啟動|重新启动|重開機|重启|截圖|截图|擷取畫面|截取屏幕)",
                options)
            || Regex.IsMatch(
                value,
                "^(?:(?:please|kindly)\\s+|(?:can|could|would|will)\\s+you\\s+|i\\s+(?:need|want)\\s+you\\s+to\\s+|go\\s+ahead\\s+and\\s+)?(?:open|launch|start|run|close|quit|terminate|find|locate|search|look\\s+(?:in|on|for)|read|inspect|list|enumerate|create|make|write|delete|remove|recycle|move|copy|rename|type|paste|shut\\s+down|restart|reboot|capture|take\\s+(?:a\\s+)?screenshot)\\b",
                options)
            || Regex.IsMatch(
                value,
                "(?:(?:please|kindly|can\\s+you|could\\s+you|would\\s+you|will\\s+you|i\\s+(?:need|want)\\s+you\\s+to)\\s+)(?:[^.!?]{0,40}\\s)?(?:open|launch|start|run|close|quit|terminate|find|locate|search|look\\s+(?:in|on|for)|read|inspect|list|enumerate|create|make|write|delete|remove|recycle|move|copy|rename|type|paste|shut\\s+down|restart|reboot|capture|take\\s+(?:a\\s+)?screenshot)\\b",
                options)
            || Regex.IsMatch(
                value,
                "(?:お願い|頼む|ください|してほしい|してくれる|してもらえる|ちょうだい|リリス[、,:：\\s]*)[^。.!！?？]{0,80}?(?:開いて|起動して|実行して|閉じて|終了して|探して|検索して|見つけて|見て|読んで|読み取って|一覧にして|列挙して|作って|作成して|削除して|移動して|コピーして|名前を変更して|貼り付けて|入力して|シャットダウンして|再起動して|撮って)|(?:開いて|起動して|実行して|閉じて|終了して|探して|検索して|見つけて|見て|読んで|読み取って|一覧にして|列挙して|作って|作成して|削除して|移動して|コピーして|名前を変更して|貼り付けて|入力して|シャットダウンして|再起動して|撮って)(?:ください|くれる|ほしい)?[。.!！?？]*$",
                options);
        if (!directImperative)
        {
            // Accept location-first commands such as "在桌面建立 X" without
            // weakening the normal imperative requirement.  The location is
            // still restricted to known local scopes and the educational
            // question filter below remains authoritative.
            directImperative = Regex.IsMatch(
                    value,
                    @"^(?:\u5728|\u5230)?(?:\u684c\u9762|\u4e0b\u8f09|\u4e0b\u8f7d|\u6587\u4ef6|\u5716\u7247|\u56fe\u7247|\u8cc7\u6599\u593e|\u8d44\u6599\u5939|known:(?:desktop|documents|downloads|pictures))(?:\u4e0a|\u88e1|\u91cc|\u5167|\u5185|\u4e2d)?(?:\u7684)?[^\u3002.!\uff01?\uff1f]{0,80}?(?:\u958b\u555f|\u5f00\u542f|\u6253\u958b|\u6253\u5f00|\u5efa\u7acb|\u65b0\u589e|\u5275\u5efa|\u521b\u5efa|\u5beb\u5165|\u5199\u5165|\u522a\u9664|\u79fb\u52d5|\u79fb\u52a8|\u8907\u88fd|\u590d\u5236|\u91cd\u65b0\u547d\u540d|\u91cd\u547d\u540d)",
                    options)
                || Regex.IsMatch(
                    value,
                    @"^(?:on|in)\s+(?:the\s+)?(?:desktop|downloads?|documents?|pictures?|known:(?:desktop|documents|downloads|pictures))\b[^.!?]{0,80}\b(?:open|create|make|write|delete|move|copy|rename)\b",
                    options);
        }
        if (!directImperative)
            return false;

        var educationalQuestion = Regex.IsMatch(
            value,
            "(?:怎麼|怎么|如何|為什麼|为什么|教我|教學|教学|教程|方法|怎樣|怎样|どうやって|どのように|なぜ|方法|使い方|教えて|\\bhow\\s+(?:do|can|would|should)\\b|\\bwhat\\s+is\\b|\\bwhy\\b|\\btell\\s+me\\s+how\\b|\\bexplain\\b)",
            options);
        var explicitEffectRequest = Regex.IsMatch(
            value,
            "(?:幫我|帮我|替我|給我|给我|我要你|我想請你|我想请你)\\s*(?:把|將|将)?[^。.!！?？]{0,40}?(?:開啟|打开|打開|開|开|啟動|启动|運行|运行|關閉|关闭|關掉|关掉|關|关|尋找|查找|搜尋|搜索|找出|找|讀取|读取|讀|读|列出|建立|新增|創建|创建|刪除|删除|關機|关机|重启|重新啟動|截圖|截图)|^(?:(?:please|kindly)\\s+|(?:can|could|would|will)\\s+you\\s+|i\\s+(?:need|want)\\s+you\\s+to\\s+)(?:open|launch|start|run|close|quit|terminate|find|locate|search|read|inspect|list|enumerate|create|make|write|delete|remove|move|copy|rename|shut\\s+down|restart|reboot|capture|take\\s+(?:a\\s+)?screenshot)\\b|(?:お願い|頼む|ください|してほしい)[^。.!！?？]{0,40}?(?:開いて|起動して|閉じて|探して|検索して|見つけて|読んで|作って|削除して|再起動して|撮って)",
            options);
        return !educationalQuestion || explicitEffectRequest;
    }

    private static bool IsExplicitShellOrElevationRequest(
        string value,
        RegexOptions options)
    {
        var namesShellOrElevation = Regex.IsMatch(
            value,
            "(?:PowerShell|pwsh(?:\\.exe)?|cmd(?:\\.exe)?|command\\s+prompt|shell\\s+command|terminal\\s+command|命令提示字元|命令提示符|命令列|命令行|終端機命令|终端命令|シェルコマンド|ターミナルコマンド|以系統管理員身分|以系統管理員身份|以管理员身份|管理員權限|管理员权限|管理者として|\\brun\\s+as\\s+administrator\\b|\\belevated\\b|\\bUAC\\b)",
            options);
        if (!namesShellOrElevation)
            return false;
        var imperative = Regex.IsMatch(
            value,
            "(?:請|请|幫我|帮我|替我|我要你|執行|执行|運行|运行|使用|用|お願い|実行して|使って|\\b(?:please|run|execute|use)\\b)",
            options);
        var educational = Regex.IsMatch(
            value,
            "(?:怎麼|怎么|如何|為什麼|为什么|教我|教學|教学|どうやって|なぜ|教えて|\\b(?:how|why|explain|tell\\s+me\\s+how)\\b)",
            options);
        return imperative && !educational;
    }

    private static bool IsScreenshotCommand(string text)
    {
        var requestsScreenshot = Regex.IsMatch(text.Trim(),
            "^(?:(?:可以)?(?:幫我|帮我|請|请|替我)\\s*)?(?:截(?:個|个|一張|一张)?圖|截图|擷取(?:一下)?畫面|截取(?:一下)?屏幕)(?:一下|一張|一张|吧|嗎|吗|好嗎|好吗)?[。.!！?？]*$|^(?:take|capture)(?:\\s+me)?\\s+(?:a\\s+)?(?:screenshot|screen shot|the screen)[.!?]*$|^(?:スクリーンショット(?:を)?撮って|画面を撮って|スクリーンショットお願い)[。.!?？]*$",
            RegexOptions.IgnoreCase);
        if (!requestsScreenshot)
            return false;
        if (Regex.IsMatch(text,
            "(怎麼|如何|為什麼|为什么|教我|どのように|どうやって|what|why|how)",
            RegexOptions.IgnoreCase))
            return false;

        return true;
    }

    private static bool TryHandleScreenshotCommand(
        string text,
        PlayerTurnOperationHandle operation,
        out string reply)
    {
        reply = string.Empty;
        if (!IsScreenshotCommand(text))
            return false;

        D045PermissionControlSnapshot permissionSnapshot;
        try
        {
            permissionSnapshot = LocalPermissionStore.Load().Snapshot;
        }
        catch (Exception exception) when (exception is IOException
            or UnauthorizedAccessException
            or InvalidDataException
            or InvalidOperationException
            or ArgumentException)
        {
            Plugin.PluginLog.LogWarning(
                "Screenshot permission state was unavailable; using Default Off: "
                + exception.GetType().Name);
            reply = ApiKeyText(
                "目前無法確認截圖權限，所以沒有擷取畫面。",
                "目前无法确认截图权限，所以没有截取画面。",
                "スクリーンショット権限を確認できなかったため、画面は撮影していないよ。",
                "Screenshot permission could not be verified, so no image was captured.");
            return false;
        }
        if (permissionSnapshot.Revision <= 0
            || !permissionSnapshot.IsEnabled(
                D045PermissionCapability.ScreenshotCapture))
        {
            reply = ApiKeyText(
                "要先在 Control Center 的「設定 → 隱私與權限」開啟「擷取螢幕截圖」，我才能替你截圖。",
                "要先在 Control Center 的“设置 → 隐私与权限”开启“截取屏幕截图”，我才能替你截图。",
                "Control Center の「設定 → プライバシーと権限」でスクリーンショットを許可してね。",
                "Enable “Screenshot capture” under Control Center → Settings → Privacy & Permissions first.");
            return false;
        }

        var harnessReceipt = LocalTaskHarness.Execute(new D045HarnessRequest(
            Guid.NewGuid(),
            D045PermissionCapability.ScreenshotCapture,
            timeoutMilliseconds: 15000,
            expectedPermissionRevision: permissionSnapshot.Revision),
            () => PlayerTurnOperations.TryAdmitEffectDispatch(operation));
        if (harnessReceipt.Verified)
        {
            reply = ApiKeyText(
                $"截好了，存在「{harnessReceipt.Output}」。",
                $"截好了，保存在“{harnessReceipt.Output}”。",
                $"撮れたよ。「{harnessReceipt.Output}」に保存した。",
                $"Done. I saved it as {harnessReceipt.Output}.");
        }
        else
        {
            reply = ApiKeyText(
                "截圖沒有通過 Harness 的完成驗證。",
                "截图没有通过 Harness 的完成验证。",
                "スクリーンショットは Harness の完了検証を通過しなかった。",
                "The screenshot did not pass Harness completion verification.");
            Plugin.PluginLog.LogWarning(
                "Screenshot Harness task was not verified: "
                + harnessReceipt.Message);
        }
        return harnessReceipt.Verified;

#if D045_LEGACY_SCREENSHOT_FALLBACK
        try
        {
            var pictures = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures);
            if (string.IsNullOrWhiteSpace(pictures))
                pictures = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Pictures");
            var directory = Path.Combine(pictures, "Lilith Screenshots");
            Directory.CreateDirectory(directory);
            var fileName = $"Lilith_{DateTime.Now:yyyyMMdd_HHmmss}.png";
            var outputPath = Path.Combine(directory, fileName);
            var escapedPath = outputPath.Replace("'", "''");
            var script =
                "Add-Type -AssemblyName System.Windows.Forms; " +
                "Add-Type -AssemblyName System.Drawing; " +
                "$bounds=[System.Windows.Forms.SystemInformation]::VirtualScreen; " +
                "$bitmap=New-Object System.Drawing.Bitmap($bounds.Width,$bounds.Height); " +
                "$graphics=[System.Drawing.Graphics]::FromImage($bitmap); " +
                "$graphics.CopyFromScreen($bounds.Left,$bounds.Top,0,0,$bitmap.Size); " +
                $"$bitmap.Save('{escapedPath}',[System.Drawing.Imaging.ImageFormat]::Png); " +
                "$graphics.Dispose(); $bitmap.Dispose();";
            var encoded = Convert.ToBase64String(Encoding.Unicode.GetBytes(script));
            using var process = Process.Start(new ProcessStartInfo("powershell.exe")
            {
                Arguments = $"-NoLogo -NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand {encoded}",
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardError = true
            });
            if (process == null)
                throw new InvalidOperationException("The screenshot helper could not be started.");
            if (!process.WaitForExit(10000))
            {
                try { process.Kill(true); } catch { }
                throw new TimeoutException("The screenshot helper timed out.");
            }
            var error = process.StandardError.ReadToEnd();
            if (process.ExitCode != 0 || !File.Exists(outputPath))
                throw new InvalidOperationException(string.IsNullOrWhiteSpace(error) ? "No screenshot file was created." : error.Trim());

            reply = ApiKeyText(
                $"截好了，存在「圖片\\Lilith Screenshots\\{fileName}」。",
                $"截好了，保存在“图片\\Lilith Screenshots\\{fileName}”。",
                $"撮れたよ。「ピクチャ\\Lilith Screenshots\\{fileName}」に保存した。",
                $"Done. I saved it as Pictures\\Lilith Screenshots\\{fileName}.");
            Plugin.PluginLog.LogInfo($"Saved an allowlisted desktop screenshot to {outputPath}.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Primary screenshot method failed; trying the Windows screenshot shortcut: {exception.Message}");
            try
            {
                SendShortcut(0x5B, 0x2C);
                reply = ApiKeyText(
                    "已改用 Windows 截圖快捷鍵，圖片會在系統的「螢幕擷取畫面」資料夾。",
                    "已改用 Windows 截图快捷键，图片会在系统的“屏幕截图”文件夹。",
                    "Windowsのスクリーンショット機能に切り替えたよ。画像はシステムのスクリーンショットフォルダーに保存される。",
                    "I used the Windows screenshot shortcut instead; the image will be in the system Screenshots folder.");
            }
            catch (Exception fallbackException)
            {
                reply = ApiKeyText(
                    "這台電腦目前沒有可用的截圖方式。",
                    "这台电脑目前没有可用的截图方式。",
                    "このPCでは今、利用できるスクリーンショット方法が見つからない。",
                    "No compatible screenshot method is currently available on this PC.");
                Plugin.PluginLog.LogWarning($"Screenshot fallback also failed: {fallbackException.Message}");
            }
        }
        return true;
#endif
    }

    private static bool HasAnyHarnessPermission()
    {
        try
        {
            return LocalPermissionStore.Load().Snapshot.AnyEnabled;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Harness permission state was unavailable; using Default Off: "
                + exception.Message);
            return false;
        }
    }

    private static bool TryAdmitExplicitActionPermissions(
        LocalActionGoal actionGoal,
        LocalOpenTargetKind openTargetKind,
        out D045ExplicitActionPermissionPreflightResult result)
    {
        var requirement = new D045ExplicitActionRequirement(
            ToExplicitActionGoals(actionGoal),
            ToExplicitOpenTargetKind(openTargetKind));
        try
        {
            result = D045ExplicitActionPermissionPreflight.Evaluate(
                requirement,
                LocalPermissionStore.Load());
            return result.Admitted;
        }
        catch (Exception exception) when (exception is IOException
            or UnauthorizedAccessException
            or InvalidDataException
            or InvalidOperationException
            or ArgumentException)
        {
            Plugin.PluginLog.LogWarning(
                "Explicit-action permission preflight was unavailable; "
                + "using Default Off: "
                + exception.GetType().Name);
            result = new D045ExplicitActionPermissionPreflightResult(
                admitted: false,
                D045AgentTaskStopReason.PermissionStateUnavailable,
                permissionRevision: 0);
            return false;
        }
    }

    private static bool TryConsumeAgentOperationCancellation(
        PlayerTurnOperationHandle operation,
        out D045WorkbenchTurnCancellationKind kind)
    {
        if (TryConsumeWorkbenchOperationCancellation(operation, out kind))
            return true;
        kind = D045WorkbenchTurnCancellationKind.None;
        return !PlayerTurnOperations.IsActive(operation);
    }

    private static bool IsAgentOperationLive(
        PlayerTurnOperationHandle operation)
        => PlayerTurnOperations.IsActive(operation)
            && (!IsWorkbenchOperation(operation)
                || IsWorkbenchOperationLive(operation));

    private static int RetireSemanticObservationReferences(
        D045SemanticLocalObservationExecutionResult execution,
        string sessionId,
        Guid taskId)
    {
        var retiredCount = 0;
        if (execution.Receipt is null)
            return retiredCount;
        foreach (var candidate in execution.Receipt.Candidates
            .Where(value => value.IsRedeemable))
        {
            LocalTaskHarness.RetireSemanticTargetReference(
                candidate.OpaqueTargetReference,
                sessionId,
                taskId,
                DateTimeOffset.UtcNow);
            retiredCount++;
        }
        return retiredCount;
    }

    private static void BindSemanticReferenceToOperationLifetime(
        PlayerTurnOperationHandle operation,
        Guid taskId,
        string targetReference)
    {
        void Retire()
            => LocalTaskHarness.RetireSemanticTargetReference(
                targetReference,
                operation.OperationId,
                taskId,
                DateTimeOffset.UtcNow);

        _ = PlayerTurnOperations.GetCancellationToken(operation)
            .Register(Retire);
        var workbenchCancellation =
            GetWorkbenchOperationCancellationToken(operation);
        if (workbenchCancellation.CanBeCanceled)
            _ = workbenchCancellation.Register(Retire);
    }

    private static void CompleteAgentOperationCancellation(
        PlayerTurnOperationHandle operation,
        D045WorkbenchTurnCancellationKind kind)
    {
        HermesNoteCandidates.Retire(operation);
        var reason = kind switch
        {
            D045WorkbenchTurnCancellationKind.TurnTimedOut =>
                PlayerTurnCancellationReason.Expired,
            D045WorkbenchTurnCancellationKind.ServerShutdown =>
                PlayerTurnCancellationReason.Shutdown,
            _ => PlayerTurnCancellationReason.Superseded
        };
        if (PlayerTurnOperations.IsActive(operation))
            PlayerTurnOperations.TryCancel(operation, reason);
        CompleteWorkbenchCancellation(operation);
        _requestInFlight = false;
    }

    private static D045ExplicitActionGoal ToExplicitActionGoals(
        LocalActionGoal actionGoal)
    {
        var result = D045ExplicitActionGoal.None;
        if (actionGoal.HasFlag(LocalActionGoal.ReadOrInspect))
            result |= D045ExplicitActionGoal.ReadOrInspect;
        if (actionGoal.HasFlag(LocalActionGoal.ReadFile))
            result |= D045ExplicitActionGoal.ReadFile;
        if (actionGoal.HasFlag(LocalActionGoal.EnumerateFolder))
            result |= D045ExplicitActionGoal.EnumerateFolder;
        if (actionGoal.HasFlag(LocalActionGoal.ClipboardRead))
            result |= D045ExplicitActionGoal.ClipboardRead;
        if (actionGoal.HasFlag(LocalActionGoal.StatusRead))
            result |= D045ExplicitActionGoal.StatusRead;
        if (actionGoal.HasFlag(LocalActionGoal.Open))
            result |= D045ExplicitActionGoal.Open;
        if (actionGoal.HasFlag(LocalActionGoal.Create))
            result |= D045ExplicitActionGoal.Create;
        if (actionGoal.HasFlag(LocalActionGoal.Delete))
            result |= D045ExplicitActionGoal.Delete;
        if (actionGoal.HasFlag(LocalActionGoal.PermanentDelete))
            result |= D045ExplicitActionGoal.PermanentDelete;
        if (actionGoal.HasFlag(LocalActionGoal.Close))
            result |= D045ExplicitActionGoal.Close;
        if (actionGoal.HasFlag(LocalActionGoal.ForceClose))
            result |= D045ExplicitActionGoal.ForceClose;
        if (actionGoal.HasFlag(LocalActionGoal.Shutdown))
            result |= D045ExplicitActionGoal.Shutdown;
        if (actionGoal.HasFlag(LocalActionGoal.Restart))
            result |= D045ExplicitActionGoal.Restart;
        if (actionGoal.HasFlag(LocalActionGoal.Screenshot))
            result |= D045ExplicitActionGoal.Screenshot;
        if (actionGoal.HasFlag(LocalActionGoal.ExternalInput))
            result |= D045ExplicitActionGoal.ExternalInput;
        if (actionGoal.HasFlag(LocalActionGoal.RawShell))
            result |= D045ExplicitActionGoal.RawShell;
        if (actionGoal.HasFlag(LocalActionGoal.Elevation))
            result |= D045ExplicitActionGoal.Elevation;
        if (actionGoal.HasFlag(LocalActionGoal.Workstation))
            result |= D045ExplicitActionGoal.Workstation;
        if (actionGoal.HasFlag(LocalActionGoal.UnsupportedEffect))
            result |= D045ExplicitActionGoal.Unsupported;
        return result;
    }

    private static D045ExplicitOpenTargetKind ToExplicitOpenTargetKind(
        LocalOpenTargetKind kind)
        => kind switch
        {
            LocalOpenTargetKind.File => D045ExplicitOpenTargetKind.File,
            LocalOpenTargetKind.Directory => D045ExplicitOpenTargetKind.Directory,
            LocalOpenTargetKind.Application => D045ExplicitOpenTargetKind.Application,
            _ => D045ExplicitOpenTargetKind.Any
        };

    private static IReadOnlyList<string>
        CaptureEnabledHarnessCapabilityTokens()
        => CaptureHarnessPermissionAdmission().CapabilityTokens;

    private static (IReadOnlyList<string> CapabilityTokens,
        long PermissionRevision,
        D045AgentToolManifest ToolManifest) CaptureHarnessPermissionAdmission()
    {
        try
        {
            var manifest = D045AgentToolManifest.Freeze(
                LocalPermissionStore.Load());
            return (
                manifest.CapabilityTokens,
                manifest.PermissionRevision,
                manifest);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Harness permission state was unavailable while preparing "
                + "the agent capability packet; using Default Off: "
                + exception.Message);
            var manifest = D045AgentToolManifest.Freeze(
                new D045PermissionLoadResult(
                    new D045PermissionControlSnapshot(),
                    D045PermissionStoreDisposition.InvalidDefaultOff));
            return (Array.Empty<string>(), 0, manifest);
        }
    }

    private static string HarnessCapabilityToken(
        D045PermissionCapability capability)
        => D045CapabilityDescriptorCatalog.Get(capability).ToolToken;

    private static string BuildLocalTaskHarnessPrompt(
        IReadOnlyList<string> enabledCapabilities)
    {
        var enabled = enabledCapabilities.Count == 0
            ? "none"
            : string.Join(", ", enabledCapabilities);
        return "\nLocal Task Harness policy: You may call only the tools "
            + "declared for this turn: observe_local_target, run_local_task, "
            + "or run_workstation_tool when present. "
            + "Capabilities enabled for this exact turn: " + enabled + ". "
            + "Treat every capability not named in that list as unavailable; "
            + "do not probe it. Every request must name one specific intended "
            + "target. The Harness binds one task identity to one attempt, "
            + "rechecks permission, verifies the postcondition, and returns a "
            + "receipt. Never claim success unless verified=true. Do not "
            + "treat an inspection receipt as proof that a requested effect "
            + "occurred: completion requires a verified receipt for the "
            + "goal-matching effect capability. Do not substitute a different "
            + "target or capability. Never request "
            + "passwords, API keys, OTPs, or secrets. "
            + "When using a legacy local read/open capability and its local path "
            + "or installed application is not already exact, call "
            + "observe_local_target first when that tool is declared. It is "
            + "read-only, returns at most "
            + "five bounded candidates, and never completes an effect goal. Use "
            + "the returned opaque target_ref as run_local_task.target; do not "
            + "guess or reconstruct a machine path. An ambiguous observation "
            + "requires clarification or a narrower query. "
            + "local_folder_enumerate is directory-only for ordinary exact "
            + "targets; its generic aliases "
            + "known:desktop, "
            + "known:documents, known:downloads, and known:pictures resolve "
            + "the current player's redirected Windows folders without "
            + "revealing a machine-specific path. It accepts an exact directory. "
            + "For a requested file whose leaf name is known but parent directory "
            + "is not, make the effect request directly by calling "
            + "local_content_open once with known:<alias>/**/<file-leaf>. Only if "
            + "that direct request cannot identify one target, "
            + "local_folder_enumerate may use the same bounded recursive selector "
            + "as a read-only unique-candidate fallback; that fallback does not "
            + "open or read the file. Never enumerate or guess sibling folders "
            + "one by one, and never open a parent directory as fallback for a "
            + "requested file. A directory lookup may use "
            + "known:<alias>/**/<directory-leaf>. After "
            + "directory enumeration, append "
            + "/ plus the exact returned relative name to the same known: "
            + "alias when addressing a descendant. Use local_content_open for "
            + "one exact safe document, image, audio, video, or directory and "
            + "let Windows choose its registered application. Never use it for "
            + "executables, scripts, shortcuts, Internet shortcuts, URLs, or "
            + "control files. Use application_launch only for an executable or "
            + "installed application name. local_data_create creates only a "
            + "brand-new UTF-8 file or directory and never overwrites. Do not "
            + "use raw_shell to discover, enumerate, open ordinary local "
            + "content, or launch a normal installed application. Continue "
            + "only while receipts show new progress; an ambiguous, denied, "
            + "skipped, or repeated receipt is not success. Request at most "
            + "one high-risk capability in each tool round, then observe its "
            + "receipt before planning another. Shutdown, restart, "
            + "permanent deletion, raw shell, external-app input, and elevation "
            + "remain available only when explicitly present in the enabled "
             + "list; elevation still requires operating-system confirmation.";
    }

    private const string HostPreObservedApplicationContinuationInstruction =
        "\nThe host has already completed the one permitted read-only "
        + "application observation for this exact player request and resolved "
        + "one unique application. Do not observe, translate, rename, or "
        + "reconstruct the target. The current run_local_task declaration "
        + "contains the sole permitted opaque target. Your next local-tool "
        + "call must use capability application_launch and that exact allowed "
        + "target, with no secondary_target or payload.";

    private const string HostVerifiedApplicationContinuationInstruction =
        "\nThe host has verified the exact application launch from its "
        + "pre-observed opaque reference. Continue only with the exact "
        + "applicationUiTarget returned by that verified launch receipt as "
        + "the target for UI inspection, UI focus/action, window control, or "
        + "keyboard input. Never invent or reconstruct a PID, window, or path, and do "
        + "not launch the application again.";

    private static readonly TimeSpan
        HostApplicationReferenceDeadlineSafetyMargin =
            TimeSpan.FromSeconds(10);

    private static bool TryPreObserveExplicitApplicationOpen(
        bool explicitLocalComputerTask,
        LocalActionGoal actionGoal,
        bool requiresHostApplicationLaunch,
        LocalOpenTargetKind openTargetKind,
        string expectedSemanticTarget,
        long admittedPermissionRevision,
        PlayerTurnOperationHandle operation,
        out HostApplicationPreObservation? observation,
        out D045AgentTaskStopReason stopReason)
    {
        observation = null;
        stopReason = D045AgentTaskStopReason.None;
        if (!explicitLocalComputerTask
            || (!actionGoal.HasFlag(LocalActionGoal.Open)
                && !requiresHostApplicationLaunch)
            || openTargetKind != LocalOpenTargetKind.Application
            || string.IsNullOrWhiteSpace(expectedSemanticTarget))
        {
            return true;
        }

        if (!IsAgentOperationLive(operation))
        {
            stopReason = D045AgentTaskStopReason.OperationCancelled;
            return false;
        }

        var taskId = Guid.NewGuid();
        var call = new GeminiFunctionCallData
        {
            Id = "d045-host-observe-" + taskId.ToString("N"),
            Name = "observe_local_target",
            Args = JsonSerializer.SerializeToElement(new
            {
                query_kind = "query_application",
                query = expectedSemanticTarget
            })
        };
        var observedAtUtc = DateTimeOffset.UtcNow;
        var execution = LocalTaskHarness.ExecuteSemanticObservation(
            new D045SemanticLocalObservationHostRequest(
                operation.OperationId,
                taskId,
                D045SemanticLocalQueryKind.QueryApplication,
                D045SemanticLocalPurpose.LaunchApplication,
                expectedSemanticTarget),
             observedAtUtc);

        if (!IsAgentOperationLive(operation))
        {
            var retiredCount = RetireSemanticObservationReferences(
                execution,
                operation.OperationId,
                taskId);
            Plugin.PluginLog.LogInfo(
                "D-045 host application pre-observation was revoked after "
                + "operation cancellation: referencesRetired=" + retiredCount
                + ", providerCalls=0, effects=0. Query, reference value and "
                + "machine path are omitted.");
            stopReason = D045AgentTaskStopReason.OperationCancelled;
            return false;
        }

        LogSemanticObservationExecution(
            "host-pre-provider",
            D045SemanticLocalQueryKind.QueryApplication,
            execution);

        var receipt = execution.Receipt;
        if (execution.Disposition
                == D045SemanticObservationExecutionDisposition.ObservedUnique
            && receipt is not null
            && receipt.PermissionRevision == admittedPermissionRevision
            && receipt.Complete
            && !receipt.Ambiguous
            && receipt.Candidates.Count == 1
            && receipt.Candidates[0].IsRedeemable)
        {
            BindSemanticReferenceToOperationLifetime(
                operation,
                taskId,
                receipt.Candidates[0].OpaqueTargetReference);
            if (!IsAgentOperationLive(operation))
            {
                RetireSemanticObservationReferences(
                    execution,
                    operation.OperationId,
                    taskId);
                stopReason = D045AgentTaskStopReason.OperationCancelled;
                return false;
            }
            var result = ToolResultFromSemanticObservation(call, execution);
            result.GoalSatisfied = false;
            result.SatisfiedGoals = LocalActionGoal.None.ToString();
            result.AgentPhase = D045AgentTaskPhase.Planning.ToString();
            result.RemainingGoals = actionGoal.ToString();
            result.TerminalReason = D045AgentTaskStopReason.None.ToString();
            observation = new HostApplicationPreObservation(
                taskId,
                call,
                result,
                receipt,
                observedAtUtc
                    + D045SemanticTargetReferenceRegistry.ReferenceLifetime
                    - HostApplicationReferenceDeadlineSafetyMargin);
            Plugin.PluginLog.LogInfo(
                "D-045 host application pre-observation admitted: "
                + "disposition=ObservedUnique, candidates=1, redeemable=1, "
                + "providerCalls=0, effects=0. Query, reference value and "
                + "machine path are omitted.");
            return true;
        }

        RetireSemanticObservationReferences(
            execution,
            operation.OperationId,
            taskId);

        stopReason = execution.Disposition switch
        {
            D045SemanticObservationExecutionDisposition.TargetAmbiguous =>
                D045AgentTaskStopReason.TargetAmbiguous,
            D045SemanticObservationExecutionDisposition.TargetNotFound =>
                D045AgentTaskStopReason.TargetNotFound,
            D045SemanticObservationExecutionDisposition.ApplicationBlocked
                or D045SemanticObservationExecutionDisposition
                    .ApplicationFixedArgumentsRejected
                or D045SemanticObservationExecutionDisposition
                    .UnsafeTargetRejected =>
                D045AgentTaskStopReason.ExplicitActionUnsupported,
            _ when receipt is not null
                && receipt.PermissionRevision != admittedPermissionRevision =>
                D045AgentTaskStopReason.RequiredPermissionRevoked,
            _ => D045AgentTaskStopReason.GoalIncomplete
        };
        Plugin.PluginLog.LogInfo(
            "D-045 host application pre-observation stopped before provider: "
            + "disposition=" + execution.Disposition
            + ", stopReason=" + stopReason
            + ", providerCalls=0, effects=0. Query, reference value and "
            + "machine path are omitted.");
        return false;
    }

    private const string LocalTaskHarnessTargetDescription =
        "Specific URL, path, PID, target, or short-lived opaque d045ref_ target "
        + "returned by observe_local_target and required by the capability. "
        + "local_folder_enumerate is directory-only for ordinary exact targets: "
        + "it accepts an exact "
        + "directory, a known root known:desktop/documents/downloads/pictures, "
        + "or known:<alias>/**/<directory-leaf>. When a requested file leaf is "
        + "known but its parent directory is not, make the effect request by "
        + "calling local_content_open directly once with "
        + "known:<alias>/**/<file-leaf>. Only after that direct request cannot "
        + "identify one target, local_folder_enumerate may use the same bounded "
        + "recursive selector as a read-only unique-candidate fallback; it does "
        + "not open or read the file. No other recursive or wildcard form is "
        + "accepted. Never enumerate guessed sibling folders or open a parent "
        + "directory as fallback. local_content_open accepts one exact safe document, image, "
        + "audio, video, data file, or directory (not executables, scripts, "
        + "shortcuts, URLs, or control files). application_launch accepts an "
        + "exact executable path or installed-application/Start-menu name; "
        + "otherwise empty.";

    private static string BuildSanitizedLilithHarnessStatus()
        => "runtime=active;formal="
            + (Plugin.FormalIntegrationActive ? "1" : "0")
            + ";provider=" + NormalizeAiProvider(Plugin.AiProvider.Value)
            + ";voice=" + (Plugin.VoiceEnabled.Value ? "1" : "0")
            + ";requestInFlight=" + (_requestInFlight ? "1" : "0");

    private static bool TryHandleComputerCommand(string text, out string reply)
    {
        reply = string.Empty;
        return TryHandleBlockedComputerCommand(text, out reply)
            || TryDescribeComputerCapabilities(text, out reply)
            || TryReportSystemStatus(text, out reply)
            || TryOpenKnownFolder(text, out reply)
            || TryHandleWindowCommand(text, out reply)
            || TryWriteClipboard(text, out reply)
            || TryOpenBrowserSearch(text, out reply);
    }

    private static bool TryHandleBlockedComputerCommand(string text, out string reply)
    {
        reply = string.Empty;
        if (Regex.IsMatch(text, "(不要|別|别|不准|しないで|don't|do not)", RegexOptions.IgnoreCase))
            return false;
        var destructive = Regex.IsMatch(text,
            "((刪除|删除|清空|永久刪|delete|erase|empty).{0,12}(檔案|文件|資料夾|文件夹|回收筒|回收站|file|folder|recycle bin)|關機|关机|重新啟動|重新启动|重開機|重启|shutdown|restart|reboot|シャットダウン|再起動)",
            RegexOptions.IgnoreCase);
        var unsafeControl = Regex.IsMatch(text,
            "((關閉|关闭|強制結束|强制结束|kill|terminate|close).{0,8}(程式|程序|應用|应用|視窗|窗口|process|app|window)|PowerShell|命令提示字元|命令提示符|CMD|terminal|終端|管理員權限|管理员权限|administrator|管理者権限)",
            RegexOptions.IgnoreCase);
        var security = Regex.IsMatch(text,
            "((輸入|输入|貼上|粘贴|顯示|显示|讀取|读取|enter|paste|show|read).{0,8}(密碼|密码|API.?KEY|token|驗證碼|验证码|password|OTP|パスワード))",
            RegexOptions.IgnoreCase);
        if (!destructive && !unsafeControl && !security)
            return false;
        reply = ApiKeyText(
            "這類操作可能刪除資料、失去未儲存內容或暴露憑證，所以不在莉莉絲的電腦操作權限內。",
            "这类操作可能删除数据、丢失未保存内容或暴露凭证，所以不在莉莉丝的电脑操作权限内。",
            "データの削除、未保存内容の消失、認証情報の露出につながる操作だから、リリスのPC操作権限には含めていないよ。",
            "That action could delete data, lose unsaved work, or expose credentials, so it is outside Lilith's computer-control permissions.");
        Plugin.PluginLog.LogInfo("Blocked a destructive, arbitrary-shell, or credential-related computer command.");
        return true;
    }

    private static bool TryDescribeComputerCapabilities(string text, out string reply)
    {
        reply = string.Empty;
        if (!Regex.IsMatch(text,
            "((你|妳).{0,5}(能|可以|會|会).{0,8}(操作|控制).{0,5}(電腦|电脑|PC)|(進階|高级|高度な|advanced).{0,5}(功能|機能|controls)|what can you (?:do|control).{0,8}(?:computer|PC))",
            RegexOptions.IgnoreCase))
            return false;
        reply = ApiKeyText(
            "我能替你截圖、開啟常用資料夾、切換或排列視窗、顯示桌面、開啟工作檢視、複製指定文字，以及用瀏覽器搜尋。也能查看電量、記憶體、系統磁碟和網路狀態；刪檔、關機、密碼與任意終端指令不在權限內。",
            "我能替你截图、打开常用文件夹、切换或排列窗口、显示桌面、打开任务视图、复制指定文字，以及用浏览器搜索。也能查看电量、内存、系统磁盘和网络状态；删除文件、关机、密码与任意终端命令不在权限内。",
            "スクリーンショット、よく使うフォルダー、ウィンドウの切替や整列、デスクトップ表示、タスクビュー、指定した文字のコピー、ブラウザ検索ができるよ。バッテリー、メモリ、システムドライブ、ネット接続も確認できるけれど、削除、シャットダウン、パスワード、任意のコマンド実行はできない。",
            "I can take screenshots, open common folders, switch or arrange windows, show the desktop, open Task View, copy text you specify, and search in your browser. I can also report battery, memory, system-drive, and network status; deletion, shutdown, passwords, and arbitrary shell commands stay blocked.");
        return true;
    }

    private static bool TryReportSystemStatus(string text, out string reply)
    {
        reply = string.Empty;
        if (Regex.IsMatch(text, "(電池|电池|電量|电量|battery|バッテリー).{0,12}(多少|幾|几|剩|狀態|状态|status|level|残|ある)|((多少|幾|几|剩).{0,8}(電量|电量|battery))", RegexOptions.IgnoreCase))
        {
            if (!GetSystemPowerStatus(out var power) || power.BatteryLifePercent == 255)
            {
                reply = ApiKeyText("這台電腦沒有回報可用的電池資訊。", "这台电脑没有报告可用的电池信息。", "このPCからバッテリー情報を取得できなかったよ。", "This PC did not report usable battery information.");
            }
            else
            {
                var charging = power.ACLineStatus == 1;
                reply = ApiKeyText(
                    $"目前電量是 {power.BatteryLifePercent}%{(charging ? "，正在接電" : "")}。",
                    $"目前电量是 {power.BatteryLifePercent}%{(charging ? "，正在接电" : "")}。",
                    $"バッテリーは {power.BatteryLifePercent}%{(charging ? "、電源に接続中" : "")}だよ。",
                    $"The battery is at {power.BatteryLifePercent}%{(charging ? " and connected to power" : "")}.");
            }
            return true;
        }

        if (Regex.IsMatch(text, "((系統|系统|電腦|电脑|PC).{0,5}(記憶體|内存|memory|RAM|メモリ)|(記憶體|内存|memory|RAM|メモリ).{0,8}(使用|剩|狀態|状态|usage|status|空き))", RegexOptions.IgnoreCase))
        {
            var memory = new MemoryStatusEx { Length = (uint)Marshal.SizeOf<MemoryStatusEx>() };
            if (!GlobalMemoryStatusEx(ref memory))
                reply = ApiKeyText("沒有讀到記憶體狀態。", "没有读取到内存状态。", "メモリの状態を取得できなかった。", "I could not read the memory status.");
            else
            {
                var total = FormatGiB(memory.TotalPhysical);
                var available = FormatGiB(memory.AvailablePhysical);
                reply = ApiKeyText(
                    $"記憶體使用率約 {memory.MemoryLoad}%，可用 {available} GB，共 {total} GB。",
                    $"内存使用率约 {memory.MemoryLoad}%，可用 {available} GB，共 {total} GB。",
                    $"メモリ使用率は約 {memory.MemoryLoad}%、空きは {available} GB、合計 {total} GBだよ。",
                    $"Memory usage is about {memory.MemoryLoad}%; {available} GB is available out of {total} GB.");
            }
            return true;
        }

        if (Regex.IsMatch(text, "((系統|系统|C槽|C盘|磁碟|磁盘|硬碟|硬盘|disk|storage|ストレージ).{0,10}(空間|空间|剩|可用|free|available|空き))", RegexOptions.IgnoreCase))
        {
            try
            {
                var root = Path.GetPathRoot(Environment.SystemDirectory) ?? "C:\\";
                var drive = new DriveInfo(root);
                reply = ApiKeyText(
                    $"系統磁碟還有 {FormatGiB((ulong)drive.AvailableFreeSpace)} GB 可用，共 {FormatGiB((ulong)drive.TotalSize)} GB。",
                    $"系统磁盘还有 {FormatGiB((ulong)drive.AvailableFreeSpace)} GB 可用，共 {FormatGiB((ulong)drive.TotalSize)} GB。",
                    $"システムドライブの空きは {FormatGiB((ulong)drive.AvailableFreeSpace)} GB、合計 {FormatGiB((ulong)drive.TotalSize)} GBだよ。",
                    $"The system drive has {FormatGiB((ulong)drive.AvailableFreeSpace)} GB free out of {FormatGiB((ulong)drive.TotalSize)} GB.");
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogWarning($"Could not inspect the system drive: {exception.Message}");
                reply = ApiKeyText("沒有讀到系統磁碟狀態。", "没有读取到系统磁盘状态。", "システムドライブの状態を取得できなかった。", "I could not read the system-drive status.");
            }
            return true;
        }

        if (Regex.IsMatch(text, "((網路|网络|internet|network|インターネット|ネット).{0,10}(連線|连接|狀態|状态|通|connected|status|つなが|接続))", RegexOptions.IgnoreCase))
        {
            var available = System.Net.NetworkInformation.NetworkInterface.GetIsNetworkAvailable();
            reply = available
                ? ApiKeyText("本機目前有可用的網路連線。", "本机目前有可用的网络连接。", "今は利用できるネット接続があるよ。", "A network connection is currently available.")
                : ApiKeyText("本機目前沒有偵測到可用的網路連線。", "本机目前没有检测到可用的网络连接。", "今は利用できるネット接続が見つからない。", "No available network connection is currently detected.");
            return true;
        }
        return false;
    }

    private static string FormatGiB(ulong bytes)
        => (bytes / 1073741824d).ToString("0.0", CultureInfo.InvariantCulture);

    private static bool TryOpenKnownFolder(string text, out string reply)
    {
        reply = string.Empty;
        var hasOpenVerb = Regex.IsMatch(text, "(打開|打开|開啟|开启|幫我開|帮我开|open|show|開いて|開く)", RegexOptions.IgnoreCase);
        if (!hasOpenVerb)
            return false;

        string? path = null;
        string name = string.Empty;
        if (Regex.IsMatch(text, "(截圖|截图|screenshot|スクリーンショット).{0,5}(資料夾|文件夹|folder|フォルダ)", RegexOptions.IgnoreCase))
        {
            path = Path.Combine(GetPicturesDirectory(), "Lilith Screenshots");
            Directory.CreateDirectory(path);
            name = ApiKeyText("截圖資料夾", "截图文件夹", "スクリーンショットフォルダー", "Screenshots folder");
        }
        else if (Regex.IsMatch(text, "(下載|下载|downloads?|ダウンロード)", RegexOptions.IgnoreCase))
        {
            path = GetDownloadsDirectory();
            name = ApiKeyText("下載資料夾", "下载文件夹", "ダウンロードフォルダー", "Downloads folder");
        }
        else if (Regex.IsMatch(text, "(桌面|desktop|デスクトップ)", RegexOptions.IgnoreCase))
        {
            path = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
            name = ApiKeyText("桌面資料夾", "桌面文件夹", "デスクトップフォルダー", "Desktop folder");
        }
        else if (Regex.IsMatch(text, "(文件(?:資料夾|文件夹)|文檔|文档|documents?|ドキュメント)", RegexOptions.IgnoreCase))
        {
            path = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
            name = ApiKeyText("文件資料夾", "文档文件夹", "ドキュメントフォルダー", "Documents folder");
        }
        else if (Regex.IsMatch(text, "(圖片|图片|照片|pictures?|photos?|ピクチャ|写真).{0,5}(資料夾|文件夹|folder|フォルダ)?", RegexOptions.IgnoreCase))
        {
            path = GetPicturesDirectory();
            name = ApiKeyText("圖片資料夾", "图片文件夹", "ピクチャフォルダー", "Pictures folder");
        }
        else if (Regex.IsMatch(text, "(音樂|音乐|music|ミュージック).{0,5}(資料夾|文件夹|folder|フォルダ)?", RegexOptions.IgnoreCase))
        {
            path = Environment.GetFolderPath(Environment.SpecialFolder.MyMusic);
            name = ApiKeyText("音樂資料夾", "音乐文件夹", "ミュージックフォルダー", "Music folder");
        }
        else if (Regex.IsMatch(text, "(影片|視頻|视频|videos?|ビデオ).{0,5}(資料夾|文件夹|folder|フォルダ)?", RegexOptions.IgnoreCase))
        {
            path = Environment.GetFolderPath(Environment.SpecialFolder.MyVideos);
            name = ApiKeyText("影片資料夾", "视频文件夹", "ビデオフォルダー", "Videos folder");
        }
        else if (Regex.IsMatch(text, "(MOD|模組|模组).{0,5}(資料夾|文件夹|folder|フォルダ)", RegexOptions.IgnoreCase))
        {
            path = MemoryDirectory;
            Directory.CreateDirectory(path);
            name = ApiKeyText("MOD 資料夾", "MOD 文件夹", "MODフォルダー", "MOD folder");
        }
        else if (Regex.IsMatch(text, "(資源回收筒|回收站|recycle bin|ごみ箱)", RegexOptions.IgnoreCase))
        {
            path = "shell:RecycleBinFolder";
            name = ApiKeyText("資源回收筒", "回收站", "ごみ箱", "Recycle Bin");
        }
        if (path == null)
            return false;
        if (!EnsureAdvancedComputerActions(out reply))
            return true;

        try
        {
            Process.Start(new ProcessStartInfo("explorer.exe")
            {
                Arguments = path.StartsWith("shell:", StringComparison.OrdinalIgnoreCase) ? path : $"\"{path}\"",
                UseShellExecute = true
            });
            reply = ApiKeyText($"好，替你打開{name}。", $"好，替你打开{name}。", $"うん、{name}を開くね。", $"Okay, I'll open the {name}.");
            Plugin.PluginLog.LogInfo($"Opened allowlisted known folder '{name}'.");
        }
        catch (Exception exception)
        {
            reply = ApiKeyText($"{name}沒有成功打開。", $"{name}没有成功打开。", $"{name}を開けなかった……", $"I couldn't open the {name}.");
            Plugin.PluginLog.LogWarning($"Could not open known folder '{name}': {exception.Message}");
        }
        return true;
    }

    private static string GetPicturesDirectory()
    {
        var pictures = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures);
        return string.IsNullOrWhiteSpace(pictures)
            ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Pictures")
            : pictures;
    }

    private static string GetDownloadsDirectory()
    {
        if (!OperatingSystem.IsWindows())
            return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads");
        try
        {
            using var key = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders");
            var configured = key?.GetValue("{374DE290-123F-4565-9164-39C4925E467B}") as string;
            if (!string.IsNullOrWhiteSpace(configured))
                return Environment.ExpandEnvironmentVariables(configured);
        }
        catch { }
        return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads");
    }

    private static bool TryHandleWindowCommand(string text, out string reply)
    {
        reply = string.Empty;
        string action;
        if (Regex.IsMatch(text, "(顯示桌面|显示桌面|show (?:the )?desktop|デスクトップを表示)", RegexOptions.IgnoreCase))
            action = "desktop";
        else if (Regex.IsMatch(text, "(工作檢視|任务视图|task view|タスクビュー)", RegexOptions.IgnoreCase))
            action = "taskview";
        else if (Regex.IsMatch(text, "(切換|切换|換到|换到|switch).{0,8}(視窗|窗口|window)|(上一個|上一个|前一個|前一个).{0,5}(視窗|窗口|window)|ウィンドウ.{0,4}(切り替|切替)", RegexOptions.IgnoreCase))
            action = "switch";
        else if (Regex.IsMatch(text, "((最小化).{0,5}(視窗|窗口)|(視窗|窗口).{0,5}最小化|minimi[sz]e (?:the )?window|ウィンドウ.{0,5}最小化)", RegexOptions.IgnoreCase))
            action = "minimize";
        else if (Regex.IsMatch(text, "((最大化).{0,5}(視窗|窗口)|(視窗|窗口).{0,5}最大化|maximi[sz]e (?:the )?window|ウィンドウ.{0,5}最大化)", RegexOptions.IgnoreCase))
            action = "maximize";
        else if (Regex.IsMatch(text, "((還原|恢复).{0,5}(視窗|窗口)|(視窗|窗口).{0,5}(還原|恢复)|restore (?:the )?window|ウィンドウ.{0,5}元に戻)", RegexOptions.IgnoreCase))
            action = "restore";
        else if (Regex.IsMatch(text, "(視窗|窗口|window).{0,8}(左邊|左側|左半|left|左に)|(貼|贴|snap).{0,5}(左邊|左側|left)", RegexOptions.IgnoreCase))
            action = "left";
        else if (Regex.IsMatch(text, "(視窗|窗口|window).{0,8}(右邊|右側|右半|right|右に)|(貼|贴|snap).{0,5}(右邊|右側|right)", RegexOptions.IgnoreCase))
            action = "right";
        else
            return false;

        if (!EnsureAdvancedComputerActions(out reply))
            return true;
        try
        {
            switch (action)
            {
                case "desktop":
                    SendShortcut(0x5B, 0x44);
                    reply = ApiKeyText("好，顯示桌面。", "好，显示桌面。", "うん、デスクトップを表示するね。", "Okay, showing the desktop.");
                    break;
                case "taskview":
                    SendShortcut(0x5B, 0x09);
                    reply = ApiKeyText("工作檢視打開了。", "任务视图打开了。", "タスクビューを開いたよ。", "Task View is open.");
                    break;
                case "switch":
                    SendShortcut(0x12, 0x09);
                    reply = ApiKeyText("替你切到上一個視窗。", "替你切到上一个窗口。", "前のウィンドウに切り替えたよ。", "I switched to the previous window.");
                    break;
                default:
                    var target = GetControllableWindow();
                    if (target == IntPtr.Zero)
                        throw new InvalidOperationException("No external foreground window is available.");
                    if (action == "minimize")
                    {
                        ShowWindow(target, 6);
                        reply = ApiKeyText("把剛才的視窗最小化了。", "把刚才的窗口最小化了。", "さっきのウィンドウを最小化したよ。", "I minimized the previous window.");
                    }
                    else if (action == "maximize")
                    {
                        ShowWindow(target, 3);
                        reply = ApiKeyText("把剛才的視窗最大化了。", "把刚才的窗口最大化了。", "さっきのウィンドウを最大化したよ。", "I maximized the previous window.");
                    }
                    else if (action == "restore")
                    {
                        ShowWindow(target, 9);
                        reply = ApiKeyText("視窗已經還原。", "窗口已经恢复。", "ウィンドウを元に戻したよ。", "I restored the window.");
                    }
                    else
                    {
                        ShowWindow(target, 9);
                        if (!SetForegroundWindow(target))
                            throw new InvalidOperationException("The target window could not be activated.");
                        SendShortcut(0x5B, action == "left" ? (byte)0x25 : (byte)0x27);
                        reply = action == "left"
                            ? ApiKeyText("把剛才的視窗排到左側了。", "把刚才的窗口排到左侧了。", "さっきのウィンドウを左側に並べたよ。", "I snapped the previous window to the left.")
                            : ApiKeyText("把剛才的視窗排到右側了。", "把刚才的窗口排到右侧了。", "さっきのウィンドウを右側に並べたよ。", "I snapped the previous window to the right.");
                    }
                    break;
            }
            Plugin.PluginLog.LogInfo($"Executed allowlisted window action '{action}'.");
        }
        catch (Exception exception)
        {
            reply = ApiKeyText("這次沒有找到能操作的視窗。", "这次没有找到能操作的窗口。", "今回は操作できるウィンドウが見つからなかった。", "I couldn't find a window to control this time.");
            Plugin.PluginLog.LogWarning($"Could not execute window action '{action}': {exception.Message}");
        }
        return true;
    }

    private static bool TryWriteClipboard(string text, out string reply)
    {
        reply = string.Empty;
        if (!Regex.IsMatch(text, "(複製|复制|copy|コピー)", RegexOptions.IgnoreCase))
            return false;
        if (Regex.IsMatch(text, "(檔案|文件|資料夾|文件夹|file|folder|フォルダ)", RegexOptions.IgnoreCase)
            && !Regex.IsMatch(text, "[「『\"']", RegexOptions.IgnoreCase))
            return false;

        string content = string.Empty;
        var quoted = Regex.Match(text, "[「『\"'](?<value>.+?)[」』\"']", RegexOptions.Singleline);
        if (quoted.Success)
            content = quoted.Groups["value"].Value;
        else
        {
            var chinese = Regex.Match(text, "(?:幫我|帮我|請|请)?(?:複製|复制)(?:這段|这段|文字|內容|内容)?[：:\\s]+(?<value>.+)$", RegexOptions.IgnoreCase | RegexOptions.Singleline);
            var english = Regex.Match(text, "copy\\s+(?<value>.+?)(?:\\s+to\\s+(?:the\\s+)?clipboard)?$", RegexOptions.IgnoreCase | RegexOptions.Singleline);
            var japanese = Regex.Match(text, "(?<value>.+?)(?:を)?コピー(?:して)?$", RegexOptions.IgnoreCase | RegexOptions.Singleline);
            var match = chinese.Success ? chinese : english.Success ? english : japanese;
            if (match.Success)
                content = match.Groups["value"].Value.Trim();
        }
        if (string.IsNullOrWhiteSpace(content) || content.Length > 4000)
            return false;
        if (ContainsSensitiveNoteData(content))
        {
            reply = ApiKeyText("為了避免憑證外洩，我不會代為複製看起來像密碼、API Key 或驗證碼的內容。", "为了避免凭证泄露，我不会代为复制看起来像密码、API Key 或验证码的内容。", "認証情報の漏えいを避けるため、パスワード、APIキー、認証コードらしい内容はコピーしないよ。", "To avoid credential exposure, I won't copy text that looks like a password, API key, or verification code.");
            return true;
        }
        if (!EnsureAdvancedComputerActions(out reply))
            return true;

        GUIUtility.systemCopyBuffer = content;
        reply = ApiKeyText("已經替你複製到剪貼簿了。", "已经替你复制到剪贴板了。", "クリップボードにコピーしたよ。", "I copied it to the clipboard.");
        Plugin.PluginLog.LogInfo($"Copied player-specified text to the clipboard ({content.Length} chars; content hidden from log).");
        return true;
    }

    private static bool TryOpenBrowserSearch(string text, out string reply)
    {
        reply = string.Empty;
        Match match;
        if ((match = Regex.Match(text, "(?:用|在)?(?:瀏覽器|浏览器|Google|谷歌).{0,5}(?:搜尋|搜索|查詢|查询)[：:\\s]*(?<query>.+)$", RegexOptions.IgnoreCase)).Success
            || (match = Regex.Match(text, "(?:search|google)(?:\\s+the\\s+web)?(?:\\s+for)?\\s+(?<query>.+)$", RegexOptions.IgnoreCase)).Success
            || (match = Regex.Match(text, "(?:ブラウザ|Google).{0,5}(?:で)?(?:検索|調べ)[：:\\s]*(?<query>.+)$", RegexOptions.IgnoreCase)).Success)
        {
            var query = match.Groups["query"].Value.Trim(' ', '。', '.', '？', '?', '！', '!');
            if (query.Length == 0 || query.Length > 500)
                return false;
            if (!EnsureAdvancedComputerActions(out reply))
                return true;
            try
            {
                var url = "https://www.google.com/search?q=" + Uri.EscapeDataString(query);
                Process.Start(new ProcessStartInfo(url) { UseShellExecute = true });
                reply = ApiKeyText("好，已經在瀏覽器搜尋了。", "好，已经在浏览器搜索了。", "うん、ブラウザで検索したよ。", "Okay, I searched for it in your browser.");
                Plugin.PluginLog.LogInfo($"Opened an explicit browser search ({query.Length} chars; query hidden from log).");
            }
            catch (Exception exception)
            {
                reply = ApiKeyText("瀏覽器沒有成功打開。", "浏览器没有成功打开。", "ブラウザを開けなかった……", "I couldn't open the browser.");
                Plugin.PluginLog.LogWarning($"Could not open browser search: {exception.Message}");
            }
            return true;
        }
        return false;
    }

    private static bool EnsureAdvancedComputerActions(out string reply)
    {
        if (FormalIntegrationStopBleedPolicy.Evaluate(
                Plugin.FormalIntegrationActive,
                Plugin.AdvancedComputerActionsEnabled.Value)
            .DesktopToolsEffective)
        {
            reply = string.Empty;
            return true;
        }
        reply = ApiKeyText(
            "要先在設定中打開「進階電腦操作」，我才能執行這個動作。",
            "要先在设置中打开“高级电脑操作”，我才能执行这个动作。",
            "先に設定で「高度なPC操作」を有効にしてね。",
            "Enable “Advanced PC controls” in Settings before I perform that action.");
        return false;
    }

    private static bool TryHandleMediaCommand(string text, out string reply)
    {
        reply = string.Empty;
        if (Regex.IsMatch(text, "(不要|別|别|しないで|don't|do not)", RegexOptions.IgnoreCase))
            return false;

        byte key;
        string traditional;
        string simplified;
        string japanese;
        string english;
        if (Regex.IsMatch(text, "(下一首|下一曲|下一個|下一个|切下一首|次の曲|次へ|next song|next track)", RegexOptions.IgnoreCase))
        {
            key = 0xB0;
            traditional = "好，換到下一首。"; simplified = "好，换到下一首。"; japanese = "うん、次の曲にするね。"; english = "Okay, next track.";
        }
        else if (Regex.IsMatch(text, "(上一首|上一曲|上一個|上一个|切上一首|前の曲|前へ|previous song|previous track)", RegexOptions.IgnoreCase))
        {
            key = 0xB1;
            traditional = "好，回到上一首。"; simplified = "好，回到上一首。"; japanese = "うん、前の曲に戻すね。"; english = "Okay, previous track.";
        }
        else if (Regex.IsMatch(text, "(停止音樂|停止音乐|停止播放|音樂停掉|音乐停掉|再生停止|stop music|stop playback)", RegexOptions.IgnoreCase))
        {
            key = 0xB2;
            traditional = "音樂停下來了。"; simplified = "音乐停下来了。"; japanese = "音楽を止めたよ。"; english = "I stopped the music.";
        }
        else if (Regex.IsMatch(text, "(暫停音樂|暂停音乐|暫停播放|暂停播放|音樂暫停|音乐暂停|先停一下|一時停止|pause music|pause playback)", RegexOptions.IgnoreCase))
        {
            key = 0xB3;
            traditional = "嗯，先暫停一下。"; simplified = "嗯，先暂停一下。"; japanese = "うん、いったん止めるね。"; english = "Okay, paused for now.";
        }
        else if (Regex.IsMatch(text, "(繼續播放|继续播放|繼續音樂|继续音乐|恢復播放|恢复播放|接著播|接着播|再生して|resume music|resume playback|play music)", RegexOptions.IgnoreCase))
        {
            key = 0xB3;
            traditional = "好，繼續播放。"; simplified = "好，继续播放。"; japanese = "うん、続きを再生するね。"; english = "Okay, resuming playback.";
        }
        else if (Regex.IsMatch(text, "(靜音|静音|關掉聲音|关掉声音|ミュート|mute)", RegexOptions.IgnoreCase))
        {
            key = 0xAD;
            traditional = "好，靜音了。"; simplified = "好，静音了。"; japanese = "ミュートにしたよ。"; english = "Muted.";
        }
        else if (Regex.IsMatch(text, "(音量大一點|音量大一点|提高音量|調大聲|调大声|音量上げ|volume up|louder)", RegexOptions.IgnoreCase))
        {
            key = 0xAF;
            traditional = "音量調高一點了。"; simplified = "音量调高一点了。"; japanese = "少し音量を上げたよ。"; english = "I turned it up a little.";
        }
        else if (Regex.IsMatch(text, "(音量小一點|音量小一点|降低音量|調小聲|调小声|音量下げ|volume down|quieter)", RegexOptions.IgnoreCase))
        {
            key = 0xAE;
            traditional = "音量調低一點了。"; simplified = "音量调低一点了。"; japanese = "少し音量を下げたよ。"; english = "I turned it down a little.";
        }
        else
        {
            return false;
        }

        try
        {
            SendVirtualKey(key);
            reply = ApiKeyText(traditional, simplified, japanese, english);
            Plugin.PluginLog.LogInfo($"Sent allowlisted Windows media key 0x{key:X2}.");
        }
        catch (Exception exception)
        {
            reply = ApiKeyText("媒體控制沒有成功。", "媒体控制没有成功。", "メディア操作がうまくいかなかった……", "The media control did not work.");
            Plugin.PluginLog.LogWarning($"Could not send Windows media key: {exception.Message}");
        }
        return true;
    }

    private static bool TryLaunchApplicationCommand(string text, out string reply)
    {
        reply = string.Empty;
        if (Regex.IsMatch(text, "(不要|別|别|不可|禁止|しないで|開かないで|don't|do not)", RegexOptions.IgnoreCase))
            return false;
        var configured = FindConfiguredApplication(text);
        var official = FindOfficialApplication(text);
        var mentionsBuiltIn = Regex.IsMatch(text,
            "(記事本|记事本|メモ帳|notepad|計算機|计算器|電卓|calculator|calc|檔案總管|文件资源管理器|資源管理器|エクスプローラー|file explorer|explorer|瀏覽器|浏览器|ブラウザ|browser|chrome|edge|steam|蒸汽平台|スチーム)",
            RegexOptions.IgnoreCase);
        var explicitLaunch = Regex.IsMatch(text,
            "(開啟|开启|打開|打开|啟動|启动|幫我開|帮我开|開いて|起動して|open|launch|start)", RegexOptions.IgnoreCase);
        var likelyMisheardLaunch = text.Length <= 32
            && (configured != null || official != null || mentionsBuiltIn)
            && Regex.IsMatch(text, "(撥給|拨给|播給|播给|包我|幫我|帮我|幫忙|帮忙|給我|给我|我要你|麻煩|麻烦)", RegexOptions.IgnoreCase)
            && !Regex.IsMatch(text, "(什麼|什么|介紹|介绍|查詢|查询|搜尋|搜索|攻略|怎麼|怎么|為什麼|为什么|what|why|how)", RegexOptions.IgnoreCase);
        if (!explicitLaunch && !likelyMisheardLaunch)
            return false;

        if (likelyMisheardLaunch && !explicitLaunch)
            Plugin.PluginLog.LogInfo("Recovered a likely speech-recognition error as an allowlisted launch command.");

        string? target;
        string? arguments;
        string appName;
        if (configured != null)
        {
            target = configured.Target;
            arguments = configured.Arguments;
            appName = configured.Name;
        }
        else if (official != null)
        {
            target = official.Target;
            arguments = official.Arguments;
            appName = official.Name;
        }
        else if (Regex.IsMatch(text, "(記事本|记事本|メモ帳|notepad)", RegexOptions.IgnoreCase))
        {
            target = "notepad.exe";
            arguments = string.Empty;
            appName = ApiKeyText("記事本", "记事本", "メモ帳", "Notepad");
        }
        else if (Regex.IsMatch(text, "(計算機|计算器|電卓|calculator|calc)", RegexOptions.IgnoreCase))
        {
            target = "calc.exe";
            arguments = string.Empty;
            appName = ApiKeyText("計算機", "计算器", "電卓", "Calculator");
        }
        else if (Regex.IsMatch(text, "(檔案總管|文件资源管理器|資源管理器|エクスプローラー|file explorer|explorer)", RegexOptions.IgnoreCase))
        {
            target = "explorer.exe";
            arguments = string.Empty;
            appName = ApiKeyText("檔案總管", "文件资源管理器", "エクスプローラー", "File Explorer");
        }
        else if (Regex.IsMatch(text, "(瀏覽器|浏览器|ブラウザ|browser|chrome|edge)", RegexOptions.IgnoreCase))
        {
            target = "https://www.google.com/";
            arguments = string.Empty;
            appName = ApiKeyText("瀏覽器", "浏览器", "ブラウザ", "browser");
        }
        else if (Regex.IsMatch(text, "(steam|蒸汽平台|スチーム)", RegexOptions.IgnoreCase))
        {
            target = "steam://open/main";
            arguments = string.Empty;
            appName = "Steam";
        }
        else
        {
            var requestedName = ExtractRequestedApplicationName(text);
            if (string.IsNullOrWhiteSpace(requestedName))
                return false;
            appName = requestedName;
            if (TryFocusRunningApplication(requestedName))
            {
                reply = ApiKeyText($"好，已切換到{appName}。", $"好，已切换到{appName}。", $"うん、{appName}に切り替えたよ。", $"Sure, I focused {appName}.");
                Plugin.PluginLog.LogInfo($"Focused installed application requested through the local router: '{requestedName}'.");
                return true;
            }
            var startApplication = ResolveWindowsStartApplication(requestedName);
            if (startApplication != null && TryLaunchWindowsStartApplication(startApplication))
            {
                reply = ApiKeyText($"好，正在開啟{startApplication.Name}。", $"好，正在打开{startApplication.Name}。", $"うん、{startApplication.Name}を開くね。", $"Sure, I'm opening {startApplication.Name}.");
                return true;
            }
            var shortcut = ResolveWindowsShortcut(new[] { requestedName }) ?? ResolveFuzzyWindowsShortcut(requestedName);
            if (string.IsNullOrWhiteSpace(shortcut))
                return false;
            target = shortcut;
            arguments = string.Empty;
            appName = Path.GetFileNameWithoutExtension(shortcut);
        }

        try
        {
            Process.Start(new ProcessStartInfo(target)
            {
                Arguments = arguments ?? string.Empty,
                UseShellExecute = true
            });
            reply = ApiKeyText($"好，幫你開啟{appName}。", $"好，帮你打开{appName}。", $"うん、{appName}を開くね。", $"Sure, I'll open {appName}.");
            Plugin.PluginLog.LogInfo($"Launched allowlisted application target '{target}'.");
        }
        catch (Exception exception)
        {
            reply = ApiKeyText($"{appName}沒有成功開啟。", $"{appName}没有成功打开。", $"{appName}を開けなかった……", $"I couldn't open {appName}.");
            Plugin.PluginLog.LogWarning($"Could not launch allowlisted target '{target}': {exception.Message}");
        }
        return true;
    }

    private static string ExtractRequestedApplicationName(string text)
    {
        if (string.IsNullOrWhiteSpace(text) || text.Length > 160)
            return string.Empty;

        var suffixPattern = "(?:幫我開|帮我开|替我開|替我开|開啟|开启|打開|打开|啟動|启动|撥給|拨给|播給|播给|open|launch|start)\\s*(?<name>[^,，。！？!?;；]{1,80})";
        var suffixMatches = Regex.Matches(text, suffixPattern, RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (suffixMatches.Count > 0)
        {
            var name = suffixMatches[suffixMatches.Count - 1].Groups["name"].Value;
            name = Regex.Replace(name, "(?:一下|看看|好嗎|好吗|可以嗎|可以吗|拜託|拜托|please|for me|吧|嗎|吗|呢)\\s*$", string.Empty, RegexOptions.IgnoreCase).Trim();
            name = Regex.Replace(name, "^(?:應用程式|应用程序|app|application)\\s*", string.Empty, RegexOptions.IgnoreCase).Trim();
            return IsSafeApplicationDisplayName(name) ? name : string.Empty;
        }

        var japanese = Regex.Match(text, "(?<name>[^,，。！？!?;；]{1,80}?)(?:を)?(?:開いて|起動して|立ち上げて)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
        if (japanese.Success)
        {
            var name = Regex.Replace(japanese.Groups["name"].Value, "^(?:ねえ|お願い|ちょっと)\\s*", string.Empty).Trim();
            return IsSafeApplicationDisplayName(name) ? name : string.Empty;
        }
        return string.Empty;
    }

    private static bool IsSafeApplicationDisplayName(string name)
        => name.Length is >= 2 and <= 80
            && !Regex.IsMatch(name, "[\\\\/:*?\"<>|`$]");

    internal static void EnsureApplicationLauncherFile()
    {
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(ApplicationLauncherPath) ?? PlayerDataRootDirectory);
            if (File.Exists(ApplicationLauncherPath))
                return;
            var defaults = new[]
            {
                new ApplicationLauncher { Name = "記事本", Target = "notepad.exe", Aliases = new[] { "記事本", "记事本", "メモ帳", "notepad" } },
                new ApplicationLauncher { Name = "計算機", Target = "calc.exe", Aliases = new[] { "計算機", "计算器", "電卓", "calculator", "calc" } },
                new ApplicationLauncher { Name = "檔案總管", Target = "explorer.exe", Aliases = new[] { "檔案總管", "文件资源管理器", "資源管理器", "エクスプローラー", "file explorer", "explorer" } },
                new ApplicationLauncher { Name = "瀏覽器", Target = "https://www.google.com/", Aliases = new[] { "瀏覽器", "浏览器", "ブラウザ", "browser", "chrome", "edge" } },
                new ApplicationLauncher { Name = "Steam", Target = "steam://open/main", Aliases = new[] { "Steam", "蒸汽平台", "スチーム" } }
            };
            File.WriteAllText(ApplicationLauncherPath,
                JsonSerializer.Serialize(defaults, new JsonSerializerOptions
                {
                    WriteIndented = true,
                    Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
                }), Encoding.UTF8);
            Plugin.PluginLog.LogInfo($"Created editable application launcher list at {ApplicationLauncherPath}.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not create application launcher list: {exception.Message}");
        }
    }

    private static ApplicationLauncher? FindConfiguredApplication(string text)
    {
        try
        {
            EnsureApplicationLauncherFile();
            var launchers = JsonSerializer.Deserialize<ApplicationLauncher[]>(File.ReadAllText(ApplicationLauncherPath),
                new JsonSerializerOptions { PropertyNameCaseInsensitive = true }) ?? Array.Empty<ApplicationLauncher>();
            foreach (var launcher in launchers)
            {
                if (string.IsNullOrWhiteSpace(launcher.Name) || string.IsNullOrWhiteSpace(launcher.Target))
                    continue;
                var aliases = launcher.Aliases == null || launcher.Aliases.Length == 0
                    ? new[] { launcher.Name }
                    : launcher.Aliases;
                if (aliases.Any(alias => !string.IsNullOrWhiteSpace(alias)
                    && text.IndexOf(alias, StringComparison.OrdinalIgnoreCase) >= 0))
                    return launcher;
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not read application launcher list: {exception.Message}");
        }
        return null;
    }

    private static ApplicationLauncher? FindOfficialApplication(string text)
    {
        if (FindOfficialGame(text) is { } game)
            return game;
        if (Regex.IsMatch(text, "(Spotify|スポティファイ|Spotify 音樂|Spotify 音乐)", RegexOptions.IgnoreCase))
        {
            var shortcut = ResolveWindowsShortcut(new[] { "Spotify" });
            return new ApplicationLauncher { Name = "Spotify", Target = shortcut ?? "spotify:" };
        }

        var applications = new[]
        {
            new OfficialApplication("VS Code", "Code.exe", new[] { "VS Code", "Visual Studio Code", "視覺化工作室程式碼", "代码编辑器", "コード", "ブイエスコード" }),
            new OfficialApplication("Visual Studio", "devenv.exe", new[] { "Visual Studio", "視覺工作室", "视觉工作室", "ビジュアルスタジオ" }),
            new OfficialApplication("Rider", "rider64.exe", new[] { "Rider", "JetBrains Rider", "ライダー" }),
            new OfficialApplication("IntelliJ IDEA", "idea64.exe", new[] { "IntelliJ", "IntelliJ IDEA", "IDEA", "インテリジェイ" }),
            new OfficialApplication("PyCharm", "pycharm64.exe", new[] { "PyCharm", "派洽姆", "パイチャーム" }),
            new OfficialApplication("WebStorm", "webstorm64.exe", new[] { "WebStorm", "ウェブストーム" }),
            new OfficialApplication("CLion", "clion64.exe", new[] { "CLion", "シーライオン" }),
            new OfficialApplication("Cursor", "Cursor.exe", new[] { "Cursor", "游標編輯器", "光标编辑器", "カーソル" }),
            new OfficialApplication("Sublime Text", "sublime_text.exe", new[] { "Sublime", "Sublime Text", "サブライム" }),
            new OfficialApplication("Notepad++", "notepad++.exe", new[] { "Notepad++", "Notepad Plus Plus", "記事本++", "记事本++", "ノートパッドプラスプラス" }),
            new OfficialApplication("VLC", "vlc.exe", new[] { "VLC", "VLC 播放器", "VLC プレイヤー" }),
            new OfficialApplication("PotPlayer", "PotPlayerMini64.exe", new[] { "PotPlayer", "Pot Player", "影音播放器", "ポットプレイヤー" }, "PotPlayerMini.exe"),
            new OfficialApplication("MPV", "mpv.exe", new[] { "MPV", "MPV 播放器", "MPV プレイヤー" }),
            new OfficialApplication("MPC-HC", "mpc-hc64.exe", new[] { "MPC-HC", "Media Player Classic", "メディアプレイヤークラシック" }, "mpc-hc.exe"),
            new OfficialApplication("Windows Media Player", "wmplayer.exe", new[] { "Windows Media Player", "Windows 媒體播放器", "Windows 媒体播放器", "ウィンドウズメディアプレイヤー" })
        };

        foreach (var application in applications)
        {
            if (!application.Aliases.Any(alias => text.IndexOf(alias, StringComparison.OrdinalIgnoreCase) >= 0))
                continue;
            foreach (var executable in application.Executables)
            {
                var resolved = ResolveRegisteredExecutable(executable);
                if (!string.IsNullOrWhiteSpace(resolved))
                    return new ApplicationLauncher { Name = application.Name, Target = resolved };
            }
            Plugin.PluginLog.LogWarning($"Official application '{application.Name}' was requested but is not installed or registered with Windows.");
            return new ApplicationLauncher { Name = application.Name, Target = application.Executables[0] };
        }
        return null;
    }

