        public string Target { get; set; } = string.Empty;
        public string Arguments { get; set; } = string.Empty;
        public string[] Aliases { get; set; } = Array.Empty<string>();
    }

    private sealed class WindowsStartApplication
    {
        public string Name { get; set; } = string.Empty;
        public string AppId { get; set; } = string.Empty;
    }

    private static void RefreshD046GameControlProjection()
    {
        TryCommitD046GameControlProjection();
        if (Time.unscaledTime < _d046GameControlNextRefreshAt)
            return;

        _d046GameControlNextRefreshAt =
            Time.unscaledTime + D046GameControlRefreshIntervalSeconds;
        RefreshOfficialVoiceSynchronization();
        var desired = LoadD046DesiredGameControls();
        D046GameControlProjection.Offer(desired);
        TryCommitD046GameControlProjection();
    }

    private static void RefreshOfficialVoiceSynchronization()
    {
        // Called only from the Unity main-thread update. Worker TTS code reads
        // the published enum, never Unity/IL2CPP objects or official settings.
        try
        {
            _d046GameControlStore ??= D046GameControlPreferencesStore.ForCurrentUser();
            var outcome = OfficialVoiceSync.Refresh(
                ReadOfficialVoiceLanguage(), _d046GameControlStore.Load(),
                ApplyOfficialVoiceLanguage,
                (revision, voice) => _d046GameControlStore.TryMirrorOfficialVoice(
                    revision, voice, DateTimeOffset.UtcNow));
            if (OfficialVoiceSync.EffectiveVoice is { } verified)
                Volatile.Write(ref _verifiedOfficialVoiceLanguage, (int)verified);
            if (outcome != _lastOfficialVoiceSyncOutcome)
            {
                Plugin.PluginLog.LogInfo(
                    $"Official voice synchronization: {outcome}; AI voice="
                    + (OfficialVoiceSync.EffectiveVoice?.ToString() ?? "fallback"));
                _lastOfficialVoiceSyncOutcome = outcome;
            }
        }
        catch (Exception exception)
        {
            if (_lastOfficialVoiceSyncOutcome != D046OfficialVoiceSyncOutcome.StoreUnavailable)
                Plugin.PluginLog.LogWarning("Official voice synchronization unavailable: "
                    + exception.GetType().Name);
            _lastOfficialVoiceSyncOutcome = D046OfficialVoiceSyncOutcome.StoreUnavailable;
        }
    }

    private static D046GameVoiceLanguage? ReadOfficialVoiceLanguage()
    {
        try
        {
            return LocalizationConfig.GetCurrentVoiceType() switch
            {
                UI.TraySetting.TraySettingChanged.GameLocalizationVoiceType.Japanese
                    => D046GameVoiceLanguage.Japanese,
                UI.TraySetting.TraySettingChanged.GameLocalizationVoiceType.ChineseSimplified
                    => D046GameVoiceLanguage.TraditionalChinese,
                _ => null
            };
        }
        catch (Exception) { return null; }
    }

    private static D046GameVoiceLanguage? ApplyOfficialVoiceLanguage(
        D046GameVoiceLanguage requested)
    {
        try
        {
            var official = requested switch
            {
                D046GameVoiceLanguage.Japanese
                    => UI.TraySetting.TraySettingChanged.GameLocalizationVoiceType.Japanese,
                D046GameVoiceLanguage.TraditionalChinese
                    => UI.TraySetting.TraySettingChanged.GameLocalizationVoiceType.ChineseSimplified,
                _ => throw new ArgumentOutOfRangeException(nameof(requested))
            };
            // Use the original settings model; no PlayerPrefs/registry/archive
            // writes and no recreated/forced voice-toggle UI or duplicate event.
            new UI.TraySetting.TraySettingModel().SaveGameVoice(official);
            return ReadOfficialVoiceLanguage();
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning("Official voice selection was not confirmed: "
                + exception.GetType().Name);
            return null;
        }
    }

    private static D046GameControlProjectionSnapshot
        LoadD046DesiredGameControls()
    {
        var legacy = CaptureD046LegacyGameControls();
        try
        {
            _d046GameControlStore ??=
                D046GameControlPreferencesStore.ForCurrentUser();
            var loaded = _d046GameControlStore.Load();
            if (loaded.Disposition
                == D046GameControlLoadDisposition.MissingDefaults)
            {
                // A missing portable profile gets only its initial F6 input
                // language from the current Windows UI culture. Legacy hotkeys
                // and the independent voice-output selection stay untouched.
                return RetainD046PortableOrLegacy(
                    legacy.WithSpeechInputLanguage(
                        loaded.Snapshot.SpeechInputLanguage));
            }
            if (!D046GameControlProjectionState.IsAuthoritativeLoad(
                    loaded.Disposition))
            {
                return RetainD046PortableOrLegacy(legacy);
            }

            var snapshot = loaded.Snapshot;
            if (!TryMapD046FunctionKey(snapshot.PushToTalkKey, out var pushToTalk)
                || !TryMapD046FunctionKey(snapshot.TextChatKey, out var textChat)
                || !TryMapD046FunctionKey(
                    snapshot.ConversationHistoryKey,
                    out var history)
                || !TryMapD046FunctionKey(snapshot.StopKey, out var stop))
            {
                return RetainD046PortableOrLegacy(legacy);
            }

            return new D046GameControlProjectionSnapshot(
                fromPortableStore: true,
                snapshot.Revision,
                (int)pushToTalk,
                (int)textChat,
                (int)history,
                (int)stop,
                snapshot.VoiceLanguage,
                snapshot.SpeechInputLanguage,
                snapshot.PushToTalkKey,
                snapshot.TextChatKey,
                snapshot.ConversationHistoryKey,
                snapshot.StopKey,
                proactiveDialogueEnabled:
                    snapshot.ProactiveDialogueEnabled);
        }
        catch (Exception exception) when (
            exception is IOException
                or UnauthorizedAccessException
                or InvalidOperationException
                or ArgumentException)
        {
            return RetainD046PortableOrLegacy(legacy);
        }
    }

    private static D046GameControlProjectionSnapshot
        RetainD046PortableOrLegacy(
            D046GameControlProjectionSnapshot legacy)
        => D046GameControlProjection.Effective is
            { FromPortableStore: true } portable
                ? portable
                : legacy;

    private static D046GameControlProjectionSnapshot
        CaptureD046LegacyGameControls()
        => new(
            fromPortableStore: false,
            revision: 0,
            (int)Plugin.VoiceInputKey.Value,
            (int)Plugin.TextInputKey.Value,
            (int)Plugin.ConversationHistoryKey.Value,
            (int)LegacyD046StopKey(),
            Plugin.JapaneseVoiceControlCenterSelected.Value
                ? D046GameVoiceLanguage.Japanese
                : D046GameVoiceLanguage.TraditionalChinese,
            D046GameControlPreferencesDocument.InitialSpeechInputLanguage(
                CultureInfo.CurrentUICulture));

    private static KeyCode LegacyD046StopKey()
    {
        var occupied = new HashSet<KeyCode>
        {
            Plugin.VoiceInputKey.Value,
            Plugin.TextInputKey.Value,
            Plugin.ConversationHistoryKey.Value
        };
        foreach (var candidate in new[]
                 {
                     KeyCode.F8,
                     KeyCode.F9,
                     KeyCode.F11,
                     KeyCode.F12
                 })
        {
            if (!occupied.Contains(candidate))
                return candidate;
        }

        return KeyCode.F8;
    }

    private static void TryCommitD046GameControlProjection()
    {
        var pending = D046GameControlProjection.Pending;
        if (pending == null)
            return;

        var heldKeyIds = new HashSet<int>();
        AddHeldD046GameControlKeys(
            D046GameControlProjection.Effective,
            heldKeyIds);
        AddHeldD046GameControlKeys(pending, heldKeyIds);
        var physical = new D046GameControlPhysicalSample(
            _microphoneRecording,
            heldKeyIds,
            IsKeyCurrentlyDown(KeyCode.LeftControl)
                || IsKeyCurrentlyDown(KeyCode.RightControl),
            IsKeyCurrentlyDown(KeyCode.LeftShift)
                || IsKeyCurrentlyDown(KeyCode.RightShift),
            IsKeyCurrentlyDown(KeyCode.LeftAlt)
                || IsKeyCurrentlyDown(KeyCode.RightAlt));
        if (D046GameControlProjection.TryCommit(physical)
            != D046GameControlProjectionCommit.Applied)
        {
            return;
        }

        TextInputHotkeyLatch.Reset();
        VoiceInputHotkeyLatch.Reset();
        ConversationHistoryHotkeyLatch.Reset();
        StopHotkeyLatch.Reset();
        var effective = D046GameControlProjection.Effective!;
        Plugin.PluginLog.LogInfo(
            "Applied one D-046 game-control revision from "
            + (effective.FromPortableStore ? "Control Center" : "legacy config")
            + $": revision={effective.Revision}, push-to-talk={(KeyCode)effective.PushToTalkKeyId}, "
            + $"text={(KeyCode)effective.TextChatKeyId}, history={(KeyCode)effective.ConversationHistoryKeyId}, "
            + $"stop={(KeyCode)effective.StopKeyId}, "
            + $"voice={effective.VoiceLanguage}, speech-input={effective.SpeechInputLanguage}, "
            + $"proactive-dialogue={(effective.ProactiveDialogueEnabled ? "on" : "off")}.");
    }

    private static void AddHeldD046GameControlKeys(
        D046GameControlProjectionSnapshot? snapshot,
        ISet<int> heldKeyIds)
    {
        if (snapshot == null)
            return;
        AddHeldD046GameControlKey(
            snapshot.PushToTalkKeyId,
            snapshot.PushToTalkPortableKey,
            heldKeyIds);
        AddHeldD046GameControlKey(
            snapshot.TextChatKeyId,
            snapshot.TextChatPortableKey,
            heldKeyIds);
        AddHeldD046GameControlKey(
            snapshot.ConversationHistoryKeyId,
            snapshot.ConversationHistoryPortableKey,
            heldKeyIds);
        AddHeldD046GameControlKey(
            snapshot.StopKeyId,
            snapshot.StopPortableKey,
            heldKeyIds);
    }

    private static void AddHeldD046GameControlKey(
        int keyId,
        D046FunctionKey? portableKey,
        ISet<int> heldKeyIds)
    {
        if (IsD046GameControlKeyCurrentlyDown((KeyCode)keyId, portableKey))
            heldKeyIds.Add(keyId);
    }

    private static bool TryMapD046FunctionKey(
        D046FunctionKey source,
        out KeyCode mapped)
    {
        mapped = source switch
        {
            D046FunctionKey.F1 => KeyCode.F1,
            D046FunctionKey.F2 => KeyCode.F2,
            D046FunctionKey.F3 => KeyCode.F3,
            D046FunctionKey.F4 => KeyCode.F4,
            D046FunctionKey.F5 => KeyCode.F5,
            D046FunctionKey.F6 => KeyCode.F6,
            D046FunctionKey.F7 => KeyCode.F7,
            D046FunctionKey.F8 => KeyCode.F8,
            D046FunctionKey.F9 => KeyCode.F9,
            D046FunctionKey.F10 => KeyCode.F10,
            D046FunctionKey.F11 => KeyCode.F11,
            D046FunctionKey.F12 => KeyCode.F12,
            D046FunctionKey.F13 => KeyCode.F13,
            D046FunctionKey.F14 => KeyCode.F14,
            D046FunctionKey.F15 => KeyCode.F15,
            D046FunctionKey.A => KeyCode.A,
            D046FunctionKey.B => KeyCode.B,
            D046FunctionKey.C => KeyCode.C,
            D046FunctionKey.D => KeyCode.D,
            D046FunctionKey.E => KeyCode.E,
            D046FunctionKey.F => KeyCode.F,
            D046FunctionKey.G => KeyCode.G,
            D046FunctionKey.H => KeyCode.H,
            D046FunctionKey.I => KeyCode.I,
            D046FunctionKey.J => KeyCode.J,
            D046FunctionKey.K => KeyCode.K,
            D046FunctionKey.L => KeyCode.L,
            D046FunctionKey.M => KeyCode.M,
            D046FunctionKey.N => KeyCode.N,
            D046FunctionKey.O => KeyCode.O,
            D046FunctionKey.P => KeyCode.P,
            D046FunctionKey.Q => KeyCode.Q,
            D046FunctionKey.R => KeyCode.R,
            D046FunctionKey.S => KeyCode.S,
            D046FunctionKey.T => KeyCode.T,
            D046FunctionKey.U => KeyCode.U,
            D046FunctionKey.V => KeyCode.V,
            D046FunctionKey.W => KeyCode.W,
            D046FunctionKey.X => KeyCode.X,
            D046FunctionKey.Y => KeyCode.Y,
            D046FunctionKey.Z => KeyCode.Z,
            D046FunctionKey.Digit0 => KeyCode.Alpha0,
            D046FunctionKey.Digit1 => KeyCode.Alpha1,
            D046FunctionKey.Digit2 => KeyCode.Alpha2,
            D046FunctionKey.Digit3 => KeyCode.Alpha3,
            D046FunctionKey.Digit4 => KeyCode.Alpha4,
            D046FunctionKey.Digit5 => KeyCode.Alpha5,
            D046FunctionKey.Digit6 => KeyCode.Alpha6,
            D046FunctionKey.Digit7 => KeyCode.Alpha7,
            D046FunctionKey.Digit8 => KeyCode.Alpha8,
            D046FunctionKey.Digit9 => KeyCode.Alpha9,
            D046FunctionKey.NumPad0 => KeyCode.Keypad0,
            D046FunctionKey.NumPad1 => KeyCode.Keypad1,
            D046FunctionKey.NumPad2 => KeyCode.Keypad2,
            D046FunctionKey.NumPad3 => KeyCode.Keypad3,
            D046FunctionKey.NumPad4 => KeyCode.Keypad4,
            D046FunctionKey.NumPad5 => KeyCode.Keypad5,
            D046FunctionKey.NumPad6 => KeyCode.Keypad6,
            D046FunctionKey.NumPad7 => KeyCode.Keypad7,
            D046FunctionKey.NumPad8 => KeyCode.Keypad8,
            D046FunctionKey.NumPad9 => KeyCode.Keypad9,
            D046FunctionKey.NumPadDivide => KeyCode.KeypadDivide,
            D046FunctionKey.NumPadMultiply => KeyCode.KeypadMultiply,
            D046FunctionKey.NumPadSubtract => KeyCode.KeypadMinus,
            D046FunctionKey.NumPadAdd => KeyCode.KeypadPlus,
            D046FunctionKey.NumPadDecimal => KeyCode.KeypadPeriod,
            D046FunctionKey.LeftArrow => KeyCode.LeftArrow,
            D046FunctionKey.RightArrow => KeyCode.RightArrow,
            D046FunctionKey.UpArrow => KeyCode.UpArrow,
            D046FunctionKey.DownArrow => KeyCode.DownArrow,
            D046FunctionKey.Home => KeyCode.Home,
            D046FunctionKey.End => KeyCode.End,
            D046FunctionKey.PageUp => KeyCode.PageUp,
            D046FunctionKey.PageDown => KeyCode.PageDown,
            D046FunctionKey.Insert => KeyCode.Insert,
            D046FunctionKey.Delete => KeyCode.Delete,
            D046FunctionKey.Space => KeyCode.Space,
            D046FunctionKey.Tab => KeyCode.Tab,
            D046FunctionKey.Enter => KeyCode.Return,
            D046FunctionKey.Backspace => KeyCode.Backspace,
            D046FunctionKey.OemSemicolon => KeyCode.Semicolon,
            D046FunctionKey.OemPlus => KeyCode.Equals,
            D046FunctionKey.OemComma => KeyCode.Comma,
            D046FunctionKey.OemMinus => KeyCode.Minus,
            D046FunctionKey.OemPeriod => KeyCode.Period,
            D046FunctionKey.OemQuestion => KeyCode.Slash,
            D046FunctionKey.OemTilde => KeyCode.BackQuote,
            D046FunctionKey.OemOpenBrackets => KeyCode.LeftBracket,
            D046FunctionKey.OemPipe => KeyCode.Backslash,
            D046FunctionKey.OemCloseBrackets => KeyCode.RightBracket,
            D046FunctionKey.OemQuotes => KeyCode.Quote,
            _ => KeyCode.None
        };
        return D046FunctionKeyCatalog.IsAssignable(source)
            && mapped != KeyCode.None;
    }

