    private static D046HotkeyTransition ObserveD046ExactHotkey(
        KeyCode key,
        D046ExactHotkeyLatch latch,
        D046FunctionKey? portableKey = null,
        bool suppressNewPresses = false)
    {
        return latch.Observe(
            IsD046GameControlKeyCurrentlyDown(key, portableKey),
            IsKeyCurrentlyDown(KeyCode.LeftControl)
                || IsKeyCurrentlyDown(KeyCode.RightControl),
            IsKeyCurrentlyDown(KeyCode.LeftShift)
                || IsKeyCurrentlyDown(KeyCode.RightShift),
            IsKeyCurrentlyDown(KeyCode.LeftAlt)
                || IsKeyCurrentlyDown(KeyCode.RightAlt),
            IsVirtualKeyDown(0x5B) || IsVirtualKeyDown(0x5C),
            suppressNewPresses);
    }

    private static void HandleD046Stop(DialogueManager manager)
    {
        OldMaidPresentation.Pause();
        ContinuationPresentation.Invalidate(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        StopDailyNoteDispatch();
        StopForegroundProactiveDispatch();
        // A proactive native continuation is owned only by Runtime, so it has
        // no local PlayerTurnOperation to cancel. Send the authenticated Stop
        // intent on every F8 press; the existing local cancellation paths below
        // remain authoritative for voice, player turns, and reply speech.
        _ = TryInterruptGameHermesTurnAsync(
            GameHermesNativeContinuationStopTurnId);

        var capture = _activeGameHermesVoiceCapture;
        var voiceCaptureStopped = capture != null;
        if (capture != null)
        {
            RequestGameHermesVoiceStop(
                capture,
                LilithGameBridgeVoiceStopDisposition.Cancel,
                reachedLimit: false);
        }

        var pendingTranscriptStopped = _pendingVoiceSubmitText != null;
        _pendingVoiceSubmitText = null;
        _pendingVoiceSubmitAt = -1f;
        while (PendingTranscripts.TryDequeue(out _))
            pendingTranscriptStopped = true;
        while (PendingTranscriptionErrors.TryDequeue(out _)) { }

        var active = PlayerTurnOperations.GetSnapshot().Active;
        var turnStopped = active != null
            && PlayerTurnOperations.TryCancel(
                active.Handle,
                PlayerTurnCancellationReason.PlayerRequested);
        if (turnStopped && active != null)
            HermesNoteCandidates.Retire(active.Handle);

        var replySpeechStopped = HasActivePublishedPlayerReplySpeech();
        CancelPublishedPlayerReplySpeech(
            D043SpeechCancellationReason.UserRequested);

        if (turnStopped || voiceCaptureStopped || pendingTranscriptStopped)
        {
            ForceSaySynthetic(
                manager,
                GameHermesFailureText(LilithGameBridgeTerminal.Interrupted),
                string.Empty,
                4f);
        }

        Plugin.PluginLog.LogInfo(
            "Processed the game stop hotkey: turn="
            + (turnStopped ? "1" : "0")
            + ", capture="
            + (voiceCaptureStopped ? "1" : "0")
            + ", transcript="
            + (pendingTranscriptStopped ? "1" : "0")
            + ", reply-speech="
            + (replySpeechStopped ? "1" : "0")
            + ", runtime-interrupt=1"
            + ".");
    }

    private static bool IsD046GameControlKeyCurrentlyDown(
        KeyCode unityKey,
        D046FunctionKey? portableKey)
    {
        if (portableKey.HasValue)
        {
            if (!D046FunctionKeyCatalog.TryGetWindowsVirtualKey(
                    portableKey.Value,
                    out var virtualKey))
            {
                return false;
            }
            if (OperatingSystem.IsWindows())
                return IsVirtualKeyDown(virtualKey);
        }

        try
        {
            return Input.GetKey(unityKey);
        }
        catch
        {
            return false;
        }
    }

    private static void EnsureLocalVoiceHost()
    {
        if (Time.unscaledTime < 2f)
            return;

        var useJapanese = IsJapaneseVoiceMode();
        if (VoiceHostLifecycle.Select(
                Plugin.VoiceEnabled.Value && Plugin.VoiceAutoStartLocalService.Value,
                useJapanese,
                Time.unscaledTime))
        {
            StopLocalVoiceHost();
            Plugin.PluginLog.LogInfo(VoiceHostLifecycle.Enabled
                ? $"Voice language or enablement changed to {(useJapanese ? "Japanese" : "Chinese")}; restarting the single local voice service with a fresh three-attempt budget."
                : "Automatic local voice service disabled; the owned voice host was stopped.");
            return;
        }
        if (!VoiceHostLifecycle.Enabled)
            return;

        if (_voiceHostProcess != null)
        {
            try
            {
                if (_voiceHostProcess.HasExited)
                {
                    var exitCode = _voiceHostProcess.ExitCode;
                    _voiceHostProcess.Dispose();
                    _voiceHostProcess = null;
                    _voiceHostJapaneseMode = null;
                    VoiceHostLifecycle.MarkStopped();
                    LocalVoicePreparation.Reset();
                    RegisterVoiceHostFailure(
                        "Bundled local voice host exited with code "
                        + exitCode
                        + ".");
                }
                else
                {
                    VoiceHostLifecycle.ObserveRunning(Time.unscaledTime);
                }
            }
            catch
            {
                StopLocalVoiceHost();
                RegisterVoiceHostFailure(
                    "Bundled local voice host state could not be inspected.");
            }
        }

        if (!VoiceHostLifecycle.CanLaunch(Time.unscaledTime))
            return;

        try
        {
            var endpoint = (useJapanese ? Plugin.JapaneseVoiceEndpoint.Value : Plugin.VoiceEndpoint.Value).Trim();
            if (!endpoint.StartsWith("http://127.0.0.1:", StringComparison.OrdinalIgnoreCase))
                return;
            VoiceHostLifecycle.MarkLaunchAttempt();
            var hostPath = Environment.ExpandEnvironmentVariables(Plugin.VoiceHostPath.Value.Trim());
            if (!File.Exists(hostPath))
            {
                Plugin.PluginLog.LogInfo("Bundled local voice service is not installed; dynamic voice remains available through configured external endpoints.");
                return;
            }
            var startInfo = new ProcessStartInfo
            {
                FileName = hostPath,
                Arguments = $"--voice-host --parent {Environment.ProcessId} --language {(useJapanese ? "ja" : "zh")}",
                WorkingDirectory = Path.GetDirectoryName(hostPath) ?? Paths.GameRootPath,
                UseShellExecute = false,
                CreateNoWindow = true,
                WindowStyle = ProcessWindowStyle.Hidden
            };
            var bundledDotnet = Path.Combine(Paths.GameRootPath, "dotnet");
            if (Directory.Exists(bundledDotnet))
                startInfo.Environment["DOTNET_ROOT"] = bundledDotnet;
            _voiceHostProcess = Process.Start(startInfo)
                ?? throw new InvalidOperationException(
                    "The bundled local voice host did not return a process handle.");
            _voiceHostJapaneseMode = useJapanese;
            VoiceHostLifecycle.MarkStarted(Time.unscaledTime);
            Plugin.PluginLog.LogInfo($"Started the bundled local {(useJapanese ? "Japanese" : "Chinese")} voice host without a console window.");
        }
        catch (Exception exception)
        {
            RegisterVoiceHostFailure(
                "Could not start the bundled local voice host: "
                + exception.Message);
        }
    }

    private static void RegisterVoiceHostFailure(string message)
    {
        VoiceHostLifecycle.RegisterFailure(Time.unscaledTime);
        if (VoiceHostLifecycle.ConsecutiveFailures >= 3)
        {
            Plugin.PluginLog.LogWarning(
                message
                + " The three-attempt restart budget is exhausted for "
                + "this voice selection; change language or disable/re-enable voice to retry. Text chat remains available.");
            return;
        }

        var delaySeconds = 5f * VoiceHostLifecycle.ConsecutiveFailures;
        Plugin.PluginLog.LogWarning(
            message
            + " Restart attempt "
            + (VoiceHostLifecycle.ConsecutiveFailures + 1)
            + "/3 is delayed by "
            + delaySeconds.ToString("0", CultureInfo.InvariantCulture)
            + " seconds.");
    }

    private static void StopLocalVoiceHost()
    {
        LocalVoicePreparation.Reset();
        var process = _voiceHostProcess;
        _voiceHostProcess = null;
        _voiceHostJapaneseMode = null;
        VoiceHostLifecycle.MarkStopped();
        if (process == null)
            return;

        try
        {
            if (!process.HasExited)
                process.Kill(true);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not stop the previous local voice host: {exception.Message}");
        }
        finally
        {
            process.Dispose();
        }
    }

    private static string ActionShowcaseMarkerPath => Path.Combine(
        Paths.BepInExRootPath, "data", "LilithTextInjector", "action-showcase.enabled");

    private static string GroundWalkSmokeRequestPath => Path.Combine(
        Paths.BepInExRootPath, "data", "LilithTextInjector", "ground-walk-smoke.request");

    private static void UpdateMotionIntentRuntime(DialogueManager manager)
    {
        var globalPhysicsEnabled = Plugin.Effective(
            Plugin.GlobalMotionPhysicsEnabled.Value);
        var requiresRuntime = globalPhysicsEnabled
            || _globalMotionPhysicsRuntimeActive
            || Plugin.MotionDirectorEnabled.Value
            || _actionShowcasePendingOperation != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcaseWindowWalkContinuationActive
            || _actionShowcaseAttachedToWindow
            || _actionShowcaseHasWindowPlatform
            || _motionIntentSitActive
            || _activeMotionProposalExecution != null
            || _actionShowcaseCoherentRandomActive;
        if (!requiresRuntime)
            return;

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (character == null || state == null)
            return;

        SynchronizeGlobalMotionPhysics(globalPhysicsEnabled, state);

        MaintainActionShowcaseDedicatedPlatform(state);
        if (_actionShowcasePendingOperation != ActionShowcasePendingOperation.None)
            CompletePendingActionShowcaseOperation(manager, character, state);
        UpdateActionShowcaseWindowWalkContinuation(state);
        UpdateActionShowcaseCoherentRandom(manager, character, state);
    }

    private static void SynchronizeGlobalMotionPhysics(
        bool enabled,
        LilithStateManager state)
    {
        if (!_globalMotionPhysicsRuntimeInitialized)
        {
            _globalMotionPhysicsRuntimeInitialized = true;
            _globalMotionPhysicsRuntimeActive = enabled;
            Plugin.PluginLog.LogInfo(
                $"Global Motion Authority physics initialized: enabled={enabled}. MOD window surfaces are {(enabled ? "authoritative for all desktop-pet motion" : "limited to explicit exploration sessions")}.");
            return;
        }
        if (_globalMotionPhysicsRuntimeActive == enabled)
            return;

        _globalMotionPhysicsRuntimeActive = enabled;
        if (enabled)
        {
            _actionShowcasePlatformRefreshAt = -1f;
            _globalMotionPhysicsInventoryLogged = false;
            Plugin.PluginLog.LogInfo(
                "Global Motion Authority physics enabled; activating MOD one-way surfaces for every motion source.");
            return;
        }

        if (!_actionShowcaseHasExplorationOrigin)
        {
            _actionShowcaseHasWindowPlatform = false;
            _actionShowcaseWindowHandle = IntPtr.Zero;
            ClearActionShowcaseStandingPlatformMemory();
            ClearActionShowcaseWindowAttachment();
            DestroyActionShowcaseDedicatedPlatform();
            _globalMotionPhysicsInventoryLogged = false;
            StopActionShowcasePhysics(state, markGrounded: state.IsGround);
        }
        Plugin.PluginLog.LogInfo(
            "Global Motion Authority physics disabled; restored native window collisions outside explicit exploration.");
    }

    private static bool IsGlobalMotionPhysicsActive =>
        Plugin.Effective(Plugin.GlobalMotionPhysicsEnabled.Value);

    private static void HandleActionShowcase(DialogueManager manager)
    {
        if (!File.Exists(ActionShowcaseMarkerPath))
            return;
        var groundWalkSmokeRequested = File.Exists(GroundWalkSmokeRequestPath);
        var hasPendingOperation = _actionShowcasePendingOperation != ActionShowcasePendingOperation.None;
        if (!hasPendingOperation
            && !_actionShowcaseHasExplorationOrigin
            && !_actionShowcaseOverlayBehindWindow
            && !_actionShowcaseCoherentRandomActive
            && !_groundWalkSmokeActive
            && !groundWalkSmokeRequested)
            return;

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (character == null || state == null)
        {
            ShowActionShowcaseMessage(manager, "找不到莉莉絲的角色控制器，這次無法展示。");
            Plugin.PluginLog.LogWarning("Action showcase could not find CharacterController or LilithStateManager.");
            return;
        }

        MaintainActionShowcaseDedicatedPlatform(state);

        if (groundWalkSmokeRequested)
        {
            try
            {
                File.Delete(GroundWalkSmokeRequestPath);
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogWarning(
                    $"Could not consume ground-walk smoke request: {exception.Message}");
            }
            BeginGroundWalkSmokeTest(manager, character, state);
        }
        UpdateGroundWalkSmokeTest(manager, character, state);

    }

    private static void BeginGroundWalkSmokeTest(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (_actionShowcaseHasExplorationOrigin)
            RestoreActionShowcaseExploration(character, state, restorePosition: true);
        ResetActionShowcaseCharacter(character, state);
        if (state.ClothingState == LilithClothingState.Pajamas)
        {
            _groundWalkSmokeActive = false;
            Plugin.PluginLog.LogWarning(
                "Ground walk smoke test aborted because Pajamas has no directional walk assets.");
            return;
        }
        if (!state.IsGround || state.IsDrag || state.IsStateMachineLocked)
        {
            _groundWalkSmokeActive = false;
            Plugin.PluginLog.LogWarning(
                $"Ground walk smoke test aborted because the character is unavailable: ground={state.IsGround}, drag={state.IsDrag}, locked={state.IsStateMachineLocked}.");
            return;
        }

        _actionShowcaseGroup = -1;
        _groundWalkSmokeActive = true;
        _groundWalkSmokePhase = 0;
        _groundWalkSmokeOriginX = state.transform.position.x;
        _groundWalkSmokeOffset = Math.Clamp(state.CharacterHeightWorld * 0.75f, 0.5f, 3f);
        _groundWalkSmokePassed = true;
        ShowActionShowcaseMessage(manager, "地板走路回歸：左走 → 右走 → 回到起點", 6f);
        StartGroundWalkSmokeSegment(state, _groundWalkSmokeOriginX - _groundWalkSmokeOffset, "Left");
        Plugin.PluginLog.LogInfo(
            $"Ground walk smoke test started: originX={_groundWalkSmokeOriginX:F3}, offset={_groundWalkSmokeOffset:F3}.");
    }

    private static void StartGroundWalkSmokeSegment(
        LilithStateManager state,
        float targetX,
        string label)
    {
        _groundWalkSmokeSegmentStartX = state.transform.position.x;
        _groundWalkSmokeSegmentStartedAt = Time.unscaledTime;
        _groundWalkSmokeSettleAt = Time.unscaledTime + 0.2f;
        state.ClearWalkTarget();
        var started = state.EnterWalkToX(targetX, 0.15f);
        if (!started)
            _groundWalkSmokePassed = false;
        Plugin.PluginLog.LogInfo(
            $"Ground walk smoke segment requested: phase={_groundWalkSmokePhase}, label={label}, startX={_groundWalkSmokeSegmentStartX:F3}, targetX={targetX:F3}, started={started}.");
    }

    private static void UpdateGroundWalkSmokeTest(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (!_groundWalkSmokeActive)
            return;
        if (state.IsWalkLeft || state.IsWalkRight)
        {
            if (Time.unscaledTime - _groundWalkSmokeSegmentStartedAt <= 10f)
                return;
            _groundWalkSmokePassed = false;
            state.ClearWalkTarget();
            state.ReturnIdle();
            Plugin.PluginLog.LogWarning(
                $"Ground walk smoke segment timed out: phase={_groundWalkSmokePhase}, positionX={state.transform.position.x:F3}.");
        }
        if (Time.unscaledTime < _groundWalkSmokeSettleAt)
            return;

        var endX = state.transform.position.x;
        var deltaX = endX - _groundWalkSmokeSegmentStartX;
        var minimumProgress = Math.Max(0.18f, _groundWalkSmokeOffset * 0.35f);
        var segmentPassed = _groundWalkSmokePhase switch
        {
            0 => deltaX <= -minimumProgress,
            1 => deltaX >= minimumProgress,
            _ => Math.Abs(endX - _groundWalkSmokeOriginX)
                <= Math.Max(0.25f, _groundWalkSmokeOffset * 0.2f)
        };
        _groundWalkSmokePassed &= segmentPassed && state.IsGround;
        Plugin.PluginLog.LogInfo(
            $"Ground walk smoke segment completed: phase={_groundWalkSmokePhase}, startX={_groundWalkSmokeSegmentStartX:F3}, endX={endX:F3}, deltaX={deltaX:F3}, ground={state.IsGround}, passed={segmentPassed}.");

        _groundWalkSmokePhase++;
        switch (_groundWalkSmokePhase)
        {
            case 1:
                ResetActionShowcaseCharacter(character, state);
                StartGroundWalkSmokeSegment(state, _groundWalkSmokeOriginX + _groundWalkSmokeOffset, "Right");
                break;
            case 2:
                ResetActionShowcaseCharacter(character, state);
                StartGroundWalkSmokeSegment(state, _groundWalkSmokeOriginX, "Return");
                break;
            default:
                ResetActionShowcaseCharacter(character, state);
                _groundWalkSmokeActive = false;
                _groundWalkSmokeSegmentStartedAt = -1f;
                _groundWalkSmokeSettleAt = -1f;
                ShowActionShowcaseMessage(
                    manager,
                    _groundWalkSmokePassed ? "地板走路回歸通過" : "地板走路回歸失敗，請查看日誌",
                    6f);
                Plugin.PluginLog.LogInfo(
                    $"Ground walk smoke test completed: passed={_groundWalkSmokePassed}, finalX={state.transform.position.x:F3}, originX={_groundWalkSmokeOriginX:F3}.");
                break;
        }
    }

    private static void PlayActionShowcaseOneShot(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int direction,
        bool replay)
    {
        var index = ActionShowcaseIndices[0];
        for (var attempts = 0; attempts < ActionShowcaseOneShots.Length; attempts++)
        {
            if (!replay || index < 0)
                index = WrapActionShowcaseIndex(index + direction, ActionShowcaseOneShots.Length);
            replay = false;
            var action = ActionShowcaseOneShots[index];
            if (!state.HasActionAnimation(action))
                continue;

            ActionShowcaseIndices[0] = index;
            ResetActionShowcaseCharacter(character, state);
            ShowActionShowcaseMessage(manager, $"單次動作 {index + 1}/{ActionShowcaseOneShots.Length}：{action}", 5f);
            character.PlayLilithAction(action, true, null);
            Plugin.PluginLog.LogInfo($"Action showcase played one-shot {index + 1}/{ActionShowcaseOneShots.Length}: {action}.");
            return;
        }

        ShowActionShowcaseMessage(manager, "目前服裝沒有可播放的單次動作。", 4f);
        Plugin.PluginLog.LogWarning("Action showcase found no supported one-shot animation for the current clothing state.");
    }

    private static void PlayActionShowcaseEmotion(
        DialogueManager manager,
        global::CharacterController character,
        int direction,
        bool replay)
    {
        var index = ActionShowcaseIndices[1];
        if (!replay || index < 0)
            index = WrapActionShowcaseIndex(index + direction, ActionShowcaseEmotions.Length);
        ActionShowcaseIndices[1] = index;
        var emotion = ActionShowcaseEmotions[index];
        var played = character.PlayEmotion(emotion, loop: false, instant: false, bypassFollowLock: false);
        ShowActionShowcaseMessage(manager, $"表情 {index + 1}/{ActionShowcaseEmotions.Length}：{emotion}（{(played ? "已播放" : "不可用")}）", 5f);
        Plugin.PluginLog.LogInfo($"Action showcase requested emotion {index + 1}/{ActionShowcaseEmotions.Length}: {emotion}; played={played}.");
    }

    private static void PlayActionShowcaseMovement(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int direction,
        bool replay)
    {
        if (state.ClothingState == LilithClothingState.Pajamas)
        {
            ShowActionShowcaseMessage(manager, "睡衣狀態沒有左右走路動畫，已取消走動。", 5f);
            Plugin.PluginLog.LogInfo("Action showcase rejected movement because Pajamas has no directional walk assets.");
            return;
        }

        const int itemCount = 3;
        var index = ActionShowcaseIndices[2];
        if (!replay || index < 0)
            index = WrapActionShowcaseIndex(index + direction, itemCount);
        ActionShowcaseIndices[2] = index;

        if (!_actionShowcaseHasWalkOrigin)
        {
            _actionShowcaseWalkOriginX = state.transform.position.x;
            _actionShowcaseHasWalkOrigin = true;
        }

        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        var offset = Math.Clamp(state.CharacterHeightWorld * 0.75f, 0.5f, 3f);
        var target = index switch
        {
            0 => state.transform.position.x - offset,
            1 => state.transform.position.x + offset,
            _ => _actionShowcaseWalkOriginX
        };
        var label = index switch
        {
            0 => "向左短距離走動",
            1 => "向右短距離走動",
            _ => "走回展示起點"
        };
        var started = state.EnterWalkToX(target, 0.15f);
        ShowActionShowcaseMessage(manager, $"走動 {index + 1}/{itemCount}：{label}（{(started ? "已開始" : "目前不可走")}）", 5f);
        Plugin.PluginLog.LogInfo($"Action showcase requested movement {index + 1}/{itemCount}: {label}; started={started}.");
    }

    private static void PlayActionShowcasePose(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int direction,
        bool replay)
    {
        const int itemCount = 4;
        var index = ActionShowcaseIndices[3];
        if (!replay || index < 0)
            index = WrapActionShowcaseIndex(index + direction, itemCount);
        ActionShowcaseIndices[3] = index;

        switch (index)
        {
            case 0:
                ResetActionShowcaseCharacter(character, state);
                var poseSitStarted = EnterActionShowcaseSitAtCurrentPosition(state);
                ShowActionShowcaseMessage(
                    manager,
                    $"姿勢 1/4：在目前位置坐下（{(poseSitStarted ? "已開始" : "目前位置不可坐")}）",
                    5f);
                break;
            case 1:
                ResetActionShowcaseCharacter(character, state);
                state.EnterLieDownState();
                ShowActionShowcaseMessage(manager, "姿勢 2/4：躺下", 5f);
                break;
            case 2:
                ResetActionShowcaseCharacter(character, state);
                state.EnterSleepState();
                ShowActionShowcaseMessage(manager, "姿勢 3/4：睡覺", 5f);
                break;
            default:
                ResetActionShowcaseCharacter(character, state);
                ShowActionShowcaseMessage(manager, "姿勢 4/4：恢復站立待機", 5f);
                break;
        }
        Plugin.PluginLog.LogInfo($"Action showcase requested pose {index + 1}/{itemCount}.");
    }

    private static void PlayActionShowcaseExploration(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int direction,
        bool replay)
    {
        const int itemCount = 12;
        var index = ActionShowcaseIndices[4];
        if (!replay || index < 0)
            index = WrapActionShowcaseIndex(index + direction, itemCount);
        ActionShowcaseIndices[4] = index;
        CaptureActionShowcaseExplorationOrigin(state);
        if (_actionShowcaseCoherentRandomActive && index != 8)
            StopActionShowcaseCoherentRandom();

        switch (index)
        {
            case 0:
            {
                var target = Math.Min(0.35f, _actionShowcaseExplorationOriginFraction);
                BeginActionShowcaseScaleSnap(manager, character, state, target, $"探索 1/{itemCount}：響指縮放到 {target:P0}");
                break;
            }
            case 1:
            {
                var target = Math.Min(0.25f, _actionShowcaseExplorationOriginFraction);
                BeginActionShowcaseScaleSnap(manager, character, state, target, $"探索 2/{itemCount}：響指縮放到暫定軟下限 {target:P0}");
                break;
            }
            case 2:
            {
                var target = Math.Min(0.5f, _actionShowcaseExplorationOriginFraction);
                BeginActionShowcaseScaleSnap(manager, character, state, target, $"探索 3/{itemCount}：響指放大，但不超過 {target:P0}");
                break;
            }
            case 3:
            {
                ResetActionShowcaseCharacter(character, state);
                var started = BeginNativeScreenPeekLifecycle(character, state);
                ShowActionShowcaseMessage(manager, $"探索 4/{itemCount}：原生螢幕左緣探頭（{(started ? "已開始" : "目前不可用")}）", 6f);
                Plugin.PluginLog.LogInfo($"Exploration showcase requested native ScreenPeek; started={started}.");
                break;
            }
            case 4:
            {
                ResetActionShowcaseCharacter(character, state);
                RefreshActionShowcaseAllWindowPlatforms(state);
                if (TryAdoptActionShowcasePlatformUnderCharacter(state))
                {
                    var explorationSitStarted = EnterActionShowcaseSitAtCurrentPosition(state);
                    ShowActionShowcaseMessage(
                        manager,
                        $"探索 5/{itemCount}：在目前視窗位置自由坐下（{(explorationSitStarted ? "已開始" : "原生坐姿取消")}）",
                        7f);
                    Plugin.PluginLog.LogInfo($"Exploration showcase requested an in-place sit; started={explorationSitStarted}.");
                }
                else
                {
                    BeginActionShowcaseWindowSitSnap(manager, character, state, itemCount);
                }
                break;
            }
            case 5:
                BeginActionShowcaseWindowSnap(manager, character, state, itemCount);
                break;
            case 6:
                PlayActionShowcaseWindowWalk(manager, character, state, walkLeft: true, index + 1, itemCount);
                break;
            case 7:
                PlayActionShowcaseWindowWalk(manager, character, state, walkLeft: false, index + 1, itemCount);
                break;
            case 8:
                ToggleActionShowcaseCoherentRandom(manager, character, state, index + 1, itemCount);
                break;
            case 9:
                PlayActionShowcaseWindowDrop(manager, character, state, index + 1, itemCount);
                break;
            case 10:
                PlayActionShowcaseWindowPeek(manager, character, state, index + 1, itemCount);
                break;
            default:
                RestoreActionShowcaseExploration(character, state, restorePosition: true);
                ShowActionShowcaseMessage(manager, $"探索 12/{itemCount}：已恢復原位置與玩家原尺寸", 6f);
                Plugin.PluginLog.LogInfo("Exploration showcase restored its original transform from the final item.");
                break;
        }
    }

    private static void CaptureActionShowcaseExplorationOrigin(LilithStateManager state)
    {
        if (_actionShowcaseHasExplorationOrigin)
            return;

        _actionShowcaseExplorationOriginPosition = state.transform.position;
        _actionShowcaseExplorationOriginScale = state.transform.localScale;
        var fraction = Archive.Instance?.lilithScreenFraction ?? 0.5f;
        if (float.IsNaN(fraction) || float.IsInfinity(fraction) || fraction < 0.1f || fraction > 0.7f)
            fraction = 0.5f;
        _actionShowcaseExplorationOriginFraction = fraction;
        _actionShowcaseHasExplorationOrigin = true;
        _actionShowcasePlatformRefreshAt = -1f;
        MaintainActionShowcaseDedicatedPlatform(state);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase captured origin: fraction={fraction:F3}, position={_actionShowcaseExplorationOriginPosition}, scale={_actionShowcaseExplorationOriginScale}.");
    }

    private static void BeginActionShowcaseScaleSnap(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        float targetFraction,
        string description)
    {
        targetFraction = Math.Clamp(targetFraction, 0.1f, 0.5f);
        ResetActionShowcaseCharacter(character, state);
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.ApplyScale;
        _actionShowcasePendingScaleFraction = targetFraction;
        _actionShowcasePendingDescription = description;
        ShowActionShowcaseMessage(manager, description, 6f);
        BeginActionShowcaseSnap(character, state);
        Plugin.PluginLog.LogInfo($"Exploration showcase scheduled scale fraction {targetFraction:F3} behind Snap.");
    }

    private static void BeginActionShowcaseWindowSnap(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int itemCount)
    {
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (windowColliders == null)
        {
            ShowActionShowcaseMessage(manager, $"探索 6/{itemCount}：找不到視窗碰撞控制器", 5f);
            return;
        }

        if (!TrySelectActionShowcaseWindowPlatform(
                windowColliders,
                state,
                forSeatedPose: false,
                out var windowHandle,
                out var windowTitle,
                out var topCenter,
                out var windowBounds,
                out var candidateNumber,
                out var candidateCount))
        {
            ShowActionShowcaseMessage(manager, $"探索 6/{itemCount}：全部可見視窗都沒有寬度、露出頂邊及頭部空間合格的位置", 7f);
            Plugin.PluginLog.LogInfo("Exploration showcase found no eligible platform among all active window colliders.");
            return;
        }

        ResetActionShowcaseCharacter(character, state);
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.MoveToWindow;
        _actionShowcaseWindowHandle = windowHandle;
        _actionShowcaseWindowTitle = windowTitle;
        _actionShowcasePendingWindowTop = topCenter;
        _actionShowcasePendingWindowBounds = windowBounds;
        _actionShowcasePendingDescription = $"探索 6/{itemCount}：響指移到可見視窗候選 {candidateNumber}/{candidateCount}";
        _actionShowcasePendingDescription = $"Exploration 6/{itemCount}: target {candidateNumber}/{candidateCount} - {windowTitle}";
        ShowActionShowcaseMessage(manager, _actionShowcasePendingDescription, 6f);
        BeginActionShowcaseSnap(character, state);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase scheduled enumerated window move: handle=0x{windowHandle.ToInt64():X}, candidate={candidateNumber}/{candidateCount}, top={topCenter}, bounds={windowBounds}.");
    }

    private static bool BeginActionShowcaseWindowSitSnap(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int itemCount,
        bool showFeedback = true)
    {
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (windowColliders == null
            || !TrySelectActionShowcaseWindowPlatform(
                windowColliders,
                state,
                forSeatedPose: true,
                out var windowHandle,
                out var windowTitle,
                out var topCenter,
                out var windowBounds,
                out var candidateNumber,
                out var candidateCount))
        {
            if (showFeedback)
            {
                ShowActionShowcaseMessage(
                    manager,
                    $"探索 5/{itemCount}：目前沒有寬度、露出頂邊及頭部空間合格的座位",
                    7f);
            }
            Plugin.PluginLog.LogInfo("Exploration showcase found no eligible window for its sit fallback.");
            return false;
        }

        ResetActionShowcaseCharacter(character, state);
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.MoveToWindowThenSit;
        _actionShowcaseWindowHandle = windowHandle;
        _actionShowcaseWindowTitle = windowTitle;
        _actionShowcasePendingWindowTop = topCenter;
        _actionShowcasePendingWindowBounds = windowBounds;
        _actionShowcasePendingDescription =
            $"探索 5/{itemCount}：響指前往座位 {candidateNumber}/{candidateCount}「{windowTitle}」並坐下";
        _actionShowcasePendingShowFeedback = showFeedback;
        if (showFeedback)
            ShowActionShowcaseMessage(manager, _actionShowcasePendingDescription, 7f);
        BeginActionShowcaseSnap(character, state);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase scheduled window-sit fallback: handle=0x{windowHandle.ToInt64():X}, candidate={candidateNumber}/{candidateCount}, top={topCenter}, bounds={windowBounds}.");
        return true;
    }

    private static bool TrySelectActionShowcaseWindowPlatform(
        ActiveWindowCollider windowColliders,
        LilithStateManager state,
        bool forSeatedPose,
        out IntPtr windowHandle,
        out string windowTitle,
        out Vector3 topCenter,
        out Bounds windowBounds,
        out int candidateNumber,
        out int candidateCount)
    {
        windowHandle = IntPtr.Zero;
        windowTitle = string.Empty;
        topCenter = default;
        windowBounds = default;
        candidateNumber = 0;
        candidateCount = 0;
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return false;

        var desktopWindows = EnumerateActionShowcasePlatformWindows();
        Plugin.PluginLog.LogInfo(
            "Exploration visible window surfaces: "
            + (desktopWindows.Count == 0
                ? "none"
                : string.Join(
                    " | ",
                    desktopWindows.Select(window =>
                        $"{window.Title} [0x{window.Handle.ToInt64():X}] {window.Bounds}"))));

        var candidates = new List<(IntPtr Handle, Vector3 Top, Bounds Bounds, string Process)>();
        var screenTop = windowColliders.GetScreenTopWorldY();
        for (var i = 0; i < desktopWindows.Count; i++)
        {
            var desktopWindow = desktopWindows[i];
            if (desktopWindow.Handle == IntPtr.Zero
                || desktopWindow.Bounds.width < 80
                || desktopWindow.Bounds.height < 40
                || !TryConvertDesktopRectToWorld(desktopWindow.Bounds, state.transform, out var describedBounds))
                continue;

            var horizontalMargin = Math.Max(0.04f, characterBounds.extents.x * 0.2f);
            var minCenterX = describedBounds.min.x + characterBounds.extents.x + horizontalMargin;
            var maxCenterX = describedBounds.max.x - characterBounds.extents.x - horizontalMargin;
            if (minCenterX > maxCenterX)
                continue;

            var preferredX = Math.Clamp(characterBounds.center.x, minCenterX, maxCenterX);
            var foundPoint = false;
            var selectedX = preferredX;
            for (var sample = 0; sample < 9; sample++)
            {
                var t = sample == 0 ? 0.5f : (sample - 1) / 7f;
                var candidateX = sample == 0 ? preferredX : Mathf.Lerp(minCenterX, maxCenterX, t);
                var shiftedMaxY = forSeatedPose
                    ? GetActionShowcasePredictedSeatedMaximumY(
                        state,
                        describedBounds.max.y,
                        characterBounds)
                    : characterBounds.max.y
                        + (describedBounds.max.y + 0.025f - characterBounds.min.y);
                if (shiftedMaxY > screenTop - 0.02f)
                {
                    if (sample == 0)
                    {
                        Plugin.PluginLog.LogInfo(
                            $"Exploration rejected window headroom: mode={(forSeatedPose ? "Sit" : "Stand")}, title={desktopWindow.Title}, handle=0x{desktopWindow.Handle.ToInt64():X}, predictedTop={shiftedMaxY:F3}, screenLimit={screenTop - 0.02f:F3}, windowTop={describedBounds.max.y:F3}.");
                    }
                    continue;
                }

                var pixelT = maxCenterX <= minCenterX
                    ? 0.5f
                    : Mathf.InverseLerp(describedBounds.min.x, describedBounds.max.x, candidateX);
                var desktopX = desktopWindow.Bounds.xMin
                    + Mathf.RoundToInt(desktopWindow.Bounds.width * pixelT);
                var desktopY = desktopWindow.Bounds.yMin - 2;
                var topEdgeCovered = false;
                for (var frontIndex = 0; frontIndex < i; frontIndex++)
                {
                    var frontBounds = desktopWindows[frontIndex].Bounds;
                    if (desktopX > frontBounds.xMin
                        && desktopX < frontBounds.xMax
                        && desktopY > frontBounds.yMin
                        && desktopY < frontBounds.yMax)
                    {
                        topEdgeCovered = true;
                        break;
                    }
                }
                if (topEdgeCovered)
                    continue;

                selectedX = candidateX;
                foundPoint = true;
                break;
            }
            if (!foundPoint)
                continue;

            var describedTop = new Vector3(selectedX, describedBounds.max.y, state.transform.position.z);
            candidates.Add((desktopWindow.Handle, describedTop, describedBounds, desktopWindow.Title));
        }

        candidateCount = candidates.Count;
        if (candidateCount == 0)
            return false;
        _actionShowcaseWindowCandidateCursor = WrapActionShowcaseIndex(
            _actionShowcaseWindowCandidateCursor,
            candidateCount);
        var selected = candidates[_actionShowcaseWindowCandidateCursor];
        candidateNumber = _actionShowcaseWindowCandidateCursor + 1;
        _actionShowcaseWindowCandidateCursor = (_actionShowcaseWindowCandidateCursor + 1) % candidateCount;
        windowHandle = selected.Handle;
        windowTitle = selected.Process;
        topCenter = selected.Top;
        windowBounds = selected.Bounds;
        Plugin.PluginLog.LogInfo(
            $"Exploration OS window candidate selected: process={selected.Process}, handle=0x{selected.Handle.ToInt64():X}, total={candidateCount}.");
        return true;
    }

    private static float GetActionShowcasePredictedSeatedMaximumY(
        LilithStateManager state,
        float platformTopY,
        Bounds fallbackCharacterBounds)
    {
        var silhouetteBounds = TryGetActionShowcaseVisualBounds(state, out var visualBounds)
            ? visualBounds
            : fallbackCharacterBounds;
        var silhouetteTopFromRoot = silhouetteBounds.max.y - state.transform.position.y;
        // Native SitState keeps a small visual clearance above the mathematical
        // seat root.  Include a conservative budget so accepted heads remain on-screen.
        var nativeSeatClearance = Math.Max(0.05f, state.CharacterHeightWorld * 0.012f);
        return platformTopY
            - state.GetSitVerticalOffset()
            + silhouetteTopFromRoot
            + nativeSeatClearance;
    }

    private static bool TryConvertDesktopRectToWorld(RectInt desktopBounds, Transform reference, out Bounds worldBounds)
    {
        worldBounds = default;
        var camera = Camera.main;
        if (camera == null || desktopBounds.width <= 0 || desktopBounds.height <= 0)
            return false;
        var virtualBounds = PlatformService.Current.GetVirtualScreenBounds();
        if (virtualBounds.width <= 0 || virtualBounds.height <= 0)
            return false;

        var leftPixels = desktopBounds.xMin - virtualBounds.xMin;
        var rightPixels = desktopBounds.xMax - virtualBounds.xMin;
        var topPixels = virtualBounds.height - (desktopBounds.yMin - virtualBounds.yMin);
        var bottomPixels = virtualBounds.height - (desktopBounds.yMax - virtualBounds.yMin);
        var depth = camera.WorldToScreenPoint(reference.position).z;
        var bottomLeft = camera.ScreenToWorldPoint(new Vector3(leftPixels, bottomPixels, depth));
        var topRight = camera.ScreenToWorldPoint(new Vector3(rightPixels, topPixels, depth));
        var min = new Vector3(Math.Min(bottomLeft.x, topRight.x), Math.Min(bottomLeft.y, topRight.y), reference.position.z);
        var max = new Vector3(Math.Max(bottomLeft.x, topRight.x), Math.Max(bottomLeft.y, topRight.y), reference.position.z);
        worldBounds = new Bounds((min + max) * 0.5f, new Vector3(max.x - min.x, max.y - min.y, 0f));
        return worldBounds.size.x > 0.01f && worldBounds.size.y > 0.01f;
    }

    [UnmanagedFunctionPointer(CallingConvention.Winapi)]
    private delegate bool ActionShowcaseEnumWindowsProc(IntPtr window, IntPtr parameter);

    [DllImport("user32.dll", EntryPoint = "EnumWindows")]
    private static extern bool EnumerateActionShowcaseWindows(
        ActionShowcaseEnumWindowsProc callback,
        IntPtr parameter);

    [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetWindowTextLengthW")]
    private static extern int GetActionShowcaseWindowTextLength(IntPtr window);

    [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "GetWindowTextW")]
    private static extern int GetActionShowcaseWindowText(
        IntPtr window,
        StringBuilder text,
        int maximumCount);

    [DllImport("dwmapi.dll")]
    private static extern int DwmGetWindowAttribute(
        IntPtr window,
        int attribute,
        out int value,
        int valueSize);

    private static bool IsActionShowcaseWindowCloaked(IntPtr window)
    {
        const int dwmWindowAttributeCloaked = 14;
        try
        {
            return DwmGetWindowAttribute(
                    window,
                    dwmWindowAttributeCloaked,
                    out var cloaked,
                    sizeof(int)) == 0
                && cloaked != 0;
        }
        catch
        {
            return false;
        }
    }

    private static List<ActionShowcaseDesktopWindow> EnumerateActionShowcaseDesktopWindows()
    {
        var result = new List<ActionShowcaseDesktopWindow>();
        if (!OperatingSystem.IsWindows())
            return result;

        var appWindow = PlatformService.Current.GetAppWindowHandle();
        var shellWindow = WindowsNativeAPI.GetShellWindow();
        var allowedBounds = PlatformService.Current.GetVirtualScreenBounds();
        if (allowedBounds.width <= 0 || allowedBounds.height <= 0)
            return result;
        ActionShowcaseEnumWindowsProc callback = (window, _) =>
        {
            try
            {
            if (window == IntPtr.Zero
                || window == appWindow
                || window == shellWindow
                || !IsWindowVisible(window)
                || WindowsNativeAPI.IsIconic(window)
                || !WindowsNativeAPI.IsWindowOnCurrentVirtualDesktop(window)
                || IsActionShowcaseWindowCloaked(window))
                return true;

            var extendedStyle = WindowsNativeAPI.GetWindowLongPtrSafe(window, WindowsNativeAPI.GWL_EXSTYLE).ToInt64();
            if ((extendedStyle & WindowsNativeAPI.WS_EX_TOOLWINDOW) != 0)
                return true;

            var titleLength = GetActionShowcaseWindowTextLength(window);
            if (titleLength <= 0)
                return true;
            var titleBuffer = new StringBuilder(titleLength + 1);
            GetActionShowcaseWindowText(window, titleBuffer, titleBuffer.Capacity);

            if (!TryGetActionShowcaseDesktopWindowBounds(window, out var bounds)
                || bounds.width < 80
                || bounds.height < 40)
                return true;
            var visibleWidth = Math.Min(bounds.xMax, allowedBounds.xMax)
                - Math.Max(bounds.xMin, allowedBounds.xMin);
            var visibleHeight = Math.Min(bounds.yMax, allowedBounds.yMax)
                - Math.Max(bounds.yMin, allowedBounds.yMin);
            if (visibleWidth < 80
                || visibleHeight < 40
                || bounds.yMin < allowedBounds.yMin
                || bounds.yMin >= allowedBounds.yMax)
                return true;
            result.Add(new ActionShowcaseDesktopWindow(window, bounds, titleBuffer.ToString()));
            return true;
            }
            catch (Exception ex)
            {
                Plugin.PluginLog.LogDebug(
                    $"Skipped desktop window 0x{window.ToInt64():X} after enumeration error: {ex.Message}");
                return true;
            }
        };
        EnumerateActionShowcaseWindows(callback, IntPtr.Zero);
        GC.KeepAlive(callback);
        return result;
    }

    private static List<ActionShowcaseDesktopWindow> EnumerateActionShowcasePlatformWindows()
    {
        var windows = EnumerateActionShowcaseDesktopWindows();
        var result = new List<ActionShowcaseDesktopWindow>();
        var allowedBounds = PlatformService.Current.GetVirtualScreenBounds();
        if (allowedBounds.width <= 0 || allowedBounds.height <= 0)
            return result;
        for (var i = 0; i < windows.Count; i++)
        {
            var source = windows[i];
            var topY = source.Bounds.yMin;
            var left = Math.Max(source.Bounds.xMin, allowedBounds.xMin);
            var right = Math.Min(source.Bounds.xMax, allowedBounds.xMax);
            var bottom = Math.Min(source.Bounds.yMax, allowedBounds.yMax);
            if (right - left < 80 || bottom - topY < 40)
                continue;

            var visibleSegments = new List<(int Left, int Right)> { (left, right) };
            for (var frontIndex = 0; frontIndex < i && visibleSegments.Count > 0; frontIndex++)
            {
                var front = windows[frontIndex].Bounds;
                // Window frame tops that differ by only a few DWM pixels are
                // visually coplanar.  In their overlap, the front HWND owns the
                // usable surface even if the back window protrudes 1-6 px higher.
                if (front.yMin > topY + ActionShowcaseTopOcclusionTolerancePixels
                    || front.yMax <= topY)
                    continue;
                var cutLeft = Math.Max(front.xMin, allowedBounds.xMin);
                var cutRight = Math.Min(front.xMax, allowedBounds.xMax);
                if (cutRight <= cutLeft)
                    continue;

                var remaining = new List<(int Left, int Right)>();
                foreach (var segment in visibleSegments)
                {
                    if (cutRight <= segment.Left || cutLeft >= segment.Right)
                    {
                        remaining.Add(segment);
                        continue;
                    }
                    if (cutLeft - segment.Left >= 80)
                        remaining.Add((segment.Left, cutLeft));
                    if (segment.Right - cutRight >= 80)
                        remaining.Add((cutRight, segment.Right));
                }
                visibleSegments = remaining;
            }

            if (visibleSegments.Count == 0)
                continue;
            var best = visibleSegments
                .OrderByDescending(segment => segment.Right - segment.Left)
                .First();
            result.Add(new ActionShowcaseDesktopWindow(
                source.Handle,
                new RectInt(best.Left, topY, best.Right - best.Left, bottom - topY),
                source.Title));
        }
        return result;
    }

    private static bool BeginActionShowcaseSnap(global::CharacterController character, LilithStateManager state)
    {
        var duration = 1f;
        if (state.TryGetActionDuration(LilithActionType.Snap, out var detectedDuration) && detectedDuration > 0f)
            duration = detectedDuration;
        var operationOffset = Math.Clamp(
            duration * 0.72f,
            0.25f,
            Math.Max(0.25f, duration - 0.08f));
        _actionShowcasePendingAt = Time.unscaledTime + operationOffset;
        _actionShowcaseSnapEndsAt = Time.unscaledTime + duration + 0.08f;
        if (state.HasActionAnimation(LilithActionType.Snap))
        {
            character.PlayLilithAction(LilithActionType.Snap, true, null);
            Plugin.PluginLog.LogInfo(
                $"Exploration Snap scheduled its hidden-phase operation at {operationOffset:F3}s of {duration:F3}s.");
            return true;
        }

        _actionShowcasePendingAt = Time.unscaledTime;
        _actionShowcaseSnapEndsAt = Time.unscaledTime;
        return false;
    }

    private static void CompletePendingActionShowcaseOperation(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (_actionShowcasePendingOperation == ActionShowcasePendingOperation.None || Time.unscaledTime < _actionShowcasePendingAt)
            return;

        var operation = _actionShowcasePendingOperation;
        var description = _actionShowcasePendingDescription;
        var showFeedback = _actionShowcasePendingShowFeedback;
        var snapTransitionOperation = operation == ActionShowcasePendingOperation.ApplyScale
            || operation == ActionShowcasePendingOperation.MoveToWindow
            || operation == ActionShowcasePendingOperation.MoveToWindowThenSit
            || operation == ActionShowcasePendingOperation.SitAfterWindowMove
            || operation == ActionShowcasePendingOperation.PrepareWindowPeekAfterSnap
            || operation == ActionShowcasePendingOperation.StartWindowPeekAfterSnap
            || operation == ActionShowcasePendingOperation.BeginWindowPeekReturnSnap
            || operation == ActionShowcasePendingOperation.RestoreWindowPeekDuringSnap;
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
        _actionShowcasePendingAt = -1f;
        _actionShowcasePendingDescription = string.Empty;
        _actionShowcasePendingShowFeedback = true;

        switch (operation)
        {
            case ActionShowcasePendingOperation.ApplyScale:
                ApplyActionShowcaseScale(state, _actionShowcasePendingScaleFraction);
                Plugin.PluginLog.LogInfo($"Exploration showcase applied scale fraction {_actionShowcasePendingScaleFraction:F3}.");
                break;
            case ActionShowcasePendingOperation.MoveToWindow:
                MoveActionShowcaseToWindow(state, _actionShowcasePendingWindowTop, _actionShowcasePendingWindowBounds);
                Plugin.PluginLog.LogInfo("Exploration showcase moved the character to the selected window platform.");
                break;
            case ActionShowcasePendingOperation.MoveToWindowThenSit:
            {
                MoveActionShowcaseToWindow(state, _actionShowcasePendingWindowTop, _actionShowcasePendingWindowBounds);
                HoldActionShowcaseWindowSitSnapPose(state);
                _actionShowcasePendingOperation = ActionShowcasePendingOperation.SitAfterWindowMove;
                // _actionShowcaseSnapEndsAt includes an 80 ms generic tail guard.
                // Keep the standing Snap pose with its feet on the window during
                // the hidden tail. Applying the seated root here lowers a still-
                // standing sprite by one sit offset and reveals half its body
                // inside the window. Enter the seated pose only at the real end.
                _actionShowcasePendingAt = Math.Max(
                    Time.unscaledTime + 0.05f,
                    _actionShowcaseSnapEndsAt - 0.08f);
                _actionShowcasePendingDescription = description;
                _actionShowcasePendingShowFeedback = showFeedback;
                Plugin.PluginLog.LogInfo(
                    $"Exploration showcase placed the Snap pose feet on its sit window and scheduled the seated state at the real Snap endpoint {_actionShowcasePendingAt:F3}.");
                break;
            }
            case ActionShowcasePendingOperation.SitAfterWindowMove:
            {
                ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
                var sitStarted = EnterActionShowcaseSitAtCurrentPosition(state);
                Plugin.PluginLog.LogInfo(
                    $"Exploration showcase completed its window-sit fallback; started={sitStarted}, handle=0x{_actionShowcaseWindowHandle.ToInt64():X}.");
                if (showFeedback)
                {
                    ShowActionShowcaseMessage(
                        manager,
                        sitStarted ? "響指抵達視窗，已坐下。" : "響指已抵達視窗，但原生坐姿仍取消。",
                        5f);
                }
                _actionShowcaseSnapEndsAt = -1f;
                break;
            }
            case ActionShowcasePendingOperation.PrepareWindowPeekAfterSnap:
            {
                if (!PrepareActionShowcaseWindowPeek(manager, character, state))
                {
                    Plugin.PluginLog.LogWarning(
                        "Exploration window peek cancelled because its hidden-phase preparation failed after Snap action 36.");
                    break;
                }

                _actionShowcasePendingOperation = ActionShowcasePendingOperation.StartWindowPeekAfterSnap;
                _actionShowcasePendingAt = Math.Max(
                    Time.unscaledTime + 0.05f,
                    _actionShowcaseSnapEndsAt - 0.08f);
                _actionShowcasePendingDescription = description;
                _actionShowcasePendingShowFeedback = showFeedback;
                Plugin.PluginLog.LogInfo(
                    $"Exploration window peek completed its hidden-phase placement and is waiting for the real Snap endpoint {_actionShowcasePendingAt:F3}.");
                break;
            }
            case ActionShowcasePendingOperation.StartWindowPeekAfterSnap:
            {
                if (!StartActionShowcaseWindowPeekAfterSnap(character, state, description))
                {
                    RestoreActionShowcaseWindowPeek(character, state);
                    Plugin.PluginLog.LogWarning(
                        "Exploration window peek cancelled and restored because ScreenPeek could not start after Snap action 36.");
                }
                _actionShowcaseSnapEndsAt = -1f;
                break;
            }
            case ActionShowcasePendingOperation.BeginWindowPeekReturnSnap:
            {
                if (!AgentMotionTransitionContract.RequiresSnapOnExit(MotionIntentKind.PeekFromWindow)
                    || !state.HasActionAnimation(LilithActionType.Snap))
                {
                    RestoreActionShowcaseWindowPeek(character, state);
                    Plugin.PluginLog.LogWarning(
                        "Exploration window peek return Snap was unavailable; the overlay was restored immediately as a safety fallback.");
                    break;
                }

                _actionShowcasePendingOperation = ActionShowcasePendingOperation.RestoreWindowPeekDuringSnap;
                _actionShowcasePendingDescription = description;
                _actionShowcasePendingShowFeedback = false;
                if (!BeginActionShowcaseSnap(character, state))
                {
                    _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
                    RestoreActionShowcaseWindowPeek(character, state);
                    Plugin.PluginLog.LogWarning(
                        "Exploration window peek return Snap could not start; the overlay was restored immediately as a safety fallback.");
                    break;
                }

                Plugin.PluginLog.LogInfo(
                    "Exploration window peek started its second Snap; window-top restoration is deferred to the hidden flash phase.");
                break;
            }
            case ActionShowcasePendingOperation.RestoreWindowPeekDuringSnap:
                RestoreActionShowcaseWindowPeek(character, state, preserveActiveAction: true);
                Plugin.PluginLog.LogInfo(
                    "Exploration showcase restored overlay order and window-top position during the hidden phase of its second Snap.");
                break;
        }

        if (_actionShowcasePendingOperation != ActionShowcasePendingOperation.SitAfterWindowMove
            && _actionShowcasePendingOperation != ActionShowcasePendingOperation.StartWindowPeekAfterSnap
            && _actionShowcasePendingOperation != ActionShowcasePendingOperation.RestoreWindowPeekDuringSnap)
            _actionShowcaseSnapEndsAt = -1f;

        // Scale/window Snap already displayed its message before starting the animation.
        // A second ForceSay here interrupts the native flash/disappearance tail.
        if (!snapTransitionOperation && showFeedback)
            ShowActionShowcaseMessage(manager, $"{description}（已套用）", 4f);
    }

    private static void ApplyActionShowcaseScale(LilithStateManager state, float targetFraction)
    {
        var hasBoundsBefore = TryGetActionShowcaseCharacterBounds(state, out var boundsBefore);
        LilithScreenScale.Apply(targetFraction, state.transform);
        Physics2D.SyncTransforms();
        if (hasBoundsBefore && TryGetActionShowcaseCharacterBounds(state, out var boundsAfter))
        {
            var position = state.transform.position;
            position.y += boundsBefore.min.y - boundsAfter.min.y;
            state.transform.position = position;
            Physics2D.SyncTransforms();
        }
        StopActionShowcasePhysics(state, markGrounded: true);
    }

    private static void MoveActionShowcaseToWindow(LilithStateManager state, Vector3 topCenter, Bounds windowBounds)
    {
        UpdateActionShowcaseDedicatedPlatform(
            _actionShowcaseWindowHandle,
            windowBounds,
            selected: true,
            state,
            forceVisibilityShape: true);
        RefreshActionShowcaseNativeWindowCollisionIsolation(state);
        var position = state.transform.position;
        if (TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            position.x = topCenter.x + (state.transform.position.x - characterBounds.center.x);
            position.y = topCenter.y + (state.transform.position.y - characterBounds.min.y) + 0.025f;
        }
        else
        {
            position.x = topCenter.x;
            position.y = topCenter.y + Math.Max(0.1f, state.CharacterHeightWorld * 0.5f);
        }
        state.transform.position = position;
        Physics2D.SyncTransforms();
        StopActionShowcasePhysics(state, markGrounded: true);
        _actionShowcaseWindowPlatformTop = topCenter;
        _actionShowcaseWindowPlatformBounds = windowBounds;
        _actionShowcaseHasWindowPlatform = true;
        _actionShowcaseSupportedWindowHandle = _actionShowcaseWindowHandle;
        _actionShowcaseSupportedWindowUntil = Time.unscaledTime
            + GetActionShowcaseSupportRecoveryDuration();
        RefreshActionShowcasePlatformCollisionRules(state);
    }

    private static void HoldActionShowcaseWindowSitSnapPose(LilithStateManager state)
    {
        var position = state.transform.position;
        Physics2D.SyncTransforms();
        StopActionShowcasePhysics(state, markGrounded: true);
        var feetY = TryGetActionShowcaseCharacterBounds(state, out var characterBounds)
            ? characterBounds.min.y
            : position.y;
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
        {
            _actionShowcasePendingSitBodyWasSimulated = body.simulated;
            body.simulated = false;
            _actionShowcasePendingSitPhysicsHeld = true;
        }
        Plugin.PluginLog.LogInfo(
            $"Exploration physics-held the hidden standing Snap pose on the window: position={position}, feetY={feetY:F3}, windowTopY={_actionShowcasePendingWindowTop.y:F3}, bodyHeld={_actionShowcasePendingSitPhysicsHeld}.");
    }

    private static void RestoreActionShowcasePendingSitPhysics(LilithStateManager state)
    {
        if (!_actionShowcasePendingSitPhysicsHeld)
            return;
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
        {
            body.position = state.transform.position;
            body.velocity = Vector2.zero;
            body.angularVelocity = 0f;
            body.simulated = _actionShowcasePendingSitBodyWasSimulated;
        }
        _actionShowcasePendingSitPhysicsHeld = false;
        _actionShowcasePendingSitBodyWasSimulated = false;
    }

    private static void MaintainActionShowcaseDedicatedPlatform(LilithStateManager state)
    {
        if ((!IsGlobalMotionPhysicsActive && !_actionShowcaseHasExplorationOrigin)
            || Time.unscaledTime < _actionShowcasePlatformRefreshAt)
            return;
        _actionShowcasePlatformRefreshAt = Time.unscaledTime + GetActionShowcasePlatformRefreshInterval();
        RefreshActionShowcaseNativeWindowCollisionIsolation(state);
        MaintainGlobalMotionGround(state);
        if (_actionShowcaseOverlayBehindWindow)
            return;
        RefreshActionShowcaseAllWindowPlatforms(state);
        if (IsGlobalMotionPhysicsActive
            && !_globalMotionPhysicsInventoryLogged
            && ActionShowcaseWindowPlatforms.Count > 0)
        {
            _globalMotionPhysicsInventoryLogged = true;
            Plugin.PluginLog.LogInfo(
                $"Global Motion Authority surface registry ready: modWindowSurfaces={ActionShowcaseWindowPlatforms.Count}, modVirtualGround={_globalMotionGroundCollider != null && _globalMotionGroundCollider.enabled}, ignoredNativeWindowColliders={ActionShowcaseIgnoredNativeWindowColliders.Count}, refreshHz={1f / GetActionShowcasePlatformRefreshInterval():F0}. Native ceiling and outer side bounds remain physical.");
        }
        if (_actionShowcaseHasWindowPlatform && !RefreshActionShowcaseWindowPlatform())
            Plugin.PluginLog.LogDebug("Exploration target window is temporarily unavailable; retaining the last stable platform bounds.");
        RefreshActionShowcasePlatformCollisionRules(state);
        MaintainActionShowcaseWindowAttachment(state);
    }

    private static float GetActionShowcasePlatformRefreshInterval()
    {
        var refreshRate = 60;
        try
        {
            refreshRate = Screen.currentResolution.refreshRate;
        }
        catch
        {
            // Unity may briefly have no display information while the overlay is changing screens.
        }
        return 1f / Math.Clamp(refreshRate, 30, 240);
    }

    private static float GetActionShowcaseSupportRecoveryDuration() =>
        Math.Clamp(GetActionShowcasePlatformRefreshInterval() * 3f, 0.06f, 0.12f);

    private static void MaintainGlobalMotionGround(LilithStateManager state)
    {
        if (!IsGlobalMotionPhysicsActive)
        {
            DestroyGlobalMotionGround();
            return;
        }

        var nativeWindowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (nativeWindowColliders == null)
            return;

        if (_globalMotionGroundObject == null || _globalMotionGroundCollider == null)
        {
            GameObject? createdObject = null;
            try
            {
                createdObject = new GameObject(
                    "LilithMotionAuthorityVirtualDesktopGround",
                    Il2CppType.Of<BoxCollider2D>());
                var collider = createdObject.GetComponent<BoxCollider2D>();
                if (collider == null)
                    throw new InvalidOperationException("Required global ground collider was not created.");
                createdObject.hideFlags = HideFlags.HideAndDontSave;
                if (nativeWindowColliders.windowRigidLayer >= 0
                    && nativeWindowColliders.windowRigidLayer <= 31)
                {
                    createdObject.layer = nativeWindowColliders.windowRigidLayer;
                }
                collider.isTrigger = false;
                collider.usedByEffector = false;
                _globalMotionGroundObject = createdObject;
                _globalMotionGroundCollider = collider;
            }
            catch (Exception exception)
            {
                if (createdObject != null)
                {
                    createdObject.SetActive(false);
                    UnityEngine.Object.Destroy(createdObject);
                }
                _globalMotionGroundObject = null;
                _globalMotionGroundCollider = null;
                Plugin.PluginLog.LogError(
                    $"Global Motion Authority ground creation failed safely: {exception.Message}");
                return;
            }
        }

        var visibleLeft = nativeWindowColliders.GetVisibleLeftWorldX();
        var visibleRight = nativeWindowColliders.GetVisibleRightWorldX();
        var groundTop = nativeWindowColliders.GetGroundTopWorldY();
        if (float.IsNaN(visibleLeft)
            || float.IsNaN(visibleRight)
            || float.IsNaN(groundTop)
            || float.IsInfinity(visibleLeft)
            || float.IsInfinity(visibleRight)
            || float.IsInfinity(groundTop)
            || visibleRight <= visibleLeft + 0.05f)
        {
            _globalMotionGroundCollider.enabled = false;
            return;
        }

        // Preserve the native desktop top line, but extend the solid volume far
        // below it. The former 8-16 cm strip could be crossed in one Discrete
        // physics step after a scripted native action released the Rigidbody.
        var stripHeight = Math.Max(4f, state.CharacterHeightWorld * 3f);
        var horizontalGuard = Math.Max(2f, state.CharacterHeightWorld * 2f);
        _globalMotionGroundObject.transform.position = new Vector3(
            (visibleLeft + visibleRight) * 0.5f,
            groundTop - stripHeight * 0.5f,
            0f);
        _globalMotionGroundObject.transform.localScale = Vector3.one;
        _globalMotionGroundCollider.offset = Vector2.zero;
        _globalMotionGroundCollider.size = new Vector2(
            visibleRight - visibleLeft + horizontalGuard * 2f,
            stripHeight);
        _globalMotionGroundCollider.enabled = true;
        RecoverGlobalMotionCharacterBelowGround(
            state,
            visibleLeft,
            visibleRight,
            groundTop);
    }

    private static void DestroyGlobalMotionGround()
    {
        if (_globalMotionGroundObject != null)
            UnityEngine.Object.Destroy(_globalMotionGroundObject);
        _globalMotionGroundObject = null;
        _globalMotionGroundCollider = null;
        _globalMotionBelowGroundSince = -1f;
        _globalMotionBelowGroundRecoveryCooldownUntil = -1f;
    }

    private static bool BeginNativeScreenPeekLifecycle(
        global::CharacterController character,
        LilithStateManager state)
    {
        CancelNativeScreenPeekRecovery();
        var body = state.GetComponent<Rigidbody2D>();
        _nativeScreenPeekMovementWasDisabled = GetActionShowcaseMovementDisabled(character);
        if (body != null)
        {
            _nativeScreenPeekBodyConstraints = body.constraints;
            _nativeScreenPeekBodyCollisionMode = body.collisionDetectionMode;
            _nativeScreenPeekBodyGravityScale = body.gravityScale;
        }

        _nativeScreenPeekRevealCompletedCallback ??=
            DelegateSupport.ConvertDelegate<Il2CppSystem.Action>(
                new System.Action(OnNativeScreenPeekRevealCompleted));
        _nativeScreenPeekEndCompletedCallback ??=
            DelegateSupport.ConvertDelegate<Il2CppSystem.Action>(
                new System.Action(OnNativeScreenPeekEndCompleted));

        _nativeScreenPeekRecoveryActive = true;
        _nativeScreenPeekStartedAt = Time.unscaledTime;
        try
        {
            var started = character.PlayScreenPeekFromLeft(_nativeScreenPeekRevealCompletedCallback);
            if (!started)
                CancelNativeScreenPeekRecovery();
            return started;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Native ScreenPeek could not start: {exception.Message}");
            CancelNativeScreenPeekRecovery();
            return false;
        }
    }

    private static void OnNativeScreenPeekRevealCompleted()
    {
        if (!_nativeScreenPeekRecoveryActive || _nativeScreenPeekEnding)
            return;
        _nativeScreenPeekEnding = true;
        try
        {
            var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
            if (character == null)
            {
                _nativeScreenPeekEndCompleted = true;
                return;
            }
            character.PlayPeekEnd(_nativeScreenPeekEndCompletedCallback);
            Plugin.PluginLog.LogInfo(
                "Native ScreenPeek reveal completed; started its matching native exit animation.");
        }
        catch (Exception exception)
        {
            _nativeScreenPeekEndCompleted = true;
            Plugin.PluginLog.LogWarning(
                $"Native ScreenPeek exit animation could not start; recovery will finish safely: {exception.Message}");
        }
    }

    private static void OnNativeScreenPeekEndCompleted()
    {
        if (_nativeScreenPeekRecoveryActive)
            _nativeScreenPeekEndCompleted = true;
    }

    private static void UpdateNativeScreenPeekRecovery()
    {
        if (!_nativeScreenPeekRecoveryActive)
            return;

        var elapsed = Time.unscaledTime - _nativeScreenPeekStartedAt;
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        if (state == null || character == null)
        {
            if (elapsed >= 12f)
                CancelNativeScreenPeekRecovery();
            return;
        }

        var animationName = state.SkeletonAnimation?.AnimationName ?? string.Empty;
        var screenPeekVisualActive = animationName.IndexOf(
            "screen_peek",
            StringComparison.OrdinalIgnoreCase) >= 0;
        if (!screenPeekVisualActive && elapsed >= 0.25f)
        {
            if (_nativeScreenPeekVisuallyEndedAt < 0f)
                _nativeScreenPeekVisuallyEndedAt = Time.unscaledTime;
        }
        else
        {
            _nativeScreenPeekVisuallyEndedAt = -1f;
        }

        var visualTerminalStable = _nativeScreenPeekVisuallyEndedAt >= 0f
            && Time.unscaledTime - _nativeScreenPeekVisuallyEndedAt
                >= GetActionShowcaseSupportRecoveryDuration();
        if (_nativeScreenPeekEndCompleted
            || (_nativeScreenPeekEnding && visualTerminalStable)
            || elapsed >= 12f)
        {
            CompleteNativeScreenPeekRecovery(
                character,
                state,
                elapsed >= 12f ? "terminal-timeout" : "native-animation-complete");
        }
    }

    private static void CompleteNativeScreenPeekRecovery(
        global::CharacterController character,
        LilithStateManager state,
        string reason)
    {
        try
        {
            character.RestorePeekColliderSizes();
            character.ExitPeekToIdle();
            SetActionShowcaseMovementDisabled(character, _nativeScreenPeekMovementWasDisabled);

            var body = state.GetComponent<Rigidbody2D>();
            if (body != null)
            {
                body.simulated = true;
                body.constraints = _nativeScreenPeekBodyConstraints;
                body.collisionDetectionMode = _nativeScreenPeekBodyCollisionMode;
                body.gravityScale = _nativeScreenPeekBodyGravityScale;
                body.position = state.transform.position;
                body.angularVelocity = 0f;
            }

            Physics2D.SyncTransforms();
            var nativeGround = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
            var grounded = nativeGround != null
                && TryGetActionShowcaseCharacterBounds(state, out var bounds)
                && Math.Abs(bounds.min.y - nativeGround.GetGroundTopWorldY())
                    <= Math.Max(0.12f, state.CharacterHeightWorld * 0.04f);
            state.IsGround = grounded;
            character.IsGround = grounded;
            if (body != null)
            {
                body.velocity = grounded
                    ? Vector2.zero
                    : new Vector2(body.velocity.x, Math.Min(body.velocity.y, -0.1f));
            }
            Plugin.PluginLog.LogInfo(
                $"Native ScreenPeek handed back to global physics: reason={reason}, grounded={grounded}, position={state.transform.position}.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Native ScreenPeek recovery encountered an error; below-ground rescue remains active: {exception.Message}");
        }
        finally
        {
            CancelNativeScreenPeekRecovery();
        }
    }

    private static void CancelNativeScreenPeekRecovery()
    {
        _nativeScreenPeekRecoveryActive = false;
        _nativeScreenPeekEnding = false;
        _nativeScreenPeekEndCompleted = false;
        _nativeScreenPeekStartedAt = -1f;
        _nativeScreenPeekVisuallyEndedAt = -1f;
    }

    private static void RecoverGlobalMotionCharacterBelowGround(
        LilithStateManager state,
        float visibleLeft,
        float visibleRight,
        float groundTop)
    {
        if (state.IsDrag
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcasePendingOperation != ActionShowcasePendingOperation.None
            || Time.unscaledTime < _globalMotionBelowGroundRecoveryCooldownUntil
            || !TryGetActionShowcaseCharacterBounds(state, out var bounds))
        {
            _globalMotionBelowGroundSince = -1f;
            return;
        }

        // A character centre below the desktop line is never a valid resting or
        // throw state. Requiring sustained, deep penetration avoids touching the
        // tiny overlap produced by Unity's ordinary contact solver.
        var invalidDepth = groundTop - bounds.center.y;
        var minimumInvalidDepth = Math.Max(0.2f, state.CharacterHeightWorld * 0.08f);
        if (invalidDepth <= minimumInvalidDepth)
        {
            _globalMotionBelowGroundSince = -1f;
            return;
        }

        if (_globalMotionBelowGroundSince < 0f)
        {
            _globalMotionBelowGroundSince = Time.unscaledTime;
            return;
        }
        if (Time.unscaledTime - _globalMotionBelowGroundSince
            < GetActionShowcaseSupportRecoveryDuration())
        {
            return;
        }

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var from = state.transform.position;
        try
        {
            if (character != null)
            {
                character.RestorePeekColliderSizes();
                character.ExitPeekToIdle();
                SetActionShowcaseMovementDisabled(character, false);
            }

            // ExitPeekToIdle may alter native state, but recovery itself preserves
            // the last horizontal position instead of resetting to screen centre.
            var afterNativeExit = state.transform.position;
            state.transform.position = new Vector3(from.x, afterNativeExit.y, from.z);
            Physics2D.SyncTransforms();
            if (!TryGetActionShowcaseCharacterBounds(state, out bounds))
                return;

            var target = state.transform.position;
            target.y += groundTop + Math.Max(0.02f, state.CharacterHeightWorld * 0.006f)
                - bounds.min.y;
            var inset = Math.Max(0.03f, state.CharacterHeightWorld * 0.01f);
            if (bounds.size.x >= visibleRight - visibleLeft - inset * 2f)
            {
                target.x += (visibleLeft + visibleRight) * 0.5f - bounds.center.x;
            }
            else
            {
                if (bounds.min.x < visibleLeft + inset)
                    target.x += visibleLeft + inset - bounds.min.x;
                if (bounds.max.x > visibleRight - inset)
                    target.x -= bounds.max.x - (visibleRight - inset);
            }

            state.transform.position = target;
            Physics2D.SyncTransforms();
            var body = state.GetComponent<Rigidbody2D>();
            if (body != null)
            {
                body.simulated = true;
                body.position = target;
                body.velocity = Vector2.zero;
                body.angularVelocity = 0f;
                body.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
            }
            state.ReturnIdle();
            state.IsGround = true;
            if (character != null)
                character.IsGround = true;
            _globalMotionBelowGroundRecoveryCooldownUntil = Time.unscaledTime + 0.35f;
            Plugin.PluginLog.LogWarning(
                $"Global Motion Authority recovered a confirmed below-ground state without a centre reset: depth={invalidDepth:F2}, from={from}, to={target}.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Global Motion Authority below-ground recovery failed safely: {exception.Message}");
        }
        finally
        {
            _globalMotionBelowGroundSince = -1f;
        }
    }

    private static void UpdateActionShowcaseDedicatedPlatform(
        IntPtr handle,
        Bounds windowBounds,
        bool selected,
        LilithStateManager state,
        bool forceVisibilityShape = false)
    {
        if (handle == IntPtr.Zero)
            return;
        if (!ActionShowcaseWindowPlatforms.TryGetValue(handle, out var platform)
            || platform.Object == null
            || platform.Collider == null)
        {
            GameObject? createdObject = null;
            try
            {
                createdObject = new GameObject(
                    $"LilithExplorationWindowPlatform_{handle.ToInt64():X}",
                    Il2CppType.Of<BoxCollider2D>());
                var collider = createdObject.GetComponent<BoxCollider2D>();
                if (collider == null)
                    throw new InvalidOperationException("Required platform collider was not created.");

                platform = new ActionShowcaseWindowPlatform
                {
                    Handle = handle,
                    Object = createdObject,
                    Collider = collider
                };
                platform.Object.hideFlags = HideFlags.HideAndDontSave;
                var nativeWindowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
                if (nativeWindowColliders != null
                    && nativeWindowColliders.windowRigidLayer >= 0
                    && nativeWindowColliders.windowRigidLayer <= 31)
                    platform.Object.layer = nativeWindowColliders.windowRigidLayer;
                platform.Collider.isTrigger = false;
                platform.Collider.usedByEffector = false;
                ActionShowcaseWindowPlatforms[handle] = platform;
            }
            catch (Exception ex)
            {
                if (createdObject != null)
                {
                    createdObject.SetActive(false);
                    UnityEngine.Object.Destroy(createdObject);
                }
                Plugin.PluginLog.LogError(
                    $"Exploration platform creation failed safely for handle=0x{handle.ToInt64():X}: {ex.Message}");
                return;
            }
        }

        var motionBounds = windowBounds;
        if (TryGetActionShowcaseDesktopWindowBounds(handle, out var desktopMotionBounds)
            && TryConvertDesktopRectToWorld(desktopMotionBounds, state.transform, out var convertedMotionBounds))
            motionBounds = convertedMotionBounds;
        windowBounds = StabilizeActionShowcaseVisibilityShape(
            platform,
            windowBounds,
            motionBounds,
            forceVisibilityShape);

        var stripHeight = Math.Clamp(state.CharacterHeightWorld * 0.03f, 0.06f, 0.12f);
        // Native walking probes two world units sideways for obstacles. Keep the
        // thin platform's vertical end caps beyond that probe while retaining
        // WindowBounds as the authoritative support area.
        var sideProbePadding = 2f
            + Math.Clamp(state.CharacterHeightWorld * 0.06f, 0.12f, 0.3f);
        platform.Object.transform.position = new Vector3(
            windowBounds.center.x,
            windowBounds.max.y - stripHeight * 0.5f,
            0f);
        platform.Object.transform.localScale = Vector3.one;
        platform.Collider.offset = Vector2.zero;
        platform.Collider.size = new Vector2(
            Math.Max(0.02f, windowBounds.size.x + sideProbePadding * 2f),
            stripHeight);
        platform.Collider.enabled = platform.CollisionRulesInitialized
            && !_actionShowcaseOverlayBehindWindow;
        platform.WindowBounds = windowBounds;
        platform.MotionBounds = motionBounds;
        platform.Seen = true;
        platform.LastSeenAt = Time.unscaledTime;
        if (selected)
        {
            _actionShowcasePlatformObject = platform.Object;
            _actionShowcasePlatformCollider = platform.Collider;
        }
    }

    private static Bounds StabilizeActionShowcaseVisibilityShape(
        ActionShowcaseWindowPlatform platform,
        Bounds candidateBounds,
        Bounds motionBounds,
        bool force)
    {
        if (motionBounds.size.x <= 0.01f)
            return candidateBounds;

        var candidateLeftRatio = Math.Clamp(
            (candidateBounds.min.x - motionBounds.min.x) / motionBounds.size.x,
            0f,
            1f);
        var candidateRightRatio = Math.Clamp(
            (candidateBounds.max.x - motionBounds.min.x) / motionBounds.size.x,
            candidateLeftRatio,
            1f);
        const float ratioTolerance = 0.004f;
        if (force || !platform.VisibilityShapeInitialized)
        {
            platform.VisibilityShapeInitialized = true;
            platform.VisibleLeftRatio = candidateLeftRatio;
            platform.VisibleRightRatio = candidateRightRatio;
            platform.PendingVisibilitySamples = 0;
            platform.LastVisibilitySampleAt = Time.unscaledTime;
            return candidateBounds;
        }

        var matchesApplied = Math.Abs(candidateLeftRatio - platform.VisibleLeftRatio) <= ratioTolerance
            && Math.Abs(candidateRightRatio - platform.VisibleRightRatio) <= ratioTolerance;
        if (matchesApplied)
        {
            platform.VisibleLeftRatio = candidateLeftRatio;
            platform.VisibleRightRatio = candidateRightRatio;
            platform.PendingVisibilitySamples = 0;
            platform.LastVisibilitySampleAt = Time.unscaledTime;
            return candidateBounds;
        }

        var matchesPending = platform.PendingVisibilitySamples > 0
            && Math.Abs(candidateLeftRatio - platform.PendingVisibleLeftRatio) <= ratioTolerance
            && Math.Abs(candidateRightRatio - platform.PendingVisibleRightRatio) <= ratioTolerance;
        if (!matchesPending)
        {
            platform.PendingVisibleLeftRatio = candidateLeftRatio;
            platform.PendingVisibleRightRatio = candidateRightRatio;
            platform.PendingVisibilitySamples = 1;
            platform.LastVisibilitySampleAt = Time.unscaledTime;
        }
        else if (Time.unscaledTime - platform.LastVisibilitySampleAt
            >= GetActionShowcasePlatformRefreshInterval() * 0.5f)
        {
            platform.PendingVisibilitySamples++;
            platform.LastVisibilitySampleAt = Time.unscaledTime;
        }

        if (platform.PendingVisibilitySamples >= 3)
        {
            var previousLeft = platform.VisibleLeftRatio;
            var previousRight = platform.VisibleRightRatio;
            platform.VisibleLeftRatio = candidateLeftRatio;
            platform.VisibleRightRatio = candidateRightRatio;
            platform.PendingVisibilitySamples = 0;
            Plugin.PluginLog.LogInfo(
                $"Exploration committed stable visible-platform topology: handle=0x{platform.Handle.ToInt64():X}, ratios=({previousLeft:F3},{previousRight:F3})->({candidateLeftRatio:F3},{candidateRightRatio:F3}).");
            return candidateBounds;
        }

        var stableMinimumX = Mathf.Lerp(
            motionBounds.min.x,
            motionBounds.max.x,
            platform.VisibleLeftRatio);
        var stableMaximumX = Mathf.Lerp(
            motionBounds.min.x,
            motionBounds.max.x,
            platform.VisibleRightRatio);
        return new Bounds(
            new Vector3(
                (stableMinimumX + stableMaximumX) * 0.5f,
                candidateBounds.center.y,
                candidateBounds.center.z),
            new Vector3(
                Math.Max(0.02f, stableMaximumX - stableMinimumX),
                candidateBounds.size.y,
                candidateBounds.size.z));
    }

    private static void RefreshActionShowcaseAllWindowPlatforms(LilithStateManager state)
    {
        ActionShowcaseWindowPlatform? standingPlatform = null;
        var standingPlatformMotionBounds = default(Bounds);
        var standingPlatformUpdatedAt = Time.unscaledTime;
        var recoveredSupport = false;
        if (!_actionShowcaseAttachedToWindow
            && !state.IsDrag)
        {
            var body = state.GetComponent<Rigidbody2D>();
            var canRidePlatform = body == null || body.velocity.y <= 0.15f;
            if (canRidePlatform
                && TryFindActionShowcasePlatformUnderCharacter(state, out var detectedPlatform)
                && detectedPlatform != null
                && (state.IsGround
                    || (detectedPlatform.Handle == _actionShowcaseSupportedWindowHandle
                        && Time.unscaledTime <= _actionShowcaseSupportedWindowUntil)))
            {
                standingPlatform = detectedPlatform;
                recoveredSupport = !state.IsGround;
            }
            else if (canRidePlatform
                && Time.unscaledTime <= _actionShowcaseSupportedWindowUntil
                && ActionShowcaseWindowPlatforms.TryGetValue(
                    _actionShowcaseSupportedWindowHandle,
                    out var rememberedPlatform)
                && IsActionShowcaseSupportRecoveryEligible(state, rememberedPlatform))
            {
                standingPlatform = rememberedPlatform;
                recoveredSupport = true;
            }

            if (standingPlatform != null)
            {
                standingPlatformMotionBounds = standingPlatform.MotionBounds;
                standingPlatformUpdatedAt = standingPlatform.LastSeenAt;
                _actionShowcaseSupportedWindowHandle = standingPlatform.Handle;
                _actionShowcaseSupportedWindowUntil = Time.unscaledTime
                    + GetActionShowcaseSupportRecoveryDuration();
            }
            else if (state.IsDrag
                || (body != null && body.velocity.y > 0.15f)
                || Time.unscaledTime > _actionShowcaseSupportedWindowUntil)
            {
                if (!state.IsDrag && (body == null || body.velocity.y <= 0.15f))
                    ReleaseActionShowcaseWindowRideMomentum(state, "support lost");
                ClearActionShowcaseStandingPlatformMemory();
            }
        }
        else if (_actionShowcaseAttachedToWindow || state.IsDrag)
            ClearActionShowcaseStandingPlatformMemory();

        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
            platform.Seen = false;

        var windows = EnumerateActionShowcasePlatformWindows();
        for (var i = 0; i < windows.Count; i++)
        {
            var window = windows[i];
            if (!TryConvertDesktopRectToWorld(window.Bounds, state.transform, out var windowBounds))
                continue;
            UpdateActionShowcaseDedicatedPlatform(
                window.Handle,
                windowBounds,
                window.Handle == _actionShowcaseWindowHandle,
                state);
        }

        // A foreground-order change can replace the visible surface underneath
        // Lilith without moving either HWND.  Resolve the new owner before the old
        // collider is disabled so walking never observes a one-frame support gap.
        if (standingPlatform != null
            && TryFindActionShowcasePlatformUnderCharacter(state, out var resolvedPlatform)
            && resolvedPlatform != null
            && resolvedPlatform.Handle != standingPlatform.Handle)
        {
            var previousHandle = standingPlatform.Handle;
            standingPlatform = resolvedPlatform;
            standingPlatformMotionBounds = resolvedPlatform.MotionBounds;
            standingPlatformUpdatedAt = Time.unscaledTime;
            recoveredSupport = true;
            _actionShowcaseSupportedWindowHandle = resolvedPlatform.Handle;
            _actionShowcaseSupportedWindowUntil = Time.unscaledTime
                + GetActionShowcaseSupportRecoveryDuration();
            state.IsGround = true;
            Plugin.PluginLog.LogInfo(
                $"Exploration transferred support across a visible-platform topology change: 0x{previousHandle.ToInt64():X}->0x{resolvedPlatform.Handle.ToInt64():X}.");
        }

        var staleHandles = ActionShowcaseWindowPlatforms
            .Where(pair => !pair.Value.Seen
                && Time.unscaledTime - pair.Value.LastSeenAt > 0.35f)
            .Select(pair => pair.Key)
            .ToArray();
        foreach (var handle in staleHandles)
        {
            var platform = ActionShowcaseWindowPlatforms[handle];
            if (platform.Object != null)
                UnityEngine.Object.Destroy(platform.Object);
            ActionShowcaseWindowPlatforms.Remove(handle);
        }

        if (standingPlatform != null
            && ActionShowcaseWindowPlatforms.TryGetValue(standingPlatform.Handle, out var updatedPlatform))
        {
            var delta = CalculateActionShowcaseWindowMotionDelta(
                standingPlatformMotionBounds,
                updatedPlatform.MotionBounds);
            var elapsed = Math.Max(0.001f, Time.unscaledTime - standingPlatformUpdatedAt);
            if (TryLaunchActionShowcaseFromRisingWindow(state, delta, elapsed, standingPlatform.Handle))
            {
                ClearActionShowcaseStandingPlatformMemory();
            }
            else
            {
                var horizontalRideDelta = CalculateActionShowcaseWindowRideHorizontalDelta(
                    state,
                    standingPlatform.Handle,
                    delta.x,
                    elapsed);
                var rideDelta = new Vector3(horizontalRideDelta, delta.y, 0f);
                if (rideDelta.sqrMagnitude > 0.000001f)
                {
                    state.transform.position += rideDelta;
                    StopActionShowcasePhysics(state, markGrounded: true);
                    _actionShowcaseSupportedWindowHandle = standingPlatform.Handle;
                    _actionShowcaseSupportedWindowUntil = Time.unscaledTime
                        + GetActionShowcaseSupportRecoveryDuration();
                }
                else if (recoveredSupport)
                {
                    StopActionShowcasePhysics(state, markGrounded: true);
                    _actionShowcaseSupportedWindowUntil = Time.unscaledTime
                        + GetActionShowcaseSupportRecoveryDuration();
                }
            }
        }
        UpdateActionShowcaseGroundSlide(state, standingPlatform);
        RefreshActionShowcaseLaunchLandingGate(state, standingPlatform);
        Physics2D.SyncTransforms();
    }

    private static void UpdateActionShowcaseGroundSlide(
        LilithStateManager state,
        ActionShowcaseWindowPlatform? standingPlatform)
    {
        if (state.IsDrag)
        {
            ClearActionShowcaseGroundSlide();
            return;
        }
        if (_actionShowcaseGroundSlidePending && state.IsGround)
        {
            _actionShowcaseGroundSlidePending = false;
            _actionShowcaseGroundSlideOnWindow = standingPlatform != null;
            _actionShowcaseGroundSlidePlatformHandle = standingPlatform?.Handle ?? IntPtr.Zero;
            _actionShowcaseGroundSlideVelocityX *= _actionShowcaseGroundSlideOnWindow
                ? 0.45f
                : 0.65f;
            _actionShowcaseGroundSlideActive = Math.Abs(_actionShowcaseGroundSlideVelocityX) >= 0.08f;
            _actionShowcaseGroundSlideLastAt = Time.unscaledTime;
            if (_actionShowcaseGroundSlideActive)
            {
                Plugin.PluginLog.LogInfo(
                    $"Exploration landing braking started: surface={(_actionShowcaseGroundSlideOnWindow ? "window" : "ground")}, velocityX={_actionShowcaseGroundSlideVelocityX:F2}.");
            }
        }
        if (!_actionShowcaseGroundSlideActive)
            return;
        if (!state.IsGround)
        {
            ClearActionShowcaseGroundSlide();
            return;
        }

        ActionShowcaseWindowPlatform? brakingPlatform = null;
        if (_actionShowcaseGroundSlideOnWindow
            && !ActionShowcaseWindowPlatforms.TryGetValue(
                _actionShowcaseGroundSlidePlatformHandle,
                out brakingPlatform))
        {
            ClearActionShowcaseGroundSlide();
            StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: -0.15f);
            return;
        }

        var deltaTime = Math.Clamp(
            Time.unscaledTime - _actionShowcaseGroundSlideLastAt,
            0f,
            0.05f);
        _actionShowcaseGroundSlideLastAt = Time.unscaledTime;
        if (deltaTime <= 0f || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return;

        var desiredCenterX = characterBounds.center.x
            + _actionShowcaseGroundSlideVelocityX * deltaTime;
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        var hitScreenEdge = false;
        if (windowColliders != null)
        {
            var minimumCenterX = windowColliders.GetVisibleLeftWorldX()
                + characterBounds.extents.x + 0.04f;
            var maximumCenterX = windowColliders.GetVisibleRightWorldX()
                - characterBounds.extents.x - 0.04f;
            var clampedCenterX = Math.Clamp(desiredCenterX, minimumCenterX, maximumCenterX);
            hitScreenEdge = Math.Abs(clampedCenterX - desiredCenterX) > 0.0001f;
            desiredCenterX = clampedCenterX;
        }

        var position = state.transform.position;
        position.x += desiredCenterX - characterBounds.center.x;
        state.transform.position = position;
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
        {
            body.position = position;
            body.velocity = Vector2.zero;
            body.angularVelocity = 0f;
        }
        state.IsGround = true;
        Physics2D.SyncTransforms();

        if (_actionShowcaseGroundSlideOnWindow)
        {
            var predictedMinimumX = desiredCenterX - characterBounds.extents.x;
            var predictedMaximumX = desiredCenterX + characterBounds.extents.x;
            var stillOverlapsPlatform = predictedMaximumX > brakingPlatform!.WindowBounds.min.x
                && predictedMinimumX < brakingPlatform.WindowBounds.max.x;
            if (!stillOverlapsPlatform)
            {
                Plugin.PluginLog.LogInfo(
                    $"Exploration window braking exited the platform: handle=0x{brakingPlatform.Handle.ToInt64():X}.");
                ClearActionShowcaseGroundSlide();
                StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: -0.15f);
                RefreshActionShowcasePlatformCollisionRules(state);
                return;
            }
        }

        var brakingDeceleration = _actionShowcaseGroundSlideOnWindow ? 5f : 7.5f;
        var remainingSpeed = Mathf.MoveTowards(
            Math.Abs(_actionShowcaseGroundSlideVelocityX),
            0f,
            brakingDeceleration * deltaTime);
        _actionShowcaseGroundSlideVelocityX = Math.Sign(_actionShowcaseGroundSlideVelocityX)
            * remainingSpeed;
        if (hitScreenEdge || remainingSpeed <= 0.02f)
        {
            Plugin.PluginLog.LogInfo(
                $"Exploration landing braking completed: surface={(_actionShowcaseGroundSlideOnWindow ? "window" : "ground")}, hitScreenEdge={hitScreenEdge}.");
            ClearActionShowcaseGroundSlide();
            StopActionShowcasePhysics(state, markGrounded: true);
        }
    }

    private static void ClearActionShowcaseGroundSlide()
    {
        _actionShowcaseGroundSlidePending = false;
        _actionShowcaseGroundSlideActive = false;
        _actionShowcaseGroundSlideOnWindow = false;
        _actionShowcaseGroundSlidePlatformHandle = IntPtr.Zero;
        _actionShowcaseGroundSlideVelocityX = 0f;
        _actionShowcaseGroundSlideLastAt = -1f;
    }

    internal static bool IsHorizontalFloorDragReleaseCandidate()
    {
        try
        {
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
            if (state == null
                || windowColliders == null
                || !state.IsDrag
                || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            {
                return false;
            }

            Physics2D.SyncTransforms();
            var floorTolerance = Math.Clamp(characterBounds.size.y * 0.08f, 0.08f, 0.16f);
            var touchesFloor = Math.Abs(
                characterBounds.min.y - windowColliders.GetGroundTopWorldY()) <= floorTolerance;
            if (!touchesFloor)
                return false;

            // A low window can be close to the taskbar.  Never apply floor friction
            // when a real desktop-window platform is supporting the character.
            return !TryFindActionShowcasePlatformUnderCharacter(state, out _);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogDebug(
                $"Could not classify a ground drag release: {exception.Message}");
            return false;
        }
    }

    private static bool TryGetMotionDesktopGroundWalkAvailability(
        LilithStateManager state,
        out bool canWalkLeft,
        out bool canWalkRight)
    {
        canWalkLeft = false;
        canWalkRight = false;
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (windowColliders == null
            || !state.IsGround
            || state.IsSit
            || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            return false;
        }

        Physics2D.SyncTransforms();
        var floorTolerance = Math.Clamp(characterBounds.size.y * 0.08f, 0.08f, 0.16f);
        var touchesFloor = Math.Abs(
            characterBounds.min.y - windowColliders.GetGroundTopWorldY()) <= floorTolerance;
        if (!touchesFloor || TryFindActionShowcasePlatformUnderCharacter(state, out _))
            return false;

        var edgeInset = GetActionShowcaseSafePlatformInset(characterBounds);
        var minimumCenterX = windowColliders.GetVisibleLeftWorldX()
            + characterBounds.extents.x
            + edgeInset;
        var maximumCenterX = windowColliders.GetVisibleRightWorldX()
            - characterBounds.extents.x
            - edgeInset;
        var minimumTravel = Math.Max(0.18f, characterBounds.size.x * 0.08f);
        canWalkLeft = characterBounds.center.x - minimumCenterX >= minimumTravel;
        canWalkRight = maximumCenterX - characterBounds.center.x >= minimumTravel;
        return maximumCenterX >= minimumCenterX;
    }

    private static bool PlayMotionIntentGroundWalk(
        global::CharacterController character,
        LilithStateManager state,
        bool walkLeft)
    {
        if (state.ClothingState == LilithClothingState.Pajamas
            || !TryGetMotionDesktopGroundWalkAvailability(
                state,
                out var canWalkLeft,
                out var canWalkRight)
            || (walkLeft ? !canWalkLeft : !canWalkRight))
        {
            return false;
        }

        ResetActionShowcaseCharacter(
            character,
            state,
            preserveWalkOrigin: true);
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (windowColliders == null
            || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            return false;
        }

        var edgeInset = GetActionShowcaseSafePlatformInset(characterBounds);
        var minimumCenterX = windowColliders.GetVisibleLeftWorldX()
            + characterBounds.extents.x
            + edgeInset;
        var maximumCenterX = windowColliders.GetVisibleRightWorldX()
            - characterBounds.extents.x
            - edgeInset;
        var offset = Math.Clamp(state.CharacterHeightWorld * 0.75f, 0.5f, 3f);
        var desiredCenterX = Math.Clamp(
            characterBounds.center.x + (walkLeft ? -offset : offset),
            minimumCenterX,
            maximumCenterX);
        var targetRootX = desiredCenterX
            + (state.transform.position.x - characterBounds.center.x);
        var minimumTravel = Math.Max(0.18f, characterBounds.size.x * 0.08f);
        if (Math.Abs(targetRootX - state.transform.position.x) < minimumTravel)
            return false;

        state.ClearWalkTarget();
        var started = state.EnterWalkToX(targetRootX, 0.15f);
        Plugin.PluginLog.LogInfo(
            $"Motion intent ground walk: direction={(walkLeft ? "left" : "right")}, started={started}, targetX={targetRootX:F3}, centerRange=({minimumCenterX:F3}, {maximumCenterX:F3}), safeInset={edgeInset:F3}.");
        return started;
    }

    private static void GetMotionWindowWalkAvailability(
        LilithStateManager state,
        out bool canWalkLeft,
        out bool canWalkRight)
    {
        canWalkLeft = false;
        canWalkRight = false;
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return;

        GetActionShowcaseConnectedSurfaceSpan(
            characterBounds,
            out var connectedMinimumX,
            out var connectedMaximumX,
            out _,
            out _,
            out _);
        var margin = GetActionShowcaseSafePlatformInset(characterBounds);
        var leftCenterX = connectedMinimumX + characterBounds.extents.x + margin;
        var rightCenterX = connectedMaximumX - characterBounds.extents.x - margin;
        const float minimumTravel = 0.1f;
        canWalkLeft = characterBounds.center.x - leftCenterX >= minimumTravel;
        canWalkRight = rightCenterX - characterBounds.center.x >= minimumTravel;
    }

    internal static void BrakeHorizontalFloorDragRelease(bool wasOnFloor)
    {
        if (!wasOnFloor)
            return;
        try
        {
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            var body = state?.GetComponent<Rigidbody2D>();
            if (state == null || body == null)
                return;

            var velocity = body.velocity;
            // This path is deliberately limited to a near-horizontal release.  An
            // upward or diagonal throw must retain both components unchanged.
            if (Math.Abs(velocity.x) < 0.08f || Math.Abs(velocity.y) > 0.65f)
                return;

            var dampedX = velocity.x * 0.58f;
            if (Math.Abs(dampedX) < 0.12f)
                dampedX = 0f;
            body.velocity = new Vector2(dampedX, velocity.y);
            Plugin.PluginLog.LogInfo(
                $"Applied floor-only horizontal drag-release braking: velocityX={velocity.x:F2}->{dampedX:F2}, velocityY={velocity.y:F2}.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogDebug(
                $"Could not brake a ground drag release: {exception.Message}");
        }
    }

    private static void RefreshActionShowcaseLaunchLandingGate(
        LilithStateManager state,
        ActionShowcaseWindowPlatform? standingPlatform)
    {
        if (!_actionShowcaseWindowLaunchAwaitingLanding)
            return;
        var stableOnWindowPlatform = standingPlatform != null
            && ActionShowcaseWindowPlatforms.ContainsKey(standingPlatform.Handle)
            && state.IsGround
            && !state.IsDrag;
        if (!stableOnWindowPlatform)
        {
            _actionShowcaseWindowLaunchLandedAt = -1f;
            if (state.IsGround && !state.IsDrag)
                RestoreActionShowcaseLaunchCollisionMode();
            return;
        }
        if (_actionShowcaseWindowLaunchLandedAt < 0f)
        {
            _actionShowcaseWindowLaunchLandedAt = Time.unscaledTime;
            return;
        }
        var rearmDebounce = Math.Clamp(
            GetActionShowcasePlatformRefreshInterval() * 4f,
            0.025f,
            0.05f);
        if (Time.unscaledTime - _actionShowcaseWindowLaunchLandedAt < rearmDebounce)
            return;

        _actionShowcaseWindowLaunchAwaitingLanding = false;
        _actionShowcaseWindowLaunchLandedAt = -1f;
        _actionShowcaseWindowLaunchCooldownUntil = -1f;
        ClearActionShowcaseRisingWindowGesture();
        RestoreActionShowcaseLaunchCollisionMode();
        Plugin.PluginLog.LogInfo(
            $"Exploration window launch rearmed after a debounced platform landing: handle=0x{standingPlatform!.Handle.ToInt64():X}, debounce={rearmDebounce:F3}, brakingActive={_actionShowcaseGroundSlideActive}.");
    }

    private static void ResetActionShowcaseLaunchLandingGate()
    {
        _actionShowcaseWindowLaunchAwaitingLanding = false;
        _actionShowcaseWindowLaunchLandedAt = -1f;
        _actionShowcaseWindowLaunchCooldownUntil = -1f;
        RestoreActionShowcaseLaunchCollisionMode();
        ClearActionShowcaseGroundSlide();
    }

    private static void CaptureActionShowcaseLaunchCollisionMode(Rigidbody2D body)
    {
        RestoreActionShowcaseLaunchCollisionMode();
        try
        {
            _actionShowcaseWindowLaunchBody = body;
            _actionShowcaseWindowLaunchOriginalCollisionMode = body.collisionDetectionMode;
            _actionShowcaseWindowLaunchCollisionModeCaptured = true;
            body.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
        }
        catch (Exception ex)
        {
            _actionShowcaseWindowLaunchBody = null;
            _actionShowcaseWindowLaunchCollisionModeCaptured = false;
            Plugin.PluginLog.LogWarning(
                $"Could not enable continuous collision detection for a window launch: {ex.Message}");
        }
    }

    private static void RestoreActionShowcaseLaunchCollisionMode()
    {
        if (_actionShowcaseWindowLaunchCollisionModeCaptured
            && _actionShowcaseWindowLaunchBody != null)
        {
            try
            {
                _actionShowcaseWindowLaunchBody.collisionDetectionMode =
                    _actionShowcaseWindowLaunchOriginalCollisionMode;
            }
            catch (Exception ex)
            {
                Plugin.PluginLog.LogDebug(
                    $"Could not restore the pre-launch collision detection mode: {ex.Message}");
            }
        }
        _actionShowcaseWindowLaunchBody = null;
        _actionShowcaseWindowLaunchCollisionModeCaptured = false;
    }

    private static bool IsActionShowcaseSupportRecoveryEligible(
        LilithStateManager state,
        ActionShowcaseWindowPlatform platform)
    {
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return false;
        var bounds = platform.WindowBounds;
        var overlapsHorizontally = characterBounds.max.x > bounds.min.x + 0.01f
            && characterBounds.min.x < bounds.max.x - 0.01f;
        var recoveryTolerance = Math.Max(0.18f, characterBounds.size.y * 0.15f);
        return overlapsHorizontally
            && Math.Abs(characterBounds.min.y - bounds.max.y) <= recoveryTolerance;
    }

    private static void ClearActionShowcaseStandingPlatformMemory()
    {
        _actionShowcaseSupportedWindowHandle = IntPtr.Zero;
        _actionShowcaseSupportedWindowUntil = -1f;
        ClearActionShowcaseWindowRideMotion();
        ClearActionShowcaseRisingWindowGesture();
    }

    private static float CalculateActionShowcaseWindowRideHorizontalDelta(
        LilithStateManager state,
        IntPtr platformHandle,
        float platformDeltaX,
        float elapsed)
    {
        elapsed = Math.Clamp(elapsed, 0.001f, 0.05f);
        var rawPlatformVelocity = Math.Clamp(platformDeltaX / elapsed, -14f, 14f);
        if (_actionShowcaseWindowRideHandle != platformHandle
            || _actionShowcaseWindowRideLastAt < 0f)
        {
            _actionShowcaseWindowRideHandle = platformHandle;
            _actionShowcaseWindowRideFilteredPlatformVelocityX = rawPlatformVelocity;
            _actionShowcaseWindowRideVelocityX = Math.Abs(rawPlatformVelocity) <= 2.2f
                ? rawPlatformVelocity
                : Math.Sign(rawPlatformVelocity) * 2.2f;
            _actionShowcaseWindowRideLastAt = Time.unscaledTime;
            return _actionShowcaseWindowRideVelocityX * elapsed;
        }

        var filterAlpha = 1f - Mathf.Exp(-elapsed / 0.03f);
        _actionShowcaseWindowRideFilteredPlatformVelocityX = Mathf.Lerp(
            _actionShowcaseWindowRideFilteredPlatformVelocityX,
            rawPlatformVelocity,
            filterAlpha);
        var desiredVelocity = Math.Abs(_actionShowcaseWindowRideFilteredPlatformVelocityX) < 0.04f
            ? 0f
            : _actionShowcaseWindowRideFilteredPlatformVelocityX;
        var maximumTractionAcceleration = Math.Max(14f, state.CharacterHeightWorld * 4.5f);
        var requestedAcceleration = Math.Abs(
            desiredVelocity - _actionShowcaseWindowRideVelocityX) / elapsed;
        var hasStaticGrip = Math.Abs(desiredVelocity) <= 1.6f
            && requestedAcceleration <= maximumTractionAcceleration * 1.35f;
        _actionShowcaseWindowRideVelocityX = hasStaticGrip
            ? desiredVelocity
            : Mathf.MoveTowards(
                _actionShowcaseWindowRideVelocityX,
                desiredVelocity,
                maximumTractionAcceleration * elapsed);
        _actionShowcaseWindowRideLastAt = Time.unscaledTime;

        var relativeSpeed = Math.Abs(
            desiredVelocity - _actionShowcaseWindowRideVelocityX);
        if (relativeSpeed >= 0.75f
            && Time.unscaledTime - _actionShowcaseWindowRideLastSlipLogAt >= 0.25f)
        {
            _actionShowcaseWindowRideLastSlipLogAt = Time.unscaledTime;
            Plugin.PluginLog.LogInfo(
                $"Exploration window ride is slipping: handle=0x{platformHandle.ToInt64():X}, platformVelocityX={desiredVelocity:F2}, characterVelocityX={_actionShowcaseWindowRideVelocityX:F2}, relativeSpeed={relativeSpeed:F2}.");
        }
        return _actionShowcaseWindowRideVelocityX * elapsed;
    }

    private static void ReleaseActionShowcaseWindowRideMomentum(
        LilithStateManager state,
        string reason)
    {
        if (_actionShowcaseWindowRideHandle == IntPtr.Zero
            || Math.Abs(_actionShowcaseWindowRideVelocityX) < 0.08f)
            return;
        var body = state.GetComponent<Rigidbody2D>();
        if (body == null)
            return;

        var releaseVelocityX = Math.Clamp(
            _actionShowcaseWindowRideVelocityX * 0.9f,
            -6f,
            6f);
        body.velocity = new Vector2(
            releaseVelocityX,
            Math.Min(body.velocity.y, -0.12f));
        body.angularVelocity = 0f;
        state.IsGround = false;
        _actionShowcaseGroundSlidePending = true;
        _actionShowcaseGroundSlideVelocityX = releaseVelocityX;
        Plugin.PluginLog.LogInfo(
            $"Exploration window ride released with momentum: reason={reason}, velocityX={releaseVelocityX:F2}.");
    }

    private static void ClearActionShowcaseWindowRideMotion()
    {
        _actionShowcaseWindowRideHandle = IntPtr.Zero;
        _actionShowcaseWindowRideVelocityX = 0f;
        _actionShowcaseWindowRideFilteredPlatformVelocityX = 0f;
        _actionShowcaseWindowRideLastAt = -1f;
        _actionShowcaseWindowRideLastSlipLogAt = -1f;
    }

    private static void ClearActionShowcaseRisingWindowGesture()
    {
        _actionShowcaseRisingWindowHandle = IntPtr.Zero;
        _actionShowcaseRisingWindowPeakSpeed = 0f;
        _actionShowcaseRisingWindowDistance = 0f;
        _actionShowcaseRisingWindowNetDistance = 0f;
        _actionShowcaseRisingWindowHorizontalSpeed = 0f;
        _actionShowcaseRisingWindowFilteredVerticalSpeed = 0f;
        _actionShowcaseRisingWindowSignificantSamples = 0;
        _actionShowcaseRisingWindowLastSignificantSampleAt = -1f;
        _actionShowcaseRisingWindowDownwardStartedAt = -1f;
        _actionShowcaseRisingWindowDownwardDistance = 0f;
        _actionShowcaseRisingWindowLastMotionAt = -1f;
    }

    private static Vector3 CalculateActionShowcaseWindowMotionDelta(Bounds oldBounds, Bounds newBounds)
    {
        if (oldBounds.size.x <= 0.01f
            || oldBounds.size.y <= 0.01f
            || newBounds.size.x <= 0.01f
            || newBounds.size.y <= 0.01f)
            return Vector3.zero;

        var leftDelta = newBounds.min.x - oldBounds.min.x;
        var rightDelta = newBounds.max.x - oldBounds.max.x;
        var translationTolerance = Math.Max(0.02f, oldBounds.size.x * 0.005f);
        var horizontalDelta = Math.Abs(leftDelta - rightDelta) <= translationTolerance
            ? (leftDelta + rightDelta) * 0.5f
            : 0f;
        var verticalDelta = newBounds.max.y - oldBounds.max.y;
        return new Vector3(horizontalDelta, verticalDelta, 0f);
    }

    private static bool TryLaunchActionShowcaseFromRisingWindow(
        LilithStateManager state,
        Vector3 platformDelta,
        float elapsed,
        IntPtr platformHandle)
    {
        if (_actionShowcaseWindowLaunchAwaitingLanding
            || Time.unscaledTime < _actionShowcaseWindowLaunchCooldownUntil
            || elapsed <= 0f)
        {
            ClearActionShowcaseRisingWindowGesture();
            return false;
        }

        var launchThreshold = Math.Max(1.8f, state.CharacterHeightWorld * 0.4f);
        var upwardSpeed = platformDelta.y > 0f ? platformDelta.y / elapsed : 0f;
        var maximumContinuousDelta = Math.Max(0.45f, state.CharacterHeightWorld * 0.35f);
        if (platformDelta.y > maximumContinuousDelta)
        {
            ClearActionShowcaseRisingWindowGesture();
            return false;
        }

        var gestureStartedThisFrame = false;
        if (platformDelta.y > 0.0005f
            && (_actionShowcaseRisingWindowHandle != platformHandle
                || Time.unscaledTime - _actionShowcaseRisingWindowLastMotionAt > 0.25f))
        {
            ClearActionShowcaseRisingWindowGesture();
            _actionShowcaseRisingWindowHandle = platformHandle;
            _actionShowcaseRisingWindowLastMotionAt = Time.unscaledTime;
            gestureStartedThisFrame = true;
        }

        if (_actionShowcaseRisingWindowHandle == platformHandle)
        {
            var rawVerticalSpeed = platformDelta.y / elapsed;
            var filterAlpha = 1f - Mathf.Exp(-elapsed / 0.025f);
            _actionShowcaseRisingWindowFilteredVerticalSpeed = gestureStartedThisFrame
                ? rawVerticalSpeed
                : Mathf.Lerp(
                    _actionShowcaseRisingWindowFilteredVerticalSpeed,
                    rawVerticalSpeed,
                    filterAlpha);
            _actionShowcaseRisingWindowNetDistance += platformDelta.y;
            _actionShowcaseRisingWindowDistance = Math.Max(
                _actionShowcaseRisingWindowDistance,
                _actionShowcaseRisingWindowNetDistance);
            _actionShowcaseRisingWindowPeakSpeed = Math.Max(
                _actionShowcaseRisingWindowPeakSpeed,
                _actionShowcaseRisingWindowFilteredVerticalSpeed);

            var horizontalSpeed = platformDelta.x / elapsed;
            if (Math.Abs(horizontalSpeed) > 0.02f)
            {
                _actionShowcaseRisingWindowHorizontalSpeed = Mathf.Lerp(
                    _actionShowcaseRisingWindowHorizontalSpeed,
                    horizontalSpeed,
                    0.5f);
            }

            var jitterDistance = Math.Max(0.01f, state.CharacterHeightWorld * 0.003f);
            var significantMotionSpeed = Math.Max(1.5f, state.CharacterHeightWorld * 0.3f);
            var significantUpwardSample = platformDelta.y >= jitterDistance
                && _actionShowcaseRisingWindowFilteredVerticalSpeed >= significantMotionSpeed;
            if (significantUpwardSample)
            {
                _actionShowcaseRisingWindowSignificantSamples =
                    Time.unscaledTime - _actionShowcaseRisingWindowLastSignificantSampleAt <= 0.035f
                        ? _actionShowcaseRisingWindowSignificantSamples + 1
                        : 1;
                _actionShowcaseRisingWindowLastSignificantSampleAt = Time.unscaledTime;
                if (_actionShowcaseRisingWindowSignificantSamples >= 2)
                    _actionShowcaseRisingWindowLastMotionAt = Time.unscaledTime;
            }

            var downwardCancelDistance = Math.Max(0.025f, state.CharacterHeightWorld * 0.008f);
            var significantDownwardSample = platformDelta.y <= -jitterDistance;
            if (significantDownwardSample)
            {
                if (_actionShowcaseRisingWindowDownwardStartedAt < 0f)
                    _actionShowcaseRisingWindowDownwardStartedAt = Time.unscaledTime;
                _actionShowcaseRisingWindowDownwardDistance += -platformDelta.y;
                var sustainedDownwardDistance = Math.Max(
                    0.18f,
                    state.CharacterHeightWorld * 0.06f);
                var downwardDuration = Time.unscaledTime
                    - _actionShowcaseRisingWindowDownwardStartedAt;
                if (_actionShowcaseRisingWindowDownwardDistance >= sustainedDownwardDistance
                    && downwardDuration >= 0.05f)
                {
                    ClearActionShowcaseRisingWindowGesture();
                }
                return false;
            }
            if (platformDelta.y >= -downwardCancelDistance)
            {
                _actionShowcaseRisingWindowDownwardStartedAt = -1f;
                _actionShowcaseRisingWindowDownwardDistance = 0f;
            }
            if (upwardSpeed >= significantMotionSpeed)
                return false;
        }

        if (_actionShowcaseRisingWindowHandle != platformHandle)
            return false;
        const int virtualKeyLeftMouseButton = 0x01;
        var mouseButtonHeld = IsVirtualKeyDown(virtualKeyLeftMouseButton);
        var releaseDelay = mouseButtonHeld
            ? Math.Clamp(
                GetActionShowcasePlatformRefreshInterval() * 5f,
                0.03f,
                0.05f)
            : 0.012f;
        var timeSinceMotion = Time.unscaledTime - _actionShowcaseRisingWindowLastMotionAt;
        if (timeSinceMotion < releaseDelay)
            return false;

        var peakUpwardSpeed = _actionShowcaseRisingWindowPeakSpeed;
        var risingDistance = _actionShowcaseRisingWindowDistance;
        var gestureHorizontalSpeed = _actionShowcaseRisingWindowHorizontalSpeed;
        ClearActionShowcaseRisingWindowGesture();
        var minimumRisingDistance = Math.Max(0.08f, state.CharacterHeightWorld * 0.03f);
        if (peakUpwardSpeed < launchThreshold
            || risingDistance < minimumRisingDistance
            || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            Plugin.PluginLog.LogDebug(
                $"Exploration upward carry released without launch: handle=0x{platformHandle.ToInt64():X}, peakPlatformSpeed={peakUpwardSpeed:F2}/{launchThreshold:F2}, risingDistance={risingDistance:F3}/{minimumRisingDistance:F3}.");
            return false;
        }

        var body = state.GetComponent<Rigidbody2D>();
        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (body == null || windowColliders == null)
            return false;
        var headroom = windowColliders.GetScreenTopWorldY()
            - (characterBounds.max.y + Math.Max(0f, platformDelta.y));
        var gravity = Math.Max(0.1f, Math.Abs(Physics2D.gravity.y * body.gravityScale));
        var desiredVelocity = Math.Clamp(peakUpwardSpeed * 0.9f + 0.8f, 3.2f, 6.5f);
        // A player-driven throw is allowed to reach the real screen-edge collider.
        // Pre-clamping against headroom made the same gesture lose energy abruptly
        // near the top of the display and felt less physical than an actual impact.
        var launchVelocity = desiredVelocity;
        var launchHorizontalVelocity = CalculateActionShowcaseLaunchHorizontalVelocity(
            platformHandle,
            characterBounds,
            gestureHorizontalSpeed,
            peakUpwardSpeed,
            launchVelocity,
            gravity,
            out var leavesPlatform);

        CaptureActionShowcaseLaunchCollisionMode(body);
        state.transform.position += platformDelta + Vector3.up * 0.015f;
        Physics2D.SyncTransforms();
        body.position = state.transform.position;
        body.velocity = new Vector2(launchHorizontalVelocity, launchVelocity);
        body.angularVelocity = 0f;
        state.IsGround = false;
        ClearActionShowcaseGroundSlide();
        _actionShowcaseGroundSlidePending = true;
        _actionShowcaseGroundSlideVelocityX = launchHorizontalVelocity;
        _actionShowcaseWindowLaunchAwaitingLanding = true;
        _actionShowcaseWindowLaunchLandedAt = -1f;
        _actionShowcaseWindowLaunchCooldownUntil = Time.unscaledTime + 0.1f;
        Plugin.PluginLog.LogInfo(
            $"Exploration controlled window launch after release: handle=0x{platformHandle.ToInt64():X}, peakPlatformSpeed={peakUpwardSpeed:F2}, risingDistance={risingDistance:F2}, releaseDelay={timeSinceMotion:F3}, mouseHeld={mouseButtonHeld}, gestureHorizontalSpeed={gestureHorizontalSpeed:F2}, launchVelocity=({launchHorizontalVelocity:F2}, {launchVelocity:F2}), leavesPlatform={leavesPlatform}, headroom={headroom:F2}, ceilingLimited=False.");
        return true;
    }

    private static float CalculateActionShowcaseLaunchHorizontalVelocity(
        IntPtr platformHandle,
        Bounds characterBounds,
        float gestureHorizontalSpeed,
        float gestureVerticalSpeed,
        float launchVerticalVelocity,
        float gravity,
        out bool leavesPlatform)
    {
        leavesPlatform = false;
        if (!ActionShowcaseWindowPlatforms.TryGetValue(platformHandle, out var platform))
            return 0f;
        var bounds = platform.WindowBounds;
        var horizontalMargin = Math.Max(0.03f, characterBounds.size.x * 0.04f);
        var minimumCenterX = bounds.min.x + characterBounds.extents.x + horizontalMargin;
        var maximumCenterX = bounds.max.x - characterBounds.extents.x - horizontalMargin;
        if (minimumCenterX >= maximumCenterX)
            return 0f;

        var flightTime = Math.Max(0.1f, 2f * launchVerticalVelocity / gravity);
        var escapeThreshold = Math.Max(6f, gestureVerticalSpeed * 0.75f);
        if (Math.Abs(gestureHorizontalSpeed) >= escapeThreshold)
        {
            var direction = Math.Sign(gestureHorizontalSpeed);
            var escapeCenterX = direction > 0f
                ? bounds.max.x + characterBounds.extents.x + 0.03f
                : bounds.min.x - characterBounds.extents.x - 0.03f;
            var requiredEscapeSpeed = Math.Abs(
                (escapeCenterX - characterBounds.center.x) / flightTime) * 1.05f;
            var requestedEscapeSpeed = Math.Clamp(
                Math.Abs(gestureHorizontalSpeed) * 0.28f,
                2.2f,
                5f);
            var maximumScreenSafeSpeed = 5f;
            var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
            if (windowColliders != null)
            {
                var screenSafeCenterX = direction > 0f
                    ? windowColliders.GetVisibleRightWorldX() - characterBounds.extents.x - 0.04f
                    : windowColliders.GetVisibleLeftWorldX() + characterBounds.extents.x + 0.04f;
                maximumScreenSafeSpeed = Math.Min(
                    maximumScreenSafeSpeed,
                    Math.Max(
                        0f,
                        direction * (screenSafeCenterX - characterBounds.center.x) / flightTime));
            }
            var escapeSpeed = Math.Min(requestedEscapeSpeed, maximumScreenSafeSpeed);
            leavesPlatform = escapeSpeed >= requiredEscapeSpeed * 0.95f;
            return direction * escapeSpeed;
        }

        var inwardDirection = Math.Abs(bounds.center.x - characterBounds.center.x) > 0.05f
            ? Math.Sign(bounds.center.x - characterBounds.center.x)
            : bounds.center.x >= 0f ? -1f : 1f;
        var desiredVelocity = Math.Abs(gestureHorizontalSpeed) >= 0.2f
            ? Math.Clamp(gestureHorizontalSpeed * 0.55f, -1.5f, 1.5f)
            : inwardDirection * 0.7f;
        var minimumSafeVelocity = (minimumCenterX - characterBounds.center.x) / flightTime;
        var maximumSafeVelocity = (maximumCenterX - characterBounds.center.x) / flightTime;
        return Math.Clamp(desiredVelocity, minimumSafeVelocity, maximumSafeVelocity);
    }

    private static void MaintainActionShowcaseWindowAttachment(LilithStateManager state)
    {
        if (!_actionShowcaseAttachedToWindow)
        {
            if (state.IsSit && TryAdoptActionShowcasePlatformUnderCharacter(state))
                AttachActionShowcasePoseToWindow(_actionShowcaseWindowHandle);
            return;
        }
        if (state.IsDrag || (!state.IsLieDown && !state.IsSit))
        {
            ClearActionShowcaseWindowAttachment();
            return;
        }
        if (!ActionShowcaseWindowPlatforms.TryGetValue(_actionShowcaseAttachedWindowHandle, out var platform))
        {
            ClearActionShowcaseWindowAttachment();
            StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: -0.1f);
            return;
        }
        var delta = CalculateActionShowcaseWindowMotionDelta(
            _actionShowcaseAttachedWindowMotionBounds,
            platform.MotionBounds);
        var elapsed = _actionShowcaseAttachedWindowMotionAt < 0f
            ? GetActionShowcasePlatformRefreshInterval()
            : Math.Max(0.001f, Time.unscaledTime - _actionShowcaseAttachedWindowMotionAt);
        if (state.IsSit
            && ShouldReleaseActionShowcaseSeatedWindowRide(
                state,
                platform.Handle,
                delta,
                elapsed,
                out var releaseVelocity))
        {
            ReleaseActionShowcaseSeatedWindowRide(state, platform.Handle, releaseVelocity);
            return;
        }
        if (state.IsSit)
        {
            var requestedPosition = ResolveActionShowcaseSeatedRootPosition(
                state,
                platform,
                state.transform.position.x + delta.x);
            var beforeMove = state.transform.position;
            var stationaryDistance = Math.Max(0.002f, state.CharacterHeightWorld * 0.00075f);
            var observedNativeBiasY = beforeMove.y - requestedPosition.y;
            var maximumLearnableBias = Math.Max(0.08f, state.CharacterHeightWorld * 0.03f);
            if (delta.magnitude <= stationaryDistance
                && Math.Abs(observedNativeBiasY) <= maximumLearnableBias)
            {
                _actionShowcaseAttachedWindowNativeSeatBiasY = observedNativeBiasY;
            }
            requestedPosition.y += _actionShowcaseAttachedWindowNativeSeatBiasY;
            if ((beforeMove - requestedPosition).sqrMagnitude > 0.000001f)
            {
                state.MoveWhileSitFrozen(requestedPosition);
                var appliedPosition = state.transform.position;
                if ((appliedPosition - requestedPosition).sqrMagnitude > 0.000001f)
                {
                    state.transform.position = requestedPosition;
                    var seatedBody = state.GetComponent<Rigidbody2D>();
                    if (seatedBody != null)
                        seatedBody.position = requestedPosition;
                }
                var correction = requestedPosition - (beforeMove + delta);
                if (Math.Abs(correction.y) > 0.01f
                    && Time.unscaledTime - _actionShowcaseAttachedWindowLastCorrectionLogAt >= 0.25f)
                {
                    _actionShowcaseAttachedWindowLastCorrectionLogAt = Time.unscaledTime;
                    Plugin.PluginLog.LogInfo(
                        $"Exploration corrected seated absolute platform anchor: handle=0x{platform.Handle.ToInt64():X}, delta={delta}, correction={correction}, requested={requestedPosition}, applied={appliedPosition}.");
                }
                Physics2D.SyncTransforms();
                StopActionShowcasePhysics(state, markGrounded: true);
            }
        }
        else if (delta.sqrMagnitude > 0.000001f)
        {
            state.transform.position += delta;
            Physics2D.SyncTransforms();
            StopActionShowcasePhysics(state, markGrounded: true);
        }
        if (!IsActionShowcaseAttachedPoseSupported(state, platform))
        {
            if (TryFindActionShowcasePlatformUnderCharacter(state, out var replacement)
                && replacement != null
                && replacement.Handle != platform.Handle)
            {
                var previousHandle = platform.Handle;
                _actionShowcaseAttachedWindowHandle = replacement.Handle;
                _actionShowcaseAttachedWindowBounds = replacement.WindowBounds;
                _actionShowcaseAttachedWindowMotionBounds = replacement.MotionBounds;
                ResetActionShowcaseAttachedWindowMotion();
                _actionShowcaseWindowHandle = replacement.Handle;
                _actionShowcaseWindowPlatformBounds = replacement.WindowBounds;
                _actionShowcaseWindowPlatformTop = new Vector3(
                    Math.Clamp(state.transform.position.x, replacement.WindowBounds.min.x, replacement.WindowBounds.max.x),
                    replacement.WindowBounds.max.y,
                    state.transform.position.z);
                _actionShowcasePlatformObject = replacement.Object;
                _actionShowcasePlatformCollider = replacement.Collider;
                _actionShowcaseSupportedWindowHandle = replacement.Handle;
                _actionShowcaseSupportedWindowUntil = Time.unscaledTime
                    + GetActionShowcaseSupportRecoveryDuration();
                if (state.IsSit)
                    state.RequestSitSeatHandle(replacement.Handle);
                StopActionShowcasePhysics(state, markGrounded: true);
                Plugin.PluginLog.LogInfo(
                    $"Exploration transferred attached pose after foreground topology changed: 0x{previousHandle.ToInt64():X}->0x{replacement.Handle.ToInt64():X}.");
                return;
            }
            ReleaseActionShowcaseUnsupportedAttachedPose(state, platform.Handle);
            return;
        }
        _actionShowcaseAttachedWindowBounds = platform.WindowBounds;
        _actionShowcaseAttachedWindowMotionBounds = platform.MotionBounds;
        _actionShowcaseAttachedWindowMotionAt = Time.unscaledTime;
    }

    private static void AttachActionShowcasePoseToWindow(IntPtr handle)
    {
        if (handle == IntPtr.Zero
            || !ActionShowcaseWindowPlatforms.TryGetValue(handle, out var platform))
            return;
        _actionShowcaseAttachedToWindow = true;
        _actionShowcaseAttachedWindowHandle = handle;
        _actionShowcaseAttachedWindowBounds = platform.WindowBounds;
        _actionShowcaseAttachedWindowMotionBounds = platform.MotionBounds;
        ResetActionShowcaseAttachedWindowMotion();
    }

    private static void ResetActionShowcaseAttachedWindowMotion()
    {
        _actionShowcaseAttachedWindowFilteredVelocity = Vector2.zero;
        _actionShowcaseAttachedWindowMotionAt = Time.unscaledTime;
        _actionShowcaseAttachedWindowFastMotionSamples = 0;
        _actionShowcaseAttachedWindowFastMotionDistance = 0f;
        _actionShowcaseAttachedWindowLastFastMotionAt = -1f;
        _actionShowcaseAttachedWindowLastCorrectionLogAt = -1f;
        _actionShowcaseAttachedWindowNativeSeatBiasY = 0f;
    }

    private static Vector3 ResolveActionShowcaseSeatedRootPosition(
        LilithStateManager state,
        ActionShowcaseWindowPlatform platform,
        float rootX)
    {
        var target = new Vector3(
            rootX,
            platform.MotionBounds.max.y - state.GetSitVerticalOffset(),
            state.transform.position.z);
        return state.ClampSitTargetToGround(target);
    }

    private static bool ShouldReleaseActionShowcaseSeatedWindowRide(
        LilithStateManager state,
        IntPtr platformHandle,
        Vector3 platformDelta,
        float elapsed,
        out Vector2 releaseVelocity)
    {
        elapsed = Math.Clamp(elapsed, 0.001f, 0.05f);
        var rawVelocity = new Vector2(platformDelta.x / elapsed, platformDelta.y / elapsed);
        var filterAlpha = 1f - Mathf.Exp(-elapsed / 0.025f);
        _actionShowcaseAttachedWindowFilteredVelocity = Vector2.Lerp(
            _actionShowcaseAttachedWindowFilteredVelocity,
            rawVelocity,
            filterAlpha);
        releaseVelocity = _actionShowcaseAttachedWindowFilteredVelocity;

        var jitterDistance = Math.Max(0.008f, state.CharacterHeightWorld * 0.0025f);
        var horizontalReleaseSpeed = Math.Max(5.5f, state.CharacterHeightWorld * 1.1f);
        var verticalReleaseSpeed = Math.Max(4.5f, state.CharacterHeightWorld * 0.9f);
        var hasFastVelocity = Math.Abs(releaseVelocity.x) >= horizontalReleaseSpeed
            || Math.Abs(releaseVelocity.y) >= verticalReleaseSpeed;
        var significantFastSample = platformDelta.magnitude >= jitterDistance && hasFastVelocity;
        var consecutiveWindow = Math.Clamp(
            GetActionShowcasePlatformRefreshInterval() * 4f,
            0.025f,
            0.05f);
        if (significantFastSample)
        {
            _actionShowcaseAttachedWindowFastMotionSamples =
                _actionShowcaseAttachedWindowLastFastMotionAt >= 0f
                && Time.unscaledTime - _actionShowcaseAttachedWindowLastFastMotionAt <= consecutiveWindow
                    ? _actionShowcaseAttachedWindowFastMotionSamples + 1
                    : 1;
            _actionShowcaseAttachedWindowFastMotionDistance += platformDelta.magnitude;
            _actionShowcaseAttachedWindowLastFastMotionAt = Time.unscaledTime;
        }
        else if (_actionShowcaseAttachedWindowLastFastMotionAt >= 0f
            && Time.unscaledTime - _actionShowcaseAttachedWindowLastFastMotionAt > consecutiveWindow)
        {
            _actionShowcaseAttachedWindowFastMotionSamples = 0;
            _actionShowcaseAttachedWindowFastMotionDistance = 0f;
            _actionShowcaseAttachedWindowLastFastMotionAt = -1f;
        }

        var minimumReleaseDistance = Math.Max(0.12f, state.CharacterHeightWorld * 0.035f);
        var immediateReleaseDistance = Math.Max(0.5f, state.CharacterHeightWorld * 0.18f);
        var sustainedRelease = _actionShowcaseAttachedWindowFastMotionSamples >= 2
            && _actionShowcaseAttachedWindowFastMotionDistance >= minimumReleaseDistance;
        var immediateRelease = platformDelta.magnitude >= immediateReleaseDistance;
        if (!sustainedRelease && !immediateRelease)
            return false;

        Plugin.PluginLog.LogInfo(
            $"Exploration seated window ride exceeded its release threshold: handle=0x{platformHandle.ToInt64():X}, delta={platformDelta}, filteredVelocity={releaseVelocity}, samples={_actionShowcaseAttachedWindowFastMotionSamples}, distance={_actionShowcaseAttachedWindowFastMotionDistance:F3}, immediate={immediateRelease}.");
        return true;
    }

    private static void ReleaseActionShowcaseSeatedWindowRide(
        LilithStateManager state,
        IntPtr platformHandle,
        Vector2 platformVelocity)
    {
        var releaseVelocityX = Math.Clamp(platformVelocity.x * 0.55f, -4.5f, 4.5f);
        var releaseVelocityY = Math.Clamp(Math.Min(-0.12f, platformVelocity.y * 0.3f), -3f, -0.12f);
        ClearActionShowcaseWindowAttachment();
        ClearActionShowcaseStandingPlatformMemory();
        _motionIntentSitActive = false;
        state.ReturnIdle();
        StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: releaseVelocityY);
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
            body.velocity = new Vector2(releaseVelocityX, releaseVelocityY);
        _actionShowcaseGroundSlidePending = true;
        _actionShowcaseGroundSlideVelocityX = releaseVelocityX;
        Plugin.PluginLog.LogInfo(
            $"Exploration released seated window ride after a fast window move: handle=0x{platformHandle.ToInt64():X}, velocity=({releaseVelocityX:F2}, {releaseVelocityY:F2}).");
    }

    private static bool IsActionShowcaseAttachedPoseSupported(
        LilithStateManager state,
        ActionShowcaseWindowPlatform platform)
    {
        Physics2D.SyncTransforms();
        var platformBounds = state.IsSit ? platform.MotionBounds : platform.WindowBounds;
        if (state.IsLieDown)
        {
            if (!TryGetActionShowcaseVisualBounds(state, out var lieBounds))
                return false;
            var margin = Math.Max(0.02f, lieBounds.size.x * 0.02f);
            return lieBounds.min.x >= platformBounds.min.x - margin
                && lieBounds.max.x <= platformBounds.max.x + margin;
        }

        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return false;
        var supportX = state.IsSit ? state.transform.position.x : characterBounds.center.x;
        var horizontalMargin = Math.Min(
            Math.Max(0.01f, characterBounds.size.x * 0.03f),
            Math.Max(0.01f, platformBounds.extents.x * 0.25f));
        var verticalTolerance = Math.Max(0.18f, characterBounds.size.y * 0.15f);
        var verticalError = state.IsSit
            ? Math.Abs(
                state.transform.position.y
                - ResolveActionShowcaseSeatedRootPosition(
                    state,
                    platform,
                    state.transform.position.x).y)
            : Math.Abs(characterBounds.min.y - platformBounds.max.y);
        return supportX >= platformBounds.min.x + horizontalMargin
            && supportX <= platformBounds.max.x - horizontalMargin
            && verticalError <= verticalTolerance;
    }

    private static void ReleaseActionShowcaseUnsupportedAttachedPose(
        LilithStateManager state,
        IntPtr platformHandle)
    {
        var pose = state.IsLieDown ? "LieDown" : state.IsSit ? "Sit" : "Pose";
        ClearActionShowcaseWindowAttachment();
        ClearActionShowcaseStandingPlatformMemory();
        if (state.IsLieDown)
            state.ExitLieDownState();
        state.ReturnIdle();
        StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: -0.15f);
        Plugin.PluginLog.LogInfo(
            $"Exploration released unsupported attached {pose} after window resize: handle=0x{platformHandle.ToInt64():X}.");
    }

    private static void ClearActionShowcaseWindowAttachment()
    {
        _actionShowcaseAttachedToWindow = false;
        _actionShowcaseAttachedWindowHandle = IntPtr.Zero;
        _actionShowcaseAttachedWindowBounds = default;
        _actionShowcaseAttachedWindowMotionBounds = default;
        _actionShowcaseAttachedWindowFilteredVelocity = Vector2.zero;
        _actionShowcaseAttachedWindowMotionAt = -1f;
        _actionShowcaseAttachedWindowFastMotionSamples = 0;
        _actionShowcaseAttachedWindowFastMotionDistance = 0f;
        _actionShowcaseAttachedWindowLastFastMotionAt = -1f;
        _actionShowcaseAttachedWindowLastCorrectionLogAt = -1f;
        _actionShowcaseAttachedWindowNativeSeatBiasY = 0f;
    }

    private static bool TryFindActionShowcasePlatformUnderCharacter(
        LilithStateManager state,
        out ActionShowcaseWindowPlatform? best)
    {
        best = null;
        Physics2D.SyncTransforms();
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return false;
        var verticalTolerance = Math.Max(0.12f, characterBounds.size.y * 0.1f);
        var supportY = state.IsSit
            ? state.transform.position.y + state.GetSitVerticalOffset()
            : characterBounds.min.y;
        var bestDistance = float.MaxValue;
        ActionShowcaseWindowPlatform? stickyPlatform = null;
        var stickyDistance = float.MaxValue;
        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
        {
            var mayRecoverUnseenSupport = platform.Handle == _actionShowcaseSupportedWindowHandle
                && Time.unscaledTime <= _actionShowcaseSupportedWindowUntil;
            if (!platform.Seen && !mayRecoverUnseenSupport)
                continue;
            var bounds = platform.WindowBounds;
            var overlapsHorizontally = characterBounds.max.x > bounds.min.x + 0.01f
                && characterBounds.min.x < bounds.max.x - 0.01f;
            var distance = Math.Abs(supportY - bounds.max.y);
            if (!overlapsHorizontally || distance > verticalTolerance)
                continue;
            if (platform.Handle == _actionShowcaseSupportedWindowHandle)
            {
                stickyPlatform = platform;
                stickyDistance = distance;
            }
            if (distance < bestDistance)
            {
                best = platform;
                bestDistance = distance;
            }
        }
        var switchAdvantage = Math.Min(0.05f, verticalTolerance * 0.4f);
        if (stickyPlatform != null && stickyDistance <= bestDistance + switchAdvantage)
            best = stickyPlatform;
        return best != null;
    }

    private static bool TryAdoptActionShowcasePlatformUnderCharacter(LilithStateManager state)
    {
        Physics2D.SyncTransforms();
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return false;
        var verticalTolerance = Math.Max(0.12f, characterBounds.size.y * 0.1f);
        var supportY = state.IsSit
            ? state.transform.position.y + state.GetSitVerticalOffset()
            : characterBounds.min.y;
        var horizontalGrace = GetActionShowcaseSafePlatformInset(characterBounds);
        ActionShowcaseWindowPlatform? best = null;
        var bestScore = float.MaxValue;
        ActionShowcaseWindowPlatform? stickyPlatform = null;
        var stickyScore = float.MaxValue;
        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
        {
            if (!platform.Seen)
                continue;
            var bounds = platform.WindowBounds;
            var horizontalGap = bounds.min.x > characterBounds.max.x
                ? bounds.min.x - characterBounds.max.x
                : characterBounds.min.x > bounds.max.x
                    ? characterBounds.min.x - bounds.max.x
                    : 0f;
            var verticalDistance = Math.Abs(supportY - bounds.max.y);
            var score = verticalDistance + horizontalGap * 0.5f;
            if (horizontalGap > horizontalGrace
                || verticalDistance > verticalTolerance)
                continue;
            if (platform.Handle == _actionShowcaseSupportedWindowHandle)
            {
                stickyPlatform = platform;
                stickyScore = score;
            }
            if (score < bestScore)
            {
                best = platform;
                bestScore = score;
            }
        }
        var switchAdvantage = Math.Min(0.05f, verticalTolerance * 0.4f);
        if (stickyPlatform != null && stickyScore <= bestScore + switchAdvantage)
            best = stickyPlatform;
        if (best == null)
            return false;

        // A verified platform directly under Lilith is sufficient to establish
        // platform ownership. Model-driven walking must not depend on the legacy
        // showcase step having selected the same window beforehand.
        _actionShowcaseHasWindowPlatform = true;
        _actionShowcaseWindowHandle = best.Handle;
        _actionShowcaseWindowPlatformBounds = best.WindowBounds;
        _actionShowcaseWindowPlatformTop = new Vector3(
            Math.Clamp(characterBounds.center.x, best.WindowBounds.min.x, best.WindowBounds.max.x),
            best.WindowBounds.max.y,
            state.transform.position.z);
        _actionShowcasePlatformObject = best.Object;
        _actionShowcasePlatformCollider = best.Collider;
        _actionShowcaseSupportedWindowHandle = best.Handle;
        _actionShowcaseSupportedWindowUntil = Time.unscaledTime
            + GetActionShowcaseSupportRecoveryDuration();
        return true;
    }

    private static bool TryAdoptActionShowcasePlatformByHandle(
        LilithStateManager state,
        IntPtr handle)
    {
        if (handle == IntPtr.Zero
            || !ActionShowcaseWindowPlatforms.TryGetValue(handle, out var platform)
            || (!platform.Seen && Time.unscaledTime - platform.LastSeenAt > 0.35f))
        {
            return false;
        }

        _actionShowcaseHasWindowPlatform = true;
        _actionShowcaseWindowHandle = platform.Handle;
        _actionShowcaseWindowPlatformBounds = platform.WindowBounds;
        _actionShowcaseWindowPlatformTop = new Vector3(
            Math.Clamp(state.transform.position.x, platform.WindowBounds.min.x, platform.WindowBounds.max.x),
            platform.WindowBounds.max.y,
            state.transform.position.z);
        _actionShowcasePlatformObject = platform.Object;
        _actionShowcasePlatformCollider = platform.Collider;
        _actionShowcaseSupportedWindowHandle = platform.Handle;
        _actionShowcaseSupportedWindowUntil = Time.unscaledTime
            + GetActionShowcaseSupportRecoveryDuration();
        return true;
    }

    private static bool TryResolveMotionWindowPlatform(
        LilithStateManager state,
        bool sitting)
    {
        RefreshActionShowcaseAllWindowPlatforms(state);
        if (TryAdoptActionShowcasePlatformUnderCharacter(state))
            return true;
        if (sitting
            && _actionShowcaseWindowHandle != IntPtr.Zero
            && TryAdoptActionShowcasePlatformByHandle(state, _actionShowcaseWindowHandle))
        {
            return true;
        }

        // The model review and dispatcher run on different frames. Preserve only
        // the short, geometry-verified support lease used by the 170 Hz platform
        // solver so a transient native Ground=false sample cannot reject a walk.
        return Time.unscaledTime <= _actionShowcaseSupportedWindowUntil
            && ActionShowcaseWindowPlatforms.TryGetValue(
                _actionShowcaseSupportedWindowHandle,
                out var supportedPlatform)
            && IsActionShowcaseSupportRecoveryEligible(state, supportedPlatform)
            && TryAdoptActionShowcasePlatformByHandle(
                state,
                _actionShowcaseSupportedWindowHandle);
    }

    internal static bool TryGetActionShowcaseSitPlatformByHandle(
        IntPtr windowHandle,
        bool requireSitHeadroom,
        ActiveWindowCollider windowColliders,
        out Vector3 topCenterWorld,
        out Bounds boxBounds)
    {
        topCenterWorld = default;
        boxBounds = default;
        if ((!IsGlobalMotionPhysicsActive && !_actionShowcaseHasExplorationOrigin)
            || windowHandle == IntPtr.Zero
            || !ActionShowcaseWindowPlatforms.TryGetValue(windowHandle, out var platform)
            || platform == null
            || !platform.Seen)
        {
            return false;
        }

        boxBounds = platform.WindowBounds;
        if (boxBounds.size.x <= 0.01f || boxBounds.size.y <= 0.01f)
            return false;

        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (state == null)
            return false;
        if (requireSitHeadroom
            && TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            var shiftedMaximumY = GetActionShowcasePredictedSeatedMaximumY(
                state,
                boxBounds.max.y,
                characterBounds);
            if (shiftedMaximumY > windowColliders.GetScreenTopWorldY() - 0.02f)
                return false;
        }

        topCenterWorld = new Vector3(
            boxBounds.center.x,
            boxBounds.max.y,
            state.transform.position.z);
        return true;
    }

    private static float GetActionShowcaseSafePlatformInset(Bounds characterBounds)
    {
        // Walking end transitions and the seated silhouette both extend farther than
        // the narrow standing support footprint.  Keep autonomous endpoints inside a
        // shared safety zone while still allowing an intentional ledge drop.
        return Math.Clamp(characterBounds.size.x * 0.35f, 0.12f, 0.42f);
    }

    private static void RefreshActionShowcaseNativeWindowCollisionIsolation(LilithStateManager state)
    {
        var nativeWindowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (nativeWindowColliders == null || nativeWindowColliders.boxColliders == null)
            return;

        foreach (var characterCollider in state.GetComponentsInChildren<Collider2D>(true))
        {
            if (characterCollider == null || characterCollider == _actionShowcasePlatformCollider)
                continue;
            if (!ActionShowcaseIgnoredCharacterColliders.Contains(characterCollider))
                ActionShowcaseIgnoredCharacterColliders.Add(characterCollider);
        }
        for (var i = 0; i < nativeWindowColliders.boxColliders.Count; i++)
        {
            var windowCollider = nativeWindowColliders.boxColliders[i];
            if (windowCollider == null)
                continue;
            if (!ActionShowcaseIgnoredNativeWindowColliders.Contains(windowCollider))
                ActionShowcaseIgnoredNativeWindowColliders.Add(windowCollider);
        }

        foreach (var characterCollider in ActionShowcaseIgnoredCharacterColliders)
        {
            if (characterCollider == null)
                continue;
            foreach (var windowCollider in ActionShowcaseIgnoredNativeWindowColliders)
            {
                if (windowCollider != null)
                    Physics2D.IgnoreCollision(characterCollider, windowCollider, true);
            }
        }
    }

    private static void RestoreActionShowcaseNativeWindowCollisions()
    {
        foreach (var characterCollider in ActionShowcaseIgnoredCharacterColliders)
        {
            if (characterCollider == null)
                continue;
            foreach (var windowCollider in ActionShowcaseIgnoredNativeWindowColliders)
            {
                if (windowCollider != null)
                    Physics2D.IgnoreCollision(characterCollider, windowCollider, false);
            }
        }
        ActionShowcaseIgnoredCharacterColliders.Clear();
        ActionShowcaseIgnoredNativeWindowColliders.Clear();
    }

    private static void GetActionShowcaseConnectedSurfaceSpan(
        Bounds characterBounds,
        out float minimumX,
        out float maximumX,
        out int platformCount,
        out float largestAcceptedGap,
        out float largestAcceptedTopDifference)
    {
        minimumX = _actionShowcaseWindowPlatformBounds.min.x;
        maximumX = _actionShowcaseWindowPlatformBounds.max.x;
        platformCount = 1;
        largestAcceptedGap = 0f;
        largestAcceptedTopDifference = 0f;
        var referenceTopY = _actionShowcaseWindowPlatformBounds.max.y;
        // DWM's invisible resize borders can leave a small world-space seam even when
        // two windows look perfectly flush.  Treat only a character-relative, tightly
        // capped gap as connected; larger gaps remain real ledges.
        var verticalTolerance = Math.Clamp(characterBounds.size.y * 0.055f, 0.07f, 0.22f);
        var maximumHorizontalGap = Math.Clamp(characterBounds.size.x * 0.12f, 0.04f, 0.18f);
        var connectedHandles = new HashSet<IntPtr> { _actionShowcaseWindowHandle };

        var expanded = true;
        while (expanded)
        {
            expanded = false;
            foreach (var platform in ActionShowcaseWindowPlatforms.Values)
            {
                var topDifference = Math.Abs(platform.WindowBounds.max.y - referenceTopY);
                if (!platform.Seen
                    || connectedHandles.Contains(platform.Handle)
                    || topDifference > verticalTolerance)
                {
                    continue;
                }

                var horizontalGap = platform.WindowBounds.min.x > maximumX
                    ? platform.WindowBounds.min.x - maximumX
                    : minimumX > platform.WindowBounds.max.x
                        ? minimumX - platform.WindowBounds.max.x
                        : 0f;
                if (horizontalGap > maximumHorizontalGap)
                    continue;

                connectedHandles.Add(platform.Handle);
                minimumX = Math.Min(minimumX, platform.WindowBounds.min.x);
                maximumX = Math.Max(maximumX, platform.WindowBounds.max.x);
                largestAcceptedGap = Math.Max(largestAcceptedGap, horizontalGap);
                largestAcceptedTopDifference = Math.Max(largestAcceptedTopDifference, topDifference);
                platformCount++;
                expanded = true;
            }
        }
    }

    private static void DestroyActionShowcaseDedicatedPlatform()
    {
        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
        {
            if (platform.Collider != null)
            {
                foreach (var characterCollider in ActionShowcaseIgnoredCharacterColliders)
                {
                    if (characterCollider != null)
                        Physics2D.IgnoreCollision(characterCollider, platform.Collider, false);
                }
            }
            if (platform.Object != null)
                UnityEngine.Object.Destroy(platform.Object);
        }
        RestoreActionShowcaseNativeWindowCollisions();
        ActionShowcaseWindowPlatforms.Clear();
        DestroyGlobalMotionGround();
        _actionShowcasePlatformObject = null;
        _actionShowcasePlatformCollider = null;
        _actionShowcasePlatformRefreshAt = -1f;
        ClearActionShowcaseStandingPlatformMemory();
        ResetActionShowcaseLaunchLandingGate();
        ClearActionShowcaseWindowAttachment();
    }

    private static void SetActionShowcasePlatformsEnabled(bool enabled)
    {
        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
        {
            if (platform.Collider != null)
                platform.Collider.enabled = enabled;
        }
        Physics2D.SyncTransforms();
    }

    private static void RefreshActionShowcasePlatformCollisionRules(LilithStateManager state)
    {
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
            return;
        var body = state.GetComponent<Rigidbody2D>();
        var verticalTolerance = Math.Max(0.02f, characterBounds.size.y * 0.02f);
        var characterColliders = state.GetComponentsInChildren<Collider2D>(true);
        foreach (var platform in ActionShowcaseWindowPlatforms.Values)
        {
            if (platform.Collider == null)
                continue;
            var platformBounds = platform.WindowBounds;
            var overlapsHorizontally = characterBounds.max.x > platformBounds.min.x + 0.005f
                && characterBounds.min.x < platformBounds.max.x - 0.005f;
            var isAboveSurface = characterBounds.min.y >= platformBounds.max.y - verticalTolerance;
            var isDescendingOrStable = body == null || body.velocity.y <= 0.15f;
            var allowTopContact = !state.IsDrag
                && overlapsHorizontally
                && isAboveSurface
                && isDescendingOrStable;
            foreach (var characterCollider in characterColliders)
            {
                if (characterCollider != null && !characterCollider.isTrigger)
                    Physics2D.IgnoreCollision(characterCollider, platform.Collider, !allowTopContact);
            }
            platform.CollisionRulesInitialized = true;
            platform.Collider.enabled = !_actionShowcaseOverlayBehindWindow;
        }
    }

    private static bool PlayActionShowcaseWindowWalk(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        bool walkLeft,
        int itemNumber,
        int itemCount,
        bool coherentSequence = false)
    {
        if (state.ClothingState == LilithClothingState.Pajamas)
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：睡衣沒有左右走路動畫，已取消窗頂走動", 6f);
            Plugin.PluginLog.LogInfo("Exploration showcase rejected window walking because Pajamas has no directional walk assets.");
            return false;
        }

        if (!TryResolveMotionWindowPlatform(state, sitting: false))
        {
            ShowActionShowcaseMessage(manager, $"Exploration {itemNumber}/{itemCount}: Lilith is not standing on a window platform; walk cancelled.", 5f);
            Plugin.PluginLog.LogInfo("Exploration showcase rejected window walking because the character is not standing on a window platform.");
            return false;
        }

        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：無法取得角色碰撞外框", 5f);
            return false;
        }

        GetActionShowcaseConnectedSurfaceSpan(
            characterBounds,
            out var connectedMinimumX,
            out var connectedMaximumX,
            out var connectedPlatformCount,
            out var largestAcceptedGap,
            out var largestAcceptedTopDifference);
        var margin = GetActionShowcaseSafePlatformInset(characterBounds);
        var desiredCenterX = walkLeft
            ? connectedMinimumX + characterBounds.extents.x + margin
            : connectedMaximumX - characterBounds.extents.x - margin;
        var targetRootX = desiredCenterX + (state.transform.position.x - characterBounds.center.x);
        var started = state.EnterWalkToX(targetRootX, 0.08f);
        if (started)
        {
            _actionShowcaseWindowWalkContinuationActive = true;
            _actionShowcaseWindowWalkTargetRootX = targetRootX;
            _actionShowcaseWindowWalkLastRootX = state.transform.position.x;
            _actionShowcaseWindowWalkStartedAt = Time.unscaledTime;
            _actionShowcaseWindowWalkResumeAt = Time.unscaledTime + 0.2f;
            _actionShowcaseWindowWalkNoProgressSegments = 0;
            _actionShowcaseWindowWalkSegmentStarted = true;
        }
        else
        {
            ClearActionShowcaseWindowWalkContinuation();
        }
        var directionLabel = walkLeft ? "左" : "右";
        ShowActionShowcaseMessage(
            manager,
            coherentSequence
                ? $"連貫展示：沿著視窗頂向{directionLabel}走"
                : $"探索 {itemNumber}/{itemCount}：嘗試在視窗頂向{directionLabel}走（{(started ? "已開始" : "原生狀態拒絕")}）",
            6f);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase requested window walk {directionLabel}; started={started}, targetX={targetRootX:F3}, connectedPlatforms={connectedPlatformCount}, span=({connectedMinimumX:F3}, {connectedMaximumX:F3}), safeInset={margin:F3}, acceptedGap={largestAcceptedGap:F3}, acceptedTopDelta={largestAcceptedTopDifference:F3}, platform={_actionShowcaseWindowPlatformBounds}.");
        return started;
    }

    internal static bool ShouldBypassNativeDirectedWalkLimits =>
        _actionShowcaseWindowWalkContinuationActive;

    private static void UpdateActionShowcaseWindowWalkContinuation(LilithStateManager state)
    {
        if (!_actionShowcaseWindowWalkContinuationActive)
            return;
        if (state.IsDrag
            || state.IsSit
            || _actionShowcasePendingOperation != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow)
        {
            ClearActionShowcaseWindowWalkContinuation();
            return;
        }
        if (state.IsWalkLeft || state.IsWalkRight)
            return;

        var remainingDistance = Math.Abs(
            _actionShowcaseWindowWalkTargetRootX - state.transform.position.x);
        if (remainingDistance <= 0.1f)
        {
            Plugin.PluginLog.LogInfo(
                $"Exploration connected-window walk reached its target after {Time.unscaledTime - _actionShowcaseWindowWalkStartedAt:F2}s.");
            ClearActionShowcaseWindowWalkContinuation();
            if (_actionShowcaseCoherentRandomActive)
            {
                _actionShowcaseCoherentRandomNextAt = Math.Max(
                    _actionShowcaseCoherentRandomNextAt,
                    Time.unscaledTime + 0.45f);
            }
            return;
        }
        if (!state.IsGround)
        {
            Plugin.PluginLog.LogInfo(
                $"Exploration connected-window walk stopped after leaving its support surface; remaining={remainingDistance:F3}.");
            ClearActionShowcaseWindowWalkContinuation();
            return;
        }
        if (state.IsStateMachineLocked
            || state.IsAnyActionAnimPlaying)
        {
            return;
        }
        if (Time.unscaledTime - _actionShowcaseWindowWalkStartedAt > 20f)
        {
            Plugin.PluginLog.LogInfo(
                $"Exploration connected-window walk reached its 20-second route limit; remaining={remainingDistance:F3}.");
            ClearActionShowcaseWindowWalkContinuation();
            return;
        }

        if (_actionShowcaseWindowWalkSegmentStarted)
        {
            var segmentProgress = Math.Abs(
                state.transform.position.x - _actionShowcaseWindowWalkLastRootX);
            if (segmentProgress < 0.03f)
                _actionShowcaseWindowWalkNoProgressSegments++;
            else
                _actionShowcaseWindowWalkNoProgressSegments = 0;
            if (_actionShowcaseWindowWalkNoProgressSegments >= 2)
            {
                Plugin.PluginLog.LogInfo(
                    $"Exploration connected-window walk stopped after two no-progress segments; remaining={remainingDistance:F3}.");
                ClearActionShowcaseWindowWalkContinuation();
                return;
            }

            _actionShowcaseWindowWalkLastRootX = state.transform.position.x;
            _actionShowcaseWindowWalkSegmentStarted = false;
            state.ClearWalkTarget();
            state.ReturnIdle();
            _actionShowcaseWindowWalkResumeAt = Time.unscaledTime + 0.12f;
            Plugin.PluginLog.LogInfo(
                $"Exploration connected-window walk segment ended; progress={segmentProgress:F3}, remaining={remainingDistance:F3}; returning to idle before continuation.");
            return;
        }

        if (!state.IsIdle || Time.unscaledTime < _actionShowcaseWindowWalkResumeAt)
            return;

        state.ClearWalkTarget();
        var resumed = state.EnterWalkToX(_actionShowcaseWindowWalkTargetRootX, 0.08f);
        _actionShowcaseWindowWalkSegmentStarted = resumed;
        _actionShowcaseWindowWalkResumeAt = Time.unscaledTime + (resumed ? 0.2f : 0.25f);
        Plugin.PluginLog.LogInfo(
            $"Exploration connected-window walk continuation requested from idle; started={resumed}, remaining={remainingDistance:F3}.");
    }

    private static void ClearActionShowcaseWindowWalkContinuation()
    {
        _actionShowcaseWindowWalkContinuationActive = false;
        _actionShowcaseWindowWalkTargetRootX = 0f;
        _actionShowcaseWindowWalkLastRootX = 0f;
        _actionShowcaseWindowWalkStartedAt = -1f;
        _actionShowcaseWindowWalkResumeAt = -1f;
        _actionShowcaseWindowWalkNoProgressSegments = 0;
        _actionShowcaseWindowWalkSegmentStarted = false;
    }

    private static void ToggleActionShowcaseCoherentRandom(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int itemNumber,
        int itemCount)
    {
        if (_actionShowcaseCoherentRandomActive)
        {
            StopActionShowcaseCoherentRandom();
            ResetActionShowcaseCharacter(character, state);
            ShowActionShowcaseMessage(
                manager,
                $"探索 {itemNumber}/{itemCount}：已停止連貫隨機展示",
                5f);
            Plugin.PluginLog.LogInfo("Exploration coherent random showcase stopped by the user.");
            return;
        }

        if (state.ClothingState == LilithClothingState.Pajamas)
        {
            ShowActionShowcaseMessage(
                manager,
                $"探索 {itemNumber}/{itemCount}：睡衣狀態不執行桌面走動，連貫展示暫不啟動",
                6f);
            Plugin.PluginLog.LogInfo("Exploration coherent random showcase rejected Pajamas movement.");
            return;
        }

        ResetActionShowcaseCharacter(character, state);
        _actionShowcaseCoherentRandomActive = true;
        _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.65f;
        _actionShowcaseCoherentRandomStep = 0;
        _actionShowcaseCoherentRandomLastAction = ActionShowcaseCoherentAction.None;
        _actionShowcaseCoherentRandomLastOneShot = LilithActionType.None;
        _actionShowcaseCoherentRandomSitCooldownUntil = -1f;
        _actionShowcaseCoherentRandomSitBlockedUntilStep = 0;
        _motionIntentSitActive = false;
        ShowActionShowcaseMessage(
            manager,
            $"探索 {itemNumber}/{itemCount}：連貫隨機展示已啟動；再次重播本項可停止",
            6f);
        Plugin.PluginLog.LogInfo("Exploration coherent random showcase started.");
    }

    private static void StopActionShowcaseCoherentRandom()
    {
        ClearActionShowcaseWindowWalkContinuation();
        _motionIntentSitActive = false;
        _actionShowcaseCoherentRandomActive = false;
        _actionShowcaseCoherentRandomNextAt = -1f;
        _actionShowcaseCoherentRandomStep = 0;
        _actionShowcaseCoherentRandomLastAction = ActionShowcaseCoherentAction.None;
        _actionShowcaseCoherentRandomLastOneShot = LilithActionType.None;
        _actionShowcaseCoherentRandomSitCooldownUntil = -1f;
        _actionShowcaseCoherentRandomSitBlockedUntilStep = 0;
    }

    internal static void NotifyAutomaticSafetyRecovery(
        global::CharacterController character,
        LilithStateManager? state)
    {
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
        _actionShowcasePendingAt = -1f;
        _actionShowcaseSnapEndsAt = -1f;
        _actionShowcasePendingDescription = string.Empty;
        _actionShowcasePendingShowFeedback = true;
        if (state != null)
        {
            if (_actionShowcaseOverlayBehindWindow)
                RestoreActionShowcaseWindowPeek(character, state);
            state.ClearWalkTarget();
        }
        _actionShowcaseOverlayBehindWindow = false;
        _motionIntentSitActive = false;
        ClearActionShowcaseWindowWalkContinuation();
        ClearActionShowcaseWindowAttachment();
        ClearActionShowcaseStandingPlatformMemory();
        ResetActionShowcaseLaunchLandingGate();
        if (_actionShowcaseCoherentRandomActive)
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.75f;
    }

    internal static bool IsCharacterStillInsideVisibleSafetyArea(out Bounds characterBounds)
    {
        characterBounds = default;
        try
        {
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
            Physics2D.SyncTransforms();
            if (state == null
                || windowColliders == null
                || !TryGetActionShowcaseCharacterBounds(state, out characterBounds))
            {
                return false;
            }
            var horizontalMargin = Math.Max(0.08f, characterBounds.size.x * 0.15f);
            var verticalMargin = Math.Max(0.12f, characterBounds.size.y * 0.25f);
            var intersectsVisibleWidth = characterBounds.max.x
                    >= windowColliders.GetVisibleLeftWorldX() - horizontalMargin
                && characterBounds.min.x
                    <= windowColliders.GetVisibleRightWorldX() + horizontalMargin;
            var intersectsVisibleHeight = characterBounds.max.y
                    >= windowColliders.GetGroundTopWorldY() - verticalMargin
                && characterBounds.min.y
                    <= windowColliders.GetScreenTopWorldY() + verticalMargin;
            return intersectsVisibleWidth && intersectsVisibleHeight;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogDebug(
                $"Could not evaluate visible safety bounds: {exception.Message}");
            return false;
        }
    }

    private static void MonitorAutomaticHiddenRecovery()
    {
        if (Time.unscaledTime < _nextAutomaticHiddenStateCheckAt)
            return;
        _nextAutomaticHiddenStateCheckAt = Time.unscaledTime + 0.05f;

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        if (character == null)
        {
            var allCharacters = Resources.FindObjectsOfTypeAll<global::CharacterController>();
            for (var i = 0; i < allCharacters.Length; i++)
            {
                if (allCharacters[i] == null)
                    continue;
                character = allCharacters[i];
                break;
            }
        }
        if (character == null)
            return;

        var safetyHidden = character.IsHiddenAway
            || character.ControlMode == LilithControlMode.HiddenAway;
        var showcaseNeglectHidden = _actionShowcaseCoherentRandomActive
            && (character.IsNeglectHidden
                || character.ControlMode == LilithControlMode.NeglectHidden);
        if (!safetyHidden && !showcaseNeglectHidden)
            return;

        RecoverCharacterFromHiddenState(
            character,
            showcaseNeglectHidden ? "coherent-showcase neglect hide" : "hidden-state monitor",
            cancelNeglect: showcaseNeglectHidden);
    }

    internal static bool RecoverCharacterFromHiddenState(
        global::CharacterController character,
        string source,
        bool cancelNeglect)
    {
        if (character == null)
            return false;
        if (_automaticHiddenRecoveryInProgress)
            return true;
        if (Time.unscaledTime < _automaticHiddenRecoveryCooldownUntil)
            return true;

        _automaticHiddenRecoveryInProgress = true;
        try
        {
            var previousMode = character.ControlMode;
            if (cancelNeglect
                && (character.IsNeglectHidden
                    || previousMode == LilithControlMode.NeglectHidden))
            {
                character.CancelNeglectHide();
            }

            character.ResetPosition();
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            NotifyAutomaticSafetyRecovery(character, state);
            _automaticHiddenRecoveryCooldownUntil = Time.unscaledTime + 0.5f;
            Plugin.PluginLog.LogInfo(
                $"Automatically recovered hidden character from {source}; previousMode={previousMode}, coherentShowcase={_actionShowcaseCoherentRandomActive}.");
            return true;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Could not automatically recover the hidden character from {source}: {exception.Message}");
            return false;
        }
        finally
        {
            _automaticHiddenRecoveryInProgress = false;
        }
    }

    private static void UpdateMotionDirector(DialogueManager manager)
    {
        var mode = ResolveMotionDirectorMode();
        if (mode == MotionDirectorMode.Off)
        {
            if (_motionDirectorWasRunning)
            {
                Plugin.PluginLog.LogInfo("Motion director stopped; no new autonomous intents will be submitted.");
                ResetMotionDirectorSchedule();
            }
            if (!_motionDirectorOffLogged)
            {
                Plugin.PluginLog.LogInfo("Motion director mode=Off; no autonomous proposals; existing motion and physics remain available.");
                _motionDirectorOffLogged = true;
            }
            return;
        }

        _motionDirectorOffLogged = false;
        if (!_motionDirectorWasRunning || _motionDirectorActiveMode != mode)
        {
            ResetMotionDirectorSchedule();
            _motionDirectorWasRunning = true;
            _motionDirectorActiveMode = mode;
            _motionDirectorNextAt = Time.unscaledTime + 1.5f;
            Plugin.PluginLog.LogInfo(
                $"Motion director started: mode={mode}, provider={MotionDecisionProvider.Id}. All actions still require MotionIntentPolicy and DispatchMotionIntent.");
            return;
        }

        if (Time.unscaledTime < _motionDirectorNextAt)
            return;
        if (_activeMotionProposalExecution != null)
        {
            LogMotionDirectorSilence(
                "terminal-verification",
                "Motion director paused while Motion Authority verifies the active proposal's terminal state.");
            _motionDirectorNextAt = Time.unscaledTime + 0.5f;
            return;
        }
        if (_actionShowcaseCoherentRandomActive || _groundWalkSmokeActive)
        {
            LogMotionDirectorSilence("developer-showcase", "Motion director paused while a developer motion test is active.");
            _motionDirectorNextAt = Time.unscaledTime + 1f;
            return;
        }

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (character == null || state == null)
        {
            LogMotionDirectorSilence("character-unavailable", "Motion director is waiting for Lilith's native controllers.");
            _motionDirectorNextAt = Time.unscaledTime + 1f;
            return;
        }

        var sitting = IsMotionVisualSitState(state);
        var canInspectPlatform = state.IsGround
            && !state.IsDrag
            && !state.IsStateMachineLocked
            && (_actionShowcasePendingOperation == ActionShowcasePendingOperation.None)
            && !_actionShowcaseOverlayBehindWindow
            && !_actionShowcaseWindowWalkContinuationActive
            && (state.IsIdle || sitting);
        var hasWindowPlatform = false;
        var isOnDesktopGround = false;
        var canWalkLeft = false;
        var canWalkRight = false;
        if (canInspectPlatform)
        {
            RefreshActionShowcaseAllWindowPlatforms(state);
            hasWindowPlatform = TryAdoptActionShowcasePlatformUnderCharacter(state);
            if (!hasWindowPlatform && sitting && _actionShowcaseWindowHandle != IntPtr.Zero)
                hasWindowPlatform = TryAdoptActionShowcasePlatformByHandle(state, _actionShowcaseWindowHandle);
            if (hasWindowPlatform)
            {
                GetMotionWindowWalkAvailability(
                    state,
                    out canWalkLeft,
                    out canWalkRight);
            }
            else
            {
                isOnDesktopGround = TryGetMotionDesktopGroundWalkAvailability(
                    state,
                    out canWalkLeft,
                    out canWalkRight);
            }
        }

        var hidden = character.IsHiddenAway
            || character.IsNeglectHidden
            || character.ControlMode == LilithControlMode.HiddenAway
            || character.ControlMode == LilithControlMode.NeglectHidden;
        var snapshot = new MotionDirectorSnapshot(
            enabled: true,
            observeOnly: mode == MotionDirectorMode.Observe,
            characterAvailable: !hidden,
            conversationBusy: _requestInFlight || _transcriptionInFlight || _microphoneRecording || _aiPagesAwaitingAdvance,
            isDragging: state.IsDrag,
            isStateMachineLocked: state.IsStateMachineLocked,
            isGrounded: state.IsGround || hasWindowPlatform,
            isNativeIdle: state.IsIdle,
            isPajamas: state.ClothingState == LilithClothingState.Pajamas,
            hasWindowPlatform: hasWindowPlatform,
            isOnDesktopGround: isOnDesktopGround,
            canWalkLeft: canWalkLeft,
            canWalkRight: canWalkRight,
            hasPendingOperation: _actionShowcasePendingOperation != ActionShowcasePendingOperation.None,
            isOverlayBehindWindow: _actionShowcaseOverlayBehindWindow,
            hasWalkContinuation: _actionShowcaseWindowWalkContinuationActive,
            isActionAnimationPlaying: state.IsWalkLeft || state.IsWalkRight || state.IsAnyActionAnimPlaying,
            isSitting: sitting,
            sitCooldownActive: Time.unscaledTime < _motionDirectorSitCooldownUntil
                || _motionDirectorStep < _motionDirectorSitBlockedUntilStep,
            departureAllowed: _motionDirectorStep >= 4,
            step: _motionDirectorStep,
            lastIntent: _motionDirectorLastIntent);
        var proposal = MotionDecisionProvider.Propose(
            snapshot,
            UnityEngine.Random.Range(0, 100),
            UnityEngine.Random.Range(0, 100));
        var d029Step =
            IsD029AggressiveIntegrationOperational()
                ? D029AggressiveIntegrationRuntime
                    .GetSnapshot()
                    .CurrentStep
                : null;
        var selectedProposal =
            D029MotionAssistOpportunitySelector.Select(
                d029Step,
                proposal);
        if (!ReferenceEquals(selectedProposal, proposal))
        {
            Plugin.PluginLog.LogInfo(
                "D-029 selected one safe Motion Director dispatch as the "
                + "dedicated PlayOneShot Assist opportunity; no additional "
                + "RNG, Queue or authority output was produced by selection.");
            proposal = selectedProposal;
        }
        var d022Ownership =
            D022PlayOneShotOwnershipGate.EvaluateDefaultOff(proposal);
        ObserveD022BaselineAssistOpportunity(
            proposal,
            d022Ownership);
        if (d029Step.HasValue
            && d029Step != D029IntegrationStep.MotionAssist
            && d029Step != D029IntegrationStep.CombinedStress)
        {
            // While the bounded integration run is checking non-Motion
            // components, Motion Director remains evaluated but cannot
            // submit an unrelated proposal that would contaminate the
            // fixed run.
            ScheduleNextMotionDirectorDecision();
            return;
        }
        if (d029Step == D029IntegrationStep.MotionAssist
            && proposal.Kind != MotionIntentKind.PlayOneShot)
        {
            ScheduleNextMotionDirectorDecision();
            return;
        }
        if (Plugin.Effective(Plugin.D022BaselineAssistEnabled.Value)
            && d029Step != D029IntegrationStep.CombinedStress
            && proposal.Disposition
                == MotionDirectorDisposition.Dispatch
            && proposal.Kind == MotionIntentKind.PlayOneShot)
        {
            var situation = CreateD022BaselineAssistSituation(
                character,
                state,
                hasWindowPlatform,
                checked(++_d022AssistSituationRevision),
                DateTimeOffset.UtcNow,
                includeQueuedProposalAsPending: true);
            var authorization =
                D022BaselineAssistLiveRuntime.EvaluateOpportunity(
                    proposal,
                    situation,
                    D022LilithBodyBindingVersion);
            if (!authorization.AllowsLegacyDirectSubmission)
            {
                if (authorization.Authorized)
                {
                    D022SliceEQueuePreparation? preparation = null;
                    var restrictedEnqueueResult =
                        MotionProposalIngress.SubmitRestricted(
                            MotionIntentKind.PlayOneShot,
                            MotionIntentSource.Initiative,
                            D022SliceEAssistRuntimeHost.ProducerId,
                            D022SliceACeilings.ProposalLifetime,
                            situation.EvaluatedAt,
                            prospective =>
                            {
                                preparation =
                                    D022BaselineAssistLiveRuntime
                                        .PrepareRestrictedQueue(
                                            prospective,
                                            situation);
                                return preparation.Prepared;
                            });
                    D022BaselineAssistLiveRuntime.RecordQueueSubmission(
                        restrictedEnqueueResult.Accepted);
                    if (restrictedEnqueueResult.Accepted)
                    {
                        RecordD029Signal(
                            D029PluginSignal.D022QueueSubmitted);
                    }
                    Plugin.PluginLog.LogInfo(
                        "D-022 supervised Assist restricted ingress "
                        + $"status={restrictedEnqueueResult.Status}, "
                        + $"contract={preparation?.Status.ToString() ?? "-"}, "
                        + $"proposal={restrictedEnqueueResult.Proposal?.Id.ToString() ?? "-"}, "
                        + "legacyFallback=false.");
                }
                else
                {
                    Plugin.PluginLog.LogInfo(
                        "D-022 supervised Assist owned one PlayOneShot "
                        + $"but did not authorize it: status={authorization.Status}; "
                        + "legacyFallback=false.");
                }
                ScheduleNextMotionDirectorDecision();
                return;
            }
        }

        if (proposal.Disposition == MotionDirectorDisposition.Silence)
        {
            LogMotionDirectorSilence(
                $"silence:{proposal.Reason}",
                $"Motion director chose silence: reason={proposal.Reason}.");
            _motionDirectorNextAt = Time.unscaledTime
                + (proposal.Reason == MotionDirectorReason.ClothingUnsupported ? 5f : 1f);
            return;
        }

        _motionDirectorLastLogKey = string.Empty;
        Plugin.PluginLog.LogInfo(
            $"Motion director proposal: provider={proposal.ProviderId}, disposition={proposal.Disposition}, kind={proposal.Kind}, reason={proposal.Reason}, step={_motionDirectorStep}, surface={(hasWindowPlatform ? "window" : isOnDesktopGround ? "ground" : "none")}, canWalkLeft={canWalkLeft}, canWalkRight={canWalkRight}.");
        if (proposal.Disposition == MotionDirectorDisposition.Observe)
        {
            ScheduleNextMotionDirectorDecision();
            return;
        }
        if (!d022Ownership.AllowsLegacyDirectSubmission)
        {
            ScheduleNextMotionDirectorDecision();
            return;
        }

        var enqueueResult = MotionProposalIngress.Submit(
            proposal.Kind,
            proposal.Source,
            proposal.ProviderId,
            MotionDirectorProposalTimeToLive);
        if (!enqueueResult.Accepted || enqueueResult.Proposal == null)
        {
            Plugin.PluginLog.LogWarning(
                $"Motion proposal rejected at ingress: provider={proposal.ProviderId}, kind={proposal.Kind}, source={proposal.Source}, status={enqueueResult.Status}.");
            _motionDirectorNextAt = Time.unscaledTime + 1.5f;
            return;
        }
        if (D029CombinedStressMotionGate.TryCaptureProposal(
                d029Step,
                enqueueResult.Proposal.Id))
        {
            RecordD029Signal(
                D029PluginSignal.MotionDirectorQueueSubmitted);
        }

        var queueSnapshot = MotionProposalIngress.GetSnapshot();
        Plugin.PluginLog.LogInfo(
            $"Motion proposal queued: id={enqueueResult.Proposal.Id}, sequence={enqueueResult.Proposal.Sequence}, producer={enqueueResult.Proposal.ProducerId}, source={enqueueResult.Proposal.Source}, kind={enqueueResult.Proposal.Kind}, ttlMs={MotionDirectorProposalTimeToLive.TotalMilliseconds:F0}, queued={queueSnapshot.Count}/{queueSnapshot.Capacity}.");
        ScheduleNextMotionDirectorDecision();
    }

    private static D022SliceELiveSituation
        CreateD022BaselineAssistSituation(
            global::CharacterController character,
            LilithStateManager state,
            bool hasWindowPlatform,
            long revision,
            DateTimeOffset evaluatedAt,
            bool includeQueuedProposalAsPending)
    {
        var hidden = character.IsHiddenAway
            || character.IsNeglectHidden
            || character.ControlMode == LilithControlMode.HiddenAway
            || character.ControlMode == LilithControlMode.NeglectHidden;
        var pending = _activeMotionProposalExecution != null
            || _actionShowcasePendingOperation
                != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcaseWindowWalkContinuationActive
            || (includeQueuedProposalAsPending
                && MotionProposalIngress.GetSnapshot().Count > 0);
        var conversationBusy = _requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _aiPagesAwaitingAdvance;
        return new D022SliceELiveSituation(
            revision,
            evaluatedAt,
            state.IsDrag,
            conversationBusy,
            pending,
            isQuietPeriod: false,
            state.HasActionAnimation(LilithActionType.Greet),
            characterAvailable: !hidden,
            isGrounded: state.IsGround || hasWindowPlatform,
            isNativeIdle: state.IsIdle
                && !IsMotionVisualSitState(state)
                && !state.IsWalkLeft
                && !state.IsWalkRight
                && !state.IsAnyActionAnimPlaying
                && !state.IsStateMachineLocked,
            isPajamas:
                state.ClothingState
                    == LilithClothingState.Pajamas);
    }

    private static void UpdateMotionProposalQueue(DialogueManager manager)
    {
        if (_activeMotionProposalExecution != null
            || _actionShowcaseCoherentRandomActive
            || _groundWalkSmokeActive)
            return;

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (character == null || state == null)
            return;
        var sittingOnKnownWindow = IsMotionVisualSitState(state)
            && (_actionShowcaseHasWindowPlatform
                || (_actionShowcaseWindowHandle != IntPtr.Zero
                    && ActionShowcaseWindowPlatforms.ContainsKey(_actionShowcaseWindowHandle)));
        if (_requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _aiPagesAwaitingAdvance
            || state.IsDrag
            || state.IsStateMachineLocked
            || (!state.IsGround && !sittingOnKnownWindow)
            || state.IsWalkLeft
            || state.IsWalkRight
            || state.IsAnyActionAnimPlaying
            || _actionShowcasePendingOperation != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcaseWindowWalkContinuationActive)
        {
            return;
        }

        var now = DateTimeOffset.UtcNow;
        var takeResult = MotionProposalIngress.TakeNext(now);
        if (takeResult.ExpiredSkipped > 0)
        {
            var expiredSnapshot = MotionProposalIngress.GetSnapshot();
            Plugin.PluginLog.LogInfo(
                $"Motion proposal queue expired stale entries: skipped={takeResult.ExpiredSkipped}, totalExpired={expiredSnapshot.Expired}, queued={expiredSnapshot.Count}/{expiredSnapshot.Capacity}.");
        }
        if (!takeResult.HasProposal || takeResult.Proposal == null)
            return;

        var proposal = takeResult.Proposal;
        var isD022AssistProposal =
            D022BaselineAssistLiveRuntime.MatchesActiveProposal(
                proposal);
        var request = MotionIntentRequest.Create(
            proposal.Id,
            proposal.Kind,
            proposal.Source,
            proposal.CreatedAt);
        if (string.Equals(
                proposal.ProducerId,
                D022SliceEAssistRuntimeHost.ProducerId,
                StringComparison.Ordinal))
        {
            var situation = CreateD022BaselineAssistSituation(
                character,
                state,
                _actionShowcaseHasWindowPlatform,
                Math.Max(
                    1,
                    D022BaselineAssistLiveRuntime
                        .ActiveSituationRevision),
                now,
                includeQueuedProposalAsPending: false);
            if (!isD022AssistProposal
                || !D022BaselineAssistLiveRuntime
                    .RevalidateBeforeExecution(
                        proposal,
                        situation))
            {
                var rejected = PublishMotionIntentResult(
                    MotionIntentResult.Rejected(
                        request,
                        MotionIntentReason.ExecutionFailed,
                        "D-022 restricted proposal failed its "
                        + "identity, deadline, generation, Situation "
                        + "or body-safety revalidation."));
                var rejectedPublished =
                    MotionProposalCompletions.Publish(
                        proposal,
                        rejected);
                Plugin.PluginLog.LogWarning(
                    "D-022 restricted proposal was rejected before "
                    + $"Dispatcher: id={proposal.Id}, "
                    + $"completionPublished={rejectedPublished}, "
                    + "legacyFallback=false.");
                return;
            }
        }
        var initialObservation = CaptureMotionExecutionObservation(character, state);
        var result = DispatchMotionIntent(
            manager,
            character,
            state,
            request,
            useD022FixedBodyBinding: isD022AssistProposal);
        var terminalPending = result.Status == MotionIntentStatus.Started;
        var completionPublished = false;
        if (terminalPending)
        {
            if (isD022AssistProposal)
            {
                var startedAdmission =
                    D022BaselineAssistLiveRuntime.RecordLifecycle(
                        D022SliceCLifecycleKind.Started,
                        MotionIntentReason.None,
                        result.RecordedAt);
                if (startedAdmission?.Accepted != true)
                {
                    character.InterruptActionForReminder();
                    character.ClearEmotion();
                    state.ReturnIdle();
                    result = MotionIntentResult.Failed(
                        request,
                        MotionIntentReason.ExecutionFailed,
                        "D-022 Started lifecycle correlation was "
                        + "rejected; the native action was cancelled.");
                    terminalPending = false;
                }
            }
        }
        if (terminalPending)
        {
            _activeMotionProposalExecution = new ActiveMotionProposalExecution(
                proposal,
                request,
                new MotionExecutionTracker(proposal.Kind, initialObservation),
                Time.unscaledTime);
            Plugin.PluginLog.LogInfo(
                $"Motion authority began terminal verification: id={proposal.Id}, producer={proposal.ProducerId}, kind={proposal.Kind}, initialAnimation={initialObservation.AnimationName}, initialSurface={(initialObservation.HasWindowPlatform ? "window" : initialObservation.IsOnDesktopGround ? "ground" : "none")}.");
        }
        else
        {
            completionPublished = MotionProposalCompletions.Publish(proposal, result);
        }
        if (!terminalPending && !completionPublished)
        {
            Plugin.PluginLog.LogWarning(
                $"Motion proposal completion correlation failed: proposalId={proposal.Id}, resultId={result.RequestId}, producer={proposal.ProducerId}, kind={proposal.Kind}, resultKind={result.Kind}.");
        }
        var queueSnapshot = MotionProposalIngress.GetSnapshot();
        var latency = Math.Max(0d, (now - proposal.CreatedAt).TotalMilliseconds);
        Plugin.PluginLog.LogInfo(
            $"Motion proposal dispatched: id={proposal.Id}, sequence={proposal.Sequence}, producer={proposal.ProducerId}, source={proposal.Source}, kind={proposal.Kind}, latencyMs={latency:F1}, status={result.Status}, reason={result.Reason}, terminalPending={terminalPending}, completionPublished={completionPublished}, completionSubscribers={MotionProposalCompletions.SubscriberCount}, queued={queueSnapshot.Count}/{queueSnapshot.Capacity}.");
    }

    private static void CancelD022AssistWork(
        MotionIntentReason reason,
        string detail)
    {
        var expectation =
            D022BaselineAssistLiveRuntime.ActiveExpectation;
        if (expectation == null)
            return;

        var active = _activeMotionProposalExecution;
        if (active != null
            && D022BaselineAssistLiveRuntime.MatchesActiveProposal(
                active.Proposal))
        {
            var character =
                UnityEngine.Object.FindObjectOfType<
                    global::CharacterController>();
            var state =
                UnityEngine.Object.FindObjectOfType<
                    LilithStateManager>();
            if (character != null && state != null)
            {
                character.InterruptActionForReminder();
                character.ClearEmotion();
                if (!state.IsDrag)
                {
                    state.ClearWalkTarget();
                    state.ReturnIdle();
                }
            }

            var result = MotionIntentResult.Interrupted(
                active.Request,
                reason,
                detail);
            _activeMotionProposalExecution = null;
            PublishMotionIntentResult(result);
            var published = MotionProposalCompletions.Publish(
                active.Proposal,
                result);
            DrainD022BaselineAssistCompletions();
            Plugin.PluginLog.LogInfo(
                "D-022 active one-shot was cancelled immediately: "
                + $"proposal={active.Proposal.Id}, reason={reason}, "
                + $"completionPublished={published}, "
                + "legacyFallback=false.");
            return;
        }

        if (MotionProposalIngress.Cancel(expectation.ProposalId))
        {
            D022BaselineAssistLiveRuntime.RecordLifecycle(
                reason == MotionIntentReason.PlayerInterrupted
                    ? D022SliceCLifecycleKind.PlayerInterrupted
                    : D022SliceCLifecycleKind.Failed,
                reason,
                DateTimeOffset.UtcNow);
            Plugin.PluginLog.LogInfo(
                "D-022 queued one-shot was cancelled before dispatch: "
                + $"proposal={expectation.ProposalId}, reason={reason}, "
                + "legacyFallback=false.");
        }
    }

    private static void UpdateMotionExecutionAuthority()
    {
        var active = _activeMotionProposalExecution;
        if (active == null)
            return;

        var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        var observation = CaptureMotionExecutionObservation(character, state);
        var elapsed = Math.Max(0d, Time.unscaledTime - active.StartedAt);
        var update = active.Tracker.Observe(observation, elapsed);
        if (update.Phase != active.LastLoggedPhase)
        {
            active.LastLoggedPhase = update.Phase;
            Plugin.PluginLog.LogInfo(
                $"Motion authority phase: id={active.Proposal.Id}, kind={active.Proposal.Kind}, phase={update.Phase}, elapsed={elapsed:F2}, evidence={active.Tracker.EvidenceObserved}, animation={observation.AnimationName}, grounded={observation.IsGrounded}, window={observation.HasWindowPlatform}, ground={observation.IsOnDesktopGround}, velocity=({observation.VelocityX:F2},{observation.VelocityY:F2}).");
        }
        if (!update.IsTerminal)
            return;

        var result = update.Status switch
        {
            MotionIntentStatus.Completed => MotionIntentResult.Completed(active.Request, update.Detail),
            MotionIntentStatus.Interrupted => MotionIntentResult.Interrupted(
                active.Request,
                update.Reason,
                update.Detail),
            _ => MotionIntentResult.Failed(
                active.Request,
                update.Reason,
                update.Detail)
        };
        _activeMotionProposalExecution = null;
        PublishMotionIntentResult(result);

        if (active.Request.Kind == MotionIntentKind.Sit)
        {
            _motionIntentSitActive = result.Status == MotionIntentStatus.Completed;
            if (result.Status != MotionIntentStatus.Completed
                && result.Reason != MotionIntentReason.PlayerInterrupted
                && character != null
                && state != null)
            {
                ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
            }
        }
        else if (active.Request.Kind == MotionIntentKind.Stand
            && result.Status == MotionIntentStatus.Completed)
        {
            _motionIntentSitActive = false;
        }

        var completionPublished = MotionProposalCompletions.Publish(active.Proposal, result);
        Plugin.PluginLog.LogInfo(
            $"Motion authority terminal result: id={active.Proposal.Id}, producer={active.Proposal.ProducerId}, kind={active.Proposal.Kind}, status={result.Status}, reason={result.Reason}, elapsed={elapsed:F2}, evidence={active.Tracker.EvidenceObserved}, completionPublished={completionPublished}.");
        if (!completionPublished)
        {
            Plugin.PluginLog.LogWarning(
                $"Motion authority terminal completion correlation failed: proposalId={active.Proposal.Id}, resultId={result.RequestId}, producer={active.Proposal.ProducerId}, kind={active.Proposal.Kind}.");
        }
    }

    private static MotionExecutionObservation CaptureMotionExecutionObservation(
        global::CharacterController? character,
        LilithStateManager? state)
    {
        if (character == null || state == null)
        {
            return new MotionExecutionObservation(
                characterAvailable: false,
                isDragging: false,
                isGrounded: false,
                hasWindowPlatform: false,
                isOnDesktopGround: false,
                isSitting: false,
                isLyingDown: false,
                isSleeping: false,
                isWalkingLeft: false,
                isWalkingRight: false,
                isActionAnimationPlaying: false,
                hasPendingOperation: false,
                isOverlayBehindWindow: false,
                hasWalkContinuation: false,
                animationName: string.Empty,
                positionX: 0f,
                positionY: 0f,
                velocityX: 0f,
                velocityY: 0f);
        }

        var hasWindowPlatform = false;
        var isOnDesktopGround = false;
        try
        {
            RefreshActionShowcaseAllWindowPlatforms(state);
            hasWindowPlatform = TryFindActionShowcasePlatformUnderCharacter(state, out _);
            if (!hasWindowPlatform && state.IsGround)
            {
                isOnDesktopGround = TryGetMotionDesktopGroundWalkAvailability(
                    state,
                    out _,
                    out _);
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogDebug(
                $"Motion authority could not refresh one surface observation: {exception.Message}");
        }

        var body = state.GetComponent<Rigidbody2D>();
        var velocity = body != null ? body.velocity : Vector2.zero;
        var animationName = string.Empty;
        try
        {
            animationName = state.SkeletonAnimation?.AnimationName ?? string.Empty;
        }
        catch
        {
            // The visual controller can be swapped for one frame during clothing changes.
        }
        return new MotionExecutionObservation(
            characterAvailable: true,
            isDragging: state.IsDrag,
            isGrounded: state.IsGround,
            hasWindowPlatform: hasWindowPlatform,
            isOnDesktopGround: isOnDesktopGround,
            isSitting: state.IsSit,
            isLyingDown: state.IsLieDown,
            isSleeping: state.IsSleep,
            isWalkingLeft: state.IsWalkLeft,
            isWalkingRight: state.IsWalkRight,
            isActionAnimationPlaying: state.IsAnyActionAnimPlaying,
            hasPendingOperation: _actionShowcasePendingOperation != ActionShowcasePendingOperation.None,
            isOverlayBehindWindow: _actionShowcaseOverlayBehindWindow,
            hasWalkContinuation: _actionShowcaseWindowWalkContinuationActive,
            animationName: animationName,
            positionX: state.transform.position.x,
            positionY: state.transform.position.y,
            velocityX: velocity.x,
            velocityY: velocity.y);
    }

    private static bool IsMotionVisualSitState(LilithStateManager state)
    {
        if (!state.IsSit)
            return false;
        try
        {
            var animationName = state.SkeletonAnimation?.AnimationName ?? string.Empty;
            return animationName.StartsWith("sit_", StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private static void UpdateMotionProposalCompletions()
    {
        DrainD022BaselineAssistCompletions();

        while (MotionDirectorCompletionSubscription.TryRead(out var completion))
        {
            if (completion == null)
                continue;
            Plugin.PluginLog.LogInfo(
                $"Motion director completion received: id={completion.ProposalId}, sequence={completion.Sequence}, producer={completion.ProducerId}, kind={completion.Kind}, status={completion.Status}, reason={completion.Reason}.");
            if (!_motionDirectorWasRunning
                || _motionDirectorActiveMode != MotionDirectorMode.LocalRules)
            {
                continue;
            }
            var d029Step = IsD029AggressiveIntegrationOperational()
                ? D029AggressiveIntegrationRuntime
                    .GetSnapshot()
                    .CurrentStep
                : null;
            if (D029CombinedStressMotionGate.TryCaptureCompletion(
                    d029Step,
                    completion.ProposalId,
                    completion.Status == MotionIntentStatus.Completed))
            {
                RecordD029Signal(
                    D029PluginSignal
                        .MotionDirectorMotionCompleted);
            }
            CommitMotionDirectorCompletion(completion);
        }

        while (ModelMotionAssistCompletionSubscription.TryRead(out var completion))
        {
            if (completion == null)
                continue;
            Plugin.PluginLog.LogInfo(
                $"Model motion Assist completion received: id={completion.ProposalId}, sequence={completion.Sequence}, producer={completion.ProducerId}, kind={completion.Kind}, status={completion.Status}, reason={completion.Reason}.");
        }
    }

    private static void DrainD022BaselineAssistCompletions()
    {
        while (D022BaselineAssistCompletionSubscription.TryRead(
                   out var completion))
        {
            if (completion == null)
                continue;
            var admission =
                D022BaselineAssistLiveRuntime.RecordCompletion(
                    completion);
            if (completion.Status == MotionIntentStatus.Completed
                && admission?.Accepted == true)
            {
                RecordD029Signal(
                    D029PluginSignal.D022MotionCompleted);
            }
            Plugin.PluginLog.LogInfo(
                "D-022 exact completion received: "
                + $"id={completion.ProposalId}, "
                + $"sequence={completion.Sequence}, "
                + $"status={completion.Status}, "
                + $"reason={completion.Reason}, "
                + $"admission={admission?.Status.ToString() ?? "Rejected"}, "
                + "recordOnly=true.");
        }
    }

    private static void EnqueueAgentMotionObservation(
        AgentTurnRequest request,
        IAgentAdapter adapter,
        AgentTurnResponse response,
        string provider,
        DateTimeOffset completedAt,
        ModelMotionSuggestionMode modeAtRequest)
    {
        const int maximumPendingObservations = 32;
        while (PendingAgentMotionObservations.Count >= maximumPendingObservations
            && PendingAgentMotionObservations.TryDequeue(out _))
        {
        }
        PendingAgentMotionObservations.Enqueue(new PendingAgentMotionObservation(
            request,
            adapter,
            response,
            provider,
            completedAt,
            modeAtRequest));
    }

    private static void SynchronizeModelMotionSuggestionMode(ModelMotionSuggestionMode mode)
    {
        if (!_modelMotionSuggestionModeInitialized)
        {
            _modelMotionSuggestionModeInitialized = true;
            _modelMotionSuggestionActiveMode = mode;
            Plugin.PluginLog.LogInfo($"Model motion suggestion mode initialized: mode={mode}.");
            return;
        }
        if (_modelMotionSuggestionActiveMode == mode)
            return;

        var previous = _modelMotionSuggestionActiveMode;
        _modelMotionSuggestionActiveMode = mode;
        if (AgentMotionSuggestionControlledAssistPlanner.ShouldCancelQueuedProposals(previous, mode))
        {
            var canceled = MotionProposalIngress.CancelByProducer(ModelMotionAssistProducerId);
            _modelMotionAssistCooldownUntil = -1f;
            Plugin.PluginLog.LogInfo(
                $"Model motion Assist disabled: previous={previous}, current={mode}, canceledQueued={canceled}.");
        }
        else
        {
            Plugin.PluginLog.LogInfo(
                $"Model motion suggestion mode changed: previous={previous}, current={mode}.");
        }
    }

    private static void UpdateAgentMotionSuggestionObservations()
    {
        const int maximumReviewsPerFrame = 4;
        for (var processed = 0;
             processed < maximumReviewsPerFrame
                && PendingAgentMotionObservations.TryDequeue(out var observation);
             processed++)
        {
            var character = UnityEngine.Object.FindObjectOfType<global::CharacterController>();
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            var snapshot = CaptureAgentMotionObservationSnapshot(character, state);
            var review = AgentMotionSuggestionObserver.Review(
                observation.Adapter,
                observation.Response,
                snapshot);
            var currentMode = ResolveModelMotionSuggestionMode();
            SynchronizeModelMotionSuggestionMode(currentMode);
            var effectiveMode = AgentMotionSuggestionControlledAssistPlanner.ResolveEffectiveMode(
                observation.ModeAtRequest,
                currentMode);
            var plan = AgentMotionSuggestionControlledAssistPlanner.Plan(
                effectiveMode,
                review,
                cooldownReady: Time.unscaledTime >= _modelMotionAssistCooldownUntil);
            MotionProposalEnqueueResult? enqueueResult = null;
            if (plan.HasSelection)
            {
                enqueueResult = MotionProposalIngress.Submit(
                    plan.SelectedKind,
                    MotionIntentSource.Model,
                    ModelMotionAssistProducerId,
                    ModelMotionAssistProposalTimeToLive);
                if (enqueueResult.Value.Accepted)
                {
                    var cooldown = AgentMotionSuggestionControlledAssistPlanner.ClampCooldownSeconds(
                        Plugin.ModelMotionAssistCooldownSeconds.Value);
                    _modelMotionAssistCooldownUntil = Time.unscaledTime + cooldown;
                }
            }
            var queueWrites = enqueueResult.HasValue && enqueueResult.Value.Accepted ? 1 : 0;
            var age = Math.Max(0d, (DateTimeOffset.UtcNow - observation.CompletedAt).TotalMilliseconds);
            Plugin.PluginLog.LogInfo(
                $"Model motion controlled review: id={ShortOpaqueId(observation.Request.Id.ToString("N"))}, provider={observation.Provider}, adapter={observation.Adapter.Id}, requestMode={observation.ModeAtRequest}, currentMode={currentMode}, effectiveMode={effectiveMode}, suggested={review.SuggestedCount}, reviewed={review.ReviewedCount}, dropped={review.DroppedByTurnLimit}, capability={review.CapabilityAdvertised}, plan={plan.Reason}, selected={plan.SelectedKind}, lowRiskCandidates={plan.LowRiskCandidates}, policyRejected={plan.PolicyRejectedCandidates}, ageMs={age:F0}, queueWrites={queueWrites}, ingressStatus={(enqueueResult.HasValue ? enqueueResult.Value.Status.ToString() : "not-attempted")}, executions=0, additionalProviderRequests={plan.AdditionalProviderRequests}.");
            foreach (var item in review.Items)
            {
                Plugin.PluginLog.LogInfo(
                    $"Model motion controlled decision: id={ShortOpaqueId(observation.Request.Id.ToString("N"))}, kind={item.Kind}, lowRisk={AgentMotionSuggestionControlledAssistPlanner.IsLowRiskAssistKind(item.Kind)}, wouldAllow={item.Allowed}, reason={item.Reason}, selected={plan.HasSelection && plan.SelectedKind == item.Kind}, executed=false.");
            }
        }
    }

    private static MotionPolicySnapshot CaptureAgentMotionObservationSnapshot(
        global::CharacterController? character,
        LilithStateManager? state)
    {
        if (character == null || state == null)
        {
            return new MotionPolicySnapshot(
                characterAvailable: false,
                conversationBusy: _requestInFlight || _transcriptionInFlight || _microphoneRecording || _aiPagesAwaitingAdvance,
                isDragging: false,
                isStateMachineLocked: false,
                isGrounded: false,
                isPajamas: false,
                hasWindowPlatform: false,
                isOnDesktopGround: false,
                hasPendingOperation: false,
                isOverlayBehindWindow: false,
                hasWalkContinuation: false,
                isActionAnimationPlaying: false,
                isSitting: false,
                isSleeping: false,
                canWalkLeft: false,
                canWalkRight: false);
        }

        var sitting = IsMotionVisualSitState(state);
        var hasWindowPlatform = false;
        var canRecoverWindowSupport = Time.unscaledTime <= _actionShowcaseSupportedWindowUntil
            && _actionShowcaseSupportedWindowHandle != IntPtr.Zero;
        var canWalkLeft = false;
        var canWalkRight = false;
        if ((state.IsGround || sitting || canRecoverWindowSupport)
            && !state.IsDrag
            && _actionShowcasePendingOperation == ActionShowcasePendingOperation.None
            && !_actionShowcaseOverlayBehindWindow)
        {
            try
            {
                hasWindowPlatform = TryResolveMotionWindowPlatform(state, sitting);
                if (hasWindowPlatform)
                {
                    GetMotionWindowWalkAvailability(
                        state,
                        out canWalkLeft,
                        out canWalkRight);
                }
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogDebug(
                    $"Model motion review could not refresh its live surface snapshot: {exception.Message}");
            }
        }
        var isOnDesktopGround = false;
        if (state.IsGround && !hasWindowPlatform)
        {
            try
            {
                isOnDesktopGround = TryGetMotionDesktopGroundWalkAvailability(
                    state,
                    out canWalkLeft,
                    out canWalkRight);
            }
            catch
            {
                isOnDesktopGround = false;
            }
        }

        return new MotionPolicySnapshot(
            characterAvailable: true,
            conversationBusy: _requestInFlight || _transcriptionInFlight || _microphoneRecording || _aiPagesAwaitingAdvance,
            isDragging: state.IsDrag,
            isStateMachineLocked: state.IsStateMachineLocked,
            isGrounded: state.IsGround || hasWindowPlatform,
            isPajamas: state.ClothingState == LilithClothingState.Pajamas,
            hasWindowPlatform: hasWindowPlatform,
            isOnDesktopGround: isOnDesktopGround,
            hasPendingOperation: _actionShowcasePendingOperation != ActionShowcasePendingOperation.None,
            isOverlayBehindWindow: _actionShowcaseOverlayBehindWindow,
            hasWalkContinuation: _actionShowcaseWindowWalkContinuationActive,
            isActionAnimationPlaying: state.IsWalkLeft || state.IsWalkRight || state.IsAnyActionAnimPlaying,
            isSitting: sitting,
            isSleeping: state.IsSleep,
            canWalkLeft: canWalkLeft,
            canWalkRight: canWalkRight);
    }

    private static void CommitMotionDirectorCompletion(
        MotionProposalCompletion completion)
    {
        if (completion.Status != MotionIntentStatus.Completed)
        {
            _motionDirectorNextAt = Time.unscaledTime + 1.5f;
            return;
        }

        _motionDirectorLastIntent = completion.Kind;
        _motionDirectorStep++;
        if (completion.Kind == MotionIntentKind.Stand)
        {
            _motionDirectorSitCooldownUntil = Time.unscaledTime + UnityEngine.Random.Range(14f, 22f);
            _motionDirectorSitBlockedUntilStep = _motionDirectorStep + 3;
        }
    }

    private static MotionDirectorMode ResolveMotionDirectorMode()
    {
        // The player's motion master switch is a veto, not a Formal opt-in.
        if (!Plugin.MotionDirectorEnabled.Value)
        {
            _motionDirectorInvalidModeLogged = false;
            return MotionDirectorMode.Off;
        }

        if (Plugin.FormalIntegrationActive)
        {
            _motionDirectorInvalidModeLogged = false;
            return MotionDirectorMode.LocalRules;
        }

        var configured = (Plugin.MotionDirectorModeSetting.Value ?? string.Empty).Trim();
        if (configured.Equals("Observe", StringComparison.OrdinalIgnoreCase))
        {
            _motionDirectorInvalidModeLogged = false;
            return MotionDirectorMode.Observe;
        }
        if (configured.Equals("LocalRules", StringComparison.OrdinalIgnoreCase)
            || configured.Equals("Local-Rules", StringComparison.OrdinalIgnoreCase)
            || configured.Equals("Act", StringComparison.OrdinalIgnoreCase))
        {
            _motionDirectorInvalidModeLogged = false;
            return MotionDirectorMode.LocalRules;
        }
        if (configured.Equals("Off", StringComparison.OrdinalIgnoreCase))
        {
            _motionDirectorInvalidModeLogged = false;
            return MotionDirectorMode.Off;
        }

        if (!_motionDirectorInvalidModeLogged)
        {
            _motionDirectorInvalidModeLogged = true;
            Plugin.PluginLog.LogWarning(
                $"Unknown MotionDirector.Mode '{configured}'. Failing closed; expected Off, Observe, or LocalRules.");
        }
        return MotionDirectorMode.Off;
    }

    private static void ResetMotionDirectorSchedule()
    {
        var canceled = MotionProposalIngress.CancelByProducer(MotionDecisionProvider.Id);
        if (canceled > 0)
        {
            Plugin.PluginLog.LogInfo(
                $"Motion director canceled {canceled} queued proposal(s) while resetting its schedule.");
        }
        while (MotionDirectorCompletionSubscription.TryRead(out _))
        {
        }
        _motionDirectorWasRunning = false;
        _motionDirectorActiveMode = MotionDirectorMode.Off;
        _motionDirectorNextAt = -1f;
        _motionDirectorStep = 0;
        _motionDirectorLastIntent = MotionIntentKind.None;
        _motionDirectorSitCooldownUntil = -1f;
        _motionDirectorSitBlockedUntilStep = 0;
        _motionDirectorLastLogKey = string.Empty;
    }

    private static void ScheduleNextMotionDirectorDecision()
    {
        var minimum = Math.Clamp(Plugin.MotionDirectorMinimumIntervalSeconds.Value, 2f, 120f);
        var maximum = Math.Clamp(Plugin.MotionDirectorMaximumIntervalSeconds.Value, minimum, 300f);
        _motionDirectorNextAt = Time.unscaledTime + UnityEngine.Random.Range(minimum, maximum);
    }

    private static void LogMotionDirectorSilence(string key, string message)
    {
        if (string.Equals(_motionDirectorLastLogKey, key, StringComparison.Ordinal))
            return;
        _motionDirectorLastLogKey = key;
        Plugin.PluginLog.LogInfo(message);
    }

    private static void UpdateActionShowcaseCoherentRandom(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (!_actionShowcaseCoherentRandomActive)
            return;
        if (_actionShowcaseGroup != 4 || ActionShowcaseIndices[4] != 8)
        {
            StopActionShowcaseCoherentRandom();
            return;
        }
        if (state.ClothingState == LilithClothingState.Pajamas)
        {
            StopActionShowcaseCoherentRandom();
            ResetActionShowcaseCharacter(character, state);
            ShowActionShowcaseMessage(manager, "連貫展示：已進入睡衣狀態，停止桌面走動。", 5f);
            Plugin.PluginLog.LogInfo("Exploration coherent random showcase stopped after entering Pajamas.");
            return;
        }
        if (_actionShowcasePendingOperation != ActionShowcasePendingOperation.None
            || _actionShowcaseOverlayBehindWindow
            || _actionShowcaseWindowWalkContinuationActive
            || state.IsDrag
            || Time.unscaledTime < _actionShowcaseCoherentRandomNextAt)
        {
            return;
        }
        if (IsMotionVisualSitState(state))
        {
            ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
            _actionShowcaseCoherentRandomLastAction = ActionShowcaseCoherentAction.Stand;
            _actionShowcaseCoherentRandomStep++;
            _actionShowcaseCoherentRandomSitCooldownUntil = Time.unscaledTime
                + UnityEngine.Random.Range(12f, 18f);
            _actionShowcaseCoherentRandomSitBlockedUntilStep =
                _actionShowcaseCoherentRandomStep + 3;
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime
                + UnityEngine.Random.Range(0.75f, 1.25f);
            ShowActionShowcaseMessage(manager, "連貫展示：休息夠了，起身繼續探索。", 4f);
            Plugin.PluginLog.LogInfo(
                $"Exploration coherent random showcase stood up after sitting; sit cooldown until step {_actionShowcaseCoherentRandomSitBlockedUntilStep} and time {_actionShowcaseCoherentRandomSitCooldownUntil:F2}.");
            return;
        }
        if (state.IsStateMachineLocked)
            return;
        if (!state.IsGround)
        {
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.12f;
            return;
        }
        if (state.IsWalkLeft || state.IsWalkRight || state.IsAnyActionAnimPlaying)
        {
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.12f;
            return;
        }

        RefreshActionShowcaseAllWindowPlatforms(state);
        if (!TryAdoptActionShowcasePlatformUnderCharacter(state))
        {
            if (BeginActionShowcaseCoherentWindowSnap(manager, character, state))
            {
                _actionShowcaseCoherentRandomLastAction = ActionShowcaseCoherentAction.ArriveWindow;
                _actionShowcaseCoherentRandomStep++;
                var snapDuration = 1f;
                if (state.TryGetActionDuration(LilithActionType.Snap, out var detectedSnapDuration)
                    && detectedSnapDuration > 0f)
                {
                    snapDuration = detectedSnapDuration;
                }
                _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + snapDuration + 0.45f;
            }
            else
            {
                _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 1.25f;
            }
            return;
        }

        var nextAction = ChooseActionShowcaseCoherentAction();
        if (nextAction == ActionShowcaseCoherentAction.Sit
            && (Time.unscaledTime < _actionShowcaseCoherentRandomSitCooldownUntil
                || _actionShowcaseCoherentRandomStep
                    < _actionShowcaseCoherentRandomSitBlockedUntilStep))
        {
            nextAction = UnityEngine.Random.Range(0, 100) < 55
                ? ChooseActionShowcaseCoherentWalkDirection()
                : ActionShowcaseCoherentAction.OneShot;
        }
        var motionRequest = MotionIntentRequest.Create(
            ToMotionIntentKind(nextAction),
            MotionIntentSource.Showcase);
        var motionResult = DispatchMotionIntent(manager, character, state, motionRequest);
        if (motionResult.Status != MotionIntentStatus.Started)
        {
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.8f;
            return;
        }

        switch (nextAction)
        {
            case ActionShowcaseCoherentAction.WalkLeft:
            case ActionShowcaseCoherentAction.WalkRight:
                CommitActionShowcaseCoherentAction(nextAction, 0.65f, 1.1f);
                break;
            case ActionShowcaseCoherentAction.Sit:
                CommitActionShowcaseCoherentAction(nextAction, 3.5f, 6f);
                break;
            case ActionShowcaseCoherentAction.Peek:
                CommitActionShowcaseCoherentAction(nextAction, 3.2f, 4.2f);
                break;
            case ActionShowcaseCoherentAction.Drop:
                CommitActionShowcaseCoherentAction(nextAction, 0.8f, 1.2f);
                break;
            case ActionShowcaseCoherentAction.Stand:
                CommitActionShowcaseCoherentAction(nextAction, 0.75f, 1.25f);
                break;
        }
    }

    private static MotionIntentKind ToMotionIntentKind(ActionShowcaseCoherentAction action) => action switch
    {
        ActionShowcaseCoherentAction.ArriveWindow => MotionIntentKind.ArriveAtWindow,
        ActionShowcaseCoherentAction.WalkLeft => MotionIntentKind.WalkLeft,
        ActionShowcaseCoherentAction.WalkRight => MotionIntentKind.WalkRight,
        ActionShowcaseCoherentAction.OneShot => MotionIntentKind.PlayOneShot,
        ActionShowcaseCoherentAction.Sit => MotionIntentKind.Sit,
        ActionShowcaseCoherentAction.Stand => MotionIntentKind.Stand,
        ActionShowcaseCoherentAction.Peek => MotionIntentKind.PeekFromWindow,
        ActionShowcaseCoherentAction.Drop => MotionIntentKind.DropFromWindow,
        _ => MotionIntentKind.None
    };

    private static MotionIntentResult DispatchMotionIntent(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        MotionIntentRequest request,
        bool useD022FixedBodyBinding = false)
    {
        var sitting = IsMotionVisualSitState(state);
        var canRecoverWindowSupport = Time.unscaledTime <= _actionShowcaseSupportedWindowUntil
            && _actionShowcaseSupportedWindowHandle != IntPtr.Zero;
        var canInspectSurface = (state.IsGround || sitting || canRecoverWindowSupport)
            && !state.IsDrag
            && !state.IsStateMachineLocked
            && _actionShowcasePendingOperation == ActionShowcasePendingOperation.None
            && !_actionShowcaseOverlayBehindWindow
            && !_actionShowcaseWindowWalkContinuationActive
            && (state.IsIdle || sitting);
        var hasWindowPlatform = false;
        var isOnDesktopGround = false;
        var canWalkLeft = false;
        var canWalkRight = false;
        if (canInspectSurface)
        {
            hasWindowPlatform = TryResolveMotionWindowPlatform(state, sitting);
            if (hasWindowPlatform)
            {
                GetMotionWindowWalkAvailability(
                    state,
                    out canWalkLeft,
                    out canWalkRight);
            }
            else if (state.IsGround)
            {
                isOnDesktopGround = TryGetMotionDesktopGroundWalkAvailability(
                    state,
                    out canWalkLeft,
                    out canWalkRight);
            }
        }

        var snapshot = new MotionPolicySnapshot(
            characterAvailable: true,
            conversationBusy: _requestInFlight || _transcriptionInFlight || _microphoneRecording || _aiPagesAwaitingAdvance,
            isDragging: state.IsDrag,
            isStateMachineLocked: state.IsStateMachineLocked,
            isGrounded: state.IsGround || hasWindowPlatform,
            isPajamas: state.ClothingState == LilithClothingState.Pajamas,
            hasWindowPlatform: hasWindowPlatform,
            isOnDesktopGround: isOnDesktopGround,
            hasPendingOperation: _actionShowcasePendingOperation != ActionShowcasePendingOperation.None,
            isOverlayBehindWindow: _actionShowcaseOverlayBehindWindow,
            hasWalkContinuation: _actionShowcaseWindowWalkContinuationActive,
            isActionAnimationPlaying: state.IsWalkLeft || state.IsWalkRight || state.IsAnyActionAnimPlaying,
            isSitting: sitting,
            isSleeping: state.IsSleep,
            canWalkLeft: canWalkLeft,
            canWalkRight: canWalkRight);
        var decision = MotionIntentPolicy.Evaluate(request, snapshot);
        if (!decision.Allowed)
            return PublishMotionIntentResult(MotionIntentResult.Rejected(request, decision.Reason, decision.Detail));
        if (request.Kind == MotionIntentKind.ArriveAtWindow
            && AgentMotionTransitionContract.RequiresSnapOnEntry(request.Kind)
            && !state.HasActionAnimation(LilithActionType.Snap))
        {
            return PublishMotionIntentResult(MotionIntentResult.Rejected(
                request,
                MotionIntentReason.AnimationUnavailable,
                "Native Snap action 36 is required for a visible window-arrival transition."));
        }

        try
        {
            var previousFeedback = _motionIntentFeedbackEnabled;
            try
            {
                _motionIntentFeedbackEnabled = request.Source == MotionIntentSource.Showcase;
                _actionShowcasePendingShowFeedback = _motionIntentFeedbackEnabled;
                var started = request.Kind switch
                {
                    MotionIntentKind.ArriveAtWindow => BeginActionShowcaseCoherentWindowSnap(manager, character, state),
                    MotionIntentKind.WalkLeft => hasWindowPlatform
                        ? PlayActionShowcaseWindowWalk(
                            manager, character, state, walkLeft: true, 9, 12, coherentSequence: true)
                        : PlayMotionIntentGroundWalk(character, state, walkLeft: true),
                    MotionIntentKind.WalkRight => hasWindowPlatform
                        ? PlayActionShowcaseWindowWalk(
                            manager, character, state, walkLeft: false, 9, 12, coherentSequence: true)
                        : PlayMotionIntentGroundWalk(character, state, walkLeft: false),
                    MotionIntentKind.PlayOneShot =>
                        useD022FixedBodyBinding
                            ? PlayD022LilithFixedOneShot(
                                character,
                                state,
                                hasWindowPlatform)
                            : PlayActionShowcaseCoherentOneShot(
                                manager,
                                character,
                                state,
                                hasWindowPlatform),
                    MotionIntentKind.Sit => StartMotionIntentSit(manager, character, state, hasWindowPlatform),
                    MotionIntentKind.Stand => StartMotionIntentStand(character, state),
                    MotionIntentKind.PeekFromWindow => PlayActionShowcaseWindowPeek(
                        manager, character, state, 9, 12, coherentSequence: true),
                    MotionIntentKind.DropFromWindow => PlayActionShowcaseWindowDrop(
                        manager, character, state, 10, 12, coherentSequence: true),
                    _ => false
                };
                if (!started)
                {
                    var reason = request.Kind == MotionIntentKind.ArriveAtWindow
                        || (request.Kind == MotionIntentKind.Sit && isOnDesktopGround)
                        ? MotionIntentReason.NoEligibleWindow
                        : MotionIntentReason.AnimationUnavailable;
                    return PublishMotionIntentResult(MotionIntentResult.Rejected(
                        request,
                        reason,
                        "The selected motion could not start in the current scene."));
                }

                return PublishMotionIntentResult(MotionIntentResult.Started(request));
            }
            finally
            {
                _motionIntentFeedbackEnabled = previousFeedback;
                if (_actionShowcasePendingOperation == ActionShowcasePendingOperation.None)
                    _actionShowcasePendingShowFeedback = true;
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Motion intent execution failed: id={request.Id}, kind={request.Kind}, source={request.Source}, error={exception.Message}");
            return PublishMotionIntentResult(MotionIntentResult.Failed(request, exception.Message));
        }
    }

    private static bool StartMotionIntentSit(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        bool hasWindowPlatform)
    {
        if (!hasWindowPlatform)
        {
            var transferStarted = BeginActionShowcaseWindowSitSnap(
                manager,
                character,
                state,
                itemCount: 12,
                showFeedback: _motionIntentFeedbackEnabled);
            _motionIntentSitActive = transferStarted;
            return transferStarted;
        }

        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        if (_motionIntentFeedbackEnabled)
            ShowActionShowcaseMessage(manager, "連貫展示：在目前視窗頂坐下休息一下。", 5f);
        var started = EnterActionShowcaseSitAtCurrentPosition(state);
        _motionIntentSitActive = started;
        return started;
    }

    private static bool StartMotionIntentStand(
        global::CharacterController character,
        LilithStateManager state)
    {
        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        return true;
    }

    private static MotionIntentResult PublishMotionIntentResult(MotionIntentResult result)
    {
        MotionIntentEvents.Publish(result);
        Plugin.PluginLog.LogInfo(
            $"Motion intent result: id={result.RequestId}, kind={result.Kind}, status={result.Status}, reason={result.Reason}.");
        return result;
    }

    private static bool BeginActionShowcaseCoherentWindowSnap(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (AgentMotionTransitionContract.RequiresSnapOnEntry(MotionIntentKind.ArriveAtWindow)
            && !state.HasActionAnimation(LilithActionType.Snap))
        {
            Plugin.PluginLog.LogWarning(
                "Window arrival rejected because native Snap action 36 is unavailable.");
            return false;
        }

        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        if (windowColliders == null
            || !TrySelectActionShowcaseWindowPlatform(
                windowColliders,
                state,
                forSeatedPose: false,
                out var windowHandle,
                out var windowTitle,
                out var topCenter,
                out var windowBounds,
                out _,
                out _))
        {
            if (_motionIntentFeedbackEnabled)
                ShowActionShowcaseMessage(manager, "連貫展示：目前沒有合格的可見視窗，稍後再找。", 4f);
            return false;
        }

        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.MoveToWindow;
        _actionShowcaseWindowHandle = windowHandle;
        _actionShowcaseWindowTitle = windowTitle;
        _actionShowcasePendingWindowTop = topCenter;
        _actionShowcasePendingWindowBounds = windowBounds;
        _actionShowcasePendingDescription = $"連貫展示：響指前往「{windowTitle}」";
        if (_motionIntentFeedbackEnabled)
            ShowActionShowcaseMessage(manager, _actionShowcasePendingDescription, 5f);
        if (!BeginActionShowcaseSnap(character, state))
        {
            _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
            _actionShowcasePendingAt = -1f;
            _actionShowcasePendingDescription = string.Empty;
            _actionShowcasePendingShowFeedback = true;
            Plugin.PluginLog.LogWarning(
                "Window arrival cancelled because native Snap action 36 could not start.");
            return false;
        }
        Plugin.PluginLog.LogInfo(
            $"Exploration coherent random showcase scheduled a window arrival: handle=0x{windowHandle.ToInt64():X}, title={windowTitle}.");
        return true;
    }

    private static bool EnterActionShowcaseSitAtCurrentPosition(
        LilithStateManager state)
    {
        RefreshActionShowcaseAllWindowPlatforms(state);
        var hasWindowSeat = TryAdoptActionShowcasePlatformUnderCharacter(state);
        if (!hasWindowSeat && _actionShowcaseHasWindowPlatform)
            hasWindowSeat = TryAdoptActionShowcasePlatformByHandle(state, _actionShowcaseWindowHandle);
        if (!hasWindowSeat)
        {
            _motionIntentSitActive = false;
            _actionShowcaseSitAnchorCorrectionActive = false;
            _actionShowcaseSitAnchorCorrectionHasY = false;
            _actionShowcaseSitAnchorCorrectionUntil = -1f;
            Plugin.PluginLog.LogInfo(
                "Motion authority rejected sit before native state entry because no supported window-top seat was present.");
            return false;
        }
        var anchorX = state.transform.position.x;
        if (hasWindowSeat
            && TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            var edgePadding = GetActionShowcaseSafePlatformInset(characterBounds);
            var safeMinimumCenterX = _actionShowcaseWindowPlatformBounds.min.x
                + characterBounds.extents.x
                + edgePadding;
            var safeMaximumCenterX = _actionShowcaseWindowPlatformBounds.max.x
                - characterBounds.extents.x
                - edgePadding;
            if (safeMaximumCenterX >= safeMinimumCenterX)
            {
                var safeCenterX = Math.Clamp(
                    characterBounds.center.x,
                    safeMinimumCenterX,
                    safeMaximumCenterX);
                anchorX += safeCenterX - characterBounds.center.x;
            }
        }
        state.RememberPreSitStandX(anchorX);
        state.RequestSitAnchorX(anchorX);
        if (hasWindowSeat && _actionShowcaseWindowHandle != IntPtr.Zero)
            state.RequestSitSeatHandle(_actionShowcaseWindowHandle);
        _actionShowcaseSitAnchorCorrectionActive = true;
        _actionShowcaseSitAnchorCorrectionX = anchorX;
        _actionShowcaseSitAnchorCorrectionHasY = hasWindowSeat;
        if (hasWindowSeat)
        {
            var sitTarget = new Vector3(
                anchorX,
                _actionShowcaseWindowPlatformBounds.max.y - state.GetSitVerticalOffset(),
                state.transform.position.z);
            sitTarget = state.ClampSitTargetToGround(sitTarget);
            _actionShowcaseSitAnchorCorrectionY = sitTarget.y;
        }
        _actionShowcaseSitAnchorCorrectionUntil = Time.unscaledTime + 0.45f;
        _actionShowcaseSitAnchorCorrectionLogged = false;
        state.EnterDialogueState(DialogueStateType.Sit);
        ApplyActionShowcaseSitAnchorCorrection(state, "after EnterDialogueState");
        var started = state.IsSit;
        if (started && hasWindowSeat)
            AttachActionShowcasePoseToWindow(_actionShowcaseWindowHandle);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase requested in-place sit: started={started}, anchorX={anchorX:F3}, hasWindowSeat={hasWindowSeat}, handle=0x{_actionShowcaseWindowHandle.ToInt64():X}.");
        return started;
    }

    private static void MaintainActionShowcaseSitAnchorCorrection()
    {
        if (!_actionShowcaseSitAnchorCorrectionActive)
            return;
        if (Time.unscaledTime > _actionShowcaseSitAnchorCorrectionUntil)
        {
            _actionShowcaseSitAnchorCorrectionActive = false;
            _actionShowcaseSitAnchorCorrectionHasY = false;
            _actionShowcaseSitAnchorCorrectionUntil = -1f;
            return;
        }

        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (state != null)
            ApplyActionShowcaseSitAnchorCorrection(state, "short settle guard");
    }

    private static void ApplyActionShowcaseSitAnchorCorrection(
        LilithStateManager state,
        string source)
    {
        if (!_actionShowcaseSitAnchorCorrectionActive)
            return;
        var position = state.transform.position;
        var originalPosition = position;
        var displacementX = _actionShowcaseSitAnchorCorrectionX - position.x;
        var displacementY = _actionShowcaseSitAnchorCorrectionHasY
            ? _actionShowcaseSitAnchorCorrectionY - position.y
            : 0f;
        if (Math.Abs(displacementX) <= 0.001f && Math.Abs(displacementY) <= 0.001f)
            return;

        position.x = _actionShowcaseSitAnchorCorrectionX;
        if (_actionShowcaseSitAnchorCorrectionHasY)
            position.y = _actionShowcaseSitAnchorCorrectionY;
        if (state.IsSit && _actionShowcaseSitAnchorCorrectionHasY)
            state.MoveWhileSitFrozen(position);
        else
            state.transform.position = position;
        Physics2D.SyncTransforms();
        if (!_actionShowcaseSitAnchorCorrectionLogged)
        {
            _actionShowcaseSitAnchorCorrectionLogged = true;
            Plugin.PluginLog.LogInfo(
                $"Corrected native sit position from {originalPosition} to {position}; verticalOffset={state.GetSitVerticalOffset():F3}, hasWindowY={_actionShowcaseSitAnchorCorrectionHasY} ({source}).");
        }
    }

    internal static void ReapplyActionShowcaseSitAnchorAfterNativeEnter()
    {
        if (!_actionShowcaseSitAnchorCorrectionActive)
            return;
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (state != null)
            ApplyActionShowcaseSitAnchorCorrection(state, "LilithSitState.OnEnter postfix");
    }

    private static ActionShowcaseCoherentAction ChooseActionShowcaseCoherentAction()
    {
        var allowDeparture = _actionShowcaseCoherentRandomStep >= 4;
        var roll = UnityEngine.Random.Range(0, 100);
        return _actionShowcaseCoherentRandomLastAction switch
        {
            ActionShowcaseCoherentAction.ArriveWindow => roll < 48
                ? ChooseActionShowcaseCoherentWalkDirection()
                : roll < 78 ? ActionShowcaseCoherentAction.OneShot : ActionShowcaseCoherentAction.Sit,
            ActionShowcaseCoherentAction.WalkLeft => roll < 38
                ? ActionShowcaseCoherentAction.OneShot
                : roll < 63 ? ActionShowcaseCoherentAction.Sit
                : roll < 88 ? ActionShowcaseCoherentAction.WalkRight
                : allowDeparture ? ActionShowcaseCoherentAction.Drop : ActionShowcaseCoherentAction.OneShot,
            ActionShowcaseCoherentAction.WalkRight => roll < 38
                ? ActionShowcaseCoherentAction.OneShot
                : roll < 63 ? ActionShowcaseCoherentAction.Sit
                : roll < 88 ? ActionShowcaseCoherentAction.WalkLeft
                : allowDeparture ? ActionShowcaseCoherentAction.Drop : ActionShowcaseCoherentAction.OneShot,
            ActionShowcaseCoherentAction.OneShot => roll < 45
                ? ChooseActionShowcaseCoherentWalkDirection()
                : roll < 70 ? ActionShowcaseCoherentAction.Sit
                : roll < 88 && allowDeparture ? ActionShowcaseCoherentAction.Peek
                : allowDeparture ? ActionShowcaseCoherentAction.Drop : ChooseActionShowcaseCoherentWalkDirection(),
            ActionShowcaseCoherentAction.Stand => roll < 58
                ? ChooseActionShowcaseCoherentWalkDirection()
                : roll < 88 ? ActionShowcaseCoherentAction.OneShot
                : allowDeparture ? ActionShowcaseCoherentAction.Drop : ActionShowcaseCoherentAction.OneShot,
            ActionShowcaseCoherentAction.Peek => roll < 55
                ? ChooseActionShowcaseCoherentWalkDirection()
                : roll < 85 ? ActionShowcaseCoherentAction.OneShot : ActionShowcaseCoherentAction.Sit,
            _ => roll < 50
                ? ChooseActionShowcaseCoherentWalkDirection()
                : roll < 78 ? ActionShowcaseCoherentAction.OneShot : ActionShowcaseCoherentAction.Sit
        };
    }

    private static ActionShowcaseCoherentAction ChooseActionShowcaseCoherentWalkDirection()
    {
        if (_actionShowcaseCoherentRandomLastAction == ActionShowcaseCoherentAction.WalkLeft)
            return ActionShowcaseCoherentAction.WalkRight;
        if (_actionShowcaseCoherentRandomLastAction == ActionShowcaseCoherentAction.WalkRight)
            return ActionShowcaseCoherentAction.WalkLeft;
        return UnityEngine.Random.Range(0, 2) == 0
            ? ActionShowcaseCoherentAction.WalkLeft
            : ActionShowcaseCoherentAction.WalkRight;
    }

    private static bool PlayD022LilithFixedOneShot(
        global::CharacterController character,
        LilithStateManager state,
        bool hasWindowPlatform)
    {
        const LilithActionType nativeAction = LilithActionType.Greet;
        if (!state.HasActionAnimation(nativeAction)
            || state.ClothingState == LilithClothingState.Pajamas
            || state.IsDrag
            || state.IsStateMachineLocked
            || !state.IsIdle
            || (!state.IsGround && !hasWindowPlatform))
        {
            return false;
        }

        ResetActionShowcaseCharacter(
            character,
            state,
            preserveWalkOrigin: true);
        character.PlayLilithAction(nativeAction, true, null);
        Plugin.PluginLog.LogInfo(
            "D-022 Lilith body binding started fixed Greet; "
            + "allowlistSize=1, randomSelection=false.");
        return true;
    }

    private static bool PlayActionShowcaseCoherentOneShot(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        bool hasWindowPlatform = true)
    {
        LilithActionType selected = LilithActionType.None;
        for (var attempt = 0; attempt < ActionShowcaseCoherentOneShots.Length * 2; attempt++)
        {
            var candidate = ActionShowcaseCoherentOneShots[
                UnityEngine.Random.Range(0, ActionShowcaseCoherentOneShots.Length)];
            if (candidate == _actionShowcaseCoherentRandomLastOneShot
                || !state.HasActionAnimation(candidate))
            {
                continue;
            }
            selected = candidate;
            break;
        }
        if (selected == LilithActionType.None)
        {
            _actionShowcaseCoherentRandomNextAt = Time.unscaledTime + 0.8f;
            return false;
        }

        var restoreStandingWindowPosition = IsMotionVisualSitState(state)
            && hasWindowPlatform
            && _actionShowcaseWindowHandle != IntPtr.Zero
            && _actionShowcaseWindowPlatformBounds.size.x > 0.01f;
        var standingWindowTop = _actionShowcaseWindowPlatformTop;
        var standingWindowBounds = _actionShowcaseWindowPlatformBounds;
        ResetActionShowcaseCharacter(character, state, preserveWalkOrigin: true);
        if (restoreStandingWindowPosition)
        {
            MoveActionShowcaseToWindow(state, standingWindowTop, standingWindowBounds);
            Plugin.PluginLog.LogInfo(
                $"Motion one-shot restored a stable standing window position before playing {selected}: top={standingWindowTop}, bounds={standingWindowBounds}.");
        }
        if (_motionIntentFeedbackEnabled)
            ShowActionShowcaseMessage(manager, $"連貫展示：{selected}", 4f);
        character.PlayLilithAction(selected, true, null);
        var duration = 1.5f;
        if (state.TryGetActionDuration(selected, out var detectedDuration) && detectedDuration > 0f)
            duration = detectedDuration;
        _actionShowcaseCoherentRandomLastOneShot = selected;
        _actionShowcaseCoherentRandomLastAction = ActionShowcaseCoherentAction.OneShot;
        _actionShowcaseCoherentRandomStep++;
        _actionShowcaseCoherentRandomNextAt = Time.unscaledTime
            + duration
            + UnityEngine.Random.Range(0.35f, 0.85f);
        Plugin.PluginLog.LogInfo(
            $"Exploration coherent random showcase played {selected}; duration={duration:F2}, step={_actionShowcaseCoherentRandomStep}.");
        return true;
    }

    private static void CommitActionShowcaseCoherentAction(
        ActionShowcaseCoherentAction action,
        float minimumDelay,
        float maximumDelay)
    {
        _actionShowcaseCoherentRandomLastAction = action;
        _actionShowcaseCoherentRandomStep++;
        _actionShowcaseCoherentRandomNextAt = Time.unscaledTime
            + UnityEngine.Random.Range(minimumDelay, maximumDelay);
        Plugin.PluginLog.LogInfo(
            $"Exploration coherent random showcase committed {action}; step={_actionShowcaseCoherentRandomStep}.");
    }

    private static bool RefreshActionShowcaseWindowPlatform()
    {
        if (!_actionShowcaseHasWindowPlatform || _actionShowcaseWindowHandle == IntPtr.Zero)
            return false;
        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (state == null)
            return false;
        Bounds windowBounds;
        if (ActionShowcaseWindowPlatforms.TryGetValue(_actionShowcaseWindowHandle, out var existingPlatform))
        {
            windowBounds = existingPlatform.WindowBounds;
        }
        else
        {
            var described = EnumerateActionShowcasePlatformWindows()
                .FirstOrDefault(window => window.Handle == _actionShowcaseWindowHandle);
            if (described.Handle == IntPtr.Zero
                || !TryConvertDesktopRectToWorld(described.Bounds, state.transform, out windowBounds))
                return false;
        }

        var oldWidth = _actionShowcaseWindowPlatformBounds.size.x;
        var normalizedX = oldWidth > 0.01f
            ? Mathf.InverseLerp(
                _actionShowcaseWindowPlatformBounds.min.x,
                _actionShowcaseWindowPlatformBounds.max.x,
                _actionShowcaseWindowPlatformTop.x)
            : 0.5f;
        _actionShowcaseWindowPlatformTop = new Vector3(
            Mathf.Lerp(windowBounds.min.x, windowBounds.max.x, normalizedX),
            windowBounds.max.y,
            state.transform.position.z);
        _actionShowcaseWindowPlatformBounds = windowBounds;
        UpdateActionShowcaseDedicatedPlatform(_actionShowcaseWindowHandle, windowBounds, selected: true, state);
        Physics2D.SyncTransforms();
        return true;
    }

    private static bool TryGetActionShowcaseDesktopWindowBounds(IntPtr handle, out RectInt bounds)
    {
        bounds = default;
        if (handle == IntPtr.Zero || !WindowsNativeAPI.IsWindow(handle))
            return false;
        var platform = PlatformService.Current;
        if (platform.TryGetWindowMetrics(handle, out var metrics))
        {
            bounds = metrics.WindowBounds.width > 0 && metrics.WindowBounds.height > 0
                ? metrics.WindowBounds
                : metrics.ClientBounds;
            if (bounds.width > 0 && bounds.height > 0)
                return true;
        }

        var windows = platform.GetDesktopObstacleWindows(platform.GetAppWindowHandle());
        if (windows == null)
            return false;
        for (var i = 0; i < windows.Count; i++)
        {
            if (windows[i].Handle != handle)
                continue;
            bounds = windows[i].Bounds;
            return bounds.width > 0 && bounds.height > 0;
        }
        return false;
    }

    private static bool PlayActionShowcaseWindowDrop(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int itemNumber,
        int itemCount,
        bool coherentSequence = false)
    {
        if (!_actionShowcaseHasWindowPlatform || !RefreshActionShowcaseWindowPlatform())
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：請先執行第 6 項，且保持目標視窗開啟", 5f);
            return false;
        }

        ResetActionShowcaseCharacter(character, state);
        RefreshActionShowcaseAllWindowPlatforms(state);
        TryAdoptActionShowcasePlatformUnderCharacter(state);
        if (!TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：無法取得角色碰撞外框", 5f);
            return false;
        }

        var windowColliders = UnityEngine.Object.FindObjectOfType<ActiveWindowCollider>();
        var canDropRight = windowColliders == null
            || _actionShowcaseWindowPlatformBounds.max.x + characterBounds.size.x + 0.1f < windowColliders.GetVisibleRightWorldX();
        var canDropLeft = windowColliders == null
            || _actionShowcaseWindowPlatformBounds.min.x - characterBounds.size.x - 0.1f > windowColliders.GetVisibleLeftWorldX();
        var distanceToLeftEdge = Math.Abs(characterBounds.center.x - _actionShowcaseWindowPlatformBounds.min.x);
        var distanceToRightEdge = Math.Abs(_actionShowcaseWindowPlatformBounds.max.x - characterBounds.center.x);
        var dropRight = distanceToRightEdge <= distanceToLeftEdge;
        if (dropRight && !canDropRight && canDropLeft)
            dropRight = false;
        else if (!dropRight && !canDropLeft && canDropRight)
            dropRight = true;
        else if (!canDropLeft && !canDropRight)
        {
            ShowActionShowcaseMessage(
                manager,
                coherentSequence
                    ? "連貫展示：目前視窗兩側沒有足夠的安全落下空間，改做下一個動作。"
                    : $"探索 {itemNumber}/{itemCount}：目前視窗兩側沒有足夠的安全落下空間",
                5f);
            Plugin.PluginLog.LogInfo("Exploration showcase skipped a window-edge drop because neither side has safe screen space.");
            return false;
        }
        var desiredCenterX = dropRight
            ? _actionShowcaseWindowPlatformBounds.max.x + characterBounds.extents.x + 0.08f
            : _actionShowcaseWindowPlatformBounds.min.x - characterBounds.extents.x - 0.08f;
        var position = state.transform.position;
        position.x = desiredCenterX + (state.transform.position.x - characterBounds.center.x);
        state.transform.position = position;
        Physics2D.SyncTransforms();
        StopActionShowcasePhysics(state, markGrounded: false, downwardVelocity: -0.6f);
        RefreshActionShowcasePlatformCollisionRules(state);
        ShowActionShowcaseMessage(
            manager,
            coherentSequence
                ? "連貫展示：走到窗緣後跳下，落地再繼續探索。"
                : $"探索 {itemNumber}/{itemCount}：移出窗緣，交給原生 Falling／落地流程",
            7f);
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase initiated a nearest-edge drop; right={dropRight}, distanceLeft={distanceToLeftEdge:F3}, distanceRight={distanceToRightEdge:F3}, position={position}.");
        return true;
    }

    private static bool PlayActionShowcaseWindowPeek(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state,
        int itemNumber,
        int itemCount,
        bool coherentSequence = false)
    {
        if (!_actionShowcaseHasWindowPlatform || !RefreshActionShowcaseWindowPlatform())
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：請先執行第 6 項，且保持目標視窗開啟", 5f);
            return false;
        }
        if (!OperatingSystem.IsWindows()
            || _actionShowcaseWindowHandle == IntPtr.Zero)
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：目前無法建立視窗後方探頭測試", 5f);
            return false;
        }
        if (!state.HasActionAnimation(LilithActionType.Snap))
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：缺少原生第 36 號彈指，已取消探頭", 5f);
            Plugin.PluginLog.LogWarning(
                "Exploration window peek was cancelled because native Snap action 36 is unavailable.");
            return false;
        }
        if (!state.HasActionAnimation(LilithActionType.ScreenPeek))
        {
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：缺少原生探頭動畫，已取消轉場", 5f);
            Plugin.PluginLog.LogWarning(
                "Exploration window peek was cancelled because ScreenPeek is unavailable.");
            return false;
        }

        ResetActionShowcaseCharacter(character, state);
        _actionShowcaseWindowPeekOriginPosition = state.transform.position;
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.PrepareWindowPeekAfterSnap;
        _actionShowcasePendingDescription = coherentSequence
            ? "連貫展示：彈指後藏到視窗後方探頭，結束再回到窗頂"
            : $"探索 {itemNumber}/{itemCount}：先彈指，再從目標視窗左側後方探頭";
        ShowActionShowcaseMessage(manager, _actionShowcasePendingDescription, 7f);
        if (!BeginActionShowcaseSnap(character, state))
        {
            _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
            _actionShowcasePendingAt = -1f;
            _actionShowcaseSnapEndsAt = -1f;
            _actionShowcasePendingDescription = string.Empty;
            ShowActionShowcaseMessage(manager, $"探索 {itemNumber}/{itemCount}：彈指未能開始，已取消探頭", 5f);
            Plugin.PluginLog.LogWarning(
                "Exploration window peek was cancelled because Snap action 36 did not start.");
            return false;
        }

        Plugin.PluginLog.LogInfo(
            $"Exploration window peek scheduled behind verified Snap action 36; handle=0x{_actionShowcaseWindowHandle.ToInt64():X}.");
        return true;
    }

    private static bool PrepareActionShowcaseWindowPeek(
        DialogueManager manager,
        global::CharacterController character,
        LilithStateManager state)
    {
        if (!_actionShowcaseHasWindowPlatform
            || !RefreshActionShowcaseWindowPlatform()
            || !OperatingSystem.IsWindows()
            || _actionShowcaseWindowHandle == IntPtr.Zero
            || !TryGetActionShowcaseCharacterBounds(state, out var characterBounds))
        {
            ShowActionShowcaseMessage(manager, "彈指期間目標視窗已失效，探頭已取消。", 5f);
            return false;
        }

        var desiredCenterX = _actionShowcaseWindowPlatformBounds.max.x - characterBounds.extents.x * 0.18f;
        var desiredCenterY = _actionShowcaseWindowPlatformBounds.center.y;
        var position = state.transform.position;
        position.x += desiredCenterX - characterBounds.center.x;
        position.y += desiredCenterY - characterBounds.center.y;
        state.transform.position = position;
        Physics2D.SyncTransforms();
        StopActionShowcasePhysics(state, markGrounded: true);

        var body = state.GetComponent<Rigidbody2D>();
        _actionShowcaseWindowPeekBodyWasSimulated = body == null || body.simulated;
        _actionShowcaseWindowPeekMovementWasDisabled = GetActionShowcaseMovementDisabled(character);
        SetActionShowcaseMovementDisabled(character, true);
        if (body != null)
            body.simulated = false;
        SetActionShowcasePlatformsEnabled(false);

        var appWindow = PlatformService.Current.GetAppWindowHandle();
        const int noMoveNoSizeNoActivate = 0x0001 | 0x0002 | 0x0010;
        var zOrderChanged = appWindow != IntPtr.Zero
            && WindowsNativeAPI.SetWindowPos(
                appWindow,
                _actionShowcaseWindowHandle,
                0,
                0,
                0,
                0,
                noMoveNoSizeNoActivate) != 0;
        if (!zOrderChanged)
        {
            if (body != null)
                body.simulated = _actionShowcaseWindowPeekBodyWasSimulated;
            SetActionShowcaseMovementDisabled(character, _actionShowcaseWindowPeekMovementWasDisabled);
            SetActionShowcasePlatformsEnabled(true);
            state.transform.position = _actionShowcaseWindowPeekOriginPosition;
            Physics2D.SyncTransforms();
            StopActionShowcasePhysics(state, markGrounded: true);
            ShowActionShowcaseMessage(manager, "無法安全調整 overlay 層級，探頭已取消。", 6f);
            Plugin.PluginLog.LogWarning("Exploration showcase could not place the overlay behind the selected application window.");
            return false;
        }

        _actionShowcaseOverlayBehindWindow = true;
        return true;
    }

    private static bool StartActionShowcaseWindowPeekAfterSnap(
        global::CharacterController character,
        LilithStateManager state,
        string description)
    {
        if (!_actionShowcaseOverlayBehindWindow
            || !AgentMotionTransitionContract.IsSatisfied(
                MotionIntentKind.PeekFromWindow,
                nativeSnapAction36Completed: Time.unscaledTime >= _actionShowcaseSnapEndsAt - 0.08f)
            || !state.HasActionAnimation(LilithActionType.ScreenPeek))
        {
            return false;
        }

        var duration = 2.5f;
        if (state.TryGetActionDuration(LilithActionType.ScreenPeek, out var detectedDuration) && detectedDuration > 0f)
            duration = detectedDuration;
        character.PlayLilithAction(LilithActionType.ScreenPeek, true, null);
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.BeginWindowPeekReturnSnap;
        _actionShowcasePendingAt = Time.unscaledTime + Math.Clamp(duration + 0.25f, 1f, 6f);
        _actionShowcasePendingDescription = description;
        Plugin.PluginLog.LogInfo(
            $"Exploration showcase started ScreenPeek after completed Snap action 36; handle=0x{_actionShowcaseWindowHandle.ToInt64():X}, duration={duration:F2}.");
        return true;
    }

    private static void RestoreActionShowcaseWindowPeek(
        global::CharacterController character,
        LilithStateManager state,
        bool preserveActiveAction = false)
    {
        if (_actionShowcaseOverlayBehindWindow && OperatingSystem.IsWindows())
        {
            var appWindow = PlatformService.Current.GetAppWindowHandle();
            const int noMoveNoSizeNoActivate = 0x0001 | 0x0002 | 0x0010;
            if (appWindow != IntPtr.Zero)
                WindowsNativeAPI.SetWindowPos(appWindow, new IntPtr(-1), 0, 0, 0, 0, noMoveNoSizeNoActivate);
        }
        _actionShowcaseOverlayBehindWindow = false;
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
            body.simulated = _actionShowcaseWindowPeekBodyWasSimulated;
        SetActionShowcaseMovementDisabled(character, _actionShowcaseWindowPeekMovementWasDisabled);
        SetActionShowcasePlatformsEnabled(true);
        state.transform.position = _actionShowcaseWindowPeekOriginPosition;
        Physics2D.SyncTransforms();
        StopActionShowcasePhysics(state, markGrounded: true);
        if (!preserveActiveAction)
            state.ReturnIdle();
    }

    private static bool GetActionShowcaseMovementDisabled(global::CharacterController character)
    {
        try
        {
            return character.IsMovementDisabled;
        }
        catch (Exception ex)
        {
            Plugin.PluginLog.LogDebug($"Could not read CharacterController.IsMovementDisabled: {ex.Message}");
            return false;
        }
    }

    private static void SetActionShowcaseMovementDisabled(global::CharacterController character, bool disabled)
    {
        try
        {
            AccessTools.Property(typeof(global::CharacterController), "IsMovementDisabled")?.SetValue(character, disabled);
        }
        catch (Exception ex)
        {
            Plugin.PluginLog.LogDebug($"Could not set CharacterController.IsMovementDisabled: {ex.Message}");
        }
    }

    private static void StopActionShowcasePhysics(LilithStateManager state, bool markGrounded, float downwardVelocity = 0f)
    {
        var body = state.GetComponent<Rigidbody2D>();
        if (body != null)
        {
            body.position = state.transform.position;
            body.velocity = new Vector2(0f, downwardVelocity);
            body.angularVelocity = 0f;
        }
        state.IsGround = markGrounded;
    }

    private static bool TryGetActionShowcaseCharacterBounds(LilithStateManager state, out Bounds bounds)
    {
        bounds = default;
        var found = false;
        foreach (var collider in state.GetComponentsInChildren<Collider2D>(true))
        {
            if (collider == null || !collider.enabled || collider.isTrigger || !collider.gameObject.activeInHierarchy)
                continue;
            if (!found)
            {
                bounds = collider.bounds;
                found = true;
            }
            else
            {
                bounds.Encapsulate(collider.bounds);
            }
        }
        return found;
    }

    private static bool TryGetActionShowcaseVisualBounds(LilithStateManager state, out Bounds bounds)
    {
        bounds = default;
        var found = false;
        foreach (var renderer in state.GetComponentsInChildren<Renderer>(true))
        {
            if (renderer == null || !renderer.enabled || !renderer.gameObject.activeInHierarchy)
                continue;
            var rendererBounds = renderer.bounds;
            if (rendererBounds.size.x <= 0.001f || rendererBounds.size.y <= 0.001f)
                continue;
            if (!found)
            {
                bounds = rendererBounds;
                found = true;
            }
            else
            {
                bounds.Encapsulate(rendererBounds);
            }
        }
        return found;
    }

    private static void RestoreActionShowcaseExploration(
        global::CharacterController character,
        LilithStateManager state,
        bool restorePosition)
    {
        StopActionShowcaseCoherentRandom();
        _actionShowcasePendingOperation = ActionShowcasePendingOperation.None;
        _actionShowcasePendingAt = -1f;
        _actionShowcaseSnapEndsAt = -1f;
        _actionShowcasePendingDescription = string.Empty;
        _actionShowcasePendingShowFeedback = true;
        if (_actionShowcaseOverlayBehindWindow)
            RestoreActionShowcaseWindowPeek(character, state);
        ResetActionShowcaseCharacter(character, state);
        if (_actionShowcaseHasExplorationOrigin)
        {
            state.transform.localScale = _actionShowcaseExplorationOriginScale;
            if (restorePosition)
                state.transform.position = _actionShowcaseExplorationOriginPosition;
            Physics2D.SyncTransforms();
            StopActionShowcasePhysics(state, markGrounded: true);
        }
        _actionShowcaseHasExplorationOrigin = false;
        _actionShowcaseHasWindowPlatform = false;
        _actionShowcaseWindowHandle = IntPtr.Zero;
        _actionShowcaseWindowTitle = string.Empty;
        _actionShowcaseWindowCandidateCursor = 0;
        ResetActionShowcaseLaunchLandingGate();
        if (IsGlobalMotionPhysicsActive)
        {
            _actionShowcasePlatformRefreshAt = -1f;
            MaintainActionShowcaseDedicatedPlatform(state);
        }
        else
        {
            DestroyActionShowcaseDedicatedPlatform();
        }
        ActionShowcaseIndices[4] = -1;
    }

    private static void ResetActionShowcaseCharacter(
        global::CharacterController character,
        LilithStateManager state,
        bool preserveWalkOrigin = false)
    {
        RestoreActionShowcasePendingSitPhysics(state);
        ClearActionShowcaseWindowWalkContinuation();
        _motionIntentSitActive = false;
        _actionShowcaseSitAnchorCorrectionActive = false;
        _actionShowcaseSitAnchorCorrectionHasY = false;
        _actionShowcaseSitAnchorCorrectionUntil = -1f;
        ClearActionShowcaseWindowAttachment();
        character.InterruptActionForReminder();
        character.ClearEmotion();
        state.ClearWalkTarget();
        if (state.IsSleep)
            state.ExitSleepState();
        if (state.IsLieDown)
            state.ExitLieDownState();
        state.ReturnIdle();
        if (!preserveWalkOrigin)
            _actionShowcaseHasWalkOrigin = false;
    }

    private static int WrapActionShowcaseIndex(int index, int count)
    {
        if (count <= 0)
            return 0;
        index %= count;
        return index < 0 ? index + count : index;
    }

    private static string GetActionShowcaseGroupName(int group) => group switch
    {
        0 => "單次動作",
        1 => "Live2D 表情",
        2 => "走動",
        3 => "姿勢",
        _ => "自由探索實測"
    };

    private static void ShowActionShowcaseMessage(DialogueManager manager, string text, float duration = 5f)
    {
        if (!_motionIntentFeedbackEnabled)
            return;
        ForceSaySynthetic(
            manager,
            $"【動作展示】{text}",
            string.Empty,
            duration);
    }

    private static readonly TimeSpan GameHermesVoiceStartTimeout =
        TimeSpan.FromSeconds(60);
    // Runtime may spend up to 140 seconds on dispatch, transcription,
    // terminal, cleanup, and whole-generation recovery before the microphone
    // is proven retired.
    private static readonly TimeSpan GameHermesVoiceTranscriptionTimeout =
        TimeSpan.FromMinutes(3);
    private static readonly TimeSpan GameHermesVoiceCancelTimeout =
        TimeSpan.FromSeconds(60);

    private static void HandleGameHermesVoiceInput(
        DialogueManager manager,
        KeyCode voiceInputKey,
        D046HotkeyTransition voiceInputTransition)
    {
        if (!Plugin.VoiceInputEnabled.Value
            || !voiceInputTransition.Pressed)
        {
            return;
        }
        CancelPublishedPlayerReplySpeech(
            D043SpeechCancellationReason.PublicationRetired);
        if (_activeGameHermesVoiceCapture != null
            || _microphoneRecording
            || _transcriptionInFlight
            || _requestInFlight
            || _aiPagesAwaitingAdvance
            || _pendingVoiceSubmitText != null
            || !PendingTranscripts.IsEmpty
            || (_inputBubble != null
                && _inputField != null
                && _inputBubble.activeSelf))
        {
            ForceSaySynthetic(
                manager,
                ApiKeyText(
                    "先等我一下……",
                    "先等我一下……",
                    "少し待って……",
                    "Wait for me a moment…"),
                string.Empty,
                4f);
            return;
        }

        var maximumDurationMilliseconds = checked(
            Math.Clamp(Plugin.VoiceInputMaxSeconds.Value, 5, 90)
            * 1000);
        var capture = new ActiveGameHermesVoiceCapture(
            Guid.NewGuid(),
            EffectiveGameHermesVoiceLanguage(),
            maximumDurationMilliseconds,
            Time.unscaledTime);
        _activeGameHermesVoiceCapture = capture;
        _microphoneRecording = true;
        _microphoneStartedAt = capture.RequestedAt;
        try
        {
            ForceSaySynthetic(
                manager,
                ApiKeyText(
                    "正在聽……",
                    "正在听……",
                    "聞いているよ……",
                    "Listening…"),
                string.Empty,
                maximumDurationMilliseconds / 1000f + 2f);
            Plugin.PluginLog.LogInfo(
                voiceInputKey
                + " started one bounded native Hermes voice capture: "
                + capture.CaptureId.ToString("N")[..8]
                + ".");
            _ = StartGameHermesVoiceCaptureAsync(capture);
        }
        catch (Exception exception)
        {
            ReleaseGameHermesVoiceCapture(capture);
            PendingTranscriptionErrors.Enqueue(
                GameHermesVoiceUnavailableText());
            Plugin.PluginLog.LogWarning(
                "Could not launch native Hermes voice capture: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void ReconcileGameHermesVoiceCapture(
        D046HotkeyTransition voiceInputTransition)
    {
        var capture = _activeGameHermesVoiceCapture;
        if (capture == null)
            return;
        if (!Plugin.VoiceInputEnabled.Value)
        {
            RequestGameHermesVoiceStop(
                capture,
                LilithGameBridgeVoiceStopDisposition.Cancel,
                reachedLimit: false);
            return;
        }

        var elapsedMilliseconds = Math.Max(
            0d,
            (Time.unscaledTime - capture.RequestedAt) * 1000d);
        var reachedLimit = elapsedMilliseconds
            >= capture.MaximumDurationMilliseconds - 100d;
        if (voiceInputTransition.Released || reachedLimit)
        {
            RequestGameHermesVoiceStop(
                capture,
                LilithGameBridgeVoiceStopDisposition.Transcribe,
                reachedLimit);
        }
    }

    private static void RequestGameHermesVoiceStop(
        ActiveGameHermesVoiceCapture capture,
        LilithGameBridgeVoiceStopDisposition disposition,
        bool reachedLimit)
    {
        if (!ReferenceEquals(_activeGameHermesVoiceCapture, capture))
            return;
        capture.StopRequested = true;
        capture.ReachedLimit |= reachedLimit;
        if (disposition == LilithGameBridgeVoiceStopDisposition.Cancel)
        {
            capture.StopDisposition = disposition;
        }
        if (capture.Phase == GameHermesVoiceCapturePhase.Starting)
            return;
        if (capture.Phase == GameHermesVoiceCapturePhase.Recording)
        {
            capture.Phase = GameHermesVoiceCapturePhase.Stopping;
            _microphoneRecording = false;
            _transcriptionInFlight = true;
            if (capture.StopDisposition
                == LilithGameBridgeVoiceStopDisposition.Cancel)
            {
                capture.CancelRequestInFlight = true;
            }
            LaunchGameHermesVoiceStop(capture, capture.StopDisposition);
            return;
        }
        if (capture.Phase == GameHermesVoiceCapturePhase.Stopping
            && disposition == LilithGameBridgeVoiceStopDisposition.Cancel
            && !capture.CancelRequestInFlight)
        {
            capture.CancelRequestInFlight = true;
            LaunchGameHermesVoiceStop(
                capture,
                LilithGameBridgeVoiceStopDisposition.Cancel);
        }
    }

    private static void LaunchGameHermesVoiceStop(
        ActiveGameHermesVoiceCapture capture,
        LilithGameBridgeVoiceStopDisposition disposition)
    {
        try
        {
            _ = StopGameHermesVoiceCaptureAsync(capture, disposition);
        }
        catch (Exception exception)
        {
            PendingGameHermesVoiceBridgeResults.Enqueue(
                new PendingGameHermesVoiceBridgeResult(
                    capture.CaptureId,
                    startResponse: null,
                    stopResponse: null,
                    disposition,
                    exception.GetType().Name));
        }
    }

    private static async Task StartGameHermesVoiceCaptureAsync(
        ActiveGameHermesVoiceCapture capture)
    {
        using var timeout = new CancellationTokenSource(
            GameHermesVoiceStartTimeout);
        try
        {
            var response = await GameHermesClient.StartVoiceAsync(
                    Guid.NewGuid(),
                    capture.CaptureId,
                    capture.Language,
                    capture.MaximumDurationMilliseconds,
                    timeout.Token)
                .ConfigureAwait(false);
            PendingGameHermesVoiceBridgeResults.Enqueue(
                new PendingGameHermesVoiceBridgeResult(
                    capture.CaptureId,
                    response,
                    stopResponse: null,
                    stopDisposition: null,
                    string.Empty));
        }
        catch (Exception exception)
        {
            if (!LilithGameHermesClient.ProvesRequestWasNotWritten(exception))
            {
                await TryCancelOrphanedGameHermesVoiceCaptureAsync(
                        capture.CaptureId)
                    .ConfigureAwait(false);
            }
            PendingGameHermesVoiceBridgeResults.Enqueue(
                new PendingGameHermesVoiceBridgeResult(
                    capture.CaptureId,
                    startResponse: null,
                    stopResponse: null,
                    stopDisposition: null,
                    exception.GetType().Name));
        }
    }

    private static async Task StopGameHermesVoiceCaptureAsync(
        ActiveGameHermesVoiceCapture capture,
        LilithGameBridgeVoiceStopDisposition disposition)
    {
        using var timeout = new CancellationTokenSource(
            disposition == LilithGameBridgeVoiceStopDisposition.Cancel
                ? GameHermesVoiceCancelTimeout
                : GameHermesVoiceTranscriptionTimeout);
        try
        {
            var response = await GameHermesClient.StopVoiceAsync(
                    Guid.NewGuid(),
                    capture.CaptureId,
                    disposition,
                    timeout.Token)
                .ConfigureAwait(false);
            PendingGameHermesVoiceBridgeResults.Enqueue(
                new PendingGameHermesVoiceBridgeResult(
                    capture.CaptureId,
                    startResponse: null,
                    response,
                    disposition,
                    string.Empty));
        }
        catch (Exception exception)
        {
            await TryCancelOrphanedGameHermesVoiceCaptureAsync(
                    capture.CaptureId)
                .ConfigureAwait(false);
            PendingGameHermesVoiceBridgeResults.Enqueue(
                new PendingGameHermesVoiceBridgeResult(
                    capture.CaptureId,
                    startResponse: null,
                    stopResponse: null,
                    disposition,
                    exception.GetType().Name));
        }
    }

    private static async Task TryCancelOrphanedGameHermesVoiceCaptureAsync(
        Guid captureId)
    {
        while (true)
        {
            var reconciliationStartedTimestamp = Stopwatch.GetTimestamp();
            var lastResult = "no_receipt";
            while (true)
            {
                var elapsedTicks = Math.Max(
                    0,
                    Stopwatch.GetTimestamp() - reconciliationStartedTimestamp);
                var elapsed = TimeSpan.FromSeconds(
                    elapsedTicks / (double)Stopwatch.Frequency);
                var remainingSafetyEnvelope =
                    GameHermesVoiceCancelTimeout - elapsed;
                if (remainingSafetyEnvelope <= TimeSpan.Zero)
                    break;

                using var timeout = new CancellationTokenSource(
                    remainingSafetyEnvelope);
                try
                {
                    var response = await GameHermesClient.StopVoiceAsync(
                            Guid.NewGuid(),
                            captureId,
                            LilithGameBridgeVoiceStopDisposition.Cancel,
                            timeout.Token)
                        .ConfigureAwait(false);
                    if (IsGameHermesVoiceRetirementReceipt(response))
                        return;
                    lastResult = response.Code;
                }
                catch (Exception exception)
                {
                    lastResult = exception.GetType().Name;
                }

                elapsedTicks = Math.Max(
                    0,
                    Stopwatch.GetTimestamp() - reconciliationStartedTimestamp);
                elapsed = TimeSpan.FromSeconds(
                    elapsedTicks / (double)Stopwatch.Frequency);
                remainingSafetyEnvelope = GameHermesVoiceCancelTimeout - elapsed;
                if (remainingSafetyEnvelope <= TimeSpan.Zero)
                    break;
                await Task.Delay(
                        remainingSafetyEnvelope < TimeSpan.FromMilliseconds(250)
                            ? remainingSafetyEnvelope
                            : TimeSpan.FromMilliseconds(250))
                    .ConfigureAwait(false);
            }

            Plugin.PluginLog.LogInfo(
                "Native Hermes voice orphan reconciliation is still waiting "
                + "for physical-retirement proof: "
                + lastResult
                + ".");
            await Task.Delay(TimeSpan.FromSeconds(1)).ConfigureAwait(false);
        }
    }

    private static bool IsGameHermesVoiceRetirementReceipt(
        LilithGameBridgeVoiceStopResponse response)
        => !response.Succeeded
            && string.IsNullOrEmpty(response.Transcript)
            && ((response.Terminal == LilithGameBridgeTerminal.Interrupted
                    && string.Equals(
                        response.Code,
                        "runtime.voice_cancelled",
                        StringComparison.Ordinal))
                || (response.Terminal == LilithGameBridgeTerminal.Failed
                    && string.Equals(
                        response.Code,
                        "runtime.voice_generation_restarted",
                        StringComparison.Ordinal)));

    private static void ProcessPendingGameHermesVoiceBridgeResults()
    {
        while (PendingGameHermesVoiceBridgeResults.TryDequeue(
                   out var pending))
        {
            var capture = _activeGameHermesVoiceCapture;
            if (capture == null || capture.CaptureId != pending.CaptureId)
                continue;
            if (pending.StartResponse != null
                || (pending.StopResponse == null
                    && pending.StopDisposition == null))
            {
                ProcessGameHermesVoiceStartResult(capture, pending);
                continue;
            }
            ProcessGameHermesVoiceStopResult(capture, pending);
        }
    }

    private static void ProcessGameHermesVoiceStartResult(
        ActiveGameHermesVoiceCapture capture,
        PendingGameHermesVoiceBridgeResult pending)
    {
        if (capture.Phase != GameHermesVoiceCapturePhase.Starting)
            return;
        var response = pending.StartResponse;
        if (response == null || !response.Succeeded)
        {
            var cancelled = capture.StopRequested
                && capture.StopDisposition
                    == LilithGameBridgeVoiceStopDisposition.Cancel;
            ReleaseGameHermesVoiceCapture(capture);
            if (!cancelled)
            {
                PendingTranscriptionErrors.Enqueue(
                    GameHermesVoiceUnavailableText());
            }
            Plugin.PluginLog.LogWarning(
                "Native Hermes voice start failed: code="
                + (response?.Code ?? pending.FaultType)
                + ".");
            return;
        }

        capture.Phase = GameHermesVoiceCapturePhase.Recording;
        if (capture.StopRequested)
        {
            RequestGameHermesVoiceStop(
                capture,
                capture.StopDisposition,
                capture.ReachedLimit);
        }
    }

    private static void ProcessGameHermesVoiceStopResult(
        ActiveGameHermesVoiceCapture capture,
        PendingGameHermesVoiceBridgeResult pending)
    {
        if (capture.Phase != GameHermesVoiceCapturePhase.Stopping
            || pending.StopDisposition == null)
        {
            return;
        }
        var disposition = pending.StopDisposition.Value;
        if (capture.StopDisposition
                == LilithGameBridgeVoiceStopDisposition.Cancel
            && disposition
                != LilithGameBridgeVoiceStopDisposition.Cancel)
        {
            return;
        }

        var response = pending.StopResponse;
        ReleaseGameHermesVoiceCapture(capture);
        if (disposition == LilithGameBridgeVoiceStopDisposition.Cancel)
        {
            Plugin.PluginLog.LogInfo(
                "Native Hermes voice capture ended by cancellation: code="
                + (response?.Code ?? pending.FaultType)
                + ".");
            return;
        }
        if (response == null
            || !response.Succeeded
            || response.Terminal != LilithGameBridgeTerminal.Completed
            || string.IsNullOrWhiteSpace(response.Transcript))
        {
            PendingTranscriptionErrors.Enqueue(
                GameHermesVoiceUnavailableText());
            Plugin.PluginLog.LogWarning(
                "Native Hermes voice transcription failed: code="
                + (response?.Code ?? pending.FaultType)
                + ".");
            return;
        }

        var transcript = response.Transcript.Trim();
        PendingTranscripts.Enqueue(transcript);
        Plugin.PluginLog.LogInfo(
            "Native Hermes voice transcription completed ("
            + transcript.Length
            + " chars; content hidden from log).");
    }

    private static void ReleaseGameHermesVoiceCapture(
        ActiveGameHermesVoiceCapture capture)
    {
        if (!ReferenceEquals(_activeGameHermesVoiceCapture, capture))
            return;
        _activeGameHermesVoiceCapture = null;
        _microphoneRecording = false;
        _transcriptionInFlight = false;
        _microphoneStartedAt = -1f;
    }

    private static LilithGameBridgeVoiceLanguage
        EffectiveGameHermesVoiceLanguage()
        => D046GameControlProjection.Effective?.SpeechInputLanguage switch
        {
            D046SpeechInputLanguage.Automatic =>
                LilithGameBridgeVoiceLanguage.Automatic,
            D046SpeechInputLanguage.Japanese =>
                LilithGameBridgeVoiceLanguage.Japanese,
            D046SpeechInputLanguage.TraditionalChinese =>
                LilithGameBridgeVoiceLanguage.TraditionalChinese,
            D046SpeechInputLanguage.English =>
                LilithGameBridgeVoiceLanguage.English,
            _ => LilithGameBridgeVoiceLanguage.TraditionalChinese
        };

    private static string GameHermesVoiceUnavailableText()
        => ApiKeyText(
            "剛才沒有聽清楚，再試一次吧。",
            "刚才没有听清楚，再试一次吧。",
            "今の声はうまく聞き取れなかった。もう一度試してみて。",
            "I couldn't understand that recording. Please try again.");

    // Retained for non-F6 legacy callers only. Production F6 is owned by the
    // native Hermes voice bridge above and never enters provider-routed STT.
    private static void HandleVoiceInput(
        DialogueManager manager,
        KeyCode voiceInputKey,
        D046HotkeyTransition voiceInputTransition)
    {
        if (!Plugin.VoiceInputEnabled.Value)
            return;
        if (voiceInputTransition.Pressed)
        {
            if (_microphoneRecording || _transcriptionInFlight || _requestInFlight)
            {
                ForceSaySynthetic(
                    manager,
                    ApiKeyText("先等我一下……", "先等我一下……", "少し待って……", "Wait for me a moment…"),
                    string.Empty,
                    4f);
                return;
            }
            WorkbenchGeminiBinding? assignedSpeechBinding;
            try
            {
                assignedSpeechBinding = OpenAssignedSpeechRecognitionBinding();
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogWarning(
                    "Assigned speech-recognition route is unavailable: "
                    + exception.GetType().Name);
                ForceSaySynthetic(
                    manager,
                    ApiKeyText(
                        "語音辨識模型目前無法使用，請到 Control Center 重新指派。",
                        "语音识别模型目前无法使用，请到 Control Center 重新指派。",
                        "音声認識モデルを使えないみたい。Control Center で選び直してね。",
                        "The assigned speech-recognition model is unavailable. Please select it again in Control Center."),
                    string.Empty,
                    7f);
                return;
            }
            var activeVoiceProvider = assignedSpeechBinding == null
                ? NormalizeAiProvider(Plugin.AiProvider.Value)
                : "Gemini";
            var voiceApiKey = string.Equals(activeVoiceProvider, "Qwen", StringComparison.Ordinal)
                ? Plugin.RetiredLegacyPlaintextProviderCredential(
                    Plugin.QwenApiKey)
                : assignedSpeechBinding?.ApiKey
                  ?? Plugin.RetiredLegacyPlaintextProviderCredential(
                      Plugin.GeminiApiKey);
            if (string.IsNullOrWhiteSpace(voiceApiKey))
            {
                var providerName = string.Equals(activeVoiceProvider, "Qwen", StringComparison.Ordinal) ? "Qwen" : "Gemini";
                ForceSaySynthetic(
                    manager,
                    ApiKeyText($"還沒有設定 {providerName} API Key。", $"还没有设置 {providerName} API Key。", $"{providerName} APIキーがまだ設定されていないよ。", $"The {providerName} API key has not been set yet."),
                    string.Empty,
                    6f);
                return;
            }
            try
            {
                var maxSeconds = Math.Clamp(Plugin.VoiceInputMaxSeconds.Value, 5, 90);
                string deviceName;
                using (var enumerator = new MMDeviceEnumerator())
                    deviceName = enumerator.GetDefaultAudioEndpoint(DataFlow.Capture, Role.Console).FriendlyName;
                _wasapiCapture = new WasapiCapture();
                _wasapiStream = new MemoryStream();
                _wasapiWriter = new WaveFileWriter(_wasapiStream, _wasapiCapture.WaveFormat);
                _voiceCaptureFormat = _wasapiCapture.WaveFormat;
                if (string.Equals(activeVoiceProvider, "Qwen", StringComparison.Ordinal) && UseParaformerRealtime())
                    StartParaformerRealtimeSession();
                _wasapiCapture.DataAvailable += OnWasapiDataAvailable;
                _wasapiCapture.StartRecording();
                _voiceRecognitionBinding = assignedSpeechBinding;
                _microphoneRecording = true;
                _microphoneStartedAt = Time.unscaledTime;
                ForceSaySynthetic(
                    manager,
                    ApiKeyText("正在聽……", "正在听……", "聞いているよ……", "Listening…"),
                    string.Empty,
                    maxSeconds + 2f);
                Plugin.PluginLog.LogInfo($"{voiceInputKey} push-to-talk WASAPI recording started with Windows default input '{deviceName}' ({_wasapiCapture.WaveFormat}).");
            }
            catch (Exception exception)
            {
                _microphoneRecording = false;
                CleanupWasapiCapture();
                Plugin.PluginLog.LogWarning($"Could not start microphone recording: {exception.Message}");
                ForceSaySynthetic(
                    manager,
                    ApiKeyText("沒有收到麥克風的聲音。", "没有收到麦克风的声音。", "マイクの音が届いていないみたい。", "I didn't receive any microphone audio."),
                    string.Empty,
                    6f);
            }
        }

    }

    private static void ReconcileActiveVoiceInputRecording(
        D046HotkeyTransition voiceInputTransition)
    {
        var reachedLimit = _microphoneRecording
            && Time.unscaledTime - _microphoneStartedAt
                >= Math.Clamp(Plugin.VoiceInputMaxSeconds.Value, 5, 90) - 0.1f;
        if (_microphoneRecording
            && (voiceInputTransition.Released || reachedLimit))
        {
            StopVoiceInputRecording(reachedLimit);
        }
    }

    private static void StopVoiceInputRecording(bool reachedLimit)
    {
        _microphoneRecording = false;
        try
        {
            if (_wasapiCapture == null || _wasapiStream == null || _wasapiWriter == null)
                return;
            _wasapiCapture.StopRecording();
            _wasapiCapture.DataAvailable -= OnWasapiDataAvailable;
            byte[] wav;
            lock (WasapiLock)
            {
                _wasapiWriter.Flush();
                _wasapiWriter.Dispose();
                _wasapiWriter = null;
                wav = _wasapiStream.ToArray();
            }
            _wasapiCapture.Dispose();
            _wasapiCapture = null;
            _wasapiStream.Dispose();
            _wasapiStream = null;
            if (wav.Length < 2048)
            {
                _voiceRecognitionBinding = null;
                PendingTranscriptionErrors.Enqueue(ApiKeyText("剛才沒有收到聲音，再試一次吧。", "刚才没有收到声音，再试一次吧。", "今の声は届かなかったみたい。もう一度試してみて。", "I didn't receive that audio. Please try again."));
                return;
            }
            var elapsed = Math.Max(0f, Time.unscaledTime - _microphoneStartedAt);
            var qwenVoiceInput = string.Equals(NormalizeAiProvider(Plugin.AiProvider.Value), "Qwen", StringComparison.Ordinal);
            if (_voiceRecognitionBinding != null)
                qwenVoiceInput = false;
            var prepared = NormalizeVoiceWav(wav, qwenVoiceInput ? 16000 : 24000);
            if (elapsed < 0.3f || (prepared.Measured && prepared.Peak < 0.0005f && prepared.Rms < 0.00005d))
            {
                PendingTranscriptionErrors.Enqueue(ApiKeyText(
                    "剛才沒有收到聲音，再試一次吧。",
                    "刚才没有收到声音，再试一次吧。",
                    "今の録音には声が入っていなかったみたい。もう一度試してみて。",
                    "That recording did not contain audible speech. Please try again."));
                Plugin.PluginLog.LogInfo($"Skipped silent voice transcription locally (elapsed={elapsed:F1}s, RMS={prepared.Rms:F6}, peak={prepared.Peak:F6}).");
                CancelParaformerRealtimeSession();
                _voiceRecognitionBinding = null;
                return;
            }
            _transcriptionInFlight = true;
            if (qwenVoiceInput && _paraformerSessionTask != null)
            {
                _paraformerFinishRequested = true;
                _ = CompleteParaformerOrFallbackAsync(_paraformerSessionTask, prepared.Wav, GetVoiceInputLanguageInstruction());
            }
            else
            {
                _ = RequestTranscriptionAsync(
                    prepared.Wav,
                    GetVoiceInputLanguageInstruction(),
                    _voiceRecognitionBinding);
            }
            Plugin.PluginLog.LogInfo($"Push-to-talk WASAPI recording stopped after {elapsed:F1}s{(reachedLimit ? " (time limit reached)" : string.Empty)}; normalized {wav.Length} to {prepared.Wav.Length} WAV bytes for transcription.");
        }
        catch (Exception exception)
        {
            _voiceRecognitionBinding = null;
            CleanupWasapiCapture();
            Plugin.PluginLog.LogWarning($"Could not finish microphone recording: {exception.Message}");
            PendingTranscriptionErrors.Enqueue(ApiKeyText("剛才沒有聽清楚，再試一次吧。", "刚才没有听清楚，再试一次吧。", "今の声はうまく聞き取れなかった。もう一度試してみて。", "I couldn't understand that recording. Please try again."));
        }
    }

    private static void OnWasapiDataAvailable(object? sender, WaveInEventArgs args)
    {
        lock (WasapiLock)
        {
            _wasapiWriter?.Write(args.Buffer, 0, args.BytesRecorded);
        }
        if (_paraformerSessionTask != null && _voiceCaptureFormat != null && args.BytesRecorded > 0)
        {
            var pcm = ConvertCaptureChunkToMonoPcm16(args.Buffer, args.BytesRecorded, _voiceCaptureFormat);
            if (pcm.Length > 0)
                ParaformerAudioChunks.Enqueue(pcm);
        }
    }

    private static void CleanupWasapiCapture()
    {
        try { _wasapiCapture?.StopRecording(); } catch { }
        try { _wasapiCapture?.Dispose(); } catch { }
        lock (WasapiLock)
        {
            try { _wasapiWriter?.Dispose(); } catch { }
            try { _wasapiStream?.Dispose(); } catch { }
            _wasapiWriter = null;
            _wasapiStream = null;
        }
        _wasapiCapture = null;
        _voiceCaptureFormat = null;
        CancelParaformerRealtimeSession();
    }

    private static void StartParaformerRealtimeSession()
    {
        CancelParaformerRealtimeSession();
        while (ParaformerAudioChunks.TryDequeue(out _)) { }
        _paraformerFinishRequested = false;
        _paraformerResampleAccumulator = 0d;
        _paraformerCancellation = new CancellationTokenSource();
        _paraformerSessionTask = RunParaformerRealtimeSessionAsync(_paraformerCancellation.Token);
        Plugin.PluginLog.LogInfo($"Starting {_paraformerSessionTask.GetType().Name} for {Plugin.QwenRealtimeAsrModel.Value.Trim()} while push-to-talk is held.");
    }

    private static bool UseParaformerRealtime() =>
        Plugin.QwenRealtimeAsrModel.Value.Trim().StartsWith("paraformer-realtime", StringComparison.OrdinalIgnoreCase);

    private static void CancelParaformerRealtimeSession()
    {
        try { _paraformerCancellation?.Cancel(); } catch { }
        try { _paraformerCancellation?.Dispose(); } catch { }
        _paraformerCancellation = null;
        _paraformerSessionTask = null;
        _paraformerFinishRequested = false;
        while (ParaformerAudioChunks.TryDequeue(out _)) { }
    }

    private static async Task<string> RunParaformerRealtimeSessionAsync(CancellationToken cancellationToken)
    {
        using var socket = new ClientWebSocket();
        socket.Options.SetRequestHeader(
            "Authorization",
            "Bearer " + Plugin.RetiredLegacyPlaintextProviderCredential(
                Plugin.QwenApiKey).Trim());
        socket.Options.SetRequestHeader("User-Agent", "Lilith-AI-Mod/0.2.1");
        var endpoint = BuildParaformerWebSocketUri();
        await socket.ConnectAsync(endpoint, cancellationToken).WaitAsync(TimeSpan.FromSeconds(10), cancellationToken).ConfigureAwait(false);

        var taskId = Guid.NewGuid().ToString();
        var language = GetVoiceInputLanguageCode();
        var parameters = new Dictionary<string, object>
        {
            ["format"] = "pcm",
            ["sample_rate"] = 16000,
            ["disfluency_removal_enabled"] = false,
            ["punctuation_prediction_enabled"] = true,
            ["inverse_text_normalization_enabled"] = true,
            ["heartbeat"] = true
        };
        if (!string.IsNullOrWhiteSpace(language))
            parameters["language_hints"] = new[] { language };
        var runTask = new
        {
            header = new { action = "run-task", task_id = taskId, streaming = "duplex" },
            payload = new
            {
                task_group = "audio",
                task = "asr",
                function = "recognition",
                model = Plugin.QwenRealtimeAsrModel.Value.Trim(),
                parameters,
                input = new { }
            }
        };
        await SendWebSocketTextAsync(socket, JsonSerializer.Serialize(runTask), cancellationToken).ConfigureAwait(false);

        while (true)
        {
            var startedMessage = await ReceiveWebSocketTextAsync(socket, cancellationToken)
                .WaitAsync(TimeSpan.FromSeconds(10), cancellationToken).ConfigureAwait(false);
            using var startedDocument = JsonDocument.Parse(startedMessage);
            var header = startedDocument.RootElement.GetProperty("header");
            var eventName = header.GetProperty("event").GetString() ?? string.Empty;
            if (eventName == "task-started")
                break;
            if (eventName == "task-failed")
                throw new InvalidOperationException(GetParaformerFailure(header));
        }

        Plugin.PluginLog.LogInfo($"Paraformer real-time task started (task={taskId}); streaming microphone PCM.");
        var receiveTask = ReceiveParaformerTranscriptAsync(socket, cancellationToken);
        while (!_paraformerFinishRequested || !ParaformerAudioChunks.IsEmpty)
        {
            if (ParaformerAudioChunks.TryDequeue(out var audio))
            {
                for (var offset = 0; offset < audio.Length; offset += 8192)
                {
                    var count = Math.Min(8192, audio.Length - offset);
                    await socket.SendAsync(new ArraySegment<byte>(audio, offset, count), WebSocketMessageType.Binary, true, cancellationToken).ConfigureAwait(false);
                }
            }
            else
            {
                await Task.Delay(8, cancellationToken).ConfigureAwait(false);
            }
        }

        var finishTask = new
        {
            header = new { action = "finish-task", task_id = taskId, streaming = "duplex" },
            payload = new { input = new { } }
        };
        await SendWebSocketTextAsync(socket, JsonSerializer.Serialize(finishTask), cancellationToken).ConfigureAwait(false);
        var transcript = await receiveTask.WaitAsync(TimeSpan.FromSeconds(15), cancellationToken).ConfigureAwait(false);
        if (socket.State == WebSocketState.Open)
            await socket.CloseAsync(WebSocketCloseStatus.NormalClosure, "completed", CancellationToken.None).ConfigureAwait(false);
        return transcript;
    }

    private static async Task<string> ReceiveParaformerTranscriptAsync(ClientWebSocket socket, CancellationToken cancellationToken)
    {
        var finalSentences = new List<string>();
        var latestInterim = string.Empty;
        while (true)
        {
            var message = await ReceiveWebSocketTextAsync(socket, cancellationToken).ConfigureAwait(false);
            using var document = JsonDocument.Parse(message);
            var header = document.RootElement.GetProperty("header");
            var eventName = header.GetProperty("event").GetString() ?? string.Empty;
            if (eventName == "task-failed")
                throw new InvalidOperationException(GetParaformerFailure(header));
            if (eventName == "task-finished")
                return CleanReply(finalSentences.Count > 0 ? string.Concat(finalSentences) : latestInterim);
            if (eventName != "result-generated"
                || !document.RootElement.TryGetProperty("payload", out var payload)
                || !payload.TryGetProperty("output", out var output)
                || !output.TryGetProperty("sentence", out var sentence))
                continue;
            var text = sentence.TryGetProperty("text", out var textElement) ? textElement.GetString() ?? string.Empty : string.Empty;
            var sentenceEnd = sentence.TryGetProperty("sentence_end", out var endElement) && endElement.GetBoolean();
            if (sentenceEnd)
            {
                if (!string.IsNullOrWhiteSpace(text))
                    finalSentences.Add(text);
                latestInterim = string.Empty;
            }
            else if (!string.IsNullOrWhiteSpace(text))
            {
                latestInterim = text;
            }
        }
    }

    private static async Task<string> ReceiveWebSocketTextAsync(ClientWebSocket socket, CancellationToken cancellationToken)
    {
        var buffer = new byte[8192];
        using var stream = new MemoryStream();
        while (true)
        {
            var result = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), cancellationToken).ConfigureAwait(false);
            if (result.MessageType == WebSocketMessageType.Close)
                throw new WebSocketException($"Paraformer closed the connection ({socket.CloseStatus}: {socket.CloseStatusDescription}).");
            if (result.MessageType != WebSocketMessageType.Text)
                continue;
            stream.Write(buffer, 0, result.Count);
            if (result.EndOfMessage)
                return Encoding.UTF8.GetString(stream.ToArray());
        }
    }

    private static Task SendWebSocketTextAsync(ClientWebSocket socket, string text, CancellationToken cancellationToken)
    {
        var data = Encoding.UTF8.GetBytes(text);
        return socket.SendAsync(new ArraySegment<byte>(data), WebSocketMessageType.Text, true, cancellationToken);
    }

    private static Uri BuildParaformerWebSocketUri()
    {
        var baseUri = new Uri(NormalizeQwenBaseUrl(Plugin.QwenBaseUrl.Value));
        var builder = new UriBuilder(baseUri)
        {
            Scheme = "wss",
            Port = -1,
            Path = "/api-ws/v1/inference",
            Query = string.Empty
        };
        return builder.Uri;
    }

    private static string GetParaformerFailure(JsonElement header)
    {
        var code = header.TryGetProperty("error_code", out var codeElement) ? codeElement.GetString() : null;
        var message = header.TryGetProperty("error_message", out var messageElement) ? messageElement.GetString() : null;
        return $"Paraformer task failed: {code ?? "unknown"}: {message ?? "no details"}";
    }

    private static async Task CompleteParaformerOrFallbackAsync(Task<string> sessionTask, byte[] fallbackWav, string languageInstruction)
    {
        var timer = Stopwatch.StartNew();
        try
        {
            var transcript = CleanReply(await sessionTask.ConfigureAwait(false));
            if (string.IsNullOrWhiteSpace(transcript))
                throw new InvalidOperationException("Paraformer returned an empty transcript.");
            PendingTranscripts.Enqueue(transcript);
            Plugin.PluginLog.LogInfo($"Paraformer real-time transcription completed in {timer.Elapsed.TotalSeconds:F2}s after key release ({transcript.Length} chars; content hidden from log).");
            _transcriptionInFlight = false;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Paraformer real-time transcription failed; falling back to qwen3-asr-flash: {exception.Message}");
            await RequestQwenTranscriptionAsync(fallbackWav, languageInstruction).ConfigureAwait(false);
        }
        finally
        {
            if (ReferenceEquals(_paraformerSessionTask, sessionTask))
            {
                try { _paraformerCancellation?.Dispose(); } catch { }
                _paraformerCancellation = null;
                _paraformerSessionTask = null;
                _paraformerFinishRequested = false;
                _voiceCaptureFormat = null;
                while (ParaformerAudioChunks.TryDequeue(out _)) { }
            }
        }
    }

    private static byte[] ConvertCaptureChunkToMonoPcm16(byte[] buffer, int count, WaveFormat format)
    {
        var channels = Math.Max(1, format.Channels);
        var bytesPerSample = Math.Max(1, format.BitsPerSample / 8);
        var frameSize = Math.Max(1, format.BlockAlign);
        var frames = count / frameSize;
        using var output = new MemoryStream(Math.Max(256, frames * 2 * 16000 / Math.Max(8000, format.SampleRate)));
        using var writer = new BinaryWriter(output, Encoding.ASCII, true);
        for (var frame = 0; frame < frames; frame++)
        {
            double mixed = 0d;
            for (var channel = 0; channel < channels; channel++)
            {
                var offset = frame * frameSize + channel * bytesPerSample;
                float sample;
                if (format.Encoding == WaveFormatEncoding.IeeeFloat && bytesPerSample == 4)
                    sample = BitConverter.ToSingle(buffer, offset);
                else if (bytesPerSample == 2)
                    sample = BitConverter.ToInt16(buffer, offset) / 32768f;
                else if (bytesPerSample == 3)
                {
                    var value = buffer[offset] | (buffer[offset + 1] << 8) | (buffer[offset + 2] << 16);
                    if ((value & 0x800000) != 0) value |= unchecked((int)0xFF000000);
                    sample = value / 8388608f;
                }
                else if (bytesPerSample == 4)
                    sample = BitConverter.ToInt32(buffer, offset) / 2147483648f;
                else
                    sample = 0f;
                mixed += sample;
            }
            var mono = (float)(mixed / channels);
            _paraformerResampleAccumulator += 16000d;
            if (_paraformerResampleAccumulator < format.SampleRate)
                continue;
            _paraformerResampleAccumulator -= format.SampleRate;
            writer.Write((short)Math.Round(Math.Clamp(mono, -1f, 1f) * short.MaxValue));
        }
        writer.Flush();
        return output.ToArray();
    }

    private static byte[] EncodePcm16Wav(float[] samples, int channels, int sampleRate)
    {
        using var stream = new MemoryStream(44 + samples.Length * 2);
        using var writer = new BinaryWriter(stream, Encoding.ASCII, true);
        writer.Write(Encoding.ASCII.GetBytes("RIFF"));
        writer.Write(36 + samples.Length * 2);
        writer.Write(Encoding.ASCII.GetBytes("WAVEfmt "));
        writer.Write(16);
        writer.Write((short)1);
        writer.Write((short)channels);
        writer.Write(sampleRate);
        writer.Write(sampleRate * channels * 2);
        writer.Write((short)(channels * 2));
        writer.Write((short)16);
        writer.Write(Encoding.ASCII.GetBytes("data"));
        writer.Write(samples.Length * 2);
        foreach (var sample in samples)
            writer.Write((short)Math.Round(Math.Clamp(sample, -1f, 1f) * short.MaxValue));
        writer.Flush();
        return stream.ToArray();
    }

    private static (byte[] Wav, double Rms, float Peak, bool Measured) NormalizeVoiceWav(byte[] wav, int preferredSampleRate)
    {
        try
        {
            using var input = new MemoryStream(wav, false);
            using var reader = new WaveFileReader(input);
            var provider = reader.ToSampleProvider();
            var channels = Math.Max(1, provider.WaveFormat.Channels);
            var sourceRate = Math.Max(8000, provider.WaveFormat.SampleRate);
            var estimatedSamples = (int)Math.Min(int.MaxValue, Math.Max(4096L,
                reader.Length / Math.Max(1, reader.WaveFormat.BlockAlign) * channels));
            var samples = new float[estimatedSamples];
            var count = 0;
            while (count < samples.Length)
            {
                var read = provider.Read(samples, count, samples.Length - count);
                if (read <= 0)
                    break;
                count += read;
            }
            if (count < channels)
                return (wav, 0d, 0f, false);

            var frames = count / channels;
            var mono = new float[frames];
            double sumSquares = 0;
            float peak = 0;
            for (var frame = 0; frame < frames; frame++)
            {
                double sum = 0;
                for (var channel = 0; channel < channels; channel++)
                    sum += samples[frame * channels + channel];
                var value = (float)(sum / channels);
                mono[frame] = value;
                sumSquares += value * value;
                peak = Math.Max(peak, Math.Abs(value));
            }

            var rms = Math.Sqrt(sumSquares / Math.Max(1, frames));
            var gain = peak > 0.001f ? Math.Min(3f, 0.88f / peak) : 1f;
            if (gain > 1.05f)
                for (var i = 0; i < mono.Length; i++)
                    mono[i] = Math.Clamp(mono[i] * gain, -1f, 1f);

            var targetRate = Math.Min(Math.Clamp(preferredSampleRate, 8000, 48000), sourceRate);
            float[] output;
            if (targetRate == sourceRate)
            {
                output = mono;
            }
            else
            {
                var outputFrames = Math.Max(1, (int)Math.Round(frames * (double)targetRate / sourceRate));
                output = new float[outputFrames];
                var ratio = sourceRate / (double)targetRate;
                for (var i = 0; i < outputFrames; i++)
                {
                    var position = i * ratio;
                    var left = Math.Min(frames - 1, (int)position);
                    var right = Math.Min(frames - 1, left + 1);
                    var fraction = (float)(position - left);
                    output[i] = mono[left] + (mono[right] - mono[left]) * fraction;
                }
            }

            Plugin.PluginLog.LogInfo($"Voice audio prepared as mono PCM16 {targetRate}Hz (source {sourceRate}Hz/{channels}ch, RMS {rms:F4}, peak {peak:F4}, gain {gain:F2}x).");
            return (EncodePcm16Wav(output, 1, targetRate), rms, peak, true);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Voice audio normalization failed; sending original recording: {exception.Message}");
            return (wav, 0d, 0f, false);
        }
    }

    private static string GetVoiceInputLanguageInstruction()
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            if (language.StartsWith("ja", StringComparison.OrdinalIgnoreCase))
                return "The game interface language is Japanese. Transcribe as natural Japanese using Japanese script.";
            if (language.StartsWith("zh-CN", StringComparison.OrdinalIgnoreCase)
                || language.StartsWith("zh-Hans", StringComparison.OrdinalIgnoreCase))
                return "The game interface language is Simplified Chinese. Transcribe the speech in Simplified Chinese characters.";
            if (language.StartsWith("zh", StringComparison.OrdinalIgnoreCase))
                return "The game interface language is Traditional Chinese. Transcribe the speech in Traditional Chinese characters.";
            if (language.StartsWith("en", StringComparison.OrdinalIgnoreCase))
                return "The game interface language is English. Transcribe the speech in English.";
        }
        catch
        {
        }
        return "Detect whether the speech is Traditional Chinese, Japanese, or English, and transcribe it in the spoken language.";
    }

    private static WorkbenchGeminiBinding? OpenAssignedSpeechRecognitionBinding()
    {
        var providers = UnifiedProviderControlStore.Load();
        if (!providers.Accepted || providers.Snapshot == null)
            throw new InvalidOperationException("Provider control plane is unavailable.");
        var routes = D045AiFunctionRoutingStore.ForCurrentUser().Load();
        var route = routes.Snapshot?.Find(D045AiFunctionKind.SpeechRecognition);
        if (route == null)
            return null;
        var instance = providers.Snapshot.Instances.SingleOrDefault(value =>
            string.Equals(value.InstanceId, route.InstanceId, StringComparison.Ordinal));
        if (instance == null
            || !route.Matches(instance)
            || instance.ProviderKind != ProviderControlKind.GoogleGemini
            || !instance.CredentialConfigured)
        {
            throw new InvalidOperationException(
                "The speech-recognition route no longer matches its provider.");
        }
        var opened = UnifiedProviderControlStore.OpenCredential(instance);
        if (opened.Admission != UnifiedProviderStoreAdmission.Accepted
            || opened.Lease == null)
        {
            throw new InvalidOperationException(
                "The speech-recognition credential is unavailable.");
        }
        char[]? secret = null;
        try
        {
            secret = opened.Lease.Take();
            var model = route.ModelId.StartsWith("models/", StringComparison.Ordinal)
                ? route.ModelId[7..]
                : route.ModelId;
            return new WorkbenchGeminiBinding(
                new string(secret),
                route.ModelId,
                new Uri(
                    instance.BaseUri,
                    "v1beta/models/"
                    + Uri.EscapeDataString(model)
                    + ":generateContent").AbsoluteUri,
                highReasoning: false);
        }
        finally
        {
            if (secret != null)
                Array.Clear(secret, 0, secret.Length);
            opened.Lease.Dispose();
        }
    }

    private static async Task RequestTranscriptionAsync(
        byte[] wav,
        string languageInstruction,
        WorkbenchGeminiBinding? assignedBinding = null)
    {
        if (string.Equals(NormalizeAiProvider(Plugin.AiProvider.Value), "Qwen", StringComparison.Ordinal))
        {
            await RequestQwenTranscriptionAsync(wav, languageInstruction).ConfigureAwait(false);
            return;
        }
        try
        {
            var model = Uri.EscapeDataString(
                assignedBinding?.ModelId ?? Plugin.GeminiModel.Value.Trim());
            var url = assignedBinding?.Url
                ?? $"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent";
            var payload = new
            {
                contents = new[]
                {
                    new
                    {
                        role = "user",
                        parts = new object[]
                        {
                            new { text = $"Transcribe every spoken word in this entire recording verbatim from beginning to end. Do not summarize, shorten, answer, or omit later sentences, even when the speaker pauses or changes topic. Preserve all clauses and add natural punctuation. {languageInstruction} Return only the complete transcript, with no explanation, labels, quotation marks, or Markdown." },
                            new { inline_data = new { mime_type = "audio/wav", data = Convert.ToBase64String(wav) } }
                        }
                    }
                },
                generationConfig = new
                {
                    temperature = 0,
                    maxOutputTokens = 1024,
                    thinkingConfig = new { thinkingLevel = "MINIMAL" }
                }
            };
            using var request = new HttpRequestMessage(HttpMethod.Post, url);
            request.Headers.Add(
                "x-goog-api-key",
                assignedBinding?.ApiKey
                ?? Plugin.RetiredLegacyPlaintextProviderCredential(
                    Plugin.GeminiApiKey).Trim());
            request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json");
            using var response = await Http.SendAsync(request).ConfigureAwait(false);
            var body = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Gemini transcription HTTP {(int)response.StatusCode}: {body}");
            using var document = JsonDocument.Parse(body);
            var parts = document.RootElement.GetProperty("candidates")[0].GetProperty("content").GetProperty("parts");
            var builder = new StringBuilder();
            foreach (var part in parts.EnumerateArray())
                if (part.TryGetProperty("text", out var textPart))
                    builder.Append(textPart.GetString());
            var transcript = CleanReply(builder.ToString());
            if (string.IsNullOrWhiteSpace(transcript))
                throw new InvalidOperationException("Gemini returned an empty transcript.");
            PendingTranscripts.Enqueue(transcript);
            Plugin.PluginLog.LogInfo($"Voice transcription completed ({transcript.Length} chars; content hidden from log).");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Voice transcription failed: {exception}");
            PendingTranscriptionErrors.Enqueue(ApiKeyText("剛才沒有聽清楚，再試一次吧。", "刚才没有听清楚，再试一次吧。", "今の声はうまく聞き取れなかった。もう一度試してみて。", "I couldn't understand that recording. Please try again."));
        }
        finally
        {
            _voiceRecognitionBinding = null;
            _transcriptionInFlight = false;
        }
    }

    private static async Task RequestQwenTranscriptionAsync(byte[] wav, string languageInstruction)
    {
        try
        {
            var baseUrl = NormalizeQwenBaseUrl(Plugin.QwenBaseUrl.Value);
            var url = baseUrl + "/chat/completions";
            var language = GetVoiceInputLanguageCode();
            var asrOptions = new Dictionary<string, object> { ["enable_itn"] = false };
            if (!string.IsNullOrWhiteSpace(language))
                asrOptions["language"] = language;
            var payload = new Dictionary<string, object>
            {
                ["model"] = UseParaformerRealtime() ? "qwen3-asr-flash" : Plugin.QwenAsrModel.Value.Trim(),
                ["messages"] = new object[]
                {
                    new
                    {
                        role = "user",
                        content = new object[]
                        {
                            new
                            {
                                type = "input_audio",
                                input_audio = new { data = "data:audio/wav;base64," + Convert.ToBase64String(wav) }
                            }
                        }
                    }
                },
                ["stream"] = false,
                ["asr_options"] = asrOptions
            };
            using var request = new HttpRequestMessage(HttpMethod.Post, url);
            request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue(
                "Bearer",
                Plugin.RetiredLegacyPlaintextProviderCredential(
                    Plugin.QwenApiKey).Trim());
            request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json");
            using var response = await Http.SendAsync(request).ConfigureAwait(false);
            var body = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Qwen transcription HTTP {(int)response.StatusCode}: {body}");
            using var document = JsonDocument.Parse(body);
            var transcript = CleanReply(document.RootElement.GetProperty("choices")[0].GetProperty("message").GetProperty("content").GetString() ?? string.Empty);
            if (string.IsNullOrWhiteSpace(transcript))
                throw new InvalidOperationException("Qwen returned an empty transcript.");
            PendingTranscripts.Enqueue(transcript);
            var emotion = "unknown";
            var message = document.RootElement.GetProperty("choices")[0].GetProperty("message");
            if (message.TryGetProperty("annotations", out var annotations) && annotations.ValueKind == JsonValueKind.Array)
            {
                foreach (var annotation in annotations.EnumerateArray())
                    if (annotation.TryGetProperty("emotion", out var emotionElement))
                        emotion = emotionElement.GetString() ?? emotion;
            }
            Plugin.PluginLog.LogInfo($"Qwen voice transcription completed ({transcript.Length} chars; detectedEmotion={emotion}; content hidden from log).");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Qwen voice transcription failed: {exception}");
            PendingTranscriptionErrors.Enqueue(IsQwenAccountUnavailable(exception)
                ? QwenAccountUnavailableReply()
                : ApiKeyText("剛才沒有聽清楚，再試一次吧。", "刚才没有听清楚，再试一次吧。", "今の声はうまく聞き取れなかった。もう一度試してみて。", "I couldn't understand that recording. Please try again."));
        }
        finally
        {
            _transcriptionInFlight = false;
        }
    }

    private static string GetVoiceInputLanguageCode()
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            if (language.StartsWith("ja", StringComparison.OrdinalIgnoreCase)) return "ja";
            if (language.StartsWith("zh", StringComparison.OrdinalIgnoreCase)) return "zh";
            if (language.StartsWith("en", StringComparison.OrdinalIgnoreCase)) return "en";
        }
        catch
        {
        }
        return string.Empty;
    }

    private static string ApiKeyText(string traditionalChinese, string simplifiedChinese, string japanese, string english)
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            if (language.StartsWith("ja", StringComparison.OrdinalIgnoreCase))
                return japanese;
            if (language.StartsWith("zh-CN", StringComparison.OrdinalIgnoreCase)
                || language.StartsWith("zh-Hans", StringComparison.OrdinalIgnoreCase))
                return simplifiedChinese;
            if (language.StartsWith("zh", StringComparison.OrdinalIgnoreCase))
                return traditionalChinese;
        }
        catch
        {
        }
        return english;
    }

    private static (string Name, string ExtraRule, string Example) GetAiInterfaceLanguage()
    {
        var projection = LilithGamePersonaLocaleProjector.Resolve(
            GetAgentTurnLocale());
        return (
            projection.DisplayLanguageName,
            projection.DisplayOutputInstruction,
            projection.DisplayExample);
    }

    private static bool UsesTraditionalChineseInterface()
    {
        try
        {
            var language = GameSetting.Language ?? string.Empty;
            return language.StartsWith("zh-HK", StringComparison.OrdinalIgnoreCase)
                || language.StartsWith("zh-TW", StringComparison.OrdinalIgnoreCase)
                || (language.StartsWith("zh", StringComparison.OrdinalIgnoreCase)
                    && !language.StartsWith("zh-CN", StringComparison.OrdinalIgnoreCase)
                    && !language.StartsWith("zh-Hans", StringComparison.OrdinalIgnoreCase));
        }
        catch
        {
            return true;
        }
    }

    private static string GetTransformPath(Transform? transform)
    {
        var names = new List<string>();
        while (transform != null)
        {
            names.Add(transform.name);
            transform = transform.parent;
        }
        names.Reverse();
        return string.Join("/", names);
    }

