    internal static NativeDialogueForceSayInvocationToken
        BeginNativeDialogueForceSayInvocation(
        DialogueManager manager)
    {
        try
        {
            ObserveMiniGameForceSayInvocation(manager);
            nint nodeIdentityBefore = 0;
            try
            {
                var nodeBefore = manager.CurrentNode;
                nodeIdentityBefore = nodeBefore == null
                    ? 0
                    : nodeBefore.Pointer;
            }
            catch
            {
                // The invocation remains conservatively unresolved.
            }
            return NativeDialogueForceSay.Begin(
                manager.GetInstanceID(),
                nodeIdentityBefore);
        }
        catch
        {
            NativeDialogueHermesCapture.Interrupt();
            throw;
        }
    }

    internal static NativeDialogueOfficialAppSpeechToken
        BeginNativeDialogueOfficialAppSpeech(
        string text,
        int lineId)
    {
        var application = NativeDialogueOfficialAppProvenance.TryResolveKnownAppAwareTrigger(lineId, out var trigger)
            ? CaptureNativeApplicationObservation(trigger) : null;
        return NativeDialogueOfficialApp.BeginSpeech(text, lineId, application);
    }

    private static LilithGameBridgeNativeApplicationObservation? CaptureNativeApplicationObservation(string trigger)
    {
        if (!OperatingSystem.IsWindows()
            || !LilithGameBridgeNativeApplicationObservation.IsApplicationTrigger(trigger)) return null;
        try
        {
            var window = GetForegroundWindow();
            if (window == IntPtr.Zero || !IsWindowVisible(window)) return null;
            GetWindowThreadProcessId(window, out var processId);
            if (processId == 0 || processId == (uint)Environment.ProcessId) return null;
            using var process = Process.GetProcessById(checked((int)processId));
            if (!ForegroundProactiveApplicationPolicy.TryDescribe(process.ProcessName, out var application)
                || application is null || application.ApplicationId == "other") return null;
            var started = new DateTimeOffset(process.StartTime.ToUniversalTime()).ToUnixTimeMilliseconds();
            if (GetForegroundWindow() != window) return null;
            GetWindowThreadProcessId(window, out var currentProcessId);
            if (currentProcessId != processId) return null;
            return new(application.ApplicationId, application.DisplayName, application.Category,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(), window.ToInt64(), checked((int)processId), started);
        }
        catch { return null; } // No title, path, image, or private process data is retained/logged.
    }

    internal static void CompleteNativeDialogueOfficialAppSpeech(
        DialogueManager manager,
        NativeDialogueOfficialAppSpeechToken token,
        bool succeeded)
    {
        try
        {
            var node = manager.CurrentNode;
            var commit = NativeDialogueOfficialApp.CompleteSpeech(
                token,
                succeeded,
                node?.id ?? 0,
                node?.lineId ?? 0,
                GameSetting.Language ?? string.Empty,
                DateTimeOffset.UtcNow);
            if (commit == null)
                return;
            Plugin.PluginLog.LogInfo(
                "Captured one official direct perception dialogue: node="
                + commit.NodeId
                + ", line="
                + commit.LineId
                + ", trigger="
                + commit.Trigger
                + ".");
            EnqueueNativeDialogueHermesCommit(commit);
        }
        catch (Exception exception)
        {
            NativeDialogueOfficialApp.FailSpeech(token);
            Plugin.PluginLog.LogWarning(
                "Could not retain official direct perception dialogue: "
                + exception.GetType().Name
                + ".");
        }
    }

    internal static void FailNativeDialogueOfficialAppSpeech(
        NativeDialogueOfficialAppSpeechToken token)
        => NativeDialogueOfficialApp.FailSpeech(token);

    internal static void CompleteNativeDialogueForceSayInvocation(
        DialogueManager manager,
        NativeDialogueForceSayInvocationToken token,
        bool succeeded)
    {
        if (!succeeded)
        {
            NativeDialogueForceSay.Fail(token);
            return;
        }
        nint nodeIdentityAfter = 0;
        try
        {
            var node = manager.CurrentNode;
            nodeIdentityAfter = node == null ? 0 : node.Pointer;
        }
        catch
        {
            // A successful invocation with no readable exact node identity
            // leaves a one-shot unresolved exclusion for this manager.
        }
        NativeDialogueForceSay.Complete(
            token,
            nodeIdentityAfter);
    }

    internal static void FailNativeDialogueForceSayInvocation(
        NativeDialogueForceSayInvocationToken token)
    {
        NativeDialogueForceSay.Fail(token);
        NativeDialogueHermesCapture.Interrupt();
    }

    internal static long BeginNativeDialogueHermesCapture(
        DialogueBubbleUI bubble,
        DialogueNode? node)
    {
        try
        {
            if (node == null)
            {
                NativeDialogueHermesCapture.Interrupt();
                return 0;
            }
            var manager = DialogueManager.instance;
            var managerNode = manager?.CurrentNode;
            var managerInstanceId = manager?.GetInstanceID() ?? 0;
            var exactBubbleTypewriter = bubble._typewriter;
            var exactBubbleTypewriterInstanceId =
                exactBubbleTypewriter?.GetInstanceID() ?? 0;
            var forceSayExcluded = NativeDialogueForceSay.ExcludesShowNode(
                managerInstanceId,
                node.Pointer,
                bubble.GetInstanceID());
            var nativeDialogueTrigger = NativeDialogueTrigger(node);
            var officialLifecycle = managerNode != null
                && node.id > 0
                && node.lineId > 0
                && managerNode.id == node.id
                && managerNode.lineId == node.lineId
                && string.Equals(
                    managerNode.text,
                    node.text,
                    StringComparison.Ordinal)
                && (NativeDialogueOfficialAppProvenance
                        .IsKnownAppAwareLine(node.lineId)
                    || NativeDialogueMeaningfulOfficialProvenance
                        .IsAdmittedShowNode(
                            node.id,
                            node.lineId,
                            nativeDialogueTrigger))
                && !forceSayExcluded
                && !IsCurrentPublishedAiPageNode(node)
                && exactBubbleTypewriterInstanceId != 0
                && _nativeDialogueHermesOutbox != null;
            var generation = NativeDialogueHermesCapture.BeginShowNode(
                managerInstanceId,
                bubble.GetInstanceID(),
                exactBubbleTypewriterInstanceId,
                node.Pointer,
                node.id,
                node.lineId,
                nativeDialogueTrigger,
                GameSetting.Language ?? string.Empty,
                officialLifecycle,
                out var nativeDialogueAdmitted,
                officialLifecycle ? CaptureNativeApplicationObservation(nativeDialogueTrigger) : null);
            if (nativeDialogueAdmitted)
                NativeDialogueOfficialApp.ObserveAcceptedShowNode();
            if (officialLifecycle)
            {
                Plugin.PluginLog.LogInfo(
                    "Armed native dialogue memory capture: node="
                    + node.id
                    + ", line="
                    + node.lineId
                    + ".");
            }
            return generation;
        }
        catch (Exception exception)
        {
            NativeDialogueHermesCapture.Interrupt();
            Plugin.PluginLog.LogWarning(
                "Could not arm native dialogue memory capture: "
                + exception.GetType().Name
                + ".");
            return 0;
        }
    }

    internal static void EndNativeDialogueHermesShowNode(
        DialogueBubbleUI bubble,
        long generation,
        bool succeeded)
    {
        NativeDialogueHermesCapture.EndShowNode(
            generation,
            bubble.GetInstanceID(),
            succeeded);
    }

    private static string NativeDialogueTrigger(DialogueNode node)
    {
        try
        {
            var triggers = node.triggerTypes;
            if (triggers == null || triggers.Count <= 0)
                return string.Empty;
            var names = new List<string>(Math.Min(triggers.Count, 8));
            for (var index = 0;
                 index < triggers.Count && names.Count < 8;
                 index++)
            {
                names.Add(triggers[index].ToString());
            }
            return string.Join(",", names);
        }
        catch
        {
            return string.Empty;
        }
    }

    internal static long BeginNativeDialogueTypewriterPlay(
        TypewriterEffect typewriter)
    {
        var typewriterInstanceId = typewriter.GetInstanceID();
        var manager = DialogueManager.instance;
        var node = manager?.CurrentNode;
        var generation = manager == null || node == null
            ? 0
            : NativeDialogueHermesCapture.BindTypewriter(
                manager.GetInstanceID(),
                node.Pointer,
                typewriterInstanceId,
                typewriter.IsTyping);
        _nativeDialogueTypewriterPlayGeneration = generation;
        _nativeDialogueTypewriterPlayInstanceId = generation == 0
            ? 0
            : typewriterInstanceId;
        return generation;
    }

    internal static void EndNativeDialogueTypewriterPlay(
        TypewriterEffect typewriter,
        long generation)
    {
        if (_nativeDialogueTypewriterPlayGeneration == generation
            && _nativeDialogueTypewriterPlayInstanceId
                == typewriter.GetInstanceID())
        {
            _nativeDialogueTypewriterPlayGeneration = 0;
            _nativeDialogueTypewriterPlayInstanceId = 0;
        }
    }

    internal static void FailNativeDialogueTypewriterPlay(
        TypewriterEffect typewriter,
        long generation)
    {
        EndNativeDialogueTypewriterPlay(typewriter, generation);
        if (generation != 0)
            NativeDialogueHermesCapture.Interrupt("typewriter-play-threw");
    }

    internal static NativeDialogueTypewriterStopPatchState
        BeginNativeDialogueTypewriterStop(
