        => NativeDialogueHermesCapture.Interrupt();

    private static void EnqueueNativeDialogueHermesCommit(
        NativeDialogueHermesCommit? commit)
    {
        if (commit == null)
            return;
        commit = commit.WithProactiveDialogueEnabled(
            EffectiveD046ProactiveDialogueEnabled()
            && NativeDialogueMeaningfulOfficialProvenance
                .RequestsProactiveExtension(commit.Trigger));
        var outbox = _nativeDialogueHermesOutbox;
        if (outbox == null)
        {
            Plugin.PluginLog.LogWarning(
                "Native dialogue memory remained fail-closed because its durable outbox is unavailable.");
            return;
        }
        try
        {
            if (commit.ProactiveDialogueEnabled)
                NativeMiniGameEvents.Capture(commit.EventId, CaptureMiniGamePublicContext(),
                    Environment.TickCount64);
            if (!outbox.TryEnqueue(commit))
            {
                NativeMiniGameEvents.Settle(commit.EventId, null);
                Plugin.PluginLog.LogError(
                    "Native dialogue durable outbox is full; capture is fail-closed until retained events are acknowledged.");
                return;
            }
            Plugin.PluginLog.LogInfo(
                "Persisted native dialogue in durable outbox: event="
                + commit.EventId.ToString("N")[..8]
                + ", node="
                + commit.NodeId
                + ", line="
                + commit.LineId
                + ", proactive="
                + (commit.ProactiveDialogueEnabled ? "1" : "0")
                + ".");
            StartNativeDialogueHermesCommitWorkerIfNeeded();
        }
        catch (Exception exception)
        {
            NativeMiniGameEvents.Settle(commit.EventId, null);
            Plugin.PluginLog.LogError(
                "Could not persist native dialogue before delivery: "
                + exception.GetType().Name
                + ".");
        }
    }

    internal static void InitializeNativeDialogueHermesOutbox()
    {
        try
        {
            _nativeDialogueHermesOutbox =
                new NativeDialogueHermesDurableOutbox(
                    Path.Combine(
                        PlayerProfileDirectory,
                        "state",
                        "native-dialogue-hermes-outbox-v1"));
            Plugin.PluginLog.LogInfo(
                "Native dialogue durable outbox ready: pending="
                + _nativeDialogueHermesOutbox.Count
                + ".");
            StartNativeDialogueHermesCommitWorkerIfNeeded();
        }
        catch (Exception exception)
        {
            _nativeDialogueHermesOutbox = null;
            NativeDialogueHermesCapture.Interrupt();
            Plugin.PluginLog.LogError(
                "Native dialogue capture is fail-closed because its durable outbox could not be opened: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void StartNativeDialogueHermesCommitWorkerIfNeeded()
    {
        if (_nativeDialogueHermesOutbox?.Count > 0
            && Interlocked.CompareExchange(
                ref _nativeDialogueHermesCommitWorkerStarted,
                1,
                0) == 0)
            _ = RunNativeDialogueHermesCommitWorkerAsync();
    }

    private static async Task RunNativeDialogueHermesCommitWorkerAsync()
    {
        var attempt = 0;
        try
        {
            while (_nativeDialogueHermesOutbox is { } outbox
                && outbox.TryPeek(out var commit)
                && commit != null)
            {
                attempt++;
                if (await TryDeliverNativeDialogueHermesCommitAsync(
                        commit,
                        attempt).ConfigureAwait(false))
                {
                    try
                    {
                        outbox.Acknowledge(commit.EventId);
                        attempt = 0;
                        continue;
                    }
                    catch (Exception exception)
                    {
                        Plugin.PluginLog.LogWarning(
                            "Hermes acknowledged native dialogue, but durable outbox retirement will safely retry the same event: fault="
                            + exception.GetType().Name
                            + ".");
                    }
                }
                var delaySeconds = Math.Min(
                    30,
                    1 << Math.Min(Math.Max(0, attempt - 1), 5));
                await Task.Delay(TimeSpan.FromSeconds(delaySeconds))
                    .ConfigureAwait(false);
            }
        }
        finally
        {
            Interlocked.Exchange(
                ref _nativeDialogueHermesCommitWorkerStarted,
                0);
            StartNativeDialogueHermesCommitWorkerIfNeeded();
        }
    }

    private static readonly NativeMiniGameEventDispatches NativeMiniGameEvents =
        new(MiniGameConversationEvents.Shared);

    private static async Task<bool> TryDeliverNativeDialogueHermesCommitAsync(
        NativeDialogueHermesCommit commit,
        int attempt)
    {
        var eventLabel = commit.EventId.ToString("N")[..8];
        try
        {
            using var timeout = new CancellationTokenSource(
                TimeSpan.FromSeconds(15));
            var response = await GameHermesClient
                .CommitNativeAssistantAsync(
                    Guid.NewGuid(),
                    commit.EventId,
                    commit.Text,
                    commit.OccurredAtUnixTimeMilliseconds,
                    commit.NodeId,
                    commit.LineId,
                    commit.Trigger,
                    commit.Locale,
                    commit.ProactiveDialogueEnabled,
                    commit.Application,
                    timeout.Token,
                    NativeMiniGameEvents.Get(commit.EventId))
                .ConfigureAwait(false);
            if (response.Accepted)
            {
                if (!response.MiniGameEventsPending)
                    NativeMiniGameEvents.Settle(commit.EventId, response.MiniGameEventReceipt);
                // The durable native line is now part of the same canonical
                // Hermes transcript that F10 reads.  Ask the Unity thread to
                // refresh a currently open first page; a closed window will
                // already take a fresh snapshot the next time it is opened.
                Interlocked.Exchange(
                    ref _conversationHistoryRefreshRequested,
                    1);
                if (commit.ProactiveDialogueEnabled)
                {
                    _ = RefreshConversationHistoryAfterNativeContinuationAsync();
                }
                Plugin.PluginLog.LogInfo(
                    "Committed native dialogue to Hermes: event="
                    + eventLabel
                    + ", duplicate="
                    + (response.AlreadyCommitted ? "1" : "0")
                    + ".");
                return true;
            }
            if (attempt == 1 || attempt % 20 == 0)
            {
                Plugin.PluginLog.LogWarning(
                    "Hermes has not acknowledged retained native dialogue: event="
                    + eventLabel
                    + ", retryable="
                    + (response.Retryable ? "1" : "0")
                    + ", code="
                    + response.Code
                    + ".");
            }
            return false;
        }
        catch (Exception exception)
        {
            // A pipe failure may be ambiguous after write. The durable head
            // remains intact and is resent with the exact same event identity.
            if (attempt == 1 || attempt % 20 == 0)
            {
                Plugin.PluginLog.LogWarning(
                    "Native dialogue durable delivery is waiting for Hermes: event="
                    + eventLabel
                    + ", fault="
                    + exception.GetType().Name
                    + ".");
            }
            return false;
        }
    }

    private static async Task
        RefreshConversationHistoryAfterNativeContinuationAsync()
    {
        // Hermes acknowledges the official line before its optional proactive
        // continuation reaches message.complete.  Two bounded invalidations
        // cover the ordinary and slower terminal cases without polling the
        // history pipe or touching Unity objects from a worker thread.
        await Task.Delay(
                ConversationHistoryNativeContinuationFirstRefreshDelay)
            .ConfigureAwait(false);
        Interlocked.Exchange(
            ref _conversationHistoryRefreshRequested,
            1);
        await Task.Delay(
                ConversationHistoryNativeContinuationFinalRefreshDelay)
            .ConfigureAwait(false);
        Interlocked.Exchange(
            ref _conversationHistoryRefreshRequested,
            1);
    }

    private static bool UpdateConversationHistoryWindow(
        DialogueManager manager,
        D046HotkeyTransition historyTransition)
    {
        var isOpen = _conversationHistoryWindow != null && _conversationHistoryWindow.activeSelf;
        if (historyTransition.Pressed)
        {
            if (isOpen)
            {
                CloseConversationHistoryWindow();
                return true;
            }
            OpenConversationHistoryWindow();
            return true;
        }

        if (!isOpen)
            return false;
        RefreshConversationHistoryWindowIfNeeded();
        if (Input.GetKeyDown(KeyCode.Escape))
        {
            CloseConversationHistoryWindow();
            return true;
        }
        if (Input.GetMouseButtonDown(0))
        {
            var pointer = Input.mousePosition;
            if (_conversationHistoryCloseButton != null
                && RectTransformUtility.RectangleContainsScreenPoint(_conversationHistoryCloseButton, pointer, null))
            {
                CloseConversationHistoryWindow();
                return true;
            }
            if (_conversationHistoryNewerButton != null
                && !_conversationHistoryLoadInFlight
                && ConversationHistoryCursorStack.Count > 0
                && RectTransformUtility.RectangleContainsScreenPoint(_conversationHistoryNewerButton, pointer, null))
            {
                _conversationHistoryCursor = ConversationHistoryCursorStack.Pop();
                _conversationHistoryPageNumber = Math.Max(1, _conversationHistoryPageNumber - 1);
                LoadConversationHistoryPage();
                return true;
            }
            if (_conversationHistoryOlderButton != null
                && !_conversationHistoryLoadInFlight
                && _conversationHistoryPage?.HasMore == true
                && RectTransformUtility.RectangleContainsScreenPoint(_conversationHistoryOlderButton, pointer, null))
            {
                ConversationHistoryCursorStack.Push(_conversationHistoryCursor);
                _conversationHistoryCursor = _conversationHistoryPage.NextCursor;
                _conversationHistoryPageNumber++;
                LoadConversationHistoryPage();
                return true;
            }
        }
        return true;
    }

    private static void OpenConversationHistoryWindow()
    {
        OldMaidPresentation.Pause();
        if (_conversationHistoryWindow == null && !TryCreateConversationHistoryWindow())
            return;
        if (_inputBubble != null && _inputBubble.activeSelf)
            CloseInputBubble(clear: false);
        ConversationHistoryCursorStack.Clear();
        _conversationHistoryCursor = string.Empty;
        _conversationHistoryPageNumber = 1;
        _conversationHistoryTransientRetryCount = 0;
        _conversationHistoryRetryAt = -1f;
        _conversationHistoryWindow!.SetActive(true);
        var canvasGroup = _conversationHistoryWindow.GetComponent<CanvasGroup>();
        if (canvasGroup != null)
        {
            canvasGroup.alpha = 1f;
            canvasGroup.interactable = true;
            canvasGroup.blocksRaycasts = true;
        }
        _conversationHistoryWindow.transform.SetAsLastSibling();
        ApplyConversationHistoryViewportLayout();
        UpdateConversationHistoryWindowLocalization();
        LoadConversationHistoryPage();
        TryBringLilithToForeground();
        ExcludeTaskbarFromConversationHistoryWindowRegion();
    }

    private static void CloseConversationHistoryWindow()
    {
        CancelConversationHistoryLoad();
        RestoreConversationHistoryWindowRegion();
        if (_conversationHistoryWindow != null)
            _conversationHistoryWindow.SetActive(false);
        if (_conversationHistoryBody != null)
            _conversationHistoryBody.text = string.Empty;
        _conversationHistoryPage = null;
        _conversationHistoryCursor = string.Empty;
        _conversationHistoryPageNumber = 1;
        _conversationHistoryTransientRetryCount = 0;
        _conversationHistoryRetryAt = -1f;
        Interlocked.Exchange(
            ref _conversationHistoryRefreshRequested,
            0);
        ConversationHistoryCursorStack.Clear();
    }

    private static void RefreshConversationHistoryWindowIfNeeded()
    {
        if (_conversationHistoryWindow == null
            || !_conversationHistoryWindow.activeSelf
            || _conversationHistoryLoadInFlight)
        {
            return;
        }

        if (_conversationHistoryRetryAt >= 0f)
        {
            if (Time.unscaledTime < _conversationHistoryRetryAt)
                return;
            _conversationHistoryRetryAt = -1f;
            LoadConversationHistoryPage();
            return;
        }

        if (_conversationHistoryPageNumber != 1
            || _conversationHistoryCursor.Length != 0
            || Interlocked.Exchange(
                ref _conversationHistoryRefreshRequested,
                0) == 0)
        {
            return;
        }

        LoadConversationHistoryPage();
    }

    private static void CancelConversationHistoryLoad()
    {
        Interlocked.Increment(ref _conversationHistoryLoadGeneration);
        _conversationHistoryLoadInFlight = false;
        var cancellation = _conversationHistoryLoadCancellation;
        _conversationHistoryLoadCancellation = null;
        if (cancellation == null)
            return;
        try
        {
            cancellation.Cancel();
        }
        catch (ObjectDisposedException)
        {
        }
        cancellation.Dispose();
    }

    private static void ExcludeTaskbarFromConversationHistoryWindowRegion()
    {
        RestoreConversationHistoryWindowRegion();
        if (!OperatingSystem.IsWindows())
            return;
        IntPtr fullRegion = IntPtr.Zero;
        IntPtr taskbarRegion = IntPtr.Zero;
        IntPtr existingRegion = IntPtr.Zero;
        try
        {
            var appWindow = PlatformService.Current.GetAppWindowHandle();
            if (appWindow == IntPtr.Zero)
                return;
            var taskbarWindow = FindConversationHistoryWindow("Shell_TrayWnd", null);
            if (taskbarWindow == IntPtr.Zero
                || !GetConversationHistoryWindowRect(appWindow, out var appBounds)
                || !GetConversationHistoryWindowRect(taskbarWindow, out var taskbarBounds))
                return;
            var intersectionLeft = Math.Max(appBounds.Left, taskbarBounds.Left);
            var intersectionTop = Math.Max(appBounds.Top, taskbarBounds.Top);
            var intersectionRight = Math.Min(appBounds.Right, taskbarBounds.Right);
            var intersectionBottom = Math.Min(appBounds.Bottom, taskbarBounds.Bottom);
            if (intersectionRight <= intersectionLeft || intersectionBottom <= intersectionTop)
                return;

            // Do not overwrite an unknown region established by the original game or
            // another mod. The stock transparent Lilith window has no custom region.
            existingRegion = CreateConversationHistoryRectRegion(0, 0, 1, 1);
            if (existingRegion == IntPtr.Zero
                || GetConversationHistoryWindowRegion(appWindow, existingRegion) != 0)
            {
                Plugin.PluginLog.LogWarning("Conversation history left an existing game window region unchanged; the visible taskbar may remain non-interactive.");
                return;
            }

            var width = Math.Max(1, appBounds.Right - appBounds.Left);
            var height = Math.Max(1, appBounds.Bottom - appBounds.Top);
            fullRegion = CreateConversationHistoryRectRegion(0, 0, width, height);
            taskbarRegion = CreateConversationHistoryRectRegion(
                intersectionLeft - appBounds.Left,
                intersectionTop - appBounds.Top,
                intersectionRight - appBounds.Left,
                intersectionBottom - appBounds.Top);
            const int regionDifference = 4;
            if (fullRegion == IntPtr.Zero
                || taskbarRegion == IntPtr.Zero
                || CombineConversationHistoryWindowRegion(
                    fullRegion,
                    fullRegion,
                    taskbarRegion,
                    regionDifference) == 0
                || SetConversationHistoryWindowRegion(appWindow, fullRegion, true) == 0)
                return;

            // Windows owns fullRegion after a successful SetWindowRgn call.
            fullRegion = IntPtr.Zero;
            _conversationHistoryWindowRegionHandle = appWindow;
            _conversationHistoryWindowRegionApplied = true;
            Plugin.PluginLog.LogInfo("Conversation history excluded the visible Windows taskbar from the game window hit-test region.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not exclude the visible taskbar from the history window: {exception.Message}");
        }
        finally
        {
            if (existingRegion != IntPtr.Zero)
                DeleteConversationHistoryRegion(existingRegion);
            if (taskbarRegion != IntPtr.Zero)
                DeleteConversationHistoryRegion(taskbarRegion);
            if (fullRegion != IntPtr.Zero)
                DeleteConversationHistoryRegion(fullRegion);
        }
    }

    private static void RestoreConversationHistoryWindowRegion()
    {
        var appWindow = _conversationHistoryWindowRegionHandle;
        var shouldRestore = _conversationHistoryWindowRegionApplied
            && appWindow != IntPtr.Zero;
        _conversationHistoryWindowRegionApplied = false;
        _conversationHistoryWindowRegionHandle = IntPtr.Zero;
        if (!shouldRestore || !OperatingSystem.IsWindows())
            return;
        try
        {
            SetConversationHistoryWindowRegion(appWindow, IntPtr.Zero, true);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not restore the full desktop-pet window region after closing history: {exception.Message}");
        }
    }

    private static void LoadConversationHistoryPage()
    {
        if (_conversationHistoryBody == null)
            return;
        CancelConversationHistoryLoad();
        var loadGeneration = Interlocked.Increment(
            ref _conversationHistoryLoadGeneration);
        var cursor = _conversationHistoryCursor;
        var pageNumber = _conversationHistoryPageNumber;
        if (pageNumber == 1 && cursor.Length == 0)
        {
            // This request starts after every native commit observed so far.
            // A later commit races by setting the flag again and therefore
            // receives one subsequent fresh first-page snapshot.
            Interlocked.Exchange(
                ref _conversationHistoryRefreshRequested,
                0);
        }
        var pageSize = Math.Clamp(
            Plugin.ConversationHistoryPageSize.Value,
            10,
            LilithGameBridgeProtocol.MaximumHistoryPageSize);
        var cancellation = new CancellationTokenSource(
            TimeSpan.FromSeconds(15));
        _conversationHistoryLoadCancellation = cancellation;
        _conversationHistoryLoadInFlight = true;
        _conversationHistoryPage = null;
        _conversationHistoryBody.text = ApiKeyText(
            "正在讀取對話……",
            "正在读取对话……",
            "会話を読み込んでいるよ……",
            "Loading conversation…");
        ResizeConversationHistoryContent();
        UpdateConversationHistoryButtonState();
        _ = LoadConversationHistoryPageAsync(
            loadGeneration,
            cursor,
            pageNumber,
            pageSize,
            cancellation.Token);
    }

    private static async Task LoadConversationHistoryPageAsync(
        long loadGeneration,
        string cursor,
        int pageNumber,
        int pageSize,
        CancellationToken cancellationToken)
    {
        try
        {
            var response = await GameHermesClient.ReadHistoryAsync(
                    Guid.NewGuid(),
                    cursor,
                    pageSize,
                    cancellationToken)
                .ConfigureAwait(false);
            PendingGameHermesHistoryLoads.Enqueue(
                new PendingGameHermesHistoryLoad(
                    loadGeneration,
                    cursor,
                    pageNumber,
                    response,
                    string.Empty));
        }
        catch (Exception exception)
        {
            PendingGameHermesHistoryLoads.Enqueue(
                new PendingGameHermesHistoryLoad(
                    loadGeneration,
                    cursor,
                    pageNumber,
                    response: null,
                    exception.GetType().Name));
        }
    }

    private static void EnsureGameHermesNotificationListener()
    {
        var displayLocale = ToGameHermesDisplayLocale(
            LilithGamePersonaLocaleProjector.Resolve(
                GetAgentTurnLocale()).DisplayLocale);
        var speechLocale = IsJapaneseVoiceMode()
            ? LilithGameBridgeSpeechLocale.Japanese
            : LilithGameBridgeSpeechLocale.Chinese;
        Volatile.Write(
            ref _gameHermesNotificationDisplayLocale,
            (int)displayLocale);
        Volatile.Write(
            ref _gameHermesNotificationSpeechLocale,
            (int)speechLocale);
        if (Interlocked.CompareExchange(
                ref _gameHermesNotificationListenerStarted,
                1,
                0) != 0)
        {
            return;
        }

        _ = RunGameHermesNotificationListenerAsync(
            GameHermesNotificationShutdown.Token);
    }

    private static async Task RunGameHermesNotificationListenerAsync(
        CancellationToken cancellationToken)
    {
        var generationId = Guid.Empty;
        long afterSequence = 0;
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var displayLocale = (LilithGameBridgeDisplayLocale)
                    Volatile.Read(
                        ref _gameHermesNotificationDisplayLocale);
                var speechLocale = (LilithGameBridgeSpeechLocale)
                    Volatile.Read(
                        ref _gameHermesNotificationSpeechLocale);
                using var requestTimeout =
                    CancellationTokenSource.CreateLinkedTokenSource(
                        cancellationToken);
                requestTimeout.CancelAfter(TimeSpan.FromSeconds(110));
                var response = await GameHermesClient.ReadNotificationsAsync(
                        Guid.NewGuid(),
                        afterSequence,
                        generationId == Guid.Empty
                            ? 0
                            : LilithGameBridgeProtocol
                                .MaximumNotificationWaitMilliseconds,
                        displayLocale,
                        speechLocale,
                        tailOnly: generationId == Guid.Empty,
                        requestTimeout.Token)
                    .ConfigureAwait(false);

                PlayerNameSync.ObserveRuntimeGeneration(response.GenerationId);
                ContinuationPresentation.ObserveGeneration(response.GenerationId, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
                if (generationId == Guid.Empty)
                {
                    // A game-process start subscribes at the current tail. Old
                    // presentation-only reports retained by a still-running
                    // Runtime must not replay when the player relaunches the
                    // game.
                    generationId = response.GenerationId;
                    afterSequence = response.LatestSequence;
                    Interlocked.Exchange(
                        ref _gameHermesNotificationFaultLogged,
                        0);
                    continue;
                }
                if (response.GenerationId != generationId)
                {
                    // Runtime generations own disjoint sequence spaces. Fetch
                    // the new generation from zero on the next exchange so a
                    // reminder that completed during backend recovery is not
                    // lost.
                    generationId = response.GenerationId;
                    afterSequence = 0;
                    Interlocked.Exchange(
                        ref _gameHermesNotificationFaultLogged,
                        0);
                    continue;
                }
                if ((int)displayLocale != Volatile.Read(
                        ref _gameHermesNotificationDisplayLocale)
                    || (int)speechLocale != Volatile.Read(
                        ref _gameHermesNotificationSpeechLocale))
                {
                    // The long poll was projected for a voice selection that
                    // changed while it waited. Do not advance the cursor; the
                    // same presentation entry will be requested again under
                    // the current display/speech pair.
                    continue;
                }
                if (!response.Succeeded)
                {
                    if (string.Equals(
                            response.Code,
                            "runtime.notification_cursor_expired",
                            StringComparison.Ordinal))
                    {
                        afterSequence = Math.Max(
                            0,
                            response.OldestAvailableSequence - 1);
                        continue;
                    }
                    if (string.Equals(
                            response.Code,
                            "runtime.notification_cursor_ahead",
                            StringComparison.Ordinal))
                    {
                        afterSequence = 0;
                        continue;
                    }
                    if (Interlocked.Exchange(ref _gameHermesNotificationFaultLogged, 1) == 0)
                        Plugin.PluginLog.LogInfo("Game Hermes notification deferred: code=" + response.Code
                            + ", after_sequence=" + afterSequence + ".");
                    throw new InvalidDataException(
                        "The game notification stream was rejected: "
                        + response.Code
                        + ".");
                }

                Interlocked.Exchange(
                    ref _gameHermesNotificationFaultLogged,
                    0);
                var queueFull = false;
                foreach (var entry in response.Entries)
                {
                    if (entry.Sequence <= afterSequence)
                        continue;
                    if (!TryQueueGameHermesNotification(entry))
                    {
                        queueFull = true;
                        break;
                    }
                    afterSequence = entry.Sequence;
                }
                if (queueFull)
                {
                    await Task.Delay(
                            TimeSpan.FromMilliseconds(250),
                            cancellationToken)
                        .ConfigureAwait(false);
                }
            }
            catch (OperationCanceledException)
                when (cancellationToken.IsCancellationRequested)
            {
                return;
            }
            catch (Exception exception)
            {
                if (Interlocked.Exchange(
                        ref _gameHermesNotificationFaultLogged,
                        1) == 0)
                {
                    Plugin.PluginLog.LogInfo(
                        "Game Hermes reminder listener is waiting for "
                        + "Runtime: "
                        + exception.GetType().Name
                        + ".");
                }
                try
                {
                    await Task.Delay(
                            TimeSpan.FromSeconds(2),
                            cancellationToken)
                        .ConfigureAwait(false);
                }
                catch (OperationCanceledException)
                    when (cancellationToken.IsCancellationRequested)
                {
                    return;
                }
            }
        }
    }

    private static bool TryQueueGameHermesNotification(
        LilithGameBridgeNotificationEntry entry)
    {
        var count = Interlocked.Increment(
            ref _pendingGameHermesNotificationCount);
        if (count > GameHermesNotificationQueueCapacity)
        {
            Interlocked.Decrement(
                ref _pendingGameHermesNotificationCount);
            return false;
        }
        try
        {
            PendingGameHermesNotifications.Enqueue(entry);
            return true;
        }
        catch
        {
            Interlocked.Decrement(
                ref _pendingGameHermesNotificationCount);
            throw;
        }
    }

    private static void ProcessPendingGameHermesNotifications()
    {
        // Existing update tick only: a dropped control receipt must not lease
        // the shared batch forever. No provider request or dialogue is created.
        NativeMiniGameEvents.Expire(Environment.TickCount64);
        while (PendingGameHermesNotifications.TryDequeue(out var entry))
        {
            Interlocked.Decrement(
                ref _pendingGameHermesNotificationCount);
            try
            {
                if (entry.Type == LilithGameBridgeProtocol.MiniGameEventsSettledEventType)
                {
                    if (entry.MiniGameEventId is { } eventId)
                        NativeMiniGameEvents.Settle(eventId, entry.MiniGameEventReceipt);
                    continue; // control only: no history refresh, speech or interaction signal
                }
                if (string.Equals(
                        entry.Type,
                        LilithGameBridgeProtocol
                            .ForegroundProactivePlayerReplyEventType,
                        StringComparison.Ordinal))
                {
                    // Runtime emits this only for a durable Control Center
                    // user turn on the exact hidden game session. It carries
                    // no display or speech content.
                    RecordForegroundProactivePlayerTurn();
                    continue;
                }
                var foregroundProactive = string.Equals(
                    entry.Type,
                    LilithGameBridgeProtocol.ForegroundProactiveEventType,
                    StringComparison.Ordinal);
                ContinuationPresentationTicket? presentation = null;
                if (entry.Continuation is not null
                    && (!EffectiveD046ProactiveDialogueEnabled()
                        || !ContinuationPresentation.TryAdmit(entry.Continuation,
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(), out presentation)))
                    continue;
                if (foregroundProactive)
                {
                    var lifecycle = _foregroundProactiveStateMachine?
                        .GetSnapshot();
                    if (!EffectiveD046ProactiveDialogueEnabled()
                        || lifecycle == null
                        || lifecycle.State is ForegroundProactiveState.Disabled
                            or ForegroundProactiveState.Armed)
                    {
                        Plugin.PluginLog.LogInfo(
                            "Suppressed one retired foreground proactive "
                            + "presentation after player or switch priority.");
                        continue;
                    }
                    Interlocked.Exchange(
                        ref _conversationHistoryRefreshRequested,
                        1);
                }
                var message = entry.Succeeded
                    ? entry.Text
                    : ApiKeyText(
                        "排程未完成。" + entry.Text,
                        "排程未完成。" + entry.Text,
                        "予定は完了しなかったよ。" + entry.Text,
                        "The scheduled task did not complete. " + entry.Text);
                LocalTimers.Add(new LocalTimer
                {
                    Deadline = AgentLanguageRuntime.CreateDeadline(
                        TimeSpan.Zero),
                    Message = message,
                    SpeechMessage = entry.SpeechLocale
                            == (LilithGameBridgeSpeechLocale)
                                Volatile.Read(
                                    ref _gameHermesNotificationSpeechLocale)
                        ? entry.SpeechText
                        : string.Empty,
                    SpeechLocale = entry.SpeechLocale,
                    SpeechEmotion = entry.SpeechEmotion,
                    Continuation = presentation
                });
                Plugin.PluginLog.LogInfo(
                    "Queued one presentation-only Game Hermes reminder "
                    + "for main-thread delivery: sequence="
                    + entry.Sequence
                    + ".");
            }
            catch (Exception exception)
            {
                Plugin.PluginLog.LogWarning(
                    "A Game Hermes reminder could not enter the existing "
                    + "local timer publication rail: "
                    + exception.GetType().Name
                    + ".");
            }
        }
    }

    private static void ProcessPendingGameHermesHistoryLoads()
    {
        while (PendingGameHermesHistoryLoads.TryDequeue(out var pending))
        {
            if (pending.LoadGeneration
                    != Volatile.Read(ref _conversationHistoryLoadGeneration)
                || _conversationHistoryWindow == null
                || !_conversationHistoryWindow.activeSelf
                || !string.Equals(
                    pending.Cursor,
                    _conversationHistoryCursor,
                    StringComparison.Ordinal)
                || pending.PageNumber != _conversationHistoryPageNumber)
            {
                continue;
            }

            _conversationHistoryLoadInFlight = false;
            _conversationHistoryLoadCancellation?.Dispose();
            _conversationHistoryLoadCancellation = null;
            var page = pending.Response;
            if (page == null || !page.Succeeded)
            {
                _conversationHistoryPage = null;
                if (pending.PageNumber == 1
                    && pending.Cursor.Length == 0
                    && IsTransientConversationHistoryFailure(
                        page?.Code,
                        pending.FaultType)
                    && _conversationHistoryTransientRetryCount
                        < ConversationHistoryTransientRetryLimit)
                {
                    _conversationHistoryTransientRetryCount++;
                    _conversationHistoryRetryAt = Time.unscaledTime
                        + _conversationHistoryTransientRetryCount;
                    if (_conversationHistoryBody != null)
                    {
                        _conversationHistoryBody.text = ApiKeyText(
                            "正在重新連上對話紀錄……",
                            "正在重新连上对话记录……",
                            "会話履歴に再接続しているよ……",
                            "Reconnecting to conversation history…");
                        ResizeConversationHistoryContent();
                    }
                    Plugin.PluginLog.LogInfo(
                        "Canonical Hermes history will retry one transient first-page failure: attempt="
                        + _conversationHistoryTransientRetryCount
                        + ", fault="
                        + (page?.Code ?? pending.FaultType)
                        + ".");
                    UpdateConversationHistoryButtonState();
                    continue;
                }
                _conversationHistoryRetryAt = -1f;
                if (_conversationHistoryBody != null)
                {
                    _conversationHistoryBody.text = ApiKeyText(
                        "這一頁暫時讀不到。可以返回較新的頁面，或關閉後重新開啟再試一次。",
                        "这一页暂时读不到。可以返回较新的页面，或关闭后重新打开再试一次。",
                        "このページは今読み込めないみたい。新しいページへ戻るか、閉じて開き直してね。",
                        "This page is temporarily unavailable. Return to a newer page, or close and reopen it to retry.");
                    ResizeConversationHistoryContent();
                }
                Plugin.PluginLog.LogWarning(
                    "Could not read one canonical Hermes history page: fault="
                    + (page?.Code ?? pending.FaultType)
                    + ".");
                UpdateConversationHistoryButtonState();
                continue;
            }

            _conversationHistoryTransientRetryCount = 0;
            _conversationHistoryRetryAt = -1f;
            _conversationHistoryPage = page;
            RenderConversationHistoryPage(page);
        }
    }

    private static bool IsTransientConversationHistoryFailure(
        string? code,
        string faultType)
        => string.Equals(
                code,
                "runtime.game_bridge_failed",
                StringComparison.Ordinal)
            || string.Equals(
                code,
                "runtime.not_ready",
                StringComparison.Ordinal)
            || string.Equals(
                code,
                "runtime.voice_generation_restarting",
                StringComparison.Ordinal)
            || faultType is "TimeoutException"
                or "TaskCanceledException"
                or "OperationCanceledException"
                or "IOException"
                or "EndOfStreamException";

    private static void RenderConversationHistoryPage(
        LilithGameBridgeHistoryResponse page)
    {
        if (_conversationHistoryBody == null)
            return;
        const int maximumRenderedCharacters = 28_000;
        const int maximumCharactersPerEntry = 2_400;
        var builder = new StringBuilder(Math.Min(maximumRenderedCharacters, Math.Max(256, page.Entries.Count * 256)));
        foreach (var entry in page.Entries.Reverse())
        {
            var roleName = entry.Role == "user"
                ? ApiKeyText("你", "你", "あなた", "You")
                : ApiKeyText("莉莉絲", "莉莉丝", "リリス", "Lilith");
            var roleColor = entry.Role == "user" ? "#8EC5FF" : "#FFFFFF";
            var localTime = DateTimeOffset.FromUnixTimeMilliseconds(
                    entry.OccurredAtUnixTimeMilliseconds)
                .ToLocalTime()
                .ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
            var text = entry.Text.Length > maximumCharactersPerEntry
                ? entry.Text[..maximumCharactersPerEntry] + "…"
                : entry.Text;
            text = EscapeConversationHistoryRichText(text);
            var block = $"<color={roleColor}><b>{roleName}</b></color>  <color=#8A8A96>{localTime}</color>\n{text}\n\n";
            if (builder.Length + block.Length > maximumRenderedCharacters)
            {
                builder.Append(ApiKeyText(
                    "……本頁其餘內容仍保存在本機，請縮小每頁行數後查看。",
                    "……本页其余内容仍保存在本机，请缩小每页行数后查看。",
                    "……このページの残りも保存されているよ。表示件数を減らして見てね。",
                    "…The rest of this page remains stored locally. Reduce the page size to view it."));
                break;
            }
            builder.Append(block);
        }
        if (builder.Length == 0)
        {
            builder.Append(ApiKeyText(
                "這裡還沒有留下對話。",
                "这里还没有留下对话。",
                "ここには、まだ会話が残っていない。",
                "No conversations have been recorded here yet."));
        }
        _conversationHistoryBody.text = builder.ToString();
        ResizeConversationHistoryContent();
        if (_conversationHistoryFooter != null)
        {
            _conversationHistoryFooter.text = ApiKeyText(
                $"第 {_conversationHistoryPageNumber} 頁 · {page.Entries.Count} 筆 · Hermes 對話紀錄",
                $"第 {_conversationHistoryPageNumber} 页 · {page.Entries.Count} 条 · Hermes 对话记录",
                $"{_conversationHistoryPageNumber} ページ · {page.Entries.Count} 件 · Hermes 会話履歴",
                $"Page {_conversationHistoryPageNumber} · {page.Entries.Count} entries · Hermes history");
        }
        UpdateConversationHistoryButtonState();
    }

    private static string EscapeConversationHistoryRichText(string text)
        => text.Replace("<", "＜", StringComparison.Ordinal)
            .Replace(">", "＞", StringComparison.Ordinal);

    private static void ResizeConversationHistoryContent()
    {
        if (_conversationHistoryBody == null || _conversationHistoryScroll == null)
            return;
        var rect = _conversationHistoryBody.rectTransform;
        var width = Math.Max(240f, _conversationHistoryScroll.viewport.rect.width - 12f);
        var viewportHeight = Math.Max(120f, _conversationHistoryScroll.viewport.rect.height);
        var preferred = _conversationHistoryBody.GetPreferredValues(_conversationHistoryBody.text, width, 0f);
        rect.sizeDelta = new Vector2(0f, Math.Max(viewportHeight, preferred.y + 18f));
        rect.anchoredPosition = Vector2.zero;
        Canvas.ForceUpdateCanvases();
        _conversationHistoryScroll.StopMovement();
        _conversationHistoryScroll.verticalNormalizedPosition = 0f;
    }

    private static void ApplyConversationHistoryViewportLayout()
    {
        if (_conversationHistoryWindow == null)
            return;
        Canvas.ForceUpdateCanvases();
        var rootRect = _conversationHistoryWindow.GetComponent<RectTransform>();
        var layout = ConversationHistoryViewportLayout.Resolve(rootRect.rect.width);
        SetConversationHistoryHorizontalAnchors(
            _conversationHistoryTitle?.rectTransform,
            layout.ContentLeft,
            layout.TitleRight);
        SetConversationHistoryHorizontalAnchors(
            _conversationHistoryScroll?.GetComponent<RectTransform>(),
            layout.ContentLeft,
            layout.ContentRight);
        SetConversationHistoryHorizontalAnchors(
            _conversationHistoryNewerButton,
            layout.ContentLeft,
            layout.NewerButtonRight);
        SetConversationHistoryHorizontalAnchors(
            _conversationHistoryOlderButton,
            layout.OlderButtonLeft,
            layout.ContentRight);
        ApplyConversationHistoryCloseButtonLayout(layout);
        SetConversationHistoryHorizontalAnchors(
            _conversationHistoryFooter?.rectTransform,
            layout.FooterLeft,
            layout.FooterRight);
        ResizeConversationHistoryContent();
    }

    private static void ApplyConversationHistoryCloseButtonLayout(
        ConversationHistoryViewportLayout layout)
    {
        var rect = _conversationHistoryCloseButton;
        if (rect == null)
            return;
        // A fixed canvas-unit square aligned with the title, not a stretched
        // native bubble. The same rectangle remains the existing click target.
        var anchor = new Vector2(
            layout.ContentRight,
            ConversationHistoryViewportLayout.CloseButtonCenterY);
        rect.anchorMin = anchor;
        rect.anchorMax = anchor;
        rect.pivot = new Vector2(1f, 0.5f);
        rect.anchoredPosition = Vector2.zero;
        rect.sizeDelta = new Vector2(layout.CloseButtonSize, layout.CloseButtonSize);
        rect.localScale = Vector3.one;
        rect.localRotation = Quaternion.identity;
        var label = rect.GetComponentInChildren<TextMeshProUGUI>();
        if (label != null)
            label.fontSize = layout.CloseButtonFontSize;
    }

    private static void SetConversationHistoryHorizontalAnchors(
        RectTransform? rect,
        float left,
        float right)
    {
        if (rect == null)
            return;
        var anchorMin = rect.anchorMin;
        var anchorMax = rect.anchorMax;
        var offsetMin = rect.offsetMin;
        var offsetMax = rect.offsetMax;
        anchorMin.x = left;
        anchorMax.x = right;
        offsetMin.x = 0f;
        offsetMax.x = 0f;
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.offsetMin = offsetMin;
        rect.offsetMax = offsetMax;
    }

    private static void UpdateConversationHistoryWindowLocalization()
    {
        if (_conversationHistoryTitle != null)
        {
            _conversationHistoryTitle.text = ApiKeyText(
                "對話履歷  ·  過去、現在，與之後",
                "对话履历  ·  过去、现在，与之后",
                "会話履歴  ·  過去、現在、そしてこれから",
                "Conversation History  ·  past, present, and what comes next");
        }
    }

    private static void UpdateConversationHistoryButtonState()
    {
        SetConversationHistoryButtonState(
            _conversationHistoryNewerButton,
            !_conversationHistoryLoadInFlight
                && ConversationHistoryCursorStack.Count > 0);
        SetConversationHistoryButtonState(
            _conversationHistoryOlderButton,
            !_conversationHistoryLoadInFlight
                && _conversationHistoryPage?.HasMore == true);
        SetConversationHistoryButtonState(_conversationHistoryCloseButton, true);
    }

    private static void SetConversationHistoryButtonState(RectTransform? button, bool enabled)
    {
        if (button == null)
            return;
        var image = button.gameObject.GetComponent<Image>();
        if (image != null)
            image.color = enabled
                ? new Color(0.18f, 0.18f, 0.23f, 0.96f)
                : new Color(0.10f, 0.10f, 0.13f, 0.62f);
        var label = button.gameObject.GetComponentInChildren<TMP_Text>();
        if (label != null)
        {
            var color = label.color;
            color.a = enabled ? 1f : 0.36f;
            label.color = color;
        }
    }

    private static bool TryCreateConversationHistoryWindow()
    {
        try
        {
            var sourceUi = UnityEngine.Object.FindObjectOfType<DialogueBubbleUI>();
            var sourceText = sourceUi?.gameObject.GetComponentInChildren<TextMeshProUGUI>();
            if (sourceUi == null || sourceText == null)
            {
                Plugin.PluginLog.LogWarning("Conversation history window is waiting for the native dialogue UI.");
                return false;
            }
            _conversationHistoryWindow = new GameObject(
                "LilithConversationHistoryWindow",
                Il2CppType.Of<RectTransform>(),
                Il2CppType.Of<Canvas>(),
                Il2CppType.Of<CanvasScaler>(),
                Il2CppType.Of<GraphicRaycaster>(),
                Il2CppType.Of<CanvasRenderer>(),
                Il2CppType.Of<Image>(),
                Il2CppType.Of<CanvasGroup>());
            // DialogueBubbleUI belongs to a world/character-following canvas. Parenting
            // the history window anywhere in that hierarchy makes the whole overlay move
            // when Lilith walks or is thrown. A dedicated screen-space canvas keeps the
            // archive fixed to the monitor regardless of character or camera transforms.
            _conversationHistoryWindow.transform.SetParent(null, false);
            var overlayCanvas = _conversationHistoryWindow.GetComponent<Canvas>();
            overlayCanvas.renderMode = RenderMode.ScreenSpaceOverlay;
            overlayCanvas.overrideSorting = true;
            overlayCanvas.sortingOrder = 32000;
            overlayCanvas.pixelPerfect = false;
            var overlayScaler = _conversationHistoryWindow.GetComponent<CanvasScaler>();
            overlayScaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            overlayScaler.referenceResolution = new Vector2(1920f, 1080f);
            overlayScaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            overlayScaler.matchWidthOrHeight = 0.5f;
            var rootRect = _conversationHistoryWindow.GetComponent<RectTransform>();
            rootRect.anchorMin = Vector2.zero;
            rootRect.anchorMax = Vector2.one;
            rootRect.pivot = new Vector2(0.5f, 0.5f);
            rootRect.anchoredPosition = Vector2.zero;
            rootRect.sizeDelta = Vector2.zero;
            rootRect.offsetMin = Vector2.zero;
            rootRect.offsetMax = Vector2.zero;
            var background = _conversationHistoryWindow.GetComponent<Image>();
            background.color = new Color(0.025f, 0.026f, 0.042f, 0.965f);
            background.raycastTarget = true;
            // The fullscreen backdrop is a solid quad. A decorative native
            // bubble retains transparent/curved borders even when sliced.
            background.sprite = null;
            background.overrideSprite = null;
            background.type = Image.Type.Simple;
            background.useSpriteMesh = false;
            background.preserveAspect = false;

            _conversationHistoryTitle = CreateConversationHistoryViewportText(
                sourceText,
                _conversationHistoryWindow.transform,
                "Title",
                new Vector2(0.035f, 0.89f),
                new Vector2(0.79f, 0.975f),
                26f,
                TextAlignmentOptions.MidlineLeft);

            var scrollObject = new GameObject(
                "HistoryScroll",
                Il2CppType.Of<RectTransform>(),
                Il2CppType.Of<ScrollRect>());
            scrollObject.transform.SetParent(_conversationHistoryWindow.transform, false);
            var scrollRectTransform = scrollObject.GetComponent<RectTransform>();
            scrollRectTransform.anchorMin = new Vector2(0.035f, 0.14f);
            scrollRectTransform.anchorMax = new Vector2(0.965f, 0.875f);
            scrollRectTransform.offsetMin = Vector2.zero;
            scrollRectTransform.offsetMax = Vector2.zero;

            var viewportObject = new GameObject(
                "Viewport",
                Il2CppType.Of<RectTransform>(),
                Il2CppType.Of<CanvasRenderer>(),
                Il2CppType.Of<Image>(),
                Il2CppType.Of<RectMask2D>());
            viewportObject.transform.SetParent(scrollObject.transform, false);
            var viewport = viewportObject.GetComponent<RectTransform>();
            viewport.anchorMin = Vector2.zero;
            viewport.anchorMax = Vector2.one;
            viewport.offsetMin = Vector2.zero;
            viewport.offsetMax = Vector2.zero;
            var viewportImage = viewportObject.GetComponent<Image>();
            viewportImage.color = new Color(0f, 0f, 0f, 0.01f);
            viewportImage.raycastTarget = true;

            _conversationHistoryBody = CreateConversationHistoryViewportText(
                sourceText,
                viewportObject.transform,
                "HistoryText",
                new Vector2(0f, 1f),
                new Vector2(1f, 1f),
                18f,
                TextAlignmentOptions.TopLeft) as TextMeshProUGUI;
            if (_conversationHistoryBody == null)
                throw new InvalidOperationException("Could not create the history body text.");
            _conversationHistoryBody.richText = true;
            _conversationHistoryBody.enableWordWrapping = true;
            _conversationHistoryBody.overflowMode = TextOverflowModes.Overflow;
            _conversationHistoryBody.maskable = true;
            _conversationHistoryBody.margin = new Vector4(12f, 8f, 16f, 10f);
            var bodyRect = _conversationHistoryBody.rectTransform;
            bodyRect.pivot = new Vector2(0.5f, 1f);
            bodyRect.anchoredPosition = Vector2.zero;
            bodyRect.sizeDelta = new Vector2(0f, 200f);

            _conversationHistoryScroll = scrollObject.GetComponent<ScrollRect>();
            _conversationHistoryScroll.viewport = viewport;
            _conversationHistoryScroll.content = bodyRect;
            _conversationHistoryScroll.horizontal = false;
            _conversationHistoryScroll.vertical = true;
            _conversationHistoryScroll.movementType = ScrollRect.MovementType.Clamped;
            _conversationHistoryScroll.scrollSensitivity = 36f;

            _conversationHistoryNewerButton = CreateConversationHistoryButton(
                sourceText,
                _conversationHistoryWindow.transform,
                "Newer",
                new Vector2(0.035f, 0.035f),
                new Vector2(0.22f, 0.115f),
                ApiKeyText("較新", "较新", "新しい方", "Newer"));
            _conversationHistoryOlderButton = CreateConversationHistoryButton(
                sourceText,
                _conversationHistoryWindow.transform,
                "Older",
                new Vector2(0.78f, 0.035f),
                new Vector2(0.965f, 0.115f),
                ApiKeyText("較舊", "较旧", "古い方", "Older"));
            _conversationHistoryCloseButton = CreateConversationHistoryCloseButton(
                sourceText,
                _conversationHistoryWindow.transform);
            _conversationHistoryFooter = CreateConversationHistoryViewportText(
                sourceText,
                _conversationHistoryWindow.transform,
                "Footer",
                new Vector2(0.24f, 0.035f),
                new Vector2(0.76f, 0.115f),
                14f,
                TextAlignmentOptions.Center);
            var canvasGroup = _conversationHistoryWindow.GetComponent<CanvasGroup>();
            canvasGroup.alpha = 1f;
            canvasGroup.interactable = true;
            canvasGroup.blocksRaycasts = true;
            _conversationHistoryWindow.SetActive(false);
            Plugin.PluginLog.LogInfo("Created paged rectangular conversation history window with compact close control; no transcript content was logged.");
            return true;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not create conversation history window: {exception}");
            if (_conversationHistoryWindow != null)
                UnityEngine.Object.Destroy(_conversationHistoryWindow);
            _conversationHistoryWindow = null;
            _conversationHistoryBody = null;
            _conversationHistoryTitle = null;
            _conversationHistoryFooter = null;
            _conversationHistoryScroll = null;
            _conversationHistoryNewerButton = null;
            _conversationHistoryOlderButton = null;
            _conversationHistoryCloseButton = null;
            return false;
        }
    }

    private static TextMeshProUGUI CreateConversationHistoryViewportText(
        TextMeshProUGUI template,
        Transform parent,
        string name,
        Vector2 anchorMin,
        Vector2 anchorMax,
        float fontSize,
        TextAlignmentOptions alignment)
    {
        var textObject = new GameObject(
            name,
            Il2CppType.Of<RectTransform>(),
            Il2CppType.Of<CanvasRenderer>(),
            Il2CppType.Of<TextMeshProUGUI>());
        textObject.transform.SetParent(parent, false);
        var text = textObject.GetComponent<TextMeshProUGUI>();
        text.font = template.font;
        text.fontSharedMaterial = template.fontSharedMaterial;
        text.text = string.Empty;
        text.fontSize = fontSize;
        text.alignment = alignment;
        text.richText = true;
        text.enableWordWrapping = true;
        text.overflowMode = TextOverflowModes.Overflow;
        text.margin = Vector4.zero;
        text.raycastTarget = false;
        text.color = Color.white;
        var rect = text.rectTransform;
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.localScale = Vector3.one;
        rect.localRotation = Quaternion.identity;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.anchoredPosition = Vector2.zero;
        rect.sizeDelta = Vector2.zero;
        rect.offsetMin = Vector2.zero;
        rect.offsetMax = Vector2.zero;
        return text;
    }

    private static TMP_Text CreateConversationHistoryText(
        TextMeshProUGUI template,
        Transform parent,
        string name,
        Vector2 anchorMin,
        Vector2 anchorMax,
        float fontSize,
        TextAlignmentOptions alignment)
    {
        var clone = UnityEngine.Object.Instantiate(template.gameObject, parent);
        clone.name = name;
        var typewriter = clone.GetComponent<TypewriterEffect>();
        if (typewriter != null)
            typewriter.enabled = false;
        var text = clone.GetComponent<TextMeshProUGUI>();
        text.text = string.Empty;
        text.fontSize = fontSize;
        text.alignment = alignment;
        text.enableWordWrapping = true;
        text.overflowMode = TextOverflowModes.Overflow;
        text.raycastTarget = false;
        text.color = Color.white;
        var rect = text.rectTransform;
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.offsetMin = Vector2.zero;
        rect.offsetMax = Vector2.zero;
        return text;
    }

