    private static void EnqueueLivingContinuityPlayerReplyCancellation(
        PlayerTurnOperationHandle operation,
        PlayerTurnCancellationReason reason)
        => EnqueuePlayerTurnReply(
            operation,
            ApiKeyText(
                "這次回覆沒有安全完成，請再試一次。",
                "这次回复没有安全完成，请再试一次。",
                "今回の返答は安全に完了できなかったよ。もう一度試してね。",
                "This reply could not complete safely. Please try again."),
            string.Empty,
            PlayerTurnPublicationKind.FailureNotice,
            PlayerTurnTerminalDisposition.Cancelled,
            cancellationReason: reason);

    private static bool LivingPlayerReplyConfigurationMatches(
        long expectedGeneration,
        bool unifiedPromptRootRequired)
        => expectedGeneration > 0
            && Plugin.Effective(
                Plugin.LivingContinuityPlayerReplyEnabled.Value)
            && (!unifiedPromptRootRequired
                || Plugin.Effective(
                    Plugin
                        .LivingContinuityUnifiedPromptOwnershipEnabled
                        .Value))
            && expectedGeneration == Interlocked.Read(
                ref _livingContinuityPlayerReplyConfigurationGeneration);

    private static string CaptureLivingPlayerReplySituationFingerprint(
        CharacterRuntimeIdentity runtime,
        PoseContext poseContext)
    {
        var state = UnityEngine.Object.FindObjectOfType<
            LilithStateManager>();
        return LivingPromptHash.Of(
            string.Join(
                "|",
                runtime.RuntimeProfileId,
                runtime.RuntimeInstanceId,
                runtime.Generation.ToString(
                    CultureInfo.InvariantCulture),
                runtime.OrchestratorSessionId,
                runtime.OwnerIdentity,
                ((int)poseContext.MotionContext.Pose).ToString(
                    CultureInfo.InvariantCulture),
                poseContext.MotionContext.IsPajamas ? "1" : "0",
                state == null ? "missing" : "present",
                state?.IsDrag == true ? "1" : "0",
                state?.IsStateMachineLocked == true ? "1" : "0",
                state?.IsGround == true ? "1" : "0",
                state?.IsSleep == true ? "1" : "0",
                state?.IsLieDown == true ? "1" : "0",
                state != null && IsMotionVisualSitState(state)
                    ? "1"
                    : "0",
                _transcriptionInFlight ? "1" : "0",
                _microphoneRecording ? "1" : "0",
                _aiPagesAwaitingAdvance ? "1" : "0"));
    }

    private sealed class PlayerTurnPreparedProviderLifecycle
        : IPreparedProviderExecutionLifecycle
    {
        private readonly PlayerTurnOperationHandle _operation;
        private int _started;
        private int _completed;
        private string _providerRequestId = string.Empty;

        internal PlayerTurnPreparedProviderLifecycle(
            PlayerTurnOperationHandle operation)
        {
            _operation = operation
                ?? throw new ArgumentNullException(nameof(operation));
        }

        internal bool WasStarted => Volatile.Read(ref _started) != 0;

        public void OnProviderSendStarting(
            PreparedProviderExecutionRequest request)
        {
            if (request == null)
                throw new ArgumentNullException(nameof(request));
            MarkProviderStarting(
                request.ProviderRouteId,
                request.CorrelationId);
        }

        internal void MarkProviderStarting(
            string providerRouteId,
            string providerRequestId)
        {
            if (Interlocked.Exchange(ref _started, 1) != 0)
            {
                throw new InvalidOperationException(
                    "Player-turn Provider lifecycle started twice.");
            }
            _providerRequestId = providerRequestId;
            if (!PlayerTurnOperations.TryProviderStarted(
                    _operation,
                    providerRouteId,
                    providerRequestId))
            {
                throw new InvalidOperationException(
                    "Player-turn Provider start was stale or out of order.");
            }
        }

        internal PlayerTurnProviderCompletionReceipt
            MarkProviderCompletedWithReceipt(string responseFingerprint)
        {
            if (!WasStarted
                || Volatile.Read(ref _completed) != 0)
            {
                throw new InvalidOperationException(
                    "Player-turn Provider completion receipt was requested "
                    + "outside the single active completion boundary.");
            }
            if (!PlayerTurnOperations.TryProviderCompletedWithReceipt(
                    _operation,
                    _providerRequestId,
                    responseFingerprint,
                    out var receipt)
                || receipt == null)
            {
                throw new InvalidOperationException(
                    "Player-turn Provider completion receipt was stale or "
                    + "mismatched.");
            }
            if (Interlocked.Exchange(ref _completed, 1) != 0)
            {
                throw new InvalidOperationException(
                    "Player-turn Provider completion was consumed twice.");
            }
            return receipt;
        }

        internal void MarkProviderCompletedIfStarted()
        {
            if (!WasStarted
                || Interlocked.Exchange(ref _completed, 1) != 0)
            {
                return;
            }
            if (!PlayerTurnOperations.TryProviderCompleted(
                    _operation,
                    _providerRequestId))
            {
                if (!PlayerTurnOperations.IsActive(_operation))
                    return;
                throw new InvalidOperationException(
                    "Player-turn Provider completion was stale or mismatched.");
            }
        }
    }






    private static PreparedProviderRuntimeBinding
        CreateLivingPreparedProviderBinding(
            PreparedProviderExecutionRequest request)
    {
        if (request == null)
            throw new ArgumentNullException(nameof(request));
        return request.Route switch
        {
            PreparedProviderRoute.Gemini =>
                PreparedProviderRuntimeBinding.Gemini(
                    new Uri(
                        "https://generativelanguage.googleapis.com/",
                        UriKind.Absolute),
                    Plugin.GeminiModel.Value.Trim(),
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.GeminiApiKey).Trim()),
            PreparedProviderRoute.Qwen =>
                CreateLivingQwenPreparedProviderBinding(),
            PreparedProviderRoute.OpenAI =>
                PreparedProviderRuntimeBinding.Chat(
                    PreparedProviderRoute.OpenAI,
                    new Uri(
                        "https://api.openai.com/v1/chat/completions",
                        UriKind.Absolute),
                    Plugin.OpenAiModel.Value.Trim(),
                    PreparedProviderAuthentication.Bearer,
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.OpenAiApiKey).Trim()),
            PreparedProviderRoute.DeepSeek =>
                PreparedProviderRuntimeBinding.Chat(
                    PreparedProviderRoute.DeepSeek,
                    new Uri(
                        "https://api.deepseek.com/chat/completions",
                        UriKind.Absolute),
                    Plugin.DeepSeekModel.Value.Trim(),
                    PreparedProviderAuthentication.Bearer,
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.DeepSeekApiKey).Trim()),
            _ => throw new InvalidOperationException(
                "D-026 provider route has no runtime binding.")
        };
    }

    private static PreparedProviderRuntimeBinding
        CreateLivingQwenPreparedProviderBinding()
    {
        var endpoint = new Uri(
            NormalizeQwenBaseUrl(Plugin.QwenBaseUrl.Value)
            + "/responses",
            UriKind.Absolute);
        var credential = Plugin.RetiredLegacyPlaintextProviderCredential(
            Plugin.QwenApiKey).Trim();
        var authentication =
            endpoint.IsLoopback && credential.Length == 0
                ? PreparedProviderAuthentication.None
                : PreparedProviderAuthentication.Bearer;
        return PreparedProviderRuntimeBinding.Responses(
            PreparedProviderRoute.Qwen,
            endpoint,
            Plugin.QwenModel.Value.Trim(),
            authentication,
            credential);
    }

    private static void ObserveD031ProviderRuntimeStageE(
        string activeProvider,
        string systemInstruction,
        string userText)
    {
        // Stage E Off equivalence starts here: no clock read, sequence,
        // allocation, hash, registry projection or log occurs while Off.
        if (!Plugin.ProviderRuntimeRegistryObserveEnabled.Value)
            return;

        try
        {
            var providerToken = activeProvider.ToLowerInvariant();
            var endpoint = activeProvider switch
            {
                "Gemini" =>
                    "https://generativelanguage.googleapis.com/v1beta/",
                "OpenAI" => "https://api.openai.com/v1/",
                "DeepSeek" => "https://api.deepseek.com/",
                "Qwen" => Plugin.QwenBaseUrl.Value.Trim(),
                _ => throw new InvalidOperationException(
                    "D-031 Stage E provider is not allowlisted.")
            };
            var model = activeProvider switch
            {
                "Gemini" => Plugin.GeminiModel.Value.Trim(),
                "OpenAI" => Plugin.OpenAiModel.Value.Trim(),
                "DeepSeek" => Plugin.DeepSeekModel.Value.Trim(),
                "Qwen" => Plugin.QwenModel.Value.Trim(),
                _ => throw new InvalidOperationException(
                    "D-031 Stage E provider model is unavailable.")
            };
            var protocol = activeProvider switch
            {
                "Gemini" => ProviderProtocolKind.GeminiGenerateContent,
                "OpenAI" => ProviderProtocolKind.OpenAiChatCompletions,
                "DeepSeek" => ProviderProtocolKind.OpenAiChatCompletions,
                "Qwen" => ProviderProtocolKind.OpenAiResponses,
                _ => throw new InvalidOperationException(
                    "D-031 Stage E provider protocol is unavailable.")
            };
            var now = DateTimeOffset.UtcNow;
            var runtimeIdentity = CurrentCharacterRuntimeIdentity();
            var configurationGeneration = Interlocked.Read(
                ref _d031ProviderRuntimeObserveConfigurationGeneration);
            var configurationFingerprint =
                ProviderRegistryCanonicalHash.Of(
                    "D031/STAGE-E-LIVE-CONFIGURATION/1",
                    activeProvider,
                    Plugin.GeminiModel.Value.Trim(),
                    Plugin.OpenAiModel.Value.Trim(),
                    Plugin.DeepSeekModel.Value.Trim(),
                    Plugin.QwenModel.Value.Trim(),
                    Plugin.QwenBaseUrl.Value.Trim(),
                    string.IsNullOrWhiteSpace(
                        Plugin.RetiredLegacyPlaintextProviderCredential(
                            Plugin.GeminiApiKey))
                        ? "0"
                        : "1",
                    string.IsNullOrWhiteSpace(
                        Plugin.RetiredLegacyPlaintextProviderCredential(
                            Plugin.OpenAiApiKey))
                        ? "0"
                        : "1",
                    string.IsNullOrWhiteSpace(
                        Plugin.RetiredLegacyPlaintextProviderCredential(
                            Plugin.DeepSeekApiKey))
                        ? "0"
                        : "1",
                    string.IsNullOrWhiteSpace(
                        Plugin.RetiredLegacyPlaintextProviderCredential(
                            Plugin.QwenApiKey))
                        ? "0"
                        : "1");
            D031ProviderRuntimeObserve.Reconcile(
                D031ProviderRuntimeStageEConfiguration.Observe(
                    runtimeIdentity,
                    configurationGeneration,
                    configurationFingerprint));

            var sourceSequence = Interlocked.Increment(
                ref _d031ProviderRuntimeObserveSourceSequence);
            var requestFingerprint = LivingPromptHash.Of(userText);
            var promptFingerprint = LivingPromptHash.Of(systemInstruction);
            var legacyRoute = new D031ProviderLegacyRouteMetadata(
                providerToken,
                endpoint,
                model,
                protocol,
                configurationGeneration);
            var legacyExecution = new LegacyProviderExecutionSignature(
                LivingPromptHash.Of(endpoint),
                LivingPromptHash.Of(model),
                ProviderRegistryCanonicalHash.Of(
                    "D031/STAGE-E-REQUEST/1",
                    requestFingerprint,
                    promptFingerprint),
                LivingPromptHash.Of("pending-completion"),
                providerCallCount: 0,
                rngCursor: 0,
                timerTicks: 0,
                sourceSequence);
            var registryInput = new LegacyProviderRegistryInput(
                migrationGateEnabled: true,
                activeProvider,
                Plugin.GeminiModel.Value.Trim(),
                Plugin.OpenAiModel.Value.Trim(),
                Plugin.DeepSeekModel.Value.Trim(),
                Plugin.QwenModel.Value.Trim(),
                Plugin.QwenBaseUrl.Value.Trim(),
                !string.IsNullOrWhiteSpace(
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.GeminiApiKey)),
                !string.IsNullOrWhiteSpace(
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.OpenAiApiKey)),
                !string.IsNullOrWhiteSpace(
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.DeepSeekApiKey)),
                !string.IsNullOrWhiteSpace(
                    Plugin.RetiredLegacyPlaintextProviderCredential(
                        Plugin.QwenApiKey)),
                configurationGeneration,
                legacyExecution);
            var opportunity = new D031ProviderRuntimeStageEOpportunity(
                "d031-stage-e-" + sourceSequence.ToString(
                    CultureInfo.InvariantCulture),
                "player-reply",
                requestFingerprint,
                promptFingerprint,
                legacyRoute,
                runtimeIdentity,
                configurationGeneration,
                configurationFingerprint,
                now,
                now.AddSeconds(8));
            var result = D031ProviderRuntimeObserve.Observe(
                opportunity,
                registryInput,
                now);

            // This result is diagnostic only. Stage E intentionally never
            // branches reply execution, suppresses Legacy, or calls Registry.
            Plugin.PluginLog.LogInfo(
                "D-031 Stage E route observation admission="
                + result.Admission
                + ", comparison="
                + (result.Observation?.Comparison.ToString() ?? "-")
                + ", owner="
                + (result.Observation?.Ownership.ToString() ?? "-")
                + ", legacy="
                + (result.Observation?.LegacyDisposition.ToString() ?? "-")
                + "; providerCalls=0, completionDeliveries=0, "
                + "promptWrites=0, behaviorInfluence=0.");
        }
        catch (Exception exception)
        {
            D031ProviderRuntimeObserve.StopByFault();
            Plugin.PluginLog.LogWarning(
                "D-031 Stage E route observation stopped fail-closed after "
                + "a redacted "
                + exception.GetType().Name
                + " fault; Legacy reply behavior remains unchanged.");
        }
    }

    internal static D031ProviderRuntimeStageESnapshot
        GetD031ProviderRuntimeStageESnapshot()
        => D031ProviderRuntimeObserve.GetSnapshot();

    internal static D031ProviderRuntimeStageFGeminiSnapshot
        GetD031ProviderRuntimeStageFGeminiSnapshot()
        => D031ProviderRuntimeGeminiMigration.GetSnapshot();

    private static async Task RequestWorkbenchProviderAsync(
        WorkbenchProviderBinding binding,
        PlayerTurnOperationHandle operation,
        string providerInput,
        string systemInstruction,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        LocalActionGoal admittedActionGoal,
        LocalOpenTargetKind admittedOpenTargetKind,
        string admittedExpectedOpenLeaf,
        string admittedExpectedSemanticTarget,
        HostEffectTargetDescriptor? admittedHostEffectTarget,
        long admittedPermissionRevision,
        HostApplicationPreObservation? hostApplicationObservation,
        D045CodexTaskPlan codexTaskPlan,
        D045AgentToolManifest toolManifest)
    {
        var activeRequest = GetActiveWorkbenchRequest(operation);
        var replyUserText = activeRequest?.UserText ?? providerInput;
        var attachments = activeRequest?.Attachments
            ?? Array.Empty<D045WorkbenchLiveAttachment>();
        var replyPoseContext = activeRequest == null
            ? poseContext
            : PoseContext.Default;
        var replyJapaneseVoiceMode = activeRequest == null
            && japaneseVoiceMode;
        var localActionGoal = admittedActionGoal;
        var explicitLocalAction =
            localActionGoal != LocalActionGoal.None;
        if (explicitLocalAction || HasAnyHarnessPermission())
        {
            var session = new WorkbenchProviderAgentSession
            {
                Binding = binding,
                Operation = operation,
                UserText = replyUserText,
                SystemInstruction = systemInstruction,
                ProviderInput = providerInput,
                Attachments = attachments,
                PoseContext = replyPoseContext,
                JapaneseVoiceMode = replyJapaneseVoiceMode,
                ExplicitLocalAction = explicitLocalAction,
                ActionGoal = localActionGoal,
                OpenTargetKind = admittedOpenTargetKind,
                ExpectedOpenLeaf = admittedExpectedOpenLeaf,
                ExpectedSemanticTarget = admittedExpectedSemanticTarget,
                HostEffectTarget = admittedHostEffectTarget,
                PermissionRevision = admittedPermissionRevision,
                HostApplicationObservation = hostApplicationObservation,
                CodexTaskPlan = codexTaskPlan,
                ToolManifest = toolManifest,
                Messages = BuildWorkbenchProviderAgentMessages(
                    binding.Protocol,
                    providerInput,
                    attachments)
            };
            try
            {
                await SendWorkbenchProviderAgentRequestAsync(session)
                    .ConfigureAwait(false);
            }
            catch (Exception exception) when (explicitLocalAction)
            {
                LogSanitizedWorkbenchProviderAgentFailure(
                    "initial-agent-request",
                    binding,
                    exception);
                if (!CompleteVerifiedGoalFinalization(
                        session.CaptureAgentLoop(),
                        string.Empty,
                        session.UserText,
                        session.PoseContext,
                        session.JapaneseVoiceMode,
                        session.Operation))
                {
                    CompleteAgentTaskStop(
                        session.CaptureAgentLoop(),
                        session.UserText,
                        session.PoseContext,
                        session.JapaneseVoiceMode,
                        session.Operation,
                        D045AgentTaskStopReason
                            .ProviderFaultedBeforeVerification,
                        "The Workbench provider faulted before every required "
                            + "receipt was verified.",
                        session.ActionGoal);
                }
            }
            return;
        }
        var payload = BuildWorkbenchProviderPayload(
            binding,
            systemInstruction,
            providerInput,
            attachments);
        using var request = new HttpRequestMessage(HttpMethod.Post, binding.Url);
        ApplyWorkbenchAuthentication(request, binding);
        request.Headers.Accept.Add(
            new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue(
                "application/json"));
        request.Content = new StringContent(
            JsonSerializer.Serialize(payload),
            Encoding.UTF8,
            "application/json");
        var lifecycle = new PlayerTurnPreparedProviderLifecycle(operation);
        lifecycle.MarkProviderStarting(
            binding.RouteToken,
            operation.OperationId + "-workbench-provider-1");
        string responseBody;
        try
        {
            using var response = await Http.SendAsync(request).ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    binding.DisplayName
                    + " HTTP "
                    + ((int)response.StatusCode).ToString(
                        CultureInfo.InvariantCulture));
            }
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }

        using var document = JsonDocument.Parse(responseBody);
        var reply = ExtractWorkbenchProviderText(
            binding.Protocol,
            document.RootElement);
        if (string.IsNullOrWhiteSpace(reply))
            throw new InvalidDataException("The selected model returned no text.");
        CompleteAiReply(
            reply,
            replyUserText,
            replyPoseContext,
            replyJapaneseVoiceMode,
            operation);
    }

    private static List<object> BuildWorkbenchProviderAgentMessages(
        ProviderControlProtocol protocol,
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
    {
        if (protocol == ProviderControlProtocol.OpenAiResponses)
        {
            return new List<object>
            {
                new
                {
                    role = "user",
                    content = BuildWorkbenchOpenAiResponsesInput(
                        providerInput,
                        attachments)
                }
            };
        }
        if (protocol == ProviderControlProtocol.AnthropicMessages)
        {
            return new List<object>
            {
                new
                {
                    role = "user",
                    content = BuildWorkbenchAnthropicContent(
                        providerInput,
                        attachments)
                }
            };
        }
        if (protocol == ProviderControlProtocol.OllamaNativeChat)
        {
            return new List<object>
            {
                new
                {
                    role = "user",
                    content = providerInput,
                    images = attachments.Select(value => value.DataBase64).ToArray()
                }
            };
        }
        return new List<object>
        {
            new
            {
                role = "user",
                content = attachments.Count == 0
                    ? (object)providerInput
                    : BuildWorkbenchOpenAiInput(providerInput, attachments)
            }
        };
    }

    private static async Task SendWorkbenchProviderAgentRequestAsync(
        WorkbenchProviderAgentSession session)
    {
        var agentLoop = RunSanitizedWorkbenchProviderStage(
            "capture-agent-loop",
            session.CaptureAgentLoop);
        var finalizingVerifiedGoal =
            agentLoop.IsFinalizingVerifiedGoal;
        if (TryConsumeAgentOperationCancellation(
                session.Operation,
                out var operationCancellation))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentOperationCancellation(
                session.Operation,
                operationCancellation);
            return;
        }
        CancellationTokenSource? createdAgentDeadline = null;
        if ((session.ExplicitLocalAction || session.ToolRounds > 0)
            && !agentLoop
                .TryCreateDeadlineCancellationSource(
                    out createdAgentDeadline,
                    out var deadlineReason))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                InferAgentTaskStopReason(deadlineReason),
                deadlineReason,
                session.ActionGoal);
            return;
        }
        using var agentDeadline = createdAgentDeadline;
        var agentCancellationToken = agentDeadline?.Token
            ?? CancellationToken.None;
        var maximumTokens = session.Binding.HighReasoning ? 4096 : 2048;
        var systemInstruction = finalizingVerifiedGoal
            ? VerifiedGoalFinalizationInstruction(
                session.SystemInstruction,
                agentLoop)
            : session.SystemInstruction;
        var requiresHostApplicationLaunch =
            !finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && agentLoop.RequiresHostApplicationLaunch;
        if (!finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && !requiresHostApplicationLaunch)
        {
            systemInstruction = systemInstruction.Replace(
                HostPreObservedApplicationContinuationInstruction,
                HostVerifiedApplicationContinuationInstruction,
                StringComparison.Ordinal);
        }
        var payload = RunSanitizedWorkbenchProviderStage<object>(
            "build-agent-payload",
            () => finalizingVerifiedGoal
            ? session.Binding.Protocol switch
            {
                ProviderControlProtocol.OpenAiChatCompletions
                    or ProviderControlProtocol.OpenAiCompatibleChat => new
                    {
                        model = session.Binding.ModelId,
                        messages = new object[]
                            {
                                new
                                {
                                    role = "system",
                                    content = systemInstruction
                                }
                            }
                            .Concat(session.Messages)
                            .ToArray(),
                        max_tokens = maximumTokens
                    },
                ProviderControlProtocol.OpenAiResponses => new
                    {
                        model = session.Binding.ModelId,
                        instructions = systemInstruction,
                        input = session.Messages.ToArray(),
                        max_output_tokens = maximumTokens,
                        store = false
                    },
                ProviderControlProtocol.AnthropicMessages => new
                    {
                        model = session.Binding.ModelId,
                        system = systemInstruction,
                        max_tokens = maximumTokens,
                        messages = session.Messages.ToArray()
                    },
                ProviderControlProtocol.OllamaNativeChat => new
                    {
                        model = session.Binding.ModelId,
                        messages = new object[]
                            {
                                new
                                {
                                    role = "system",
                                    content = systemInstruction
                                }
                            }
                            .Concat(session.Messages)
                            .ToArray(),
                        stream = false,
                        options = new { num_predict = maximumTokens }
                    },
                _ => throw new InvalidOperationException(
                    "This Workbench provider does not expose tool calling.")
            }
            : session.Binding.Protocol switch
        {
            ProviderControlProtocol.OpenAiChatCompletions
                or ProviderControlProtocol.OpenAiCompatibleChat =>
                    BuildWorkbenchOpenAiChatAgentPayload(
                        session,
                        systemInstruction,
                        maximumTokens,
                        requiresHostApplicationLaunch),
            ProviderControlProtocol.OpenAiResponses => new
                {
                    model = session.Binding.ModelId,
                    instructions = systemInstruction,
                    input = session.Messages.ToArray(),
                    max_output_tokens = maximumTokens,
                    store = false,
                    tools = !requiresHostApplicationLaunch
                        ? BuildWorkbenchOpenAiResponsesHarnessTools(
                            session.ToolManifest)
                        : BuildWorkbenchOpenAiResponsesHostApplicationEffectTools(
                            session.HostApplicationObservation!),
                    tool_choice = session.ExplicitLocalAction
                        ? "required"
                        : "auto"
                },
            ProviderControlProtocol.AnthropicMessages => new
                {
                    model = session.Binding.ModelId,
                    system = systemInstruction,
                    max_tokens = maximumTokens,
                    messages = session.Messages.ToArray(),
                    tools = !requiresHostApplicationLaunch
                        ? BuildWorkbenchAnthropicHarnessTools(
                            session.ToolManifest)
                        : BuildWorkbenchAnthropicHostApplicationEffectTools(
                            session.HostApplicationObservation!),
                    tool_choice = new
                    {
                        type = session.ExplicitLocalAction
                            ? "any"
                            : "auto"
                    }
                },
            ProviderControlProtocol.OllamaNativeChat => new
                {
                    model = session.Binding.ModelId,
                    messages = new object[]
                        {
                            new
                            {
                                role = "system",
                                content = systemInstruction
                            }
                        }
                        .Concat(session.Messages)
                        .ToArray(),
                    stream = false,
                    tools = !requiresHostApplicationLaunch
                        ? BuildWorkbenchOpenAiHarnessTools(
                            session.ToolManifest)
                        : BuildWorkbenchOpenAiHostApplicationEffectTools(
                            session.HostApplicationObservation!),
                    options = new { num_predict = maximumTokens }
                },
            _ => throw new InvalidOperationException(
                "This Workbench provider does not expose tool calling.")
        });

        using var request = new HttpRequestMessage(
            HttpMethod.Post,
            session.Binding.Url);
        ApplyWorkbenchAuthentication(request, session.Binding);
        request.Content = new StringContent(
            RunSanitizedWorkbenchProviderStage(
                "serialize-agent-payload",
                () => JsonSerializer.Serialize(payload)),
            Encoding.UTF8,
            "application/json");
        var lifecycle = new PlayerTurnPreparedProviderLifecycle(
            session.Operation);
        lifecycle.MarkProviderStarting(
            session.Binding.RouteToken,
            session.Operation.OperationId
            + "-workbench-agent-"
            + Interlocked.Increment(ref session.ProviderRequestSequence)
                .ToString(CultureInfo.InvariantCulture));
        string responseBody;
        try
        {
            using var response = await Http.SendAsync(
                    request,
                    agentCancellationToken)
                .ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    session.Binding.DisplayName
                    + " HTTP "
                    + ((int)response.StatusCode).ToString(
                        CultureInfo.InvariantCulture));
            }
        }
        catch (OperationCanceledException)
            when (agentDeadline?.IsCancellationRequested == true)
        {
            if (TryConsumeAgentOperationCancellation(
                    session.Operation,
                    out var cancellationKind))
            {
                if (finalizingVerifiedGoal
                    && CompleteVerifiedGoalFinalization(
                        agentLoop,
                        string.Empty,
                        session.UserText,
                        session.PoseContext,
                        session.JapaneseVoiceMode,
                        session.Operation))
                {
                    return;
                }
                CompleteAgentOperationCancellation(
                    session.Operation,
                    cancellationKind);
                return;
            }
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.DeadlineExpired,
                "The host-owned local-agent deadline expired during the "
                    + "provider request.",
                session.ActionGoal);
            return;
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }

        using var document = RunSanitizedWorkbenchProviderStage(
            "parse-agent-response-json",
            () => JsonDocument.Parse(responseBody));
        string reply = string.Empty;
        object assistantMessage = null!;
        var calls = RunSanitizedWorkbenchProviderStage(
            "parse-agent-tool-calls",
            () => ParseWorkbenchProviderToolCalls(
                session.Binding.Protocol,
                session.Binding.ProviderKind,
                document.RootElement,
                out reply,
                out assistantMessage));
        if (finalizingVerifiedGoal)
        {
            CompleteVerifiedGoalFinalization(
                agentLoop,
                calls.Count == 0 ? reply : string.Empty,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation);
            return;
        }
        if (calls.Count == 0)
        {
            if (CompleteExplicitActionWithoutVerifiedReceipt(
                    session.ActionGoal,
                    session.CaptureAgentLoop(),
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAiReply(
                reply,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation);
            return;
        }
        if (assistantMessage is object[] responseItems)
            session.Messages.AddRange(responseItems);
        else
            session.Messages.Add(assistantMessage);
        PendingWorkbenchProviderToolBatches.Enqueue(
            new WorkbenchProviderToolBatch
            {
                Session = session,
                Calls = calls
            });
    }

    private static object BuildWorkbenchOpenAiChatAgentPayload(
        WorkbenchProviderAgentSession session,
        string systemInstruction,
        int maximumTokens,
        bool requiresHostApplicationLaunch)
    {
        var payload = new Dictionary<string, object?>
        {
            ["model"] = session.Binding.ModelId,
            ["messages"] = new object[]
                {
                    new
                    {
                        role = "system",
                        content = systemInstruction
                    }
                }
                .Concat(session.Messages)
                .ToArray(),
            ["max_tokens"] = maximumTokens,
            ["tools"] = !requiresHostApplicationLaunch
                ? BuildWorkbenchOpenAiHarnessTools(session.ToolManifest)
                : BuildWorkbenchOpenAiHostApplicationEffectTools(
                    session.HostApplicationObservation!)
        };

        // DeepSeek V4 thinking models reject the tool_choice request field.
        // Omitting it keeps tool calling enabled through the declared tools;
        // every returned call still passes the host-owned manifest, target,
        // permission and receipt gates before any effect can run.
        if (session.Binding.ProviderKind != ProviderControlKind.DeepSeek)
        {
            payload["tool_choice"] = session.ExplicitLocalAction
                ? "required"
                : "auto";
        }

        return payload;
    }

    private static void ProcessWorkbenchProviderToolBatches()
    {
        if (!PendingWorkbenchProviderToolBatches.TryDequeue(out var batch))
            return;
        var agentLoop = batch.Session.CaptureAgentLoop();
        if (!TryAdmitQueuedAgentToolBatch(
                agentLoop,
                batch.Session.Operation,
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.ActionGoal))
        {
            return;
        }
        try
        {
            var outcome = ExecuteBoundedAgentToolBatch(
                agentLoop,
                batch.Calls,
                batch.Session.ActionGoal);
            batch.Session.ToolRounds = agentLoop.Rounds;
            var directive = ObserveAgentToolBatch(
                agentLoop,
                batch.Session.ActionGoal,
                outcome);
            AppendWorkbenchProviderToolResults(
                batch.Session,
                outcome.Results);
            if (directive == D045AgentTaskDirective.FinalizeWithoutTools)
            {
                CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation);
                return;
            }
            if (directive == D045AgentTaskDirective.Ignore)
                return;
            if (directive == D045AgentTaskDirective.PublishUnverifiedStop)
            {
                CompleteAgentTaskStop(
                    agentLoop,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation,
                    outcome.StopReasonKind,
                    outcome.StopReason,
                    batch.Session.ActionGoal);
                return;
            }
            _ = ContinueWorkbenchProviderAgentRequestAsync(batch.Session);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError(
                "Workbench provider tool execution failed: " + exception);
            if (CompleteVerifiedGoalFinalization(
                    batch.Session.CaptureAgentLoop(),
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                batch.Session.CaptureAgentLoop(),
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.Operation,
                D045AgentTaskStopReason.ToolFailed,
                "The local tool batch faulted before every required receipt "
                    + "was verified.",
                batch.Session.ActionGoal);
        }
    }

    private static bool TryAdmitQueuedAgentToolBatch(
        AgentLoopBudget budget,
        PlayerTurnOperationHandle operation,
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        LocalActionGoal actionGoal)
    {
        // Once the host has verified the complete goal, that receipt truth
        // wins over a later cancellation or permission edit. Finalization is
        // deterministic and starts neither another provider call nor effect.
        if (budget.IsFinalizingVerifiedGoal)
        {
            CompleteVerifiedGoalFinalization(
                budget,
                string.Empty,
                userText,
                poseContext,
                japaneseVoiceMode,
                operation);
            return false;
        }

        if (TryConsumeAgentOperationCancellation(
                operation,
                out var operationCancellation))
        {
            CompleteAgentOperationCancellation(
                operation,
                operationCancellation);
            return false;
        }

        D045PermissionLoadResult permissionState;
        try
        {
            permissionState = LocalPermissionStore.Load();
        }
        catch (Exception exception) when (exception is IOException
            or UnauthorizedAccessException
            or InvalidDataException
            or InvalidOperationException
            or ArgumentException)
        {
            Plugin.PluginLog.LogWarning(
                "Queued local-agent admission could not read the permission "
                + "state; no tool or follow-up provider call was started: "
                + exception.GetType().Name);
            CompleteAgentTaskStop(
                budget,
                userText,
                poseContext,
                japaneseVoiceMode,
                operation,
                D045AgentTaskStopReason.PermissionStateUnavailable,
                "The exact admitted permission revision could not be read "
                    + "before the queued batch.",
                actionGoal);
            return false;
        }

        var snapshot = permissionState.Snapshot;
        if (!Enum.IsDefined(
                typeof(D045PermissionStoreDisposition),
                permissionState.Disposition)
            || permissionState.Disposition
                == D045PermissionStoreDisposition.InvalidDefaultOff
            || snapshot.SchemaVersion
                != D045PermissionControlSnapshot.CurrentSchemaVersion
            || snapshot.Revision <= 0
            || snapshot.Enabled is not
                { Length: D045PermissionControlSnapshot.ExactCapabilityCount }
            || snapshot.UpdatedUtc.Offset != TimeSpan.Zero
            || budget.AdmittedPermissionRevision <= 0)
        {
            CompleteAgentTaskStop(
                budget,
                userText,
                poseContext,
                japaneseVoiceMode,
                operation,
                D045AgentTaskStopReason.PermissionStateUnavailable,
                "The permission state was not structurally usable at queued "
                    + "batch admission.",
                actionGoal);
            return false;
        }

        if (snapshot.Revision != budget.AdmittedPermissionRevision)
        {
            Plugin.PluginLog.LogWarning(
                "Cancelled a queued local-agent batch because the exact "
                + "admitted permission revision changed; no tool or follow-up "
                + "provider call was started.");
            CompleteAgentTaskStop(
                budget,
                userText,
                poseContext,
                japaneseVoiceMode,
                operation,
                D045AgentTaskStopReason.RequiredPermissionRevoked,
                "Permission changed before this queued batch was admitted; "
                    + "no effect from the batch was dispatched.",
                actionGoal);
            return false;
        }

        return true;
    }

    private static AgentToolBatchOutcome ExecuteBoundedAgentToolBatch(
        AgentLoopBudget budget,
        IReadOnlyList<GeminiFunctionCallData> calls,
        LocalActionGoal actionGoal)
    {
        if (!budget.TryBeginRound(out var stopReason))
        {
            return AgentToolBatchOutcome.Stopped(
                calls.Select(call => (
                    Call: call,
                    Result: ToolResult(call, false, stopReason))),
                stopReason);
        }

        var results = new List<(
            GeminiFunctionCallData Call,
            GeminiToolResult Result)>(calls.Count);
        var mustStop = false;
        var goalSatisfied = false;
        var highRiskCallExecuted = false;
        var executedCall = false;
        var duplicateCall = false;
        var stopReasonKind = D045AgentTaskStopReason.None;
        for (var index = 0; index < calls.Count; index++)
        {
            var call = calls[index];
            GeminiToolResult result;
            if (index >= AgentLoopMaximumCallsPerRound)
            {
                result = ToolResult(
                    call,
                    false,
                    "This call was skipped because a single agent round may "
                    + "request at most eight local actions.");
            }
            else if (goalSatisfied)
            {
                result = ToolResult(
                    call,
                    false,
                    "This call was skipped because the host already verified "
                    + "every requested local effect for this turn. No later "
                    + "effect may run before the final response.");
            }
            else if (mustStop)
            {
                result = ToolResult(
                    call,
                    false,
                    "This call was skipped because the agent loop had already "
                    + "stopped after detecting no progress.");
            }
            else if (IsHighRiskAgentToolCall(call)
                && highRiskCallExecuted)
            {
                result = ToolResult(
                    call,
                    false,
                    "This call was skipped because a single agent round may "
                    + "execute at most one high-risk local capability. Ask "
                    + "for the next exact action after observing this round.");
            }
            else if (!IsAgentToolRelevantToRemainingGoals(
                call,
                budget.GetRemainingGoals(actionGoal),
                budget))
            {
                result = ToolResult(
                    call,
                    false,
                    AgentToolRelevanceFailureMessage(call, budget));
            }
            else if (!budget.TryAdmitCall(
                call,
                out var intentFingerprint,
                out var remainingExecutionTime,
                out stopReason))
            {
                result = ToolResult(call, false, stopReason);
                if (stopReason.Contains(
                        "immediately repeats",
                        StringComparison.OrdinalIgnoreCase))
                {
                    duplicateCall = true;
                }
                else
                {
                    mustStop = true;
                    stopReasonKind = InferAgentTaskStopReason(stopReason);
                }
            }
            else
            {
                executedCall = true;
                if (IsHighRiskAgentToolCall(call))
                    highRiskCallExecuted = true;
                result = string.Equals(
                        call.Name,
                        "observe_local_target",
                        StringComparison.Ordinal)
                    ? ExecuteSemanticObservationTool(
                        call,
                        budget,
                        budget.GetRemainingGoals(actionGoal))
                    : ExecuteGeminiComputerTool(
                    call,
                    remainingExecutionTime,
                    budget.RequiredOpenTargetKind,
                    budget.ExpectedOpenLeaf,
                    budget);
                if (budget.RecordResult(intentFingerprint, result))
                {
                    stopReason = "The same local-tool intent returned the "
                        + "same failed receipt again and made no new progress.";
                    mustStop = true;
                    stopReasonKind =
                        D045AgentTaskStopReason.RepeatedNoProgress;
                }
                if (result.OutcomeReason
                    == D045HarnessOutcomeReason.PermissionChangedAfterAttempt)
                {
                    stopReason = "Permission changed after an effect may have "
                        + "been applied; automatic retry is forbidden.";
                    mustStop = true;
                    stopReasonKind = D045AgentTaskStopReason.ToolFailed;
                }
                else if (result.EffectPossiblyApplied)
                {
                    stopReason = "The Harness could not verify the effect after "
                        + "it may have been applied; automatic retry is forbidden.";
                    mustStop = true;
                    stopReasonKind = HarnessFailureStopReason(result);
                }
                else if (result.HasHarnessReceipt
                    && !result.Verified
                    && !result.RetryAllowed)
                {
                    stopReason = "The Harness returned a non-retryable "
                        + result.OutcomeReason + " result.";
                    mustStop = true;
                    stopReasonKind = HarnessFailureStopReason(result);
                }
                else if (!result.HasHarnessReceipt
                    && result.OutcomeReason
                        == D045HarnessOutcomeReason.InvalidRequest
                    && string.Equals(
                        result.ObservationFailure,
                        "semantic_target_reference_rejected",
                        StringComparison.Ordinal))
                {
                    stopReason = "The opaque local target reference was invalid, "
                        + "expired, already consumed, or no longer matched the "
                        + "current permission authority.";
                    mustStop = true;
                    stopReasonKind = D045AgentTaskStopReason.GoalIncomplete;
                }
                else if (D045SemanticObservationFailureLifecycle
                    .TryClassifyTerminalFailure(
                        result.IsSemanticObservation,
                        result.Success,
                        result.OutcomeReason,
                        out var semanticStopReason))
                {
                    stopReason = semanticStopReason
                        == D045AgentTaskStopReason.TargetAmbiguous
                            ? "More than one distinct local target matched the player request; clarification is required."
                            : "No local target matched the exact player request.";
                    mustStop = true;
                    stopReasonKind = semanticStopReason;
                }
                goalSatisfied = actionGoal != LocalActionGoal.None
                    && budget.HasVerifiedHarnessReceiptFor(actionGoal);
            }
            results.Add((call, result));
        }

        if (!mustStop && duplicateCall && !executedCall && !goalSatisfied)
        {
            mustStop = true;
            stopReason = "Every admissible call in this batch repeated the "
                + "same intent without new progress.";
            stopReasonKind = D045AgentTaskStopReason.RepeatedNoProgress;
        }

        return new AgentToolBatchOutcome(
            results,
            mustStop,
            mustStop ? stopReason : string.Empty,
            stopReasonKind);
    }

    private static D045AgentTaskStopReason HarnessFailureStopReason(
        GeminiToolResult result)
        => result.OutcomeReason switch
        {
            D045HarnessOutcomeReason.PermissionDefaultOff =>
                D045AgentTaskStopReason.RequiredPermissionDisabled,
            D045HarnessOutcomeReason.PermissionChangedBeforeAttempt =>
                D045AgentTaskStopReason.RequiredPermissionRevoked,
            D045HarnessOutcomeReason.PermissionChangedAfterAttempt =>
                D045AgentTaskStopReason.ToolFailed,
            D045HarnessOutcomeReason.TargetNotFound =>
                D045AgentTaskStopReason.TargetNotFound,
            D045HarnessOutcomeReason.TargetAmbiguous =>
                D045AgentTaskStopReason.TargetAmbiguous,
            D045HarnessOutcomeReason.Timeout =>
                D045AgentTaskStopReason.DeadlineExpired,
            D045HarnessOutcomeReason.TargetWrongKind
                or D045HarnessOutcomeReason.TargetLeafMismatch
                or D045HarnessOutcomeReason.TargetChanged
                or D045HarnessOutcomeReason.InvalidRequest
                or D045HarnessOutcomeReason.TaskAlreadyConsumed =>
                D045AgentTaskStopReason.GoalIncomplete,
            _ => D045AgentTaskStopReason.ToolFailed
        };

    private static bool IsAgentToolRelevantToRemainingGoals(
        GeminiFunctionCallData call,
        LocalActionGoal remainingGoals,
        AgentLoopBudget budget)
    {
        if (call.ArgumentFailureCode.Length > 0)
        {
            return BuildAgentFunctionNames(budget.ToolManifest).Contains(
                call.Name,
                StringComparer.Ordinal);
        }
        if (string.Equals(
                call.Name,
                "observe_local_target",
                StringComparison.Ordinal))
        {
            return remainingGoals.HasFlag(LocalActionGoal.ReadFile)
                || remainingGoals.HasFlag(LocalActionGoal.EnumerateFolder)
                || remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect)
                || remainingGoals.HasFlag(LocalActionGoal.Open)
                || (remainingGoals.HasFlag(LocalActionGoal.Workstation)
                    && budget.ToolManifest.Tools.Any(value =>
                        budget.IsCodexCapabilityStillRequired(value.Capability)
                        && value.Capability is
                            D045PermissionCapability.LocalFileRead
                            or D045PermissionCapability.LocalFolderEnumerate
                            or D045PermissionCapability.ApplicationLaunch
                            or D045PermissionCapability.LocalContentOpen));
        }
        if (remainingGoals == LocalActionGoal.None)
        {
            return false;
        }
        var capabilityToken = GetToolString(call.Args, "capability", 80)
            .Trim()
            .ToLowerInvariant();
        if (!D045CapabilityDescriptorCatalog.TryResolveExactToolToken(
                capabilityToken,
                out var typedCapability))
        {
            return false;
        }
        if (string.Equals(
                call.Name,
                D045CodexProviderToolContract.FunctionName,
                StringComparison.Ordinal))
        {
            return (int)typedCapability >= 21
                && remainingGoals.HasFlag(LocalActionGoal.Workstation)
                && budget.IsCodexCapabilityExecutableNow(typedCapability)
                && budget.ToolManifest.Contains(typedCapability);
        }
        if (!string.Equals(call.Name, "run_local_task", StringComparison.Ordinal)
            || (int)typedCapability > 20)
        {
            return false;
        }
        if (remainingGoals.HasFlag(LocalActionGoal.Workstation))
        {
            return budget.IsCodexCapabilityExecutableNow(typedCapability)
                && budget.ToolManifest.Contains(typedCapability);
        }
        var capability = capabilityToken;
        return capability switch
        {
            "sanitized_status_read" =>
                remainingGoals.HasFlag(LocalActionGoal.StatusRead)
                || remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect),
            "clipboard_read" =>
                remainingGoals.HasFlag(LocalActionGoal.ClipboardRead)
                || remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect),
            "local_file_read" =>
                remainingGoals.HasFlag(LocalActionGoal.ReadFile)
                || remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect),
            "public_https_fetch" =>
                remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect),
            "local_folder_enumerate" =>
                remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect)
                || remainingGoals.HasFlag(LocalActionGoal.EnumerateFolder)
                || remainingGoals.HasFlag(LocalActionGoal.Open)
                || remainingGoals.HasFlag(LocalActionGoal.Create)
                || remainingGoals.HasFlag(LocalActionGoal.Delete)
                || remainingGoals.HasFlag(LocalActionGoal.PermanentDelete),
            "screenshot_capture" =>
                remainingGoals.HasFlag(LocalActionGoal.Screenshot)
                || remainingGoals.HasFlag(LocalActionGoal.ReadOrInspect),
            "local_data_create" =>
                remainingGoals.HasFlag(LocalActionGoal.Create),
            "application_launch" or "local_content_open" =>
                remainingGoals.HasFlag(LocalActionGoal.Open)
                || remainingGoals.HasFlag(
                    LocalActionGoal.CorrelateCreateOpen),
            "recycle_bin_delete" =>
                remainingGoals.HasFlag(LocalActionGoal.Delete),
            "permanent_delete" =>
                remainingGoals.HasFlag(LocalActionGoal.PermanentDelete),
            "graceful_process_close" =>
                remainingGoals.HasFlag(LocalActionGoal.Close),
            "force_terminate_process" =>
                remainingGoals.HasFlag(LocalActionGoal.ForceClose),
            "shutdown" => remainingGoals.HasFlag(LocalActionGoal.Shutdown),
            "restart" => remainingGoals.HasFlag(LocalActionGoal.Restart),
            "external_app_input" =>
                remainingGoals.HasFlag(LocalActionGoal.ExternalInput),
            "raw_shell" => remainingGoals.HasFlag(LocalActionGoal.RawShell),
            "elevation" => remainingGoals.HasFlag(LocalActionGoal.Elevation),
            _ => false
        };
    }

    private static string AgentToolRelevanceFailureMessage(
        GeminiFunctionCallData call,
        AgentLoopBudget budget)
    {
        var capabilityToken = GetToolString(call.Args, "capability", 80)
            .Trim()
            .ToLowerInvariant();
        if (D045CapabilityDescriptorCatalog.TryResolveExactToolToken(
                capabilityToken,
                out var capability)
            && budget.TryGetPendingCodexCapabilityPrerequisite(
                capability,
                out var prerequisite))
        {
            return "This capability was not executed because the host-owned "
                + "task sequence requires a verified "
                + HarnessCapabilityToken(prerequisite)
                + " receipt first. Perform that exact prerequisite before "
                + "retrying this later effect.";
        }
        return "This capability was not executed because it cannot satisfy "
            + "any remaining player-requested goal.";
    }

    private static bool IsHighRiskAgentToolCall(
        GeminiFunctionCallData call)
    {
        if (string.Equals(
                call.Name,
                "observe_local_target",
                StringComparison.Ordinal))
        {
            return false;
        }
        if (!string.Equals(
                call.Name,
                "run_local_task",
                StringComparison.Ordinal))
        {
            if (!string.Equals(
                    call.Name,
                    D045CodexProviderToolContract.FunctionName,
                    StringComparison.Ordinal))
            {
                return true;
            }
        }
        var capabilityToken = GetToolString(call.Args, "capability", 80)
            .Trim()
            .ToLowerInvariant();
        return !D045CapabilityDescriptorCatalog.TryResolveExactToolToken(
                capabilityToken,
                out var capability)
            || D045CapabilityDescriptorCatalog.Get(capability).RiskTier
                >= D045CapabilityRiskTier.High;
    }

    private static D045AgentTaskDirective ObserveAgentToolBatch(
        AgentLoopBudget budget,
        LocalActionGoal actionGoal,
        AgentToolBatchOutcome outcome)
    {
        var directive = budget.ObserveToolBatch(
            actionGoal,
            outcome.MustStop,
            outcome.StopReasonKind);
        var goalSatisfied = actionGoal != LocalActionGoal.None
            && budget.HasVerifiedHarnessReceiptFor(actionGoal);
        var phase = budget.TaskPhase.ToString();
        var satisfiedGoals = budget.GetSatisfiedGoals(actionGoal);
        var remainingGoals = budget.GetRemainingGoals(actionGoal);
        foreach (var value in outcome.Results)
        {
            value.Result.GoalSatisfied = goalSatisfied;
            value.Result.SatisfiedGoals = satisfiedGoals.ToString();
            value.Result.AgentPhase = phase;
            value.Result.RemainingGoals = remainingGoals.ToString();
            value.Result.TerminalReason = budget.StopReason.ToString();
        }
        return directive;
    }

    private static string VerifiedGoalFinalizationInstruction(
        string systemInstruction,
        AgentLoopBudget budget)
        => systemInstruction
            + "\nThe host has verified every requested local effect with "
            + "typed Local Task Harness receipts. Do not request or describe "
            + "another tool call. Reply once, briefly and truthfully, using "
            + "only this host-owned evidence summary: "
            + budget.VerifiedCompletionEvidenceSummary()
            + ". A scheduled or dispatch-accepted effect is not proof of its "
            + "ultimate user-visible result. Do not invent unobserved details.";

    private static string VerifiedGoalFallbackReply(AgentLoopBudget budget)
    {
        var evidence = budget.VerifiedCompletionEvidenceSummary();
        if (evidence.Contains("power request was scheduled", StringComparison.Ordinal))
        {
            return ApiKeyText(
                "Windows 已接受這次電源操作的排程。",
                "Windows 已接受这次电源操作的排程。",
                "Windows は今回の電源操作の予約を受け付けたよ。",
                "Windows accepted and scheduled the requested power action.");
        }
        if (evidence.Contains("content-open dispatch accepted", StringComparison.Ordinal))
        {
            return ApiKeyText(
                "Windows 已接受開啟指定本機內容的要求。",
                "Windows 已接受打开指定本地内容的请求。",
                "Windows は指定されたローカル項目を開く要求を受け付けたよ。",
                "Windows accepted the request to open the exact local item.");
        }
        return ApiKeyText(
            "這次操作的必要本機驗證已通過。",
            "这次操作的必要本地验证已通过。",
            "今回の操作に必要なローカル検証は通過したよ。",
            "The required local postconditions were verified.");
    }

    private static bool CompleteVerifiedGoalFinalization(
        AgentLoopBudget budget,
        string providerReply,
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        PlayerTurnOperationHandle operation)
    {
        // Provider prose is not terminal evidence. Even a tools-disabled
        // finalization response can overclaim an unobserved effect, so the
        // player-visible completion is always composed from the host-owned
        // receipt/postcondition ledger below.
        _ = providerReply;
        var directive = budget.ObserveVerifiedGoalFinalization(
            providerReplyIsUsable: false);
        if (directive == D045AgentTaskDirective.Ignore)
            return false;

        var reply = VerifiedGoalFallbackReply(budget);
        Plugin.PluginLog.LogInfo(
            "Verified local-agent task completed through the deterministic "
                + "receipt-grounded host finalization; provider prose was "
                + "not publication authority.");
        CompleteAiReply(
            reply,
            userText,
            poseContext,
            japaneseVoiceMode,
            operation);
        return true;
    }

    private static void CompleteAgentLoopStopped(
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        PlayerTurnOperationHandle operation,
        string reason)
    {
        Plugin.PluginLog.LogWarning(
            "The bounded local agent loop stopped safely: " + reason);
        CompleteAiReply(
            ApiKeyText(
                "我發現操作開始重複、沒有得到新結果，或已經用完這次的安全操作預算，所以先停在這裡。",
                "我发现操作开始重复、没有得到新结果，或已经用完这次的安全操作预算，所以先停在这里。",
                "操作が繰り返しになって新しい結果が得られないか、今回の安全な操作枠を使い切ったので、ここで止めておくね。",
                "The actions began repeating without new progress, or this "
                    + "turn used its bounded safety budget, so I stopped here."),
            userText,
            poseContext,
            japaneseVoiceMode,
            operation,
            PlayerTurnPublicationKind.FailureNotice,
            PlayerTurnTerminalDisposition.Failed,
            PlayerTurnFailureReason.ToolExecutionFailed);
    }

    private static void CompleteAgentTaskStop(
        AgentLoopBudget budget,
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        PlayerTurnOperationHandle operation,
        D045AgentTaskStopReason stopReason,
        string detail,
        LocalActionGoal actionGoal = LocalActionGoal.None)
    {
        var reason = stopReason == D045AgentTaskStopReason.None
            ? InferAgentTaskStopReason(detail)
            : stopReason;
        budget.ObserveImmediateStop(reason);
        var satisfiedGoals = budget.GetSatisfiedGoals(actionGoal);
        var remainingGoals = budget.GetRemainingGoals(actionGoal);
        CompleteExplicitActionStop(
            reason,
            Array.Empty<D045ExplicitActionPermissionClause>(),
            userText,
            poseContext,
            japaneseVoiceMode,
            operation,
            satisfiedGoals,
            remainingGoals);
    }

    private static D045AgentTaskStopReason InferAgentTaskStopReason(
        string reason)
    {
        if (reason.Contains("cancel", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.OperationCancelled;
        if (reason.Contains("permission revision", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.RequiredPermissionRevoked;
        if (reason.Contains("deadline", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.DeadlineExpired;
        if (reason.Contains("round limit", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.RoundLimitReached;
        if (reason.Contains("call limit", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.CallLimitReached;
        if (reason.Contains("repeat", StringComparison.OrdinalIgnoreCase)
            || reason.Contains("progress", StringComparison.OrdinalIgnoreCase))
            return D045AgentTaskStopReason.RepeatedNoProgress;
        return D045AgentTaskStopReason.GoalIncomplete;
    }

    private static void CompleteExplicitActionStop(
        D045AgentTaskStopReason stopReason,
        IReadOnlyList<D045ExplicitActionPermissionClause> missingClauses,
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        PlayerTurnOperationHandle operation,
        LocalActionGoal satisfiedGoals = LocalActionGoal.None,
        LocalActionGoal remainingGoals = LocalActionGoal.None)
    {
        var missing = string.Join(", ", missingClauses.Select(value => value.Token));
        var message = BuildAgentTaskStopReply(
            stopReason,
            missing,
            satisfiedGoals,
            remainingGoals);
        var cancelled = stopReason is
            D045AgentTaskStopReason.OperationCancelled
            or D045AgentTaskStopReason.RequiredPermissionRevoked;
        CompleteAiReply(
            message,
            userText,
            poseContext,
            japaneseVoiceMode,
            operation,
            PlayerTurnPublicationKind.FailureNotice,
            cancelled
                ? PlayerTurnTerminalDisposition.Cancelled
                : PlayerTurnTerminalDisposition.Failed,
            cancelled
                ? PlayerTurnFailureReason.None
                : PlayerTurnFailureReason.ToolExecutionFailed,
            cancelled
                ? PlayerTurnCancellationReason.Superseded
                : PlayerTurnCancellationReason.None);
    }

    private static string BuildAgentTaskStopReply(
        D045AgentTaskStopReason stopReason,
        string missing,
        LocalActionGoal satisfiedGoals,
        LocalActionGoal remainingGoals)
    {
        var missingSuffix = missing.Length == 0
            ? string.Empty
            : " (" + missing + ")";
        var traditional = stopReason switch
        {
            D045AgentTaskStopReason.RequiredPermissionDisabled =>
                "需要的權限目前沒有開啟" + missingSuffix
                    + "。我沒有執行這次操作；請在 Control Center 開啟後再試。",
            D045AgentTaskStopReason.PermissionStateUnavailable =>
                "我目前無法安全讀取權限狀態，所以沒有執行任何操作。",
            D045AgentTaskStopReason.ExplicitActionUnsupported =>
                "這項操作目前沒有對應的安全工具，所以我沒有執行。",
            D045AgentTaskStopReason.ExplicitActionAmbiguous
                or D045AgentTaskStopReason.TargetAmbiguous =>
                "我找到不只一個可能的目標；請再告訴我更精確的名稱或位置。",
            D045AgentTaskStopReason.TargetNotFound =>
                "我沒有找到符合的目標，因此沒有執行操作。",
            D045AgentTaskStopReason.RequiredPermissionRevoked =>
                "權限在下一個操作獲准前發生變更；我沒有送出這一步，也沒有重試。",
            D045AgentTaskStopReason.OperationCancelled =>
                "這次操作已取消，我沒有再執行後續步驟。",
            D045AgentTaskStopReason.DeadlineExpired =>
                "這次操作已超過安全時間上限；先前步驟可能已經發生，但我無法完成驗證，也沒有重試。",
            D045AgentTaskStopReason.RoundLimitReached
                or D045AgentTaskStopReason.CallLimitReached =>
                "這次操作已用完安全步驟預算，而且尚未完成，所以我先停止。",
            D045AgentTaskStopReason.RepeatedNoProgress =>
                "我發現操作開始重複而沒有新進展，因此停止了後續步驟。",
            D045AgentTaskStopReason.ProviderFaultedBeforeVerification =>
                "模型連線在操作完成驗證前中斷；我不能宣稱這次操作成功。",
            D045AgentTaskStopReason.ToolFailed =>
                "本機工具未能完成驗證；操作可能已經發生，但我沒有自動重試。",
            _ => "這次操作尚未取得完整的本機驗證，因此我不能宣稱已完成。"
        };
        var simplified = stopReason switch
        {
            D045AgentTaskStopReason.RequiredPermissionDisabled =>
                "需要的权限目前没有开启" + missingSuffix
                    + "。我没有执行这次操作；请在 Control Center 开启后再试。",
            D045AgentTaskStopReason.PermissionStateUnavailable =>
                "我目前无法安全读取权限状态，所以没有执行任何操作。",
            D045AgentTaskStopReason.ExplicitActionUnsupported =>
                "这项操作目前没有对应的安全工具，所以我没有执行。",
            D045AgentTaskStopReason.ExplicitActionAmbiguous
                or D045AgentTaskStopReason.TargetAmbiguous =>
                "我找到了不止一个可能的目标；请告诉我更精确的名称或位置。",
            D045AgentTaskStopReason.TargetNotFound =>
                "我没有找到符合的目标，因此没有执行操作。",
            D045AgentTaskStopReason.RequiredPermissionRevoked =>
                "权限在下一个操作获准前发生变化；我没有送出这一步，也没有重试。",
            D045AgentTaskStopReason.OperationCancelled =>
                "这次操作已取消，我没有再执行后续步骤。",
            D045AgentTaskStopReason.DeadlineExpired =>
                "这次操作已超过安全时间上限；先前步骤可能已经发生，但我无法完成验证，也没有重试。",
            D045AgentTaskStopReason.RoundLimitReached
                or D045AgentTaskStopReason.CallLimitReached =>
                "这次操作已用完安全步骤预算，而且尚未完成，所以我先停止。",
            D045AgentTaskStopReason.RepeatedNoProgress =>
                "我发现操作开始重复且没有新进展，因此停止了后续步骤。",
            D045AgentTaskStopReason.ProviderFaultedBeforeVerification =>
                "模型连接在操作完成验证前中断；我不能宣称这次操作成功。",
            D045AgentTaskStopReason.ToolFailed =>
                "本机工具未能完成验证；操作可能已经发生，但我没有自动重试。",
            _ => "这次操作尚未取得完整的本机验证，因此我不能宣称已完成。"
        };
        var japanese = stopReason switch
        {
            D045AgentTaskStopReason.RequiredPermissionDisabled =>
                "必要な権限が有効ではないよ" + missingSuffix
                    + "。今回は実行していないので、Control Center で有効にしてから試してね。",
            D045AgentTaskStopReason.PermissionStateUnavailable =>
                "権限の状態を安全に確認できなかったので、操作は実行していないよ。",
            D045AgentTaskStopReason.ExplicitActionUnsupported =>
                "その操作に対応する安全なツールがまだないので、実行していないよ。",
            D045AgentTaskStopReason.ExplicitActionAmbiguous
                or D045AgentTaskStopReason.TargetAmbiguous =>
                "候補が複数見つかったよ。もう少し正確な名前か場所を教えてね。",
            D045AgentTaskStopReason.TargetNotFound =>
                "一致する対象が見つからなかったので、操作は実行していないよ。",
            D045AgentTaskStopReason.RequiredPermissionRevoked =>
                "次の操作が許可される前に権限が変わったよ。この手順は送信せず、再試行もしなかったよ。",
            D045AgentTaskStopReason.OperationCancelled =>
                "この操作はキャンセルされたので、後続の手順は実行していないよ。",
            D045AgentTaskStopReason.DeadlineExpired =>
                "安全な制限時間を超えたよ。前の手順は起きた可能性があるけれど検証できず、再試行もしなかったよ。",
            D045AgentTaskStopReason.RoundLimitReached
                or D045AgentTaskStopReason.CallLimitReached =>
                "安全な手順の上限まで使っても完了しなかったので、ここで停止したよ。",
            D045AgentTaskStopReason.RepeatedNoProgress =>
                "同じ操作が繰り返されて進展がなかったので、後続の手順を停止したよ。",
            D045AgentTaskStopReason.ProviderFaultedBeforeVerification =>
                "検証が終わる前にモデル接続が切れたので、成功したとは言えないよ。",
            D045AgentTaskStopReason.ToolFailed =>
                "ローカルツールで検証を完了できなかったよ。操作は起きた可能性があるけれど、自動再試行はしていないよ。",
            _ => "完全なローカル検証が得られていないので、完了したとは言えないよ。"
        };
        var english = stopReason switch
        {
            D045AgentTaskStopReason.RequiredPermissionDisabled =>
                "The required permission is disabled" + missingSuffix
                    + ". I did not perform the action; enable it in Control Center and try again.",
            D045AgentTaskStopReason.PermissionStateUnavailable =>
                "I could not read the permission state safely, so I performed no action.",
            D045AgentTaskStopReason.ExplicitActionUnsupported =>
                "No safe tool currently supports this action, so I did not perform it.",
            D045AgentTaskStopReason.ExplicitActionAmbiguous
                or D045AgentTaskStopReason.TargetAmbiguous =>
                "I found more than one possible target; please provide a more exact name or location.",
            D045AgentTaskStopReason.TargetNotFound =>
                "I did not find a matching target, so I performed no action.",
            D045AgentTaskStopReason.RequiredPermissionRevoked =>
                "Permission changed before the next action was admitted. I did not dispatch that step or retry it.",
            D045AgentTaskStopReason.OperationCancelled =>
                "This action was cancelled, and I did not execute later steps.",
            D045AgentTaskStopReason.DeadlineExpired =>
                "This action exceeded its safety deadline. Earlier steps may have occurred, but I could not verify them and did not retry.",
            D045AgentTaskStopReason.RoundLimitReached
                or D045AgentTaskStopReason.CallLimitReached =>
                "This action exhausted its bounded step budget without completing, so I stopped.",
            D045AgentTaskStopReason.RepeatedNoProgress =>
                "The actions began repeating without new progress, so I stopped later steps.",
            D045AgentTaskStopReason.ProviderFaultedBeforeVerification =>
                "The model connection ended before verification completed, so I cannot claim success.",
            D045AgentTaskStopReason.ToolFailed =>
                "The local tool could not complete verification. The effect may have occurred, and I did not retry.",
            _ => "This action did not obtain complete local verification, so I cannot claim it completed."
        };
        var progressTraditional = BuildAgentProgressSuffix(
            satisfiedGoals,
            remainingGoals,
            " 已驗證：",
            "；尚未完成：");
        var progressSimplified = BuildAgentProgressSuffix(
            satisfiedGoals,
            remainingGoals,
            " 已验证：",
            "；尚未完成：");
        var progressJapanese = BuildAgentProgressSuffix(
            satisfiedGoals,
            remainingGoals,
            " 検証済み：",
            "；未完了：");
        var progressEnglish = BuildAgentProgressSuffix(
            satisfiedGoals,
            remainingGoals,
            " Verified: ",
            "; remaining: ");
        return ApiKeyText(
            traditional + progressTraditional,
            simplified + progressSimplified,
            japanese + progressJapanese,
            english + progressEnglish);
    }

    private static string BuildAgentProgressSuffix(
        LocalActionGoal satisfiedGoals,
        LocalActionGoal remainingGoals,
        string satisfiedPrefix,
        string remainingPrefix)
    {
        if (satisfiedGoals == LocalActionGoal.None
            || remainingGoals == LocalActionGoal.None)
        {
            return string.Empty;
        }
        return satisfiedPrefix + LocalActionGoalTokens(satisfiedGoals)
            + remainingPrefix + LocalActionGoalTokens(remainingGoals) + "。";
    }

    private static string LocalActionGoalTokens(LocalActionGoal goals)
        => string.Join(
            ", ",
            Enum.GetValues<LocalActionGoal>()
                .Where(value => value != LocalActionGoal.None
                    && goals.HasFlag(value))
                .Select(value => value.ToString().ToLowerInvariant()));

    private static bool CompleteExplicitActionWithoutVerifiedReceipt(
        LocalActionGoal actionGoal,
        AgentLoopBudget budget,
        string userText,
        PoseContext poseContext,
        bool japaneseVoiceMode,
        PlayerTurnOperationHandle operation)
    {
        if (actionGoal == LocalActionGoal.None
            || budget.HasVerifiedHarnessReceiptFor(actionGoal))
            return false;
        Plugin.PluginLog.LogWarning(
            "Rejected an explicit local-action completion because this turn "
            + "has no verified Harness receipt matching goal="
            + actionGoal
            + ".");
        CompleteAgentTaskStop(
            budget,
            userText,
            poseContext,
            japaneseVoiceMode,
            operation,
            D045AgentTaskStopReason.ProviderReturnedWithoutVerifiedReceipt,
            "The provider returned without every required verified receipt.",
            actionGoal);
        return true;
    }

    private static async Task ContinueWorkbenchProviderAgentRequestAsync(
        WorkbenchProviderAgentSession session)
    {
        try
        {
            await SendWorkbenchProviderAgentRequestAsync(session)
                .ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            LogSanitizedWorkbenchProviderAgentFailure(
                "tool-continuation",
                session.Binding,
                exception);
            if (CompleteVerifiedGoalFinalization(
                    session.CaptureAgentLoop(),
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                session.CaptureAgentLoop(),
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.ProviderFaultedBeforeVerification,
                "The provider continuation faulted before every required "
                    + "receipt was verified.",
                session.ActionGoal);
        }
    }

    private static void LogSanitizedWorkbenchProviderAgentFailure(
        string stage,
        WorkbenchProviderBinding binding,
        Exception exception)
    {
        var statusMatch = Regex.Match(
            exception.Message,
            @"\bHTTP\s+(?<code>\d{3})\b",
            RegexOptions.CultureInvariant);
        Plugin.PluginLog.LogWarning(
            "D-045 Workbench provider-agent failure: stage="
            + stage
            + ", provider="
            + binding.ProviderKind
            + ", protocol="
            + binding.Protocol
            + ", exceptionType="
            + exception.GetType().Name
            + ", httpStatus="
            + (statusMatch.Success
                ? statusMatch.Groups["code"].Value
                : "-")
            + ", internalStage="
            + (exception.Data["D045.WorkbenchProviderStage"] as string
                ?? "-")
            + ". Exception content, request/response text, credentials, "
            + "tool arguments, targets and paths are omitted.");
    }

    private static T RunSanitizedWorkbenchProviderStage<T>(
        string stage,
        Func<T> operation)
    {
        try
        {
            return operation();
        }
        catch (Exception exception)
        {
            if (!exception.Data.Contains("D045.WorkbenchProviderStage"))
                exception.Data["D045.WorkbenchProviderStage"] = stage;
            throw;
        }
    }

    private static void RunSanitizedWorkbenchProviderStage(
        string stage,
        Action operation)
    {
        RunSanitizedWorkbenchProviderStage(
            stage,
            () =>
            {
                operation();
                return true;
            });
    }

    private static object[] BuildWorkbenchOpenAiHarnessTools(
        D045AgentToolManifest manifest)
    {
        var tools = new List<object>();
        if (HasLegacyManifestTools(manifest))
        {
            tools.Add(new
            {
                type = "function",
                function = new
                {
                    name = "run_local_task",
                    description = LegacyHarnessToolDescription(manifest),
                    parameters = WorkbenchHarnessParameters(manifest)
                }
            });
        }
        if (SupportsSemanticObservation(manifest))
        {
            tools.Add(new
            {
                type = "function",
                function = new
                {
                    name = "observe_local_target",
                    description = SemanticObservationToolDescription,
                    parameters = SemanticObservationParameters()
                }
            });
        }
        if (HasCodexManifestTools(manifest))
        {
            tools.Add(new
            {
                type = "function",
                function = new
                {
                    name = D045CodexProviderToolContract.FunctionName,
                    description = CodexWorkstationToolDescription(manifest),
                    parameters = D045CodexProviderToolContract
                        .BuildJsonSchema(manifest)
                }
            });
        }
        return tools.ToArray();
    }

