    private static string CodexWorkstationToolDescription(
        D045AgentToolManifest manifest)
        => "Run one exact enabled typed workstation capability. The host "
            + "freezes the task, permission revision and owner; the executor "
            + "independently validates the request and returns a verified "
            + "postcondition receipt. Enabled exact leaves: "
            + string.Join("; ", manifest.Tools
                .Where(value => value.Ordinal >= 21)
                .Select(value => value.ToolToken + " — "
                    + value.ToolUseDetails))
            + " Exact field recipes: "
            + D045CodexProviderToolContract.BuildUsageGuide(manifest);

    private const string SemanticObservationToolDescription =
        "Resolve or inspect one player-requested local target without causing "
        + "an operating-system effect. The host chooses the fixed purpose and "
        + "backing permission; the model cannot widen it. A successful result "
        + "returns a short-lived opaque target reference for a later exact "
        + "run_local_task call. Observation never means the action completed.";

    private static object SemanticObservationParameters()
        => new
        {
            type = "object",
            properties = new
            {
                query_kind = new
                {
                    type = "string",
                    @enum = new[]
                    {
                        "resolve_local_target",
                        "inspect_local_item",
                        "query_application"
                    },
                    description = "Read-only semantic operation."
                },
                query = new
                {
                    type = "string",
                    description = "One exact app name, absolute local path, or bounded known:desktop/documents/downloads/pictures selector. Never use an empty global inventory query."
                },
                target_ref = new
                {
                    type = "string",
                    description = "Opaque d045ref_ reference returned by an earlier observation when inspecting it."
                }
            },
            required = new[] { "query_kind" },
            additionalProperties = false
        };

    private static object WorkbenchHarnessParameters(
        D045AgentToolManifest manifest)
        => new
        {
            type = "object",
            properties = new
            {
                capability = new
                {
                    type = "string",
                    @enum = LegacyManifestTokens(manifest),
                    description = LegacyManifestCapabilityDescription(manifest)
                },
                target = new
                {
                    type = "string",
                    description = LocalTaskHarnessTargetDescription
                },
                secondary_target = LegacySecondaryTargetSchema(
                    manifest,
                    gemini: false),
                payload = new
                {
                    type = "string",
                    description = "Exact command, text/keys, new UTF-8 file content, or executable arguments when required; otherwise empty."
                },
                timeout_ms = new
                {
                    type = "number",
                    description = "Execution timeout from 1000 to 120000 milliseconds."
                }
            },
            required = IsCreateOnlyLegacyManifest(manifest)
                ? new[] { "capability", "target", "secondary_target" }
                : new[] { "capability" },
            additionalProperties = false
        };

    private static string[] LegacyManifestTokens(D045AgentToolManifest manifest)
        => manifest.Tools
            .Where(value => value.Ordinal <= 20)
            .Select(value => value.ToolToken)
            .ToArray();

    private static bool HasLegacyManifestTools(D045AgentToolManifest manifest)
        => manifest.Tools.Any(value => value.Ordinal <= 20);

    private static bool IsCreateOnlyLegacyManifest(
        D045AgentToolManifest manifest)
    {
        var legacy = manifest.Tools
            .Where(value => value.Ordinal <= 20)
            .Select(value => value.Capability)
            .ToArray();
        return legacy.Length == 1
            && legacy[0] == D045PermissionCapability.LocalDataCreate;
    }

    private static object LegacySecondaryTargetSchema(
        D045AgentToolManifest manifest,
        bool gemini)
    {
        var type = gemini ? "STRING" : "string";
        return IsCreateOnlyLegacyManifest(manifest)
            ? new
            {
                type,
                @enum = new[] { "file", "directory" },
                description = "Required literal kind token for local_data_create: exactly file or directory. This is never a path."
            }
            : new
            {
                type,
                description = "Exact HTTPS upload destination, or the required literal file/directory kind token for local_data_create; otherwise empty."
            };
    }

    private static bool HasCodexManifestTools(D045AgentToolManifest manifest)
        => manifest.Tools.Any(value => value.Ordinal >= 21);

    private static bool SupportsSemanticObservation(
        D045AgentToolManifest manifest)
        => manifest.Tools.Any(value => value.Capability is
            D045PermissionCapability.LocalFileRead
            or D045PermissionCapability.LocalFolderEnumerate
            or D045PermissionCapability.ApplicationLaunch
            or D045PermissionCapability.LocalContentOpen);

    private static string LegacyManifestCapabilityDescription(
        D045AgentToolManifest manifest)
        => "Enabled exact leaves: " + string.Join("; ", manifest.Tools
            .Where(value => value.Ordinal <= 20)
            .Select(value => value.ToolToken + " — " + value.ToolUseDetails));

    private static string LegacyHarnessToolDescription(
        D045AgentToolManifest manifest)
        => "Run one exact legacy Local Task Harness capability from this "
            + "turn's frozen enum. The Harness rechecks permission and verifies "
            + "the postcondition. "
            + LegacyManifestCapabilityDescription(manifest);

    private static string[] BuildAgentFunctionNames(
        D045AgentToolManifest manifest)
    {
        var names = new List<string>();
        if (HasLegacyManifestTools(manifest))
            names.Add("run_local_task");
        if (SupportsSemanticObservation(manifest))
            names.Add("observe_local_target");
        if (HasCodexManifestTools(manifest))
            names.Add(D045CodexProviderToolContract.FunctionName);
        return names.ToArray();
    }

    private static JsonElement ParseProviderToolArguments(
        JsonElement arguments,
        ProviderControlProtocol protocol,
        int ordinal,
        out string failureCode)
    {
        failureCode = string.Empty;
        if (arguments.ValueKind is JsonValueKind.Undefined
            or JsonValueKind.Null)
        {
            return JsonSerializer.SerializeToElement(new { });
        }

        try
        {
            JsonElement parsedArguments;
            if (arguments.ValueKind == JsonValueKind.String)
            {
                var raw = arguments.GetString();
                if (string.IsNullOrWhiteSpace(raw))
                    throw new JsonException("Empty tool arguments.");
                using var parsed = JsonDocument.Parse(raw);
                parsedArguments = parsed.RootElement.Clone();
            }
            else
            {
                parsedArguments = arguments.Clone();
            }

            if (parsedArguments.ValueKind != JsonValueKind.Object)
            {
                failureCode = "arguments_not_object";
            }
            if (failureCode.Length == 0)
                return parsedArguments;
        }
        catch (JsonException)
        {
            failureCode = "malformed_json";
        }

        Plugin.PluginLog.LogWarning(
            "D-045 provider tool arguments rejected before execution: "
            + "protocol="
            + protocol
            + ", ordinal="
            + ordinal.ToString(CultureInfo.InvariantCulture)
            + ", reason="
            + failureCode
            + ". Tool name, argument content, targets and paths are omitted.");
        return JsonSerializer.SerializeToElement(new { });
    }

    private static List<GeminiFunctionCallData> ParseWorkbenchProviderToolCalls(
        ProviderControlProtocol protocol,
        ProviderControlKind providerKind,
        JsonElement root,
        out string reply,
        out object assistantMessage)
    {
        reply = ExtractWorkbenchProviderText(protocol, root);
        var calls = new List<GeminiFunctionCallData>();
        if (protocol == ProviderControlProtocol.OpenAiResponses)
        {
            var output = root.TryGetProperty("output", out var responseOutput)
                && responseOutput.ValueKind == JsonValueKind.Array
                    ? responseOutput
                    : JsonSerializer.SerializeToElement(Array.Empty<object>());
            assistantMessage = output.EnumerateArray()
                .Select(value => (object)value.Clone())
                .ToArray();
            var responseOrdinal = 0;
            foreach (var item in output.EnumerateArray())
            {
                responseOrdinal++;
                if (!item.TryGetProperty("type", out var type)
                    || !string.Equals(
                        type.GetString(),
                        "function_call",
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }
                var argumentFailureCode = string.Empty;
                var hasArguments = item.TryGetProperty(
                    "arguments",
                    out var arguments);
                var args = hasArguments
                    ? ParseProviderToolArguments(
                        arguments,
                        protocol,
                        responseOrdinal,
                        out argumentFailureCode)
                    : JsonSerializer.SerializeToElement(new { });
                calls.Add(new GeminiFunctionCallData
                {
                    Id = item.TryGetProperty("call_id", out var callId)
                        ? callId.GetString() ?? string.Empty
                        : string.Empty,
                    Name = item.TryGetProperty("name", out var name)
                        ? name.GetString() ?? string.Empty
                        : string.Empty,
                    Args = args,
                    ArgumentFailureCode = argumentFailureCode
                });
            }
            return calls;
        }
        if (protocol == ProviderControlProtocol.AnthropicMessages)
        {
            var content = root.GetProperty("content");
            assistantMessage = new { role = "assistant", content = content.Clone() };
            foreach (var part in content.EnumerateArray())
            {
                if (!part.TryGetProperty("type", out var type)
                    || type.GetString() != "tool_use")
                {
                    continue;
                }
                calls.Add(new GeminiFunctionCallData
                {
                    Id = part.TryGetProperty("id", out var id)
                        ? id.GetString() ?? string.Empty
                        : string.Empty,
                    Name = part.TryGetProperty("name", out var name)
                        ? name.GetString() ?? string.Empty
                        : string.Empty,
                    Args = part.TryGetProperty("input", out var input)
                        ? input.Clone()
                        : JsonSerializer.SerializeToElement(new { })
                });
            }
            return calls;
        }

        var message = root.GetProperty(
            protocol == ProviderControlProtocol.OllamaNativeChat
                ? "message"
                : "choices");
        if (protocol != ProviderControlProtocol.OllamaNativeChat)
            message = message[0].GetProperty("message");
        assistantMessage = BuildWorkbenchOpenAiAssistantReplayMessage(
            message,
            providerKind);
        if (!message.TryGetProperty("tool_calls", out var toolCalls)
            || toolCalls.ValueKind != JsonValueKind.Array)
            return calls;
        var ordinal = 0;
        foreach (var value in toolCalls.EnumerateArray())
        {
            ordinal++;
            var function = value.TryGetProperty("function", out var nested)
                ? nested
                : value;
            var argumentFailureCode = string.Empty;
            var hasArguments = function.TryGetProperty(
                "arguments",
                out var arguments);
            var args = hasArguments
                ? ParseProviderToolArguments(
                    arguments,
                    protocol,
                    ordinal,
                    out argumentFailureCode)
                : JsonSerializer.SerializeToElement(new { });
            calls.Add(new GeminiFunctionCallData
            {
                Id = value.TryGetProperty("id", out var id)
                    ? id.GetString() ?? string.Empty
                    : "ollama-tool-"
                        + ordinal.ToString(CultureInfo.InvariantCulture),
                Name = function.TryGetProperty("name", out var name)
                    ? name.GetString() ?? string.Empty
                    : string.Empty,
                Args = args,
                ArgumentFailureCode = argumentFailureCode
            });
        }
        return calls;
    }

    private static object BuildWorkbenchOpenAiAssistantReplayMessage(
        JsonElement message,
        ProviderControlKind providerKind)
    {
        if (providerKind != ProviderControlKind.DeepSeek)
            return message.Clone();

        var replay = new Dictionary<string, object?>
        {
            ["role"] = "assistant",
            ["content"] = message.TryGetProperty("content", out var content)
                && content.ValueKind == JsonValueKind.String
                    ? content.GetString() ?? string.Empty
                    : string.Empty
        };
        if (message.TryGetProperty(
                "reasoning_content",
                out var reasoningContent)
            && reasoningContent.ValueKind == JsonValueKind.String)
        {
            replay["reasoning_content"] =
                reasoningContent.GetString() ?? string.Empty;
        }
        if (message.TryGetProperty("tool_calls", out var toolCalls))
            replay["tool_calls"] = toolCalls.Clone();
        return replay;
    }

    private static void AppendWorkbenchProviderToolResults(
        WorkbenchProviderAgentSession session,
        IEnumerable<(GeminiFunctionCallData Call, GeminiToolResult Result)> results)
    {
        var frozen = results.ToArray();
        if (session.Binding.Protocol
            == ProviderControlProtocol.OpenAiResponses)
        {
            foreach (var value in frozen)
            {
                session.Messages.Add(new
                {
                    type = "function_call_output",
                    call_id = value.Call.Id,
                    output = JsonSerializer.Serialize(
                        BuildNormalizedProviderToolResult(value.Result))
                });
            }
            return;
        }
        if (session.Binding.Protocol == ProviderControlProtocol.AnthropicMessages)
        {
            session.Messages.Add(new
            {
                role = "user",
                content = frozen.Select(value => (object)new
                {
                    type = "tool_result",
                    tool_use_id = value.Call.Id,
                    content = JsonSerializer.Serialize(
                        BuildNormalizedProviderToolResult(value.Result))
                }).ToArray()
            });
            return;
        }
        foreach (var value in frozen)
        {
            var content = JsonSerializer.Serialize(
                BuildNormalizedProviderToolResult(value.Result));
            session.Messages.Add(
                session.Binding.Protocol == ProviderControlProtocol.OllamaNativeChat
                    ? new
                    {
                        role = "tool",
                        tool_name = value.Call.Name,
                        content
                    }
                    : (object)new
                    {
                        role = "tool",
                        tool_call_id = value.Call.Id,
                        content
                    });
        }
    }

    private static object BuildNormalizedProviderToolResult(
        GeminiToolResult result)
        => new
        {
            success = result.Success,
            taskId = result.TaskId,
            capability = result.Capability,
            attempted = result.Attempted,
            verified = result.Verified,
            exit = result.ExitCode,
            requestFingerprint = result.RequestFingerprint,
            outcomeFingerprint = result.OutcomeFingerprint,
            resolvedTargetFingerprint =
                result.ResolvedTargetFingerprint,
            targetFingerprint = result.TargetFingerprint,
            resolvedTargetKind = HarnessTargetKindToken(
                result.ResolvedTargetKind),
            resolvedExtension = result.ResolvedExtension,
            resolvedLeafNameFingerprint =
                result.ResolvedLeafNameFingerprint,
            permissionRevision = result.PermissionRevision,
            contentSha256 = result.ContentSha256,
            jobId = result.JobId,
            applicationProcessId = result.ApplicationProcessId,
            applicationUiTarget = result.ApplicationProcessId,
            typedOutcomeReason = result.TypedOutcomeReason,
            typedPostcondition = result.TypedPostcondition,
            outcomeReason = result.OutcomeReason.ToString(),
            verificationStrength = result.VerificationStrength.ToString(),
            postconditionCode = result.PostconditionCode.ToString(),
            retryAllowed = result.RetryAllowed,
            retryRequiresChangedTarget = result.RetryRequiresChangedTarget,
            effectPossiblyApplied = result.EffectPossiblyApplied,
            goalSatisfied = result.GoalSatisfied,
            satisfiedGoals = result.SatisfiedGoals,
            agentPhase = result.AgentPhase,
            remainingGoals = result.RemainingGoals,
            terminalReason = result.TerminalReason,
            observation = result.IsSemanticObservation,
            observationComplete = result.ObservationComplete,
            observationAmbiguous = result.ObservationAmbiguous,
            observationFailure = result.ObservationFailure,
            observationFingerprint = result.ObservationFingerprint,
            candidates = result.ObservationCandidates.Select(value => new
            {
                targetRef = value.TargetReference,
                name = value.SafeDisplayLeaf,
                kind = value.TargetKind,
                extension = value.SafeExtension,
                targetFingerprint = value.TargetFingerprint,
                displayLeafFingerprint = value.DisplayLeafFingerprint
            }).ToArray(),
            result = result.Message
        };

