    private static object BuildWorkbenchProviderPayload(
        WorkbenchProviderBinding binding,
        string systemInstruction,
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
    {
        var maximumTokens = binding.HighReasoning ? 4096 : 2048;
        return binding.Protocol switch
        {
            ProviderControlProtocol.OpenAiChatCompletions
                or ProviderControlProtocol.OpenAiCompatibleChat => new
                {
                    model = binding.ModelId,
                    messages = BuildWorkbenchOpenAiMessages(
                        systemInstruction,
                        providerInput,
                        attachments),
                    max_tokens = maximumTokens
                },
            ProviderControlProtocol.OpenAiResponses => new
                {
                    model = binding.ModelId,
                    instructions = systemInstruction,
                    input = new[]
                    {
                        new
                        {
                            role = "user",
                            content = BuildWorkbenchOpenAiResponsesInput(
                                providerInput,
                                attachments)
                        }
                    },
                    max_output_tokens = maximumTokens,
                    store = false
                },
            ProviderControlProtocol.AnthropicMessages => new
                {
                    model = binding.ModelId,
                    system = systemInstruction,
                    max_tokens = maximumTokens,
                    messages = new[]
                    {
                        new
                        {
                            role = "user",
                            content = BuildWorkbenchAnthropicContent(
                                providerInput,
                                attachments)
                        }
                    }
                },
            ProviderControlProtocol.OllamaNativeChat => new
                {
                    model = binding.ModelId,
                    messages = BuildWorkbenchOllamaMessages(
                        systemInstruction,
                        providerInput,
                        attachments),
                    stream = false,
                    options = new { num_predict = maximumTokens }
                },
            _ => throw new InvalidOperationException(
                "The selected Workbench protocol is not supported.")
        };
    }

    private static object[] BuildWorkbenchOpenAiMessages(
        string systemInstruction,
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
        => new object[]
        {
            new { role = "system", content = systemInstruction },
            new
            {
                role = "user",
                content = attachments.Count == 0
                    ? (object)providerInput
                    : BuildWorkbenchOpenAiInput(providerInput, attachments)
            }
        };

    private static object[] BuildWorkbenchOpenAiInput(
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
    {
        var content = new List<object>
        {
            new { type = "text", text = providerInput }
        };
        content.AddRange(attachments.Select(value => new
        {
            type = "image_url",
            image_url = new
            {
                url = "data:"
                    + value.MediaType
                    + ";base64,"
                    + value.DataBase64
            }
        }));
        return content.ToArray();
    }

    private static object[] BuildWorkbenchOpenAiResponsesInput(
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
    {
        var content = new List<object>
        {
            new { type = "input_text", text = providerInput }
        };
        content.AddRange(attachments.Select(value => new
        {
            type = "input_image",
            image_url = "data:"
                + value.MediaType
                + ";base64,"
                + value.DataBase64
        }));
        return content.ToArray();
    }

    private static object[] BuildWorkbenchAnthropicContent(
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
    {
        var content = attachments.Select(value => (object)new
        {
            type = "image",
            source = new
            {
                type = "base64",
                media_type = value.MediaType,
                data = value.DataBase64
            }
        }).ToList();
        content.Add(new { type = "text", text = providerInput });
        return content.ToArray();
    }

    private static object[] BuildWorkbenchOllamaMessages(
        string systemInstruction,
        string providerInput,
        IReadOnlyList<D045WorkbenchLiveAttachment> attachments)
        => new object[]
        {
            new { role = "system", content = systemInstruction },
            new
            {
                role = "user",
                content = providerInput,
                images = attachments.Select(value => value.DataBase64).ToArray()
            }
        };

    private static void ApplyWorkbenchAuthentication(
        HttpRequestMessage request,
        WorkbenchProviderBinding binding)
    {
        switch (binding.Authentication)
        {
            case ProviderControlAuth.Bearer:
                request.Headers.Authorization =
                    new System.Net.Http.Headers.AuthenticationHeaderValue(
                        "Bearer",
                        binding.ApiKey);
                break;
            case ProviderControlAuth.GoogleApiKeyHeader:
                request.Headers.Add("x-goog-api-key", binding.ApiKey);
                break;
            case ProviderControlAuth.AnthropicApiKeyHeader:
                request.Headers.Add("x-api-key", binding.ApiKey);
                request.Headers.Add("anthropic-version", "2023-06-01");
                break;
            case ProviderControlAuth.OptionalBearer:
            case ProviderControlAuth.LocalAiOptional:
            case ProviderControlAuth.UserDefined:
                if (!string.IsNullOrWhiteSpace(binding.ApiKey))
                {
                    request.Headers.Authorization =
                        new System.Net.Http.Headers.AuthenticationHeaderValue(
                            "Bearer",
                            binding.ApiKey);
                }
                break;
            case ProviderControlAuth.NoneByDefault:
                break;
            default:
                throw new InvalidOperationException(
                    "The selected Workbench authentication mode is unsupported.");
        }
    }

    private static string ExtractWorkbenchProviderText(
        ProviderControlProtocol protocol,
        JsonElement root)
    {
        if (protocol == ProviderControlProtocol.AnthropicMessages)
        {
            return root.TryGetProperty("content", out var content)
                ? string.Join("", content.EnumerateArray()
                    .Where(value => value.TryGetProperty("text", out _))
                    .Select(value => value.GetProperty("text").GetString()))
                : string.Empty;
        }
        if (protocol == ProviderControlProtocol.OllamaNativeChat)
        {
            return root.TryGetProperty("message", out var message)
                && message.TryGetProperty("content", out var ollamaText)
                ? ollamaText.GetString() ?? string.Empty
                : string.Empty;
        }
        if (protocol == ProviderControlProtocol.OpenAiResponses)
        {
            if (root.TryGetProperty("output_text", out var outputText))
                return outputText.GetString() ?? string.Empty;
            if (!root.TryGetProperty("output", out var output))
                return string.Empty;
            return string.Join("", output.EnumerateArray()
                .Where(value => value.TryGetProperty("content", out _))
                .SelectMany(value => value.GetProperty("content").EnumerateArray())
                .Where(value => value.TryGetProperty("text", out _))
                .Select(value => value.GetProperty("text").GetString()));
        }
        if (!root.TryGetProperty("choices", out var choices)
            || choices.GetArrayLength() == 0
            || !choices[0].TryGetProperty("message", out var openAiMessage)
            || !openAiMessage.TryGetProperty("content", out var openAiContent))
        {
            return string.Empty;
        }
        if (openAiContent.ValueKind == JsonValueKind.String)
            return openAiContent.GetString() ?? string.Empty;
        return openAiContent.ValueKind == JsonValueKind.Array
            ? string.Join("", openAiContent.EnumerateArray()
                .Where(value => value.TryGetProperty("text", out _))
                .Select(value => value.GetProperty("text").GetString()))
            : string.Empty;
    }

    private static async Task RequestWorkbenchImageGenerationAsync(
        PlayerTurnOperationHandle operation,
        string providerInput,
        string systemInstruction)
    {
        var binding = OpenWorkbenchImageGeminiBinding(operation);
        var payload = new Dictionary<string, object>
        {
            ["system_instruction"] = new
            {
                parts = new[]
                {
                    new
                    {
                        text = systemInstruction
                            + "\nThe player explicitly requested an image. "
                            + "Return the generated image and a short player-visible caption."
                    }
                }
            },
            ["contents"] = BuildWorkbenchGeminiContents(operation, providerInput),
            ["generationConfig"] = new
            {
                responseModalities = new[] { "TEXT", "IMAGE" }
            }
        };
        using var request = new HttpRequestMessage(HttpMethod.Post, binding.Url);
        request.Headers.Add("x-goog-api-key", binding.ApiKey);
        request.Content = new StringContent(
            JsonSerializer.Serialize(payload),
            Encoding.UTF8,
            "application/json");
        var lifecycle = new PlayerTurnPreparedProviderLifecycle(operation);
        lifecycle.MarkProviderStarting(
            "Gemini",
            operation.OperationId + "-workbench-image-1");
        string responseBody;
        try
        {
            using var response = await Http.SendAsync(request).ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    $"Gemini image HTTP {(int)response.StatusCode}: {responseBody}");
            }
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }

        using var document = JsonDocument.Parse(responseBody);
        var parts = document.RootElement
            .GetProperty("candidates")[0]
            .GetProperty("content")
            .GetProperty("parts");
        var caption = new StringBuilder();
        var images = new List<D045WorkbenchLiveAttachment>();
        long totalBytes = 0;
        foreach (var part in parts.EnumerateArray())
        {
            if (part.TryGetProperty("text", out var textPart))
                caption.Append(textPart.GetString());
            if (part.TryGetProperty("thought", out var thoughtPart)
                && thoughtPart.ValueKind == JsonValueKind.True)
            {
                continue;
            }
            if (!TryGetGeminiInlineImage(part, out var mediaType, out var data))
                continue;
            if (images.Count >= D045WorkbenchLiveProtocol.MaximumAttachments)
                throw new InvalidDataException("The image model returned too many images.");
            byte[] bytes;
            try
            {
                bytes = Convert.FromBase64String(data);
            }
            catch (FormatException exception)
            {
                throw new InvalidDataException(
                    "The image model returned invalid image encoding.",
                    exception);
            }
            try
            {
                totalBytes = checked(totalBytes + bytes.LongLength);
                if (bytes.Length is <= 0
                        or > D045WorkbenchLiveProtocol.MaximumAttachmentBytes
                    || totalBytes
                        > D045WorkbenchLiveProtocol.MaximumAttachmentAggregateBytes
                    || !HasSupportedImageSignature(mediaType, bytes))
                {
                    throw new InvalidDataException(
                        "The image model returned an unsupported image.");
                }
                var extension = mediaType switch
                {
                    "image/png" => "png",
                    "image/jpeg" => "jpg",
                    "image/webp" => "webp",
                    _ => throw new InvalidDataException(
                        "The image model returned an unsupported media type.")
                };
                images.Add(new D045WorkbenchLiveAttachment
                {
                    AttachmentId = Guid.NewGuid().ToString("N"),
                    FileName = "lilith-generated-"
                        + (images.Count + 1).ToString("D2", CultureInfo.InvariantCulture)
                        + "." + extension,
                    MediaType = mediaType,
                    Sha256 = Convert.ToHexString(SHA256.HashData(bytes)),
                    ByteLength = bytes.Length,
                    DataBase64 = Convert.ToBase64String(bytes)
                });
            }
            finally
            {
                CryptographicOperations.ZeroMemory(bytes);
            }
        }
        if (images.Count == 0)
            throw new InvalidDataException("The selected model returned no image.");
        CaptureWorkbenchGeneratedAttachments(
            operation,
            binding.ModelId,
            images);
        var visibleText = caption.ToString().Trim();
        if (visibleText.Length == 0)
        {
            visibleText = ApiKeyText(
                "圖片做好了。",
                "图片做好了。",
                "画像ができたよ。",
                "The image is ready.");
        }
        CompleteAiReply(
            visibleText,
            GetActiveWorkbenchRequest(operation)?.UserText ?? providerInput,
            PoseContext.Default,
            japaneseVoiceMode: false,
            operation);
    }

    private static bool TryGetGeminiInlineImage(
        JsonElement part,
        out string mediaType,
        out string data)
    {
        mediaType = string.Empty;
        data = string.Empty;
        if (!part.TryGetProperty("inlineData", out var inline)
            && !part.TryGetProperty("inline_data", out inline))
        {
            return false;
        }
        if (!inline.TryGetProperty("mimeType", out var mime)
            && !inline.TryGetProperty("mime_type", out mime))
        {
            return false;
        }
        if (!inline.TryGetProperty("data", out var encoded))
            return false;
        mediaType = mime.GetString() ?? string.Empty;
        data = encoded.GetString() ?? string.Empty;
        return mediaType is "image/png" or "image/jpeg" or "image/webp"
            && data.Length > 0;
    }

    private static bool HasSupportedImageSignature(string mediaType, byte[] bytes)
        => mediaType switch
        {
            "image/png" => bytes.Length >= 8
                && bytes.AsSpan(0, 8).SequenceEqual(
                    new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 }),
            "image/jpeg" => bytes.Length >= 4
                && bytes[0] == 0xFF && bytes[1] == 0xD8
                && bytes[^2] == 0xFF && bytes[^1] == 0xD9,
            "image/webp" => bytes.Length >= 12
                && bytes.AsSpan(0, 4).SequenceEqual(
                    new byte[] { 82, 73, 70, 70 })
                && bytes.AsSpan(8, 4).SequenceEqual(
                    new byte[] { 87, 69, 66, 80 }),
            _ => false
        };

    private static async Task SendGeminiAgentRequestAsync(GeminiAgentSession session)
    {
        if (session.Contents.Count == 0)
        {
            throw new InvalidOperationException(
                "Gemini agent contents cannot be empty.");
        }
        var agentLoop = session.CaptureAgentLoop();
        var finalizingVerifiedGoal =
            agentLoop.IsFinalizingVerifiedGoal;
        if (TryConsumeAgentOperationCancellation(
                session.Operation,
                out var operationCancellation))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentOperationCancellation(
                session.Operation,
                operationCancellation);
            return;
        }
        CancellationTokenSource? createdAgentDeadline = null;
        if ((session.ExplicitLocalAction || session.ToolRounds > 0)
            && !agentLoop
                .TryCreateDeadlineCancellationSource(
                    out createdAgentDeadline,
                    out var deadlineReason))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                InferAgentTaskStopReason(deadlineReason),
                deadlineReason,
                session.ActionGoal);
            return;
        }
        using var agentDeadline = createdAgentDeadline;
        var agentCancellationToken = agentDeadline?.Token
            ?? CancellationToken.None;
        var requiresHostApplicationLaunch =
            !finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && agentLoop.RequiresHostApplicationLaunch;
        var systemInstruction = finalizingVerifiedGoal
            ? VerifiedGoalFinalizationInstruction(
                session.SystemInstruction,
                agentLoop)
            : session.SystemInstruction;
        if (!finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && !requiresHostApplicationLaunch)
        {
            systemInstruction = systemInstruction.Replace(
                HostPreObservedApplicationContinuationInstruction,
                HostVerifiedApplicationContinuationInstruction,
                StringComparison.Ordinal);
        }
        var payload = new Dictionary<string, object>
        {
            ["system_instruction"] = new
            {
                parts = new[]
                {
                    new
                    {
                        text = systemInstruction
                    }
                }
            },
            ["contents"] = session.Contents,
            ["generationConfig"] = new
            {
                maxOutputTokens = session.HighReasoning ? 4096 : 1024,
                thinkingConfig = new
                {
                    thinkingLevel = session.HighReasoning ? "HIGH" : "MINIMAL"
                }
            }
        };
        if (!finalizingVerifiedGoal && session.DesktopToolsEnabled)
        {
            payload["tools"] = !requiresHostApplicationLaunch
                ? BuildGeminiDesktopTools(
                    session.UseGoogleSearch,
                    session.ToolManifest)
                : BuildGeminiHostApplicationEffectTools(
                    session.HostApplicationObservation!);
            if (session.ExplicitLocalAction)
            {
                payload["toolConfig"] = new
                {
                    functionCallingConfig = new
                    {
                        mode = "ANY",
                        allowedFunctionNames = !requiresHostApplicationLaunch
                            ? BuildAgentFunctionNames(session.ToolManifest)
                            : new[] { "run_local_task" }
                    }
                };
            }
            else if (session.UseGoogleSearch)
                payload["toolConfig"] = new { includeServerSideToolInvocations = true };
        }
        else if (!finalizingVerifiedGoal && session.UseGoogleSearch)
        {
            payload["tools"] = new object[] { new { googleSearch = new { } } };
        }

        using var request = new HttpRequestMessage(HttpMethod.Post, session.Url);
        request.Headers.Add("x-goog-api-key", session.ApiKey);
        request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json");
        RecordD029Signal(D029PluginSignal.ProviderCallStarted);
        var providerRequestId = session.Operation.OperationId
            + "-gemini-"
            + Interlocked.Increment(ref session.ProviderRequestSequence)
                .ToString(CultureInfo.InvariantCulture);
        var lifecycle =
            new PlayerTurnPreparedProviderLifecycle(session.Operation);
        lifecycle.MarkProviderStarting("Gemini", providerRequestId);
        string responseBody;
        try
        {
            using var response =
                await Http.SendAsync(request, agentCancellationToken)
                    .ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    $"Gemini HTTP {(int)response.StatusCode}: {responseBody}");
            }
        }
        catch (OperationCanceledException)
            when (agentDeadline?.IsCancellationRequested == true)
        {
            if (TryConsumeAgentOperationCancellation(
                    session.Operation,
                    out var cancellationKind))
            {
                if (finalizingVerifiedGoal
                    && CompleteVerifiedGoalFinalization(
                        agentLoop,
                        string.Empty,
                        session.UserText,
                        session.PoseContext,
                        session.JapaneseVoiceMode,
                        session.Operation))
                {
                    return;
                }
                CompleteAgentOperationCancellation(
                    session.Operation,
                    cancellationKind);
                return;
            }
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.DeadlineExpired,
                "The host-owned local-agent deadline expired during the "
                    + "provider request.",
                session.ActionGoal);
            return;
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }

        using var document = JsonDocument.Parse(responseBody);
        var candidate = document.RootElement.GetProperty("candidates")[0];
        var content = candidate.GetProperty("content");
        var parts = content.GetProperty("parts");
        var calls = new List<GeminiFunctionCallData>();
        var builder = new StringBuilder();
        foreach (var part in parts.EnumerateArray())
        {
            if (part.TryGetProperty("text", out var textPart))
                builder.Append(textPart.GetString());
            if (!part.TryGetProperty("functionCall", out var functionCall))
                continue;
            var name = functionCall.TryGetProperty("name", out var nameElement) ? nameElement.GetString() ?? string.Empty : string.Empty;
            var id = functionCall.TryGetProperty("id", out var idElement) ? idElement.GetString() ?? string.Empty : string.Empty;
            var args = functionCall.TryGetProperty("args", out var argsElement)
                ? argsElement.Clone()
                : JsonSerializer.SerializeToElement(new { });
            if (!string.IsNullOrWhiteSpace(name))
                calls.Add(new GeminiFunctionCallData { Name = name, Id = id, Args = args });
        }

        var finishReason = candidate.TryGetProperty("finishReason", out var finishElement)
            ? finishElement.GetString() ?? "UNKNOWN"
            : "UNKNOWN";
        var usageSummary = "unavailable";
        if (document.RootElement.TryGetProperty("usageMetadata", out var usage))
        {
            var promptTokens = usage.TryGetProperty("promptTokenCount", out var promptCount) ? promptCount.GetInt32() : -1;
            var outputTokens = usage.TryGetProperty("candidatesTokenCount", out var outputCount) ? outputCount.GetInt32() : -1;
            var thoughtTokens = usage.TryGetProperty("thoughtsTokenCount", out var thoughtCount) ? thoughtCount.GetInt32() : -1;
            usageSummary = $"prompt={promptTokens}, output={outputTokens}, thoughts={thoughtTokens}";
        }
        var grounded = candidate.TryGetProperty("groundingMetadata", out _);
        Plugin.PluginLog.LogInfo($"Gemini agent turn completed: model={session.ModelId}, highReasoning={session.HighReasoning}, finish={finishReason}, calls={calls.Count}, rawChars={builder.Length}, round={session.ToolRounds}, {usageSummary}, searchRequested={session.UseGoogleSearch}, grounded={grounded}.");

        if (finalizingVerifiedGoal)
        {
            CompleteVerifiedGoalFinalization(
                agentLoop,
                calls.Count == 0 ? builder.ToString() : string.Empty,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation);
            return;
        }

        if (calls.Count > 0)
        {
            session.Contents.Add(content.Clone());
            PendingGeminiToolBatches.Enqueue(new GeminiToolBatch { Session = session, Calls = calls });
            return;
        }

        if (CompleteExplicitActionWithoutVerifiedReceipt(
                session.ActionGoal,
                session.CaptureAgentLoop(),
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation))
        {
            return;
        }
        CompleteAiReply(builder.ToString(), session.UserText, session.PoseContext, session.JapaneseVoiceMode, session.Operation);
    }

    private static List<object> BuildHigherReasoningGeminiContents(
        string userText)
    {
        if (string.IsNullOrWhiteSpace(userText))
        {
            throw new InvalidOperationException(
                "Higher Reasoning requires the current player message.");
        }
        return new List<object>
        {
            new
            {
                role = "user",
                parts = new[] { new { text = userText } }
            }
        };
    }

    private static bool IsGeminiToolCompatibilityRejection(string message)
        => Regex.IsMatch(
                message,
                "Gemini HTTP (400|404|422)",
                RegexOptions.IgnoreCase)
            && Regex.IsMatch(
                message,
                "function.?call|function.?declaration|functionDeclarations|run_local_task|run_workstation_tool|toolConfig",
                RegexOptions.IgnoreCase);

    private static object[] BuildGeminiDesktopTools(
        bool includeGoogleSearch,
        D045AgentToolManifest manifest)
    {
        var declarations = new List<object>();
        if (HasLegacyManifestTools(manifest))
        {
            declarations.Add(new
            {
                name = "run_local_task",
                description = LegacyHarnessToolDescription(manifest),
                parameters = GeminiLegacyHarnessParameters(manifest)
            });
        }
        if (SupportsSemanticObservation(manifest))
        {
            declarations.Add(new
            {
                name = "observe_local_target",
                description = SemanticObservationToolDescription,
                parameters = GeminiSemanticObservationParameters()
            });
        }
        if (HasCodexManifestTools(manifest))
        {
            declarations.Add(new
            {
                name = D045CodexProviderToolContract.FunctionName,
                description = CodexWorkstationToolDescription(manifest),
                parameters = GeminiCodexWorkstationParameters(manifest)
            });
        }
        var tools = new List<object>();
        if (includeGoogleSearch)
            tools.Add(new { googleSearch = new { } });
        if (declarations.Count > 0)
            tools.Add(new { functionDeclarations = declarations.ToArray() });
        return tools.ToArray();
    }

