                },
                secondary_target = new
                {
                    type = "STRING",
                    description = "Exact destination path only for source-to-destination, archive, or HTTPS download recipes; otherwise omit."
                },
                payload = new
                {
                    type = "STRING",
                    description = "Literal content or typed action data only when the capability recipe requires it; never a concatenated shell command."
                },
                query = new
                {
                    type = "STRING",
                    description = "Bounded search or semantic query only when the capability recipe requires it."
