                },
                expected_sha256 = new
                {
                    type = "STRING",
                    description = "Expected 64-hex SHA-256 for download integrity or optimistic file modification."
                },
                recursive = new { type = "BOOLEAN" },
                maximum_results = new { type = "INTEGER" },
                maximum_depth = new { type = "INTEGER" },
                maximum_bytes = new { type = "INTEGER" },
                timeout_ms = new { type = "INTEGER" }
