    private static void ProcessGeminiToolBatches()
    {
        if (!PendingGeminiToolBatches.TryDequeue(out var batch))
            return;
        var agentLoop = batch.Session.CaptureAgentLoop();
        if (!TryAdmitQueuedAgentToolBatch(
                agentLoop,
                batch.Session.Operation,
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.ActionGoal))
        {
            return;
        }
        try
        {
            var outcome = ExecuteBoundedAgentToolBatch(
                agentLoop,
                batch.Calls,
                batch.Session.ActionGoal);
            batch.Session.ToolRounds = agentLoop.Rounds;
            var directive = ObserveAgentToolBatch(
                agentLoop,
                batch.Session.ActionGoal,
                outcome);

            var responseParts = new List<object>();
            foreach (var value in outcome.Results)
            {
                var result = value.Result;
                var functionResponse = new Dictionary<string, object>
                {
                    ["name"] = result.Name,
                    ["response"] =
                        BuildNormalizedProviderToolResult(result)
                };
                if (!string.IsNullOrWhiteSpace(result.Id))
                    functionResponse["id"] = result.Id;
                responseParts.Add(new Dictionary<string, object> { ["functionResponse"] = functionResponse });
            }
            batch.Session.Contents.Add(new { role = "user", parts = responseParts.ToArray() });
            if (directive == D045AgentTaskDirective.FinalizeWithoutTools)
            {
                CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation);
                return;
            }
            if (directive == D045AgentTaskDirective.Ignore)
                return;
            if (directive == D045AgentTaskDirective.PublishUnverifiedStop)
            {
                CompleteAgentTaskStop(
                    agentLoop,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation,
                    outcome.StopReasonKind,
                    outcome.StopReason,
                    batch.Session.ActionGoal);
                return;
            }
            _ = ContinueGeminiAgentRequestAsync(batch.Session);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Gemini desktop tool execution failed: {exception}");
            if (CompleteVerifiedGoalFinalization(
                    batch.Session.CaptureAgentLoop(),
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                batch.Session.CaptureAgentLoop(),
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.Operation,
                D045AgentTaskStopReason.ToolFailed,
                "The Gemini tool batch faulted before every required receipt "
                    + "was verified.",
                batch.Session.ActionGoal);
        }
    }

    private static void ProcessGeminiCompatibilityFallbacks()
    {
        if (!PendingGeminiCompatibilityFallbacks.TryDequeue(out var session))
            return;
        var agentLoop = session.CaptureAgentLoop();
        if (!TryAdmitQueuedAgentToolBatch(
                agentLoop,
                session.Operation,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.ActionGoal))
        {
            return;
        }
        try
        {
            if (session.ExplicitLocalAction)
            {
                CompleteAgentTaskStop(
                    agentLoop,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation,
                    D045AgentTaskStopReason.ExplicitActionUnsupported,
                    "The selected Gemini model rejected the required Harness "
                        + "function-calling protocol.",
                    session.ActionGoal);
                return;
            }
            session.DesktopToolsEnabled = false;
            session.SystemInstruction += "\nThe selected model or API version rejected Local Task Harness function calling. No legacy compatibility action may run. Do not claim that a computer action was performed; continue as ordinary conversation and explain that this action needs a Harness-capable provider.";
            _ = ContinueGeminiAgentRequestAsync(session);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Gemini compatibility fallback failed: {exception}");
            var reply = ApiKeyText("這個模型目前不能使用電腦工具。", "这个模型目前不能使用电脑工具。", "このモデルでは今、PCツールを使えないみたい。", "This model cannot use the computer tools right now.");
            CompleteBuiltInAgentAdapterShadow(reply, reply, session.JapaneseVoiceMode);
            EnqueuePlayerTurnReply(
                session.Operation,
                reply,
                string.Empty,
                PlayerTurnPublicationKind.FailureNotice,
                PlayerTurnTerminalDisposition.Failed,
                PlayerTurnFailureReason.ToolExecutionFailed);
        }
    }

    private static async Task ContinueGeminiAgentRequestAsync(GeminiAgentSession session)
    {
        try
        {
            await SendGeminiAgentRequestAsync(session).ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Gemini tool continuation failed: {exception}");
            if (CompleteVerifiedGoalFinalization(
                    session.CaptureAgentLoop(),
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                session.CaptureAgentLoop(),
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.ProviderFaultedBeforeVerification,
                "The Gemini continuation faulted before every required "
                    + "receipt was verified.",
                session.ActionGoal);
        }
    }

    private static GeminiToolResult ExecuteGeminiComputerTool(
        GeminiFunctionCallData call,
        TimeSpan remainingExecutionTime,
        LocalOpenTargetKind requiredOpenTargetKind,
        string expectedOpenLeaf,
        AgentLoopBudget budget)
    {
        if (call.ArgumentFailureCode.Length > 0)
        {
            return WorkstationRequestCorrection(
                call,
                Guid.NewGuid(),
                budget.ToolManifest.PermissionRevision,
                string.Empty,
                "provider_tool_arguments_rejected: "
                    + call.ArgumentFailureCode);
        }
        if (!HasAnyHarnessPermission())
            return ToolResult(call, false, ApiKeyText("進階電腦操作目前是關閉的。", "高级电脑操作目前已关闭。", "高度なPC操作は今オフになっているよ。", "Advanced PC controls are currently disabled."));
        if (!string.Equals(call.Name, "run_local_task", StringComparison.Ordinal)
            && !string.Equals(
                call.Name,
                D045CodexProviderToolContract.FunctionName,
                StringComparison.Ordinal))
            return ToolResult(call, false, "Legacy desktop tools are unavailable. Use the Local Task Harness.");
        try
        {
            switch (call.Name)
            {
                case "run_local_task":
                    return ExecuteLocalHarnessTool(
                        call,
                        remainingExecutionTime,
                        requiredOpenTargetKind,
                        expectedOpenLeaf,
                        budget);
                case D045CodexProviderToolContract.FunctionName:
                    return ExecuteCodexWorkstationTool(
                        call,
                        remainingExecutionTime,
                        budget);
                case "open_application":
                    return ExecuteOpenApplicationTool(call, GetToolString(call.Args, "name", 120));
                case "open_folder":
                    return ExecuteOpenFolderTool(call, GetToolString(call.Args, "folder", 40));
                case "window_action":
                    return ExecuteWindowTool(call, GetToolString(call.Args, "action", 40));
                case "media_control":
                    return ExecuteMediaTool(call, GetToolString(call.Args, "action", 40));
                case "copy_text":
                    return ExecuteCopyTextTool(call, GetToolString(call.Args, "text", 4000));
                case "browser_search":
                    return ExecuteBrowserSearchTool(call, GetToolString(call.Args, "query", 500));
                case "get_system_status":
                    return ExecuteSystemStatusTool(call, GetToolString(call.Args, "category", 40));
                case "keyboard_shortcut":
                    return ExecuteKeyboardShortcutTool(call, GetToolString(call.Args, "action", 40));
                case "set_timer":
                    return ExecuteSetTimerTool(call, GetToolDouble(call.Args, "minutes"), GetToolString(call.Args, "message", 160));
                case "cancel_timers":
                    var count = LocalTimers.Count;
                    LocalTimers.Clear();
                    _nextLocalTimerDeliveryAttempt = null;
                    _nextLocalTimerDeliveryFallbackAt = -1f;
                    ResetLocalTimerDeliveryRetryTelemetry();
                    return ToolResult(call, true, ApiKeyText($"已取消 {count} 個計時器。", $"已取消 {count} 个计时器。", $"{count}件のタイマーを取り消したよ。", $"Cancelled {count} timer(s)."));
                case "lock_computer":
                    _pendingSystemAction = new PendingSystemAction { Action = "lock", ExecuteAfter = Time.unscaledTime + 8f };
                    return ToolResult(call, true, ApiKeyText("已安排在回覆後鎖定電腦。", "已安排在回复后锁定电脑。", "返事のあとでPCをロックするね。", "The computer will lock after this reply."));
                case "sleep_computer":
                    _pendingSystemAction = new PendingSystemAction { Action = "sleep", ExecuteAfter = Time.unscaledTime + 8f };
                    return ToolResult(call, true, ApiKeyText("已安排在回覆後讓電腦睡眠。", "已安排在回复后让电脑睡眠。", "返事のあとでPCをスリープさせるね。", "The computer will sleep after this reply."));
                case "cancel_system_action":
                    var hadAction = _pendingSystemAction != null;
                    _pendingSystemAction = null;
                    return ToolResult(call, true, hadAction
                        ? ApiKeyText("已取消待執行的系統動作。", "已取消待执行的系统操作。", "待機中のシステム操作を取り消したよ。", "The pending system action was cancelled.")
                        : ApiKeyText("目前沒有待執行的系統動作。", "目前没有待执行的系统操作。", "待機中のシステム操作はないよ。", "There is no pending system action."));
                default:
                    return ToolResult(call, false, "Unknown or unavailable desktop tool.");
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Desktop tool '{call.Name}' failed: {exception.Message}");
            return ToolResult(call, false, $"The local action failed: {exception.Message}");
        }
    }

    private static GeminiToolResult ExecuteSemanticObservationTool(
        GeminiFunctionCallData call,
        AgentLoopBudget budget,
        LocalActionGoal remainingGoals)
    {
        var queryKindText = GetToolString(call.Args, "query_kind", 40)
            .Trim()
            .ToLowerInvariant();
        var queryKind = queryKindText switch
        {
            "resolve_local_target" =>
                D045SemanticLocalQueryKind.ResolveLocalTarget,
            "inspect_local_item" =>
                D045SemanticLocalQueryKind.InspectLocalItem,
            "query_application" =>
                D045SemanticLocalQueryKind.QueryApplication,
            _ => (D045SemanticLocalQueryKind)0
        };
        if (!Enum.IsDefined(typeof(D045SemanticLocalQueryKind), queryKind))
        {
            return SemanticObservationFailureResult(
                call,
                "unknown_semantic_query_kind");
        }

        var taskId = Guid.NewGuid();
        D045SemanticLocalPurpose purpose;
        D045SemanticHostResolvedTarget? redeemedTarget = null;
        if (queryKind == D045SemanticLocalQueryKind.InspectLocalItem)
        {
            var targetReference = GetToolString(call.Args, "target_ref", 96);
            if (!budget.TryCreateSemanticReferenceUse(
                    targetReference,
                    out var referenceUse))
            {
                return SemanticObservationFailureResult(
                    call,
                    "semantic_target_reference_not_found");
            }
            purpose = referenceUse!.Purpose;
            if (purpose is not D045SemanticLocalPurpose.ReadLocalFile
                and not D045SemanticLocalPurpose.EnumerateLocalFolder)
            {
                return SemanticObservationFailureResult(
                    call,
                    "semantic_inspection_purpose_rejected");
            }
            if (!LocalTaskHarness.TryRedeemTarget(
                    referenceUse,
                    out redeemedTarget,
                    out var referenceFailure))
            {
                return SemanticReferenceFailureResult(call, referenceFailure);
            }
            budget.RetireSemanticReference(targetReference);
        }
        else if (!TrySelectSemanticObservationPurpose(
                     queryKind,
                     remainingGoals,
                     budget.RequiredOpenTargetKind,
                     out purpose))
        {
            return SemanticObservationFailureResult(
                call,
                "semantic_query_does_not_match_remaining_goal");
        }

        var semanticQuery = GetToolString(call.Args, "query", 512);
        if (queryKind != D045SemanticLocalQueryKind.InspectLocalItem
            && !budget.SemanticTargetMatches(semanticQuery))
        {
            return SemanticObservationFailureResult(
                call,
                "semantic_query_does_not_match_player_target");
        }
        var request = new D045SemanticLocalObservationHostRequest(
            budget.OperationSessionId,
            taskId,
            queryKind,
            purpose,
            semanticQuery,
            redeemedTarget);
        var execution = LocalTaskHarness.ExecuteSemanticObservation(request);
        if (execution.Receipt is not null)
            budget.RegisterSemanticObservation(taskId, execution.Receipt);
        LogSemanticObservationExecution(
            "provider-tool",
            queryKind,
            execution);
        return ToolResultFromSemanticObservation(call, execution);
    }

    private static void LogSemanticObservationExecution(
        string source,
        D045SemanticLocalQueryKind queryKind,
        D045SemanticLocalObservationExecutionResult execution)
    {
        Plugin.PluginLog.LogInfo(
            "D-045 semantic observation completed: source="
            + source
            + ", queryKind="
            + queryKind
            + ", disposition="
            + execution.Disposition
            + ", candidates="
            + (execution.Receipt?.Candidates.Count ?? 0)
                .ToString(CultureInfo.InvariantCulture)
            + ", redeemable="
            + (execution.Receipt?.Candidates.Count(candidate =>
                    candidate.IsRedeemable) ?? 0)
                .ToString(CultureInfo.InvariantCulture)
            + ". Query and machine paths are omitted.");
    }

    private static bool TrySelectSemanticObservationPurpose(
        D045SemanticLocalQueryKind queryKind,
        LocalActionGoal remainingGoals,
        LocalOpenTargetKind openTargetKind,
        out D045SemanticLocalPurpose purpose)
    {
        purpose = default;
        if (queryKind == D045SemanticLocalQueryKind.QueryApplication)
        {
            if (!remainingGoals.HasFlag(LocalActionGoal.Open)
                || openTargetKind != LocalOpenTargetKind.Application)
            {
                return false;
            }
            purpose = D045SemanticLocalPurpose.LaunchApplication;
            return true;
        }
        if (queryKind != D045SemanticLocalQueryKind.ResolveLocalTarget)
            return false;
        if (remainingGoals.HasFlag(LocalActionGoal.ReadFile))
            purpose = D045SemanticLocalPurpose.ReadLocalFile;
        else if (remainingGoals.HasFlag(LocalActionGoal.EnumerateFolder))
            purpose = D045SemanticLocalPurpose.EnumerateLocalFolder;
        else if (remainingGoals.HasFlag(LocalActionGoal.Open)
            && openTargetKind == LocalOpenTargetKind.Application)
            purpose = D045SemanticLocalPurpose.LaunchApplication;
        else if (remainingGoals.HasFlag(LocalActionGoal.Open))
            purpose = D045SemanticLocalPurpose.OpenLocalContent;
        else
            return false;
        return true;
    }

    private static GeminiToolResult ToolResultFromSemanticObservation(
        GeminiFunctionCallData call,
        D045SemanticLocalObservationExecutionResult execution)
    {
        var receipt = execution.Receipt;
        return new GeminiToolResult
        {
            Name = call.Name,
            Id = call.Id,
            Success = execution.Disposition
                == D045SemanticObservationExecutionDisposition.ObservedUnique,
            Message = execution.ReasonCode,
            IsSemanticObservation = true,
            ObservationComplete = receipt?.Complete ?? false,
            ObservationAmbiguous = receipt?.Ambiguous ?? false,
            ObservationFailure = execution.Disposition
                == D045SemanticObservationExecutionDisposition.ObservedUnique
                    ? string.Empty
                    : execution.ReasonCode,
            ObservationFingerprint = receipt?.ObservationFingerprint
                ?? string.Empty,
            OutcomeReason = execution.Disposition switch
            {
                D045SemanticObservationExecutionDisposition.TargetNotFound =>
                    D045HarnessOutcomeReason.TargetNotFound,
                D045SemanticObservationExecutionDisposition.TargetAmbiguous =>
                    D045HarnessOutcomeReason.TargetAmbiguous,
                D045SemanticObservationExecutionDisposition.ObservedUnique =>
                    D045HarnessOutcomeReason.Unspecified,
                _ => D045HarnessOutcomeReason.InvalidRequest
            },
            PermissionRevision = receipt?.PermissionRevision ?? 0,
            Capability = receipt is null
                ? string.Empty
                : HarnessCapabilityToken(receipt.Capability),
            ObservationCandidates = receipt?.Candidates.Select(candidate =>
                new SemanticObservationCandidateResult
                {
                    TargetReference = candidate.OpaqueTargetReference,
                    SafeDisplayLeaf = candidate.SafeDisplayLeaf,
                    TargetKind = SemanticTargetKindToken(candidate.Kind),
                    SafeExtension = candidate.SafeExtension,
                    TargetFingerprint = candidate.TargetFingerprint,
                    DisplayLeafFingerprint = candidate.DisplayLeafFingerprint
                }).ToArray()
                ?? Array.Empty<SemanticObservationCandidateResult>()
        };
    }

    private static GeminiToolResult SemanticObservationFailureResult(
        GeminiFunctionCallData call,
        string reason)
        => new()
        {
            Name = call.Name,
            Id = call.Id,
            Success = false,
            Message = reason,
            IsSemanticObservation = true,
            ObservationFailure = reason
        };

    private static GeminiToolResult SemanticReferenceFailureResult(
        GeminiFunctionCallData call,
        D045SemanticTargetReferenceFailure failure)
        => new()
        {
            Name = call.Name,
            Id = call.Id,
            Success = false,
            Message = "semantic_target_reference_rejected: " + failure,
            ObservationFailure = "semantic_target_reference_rejected",
            OutcomeReason = D045HarnessOutcomeReason.InvalidRequest,
            RetryAllowed = false
        };

    private static bool TryRedeemSemanticEffectTarget(
        AgentLoopBudget budget,
        string targetReference,
        D045PermissionCapability capability,
        out string? canonicalTarget,
        out D045ExpectedTargetKind expectedTargetKind,
        out string hostIdentityFingerprint,
        out D045SemanticTargetReferenceFailure failure)
    {
        canonicalTarget = null;
        expectedTargetKind = D045ExpectedTargetKind.None;
        hostIdentityFingerprint = string.Empty;
        if (!budget.TryCreateSemanticReferenceUse(
                targetReference,
                out var use)
            || use!.Capability != capability)
        {
            failure = D045SemanticTargetReferenceFailure.WrongCapability;
            return false;
        }
        if (!LocalTaskHarness.TryRedeemTarget(
                use,
                out var resolved,
                out failure))
        {
            return false;
        }
        budget.RetireSemanticReference(targetReference);
        canonicalTarget = resolved!.CanonicalPath;
        expectedTargetKind = (D045ExpectedTargetKind)(int)resolved.Kind;
        hostIdentityFingerprint = resolved.HostIdentityFingerprint;
        return true;
    }

    private static string DesktopToolsUnavailableReply()
        => ApiKeyText(
            "目前沒有可用的 Local Task Harness 權限，或這個模型不支援 Harness；一般聊天仍可使用。",
            "当前没有可用的 Local Task Harness 权限，或这个模型不支持 Harness；普通聊天仍可使用。",
            "利用できる Local Task Harness 権限がないか、このモデルが Harness に対応していないよ。普通の会話は続けられる。",
            "No Local Task Harness capability is currently available, or this provider does not support Harness calls. Ordinary conversation is still available.");

    private static GeminiToolResult ExecuteCodexWorkstationTool(
        GeminiFunctionCallData call,
        TimeSpan remainingExecutionTime,
        AgentLoopBudget budget)
    {
        var taskId = Guid.NewGuid();
        if (!D045CodexProviderToolContract.TryParse(
                call.Args,
                budget.ToolManifest,
                taskId,
                budget.OperationSessionId,
                out var parsed,
                out var errorCode)
            || parsed is null)
        {
            Plugin.PluginLog.LogWarning(
                "D-045 C7 provider request was rejected before the Harness: "
                + "reason=" + errorCode
                + ". Arguments, targets and payload are omitted from logs.");
            return WorkstationRequestCorrection(
                call,
                taskId,
                budget.ToolManifest.PermissionRevision,
                string.Empty,
                "workstation_request_rejected: " + errorCode);
        }
        if (!budget.IsCodexCapabilityRequired(parsed.Capability))
        {
            return WorkstationRequestRejection(
                call,
                taskId,
                budget.ToolManifest.PermissionRevision,
                HarnessCapabilityToken(parsed.Capability),
                "workstation_capability_not_required_by_host_plan");
        }
        if (budget.TryGetPendingCodexCapabilityPrerequisite(
                parsed.Capability,
                out var prerequisite))
        {
            return WorkstationRequestCorrection(
                call,
                taskId,
                budget.ToolManifest.PermissionRevision,
                HarnessCapabilityToken(parsed.Capability),
                "workstation_prerequisite_not_verified:"
                    + HarnessCapabilityToken(prerequisite));
        }

        var remainingMilliseconds = (int)Math.Min(
            int.MaxValue,
            Math.Floor(remainingExecutionTime.TotalMilliseconds));
        if (remainingMilliseconds < 1_000)
        {
            return ToolResult(
                call,
                false,
                "The bounded workstation deadline expired before execution.");
        }
        var timeout = Math.Min(
            parsed.TimeoutMilliseconds,
            remainingMilliseconds);
        D045CodexCapabilityRequest request;
        if (parsed.Capability
            == D045PermissionCapability.ExternalAppSemanticUiInspect)
        {
            if (!budget.TryGetVerifiedHostApplicationWindowTarget(
                    out var exactHostWindowTarget))
            {
                return WorkstationRequestRejection(
                    call,
                    taskId,
                    budget.ToolManifest.PermissionRevision,
                    HarnessCapabilityToken(parsed.Capability),
                    "workstation_host_window_not_verified");
            }
            try
            {
                request = D045CodexProviderToolContract
                    .CanonicalizeHostBoundSemanticUiInspect(
                        parsed,
                        exactHostWindowTarget,
                        timeout);
            }
            catch (ArgumentException)
            {
                return WorkstationRequestRejection(
                    call,
                    taskId,
                    budget.ToolManifest.PermissionRevision,
                    HarnessCapabilityToken(parsed.Capability),
                    "workstation_host_window_target_mismatch");
            }
        }
        else
        {
            request = new D045CodexCapabilityRequest(
                parsed.TaskId,
                parsed.Capability,
                parsed.Operation,
                parsed.Target,
                parsed.SecondaryTarget,
                parsed.Payload,
                parsed.Query,
                parsed.WorkingDirectory,
                parsed.ExpectedSha256,
                parsed.OwnerId,
                parsed.Arguments,
                parsed.Recursive,
                parsed.MaximumResults,
                parsed.MaximumDepth,
                parsed.MaximumBytes,
                timeout,
                parsed.ExpectedPermissionRevision);
        }
        var receipt = CodexCapabilityHarness.Execute(
            request,
            budget.TryAdmitEffectDispatch);
        var message = receipt.Message;
        if (!string.IsNullOrWhiteSpace(receipt.Output))
            message += "\n" + receipt.Output;
        if (!string.IsNullOrWhiteSpace(receipt.JobId))
            message += "\njob_id=" + receipt.JobId;
        Plugin.PluginLog.LogInfo(
            "D-045 C7 receipt: capability="
            + HarnessCapabilityToken(receipt.Capability)
            + ", attempted=" + receipt.Attempted
            + ", verified=" + receipt.Verified
            + ", reason=" + receipt.OutcomeReason
            + ", postcondition=" + receipt.Postcondition
            + ", request=" + FingerprintPrefix(receipt.RequestFingerprint)
            + ", outcome=" + FingerprintPrefix(receipt.OutcomeFingerprint)
            + ". Targets and output are omitted from logs.");
        var safeBoundCorrectionAllowed = !receipt.Attempted
            && receipt.OutcomeReason
                == D045CodexOutcomeReason.OutputLimitExceeded;
        return new GeminiToolResult
        {
            Name = call.Name,
            Id = call.Id,
            Success = receipt.Verified,
            Message = message,
            HasHarnessReceipt = true,
            TaskId = receipt.TaskId.ToString("N", CultureInfo.InvariantCulture),
            Capability = HarnessCapabilityToken(receipt.Capability),
            Attempted = receipt.Attempted,
            Verified = receipt.Verified,
            ExitCode = receipt.ExitCode,
            RequestFingerprint = receipt.RequestFingerprint,
            OutcomeFingerprint = receipt.OutcomeFingerprint,
            PermissionRevision = receipt.PermissionRevision,
            ContentSha256 = receipt.ContentSha256,
            JobId = receipt.JobId,
            TypedOutcomeReason = receipt.OutcomeReason.ToString(),
            TypedPostcondition = receipt.Postcondition.ToString(),
            OutcomeReason = MapCodexOutcomeReason(receipt.OutcomeReason),
            VerificationStrength = receipt.Verified
                ? D045HarnessVerificationStrength.DeterministicPostcondition
                : receipt.EffectPossiblyApplied
                    ? D045HarnessVerificationStrength.EffectPossiblyApplied
                    : receipt.Attempted
                        ? D045HarnessVerificationStrength.PreconditionsValidated
                        : D045HarnessVerificationStrength.None,
            PostconditionCode = MapCodexPostcondition(receipt.Postcondition),
            RetryAllowed = safeBoundCorrectionAllowed,
            RetryRequiresChangedTarget = false,
            EffectPossiblyApplied = receipt.EffectPossiblyApplied
        };
    }

    private static GeminiToolResult WorkstationRequestRejection(
        GeminiFunctionCallData call,
        Guid taskId,
        long permissionRevision,
        string capability,
        string reason)
    {
        var requestMaterial = call.Args.ValueKind == JsonValueKind.Undefined
            ? "{}"
            : call.Args.GetRawText();
        var requestFingerprint = Convert.ToHexString(SHA256.HashData(
            Encoding.UTF8.GetBytes(requestMaterial)));
        var outcomeFingerprint = Convert.ToHexString(SHA256.HashData(
            Encoding.UTF8.GetBytes(requestFingerprint + "|" + reason)));
        return new GeminiToolResult
        {
            Name = call.Name,
            Id = call.Id,
            Success = false,
            Message = reason,
            HasHarnessReceipt = true,
            TaskId = taskId.ToString("N", CultureInfo.InvariantCulture),
            Capability = capability,
            Attempted = false,
            Verified = false,
            RequestFingerprint = requestFingerprint,
            OutcomeFingerprint = outcomeFingerprint,
            PermissionRevision = permissionRevision,
            TypedOutcomeReason = D045CodexOutcomeReason.InvalidRequest
                .ToString(),
            TypedPostcondition = D045CodexPostcondition.None.ToString(),
            OutcomeReason = D045HarnessOutcomeReason.InvalidRequest,
            VerificationStrength = D045HarnessVerificationStrength.None,
            PostconditionCode = D045HarnessPostconditionCode.None,
            RetryAllowed = false,
            RetryRequiresChangedTarget = false,
            EffectPossiblyApplied = false
        };
    }

    private static GeminiToolResult WorkstationRequestCorrection(
        GeminiFunctionCallData call,
        Guid taskId,
        long permissionRevision,
        string capability,
        string reason)
    {
        var requestMaterial = call.Args.ValueKind == JsonValueKind.Undefined
            ? "{}"
            : call.Args.GetRawText();
        return new GeminiToolResult
        {
            Name = call.Name,
            Id = call.Id,
            Success = false,
            Message = reason + ". Correct the typed fields once; do not repeat "
                + "the same request.",
            HasHarnessReceipt = false,
            TaskId = taskId.ToString("N", CultureInfo.InvariantCulture),
            Capability = capability,
            Attempted = false,
            Verified = false,
            RequestFingerprint = Convert.ToHexString(SHA256.HashData(
                Encoding.UTF8.GetBytes(requestMaterial))),
            PermissionRevision = permissionRevision,
            TypedOutcomeReason = D045CodexOutcomeReason.InvalidRequest
                .ToString(),
            TypedPostcondition = D045CodexPostcondition.None.ToString(),
            OutcomeReason = D045HarnessOutcomeReason.InvalidRequest,
            VerificationStrength = D045HarnessVerificationStrength.None,
            PostconditionCode = D045HarnessPostconditionCode.None,
            RetryAllowed = true,
            RetryRequiresChangedTarget = false,
            EffectPossiblyApplied = false
        };
    }

    private static D045HarnessOutcomeReason MapCodexOutcomeReason(
        D045CodexOutcomeReason reason)
        => reason switch
        {
            D045CodexOutcomeReason.EffectVerified =>
                D045HarnessOutcomeReason.EffectVerified,
            D045CodexOutcomeReason.PermissionDefaultOff
                or D045CodexOutcomeReason.PermissionCompositionMissing =>
                D045HarnessOutcomeReason.PermissionDefaultOff,
            D045CodexOutcomeReason.PermissionChangedBeforeAttempt =>
                D045HarnessOutcomeReason.PermissionChangedBeforeAttempt,
            D045CodexOutcomeReason.PermissionChangedAfterAttempt =>
                D045HarnessOutcomeReason.PermissionChangedAfterAttempt,
            D045CodexOutcomeReason.RequestAlreadyConsumed =>
                D045HarnessOutcomeReason.TaskAlreadyConsumed,
            D045CodexOutcomeReason.TargetNotFound =>
                D045HarnessOutcomeReason.TargetNotFound,
            D045CodexOutcomeReason.TargetAmbiguous =>
                D045HarnessOutcomeReason.TargetAmbiguous,
            D045CodexOutcomeReason.Timeout => D045HarnessOutcomeReason.Timeout,
            D045CodexOutcomeReason.InvalidRequest
                or D045CodexOutcomeReason.TargetAlreadyExists
                or D045CodexOutcomeReason.TargetUnsafe
                or D045CodexOutcomeReason.Unsupported
                or D045CodexOutcomeReason.IntegrityMismatch =>
                D045HarnessOutcomeReason.InvalidRequest,
            _ => D045HarnessOutcomeReason.ToolFailure
        };

    private static D045HarnessPostconditionCode MapCodexPostcondition(
        D045CodexPostcondition postcondition)
        => postcondition switch
        {
            D045CodexPostcondition.BoundedReadComplete =>
                D045HarnessPostconditionCode.ReadResultBounded,
            D045CodexPostcondition.ClipboardContentMatches
                or D045CodexPostcondition.TargetContentMatches
                or D045CodexPostcondition.ArchiveValidated
                or D045CodexPostcondition.WindowStateMatches
                or D045CodexPostcondition.HttpsBodyDigestMatches =>
                D045HarnessPostconditionCode.TargetContentStable,
            D045CodexPostcondition.TargetExists
                or D045CodexPostcondition.SourceAbsentAndTargetExists =>
                D045HarnessPostconditionCode.TargetExists,
            D045CodexPostcondition.ProcessRunning =>
                D045HarnessPostconditionCode.ProcessRunning,
            D045CodexPostcondition.ProcessExitCodeZero =>
                D045HarnessPostconditionCode.ProcessExitCodeZero,
            D045CodexPostcondition.ProcessExited =>
                D045HarnessPostconditionCode.ProcessExited,
            D045CodexPostcondition.DispatchAccepted =>
                D045HarnessPostconditionCode.DispatchAccepted,
            _ => D045HarnessPostconditionCode.None
        };

    private static GeminiToolResult ExecuteLocalHarnessTool(
        GeminiFunctionCallData call,
        TimeSpan remainingExecutionTime,
        LocalOpenTargetKind requiredOpenTargetKind,
        string expectedOpenLeaf,
        AgentLoopBudget budget)
    {
        var capabilityText = GetToolString(call.Args, "capability", 80);
        if (!TryParseHarnessCapability(capabilityText, out var capability))
            return ToolResult(call, false, "Unknown Local Task Harness capability.");
        if (budget.TryGetPendingCodexCapabilityPrerequisite(
                capability,
                out var prerequisite))
        {
            return ToolResult(
                call,
                false,
                "This effect was rejected before the Harness because the "
                    + "host-owned task sequence requires a verified "
                    + HarnessCapabilityToken(prerequisite)
                    + " receipt first.");
        }

        var timeout = 30000;
        try
        {
            var requestedTimeout = GetToolDouble(call.Args, "timeout_ms");
            if (!double.IsNaN(requestedTimeout) && requestedTimeout > 0)
                timeout = Math.Clamp((int)requestedTimeout, 1000, 120000);
        }
        catch
        {
            timeout = 30000;
        }
        var remainingMilliseconds = (int)Math.Min(
            int.MaxValue,
            Math.Floor(remainingExecutionTime.TotalMilliseconds));
        if (remainingMilliseconds < 1000)
        {
            return ToolResult(
                call,
                false,
                "The bounded local agent deadline expired before the Harness "
                    + "could start another safe attempt.");
        }
        timeout = Math.Min(timeout, remainingMilliseconds);

        var requestedTarget = GetToolString(call.Args, "target", 32768);
        var requestedSecondaryTarget =
            GetToolString(call.Args, "secondary_target", 4096);
        var requestedPayload = GetToolString(call.Args, "payload", 65536);
        if (capability == D045PermissionCapability.LocalDataCreate)
        {
            requestedSecondaryTarget = requestedSecondaryTarget
                .Trim()
                .ToLowerInvariant() switch
                {
                    "text" or "text_file" => "file",
                    "folder" => "directory",
                    var value => value
                };
            if (requestedSecondaryTarget is not ("file" or "directory"))
            {
                return ToolResult(
                    call,
                    false,
                    "local_data_create requires secondary_target to be the literal kind token file or directory; it is never a path. No effect was attempted.");
            }
        }
        var usedSemanticReference = false;
        var redeemedExpectedTargetKind = D045ExpectedTargetKind.None;
        var redeemedHostIdentityFingerprint = string.Empty;
        if (requestedTarget.StartsWith("d045ref_", StringComparison.Ordinal))
        {
            if (requestedSecondaryTarget.Length != 0
                || requestedPayload.Length != 0)
            {
                return ToolResult(
                    call,
                    false,
                    "An opaque semantic target reference accepts no secondary target or payload.");
            }
            if (!TryRedeemSemanticEffectTarget(
                    budget,
                    requestedTarget,
                    capability,
                    out var redeemedTarget,
                    out redeemedExpectedTargetKind,
                    out redeemedHostIdentityFingerprint,
                    out var referenceFailure))
            {
                return SemanticReferenceFailureResult(
                    call,
                    referenceFailure);
            }
            requestedTarget = redeemedTarget!;
            usedSemanticReference = true;
            Plugin.PluginLog.LogInfo(
                "D-045 semantic target handoff admitted: capability="
                + HarnessCapabilityToken(capability)
                + ", semanticRefRedeemed=true. Reference value and machine path are omitted.");
        }
        if (capability == D045PermissionCapability.ApplicationLaunch
            && !usedSemanticReference)
        {
            return ToolResult(
                call,
                false,
                "Application launch requires the opaque target reference from the host-owned semantic observation; direct application names and paths are rejected.");
        }
        if (!budget.TryAdmitHostEffectTarget(
                capability,
                requestedTarget,
                requestedSecondaryTarget,
                requestedPayload,
                out var goalTargetFingerprint,
                out var targetAdmissionReason))
        {
            return ToolResult(call, false, targetAdmissionReason);
        }

        var request = new D045HarnessRequest(
            Guid.NewGuid(),
            capability,
            requestedTarget,
            requestedSecondaryTarget,
            requestedPayload,
            timeout,
            expectedTargetKind: usedSemanticReference
                ? redeemedExpectedTargetKind
                : capability switch
                {
                    D045PermissionCapability.LocalContentOpen =>
                        ToHarnessExpectedTargetKind(requiredOpenTargetKind),
                    D045PermissionCapability.LocalFileRead =>
                        D045ExpectedTargetKind.File,
                    D045PermissionCapability.LocalFolderEnumerate =>
                        D045ExpectedTargetKind.Directory,
                    D045PermissionCapability.ApplicationLaunch =>
                        D045ExpectedTargetKind.Application,
                    _ => D045ExpectedTargetKind.None
                },
            expectedLeafName: capability
                is D045PermissionCapability.LocalContentOpen
                    or D045PermissionCapability.LocalFileRead
                    ? expectedOpenLeaf
                    : string.Empty,
            expectedPermissionRevision:
                budget.AdmittedPermissionRevision,
            expectedHostIdentityFingerprint:
                redeemedHostIdentityFingerprint,
            requireVisibleApplicationWindowTarget:
                capability == D045PermissionCapability.ApplicationLaunch
                && budget.RequiresVisibleHostApplicationWindowTarget);
        var receipt = LocalTaskHarness.Execute(
            request,
            budget.TryAdmitEffectDispatch);
        var message = receipt.Message;
        var providerOutput = usedSemanticReference
            ? SafeSemanticEffectOutput(capability, receipt.Output)
            : receipt.Output;
        if (!string.IsNullOrWhiteSpace(providerOutput))
            message += "\n" + providerOutput;
        Plugin.PluginLog.LogInfo(
            $"D-045 Harness receipt task={receipt.TaskId:N}, capability={receipt.Capability}, attempted={receipt.Attempted}, verified={receipt.Verified}, exit={receipt.ExitCode}, request={FingerprintPrefix(receipt.RequestFingerprint)}, target={FingerprintPrefix(receipt.ResolvedTargetFingerprint)}, outcome={FingerprintPrefix(receipt.OutcomeFingerprint)}.");
        var result = ToolResultFromHarnessReceipt(call, receipt, message);
        if (capability == D045PermissionCapability.ApplicationLaunch
            && receipt.Verified
            && (D045ExactWindowTarget.TryParse(
                    receipt.Output,
                    out _,
                    out _)
                || int.TryParse(
                    receipt.Output,
                    NumberStyles.None,
                    CultureInfo.InvariantCulture,
                    out var launchedProcessId)
                    && launchedProcessId > 0))
        {
            result.ApplicationProcessId = receipt.Output;
        }
        result.GoalTargetFingerprint = goalTargetFingerprint;
        return result;
    }

    private static string SafeSemanticEffectOutput(
        D045PermissionCapability capability,
        string output)
    {
        if (string.IsNullOrWhiteSpace(output))
            return string.Empty;
        if (capability == D045PermissionCapability.LocalFileRead)
        {
            // File content is the explicitly authorized result. The host path
            // remains absent from the provider-visible receipt projection.
            return output;
        }
        if (capability != D045PermissionCapability.LocalFolderEnumerate)
            return string.Empty;

        var safe = new List<string>();
        foreach (var line in output.Split(
                     new[] { '\r', '\n' },
                     StringSplitOptions.RemoveEmptyEntries))
        {
            if (line.StartsWith("kind=", StringComparison.Ordinal)
                || line.StartsWith("extension=", StringComparison.Ordinal))
            {
                safe.Add(line);
                continue;
            }
            if (!line.StartsWith("entry=", StringComparison.Ordinal))
                continue;
            try
            {
                using var parsed = JsonDocument.Parse(line["entry=".Length..]);
                var root = parsed.RootElement;
                safe.Add("entry=" + JsonSerializer.Serialize(new
                {
                    kind = root.TryGetProperty("kind", out var kind)
                        ? kind.GetString() ?? "unknown"
                        : "unknown",
                    extension = root.TryGetProperty(
                            "extension",
                            out var extension)
                        ? extension.GetString() ?? "none"
                        : "none",
                    name = root.TryGetProperty("name", out var name)
                        ? name.GetString() ?? "local-item"
                        : "local-item"
                }));
            }
            catch (JsonException)
            {
                // Malformed legacy output is omitted rather than leaking a
                // canonical path that the semantic reference concealed.
            }
        }
        return string.Join("\n", safe);
    }

    private static bool TryParseHarnessCapability(
        string value,
        out D045PermissionCapability capability)
    {
        return D045CapabilityDescriptorCatalog.TryResolveExactToolToken(
                value.Trim().ToLowerInvariant(),
                out capability)
            && (int)capability is >= 1 and <= 20;
    }

    private static D045ExpectedTargetKind ToHarnessExpectedTargetKind(
        LocalOpenTargetKind kind)
        => kind switch
        {
            LocalOpenTargetKind.File => D045ExpectedTargetKind.File,
            LocalOpenTargetKind.Directory => D045ExpectedTargetKind.Directory,
            LocalOpenTargetKind.Application => D045ExpectedTargetKind.Application,
            _ => D045ExpectedTargetKind.None
        };

    private static GeminiToolResult ExecuteOpenApplicationTool(GeminiFunctionCallData call, string name)
    {
        if (string.IsNullOrWhiteSpace(name) || Regex.IsMatch(name, "[\\\\/:*?\"<>|]"))
            return ToolResult(call, false, "A safe application name was not provided.");
        if (TryFocusRunningApplication(name))
            return ToolResult(call, true, ApiKeyText($"已切換到{name}。", $"已切换到{name}。", $"{name}に切り替えたよ。", $"Focused {name}."));
        var registered = FindConfiguredApplication(name) ?? FindOfficialApplication(name);
        if (registered != null)
        {
            Process.Start(new ProcessStartInfo(registered.Target)
            {
                Arguments = registered.Arguments ?? string.Empty,
                UseShellExecute = true
            });
            Plugin.PluginLog.LogInfo($"Opened registered allowlisted application '{registered.Name}'.");
            return ToolResult(call, true, ApiKeyText($"已開啟{registered.Name}。", $"已打开{registered.Name}。", $"{registered.Name}を開いたよ。", $"Opened {registered.Name}."));
        }
        var startApplication = ResolveWindowsStartApplication(name);
        if (startApplication != null && TryLaunchWindowsStartApplication(startApplication))
            return ToolResult(call, true, ApiKeyText($"正在開啟{startApplication.Name}。", $"正在打开{startApplication.Name}。", $"{startApplication.Name}を開いているよ。", $"Opening {startApplication.Name}."));
        var shortcut = ResolveWindowsShortcut(new[] { name });
        if (string.IsNullOrWhiteSpace(shortcut))
            shortcut = ResolveFuzzyWindowsShortcut(name);
        if (string.IsNullOrWhiteSpace(shortcut))
        {
            if (TryLaunchApplicationCommand("開啟 " + name, out var builtInReply))
                return ToolResultFromReply(call, builtInReply);
            return ToolResult(call, false, ApiKeyText($"沒有在這台電腦找到{name}。", $"没有在这台电脑找到{name}。", $"このPCでは{name}を見つけられなかった。", $"I couldn't find {name} on this PC."));
        }
        Process.Start(new ProcessStartInfo(shortcut) { UseShellExecute = true });
        Plugin.PluginLog.LogInfo($"Opened an installed application from a Windows shortcut named '{Path.GetFileNameWithoutExtension(shortcut)}'.");
        return ToolResult(call, true, ApiKeyText($"已開啟{name}。", $"已打开{name}。", $"{name}を開いたよ。", $"Opened {name}."));
    }

