        => kind switch
        {
            D045ExpectedTargetKind.File => "file",
            D045ExpectedTargetKind.Directory => "directory",
            D045ExpectedTargetKind.Application => "application",
            _ => "none"
        };

    private static string SemanticTargetKindToken(
        D045SemanticLocalTargetKind kind)
        => kind switch
        {
            D045SemanticLocalTargetKind.File => "file",
            D045SemanticLocalTargetKind.Directory => "directory",
            D045SemanticLocalTargetKind.Application => "application",
            _ => "unknown"
        };

    private static string FingerprintPrefix(string value)
        => string.IsNullOrWhiteSpace(value)
            ? "-"
            : value[..Math.Min(12, value.Length)];

    private static string GetToolString(JsonElement args, string name, int maximumLength)
    {
        if (args.ValueKind != JsonValueKind.Object || !args.TryGetProperty(name, out var value) || value.ValueKind != JsonValueKind.String)
            return string.Empty;
        var text = value.GetString()?.Trim() ?? string.Empty;
        return text.Length <= maximumLength ? text : text[..maximumLength];
    }

    private static double GetToolDouble(JsonElement args, string name)
    {
        if (args.ValueKind != JsonValueKind.Object || !args.TryGetProperty(name, out var value))
            return double.NaN;
        if (value.ValueKind == JsonValueKind.Number && value.TryGetDouble(out var number))
            return number;
        return value.ValueKind == JsonValueKind.String && double.TryParse(value.GetString(), NumberStyles.Float, CultureInfo.InvariantCulture, out number)
            ? number
            : double.NaN;
    }

    private static async Task RequestQwenResponsesAsync(string systemInstruction, string userText,
        PoseContext poseContext, bool japaneseVoiceMode, bool useWebSearch, bool forceWebSearch,
        bool desktopToolsEnabled, PlayerTurnOperationHandle operation,
        LocalActionGoal admittedActionGoal,
        LocalOpenTargetKind admittedOpenTargetKind,
        string admittedExpectedOpenLeaf,
        string admittedExpectedSemanticTarget,
        HostEffectTargetDescriptor? admittedHostEffectTarget,
        long admittedPermissionRevision,
        HostApplicationPreObservation? hostApplicationObservation,
        D045CodexTaskPlan codexTaskPlan,
        D045AgentToolManifest toolManifest)
    {
        var baseUrl = NormalizeQwenBaseUrl(Plugin.QwenBaseUrl.Value);
        var session = new QwenAgentSession
        {
            Url = baseUrl + "/responses",
            SystemInstruction = systemInstruction,
            UserText = userText,
            PoseContext = poseContext,
            JapaneseVoiceMode = japaneseVoiceMode,
            UseWebSearch = useWebSearch,
            ForceWebSearch = forceWebSearch,
            DesktopToolsEnabled = desktopToolsEnabled,
            ExplicitLocalAction = admittedActionGoal != LocalActionGoal.None,
            ActionGoal = admittedActionGoal,
            OpenTargetKind = admittedOpenTargetKind,
            ExpectedOpenLeaf = admittedExpectedOpenLeaf,
            ExpectedSemanticTarget = admittedExpectedSemanticTarget,
            HostEffectTarget = admittedHostEffectTarget,
            PermissionRevision = admittedPermissionRevision,
            HostApplicationObservation = hostApplicationObservation,
            CodexTaskPlan = codexTaskPlan,
            ToolManifest = toolManifest,
            Operation = operation,
            Input = BuildQwenInput().ToList()
        };
        try
        {
            await SendQwenAgentRequestAsync(session).ConfigureAwait(false);
        }
        catch when (session.ExplicitLocalAction)
        {
            if (!CompleteVerifiedGoalFinalization(
                    session.CaptureAgentLoop(),
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                CompleteAgentTaskStop(
                    session.CaptureAgentLoop(),
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation,
                    D045AgentTaskStopReason.ProviderFaultedBeforeVerification,
                    "The Qwen provider faulted before every required receipt "
                        + "was verified.",
                    session.ActionGoal);
            }
        }
    }

    private static object[] BuildQwenInput()
    {
        var input = new List<object>();
        lock (MemoryLock)
        {
            foreach (var turn in RecentConversation)
                input.Add(new { role = turn.Role == "model" ? "assistant" : "user", content = turn.Text });
        }
        return input.ToArray();
    }

    private static async Task SendQwenAgentRequestAsync(QwenAgentSession session)
    {
        var agentLoop = session.CaptureAgentLoop();
        var finalizingVerifiedGoal =
            agentLoop.IsFinalizingVerifiedGoal;
        if (TryConsumeAgentOperationCancellation(
                session.Operation,
                out var operationCancellation))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentOperationCancellation(
                session.Operation,
                operationCancellation);
            return;
        }
        CancellationTokenSource? createdAgentDeadline = null;
        if ((session.ExplicitLocalAction || session.ToolRounds > 0)
            && !agentLoop
                .TryCreateDeadlineCancellationSource(
                    out createdAgentDeadline,
                    out var deadlineReason))
        {
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                InferAgentTaskStopReason(deadlineReason),
                deadlineReason,
                session.ActionGoal);
            return;
        }
        using var agentDeadline = createdAgentDeadline;
        var agentCancellationToken = agentDeadline?.Token
            ?? CancellationToken.None;
        var requestTimer = Stopwatch.StartNew();
        var requiresHostApplicationLaunch =
            !finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && agentLoop.RequiresHostApplicationLaunch;
        var systemInstruction = finalizingVerifiedGoal
            ? VerifiedGoalFinalizationInstruction(
                session.SystemInstruction,
                agentLoop)
            : session.SystemInstruction;
        if (!finalizingVerifiedGoal
            && session.HostApplicationObservation is not null
            && !requiresHostApplicationLaunch)
        {
            systemInstruction = systemInstruction.Replace(
                HostPreObservedApplicationContinuationInstruction,
                HostVerifiedApplicationContinuationInstruction,
                StringComparison.Ordinal);
        }
        var payload = new Dictionary<string, object>
        {
            ["model"] = Plugin.QwenModel.Value.Trim(),
            ["instructions"] = systemInstruction,
            ["input"] = session.Input,
            ["max_output_tokens"] = 1536,
            ["store"] = false,
            ["reasoning"] = new { effort = "none" }
        };
        var tools = finalizingVerifiedGoal
            ? Array.Empty<object>()
            : requiresHostApplicationLaunch
                ? BuildQwenHostApplicationEffectTools(
                    session.HostApplicationObservation!)
                : BuildQwenTools(
                    session.UseWebSearch,
                    session.ForceWebSearch
                        ? false
                        : session.DesktopToolsEnabled,
                    session.ToolManifest);
        if (tools.Length > 0)
            payload["tools"] = tools;
        if (tools.Length > 0
            && !finalizingVerifiedGoal
            && (session.ForceWebSearch || session.ExplicitLocalAction))
            payload["tool_choice"] = "required";

        using var request = new HttpRequestMessage(HttpMethod.Post, session.Url);
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue(
            "Bearer",
            Plugin.RetiredLegacyPlaintextProviderCredential(
                Plugin.QwenApiKey).Trim());
        request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json");
        var providerRequestId = session.Operation.OperationId
            + "-qwen-"
            + Interlocked.Increment(ref session.ProviderRequestSequence)
                .ToString(CultureInfo.InvariantCulture);
        var lifecycle =
            new PlayerTurnPreparedProviderLifecycle(session.Operation);
        lifecycle.MarkProviderStarting("Qwen", providerRequestId);
        string responseBody;
        try
        {
            using var response =
                await Http.SendAsync(request, agentCancellationToken)
                    .ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    $"Qwen HTTP {(int)response.StatusCode}: {responseBody}");
            }
        }
        catch (OperationCanceledException)
            when (agentDeadline?.IsCancellationRequested == true)
        {
            if (TryConsumeAgentOperationCancellation(
                    session.Operation,
                    out var cancellationKind))
            {
                if (finalizingVerifiedGoal
                    && CompleteVerifiedGoalFinalization(
                        agentLoop,
                        string.Empty,
                        session.UserText,
                        session.PoseContext,
                        session.JapaneseVoiceMode,
                        session.Operation))
                {
                    return;
                }
                CompleteAgentOperationCancellation(
                    session.Operation,
                    cancellationKind);
                return;
            }
            if (finalizingVerifiedGoal
                && CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                agentLoop,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.DeadlineExpired,
                "The host-owned local-agent deadline expired during the "
                    + "provider request.",
                session.ActionGoal);
            return;
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }

        using var document = JsonDocument.Parse(responseBody);
        var calls = new List<GeminiFunctionCallData>();
        var reply = new StringBuilder();
        var webSearchCalls = 0;
        if (document.RootElement.TryGetProperty("output", out var output) && output.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in output.EnumerateArray())
            {
                var type = item.TryGetProperty("type", out var typeElement) ? typeElement.GetString() ?? string.Empty : string.Empty;
                if (string.Equals(type, "message", StringComparison.OrdinalIgnoreCase)
                    && item.TryGetProperty("content", out var content) && content.ValueKind == JsonValueKind.Array)
                {
                    foreach (var part in content.EnumerateArray())
                    {
                        if (part.TryGetProperty("type", out var partType)
                            && string.Equals(partType.GetString(), "output_text", StringComparison.OrdinalIgnoreCase)
                            && part.TryGetProperty("text", out var textElement))
                            reply.Append(textElement.GetString());
                    }
                }
                else if (string.Equals(type, "function_call", StringComparison.OrdinalIgnoreCase))
                {
                    var name = item.TryGetProperty("name", out var nameElement) ? nameElement.GetString() ?? string.Empty : string.Empty;
                    var callId = item.TryGetProperty("call_id", out var callIdElement) ? callIdElement.GetString() ?? string.Empty : string.Empty;
                    var arguments = item.TryGetProperty("arguments", out var argumentsElement) ? argumentsElement.GetString() ?? "{}" : "{}";
                    try
                    {
                        using var argumentsDocument = JsonDocument.Parse(string.IsNullOrWhiteSpace(arguments) ? "{}" : arguments);
                        calls.Add(new GeminiFunctionCallData { Name = name, Id = callId, Args = argumentsDocument.RootElement.Clone() });
                    }
                    catch
                    {
                        calls.Add(new GeminiFunctionCallData { Name = name, Id = callId, Args = JsonSerializer.SerializeToElement(new { }) });
                    }
                }
                else if (string.Equals(type, "web_search_call", StringComparison.OrdinalIgnoreCase))
                {
                    webSearchCalls++;
                    session.Input.Add(item.Clone());
                }
                else if (string.Equals(type, "web_extractor_call", StringComparison.OrdinalIgnoreCase)
                    || string.Equals(type, "reasoning", StringComparison.OrdinalIgnoreCase))
                {
                    session.Input.Add(item.Clone());
                }
            }
        }

        var status = document.RootElement.TryGetProperty("status", out var statusElement)
            ? statusElement.GetString() ?? "unknown"
            : "unknown";
        var usageSummary = "unavailable";
        if (document.RootElement.TryGetProperty("usage", out var usage))
        {
            var inputTokens = usage.TryGetProperty("input_tokens", out var inputElement) ? inputElement.GetInt32() : -1;
            var outputTokens = usage.TryGetProperty("output_tokens", out var outputElement) ? outputElement.GetInt32() : -1;
            usageSummary = $"input={inputTokens}, output={outputTokens}";
        }
        Plugin.PluginLog.LogInfo($"Qwen agent turn completed in {requestTimer.Elapsed.TotalSeconds:F2}s: status={status}, calls={calls.Count}, webSearchCalls={webSearchCalls}, rawChars={reply.Length}, round={session.ToolRounds}, {usageSummary}.");

        if (finalizingVerifiedGoal)
        {
            CompleteVerifiedGoalFinalization(
                agentLoop,
                calls.Count == 0 ? reply.ToString() : string.Empty,
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation);
            return;
        }

        if (calls.Count > 0)
        {
            PendingQwenToolBatches.Enqueue(new QwenToolBatch { Session = session, Calls = calls });
            return;
        }

        if (CompleteExplicitActionWithoutVerifiedReceipt(
                session.ActionGoal,
                session.CaptureAgentLoop(),
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation))
        {
            return;
        }
        CompleteAiReply(reply.ToString(), session.UserText, session.PoseContext, session.JapaneseVoiceMode, session.Operation);
    }

    private static object[] BuildQwenTools(
        bool includeWebSearch,
        bool includeDesktopTools,
        D045AgentToolManifest manifest)
    {
        var tools = new List<object>();
        if (includeWebSearch)
            tools.Add(new { type = "web_search" });
        if (!includeDesktopTools)
            return tools.ToArray();

        var webSearchTool = includeWebSearch ? tools[0] : null;
        tools.Clear();
        if (webSearchTool != null)
            tools.Add(webSearchTool);
        if (HasLegacyManifestTools(manifest))
        {
            tools.Add(new
            {
                type = "function",
                name = "run_local_task",
                description = LegacyHarnessToolDescription(manifest),
                parameters = WorkbenchHarnessParameters(manifest)
            });
        }
        if (SupportsSemanticObservation(manifest))
        {
            tools.Add(new
            {
                type = "function",
                name = "observe_local_target",
                description = SemanticObservationToolDescription,
                parameters = SemanticObservationParameters()
            });
        }
        if (HasCodexManifestTools(manifest))
        {
            tools.Add(new
            {
                type = "function",
                name = D045CodexProviderToolContract.FunctionName,
                description = CodexWorkstationToolDescription(manifest),
                parameters = D045CodexProviderToolContract
                    .BuildJsonSchema(manifest)
            });
        }
        return tools.ToArray();
    }

