    private static void ProcessQwenToolBatches()
    {
        if (!PendingQwenToolBatches.TryDequeue(out var batch))
            return;
        var agentLoop = batch.Session.CaptureAgentLoop();
        if (!TryAdmitQueuedAgentToolBatch(
                agentLoop,
                batch.Session.Operation,
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.ActionGoal))
        {
            return;
        }
        try
        {
            var outcome = ExecuteBoundedAgentToolBatch(
                agentLoop,
                batch.Calls,
                batch.Session.ActionGoal);
            batch.Session.ToolRounds = agentLoop.Rounds;
            var directive = ObserveAgentToolBatch(
                agentLoop,
                batch.Session.ActionGoal,
                outcome);
            foreach (var value in outcome.Results)
            {
                var call = value.Call;
                var result = value.Result;
                batch.Session.Input.Add(new
                {
                    type = "function_call",
                    name = call.Name,
                    arguments = call.Args.ValueKind == JsonValueKind.Undefined ? "{}" : call.Args.GetRawText(),
                    call_id = call.Id
                });
                batch.Session.Input.Add(new
                {
                    type = "function_call_output",
                    call_id = call.Id,
                    output = JsonSerializer.Serialize(
                        BuildNormalizedProviderToolResult(result))
                });
            }
            if (directive == D045AgentTaskDirective.FinalizeWithoutTools)
            {
                CompleteVerifiedGoalFinalization(
                    agentLoop,
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation);
                return;
            }
            if (directive == D045AgentTaskDirective.Ignore)
                return;
            if (directive == D045AgentTaskDirective.PublishUnverifiedStop)
            {
                CompleteAgentTaskStop(
                    agentLoop,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation,
                    outcome.StopReasonKind,
                    outcome.StopReason,
                    batch.Session.ActionGoal);
                return;
            }
            _ = ContinueQwenAgentRequestAsync(batch.Session);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Qwen desktop tool execution failed: {exception}");
            if (CompleteVerifiedGoalFinalization(
                    batch.Session.CaptureAgentLoop(),
                    string.Empty,
                    batch.Session.UserText,
                    batch.Session.PoseContext,
                    batch.Session.JapaneseVoiceMode,
                    batch.Session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                batch.Session.CaptureAgentLoop(),
                batch.Session.UserText,
                batch.Session.PoseContext,
                batch.Session.JapaneseVoiceMode,
                batch.Session.Operation,
                D045AgentTaskStopReason.ToolFailed,
                "The Qwen tool batch faulted before every required receipt "
                    + "was verified.",
                batch.Session.ActionGoal);
        }
    }

    private static async Task ContinueQwenAgentRequestAsync(QwenAgentSession session)
    {
        try
        {
            await SendQwenAgentRequestAsync(session).ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogError($"Qwen tool continuation failed: {exception}");
            if (CompleteVerifiedGoalFinalization(
                    session.CaptureAgentLoop(),
                    string.Empty,
                    session.UserText,
                    session.PoseContext,
                    session.JapaneseVoiceMode,
                    session.Operation))
            {
                return;
            }
            CompleteAgentTaskStop(
                session.CaptureAgentLoop(),
                session.UserText,
                session.PoseContext,
                session.JapaneseVoiceMode,
                session.Operation,
                D045AgentTaskStopReason.ProviderFaultedBeforeVerification,
                "The Qwen continuation faulted before every required receipt "
                    + "was verified.",
                session.ActionGoal);
        }
    }

