    private static async Task RequestOpenAiCompatibleAsync(string provider, string systemInstruction, string userText,
        PoseContext poseContext, bool japaneseVoiceMode, PlayerTurnOperationHandle operation)
    {
        var endpoint = provider == "DeepSeek"
            ? "https://api.deepseek.com/chat/completions"
            : "https://api.openai.com/v1/chat/completions";
        var model = provider == "DeepSeek" ? Plugin.DeepSeekModel.Value.Trim() : Plugin.OpenAiModel.Value.Trim();
        var key = provider == "DeepSeek"
            ? Plugin.RetiredLegacyPlaintextProviderCredential(
                Plugin.DeepSeekApiKey).Trim()
            : Plugin.RetiredLegacyPlaintextProviderCredential(
                Plugin.OpenAiApiKey).Trim();
        var messages = BuildOpenAiMessages(systemInstruction);
        var payload = new { model, messages, max_tokens = 1024, temperature = 0.8 };
        using var request = new HttpRequestMessage(HttpMethod.Post, endpoint);
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", key);
        request.Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json");
        var lifecycle = new PlayerTurnPreparedProviderLifecycle(operation);
        lifecycle.MarkProviderStarting(
            provider,
            operation.OperationId + "-legacy-openai-1");
        string responseBody;
        try
        {
            using var response =
                await Http.SendAsync(request).ConfigureAwait(false);
            responseBody = await response.Content
                .ReadAsStringAsync().ConfigureAwait(false);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException(
                    $"{provider} HTTP {(int)response.StatusCode}: {responseBody}");
            }
        }
        finally
        {
            lifecycle.MarkProviderCompletedIfStarted();
        }
        using var document = JsonDocument.Parse(responseBody);
        var choice = document.RootElement.GetProperty("choices")[0];
        var rawReply = choice.GetProperty("message").GetProperty("content").GetString() ?? string.Empty;
        var finishReason = choice.TryGetProperty("finish_reason", out var finish) ? finish.GetString() ?? "UNKNOWN" : "UNKNOWN";
        var usageSummary = "unavailable";
        if (document.RootElement.TryGetProperty("usage", out var usage))
        {
            var prompt = usage.TryGetProperty("prompt_tokens", out var promptElement) ? promptElement.GetInt32() : -1;
            var output = usage.TryGetProperty("completion_tokens", out var outputElement) ? outputElement.GetInt32() : -1;
            usageSummary = $"prompt={prompt}, output={output}";
        }
        Plugin.PluginLog.LogInfo($"{provider} completed: finish={finishReason}, rawChars={rawReply.Length}, {usageSummary}.");
        CompleteAiReply(
            rawReply,
            userText,
            poseContext,
            japaneseVoiceMode,
            operation);
    }

    private static object[] BuildOpenAiMessages(string systemInstruction)
    {
        var messages = new List<object> { new { role = "system", content = systemInstruction } };
        lock (MemoryLock)
        {
            foreach (var turn in RecentConversation)
                messages.Add(new { role = turn.Role == "model" ? "assistant" : "user", content = turn.Text });
        }
        return messages.ToArray();
    }

    private static void CompleteAiReply(string rawReply, string userText, PoseContext poseContext,
        bool japaneseVoiceMode, PlayerTurnOperationHandle operation,
        PlayerTurnPublicationKind publicationKind =
            PlayerTurnPublicationKind.AssistantReply,
        PlayerTurnTerminalDisposition terminalDisposition =
            PlayerTurnTerminalDisposition.Completed,
        PlayerTurnFailureReason failureReason = PlayerTurnFailureReason.None,
        PlayerTurnCancellationReason cancellationReason =
            PlayerTurnCancellationReason.None)
    {
        var motionEnvelopeRequested = IsModelMotionSuggestionEnvelopeActive();
        var motionEnvelope = AgentMotionSuggestionEnvelope.Parse(
            rawReply,
            japaneseVoiceMode,
            motionEnvelopeRequested);
        if (motionEnvelopeRequested)
        {
            Plugin.PluginLog.LogInfo(
                $"Model motion envelope parsed: status={motionEnvelope.Status}, declared={motionEnvelope.DeclaredCount}, accepted={motionEnvelope.Suggestions.Count}, rejected={motionEnvelope.RejectedCount}, truncated={motionEnvelope.TruncatedCount}. Parsed suggestions are pending configured controlled review and cannot bypass queue or dispatcher policy.");
        }
        var visibleReplyPayload = motionEnvelope.ReplyPayload;
        if (IsWorkbenchOperation(operation))
        {
            var internalEnvelope = UnderstandingEnvelopeShadowParser.Parse(
                visibleReplyPayload);
            visibleReplyPayload = internalEnvelope.ReplyPrefix;
            if (internalEnvelope.TailStripped)
            {
                Plugin.PluginLog.LogInfo(
                    "Workbench removed a model-internal understanding sidecar "
                    + "before publishing the player-visible reply.");
            }
        }
        var bilingual = japaneseVoiceMode
            ? ParseBilingualReply(visibleReplyPayload)
            : null;
        var reply = CleanReply(bilingual?.DisplayText ?? visibleReplyPayload);
        var japaneseSpeech = bilingual?.JapaneseSpeech ?? string.Empty;
        CompleteBuiltInAgentAdapterShadow(rawReply, reply, japaneseVoiceMode);
        if (reply.Length > 0)
            RecordD029Signal(D029PluginSignal.PlayerReplyCompleted);
        EnqueuePlayerTurnReply(
            operation,
            reply.Length > 0 ? reply : "……",
            ChooseAiEmotion(userText, reply, poseContext),
            reply.Length > 0
                ? publicationKind
                : PlayerTurnPublicationKind.FailureNotice,
            reply.Length > 0
                ? terminalDisposition
                : PlayerTurnTerminalDisposition.Failed,
            reply.Length > 0
                ? failureReason
                : PlayerTurnFailureReason.EmptyReply,
            reply.Length > 0
                ? cancellationReason
                : PlayerTurnCancellationReason.None,
            reply.Length > 0 ? reply : string.Empty);
        if (reply.Length == 0 || !Plugin.VoiceEnabled.Value)
            return;
        var speechText = reply;
        if (japaneseVoiceMode && !string.IsNullOrWhiteSpace(japaneseSpeech))
            speechText = japaneseSpeech;
        _ = RequestSpeechAsync(speechText.Length > 0 ? speechText : reply, poseContext.VoiceStyle, japaneseVoiceMode);
    }

    private static string NormalizeAiProvider(string? provider)
    {
        if (Plugin.FormalIntegrationActive)
            return "Gemini";
        if (string.Equals(provider, "Qwen", StringComparison.OrdinalIgnoreCase)
            || string.Equals(provider, "Tongyi", StringComparison.OrdinalIgnoreCase)
            || string.Equals(provider, "DashScope", StringComparison.OrdinalIgnoreCase)) return "Qwen";
        if (string.Equals(provider, "OpenAI", StringComparison.OrdinalIgnoreCase)) return "OpenAI";
        if (string.Equals(provider, "DeepSeek", StringComparison.OrdinalIgnoreCase)) return "DeepSeek";
        return "Gemini";
    }

