    private static PlayerReplyCredentialPrecheckResult
        EvaluatePlayerReplyCredentialPrecheck(string activeProvider)
    {
        var provider = activeProvider switch
        {
            "Gemini" => ProviderKind.Gemini,
            "OpenAI" => ProviderKind.OpenAI,
            "DeepSeek" => ProviderKind.DeepSeek,
            "Qwen" => ProviderKind.QwenDashScope,
            _ => ProviderKind.Invalid
        };
        var protectedRouteEnabled = false;
        var protectedOwnerReady = false;
        var protectedCredentialConfigured = false;

        // Provider-specific adapters project only bounded metadata into the
        // shared policy. The F7 seam and policy remain provider-neutral.
        if (provider == ProviderKind.DeepSeek)
        {
            protectedRouteEnabled =
                Plugin.ProviderRuntimeDeepSeekMigrationEnabled.Value;
            protectedOwnerReady = protectedRouteEnabled
                && D031ProviderRuntimeDeepSeekMigration
                    .CanOwnDeepSeekPlayerReply();
            if (protectedOwnerReady)
            {
                protectedCredentialConfigured =
                    RefreshDeepSeekProviderControlSnapshot(force: true)
                        ?.CredentialConfigured
                    == true;
            }
        }

        return PlayerReplyCredentialPrecheckPolicy.Evaluate(
            new PlayerReplyCredentialPrecheckFacts(
                provider,
                !string.IsNullOrWhiteSpace(GetActiveChatApiKey()),
                protectedRouteEnabled,
                protectedOwnerReady,
                protectedCredentialConfigured));
    }

