        EvaluateWorkbenchCredentialPrecheck(PlayerTurnOperationHandle operation)
        => PlayerReplyCredentialPrecheckPolicy.Evaluate(
            new PlayerReplyCredentialPrecheckFacts(
                ResolveWorkbenchRuntimeProvider(operation),
                IsWorkbenchProviderConfigured(operation),
                protectedControlPlaneRouteEnabled: false,
                protectedControlPlaneOwnerReady: false,
                protectedControlPlaneCredentialConfigured: false));

