    private static PoseContext CapturePoseContext()
    {
        try
        {
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            if (state == null)
                return PoseContext.Default;
            var isPajamas = state.ClothingState == LilithClothingState.Pajamas;
            if (state.IsSleep)
                return new PoseContext(
                    "\n莉莉絲目前正在睡覺。回答應像被輕輕叫醒：簡短、低能量、親近，但不要每次都撒嬌。她可以依個性含糊拒絕起床並繼續睡，不要假裝自己已經改變姿勢。",
                    VoiceStyle.Sleepy,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.Sleeping, isPajamas));
            if (state.IsYawnAnimPlaying)
                return new PoseContext(
                    "\n莉莉絲目前正在打呵欠、帶有睡意。回答可以稍微慵懶而簡短。",
                    VoiceStyle.Sleepy,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.TransientAction, isPajamas));
            if (state.IsLieDown)
                return new PoseContext(
                    "\n莉莉絲目前正躺著。語氣可以放鬆、安靜，像在近距離聊天；若不需要起身，可以自然說自己就躺著陪對方。",
                    VoiceStyle.Sleepy,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.LyingDown, isPajamas));
            if (IsMotionVisualSitState(state))
                return new PoseContext(
                    "\n莉莉絲目前坐著，處於放鬆陪伴的姿態。",
                    VoiceStyle.Calm,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.Sitting, isPajamas));
            if (state.IsInteracting)
                return new PoseContext(
                    "\n莉莉絲目前正在和使用者互動，注意力在對方身上。",
                    VoiceStyle.Calm,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.Interacting, isPajamas));
            if (state.IsStateMachineLocked
                || state.IsWalkLeft
                || state.IsWalkRight
                || state.IsAnyActionAnimPlaying)
            {
                return new PoseContext(
                    "\n莉莉絲目前正在完成一個原生動作或姿勢轉換。回答可以承接當下動作，但不要假裝新的動作已經完成。",
                    VoiceStyle.Calm,
                    new AgentAvatarMotionContext(AgentAvatarPoseKind.TransientAction, isPajamas));
            }
            return new PoseContext(
                "\n莉莉絲目前自然站立待機著。",
                VoiceStyle.Calm,
                new AgentAvatarMotionContext(AgentAvatarPoseKind.Standing, isPajamas));
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not read Lilith pose state: {exception.Message}");
            return PoseContext.Default;
        }
    }

    private static bool TryBuildLocalTimeReply(string input, out string reply)
    {
        var asksTime = Regex.IsMatch(input, "(現在|目前|此刻).{0,4}(幾點|几点|時間|时间)|(幾點|几点)了|現在是幾點|现在是几点");
        var asksDate = Regex.IsMatch(input, "(今天|現在|目前).{0,4}(幾號|几号|日期|幾月幾日|几月几日)");
        var asksWeekday = Regex.IsMatch(input, "(今天|現在|目前).{0,4}(星期幾|星期几|禮拜幾|礼拜几|週幾|周几)");
        if (!asksTime && !asksDate && !asksWeekday)
        {
            reply = string.Empty;
            return false;
        }

        var now = DateTimeOffset.Now;
        var parts = new List<string>();
        if (asksDate)
            parts.Add($"今天是 {now:yyyy 年 M 月 d 日}");
        if (asksWeekday)
        {
            var weekday = now.DayOfWeek switch
            {
                DayOfWeek.Monday => "星期一",
                DayOfWeek.Tuesday => "星期二",
                DayOfWeek.Wednesday => "星期三",
                DayOfWeek.Thursday => "星期四",
                DayOfWeek.Friday => "星期五",
                DayOfWeek.Saturday => "星期六",
                _ => "星期日"
            };
            parts.Add(weekday);
        }
        if (asksTime)
            parts.Add($"現在是 {now:HH:mm}");
        reply = string.Join("，", parts) + "。";
        return true;
    }

    private static async Task<LocalWeatherContextObservation>
        BuildWeatherContextAsync()
    {
        var observedTimestamp = Stopwatch.GetTimestamp();
        var configuration = CaptureWeatherConfigurationSnapshot();
        if (!configuration.Enabled)
        {
            return new LocalWeatherContextObservation(
                LocalWeatherContextAvailability.Disabled,
                string.Empty,
                configuration.Fingerprint,
                observedTimestamp,
                observedTimestamp);
        }
        if (_cachedWeatherContextObservation != null
            && string.Equals(
                _cachedWeatherContextObservation.ConfigurationFingerprint,
                configuration.Fingerprint,
                StringComparison.Ordinal)
            && _cachedWeatherContextObservation.IsFresh(
                observedTimestamp))
        {
            return _cachedWeatherContextObservation;
        }

        try
        {
            await ResolveWeatherLocationFromIpAsync().ConfigureAwait(false);
            configuration = CaptureWeatherConfigurationSnapshot();
            if (!configuration.Enabled)
            {
                observedTimestamp = Stopwatch.GetTimestamp();
                return new LocalWeatherContextObservation(
                    LocalWeatherContextAvailability.Disabled,
                    string.Empty,
                    configuration.Fingerprint,
                    observedTimestamp,
                    observedTimestamp);
            }
            var latitude = configuration.Latitude.ToString(
                CultureInfo.InvariantCulture);
            var longitude = configuration.Longitude.ToString(
                CultureInfo.InvariantCulture);
            var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,weather_code,wind_speed_10m,is_day&temperature_unit=celsius&wind_speed_unit=kmh&precipitation_unit=mm&timezone=auto";
            using var response = await Http.GetAsync(url).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            using var document = JsonDocument.Parse(await response.Content.ReadAsStringAsync().ConfigureAwait(false));
            var current = document.RootElement.GetProperty("current");
            var temperature = current.GetProperty("temperature_2m").GetDouble();
            var apparent = current.GetProperty("apparent_temperature").GetDouble();
            var humidity = current.GetProperty("relative_humidity_2m").GetDouble();
            var precipitation = current.GetProperty("precipitation").GetDouble();
            var wind = current.GetProperty("wind_speed_10m").GetDouble();
            var code = current.GetProperty("weather_code").GetInt32();
            var daylight = current.GetProperty("is_day").GetInt32() == 1 ? "白天" : "夜間";
            var condition = DescribeWeatherCode(code);
            var promptContext = $"\n目前「{configuration.LocationName}」的即時天氣（Open-Meteo 模型資料）：{condition}，{daylight}，氣溫 {temperature:0.#}°C，體感 {apparent:0.#}°C，相對濕度 {humidity:0}% ，目前降水 {precipitation:0.##} mm，風速 {wind:0.#} km/h。被問到現在的天氣時依此回答，不要自行編造未提供的資訊。";
            observedTimestamp = Stopwatch.GetTimestamp();
            var observation = new LocalWeatherContextObservation(
                LocalWeatherContextAvailability.Available,
                promptContext,
                configuration.Fingerprint,
                observedTimestamp,
                CaptureWeatherExpiryTimestamp(observedTimestamp));
            _cachedWeatherContextObservation = observation;
            return observation;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Weather lookup failed; chat continues without it: {exception.Message}");
            observedTimestamp = Stopwatch.GetTimestamp();
            configuration = CaptureWeatherConfigurationSnapshot();
            return new LocalWeatherContextObservation(
                LocalWeatherContextAvailability.Unavailable,
                "\n目前無法取得可靠的即時天氣；若被問到天氣，坦白說暫時看不到，不要猜測。",
                configuration.Fingerprint,
                observedTimestamp,
                observedTimestamp);
        }
    }

    private static string CaptureWeatherConfigurationFingerprint()
        => CaptureWeatherConfigurationSnapshot().Fingerprint;

    private static WeatherConfigurationSnapshot
        CaptureWeatherConfigurationSnapshot()
    {
        var enabled = Plugin.WeatherEnabled.Value;
        var autoDetectFromIp = Plugin.WeatherAutoDetectFromIp.Value;
        var locationName = Plugin.WeatherLocationName.Value ?? string.Empty;
        var latitude = Plugin.WeatherLatitude.Value;
        var longitude = Plugin.WeatherLongitude.Value;
        var fingerprint = LivingPromptHash.Of(
            "weather-context-v1|"
            + enabled
            + "|"
            + autoDetectFromIp
            + "|"
            + locationName
            + "|"
            + latitude.ToString("R", CultureInfo.InvariantCulture)
            + "|"
            + longitude.ToString("R", CultureInfo.InvariantCulture));
        return new WeatherConfigurationSnapshot(
            enabled,
            locationName,
            latitude,
            longitude,
            fingerprint);
    }

    private static long CaptureWeatherExpiryTimestamp(
        long observedTimestamp)
    {
        if (observedTimestamp < 0)
            throw new ArgumentOutOfRangeException(nameof(observedTimestamp));
        var lifetime = checked(Stopwatch.Frequency * 600L);
        return observedTimestamp > long.MaxValue - lifetime
            ? long.MaxValue
            : observedTimestamp + lifetime;
    }

    private sealed class WeatherConfigurationSnapshot
    {
        internal bool Enabled { get; }
        internal string LocationName { get; }
        internal double Latitude { get; }
        internal double Longitude { get; }
        internal string Fingerprint { get; }

        internal WeatherConfigurationSnapshot(
            bool enabled,
            string locationName,
            double latitude,
            double longitude,
            string fingerprint)
        {
            Enabled = enabled;
            LocationName = locationName
                ?? throw new ArgumentNullException(nameof(locationName));
            Latitude = latitude;
            Longitude = longitude;
            Fingerprint = fingerprint
                ?? throw new ArgumentNullException(nameof(fingerprint));
        }
    }

    private static async Task ResolveWeatherLocationFromIpAsync()
    {
        if (_ipWeatherLocationResolved || !Plugin.WeatherAutoDetectFromIp.Value)
            return;
        _ipWeatherLocationResolved = true;

        try
        {
            const string url = "https://ipwho.is/?fields=success,message,city,region,country,latitude,longitude";
            using var response = await Http.GetAsync(url).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            using var document = JsonDocument.Parse(await response.Content.ReadAsStringAsync().ConfigureAwait(false));
            var root = document.RootElement;
            if (root.TryGetProperty("success", out var success) && !success.GetBoolean())
            {
                var message = root.TryGetProperty("message", out var error) ? error.GetString() : "unknown error";
                throw new InvalidOperationException(message);
            }

            var latitude = root.GetProperty("latitude").GetDouble();
            var longitude = root.GetProperty("longitude").GetDouble();
            var city = root.TryGetProperty("city", out var cityElement) ? cityElement.GetString() : null;
            var region = root.TryGetProperty("region", out var regionElement) ? regionElement.GetString() : null;
            var country = root.TryGetProperty("country", out var countryElement) ? countryElement.GetString() : null;
            var locationParts = new[] { city, region, country }
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase);
            var locationName = string.Join("，", locationParts);
            if (locationName.Length == 0)
                locationName = Plugin.WeatherLocationName.Value;

            Plugin.WeatherLatitude.Value = latitude;
            Plugin.WeatherLongitude.Value = longitude;
            Plugin.WeatherLocationName.Value = locationName;
            Plugin.PluginLog.LogInfo($"Weather location approximated from IP as '{locationName}' (the IP address was not stored)." );
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"IP weather location lookup failed; using configured location: {exception.Message}");
        }
    }

    private static string DescribeWeatherCode(int code)
    {
        if (code == 0) return "晴朗";
        if (code <= 3) return "多雲";
        if (code == 45 || code == 48) return "有霧";
        if (code >= 51 && code <= 57) return "毛毛雨";
        if (code >= 61 && code <= 67) return "下雨";
        if (code >= 71 && code <= 77) return "下雪";
        if (code >= 80 && code <= 82) return "陣雨";
        if (code >= 85 && code <= 86) return "陣雪";
        if (code >= 95) return "雷雨";
        return $"天氣代碼 {code}";
    }

    private static void QueueReminderSpeech(
        string text,
        VoiceStyle poseStyle,
        bool japaneseVoiceMode,
        ContinuationPresentationTicket? continuation = null,
        string speechEmotion = "")
    {
        var ticket = new ReminderSpeechTicket(
            text,
            poseStyle,
            japaneseVoiceMode,
            continuation,
            speechEmotion);
        var count = Interlocked.Increment(
            ref _activeReminderSpeechCount);
        if (count > GameHermesNotificationQueueCapacity)
        {
            Interlocked.Decrement(ref _activeReminderSpeechCount);
            Plugin.PluginLog.LogWarning(
                "Dropped reminder speech after the bounded voice queue "
                + "reached capacity; its text was already displayed.");
            return;
        }
        PendingReminderSpeech.Enqueue(ticket);
    }

    private static void ProcessPendingReminderSpeech()
    {
        if (!PendingReminderSpeech.TryPeek(out var pending))
            return;
        if (pending.Continuation is { } continuation && !ContinuationIsCurrent(continuation))
        {
            if (PendingReminderSpeech.TryDequeue(out pending))
                RetireReminderSpeech(pending, "its continuation expired or was superseded before synthesis");
            return;
        }
        if (!Plugin.VoiceEnabled.Value)
        {
            if (PendingReminderSpeech.TryDequeue(out pending))
            {
                RetireReminderSpeech(
                    pending,
                    "voice was disabled before synthesis");
            }
            return;
        }
        if (!CanAdmitLegacyVoicePlayback()
            || Environment.TickCount64 < pending.NotBeforeTickCount
            || Interlocked.CompareExchange(
                ref _reminderSpeechPipelineBusy,
                1,
                0) != 0)
        {
            return;
        }
        if (!PendingReminderSpeech.TryDequeue(out pending))
        {
            Interlocked.Exchange(ref _reminderSpeechPipelineBusy, 0);
            return;
        }
        if (!ReminderSpeechLocaleIsCurrent(pending))
        {
            RetireReminderSpeech(
                pending,
                "voice locale changed before synthesis");
            return;
        }
        if (!pending.TryBeginSynthesis())
        {
            Interlocked.Exchange(ref _reminderSpeechPipelineBusy, 0);
            return;
        }
        _ = RequestSpeechAsync(
            pending.Text,
            poseStyle: pending.PoseStyle,
            japaneseVoiceMode: pending.JapaneseVoiceMode,
            reminder: pending);
    }

    private static bool ReminderSpeechLocaleIsCurrent(
        ReminderSpeechTicket ticket)
        => ticket.JapaneseVoiceMode == IsJapaneseVoiceMode();

    private static bool ContinuationIsCurrent(ContinuationPresentationTicket ticket)
        => EffectiveD046ProactiveDialogueEnabled()
            && ContinuationPresentation.IsCurrent(ticket, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());

    private static bool IsOfficialOrQueuedVoicePlaying()
        => AudioManager.instance?.source_Voice?.isPlaying == true;

    private static void RetireInvalidContinuationPlayback()
    {
        var enabled = EffectiveD046ProactiveDialogueEnabled();
        if (_continuationEnabledPreviously && !enabled)
            ContinuationPresentation.Invalidate(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        _continuationEnabledPreviously = enabled;
        if (_activeContinuationSpeech is null) return;
        var source = AudioManager.instance?.source_Voice;
        if (!ContinuationIsCurrent(_activeContinuationSpeech)
            && source != null && ReferenceEquals(source.clip, _activeContinuationAudio))
            AudioManager.StopVoice();
        if (source == null || !source.isPlaying || !ReferenceEquals(source.clip, _activeContinuationAudio))
        {
            _activeContinuationSpeech = null;
            _activeContinuationAudio = null;
        }
    }

    private static void RequeueReminderSpeech(
        ReminderSpeechTicket ticket,
        bool countFailure)
    {
        if (ticket.Continuation is not null)
        {
            RetireReminderSpeech(ticket, "continuation speech is single-attempt; no delayed retry");
            return;
        }
        if (!ticket.TryRequeue())
            return;
        if (countFailure
            && ticket.IncrementFailureCount()
                >= ReminderSpeechTicket.MaximumFailureCount)
        {
            RetireReminderSpeech(
                ticket,
                "voice generation or playback repeatedly failed");
            return;
        }
        ticket.NotBeforeTickCount = countFailure
            ? Environment.TickCount64 + 5_000
            : Environment.TickCount64;
        PendingReminderSpeech.Enqueue(ticket);
        Interlocked.Exchange(ref _reminderSpeechPipelineBusy, 0);
    }

    private static void RetireReminderSpeech(
        ReminderSpeechTicket ticket,
        string reason)
    {
        if (ticket.TryRetire())
        {
            Interlocked.Decrement(ref _activeReminderSpeechCount);
            Plugin.PluginLog.LogInfo(
                "Retired reminder speech after " + reason + ".");
        }
        Interlocked.Exchange(ref _reminderSpeechPipelineBusy, 0);
    }

    private static void ConsumeReminderSpeech(ReminderSpeechTicket ticket)
    {
        if (ticket.TryConsume())
            Interlocked.Decrement(ref _activeReminderSpeechCount);
        Interlocked.Exchange(ref _reminderSpeechPipelineBusy, 0);
    }

    private static async Task RequestSpeechAsync(
        string text,
        VoiceStyle poseStyle = VoiceStyle.Calm,
        bool? japaneseVoiceMode = null,
        ReminderSpeechTicket? reminder = null)
    {
        var generationTimer = Stopwatch.StartNew();
        var publicationSequence = Interlocked.Read(
            ref _d043PlayerReplyPublicationSequence);
        var reminderHandled = false;
        try
        {
            var useJapanese = japaneseVoiceMode ?? IsJapaneseVoiceMode();
            var speechText = PrepareTextForSpeech(text);
            if (speechText.Length == 0)
            {
                if (reminder != null)
                {
                    RetireReminderSpeech(
                        reminder,
                        "its speech text was empty");
                    reminderHandled = true;
                }
                return;
            }
            var referencePath = useJapanese ? Plugin.JapaneseVoiceReferencePath.Value.Trim() : Plugin.VoiceReferencePath.Value.Trim();
            var promptText = useJapanese
                ? "これは儀式でもあるの。君に私の存在を感じてもらうための儀式ね。"
                : "你的選擇創造了我，所以我的存在本身就是你的善意。";
            var effectiveStyle = poseStyle;
            var auxiliaryReferences = useJapanese ? effectiveStyle switch
            {
                VoiceStyle.Excited => new[] { Plugin.JapaneseExcitedVoiceReferencePath.Value.Trim() },
                VoiceStyle.Wronged => new[] { Plugin.JapaneseWrongedVoiceReferencePath.Value.Trim() },
                VoiceStyle.Sleepy => new[] { Plugin.JapaneseSleepyVoiceReferencePath.Value.Trim() },
                _ => new[] { Plugin.JapaneseCalmAuxVoiceReferencePath.Value.Trim() }
            } : effectiveStyle switch
            {
                VoiceStyle.Excited => new[] { Plugin.ExcitedVoiceReferencePath.Value.Trim() },
                VoiceStyle.Wronged => new[] { Plugin.WrongedVoiceReferencePath.Value.Trim() },
                VoiceStyle.Sleepy => new[] { Plugin.SleepyVoiceReferencePath.Value.Trim() },
                _ => Array.Empty<string>()
            };
            auxiliaryReferences = Array.FindAll(auxiliaryReferences, File.Exists);
            if (!File.Exists(referencePath))
            {
                Plugin.PluginLog.LogWarning($"Voice reference was not found: {referencePath}");
                if (reminder != null)
                {
                    RetireReminderSpeech(
                        reminder,
                        "its selected voice reference was unavailable");
                    reminderHandled = true;
                }
                return;
            }

            var payload = new Dictionary<string, object>
            {
                ["text"] = speechText,
                ["text_lang"] = useJapanese ? "ja" : "zh",
                ["ref_audio_path"] = referencePath,
                ["aux_ref_audio_paths"] = auxiliaryReferences,
                ["prompt_lang"] = useJapanese ? "ja" : "zh",
                ["prompt_text"] = promptText,
                ["text_split_method"] = "cut0",
                ["batch_size"] = 1,
                ["media_type"] = "wav",
                ["streaming_mode"] = false,
                ["seed"] = 42
            };
            var endpoint = useJapanese ? Plugin.JapaneseVoiceEndpoint.Value.Trim() : Plugin.VoiceEndpoint.Value.Trim();
            if (reminder?.Continuation != null && useJapanese
                && Uri.TryCreate(endpoint, UriKind.Absolute, out var uri)
                && uri.Scheme == "http" && uri.IsLoopback && uri.Port == 9881
                && uri.AbsolutePath == "/tts" && uri.Query.Length == 0)
            {
                JapaneseSpeechDeliveryPolicy.TryLeadingCue(speechText, out var delivery, out _);
                payload["lilith_emotion"] = reminder.SpeechEmotion;
                payload["lilith_reference_cue"] = delivery.ReferenceCue;
                payload["lilith_allow_native_cue"] = true;
                endpoint = new UriBuilder(uri) { Path = "/lilith/tts" }.Uri.AbsoluteUri;
            }
            var payloadJson = JsonSerializer.Serialize(payload);
            var localEndpoint = IsLocalVoiceEndpoint(endpoint);
            var maximumAttempts = reminder?.Continuation != null ? 1
                : localEndpoint && Plugin.VoiceAutoStartLocalService.Value ? 7 : 1;
            if (localEndpoint && Plugin.VoiceAutoStartLocalService.Value)
                await LocalVoicePreparation.WaitAsync(endpoint, CancellationToken.None).ConfigureAwait(false);
            for (var attempt = 1; attempt <= maximumAttempts; attempt++)
            {
                try
                {
                    if (reminder?.Continuation is { } beforeSynthesis && !ContinuationIsCurrent(beforeSynthesis))
                    {
                        RetireReminderSpeech(reminder, "its continuation expired before synthesis");
                        reminderHandled = true;
                        return;
                    }
                    using var request = new HttpRequestMessage(HttpMethod.Post, endpoint);
                    request.Content = new StringContent(payloadJson, Encoding.UTF8, "application/json");
                    using var response = await Http.SendAsync(request).ConfigureAwait(false);
                    if (!response.IsSuccessStatusCode)
                    {
                        var error = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                        throw new HttpRequestException($"TTS HTTP {(int)response.StatusCode}: {error}",
                            inner: null, statusCode: response.StatusCode);
                    }
                    var speech = await response.Content.ReadAsByteArrayAsync().ConfigureAwait(false);
                    if (reminder?.Continuation is { } afterSynthesis && !ContinuationIsCurrent(afterSynthesis))
                    {
                        Array.Clear(speech, 0, speech.Length);
                        RetireReminderSpeech(reminder, "its continuation expired during synthesis");
                        reminderHandled = true;
                        return;
                    }
                    if (reminder != null && !Plugin.VoiceEnabled.Value)
                    {
                        Array.Clear(speech, 0, speech.Length);
                        RetireReminderSpeech(
                            reminder,
                            "voice was disabled during synthesis");
                        reminderHandled = true;
                        return;
                    }
                    if (reminder != null
                        && !ReminderSpeechLocaleIsCurrent(reminder))
                    {
                        Array.Clear(speech, 0, speech.Length);
                        RetireReminderSpeech(
                            reminder,
                            "voice locale changed during synthesis");
                        reminderHandled = true;
                        return;
                    }
                    if (!IsLegacyVoicePublicationCurrent(
                            publicationSequence))
                    {
                        Array.Clear(speech, 0, speech.Length);
                        if (reminder != null)
                        {
                            RequeueReminderSpeech(
                                reminder,
                                countFailure: false);
                            reminderHandled = true;
                            Plugin.PluginLog.LogInfo(
                                "Deferred completed reminder voice behind a "
                                + "newer F6/F7 reply publication.");
                        }
                        else
                        {
                            Plugin.PluginLog.LogInfo(
                                "Dropped stale completed legacy voice after a "
                                + "newer F6/F7 reply publication.");
                        }
                        return;
                    }
                    if (reminder != null && !reminder.TryMarkReady())
                    {
                        Array.Clear(speech, 0, speech.Length);
                        RetireReminderSpeech(
                            reminder,
                            "its synthesis ownership changed unexpectedly");
                        reminderHandled = true;
                        return;
                    }
                    PendingVoiceAudio.Enqueue(
                        new VoiceSequence
                        {
                            Speech = speech,
                            PublicationSequence = publicationSequence,
                            Reminder = reminder
                        });
                    reminderHandled = reminder != null;
                    Plugin.PluginLog.LogInfo($"Local voice generation completed in {generationTimer.Elapsed.TotalSeconds:F2}s ({speech.Length} bytes)." );
                    return;
                }
                catch (HttpRequestException exception) when (
                    LocalVoiceRetryPolicy.ShouldRetry(exception, attempt, maximumAttempts))
                {
                    Plugin.PluginLog.LogInfo($"Local voice service is temporarily unavailable; retrying in 5 seconds ({attempt}/{maximumAttempts}); reason={LocalVoiceRetryPolicy.RetryReason(exception)}.");
                    await Task.Delay(TimeSpan.FromSeconds(5)).ConfigureAwait(false);
                }
            }
        }
        catch (Exception exception)
        {
            if (reminder != null && exception is HttpRequestException synthesisFailure
                && LocalVoiceRetryPolicy.IsTerminalResponse(synthesisFailure))
            {
                RetireReminderSpeech(reminder, "its synthesis returned a terminal HTTP response");
                reminderHandled = true;
            }
            Plugin.PluginLog.LogWarning($"Voice generation failed; text chat continues: {exception.Message}");
        }
        finally
        {
            if (reminder != null && !reminderHandled)
            {
                RequeueReminderSpeech(
                    reminder,
                    countFailure: true);
            }
        }
    }

    private static bool IsLocalVoiceEndpoint(string endpoint)
    {
        return Uri.TryCreate(endpoint, UriKind.Absolute, out var uri) && uri.IsLoopback;
    }

    private static bool IsLegacyVoicePublicationCurrent(
        long publicationSequence)
        => publicationSequence == Interlocked.Read(
            ref _d043PlayerReplyPublicationSequence);

    private static bool CanAdmitLegacyVoicePlayback()
        => !_requestInFlight
            && !HasActivePublishedPlayerReplySpeech();

    private static void ClearVoiceSequenceAudio(VoiceSequence sequence)
    {
        Array.Clear(sequence.Speech, 0, sequence.Speech.Length);
    }

    private static string PrepareTextForSpeech(string text)
    {
        var cleaned = LilithSpeechTextNormalizer.Prepare(text);
        if (!string.Equals(cleaned, text, StringComparison.Ordinal))
            Plugin.PluginLog.LogInfo($"Normalized text before TTS ({text.Length} -> {cleaned.Length} chars).");
        return cleaned;
    }

    private static void SetVoicePitch(float pitch)
    {
        var manager = AudioManager.instance;
        if (manager != null && manager.source_Voice != null)
            manager.source_Voice.pitch = pitch;
    }

    private static AudioClip PlayWav(byte[] wav, string label)
    {
        CancelMiniGameDialogue();
        var clip = CreateAudioClipFromWav(wav);
        AudioManager.PlayVoice(clip, false, true);
        Plugin.PluginLog.LogInfo($"Playing {label} ({wav.Length} bytes, {clip.length:0.00}s).");
        return clip;
    }

    private sealed class VoiceSequence
    {
        public byte[] Speech { get; set; } = Array.Empty<byte>();
        public long PublicationSequence { get; set; }
        public ReminderSpeechTicket? Reminder { get; set; }
    }

    private sealed class ReminderSpeechTicket
    {
        private const int PendingState = 0;
        private const int SynthesizingState = 1;
        private const int ReadyState = 2;
        private const int PlayingState = 3;
        private const int ConsumedState = 4;
        private const int RetiredState = 5;
        internal const int MaximumFailureCount = 3;

        private int _state = PendingState;
        private int _failureCount;
        private long _notBeforeTickCount;

        internal string Text { get; }
        internal VoiceStyle PoseStyle { get; }
        internal bool JapaneseVoiceMode { get; }
        internal ContinuationPresentationTicket? Continuation { get; }
        internal string SpeechEmotion { get; }
        internal long NotBeforeTickCount
        {
            get => Interlocked.Read(ref _notBeforeTickCount);
            set => Interlocked.Exchange(
                ref _notBeforeTickCount,
                value);
        }

        internal ReminderSpeechTicket(
            string text,
            VoiceStyle poseStyle,
            bool japaneseVoiceMode,
            ContinuationPresentationTicket? continuation,
            string speechEmotion)
        {
            Text = text;
            PoseStyle = poseStyle;
            JapaneseVoiceMode = japaneseVoiceMode;
            Continuation = continuation;
            SpeechEmotion = speechEmotion;
            _notBeforeTickCount = Environment.TickCount64;
        }

        internal int IncrementFailureCount()
            => Interlocked.Increment(ref _failureCount);

        internal bool TryBeginSynthesis()
            => Interlocked.CompareExchange(
                ref _state,
                SynthesizingState,
                PendingState) == PendingState;

        internal bool TryMarkReady()
            => Interlocked.CompareExchange(
                ref _state,
                ReadyState,
                SynthesizingState) == SynthesizingState;

        internal bool TryBeginPlayback()
            => Interlocked.CompareExchange(
                ref _state,
                PlayingState,
                ReadyState) == ReadyState;

        internal bool TryConsume()
            => Interlocked.CompareExchange(
                ref _state,
                ConsumedState,
                PlayingState) == PlayingState;

        internal bool TryRequeue()
        {
            while (true)
            {
                var state = Volatile.Read(ref _state);
                if (state is not (SynthesizingState
                    or ReadyState
                    or PlayingState))
                {
                    return false;
                }
                if (Interlocked.CompareExchange(
                        ref _state,
                        PendingState,
                        state) == state)
                {
                    return true;
                }
            }
        }

        internal bool TryRetire()
        {
            while (true)
            {
                var state = Volatile.Read(ref _state);
                if (state is ConsumedState or RetiredState)
                    return false;
                if (Interlocked.CompareExchange(
                        ref _state,
                        RetiredState,
                        state) == state)
                {
                    return true;
                }
            }
        }
    }

    private sealed class CodexBridgeProcessClock : ICodexBridgeQueueClock
    {
        private readonly long _origin = Stopwatch.GetTimestamp();

        public CodexBridgeQueueClockSample Capture()
        {
            var elapsed = Math.Max(0, Stopwatch.GetTimestamp() - _origin);
            var monotonicTicks = checked((long)Math.Floor(
                elapsed
                * (double)TimeSpan.TicksPerSecond
                / Stopwatch.Frequency));
            return new CodexBridgeQueueClockSample(
                DateTimeOffset.UtcNow,
                monotonicTicks);
        }
    }

