    private sealed class HostEffectTargetDescriptor
    {
        internal LocalActionGoal Goal { get; }
        internal D045PermissionCapability Capability { get; }
        internal string ExactIdentity { get; }
        internal string Fingerprint { get; }
        private bool IsProcessId { get; }

        private HostEffectTargetDescriptor(
            LocalActionGoal goal,
            D045PermissionCapability capability,
            string exactIdentity,
            bool isProcessId)
        {
            Goal = goal;
            Capability = capability;
            ExactIdentity = exactIdentity;
            IsProcessId = isProcessId;
            Fingerprint = Convert.ToHexString(SHA256.HashData(
                Encoding.UTF8.GetBytes(
                    "D045.HOST.GOAL.TARGET.V1\n"
                    + ((int)goal).ToString(CultureInfo.InvariantCulture)
                    + "\n"
                    + ((int)capability).ToString(CultureInfo.InvariantCulture)
                    + "\n"
                    + exactIdentity.ToUpperInvariant())));
        }

        internal static HostEffectTargetDescriptor ForProcess(
            LocalActionGoal goal,
            D045PermissionCapability capability,
            int processId)
            => new(
                goal,
                capability,
                processId.ToString(CultureInfo.InvariantCulture),
                isProcessId: true);

        internal static HostEffectTargetDescriptor ForPath(
            LocalActionGoal goal,
            D045PermissionCapability capability,
            string path)
        {
            if (!TryNormalizeHostEffectPath(path, out var normalized))
                throw new ArgumentException("An exact local path is required.", nameof(path));
            return new(goal, capability, normalized, isProcessId: false);
        }

        internal bool Matches(
            D045PermissionCapability capability,
            string requestedTarget,
            string secondaryTarget,
            string payload)
        {
            if (capability != Capability)
                return false;
            if (IsProcessId)
            {
                return secondaryTarget.Length == 0
                    && payload.Length == 0
                    && int.TryParse(
                        requestedTarget,
                        NumberStyles.None,
                        CultureInfo.InvariantCulture,
                        out var requestedProcessId)
                    && string.Equals(
                        requestedProcessId.ToString(CultureInfo.InvariantCulture),
                        ExactIdentity,
                        StringComparison.Ordinal);
            }
            if (!TryNormalizeHostEffectPath(requestedTarget, out var path)
                || !string.Equals(
                    path,
                    ExactIdentity,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }
            if (Capability is D045PermissionCapability.RecycleBinDelete
                or D045PermissionCapability.PermanentDelete)
            {
                return secondaryTarget.Length == 0 && payload.Length == 0;
            }
            if (Capability
                == D045PermissionCapability.GeneralElevationAdminAccess)
            {
                // The player froze one exact executable, not an arbitrary
                // elevated command line. Arguments need a separate typed goal.
                return secondaryTarget.Length == 0 && payload.Length == 0;
            }
            return true;
        }
    }

