    private sealed class HostApplicationPreObservation
    {
        internal HostApplicationPreObservation(
            Guid taskId,
            GeminiFunctionCallData call,
            GeminiToolResult result,
            D045SemanticObservationReceipt receipt,
            DateTimeOffset referenceDeadlineUtc)
        {
            TaskId = taskId;
            Call = call ?? throw new ArgumentNullException(nameof(call));
            Result = result ?? throw new ArgumentNullException(nameof(result));
            Receipt = receipt ?? throw new ArgumentNullException(nameof(receipt));
            var candidate = receipt.Candidates.Count == 1
                ? receipt.Candidates[0]
                : throw new ArgumentException(
                    "A host application pre-observation requires one candidate.",
                    nameof(receipt));
            if (!candidate.IsRedeemable)
            {
                throw new ArgumentException(
                    "A host application pre-observation requires one redeemable candidate.",
                    nameof(receipt));
            }
            TargetReference = candidate.OpaqueTargetReference;
            ReferenceDeadlineUtc = referenceDeadlineUtc.ToUniversalTime();
        }

        internal Guid TaskId { get; }
        internal GeminiFunctionCallData Call { get; }
        internal GeminiToolResult Result { get; }
        internal D045SemanticObservationReceipt Receipt { get; }
        internal string TargetReference { get; }
        internal DateTimeOffset ReferenceDeadlineUtc { get; }
    }

    [Flags]
    private enum LocalActionGoal
    {
        None = 0,
        ReadOrInspect = 1 << 0,
        Open = 1 << 1,
        Create = 1 << 2,
        Delete = 1 << 3,
        Close = 1 << 4,
        Shutdown = 1 << 5,
        Restart = 1 << 6,
        Screenshot = 1 << 7,
        ExternalInput = 1 << 8,
        UnsupportedEffect = 1 << 9,
        PermanentDelete = 1 << 10,
        ForceClose = 1 << 11,
        ReadFile = 1 << 12,
        EnumerateFolder = 1 << 13,
        ClipboardRead = 1 << 14,
        StatusRead = 1 << 15,
        CorrelateCreateOpen = 1 << 16,
        RawShell = 1 << 17,
        Elevation = 1 << 18,
        Workstation = 1 << 19
    }

