    private sealed class AgentLoopBudget
    {
        private readonly object _gate = new();
        private long _startedTimestamp;
        private readonly HashSet<string> _failedIntentReceipts =
            new(StringComparer.Ordinal);
        private readonly List<VerifiedHarnessEvidence> _verifiedReceipts =
            new();
        private readonly D045VerifiedGoalTerminalKernel _terminalKernel =
            new();
        private readonly D045HarnessRetryGate _retryGate = new();
        private readonly Dictionary<string, SemanticTargetBinding>
            _semanticTargets = new(StringComparer.Ordinal);
        private string _lastAdmittedIntent = string.Empty;
        private int _rounds;
        private int _executedCalls;
        private LocalOpenTargetKind _requiredOpenTargetKind;
        private string _expectedOpenLeaf = string.Empty;
        private string _expectedSemanticTarget = string.Empty;
        private HostEffectTargetDescriptor? _hostEffectTarget;
        private D045CodexTaskPlan? _codexTaskPlan;
        private D045AgentToolManifest? _toolManifest;
        private string _registeredHostApplicationReference = string.Empty;
        private DateTimeOffset
            _registeredHostApplicationReferenceDeadlineUtc =
                DateTimeOffset.MaxValue;
        private string _requiredHostApplicationReference = string.Empty;
        private string _verifiedHostApplicationProcessId = string.Empty;
        private DateTimeOffset _hostApplicationReferenceDeadlineUtc =
            DateTimeOffset.MaxValue;
        private PlayerTurnOperationHandle? _operation;
        private long _permissionRevision;
        private bool _isWorkbenchOperation;
        private D045WorkbenchExecutionBudgetProfile _budgetProfile =
            D045WorkbenchExecutionBudgetProfile.Quick;
        private int _maximumRounds = AgentLoopMaximumRounds;
        private int _maximumCalls = AgentLoopMaximumCalls;
        private TimeSpan _maximumDuration = AgentLoopMaximumDuration;

        internal LocalOpenTargetKind RequiredOpenTargetKind
        {
            get
            {
                lock (_gate)
                    return _requiredOpenTargetKind;
            }
        }

        internal string ExpectedOpenLeaf
        {
            get
            {
                lock (_gate)
                    return _expectedOpenLeaf;
            }
        }

        internal string ExpectedSemanticTarget
        {
            get
            {
                lock (_gate)
                    return _expectedSemanticTarget;
            }
        }

        internal long AdmittedPermissionRevision
        {
            get
            {
                lock (_gate)
                    return _permissionRevision;
            }
        }

        internal D045AgentToolManifest ToolManifest
        {
            get
            {
                lock (_gate)
                {
                    return _toolManifest
                        ?? throw new InvalidOperationException(
                            "The per-turn workstation tool manifest is not bound.");
                }
            }
        }

        internal bool IsCodexCapabilityRequired(
            D045PermissionCapability capability)
        {
            lock (_gate)
                return _codexTaskPlan?.RequiredCapabilities.Contains(capability)
                    == true;
        }

        internal bool IsCodexCapabilityStillRequired(
            D045PermissionCapability capability)
        {
            lock (_gate)
            {
                return _codexTaskPlan?.RequiredCapabilities.Contains(capability)
                        == true
                    && !HasAnyVerifiedCapabilityLocked(
                        HarnessCapabilityToken(capability));
            }
        }

        internal bool IsCodexCapabilityExecutableNow(
            D045PermissionCapability capability)
        {
            lock (_gate)
            {
                return D045CodexCapabilitySequence.IsExecutableNow(
                    _codexTaskPlan,
                    capability,
                    candidate => HasAnyVerifiedCapabilityLocked(
                        HarnessCapabilityToken(candidate)));
            }
        }

        internal bool TryGetPendingCodexCapabilityPrerequisite(
            D045PermissionCapability capability,
            out D045PermissionCapability prerequisite)
        {
            lock (_gate)
            {
                return D045CodexCapabilitySequence.TryGetPendingPrerequisite(
                    _codexTaskPlan,
                    capability,
                    candidate => HasAnyVerifiedCapabilityLocked(
                        HarnessCapabilityToken(candidate)),
                    out prerequisite);
            }
        }

        internal bool TryGetVerifiedHostApplicationWindowTarget(
            out string exactWindowTarget)
        {
            lock (_gate)
            {
                exactWindowTarget = _verifiedHostApplicationProcessId;
                return exactWindowTarget.Length > 0;
            }
        }

        internal bool IsFinalizingVerifiedGoal
            => _terminalKernel.IsFinalizingWithoutTools;

        internal D045AgentTaskPhase TaskPhase
            => _terminalKernel.Phase;

        internal D045AgentTaskStopReason StopReason
            => _terminalKernel.StopReason;

        internal string OperationSessionId
        {
            get
            {
                lock (_gate)
                    return _operation?.OperationId ?? string.Empty;
            }
        }

        internal bool RequiresHostApplicationLaunch
        {
            get
            {
                lock (_gate)
                    return _requiredHostApplicationReference.Length > 0;
            }
        }

        internal bool RequiresVisibleHostApplicationWindowTarget
        {
            get
            {
                lock (_gate)
                {
                    return _codexTaskPlan?.RequiredCapabilities.Any(
                        capability => capability is
                            D045PermissionCapability.ExternalAppSemanticUiInspect
                            or D045PermissionCapability.ExternalAppSemanticUiAction
                            or D045PermissionCapability.ArbitraryExternalAppInputKeystrokes
                            or D045PermissionCapability.ExternalAppPointerInput
                            or D045PermissionCapability.WindowControl) == true;
                }
            }
        }

        internal D045AgentTaskDirective ObserveImmediateStop(
            D045AgentTaskStopReason stopReason)
            => _terminalKernel.ObserveStop(stopReason);

        internal void BindOperation(
            PlayerTurnOperationHandle operation,
            long permissionRevision)
        {
            if (operation == null)
                throw new ArgumentNullException(nameof(operation));
            if (permissionRevision < 0)
                throw new ArgumentOutOfRangeException(nameof(permissionRevision));
            var requestedProfile =
                ResolveHostOwnedAgentLoopBudgetProfile(operation);
            var selectedBudget =
                D045WorkbenchExecutionBudgetCatalog.Get(requestedProfile);
            lock (_gate)
            {
                if (_operation == null)
                {
                    _operation = operation;
                    _permissionRevision = permissionRevision;
                    _isWorkbenchOperation = IsWorkbenchOperation(operation);
                    _budgetProfile = selectedBudget.Profile;
                    _maximumRounds = selectedBudget.MaximumRounds;
                    _maximumCalls = selectedBudget.MaximumCalls;
                    _maximumDuration = selectedBudget.MaximumDuration;
                    _startedTimestamp = Stopwatch.GetTimestamp();
                    return;
                }
                if (!_operation.Matches(operation)
                    || _permissionRevision != permissionRevision
                    || _budgetProfile != selectedBudget.Profile)
                {
                    throw new InvalidOperationException(
                        "The agent operation authority or host-owned budget "
                        + "changed during one turn.");
                }
            }
        }

        internal void RequireCodexTaskPlan(
            D045CodexTaskPlan plan,
            D045AgentToolManifest manifest)
        {
            if (plan is null)
                throw new ArgumentNullException(nameof(plan));
            if (manifest is null)
                throw new ArgumentNullException(nameof(manifest));
            lock (_gate)
            {
                if (_codexTaskPlan is null)
                {
                    _codexTaskPlan = plan;
                    _toolManifest = manifest;
                    return;
                }
                if (_codexTaskPlan.Goals != plan.Goals
                    || !_codexTaskPlan.RequiredCapabilities.SequenceEqual(
                        plan.RequiredCapabilities)
                    || _toolManifest is null
                    || _toolManifest.PermissionRevision
                        != manifest.PermissionRevision
                    || !_toolManifest.CapabilityTokens.SequenceEqual(
                        manifest.CapabilityTokens,
                        StringComparer.Ordinal))
                {
                    throw new InvalidOperationException(
                        "The host-frozen workstation plan or tool manifest "
                        + "changed during one turn.");
                }
            }
        }

        internal void RegisterSemanticObservation(
            Guid taskId,
            D045SemanticObservationReceipt receipt)
        {
            if (taskId == Guid.Empty)
                throw new ArgumentOutOfRangeException(nameof(taskId));
            if (receipt is null)
                throw new ArgumentNullException(nameof(receipt));
            lock (_gate)
            {
                if (!receipt.Complete
                    || receipt.Ambiguous
                    || receipt.Candidates.Count != 1
                    || !receipt.Candidates[0].IsRedeemable
                    || (receipt.Candidates[0].Kind
                            != D045SemanticLocalTargetKind.Application
                        && !SemanticTargetMatches(
                            receipt.Candidates[0].SafeDisplayLeaf)))
                {
                    return;
                }
                foreach (var candidate in receipt.Candidates)
                {
                    _semanticTargets[candidate.OpaqueTargetReference] =
                        new SemanticTargetBinding(
                            taskId,
                            receipt.QueryKind,
                            receipt.Purpose,
                            receipt.Capability,
                            receipt.PermissionRevision,
                            candidate.Kind,
                            candidate.TargetFingerprint,
                            candidate.HarnessTargetFingerprint);
                }
            }
        }

        internal void RegisterHostApplicationObservation(
            HostApplicationPreObservation? observation)
        {
            if (observation is null)
                return;
            lock (_gate)
            {
                if (_operation is null)
                {
                    throw new InvalidOperationException(
                        "The host application observation requires a bound operation.");
                }
                if (observation.Receipt.PermissionRevision
                    != _permissionRevision)
                {
                    throw new InvalidOperationException(
                        "The host application observation permission revision changed.");
                }
                if (_registeredHostApplicationReference.Length > 0
                    && (!string.Equals(
                            _registeredHostApplicationReference,
                            observation.TargetReference,
                            StringComparison.Ordinal)
                        || _registeredHostApplicationReferenceDeadlineUtc
                            != observation.ReferenceDeadlineUtc))
                {
                    throw new InvalidOperationException(
                        "The host application observation changed during one turn.");
                }
                if (_registeredHostApplicationReference.Length > 0)
                    return;
                _registeredHostApplicationReference =
                    observation.TargetReference;
                _registeredHostApplicationReferenceDeadlineUtc =
                    observation.ReferenceDeadlineUtc;
                _requiredHostApplicationReference =
                    observation.TargetReference;
                _hostApplicationReferenceDeadlineUtc =
                    observation.ReferenceDeadlineUtc;
            }
            RegisterSemanticObservation(
                observation.TaskId,
                observation.Receipt);
        }

        internal bool TryCreateSemanticReferenceUse(
            string targetReference,
            out D045SemanticTargetReferenceUse? use)
        {
            use = null;
            lock (_gate)
            {
                if (_operation is null
                    || !_semanticTargets.TryGetValue(
                        targetReference,
                        out var binding))
                {
                    return false;
                }
                use = new D045SemanticTargetReferenceUse(
                    targetReference,
                    _operation.OperationId,
                    binding.TaskId,
                    binding.QueryKind,
                    binding.Purpose,
                    binding.Capability,
                    binding.PermissionRevision,
                    binding.Kind,
                    binding.TargetFingerprint);
                return true;
            }
        }

        internal void RetireSemanticReference(string targetReference)
        {
            lock (_gate)
            {
                _semanticTargets.Remove(targetReference);
                if (string.Equals(
                        _requiredHostApplicationReference,
                        targetReference,
                        StringComparison.Ordinal))
                {
                    _requiredHostApplicationReference = string.Empty;
                    _hostApplicationReferenceDeadlineUtc =
                        DateTimeOffset.MaxValue;
                }
            }
        }

        internal D045AgentTaskDirective ObserveToolBatch(
            LocalActionGoal actionGoal,
            bool executionMustStop,
            D045AgentTaskStopReason stopReason)
            => _terminalKernel.ObserveToolBatch(
                actionGoal != LocalActionGoal.None
                    && HasVerifiedHarnessReceiptFor(actionGoal),
                executionMustStop,
                executionMustStop
                    ? stopReason == D045AgentTaskStopReason.None
                        ? D045AgentTaskStopReason.GoalIncomplete
                        : stopReason
                    : D045AgentTaskStopReason.None);

        internal D045AgentTaskDirective ObserveVerifiedGoalFinalization(
            bool providerReplyIsUsable)
            => _terminalKernel.ObserveFinalization(
                providerReplyIsUsable);

        internal void RequireOpenTargetKind(LocalOpenTargetKind kind)
        {
            if (kind == LocalOpenTargetKind.Any)
                return;
            lock (_gate)
            {
                if (_requiredOpenTargetKind == LocalOpenTargetKind.Any)
                {
                    _requiredOpenTargetKind = kind;
                    return;
                }
                if (_requiredOpenTargetKind != kind)
                {
                    throw new InvalidOperationException(
                        "The host open-target goal changed during one agent turn.");
                }
            }
        }

        internal void RequireExpectedOpenLeaf(string leaf)
        {
            if (string.IsNullOrWhiteSpace(leaf))
                return;
            var normalized = NormalizeExplicitLocalOpenLeaf(leaf);
            lock (_gate)
            {
                if (_expectedOpenLeaf.Length == 0)
                {
                    _expectedOpenLeaf = normalized;
                    return;
                }
                if (!string.Equals(
                        _expectedOpenLeaf,
                        normalized,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "The host expected leaf changed during one agent turn.");
                }
            }
        }

        internal void RequireExpectedSemanticTarget(string target)
        {
            if (string.IsNullOrWhiteSpace(target))
                return;
            var normalized = NormalizeSemanticTargetIdentity(target);
            if (normalized.Length == 0)
                return;
            lock (_gate)
            {
                if (_expectedSemanticTarget.Length == 0)
                {
                    _expectedSemanticTarget = normalized;
                    return;
                }
                if (!string.Equals(
                        _expectedSemanticTarget,
                        normalized,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "The host semantic target changed during one agent turn.");
                }
            }
        }

        internal bool SemanticTargetMatches(string value)
        {
            lock (_gate)
            {
                return _expectedSemanticTarget.Length == 0
                    || string.Equals(
                        _expectedSemanticTarget,
                        NormalizeSemanticTargetIdentity(value),
                        StringComparison.Ordinal);
            }
        }

        internal void RequireHostEffectTarget(
            HostEffectTargetDescriptor? descriptor)
        {
            if (descriptor is null)
                return;
            lock (_gate)
            {
                if (_hostEffectTarget is null)
                {
                    _hostEffectTarget = descriptor;
                    return;
                }
                if (!string.Equals(
                        _hostEffectTarget.Fingerprint,
                        descriptor.Fingerprint,
                        StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "The host effect-target goal changed during one agent turn.");
                }
            }
        }

        internal bool TryAdmitHostEffectTarget(
            D045PermissionCapability capability,
            string requestedTarget,
            string secondaryTarget,
            string payload,
            out string goalTargetFingerprint,
            out string reason)
        {
            goalTargetFingerprint = string.Empty;
            reason = string.Empty;
            if (capability is not (
                    D045PermissionCapability.LocalDataCreate
                    or D045PermissionCapability.RecycleBinDelete
                    or D045PermissionCapability.PermanentDelete
                    or D045PermissionCapability.GracefulProcessClose
                    or D045PermissionCapability.ForceTerminateProcess
                    or D045PermissionCapability.GeneralElevationAdminAccess))
            {
                return true;
            }
            lock (_gate)
            {
                if (capability == D045PermissionCapability.LocalDataCreate
                    && _codexTaskPlan?.IsExplicit == true
                    && _codexTaskPlan.RequiredCapabilities.Contains(capability)
                    && _toolManifest?.Contains(capability) == true)
                {
                    goalTargetFingerprint = Convert.ToHexString(
                        SHA256.HashData(Encoding.UTF8.GetBytes(
                            requestedTarget + "\n" + secondaryTarget)));
                    return true;
                }
                if (_hostEffectTarget is null)
                {
                    reason = "The host has no exact player-authored target for this destructive or elevated capability.";
                    return false;
                }
                if (!_hostEffectTarget.Matches(
                        capability,
                        requestedTarget,
                        secondaryTarget,
                        payload))
                {
                    reason = "The requested effect target does not match the host-frozen player target.";
                    return false;
                }
                goalTargetFingerprint = _hostEffectTarget.Fingerprint;
                return true;
            }
        }

        internal int Rounds
        {
            get
            {
                lock (_gate)
                    return _rounds;
            }
        }

        internal bool TryBeginRound(out string reason)
        {
            lock (_gate)
            {
                if (!IsOperationLiveLocked())
                {
                    reason = "The player operation was cancelled before another "
                        + "tool round could start.";
                    return false;
                }
                if (!PermissionAuthorityStillValidLocked())
                {
                    reason = "The permission revision changed before this "
                        + "local effect could be admitted.";
                    return false;
                }
                if (!_terminalKernel.EffectsMayRun)
                {
                    reason = "The host already verified this task, so no "
                        + "additional local effect may start during finalization.";
                    return false;
                }
                if (RemainingLocked() <= TimeSpan.Zero)
                {
                    reason = "The bounded local agent deadline expired before "
                        + "another tool round could start.";
                    return false;
                }
                if (_rounds >= _maximumRounds)
                {
                    reason = "The bounded local agent reached its host-owned "
                        + "round limit (" + _maximumRounds + " rounds).";
                    return false;
                }
                _rounds++;
                reason = string.Empty;
                return true;
            }
        }

        internal bool TryAdmitCall(
            GeminiFunctionCallData call,
            out string intentFingerprint,
            out TimeSpan remainingExecutionTime,
            out string reason)
        {
            lock (_gate)
            {
                intentFingerprint = BuildAgentToolIntentFingerprint(call);
                remainingExecutionTime =
                    RemainingLocked() - AgentLoopDeadlineSafetyMargin;
                if (!IsOperationLiveLocked())
                {
                    reason = "The player operation was cancelled before this "
                        + "local effect could be admitted.";
                    return false;
                }
                if (!PermissionAuthorityStillValidLocked())
                {
                    reason = "The permission revision changed before this "
                        + "local effect could be admitted.";
                    return false;
                }
                if (!_terminalKernel.EffectsMayRun)
                {
                    reason = "The host already verified this task, so no "
                        + "additional local effect may be admitted.";
                    return false;
                }
                if (_requiredHostApplicationReference.Length > 0
                    && call.ArgumentFailureCode.Length == 0
                    && !IsRequiredHostApplicationEffectCallLocked(call))
                {
                    reason = "The host-pre-observed application requires one "
                        + "exact application_launch call using its opaque "
                        + "target reference.";
                    return false;
                }
                if (_verifiedHostApplicationProcessId.Length > 0
                    && call.ArgumentFailureCode.Length == 0
                    && IsHostApplicationBoundCapabilityCallLocked(call)
                    && !string.Equals(
                        GetToolString(call.Args, "target", 4096),
                        _verifiedHostApplicationProcessId,
                        StringComparison.Ordinal))
                {
                    reason = "The UI/input call did not use the exact host-bound "
                        + "application window target returned by the verified launch.";
                    return false;
                }
                if (remainingExecutionTime
                    < AgentLoopMinimumOperationDuration)
                {
                    reason = "The bounded local agent deadline does not leave "
                        + "enough time for another safe tool attempt.";
                    return false;
                }
                if (_executedCalls >= _maximumCalls)
                {
                    reason = "The bounded local agent reached its host-owned "
                        + "call limit (" + _maximumCalls + " calls).";
                    return false;
                }
                if (string.Equals(
                        _lastAdmittedIntent,
                        intentFingerprint,
                        StringComparison.Ordinal))
                {
                    reason = "This call was skipped because it immediately "
                        + "repeats the same capability and equivalent arguments "
                        + "without an intervening action that could change the "
                        + "result.";
                    return false;
                }
                if (TryBuildHarnessRetryIdentity(
                        call,
                        out var retryCapability,
                        out var retryTargetFingerprint)
                    && !_retryGate.TryAdmit(
                        retryCapability,
                        retryTargetFingerprint))
                {
                    reason = "This call was skipped before execution because "
                        + "the previous Harness receipt permits a retry only "
                        + "after the exact target changes.";
                    return false;
                }
                _lastAdmittedIntent = intentFingerprint;
                _executedCalls++;
                reason = string.Empty;
                return true;
            }
        }

        internal bool TryAdmitEffectDispatch()
        {
            lock (_gate)
            {
                if (!IsOperationLiveLocked()
                    || !PermissionAuthorityStillValidLocked()
                    || !_terminalKernel.EffectsMayRun
                    || RemainingLocked() <= TimeSpan.Zero
                    || _operation is null)
                {
                    return false;
                }

                var operation = _operation;
                bool HostAdmission()
                    => PlayerTurnOperations.TryAdmitEffectDispatch(operation);
                return _isWorkbenchOperation
                    ? TryAdmitWorkbenchEffectDispatch(
                        operation,
                        HostAdmission)
                    : HostAdmission();
            }
        }

        internal bool RecordResult(
            string intentFingerprint,
            GeminiToolResult result)
        {
            lock (_gate)
            {
                if (result.HasHarnessReceipt
                    && result.Verified
                    && !string.IsNullOrWhiteSpace(result.Capability))
                {
                    if (string.Equals(
                            result.Capability,
                            "application_launch",
                            StringComparison.Ordinal)
                        && result.ApplicationProcessId.Length > 0)
                    {
                        _verifiedHostApplicationProcessId =
                            result.ApplicationProcessId;
                    }
                    _verifiedReceipts.Add(new VerifiedHarnessEvidence(
                        result.TaskId,
                        result.Capability,
                        result.ResolvedTargetFingerprint,
                        result.ResolvedTargetKind,
                         result.ResolvedExtension,
                         result.ResolvedLeafNameFingerprint,
                         result.VerificationStrength,
                         result.PostconditionCode,
                         result.GoalTargetFingerprint,
                         OpenIdentityFingerprintLocked()));
                }
                if (result.HasHarnessReceipt
                    && !result.Verified
                    && result.RetryAllowed
                    && result.RetryRequiresChangedTarget)
                {
                    var targetFingerprint =
                        result.ResolvedTargetFingerprint.Length > 0
                        ? result.ResolvedTargetFingerprint
                        : result.TargetFingerprint;
                    _retryGate.ObserveResult(
                        result.Capability,
                        targetFingerprint,
                        result.RetryAllowed,
                        result.RetryRequiresChangedTarget);
                }
                else if (result.HasHarnessReceipt
                    && result.TargetFingerprint.Length > 0)
                {
                    _retryGate.ObserveResult(
                        result.Capability,
                        result.TargetFingerprint,
                        retryAllowed: false,
                        retryRequiresChangedTarget: false);
                }
                if (result.Success || !result.HasHarnessReceipt)
                    return false;
                var receiptFingerprint = result.OutcomeFingerprint;
                if (string.IsNullOrWhiteSpace(receiptFingerprint))
                {
                    var normalized = Regex.Replace(
                            result.Message.Trim().ToLowerInvariant(),
                            "\\s+",
                            " ")
                        .Trim();
                    receiptFingerprint = Convert.ToHexString(
                        SHA256.HashData(
                            Encoding.UTF8.GetBytes(normalized)));
                }
                return !_failedIntentReceipts.Add(
                    intentFingerprint + "|" + receiptFingerprint);
            }
        }

        internal LocalActionGoal GetSatisfiedGoals(LocalActionGoal actionGoal)
        {
            lock (_gate)
                return GetSatisfiedGoalsLocked(actionGoal);
        }

        internal LocalActionGoal GetRemainingGoals(LocalActionGoal actionGoal)
        {
            lock (_gate)
                return actionGoal & ~GetSatisfiedGoalsLocked(actionGoal);
        }

        private LocalActionGoal GetSatisfiedGoalsLocked(
            LocalActionGoal actionGoal)
        {
            var satisfied = LocalActionGoal.None;
            if (actionGoal.HasFlag(LocalActionGoal.ReadOrInspect)
                && HasAnyVerifiedCapabilityLocked(
                    "sanitized_status_read",
                    "clipboard_read",
                    "local_file_read",
                    "local_folder_enumerate",
                    "screenshot_capture"))
            {
                satisfied |= LocalActionGoal.ReadOrInspect;
            }
            if (actionGoal.HasFlag(LocalActionGoal.ReadFile)
                && HasAnyVerifiedCapabilityLocked("local_file_read"))
            {
                satisfied |= LocalActionGoal.ReadFile;
            }
            if (actionGoal.HasFlag(LocalActionGoal.EnumerateFolder)
                && HasAnyVerifiedCapabilityLocked("local_folder_enumerate"))
            {
                satisfied |= LocalActionGoal.EnumerateFolder;
            }
            if (actionGoal.HasFlag(LocalActionGoal.ClipboardRead)
                && HasAnyVerifiedCapabilityLocked("clipboard_read"))
            {
                satisfied |= LocalActionGoal.ClipboardRead;
            }
            if (actionGoal.HasFlag(LocalActionGoal.StatusRead)
                && HasAnyVerifiedCapabilityLocked("sanitized_status_read"))
            {
                satisfied |= LocalActionGoal.StatusRead;
            }
            if (actionGoal.HasFlag(LocalActionGoal.Open)
                && HasVerifiedOpenTargetLocked())
            {
                satisfied |= LocalActionGoal.Open;
            }
            if (actionGoal.HasFlag(LocalActionGoal.Create)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.Create,
                    "local_data_create"))
            {
                satisfied |= LocalActionGoal.Create;
            }
            if (actionGoal.HasFlag(LocalActionGoal.Delete)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.Delete,
                    "recycle_bin_delete"))
            {
                satisfied |= LocalActionGoal.Delete;
            }
            if (actionGoal.HasFlag(LocalActionGoal.PermanentDelete)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.PermanentDelete,
                    "permanent_delete"))
            {
                satisfied |= LocalActionGoal.PermanentDelete;
            }
            if (actionGoal.HasFlag(LocalActionGoal.Close)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.Close,
                    "graceful_process_close"))
            {
                satisfied |= LocalActionGoal.Close;
            }
            if (actionGoal.HasFlag(LocalActionGoal.ForceClose)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.ForceClose,
                    "force_terminate_process"))
            {
                satisfied |= LocalActionGoal.ForceClose;
            }
            if (actionGoal.HasFlag(LocalActionGoal.Shutdown)
                && HasAnyVerifiedCapabilityLocked("shutdown"))
                satisfied |= LocalActionGoal.Shutdown;
            if (actionGoal.HasFlag(LocalActionGoal.Restart)
                && HasAnyVerifiedCapabilityLocked("restart"))
                satisfied |= LocalActionGoal.Restart;
            if (actionGoal.HasFlag(LocalActionGoal.Screenshot)
                && HasAnyVerifiedCapabilityLocked("screenshot_capture"))
                satisfied |= LocalActionGoal.Screenshot;
            if (actionGoal.HasFlag(LocalActionGoal.ExternalInput)
                && HasAnyVerifiedCapabilityLocked("external_app_input"))
                satisfied |= LocalActionGoal.ExternalInput;
            if (actionGoal.HasFlag(LocalActionGoal.RawShell)
                && HasAnyVerifiedCapabilityLocked("raw_shell"))
                satisfied |= LocalActionGoal.RawShell;
            if (actionGoal.HasFlag(LocalActionGoal.Elevation)
                && HasVerifiedHostTargetCapabilityLocked(
                    LocalActionGoal.Elevation,
                    "elevation"))
                satisfied |= LocalActionGoal.Elevation;
            if (actionGoal.HasFlag(LocalActionGoal.Workstation)
                && _codexTaskPlan?.IsExplicit == true
                && _codexTaskPlan.RequiredCapabilities.All(capability =>
                    HasAnyVerifiedCapabilityLocked(
                        HarnessCapabilityToken(capability))))
            {
                satisfied |= LocalActionGoal.Workstation;
            }
            if (actionGoal.HasFlag(LocalActionGoal.UnsupportedEffect))
                satisfied &= ~LocalActionGoal.UnsupportedEffect;
            if (actionGoal.HasFlag(LocalActionGoal.CorrelateCreateOpen)
                && CreateAndOpenTargetsMatchLocked())
            {
                satisfied |= LocalActionGoal.CorrelateCreateOpen;
            }
            return satisfied;
        }

        internal bool HasVerifiedHarnessReceiptFor(
            LocalActionGoal actionGoal)
        {
            lock (_gate)
            {
                if (actionGoal == LocalActionGoal.None)
                    return true;
                return !actionGoal.HasFlag(LocalActionGoal.UnsupportedEffect)
                    && GetSatisfiedGoalsLocked(actionGoal) == actionGoal;
            }
        }

        internal string VerifiedCompletionEvidenceSummary()
        {
            lock (_gate)
            {
                if (_codexTaskPlan?.IsExplicit == true
                    && _codexTaskPlan.RequiredCapabilities.All(capability =>
                        HasAnyVerifiedCapabilityLocked(
                            HarnessCapabilityToken(capability))))
                {
                    return "all "
                        + _codexTaskPlan.RequiredCapabilities.Count
                            .ToString(CultureInfo.InvariantCulture)
                        + " host-required workstation capability postconditions "
                        + "were verified";
                }
                if (_verifiedReceipts.Any(receipt => receipt.Capability is
                    "shutdown" or "restart"))
                    return "the exact Windows power request was scheduled";
                if (_verifiedReceipts.Any(receipt =>
                    string.Equals(
                        receipt.Capability,
                        "local_content_open",
                        StringComparison.Ordinal)
                    && receipt.PostconditionCode
                        == D045HarnessPostconditionCode.DispatchAccepted))
                    return "the exact content-open dispatch accepted";
                if (_verifiedReceipts.Any(receipt =>
                    string.Equals(receipt.Capability, "raw_shell",
                        StringComparison.Ordinal)))
                    return "the shell process returned exit code zero; no other "
                        + "semantic effect was observed";
                return "all required capability-specific postconditions were "
                    + "observed at their recorded verification strengths";
            }
        }

        private bool HasAnyVerifiedCapabilityLocked(
            params string[] capabilityTokens)
            => _verifiedReceipts.Any(receipt =>
                capabilityTokens.Contains(
                    receipt.Capability,
                    StringComparer.Ordinal));

        private bool HasVerifiedHostTargetCapabilityLocked(
            LocalActionGoal goal,
            string capabilityToken)
            => _hostEffectTarget is not null
                && _hostEffectTarget.Goal == goal
                && _verifiedReceipts.Any(receipt =>
                    string.Equals(
                        receipt.Capability,
                        capabilityToken,
                        StringComparison.Ordinal)
                    && string.Equals(
                        receipt.GoalTargetFingerprint,
                        _hostEffectTarget.Fingerprint,
                        StringComparison.Ordinal));

        private bool HasVerifiedOpenTargetLocked()
        {
            var openIdentityFingerprint = OpenIdentityFingerprintLocked();
            if (openIdentityFingerprint.Length == 0)
                return false;
            bool IdentityMatches(VerifiedHarnessEvidence receipt)
                => string.Equals(
                    receipt.HostOpenIdentityFingerprint,
                    openIdentityFingerprint,
                    StringComparison.Ordinal);
            var expectedLeafFingerprint = _expectedOpenLeaf.Length == 0
                ? string.Empty
                : Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(
                    D045HarnessRequest.NormalizeLeafName(_expectedOpenLeaf)
                        .ToUpperInvariant())));
            bool LeafMatches(VerifiedHarnessEvidence receipt)
            {
                if (expectedLeafFingerprint.Length == 0)
                    return false;
                if (string.Equals(
                        receipt.ResolvedLeafNameFingerprint,
                        expectedLeafFingerprint,
                        StringComparison.Ordinal))
                {
                    return true;
                }

                // A trusted extensionless player leaf denotes a stem.  The
                // resolver may select one unique safe file (for example
                // "左鞋" -> "左鞋.stl"); bind that exact observed extension
                // instead of losing the verified completion at the ledger.
                if (Path.HasExtension(_expectedOpenLeaf)
                    || string.IsNullOrWhiteSpace(receipt.ResolvedExtension))
                {
                    return false;
                }
                var fullLeaf = D045HarnessRequest.NormalizeLeafName(
                    _expectedOpenLeaf + receipt.ResolvedExtension);
                var fullLeafFingerprint = Convert.ToHexString(
                    SHA256.HashData(Encoding.UTF8.GetBytes(
                        fullLeaf.ToUpperInvariant())));
                return string.Equals(
                    receipt.ResolvedLeafNameFingerprint,
                    fullLeafFingerprint,
                    StringComparison.Ordinal);
            }
            return _requiredOpenTargetKind switch
            {
                LocalOpenTargetKind.File => _verifiedReceipts.Any(receipt =>
                    IdentityMatches(receipt)
                    && string.Equals(
                        receipt.Capability,
                        "local_content_open",
                        StringComparison.Ordinal)
                    && receipt.ResolvedTargetKind
                        == D045ExpectedTargetKind.File
                    && LeafMatches(receipt)),
                LocalOpenTargetKind.Directory => _verifiedReceipts.Any(receipt =>
                    IdentityMatches(receipt)
                    && string.Equals(
                        receipt.Capability,
                        "local_content_open",
                        StringComparison.Ordinal)
                    && receipt.ResolvedTargetKind
                        == D045ExpectedTargetKind.Directory
                    && LeafMatches(receipt)),
                LocalOpenTargetKind.Application => _verifiedReceipts.Any(receipt =>
                    IdentityMatches(receipt)
                    && string.Equals(
                        receipt.Capability,
                        "application_launch",
                        StringComparison.Ordinal)
                    && receipt.ResolvedTargetKind
                        == D045ExpectedTargetKind.Application),
                _ => false
            };
        }

        private string OpenIdentityFingerprintLocked()
            => _expectedSemanticTarget.Length == 0
                ? string.Empty
                : Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(
                    "D045.HOST.OPEN.IDENTITY.V1\n"
                    + _expectedSemanticTarget)));

        private bool CreateAndOpenTargetsMatchLocked()
        {
            var createdTargets = _verifiedReceipts
                .Where(receipt => string.Equals(
                    receipt.Capability,
                    "local_data_create",
                    StringComparison.Ordinal))
                .Select(receipt => receipt.ResolvedTargetFingerprint)
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .ToHashSet(StringComparer.Ordinal);
            var openedTargets = _verifiedReceipts
                .Where(receipt => receipt.Capability is
                    "local_content_open" or "application_launch")
                .Select(receipt => receipt.ResolvedTargetFingerprint)
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .ToHashSet(StringComparer.Ordinal);
            return createdTargets.Count > 0
                && openedTargets.Count > 0
                && createdTargets.Overlaps(openedTargets);
        }

        internal bool TryCreateDeadlineCancellationSource(
            out CancellationTokenSource? cancellationSource,
            out string reason)
        {
            lock (_gate)
            {
                if (!IsOperationLiveLocked())
                {
                    cancellationSource = null;
                    reason = "The player operation was cancelled before the "
                        + "provider request could start.";
                    return false;
                }
                if (!PermissionAuthorityStillValidLocked())
                {
                    cancellationSource = null;
                    reason = "The permission revision changed before this "
                        + "provider request could start.";
                    return false;
                }
                var remaining = RemainingLocked();
                if (_requiredHostApplicationReference.Length > 0)
                {
                    var referenceRemaining =
                        _hostApplicationReferenceDeadlineUtc
                        - DateTimeOffset.UtcNow;
                    if (referenceRemaining < remaining)
                        remaining = referenceRemaining;
                }
                if (remaining < AgentLoopMinimumOperationDuration)
                {
                    cancellationSource = null;
                    reason = "The bounded local agent deadline does not leave "
                        + "enough time for another provider request.";
                    return false;
                }
                var operationToken = _operation == null
                    ? CancellationToken.None
                    : PlayerTurnOperations.GetCancellationToken(_operation);
                var workbenchToken = _operation == null
                    ? CancellationToken.None
                    : GetWorkbenchOperationCancellationToken(_operation);
                cancellationSource = operationToken.CanBeCanceled
                        || workbenchToken.CanBeCanceled
                    ? CancellationTokenSource.CreateLinkedTokenSource(
                        operationToken,
                        workbenchToken)
                    : new CancellationTokenSource();
                cancellationSource.CancelAfter(remaining);
                reason = string.Empty;
                return true;
            }
        }

        private TimeSpan RemainingLocked()
        {
            var elapsedTicks = Math.Max(
                0,
                Stopwatch.GetTimestamp() - _startedTimestamp);
            var elapsed = TimeSpan.FromSeconds(
                elapsedTicks / (double)Stopwatch.Frequency);
            var remaining = _maximumDuration - elapsed;
            return remaining > TimeSpan.Zero
                ? remaining
                : TimeSpan.Zero;
        }

        private bool IsRequiredHostApplicationEffectCallLocked(
            GeminiFunctionCallData call)
        {
            if (!string.Equals(
                    call.Name,
                    "run_local_task",
                    StringComparison.Ordinal))
            {
                return false;
            }
            return string.Equals(
                    GetToolString(call.Args, "capability", 80),
                    "application_launch",
                    StringComparison.OrdinalIgnoreCase)
                && string.Equals(
                    GetToolString(call.Args, "target", 4096),
                    _requiredHostApplicationReference,
                    StringComparison.Ordinal)
                && GetToolString(call.Args, "secondary_target", 4096).Length
                    == 0
                && GetToolString(call.Args, "payload", 65536).Length == 0;
        }

        private static bool IsHostApplicationBoundCapabilityCallLocked(
            GeminiFunctionCallData call)
        {
            if (!string.Equals(call.Name, "run_local_task", StringComparison.Ordinal)
                && !string.Equals(
                    call.Name,
                    D045CodexProviderToolContract.FunctionName,
                    StringComparison.Ordinal))
            {
                return false;
            }
            return GetToolString(call.Args, "capability", 80)
                .Trim()
                .ToLowerInvariant() is
                    "external_app_input"
                    or "external_app_semantic_ui_inspect"
                    or "external_app_semantic_ui_action"
                    or "window_control";
        }

        private bool IsOperationLiveLocked()
            => _operation != null
                && PlayerTurnOperations.IsActive(_operation)
                && (!_isWorkbenchOperation
                    || IsWorkbenchOperationLive(_operation));

        private bool PermissionAuthorityStillValidLocked()
        {
            if (_permissionRevision == 0)
                return true;
            try
            {
                return LocalPermissionStore.Load().Snapshot.Revision
                    == _permissionRevision;
            }
            catch
            {
                return false;
            }
        }

