        private static string BuildAgentToolIntentFingerprint(
            GeminiFunctionCallData call)
        {
            var canonicalArguments = call.Args.ValueKind
                    == JsonValueKind.Object
                && string.Equals(
                    call.Name,
                    "run_local_task",
                    StringComparison.Ordinal)
                    ? CanonicalizeHarnessIntentArguments(call.Args)
                    : CanonicalizeAgentToolArguments(call.Args);
            var digest = Convert.ToHexString(
                SHA256.HashData(
                    Encoding.UTF8.GetBytes(canonicalArguments)));
            return call.Name.Trim().ToLowerInvariant() + "|" + digest;
        }

        private bool TryBuildHarnessRetryIdentity(
            GeminiFunctionCallData call,
            out string capability,
            out string targetFingerprint)
        {
            capability = string.Empty;
            targetFingerprint = string.Empty;
            if (!string.Equals(
                    call.Name,
                    "run_local_task",
                    StringComparison.Ordinal)
                || call.Args.ValueKind != JsonValueKind.Object)
            {
                return false;
            }

            capability = GetToolString(call.Args, "capability", 80)
                .Trim()
                .ToLowerInvariant();
            if (capability.Length == 0)
                return false;
            var target = GetToolString(call.Args, "target", 32768);
            var secondaryTarget = GetToolString(
                call.Args,
                "secondary_target",
                4096);
            if (target.StartsWith("d045ref_", StringComparison.Ordinal)
                && _semanticTargets.TryGetValue(target, out var binding))
            {
                targetFingerprint = binding.HarnessTargetFingerprint;
                return targetFingerprint.Length != 0;
            }
            targetFingerprint = Convert.ToHexString(
                SHA256.HashData(
                    Encoding.UTF8.GetBytes(
                        target + "\n" + secondaryTarget)));
            return true;
        }

        private static string CanonicalizeHarnessIntentArguments(
            JsonElement value)
        {
            var relevant = new[]
            {
                "capability",
                "target",
                "secondary_target",
                "payload"
            };
            return "{"
                + string.Join(
                    ",",
                    relevant.Select(name =>
                        JsonSerializer.Serialize(name)
                        + ":"
                        + (value.TryGetProperty(name, out var argument)
                            ? CanonicalizeAgentToolArguments(argument)
                            : "null")))
                + "}";
        }

        private static string CanonicalizeAgentToolArguments(
            JsonElement value)
        {
            switch (value.ValueKind)
            {
                case JsonValueKind.Object:
                    return "{"
                        + string.Join(
                            ",",
                            value.EnumerateObject()
                                .OrderBy(
                                    property => property.Name,
                                    StringComparer.Ordinal)
                                .Select(property =>
                                    JsonSerializer.Serialize(
                                        property.Name.ToLowerInvariant())
                                    + ":"
                                    + CanonicalizeAgentToolArguments(
                                        property.Value)))
                        + "}";
                case JsonValueKind.Array:
                    return "["
                        + string.Join(
                            ",",
                            value.EnumerateArray()
                                .Select(CanonicalizeAgentToolArguments))
                        + "]";
                case JsonValueKind.String:
                    return JsonSerializer.Serialize(
                        (value.GetString() ?? string.Empty)
                            .Trim()
                            .Replace('\\', '/')
                            .ToLowerInvariant());
                case JsonValueKind.Number:
                    return value.GetRawText();
                case JsonValueKind.True:
                    return "true";
                case JsonValueKind.False:
                    return "false";
                case JsonValueKind.Null:
                case JsonValueKind.Undefined:
                    return "null";
                default:
                    return value.GetRawText();
            }
        }
    }

