    private static object[] BuildGeminiContents()
    {
        List<ChatTurn> snapshot;
        lock (MemoryLock)
            snapshot = new List<ChatTurn>(RecentConversation);

        var contents = new List<object>();
        for (var i = 0; i < snapshot.Count; i++)
        {
            var turn = snapshot[i];
            var text = turn.Text;
            contents.Add(new { role = turn.Role, parts = new[] { new { text } } });
        }
        return contents.ToArray();
    }

    internal static void LoadAiNoteState()
    {
        try
        {
            if (File.Exists(AiNoteStatePath))
                _aiNoteState = JsonSerializer.Deserialize<AiNoteState>(File.ReadAllText(AiNoteStatePath)) ?? new AiNoteState();
            var projection = AiNoteStartupProjection.ApplyInMemory(
                _aiNoteState,
                DateTimeOffset.Now);
            Plugin.PluginLog.LogInfo(
                $"Loaded AI note scheduler read-only: pending={_aiNoteState.Pending.Count}, "
                + $"recentDeliveries={_aiNoteState.DeliveredAt.Count}, "
                + $"recoveredInMemory={projection.RecoveredStatusCount}, "
                + $"expiredInMemory={projection.ExpiredDeliveryCount}.");
        }
        catch (Exception exception)
        {
            _aiNoteState = new AiNoteState();
            Plugin.PluginLog.LogWarning($"Could not load AI note state: {exception.Message}");
        }
    }

    private static void SaveAiNoteState()
    {
        lock (AiNoteLock)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(AiNoteStatePath) ?? PlayerProfileDirectory);
            File.WriteAllText(AiNoteStatePath, JsonSerializer.Serialize(_aiNoteState,
                new JsonSerializerOptions { WriteIndented = true, Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping }), Encoding.UTF8);
        }
    }

    private static void ConsiderAiNoteEvent(string userText, string reply)
    {
        if (!Plugin.AiNotesEnabled.Value || IsManualNoteInboxToolEnabled() || Plugin.HermesDailyNoteEnabled.Value
            || ContainsSensitiveNoteData(userText))
            return;
        if (Regex.IsMatch(userText, "(取消|算了|不用了|別再提|别再提|忘了吧|キャンセル|やめて|forget it|cancel)", RegexOptions.IgnoreCase))
            return;

        string category;
        string emotion;
        if (Regex.IsMatch(userText, "(明天|後天|下週|下周|等等要|待會要|考試|面試|報告|手術|約會|旅行|出發|deadline|tomorrow|exam|interview|明日|試験|面接)", RegexOptions.IgnoreCase))
        {
            category = "upcoming";
            emotion = Regex.IsMatch(userText, "(緊張|害怕|擔心|焦慮|不安|怖い|心配|nervous|worried)", RegexOptions.IgnoreCase) ? "緊張，需要溫柔支持" : "期待中的重要安排";
        }
        else if (Regex.IsMatch(userText, "(完成了|成功了|做到了|通過了|过了|終於|终于|畢業|毕业|錄取|得獎|できた|合格|finished|succeeded|passed)", RegexOptions.IgnoreCase))
        {
            category = "achievement";
            emotion = "值得一起慶祝與記住";
        }
        else if (Regex.IsMatch(userText, "(難過|伤心|傷心|哭了|寂寞|孤單|失戀|分手|失敗|失败|被罵|壓力|压力|悲しい|寂しい|つらい|sad|lonely|heartbroken)", RegexOptions.IgnoreCase))
        {
            category = "comfort";
            emotion = "低落，需要安靜陪伴而非說教";
        }
        else if (Regex.IsMatch(userText, "(約定|答應我|記得|不要忘記|我們說好|说好|約束|覚えて|promise|remember this)", RegexOptions.IgnoreCase))
        {
            category = "promise";
            emotion = "兩人之間值得珍惜的約定";
        }
        else if (Regex.IsMatch(userText, "(喜歡妳|喜欢你|愛妳|爱你|謝謝妳|谢谢你|有妳真好|陪著我|大好き|愛してる|ありがとう|love you|thank you)", RegexOptions.IgnoreCase))
        {
            category = "bond";
            emotion = "親近、感謝與依戀";
        }
        else
        {
            return;
        }

        var now = DateTimeOffset.Now;
        var minimum = Math.Clamp(Plugin.AiNoteMinimumDelayMinutes.Value, 1, 1440);
        var maximum = Math.Clamp(Plugin.AiNoteMaximumDelayMinutes.Value, minimum, 2880);
        var delay = System.Random.Shared.Next(minimum, maximum + 1);
        var compactUser = CompactNoteContext(userText, 360);
        var compactReply = CompactNoteContext(reply, 360);
        lock (AiNoteLock)
        {
            var existing = _aiNoteState.Pending.LastOrDefault(item => item.HermesPublishedCandidate && item.Status == "pending" && item.Category == category && item.CreatedAt > now.AddHours(-6));
            if (existing != null)
            {
                existing.Topic = compactUser;
                existing.LatestContext = compactReply;
                existing.Emotion = emotion;
                SaveAiNoteState();
                Plugin.PluginLog.LogInfo($"Updated pending AI note event '{category}'.");
                return;
            }
            _aiNoteState.Pending.Add(new AiNoteEvent
            {
                Id = Guid.NewGuid().ToString("N"),
                HermesPublishedCandidate = true,
                Category = category,
                Topic = compactUser,
                LatestContext = compactReply,
                Emotion = emotion,
                CreatedAt = now,
                DeliverAfter = now.AddMinutes(delay),
                Status = "pending"
            });
            while (_aiNoteState.Pending.Count(item => item.HermesPublishedCandidate && item.Status == "pending") > 5)
                _aiNoteState.Pending.Remove(_aiNoteState.Pending.First(item => item.HermesPublishedCandidate && item.Status == "pending"));
            SaveAiNoteState();
        }
        Plugin.PluginLog.LogInfo($"Scheduled AI note event '{category}' after {delay} minutes (content hidden from log).");
    }

    private static void UpdatePendingAiNoteEvents(string userText)
    {
        if (!Plugin.AiNotesEnabled.Value)
            return;
        var cancel = Regex.IsMatch(userText, "(取消了|取消吧|算了|不用了|不去了|別再提|别再提|忘了吧|キャンセル|中止|やめて|cancel|forget it)", RegexOptions.IgnoreCase);
        var completed = Regex.IsMatch(userText, "(完成了|結束了|结束了|考完了|做完了|成功了|通過了|过了|終於好了|終わった|できた|finished|done|passed)", RegexOptions.IgnoreCase);
        if (!cancel && !completed)
            return;
        lock (AiNoteLock)
        {
            var item = _aiNoteState.Pending.LastOrDefault(value => value.HermesPublishedCandidate && value.Status == "pending");
            if (item == null) return;
            if (cancel)
            {
                item.Status = "cancelled";
                Plugin.PluginLog.LogInfo($"Cancelled pending AI note event '{item.Category}' from follow-up context.");
            }
            else
            {
                item.Category = "achievement";
                item.Emotion = "事情已經完成，適合祝賀並關心結果";
                item.LatestContext = CompactNoteContext(userText, 360);
                Plugin.PluginLog.LogInfo("Updated pending AI note event after the user reported completion.");
            }
            SaveAiNoteState();
        }
    }

    private static bool ContainsSensitiveNoteData(string text)
    {
        return Regex.IsMatch(text, "(api[ _-]?key|密碼|密码|驗證碼|验证码|信用卡|身分證|身份证|護照|passport|password|token|secret)", RegexOptions.IgnoreCase)
            || Regex.IsMatch(text, @"\b(?:\d[ -]*?){12,19}\b")
            || Regex.IsMatch(text, @"\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b", RegexOptions.IgnoreCase);
    }

    private static string CompactNoteContext(string text, int maximum)
    {
        var compact = Regex.Replace(text, @"\s+", " ").Trim();
        if (compact.Length <= maximum)
            return compact;
        var end = maximum - 1;
        if (end > 0 && char.IsHighSurrogate(compact[end - 1]))
            end--;
        return compact[..end] + "…";
    }

    private sealed class LivingProactiveNotePluginTransport
        : ILivingPreparedProviderTransport
    {
        private bool _dispatched;
        internal int Calls { get; private set; }
        internal LivingPreparedProviderRequest? Request { get; private set; }
        internal string ProviderRequestId { get; private set; } =
            string.Empty;

        public LivingPreparedProviderAcceptance Dispatch(
            LivingPreparedProviderRequest request)
        {
            if (_dispatched)
                throw new InvalidOperationException(
                    "D-025 proactive transport is single-use.");
            _dispatched = true;
            Calls++;
            Request = request
                ?? throw new ArgumentNullException(nameof(request));
            ProviderRequestId = "d025-f3-gemini-"
                + LivingPromptHash.Of(
                    request.RequestId
                    + "|"
                    + request.AttemptId)[..32];
            return new LivingPreparedProviderAcceptance(
                ProviderRequestId,
                request,
                request.AttemptedAt);
        }
    }

    private sealed class LivingProactiveNotePluginOperation
    {
        private int _cancellationDisposed;
        private int _outcomeAttempted;
        private int _providerExecutionStarted;

        internal AiNoteEvent Item { get; }
        internal ProactiveRespondRuntime DecisionRuntime { get; }
        internal ProactiveRespondAuthorization Authorization { get; }
        internal LivingProactiveNoteBridge Bridge { get; }
        internal LivingProactiveNoteSession Session { get; }
        internal LivingPromptCompositionHost PromptHost { get; }
        internal LivingProactiveNotePluginTransport Transport { get; }
        internal CharacterRuntimeIdentity RuntimeIdentity { get; }
        internal string EpochId { get; }
        internal Guid SituationId { get; }
        internal long SituationRevision { get; }
        internal string SituationFingerprint { get; }
        internal long ConfigurationGeneration { get; }
        internal LilithGameBridgeDisplayLocale DisplayLocale { get; }
        internal CancellationTokenSource Cancellation { get; } = new();
        internal bool ProviderExecutionStarted =>
            Volatile.Read(ref _providerExecutionStarted) != 0;

        internal LivingProactiveNotePluginOperation(
            AiNoteEvent item,
            ProactiveRespondRuntime decisionRuntime,
            ProactiveRespondAuthorization authorization,
            LivingProactiveNoteBridge bridge,
            LivingProactiveNoteSession session,
            LivingPromptCompositionHost promptHost,
            LivingProactiveNotePluginTransport transport,
            CharacterRuntimeIdentity runtimeIdentity,
            string epochId,
            Guid situationId,
            long situationRevision,
            string situationFingerprint,
            long configurationGeneration)
        {
            Item = item;
            DecisionRuntime = decisionRuntime;
            Authorization = authorization;
            Bridge = bridge;
            Session = session;
            PromptHost = promptHost;
            Transport = transport;
            RuntimeIdentity = runtimeIdentity;
            EpochId = LivingContinuityContractGuard.Identifier(
                epochId,
                nameof(epochId));
            SituationId = situationId;
            SituationRevision = situationRevision;
            SituationFingerprint = situationFingerprint;
            ConfigurationGeneration = configurationGeneration;
            // Capture Unity-owned locale before starting background work.
            DisplayLocale = ToGameHermesDisplayLocale(
                LilithGamePersonaLocaleProjector.Resolve(
                    GetAgentTurnLocale()).DisplayLocale);
            var remaining =
                Session.CompletionExpiresAt - DateTimeOffset.UtcNow;
            if (remaining <= TimeSpan.Zero)
                Cancellation.Cancel();
            else
                Cancellation.CancelAfter(remaining);
        }

        internal void DisposeCancellation()
        {
            if (Interlocked.Exchange(ref _cancellationDisposed, 1) == 0)
                Cancellation.Dispose();
        }

        internal void MarkProviderExecutionStarted()
            => Interlocked.Exchange(ref _providerExecutionStarted, 1);

        internal bool TryRecordOutcome(
            OutcomeStatus status,
            DateTimeOffset now)
        {
            if (Interlocked.Exchange(ref _outcomeAttempted, 1) != 0)
                return false;
            return DecisionRuntime.RecordOutcome(
                    Authorization,
                    status,
                    RuntimeIdentity,
                    SituationId,
                    SituationRevision,
                    now,
                    EpochId)
                .Admission == ProactiveRespondAdmission.OutcomeRecorded;
        }
    }

    private sealed class LivingProactiveNoteProviderResult
    {
        internal LivingProactiveNotePluginOperation Operation { get; }
        internal string? Text { get; }
        internal Exception? Fault { get; }
        internal bool WasCancelled { get; }

        internal LivingProactiveNoteProviderResult(
            LivingProactiveNotePluginOperation operation,
            string? text,
            Exception? fault,
            bool wasCancelled)
        {
            Operation = operation;
            Text = text;
            Fault = fault;
            WasCancelled = wasCancelled;
        }
    }

    private static void ProcessAiNoteScheduler()
    {
        ReconcileLivingProactiveNoteSource();
        ProcessLivingProactiveNoteProviderResults();
        while (PendingAiNotes.TryDequeue(out var generated))
        {
            if (generated.LivingContinuityOwned)
            {
                if (!MayCommitLivingProactiveNoteNativeWrite(
                        generated,
                        out var cancellationReason,
                        out var primaryPendingExecutionSubgate))
                {
                    MarkGeneratedLivingProactiveNoteRejected(
                        generated,
                        cancellationReason,
                        primaryPendingExecutionSubgate);
                    _aiNoteGenerationInFlight = false;
                    continue;
                }
                CommitLivingProactiveNoteNativeWrite(generated);
                _aiNoteGenerationInFlight = false;
                continue;
            }
            // There is no unowned writer or fallback generator in D059.
            Plugin.PluginLog.LogWarning(
                "Rejected an unowned AI note without native image output.");
            _aiNoteGenerationInFlight = false;
        }

        if (!Plugin.AiNotesEnabled.Value
            || IsManualNoteInboxToolEnabled()
            || Plugin.HermesDailyNoteEnabled.Value
            || _aiNoteGenerationInFlight
            || Time.unscaledTime < _nextAiNoteCheckAt)
            return;
        _nextAiNoteCheckAt = Time.unscaledTime + 30f;
        var now = DateTimeOffset.Now;
        AiNoteEvent? due;
        lock (AiNoteLock)
            due = _aiNoteState.Pending.FirstOrDefault(item => item.HermesPublishedCandidate && item.Status == "pending" && item.DeliverAfter <= now);
        if (due == null)
            return;
        var d029 = D029AggressiveIntegrationRuntime.GetSnapshot();
        if (D029PendingNoteSchedulerGate.ShouldHold(
                d029.Source.Status,
                d029.CurrentStep))
        {
            Plugin.PluginLog.LogInfo(
                "D-029 held one due AI Note until its bounded proactive "
                + "step; no player data, cooldown, provider or Note state "
                + "was changed.");
            return;
        }
        if (GetWindowsIdleSeconds() < Math.Clamp(Plugin.AiNoteRequiredAwayMinutes.Value, 0, 1440) * 60)
            return;
        var cooldown = TimeSpan.FromHours(Math.Clamp(Plugin.AiNoteCooldownHours.Value, 1, 720));
        if (_aiNoteState.DeliveredAt.Count > 0 && now - _aiNoteState.DeliveredAt.Max() < cooldown)
        {
            if (D029IsAwaiting(D029IntegrationStep.CombinedStress))
            {
                RecordD029Signal(
                    D029PluginSignal.ProactiveCooldownBlocked);
            }
            return;
        }
        if (_aiNoteState.DeliveredAt.Count(value => value >= now.AddDays(-7)) >= Math.Clamp(Plugin.AiNoteWeeklyLimit.Value, 1, 20))
            return;
        if (OfficialNoteWasJustDelivered(now))
            return;
        var language = GetAiInterfaceLanguage().Name;
        // Only the existing owned path may dispatch. If it declines, retain
        // the pending occurrence; never restore a legacy key or direct HTTP.
        TryStartLivingProactiveNote(due, language, now);
    }

    private static bool MayCommitLivingProactiveNoteNativeWrite(
        GeneratedAiNote generated,
        out LivingProactiveNoteCancellationReason cancellationReason,
        out LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate)
    {
        primaryPendingExecutionSubgate =
            LivingProactiveNotePrimaryPendingExecutionSubgate.None;
        var operation = generated.Operation;
        if (operation == null)
        {
            cancellationReason =
                LivingProactiveNoteCancellationReason
                    .NativeActiveOperationMismatch;
            return false;
        }
        if (!string.Equals(
                generated.EventId,
                operation.Item.Id,
                StringComparison.Ordinal))
        {
            cancellationReason =
                LivingProactiveNoteCancellationReason
                    .NativeOccurrenceMismatch;
            return false;
        }
        if (generated.ConfigurationGeneration
            != operation.ConfigurationGeneration)
        {
            cancellationReason =
                LivingProactiveNoteCancellationReason
                    .ConfigurationGenerationChanged;
            return false;
        }
        if (!generated.RuntimeIdentity.Matches(
                operation.RuntimeIdentity))
        {
            cancellationReason =
                LivingProactiveNoteCancellationReason
                    .RuntimeIdentityChanged;
            return false;
        }

        LivingProactiveNotePluginOperation? active;
        lock (LivingProactiveNoteLock)
            active = _livingProactiveNoteActive;
        var runtime = CurrentCharacterRuntimeIdentity();
        var capture = CaptureLivingProactiveNoteSituation(
            runtime,
            operation.SituationId,
            operation.SituationRevision,
            operation.ConfigurationGeneration);
        var now = DateTimeOffset.UtcNow;
        var facts = new LivingProactiveNoteFinalDeliveryFacts(
                exactActiveOperation: ReferenceEquals(active, operation),
                masterEnabled: capture.Situation.MasterEnabled,
                sourceEnabled:
                    Plugin.AiNotesEnabled.Value
                    && !IsManualNoteInboxToolEnabled()
                    && !Plugin.HermesDailyNoteEnabled.Value
                    && Plugin.Effective(
                        Plugin
                            .LivingContinuityProactiveNoteEnabled.Value)
                    && _livingProactiveNoteLastEnabled
                    && capture.Situation.SourceEnabled,
                configurationMatches:
                    operation.ConfigurationGeneration
                    == Interlocked.Read(
                        ref
                        _livingProactiveNoteConfigurationGeneration),
                runtimeMatches:
                    runtime.Matches(operation.RuntimeIdentity),
                epochMatches: string.Equals(
                    capture.Situation.EpochId,
                    operation.EpochId,
                    StringComparison.Ordinal),
                situationMatches: string.Equals(
                    capture.Fingerprint,
                    operation.SituationFingerprint,
                    StringComparison.Ordinal),
                isAvatarUnderDirectPlayerControl:
                    capture.Situation
                        .IsAvatarUnderDirectPlayerControl,
                isConversationBusy:
                    capture.Situation.IsConversationBusy,
                hasPendingExecution:
                    capture.Situation.HasPendingExecution,
                isQuietPeriod: capture.Situation.IsQuietPeriod,
                isCancelled:
                    operation.Cancellation.IsCancellationRequested,
                isBeforeCompletionDeadline:
                    now < operation.Session.CompletionExpiresAt);
        var mayCommit =
            LivingProactiveNoteDeliveryPolicy.MayCommitNativeWrite(facts);
        cancellationReason = mayCommit
            ? LivingProactiveNoteCancellationReason.None
            : LivingProactiveNoteCancellationClassifier.FromFinalDelivery(
                facts);
        primaryPendingExecutionSubgate =
            LivingProactiveNotePrimaryPendingExecutionSubgateClassifier
                .ForTerminalReason(
                    cancellationReason,
                    capture.PrimaryPendingExecutionSubgate);
        return mayCommit;
    }

    private static void CommitLivingProactiveNoteNativeWrite(
        GeneratedAiNote generated)
    {
        var operation = generated.Operation;
        if (operation == null)
        {
            MarkGeneratedLivingProactiveNoteRejected(
                generated,
                LivingProactiveNoteCancellationReason
                    .NativeActiveOperationMismatch);
            return;
        }

        var durableFileWritten = false;
        var completedAt = default(DateTimeOffset);
        try
        {
            var isolatedD029Sink =
                _d029IsolatedTestProfile != null;
            if (isolatedD029Sink
                && !_d029IsolatedNativeNotesReady)
            {
                throw new InvalidOperationException(
                    "The isolated D-029 Note sink is not ready.");
            }
            var path = isolatedD029Sink
                ? SaveD029IsolatedProactiveNote(generated)
                : SaveNativeNoteWithWriterOrigin(
                    generated.Text,
                    NativeNoteWriterOrigin
                        .ModLivingContinuityOwnedProactiveNote);
            completedAt = DateTimeOffset.UtcNow;
            durableFileWritten =
                LivingProactiveNoteDeliveryPolicy
                    .NativeWriteIsCompleted(true);
            lock (AiNoteLock)
            {
                var item = _aiNoteState.Pending.FirstOrDefault(
                    value => value.Id == generated.EventId);
                if (item != null)
                {
                    item.LivingContinuityOwned = true;
                    item.Status =
                        LivingProactiveNoteDeliveryPolicy.DeliveredStatus;
                }
                _aiNoteState.DeliveredAt.Add(completedAt);
                _aiNoteState.DeliveredPaths.Add(path);
                _aiNoteState.DeliveredAt.RemoveAll(
                    value => value < completedAt.AddDays(-30));
                SaveAiNoteState();
            }
            if (!isolatedD029Sink)
            {
                try
                {
                    NoteInbox.NotifySaved();
                }
                catch (Exception exception)
                {
                    // The native file is already the durable player-visible
                    // effect. Notification is only a best-effort UI refresh
                    // and cannot cause a retry or restore Legacy ownership.
                    Plugin.PluginLog.LogWarning(
                        "D-025 F3 native inbox refresh failed after the "
                        + "durable note write: "
                        + exception.GetType().Name);
                }
            }
            operation.TryRecordOutcome(
                OutcomeStatus.Completed,
                completedAt);
            RecordD029Signal(
                D029PluginSignal.ProactiveNoteCompleted,
                operation.RuntimeIdentity);
            ClearLivingProactiveNoteActive(operation);
            Plugin.PluginLog.LogInfo(
                isolatedD029Sink
                    ? "D-029 delivered one owned proactive Note to its "
                        + "private bounded test sink; the native inbox and "
                        + "production Notes were not touched."
                    : "D-025 F3 delivered one owned proactive note through "
                        + "the native inbox.");
        }
        catch (Exception exception)
        {
            if (durableFileWritten)
            {
                // A durable file is already an external effect. Record the
                // real result as success, retain no-fallback ownership and
                // start the fixed success budget instead of generating a
                // duplicate after a metadata fault.
                operation.TryRecordOutcome(
                    OutcomeStatus.Completed,
                    completedAt);
                RecordD029Signal(
                    D029PluginSignal.ProactiveNoteCompleted,
                    operation.RuntimeIdentity);
                operation.Item.LivingContinuityOwned = true;
                operation.Item.Status =
                    LivingProactiveNoteDeliveryPolicy.DeliveredStatus;
                ClearLivingProactiveNoteActive(operation);
                Plugin.PluginLog.LogWarning(
                    "D-025 F3 durable native write completed but its "
                    + "metadata update faulted: "
                    + exception.GetType().Name);
                return;
            }

            operation.TryRecordOutcome(
                OutcomeStatus.Failed,
                DateTimeOffset.UtcNow);
            MarkLivingProactiveNoteTerminal(
                operation.Item,
                LivingProactiveNoteDeliveryPolicy.CancelledStatus);
            ClearLivingProactiveNoteActive(operation);
            RecordLivingProactiveNoteCancellation(
                operation,
                LivingProactiveNoteCancellationStage.NativeWrite,
                LivingProactiveNoteCancellationReason.NativeWriteFailed,
                DateTimeOffset.UtcNow);
            Plugin.PluginLog.LogWarning(
                "D-025 F3 could not write an owned proactive note: "
                + exception.GetType().Name);
        }
    }

    private static string SaveD029IsolatedProactiveNote(
        GeneratedAiNote generated)
    {
        var profile = _d029IsolatedTestProfile
            ?? throw new InvalidOperationException(
                "No isolated D-029 Profile owns the Note sink.");
        return D029IsolatedNoteSink.Write(
            profile,
            generated.EventId,
            generated.Text,
            DateTimeOffset.UtcNow,
            Guid.NewGuid());
    }

    private static void ReconcileLivingProactiveNoteSource()
    {
        // Default-Off is the first branch. With no active owned operation,
        // it performs no new clock, sequence, ownership, provider, RNG,
        // persistence, or legacy scheduler mutation.
        if (!Plugin.AiNotesEnabled.Value
            || IsManualNoteInboxToolEnabled()
            || Plugin.HermesDailyNoteEnabled.Value
            || !Plugin.Effective(
                Plugin.LivingContinuityProactiveNoteEnabled.Value))
        {
            if (_livingProactiveNoteLastEnabled)
            {
                _livingProactiveNoteLastEnabled = false;
                _livingProactiveNoteArmed = false;
                checked
                {
                    _livingProactiveNoteConfigurationGeneration++;
                }
                CancelLivingProactiveNote(
                    ContinuityRetirementReason.SourceDisabled,
                    LivingProactiveNoteCancellationStage
                        .ActiveReconciliation,
                    LivingProactiveNoteCancellationReason.SourceDisabled);
            }
            return;
        }

        if (!_livingProactiveNoteLastEnabled)
        {
            _livingProactiveNoteLastEnabled = true;
            _livingProactiveNoteArmed = false;
            checked
            {
                _livingProactiveNoteConfigurationGeneration++;
            }
        }
        if (Plugin.FormalIntegrationActive)
        {
            // Formal availability is a policy mode, not a synthetic
            // keyboard Arm. Every occurrence still needs a fresh Local
            // Decision Core authorization and all existing Situation,
            // cooldown, capacity and cancellation gates.
            _livingProactiveNoteArmed = false;
            _livingProactiveNoteArmKeyWasDown = false;
        }

        var key = Plugin.LivingContinuityProactiveNoteArmKey.Value;
        var keyDown = (Input.GetKey(KeyCode.LeftControl)
                       || Input.GetKey(KeyCode.RightControl))
                      && (Input.GetKey(KeyCode.LeftShift)
                          || Input.GetKey(KeyCode.RightShift))
                      && Input.GetKey(key)
                      && !Plugin.FormalIntegrationActive;
        if (keyDown && !_livingProactiveNoteArmKeyWasDown)
        {
            _livingProactiveNoteArmed = true;
            Plugin.PluginLog.LogInfo(
                "D-025 F3 proactive AI Note source armed for one "
                + "eligible occurrence in this process.");
        }
        _livingProactiveNoteArmKeyWasDown = keyDown;

        LivingProactiveNotePluginOperation? active;
        lock (LivingProactiveNoteLock)
            active = _livingProactiveNoteActive;
        if (active == null)
            return;
        var runtime = CurrentCharacterRuntimeIdentity();
        var situation = CaptureLivingProactiveNoteSituation(
            runtime,
            active.SituationId,
            active.SituationRevision,
            active.ConfigurationGeneration);
        var now = DateTimeOffset.UtcNow;
        if (active.Cancellation.IsCancellationRequested
            || now >= active.Session.CompletionExpiresAt)
        {
            var cancellationReason =
                LivingProactiveNoteCancellationClassifier
                    .FromActiveCancellation(
                        active.Cancellation.IsCancellationRequested,
                        now < active.Session.CompletionExpiresAt);
            CancelLivingProactiveNote(
                ContinuityRetirementReason.Expired,
                LivingProactiveNoteCancellationStage
                    .ActiveReconciliation,
                cancellationReason);
            return;
        }
        if (active.ConfigurationGeneration
                != _livingProactiveNoteConfigurationGeneration
            || !runtime.Matches(active.RuntimeIdentity)
            || !string.Equals(
                situation.Situation.EpochId,
                active.EpochId,
                StringComparison.Ordinal)
            || !string.Equals(
                situation.Fingerprint,
                active.SituationFingerprint,
                StringComparison.Ordinal)
            || !situation.Situation.MasterEnabled
            || !situation.Situation.SourceEnabled
            || situation.Situation.IsAvatarUnderDirectPlayerControl
            || situation.Situation.IsConversationBusy
            || situation.Situation.HasPendingExecution
            || situation.Situation.IsQuietPeriod)
        {
            var cancellationReason =
                LivingProactiveNoteCancellationClassifier.FromGate(
                    new LivingProactiveNoteCancellationGateFacts(
                        exactActiveOperation: true,
                        configurationMatches:
                            active.ConfigurationGeneration
                            == _livingProactiveNoteConfigurationGeneration,
                        runtimeMatches:
                            runtime.Matches(active.RuntimeIdentity),
                        epochMatches: string.Equals(
                            situation.Situation.EpochId,
                            active.EpochId,
                            StringComparison.Ordinal),
                        masterEnabled:
                            situation.Situation.MasterEnabled,
                        sourceEnabled:
                            situation.Situation.SourceEnabled,
                        isAvatarUnderDirectPlayerControl:
                            situation.Situation
                                .IsAvatarUnderDirectPlayerControl,
                        isConversationBusy:
                            situation.Situation.IsConversationBusy,
                        hasPendingExecution:
                            situation.Situation.HasPendingExecution,
                        isQuietPeriod:
                            situation.Situation.IsQuietPeriod,
                        isCancellationRequested:
                            active.Cancellation.IsCancellationRequested,
                        isBeforeCompletionDeadline:
                            now < active.Session.CompletionExpiresAt,
                        situationMatches: string.Equals(
                            situation.Fingerprint,
                            active.SituationFingerprint,
                            StringComparison.Ordinal)));
            CancelLivingProactiveNote(
                ContinuityRetirementReason.SituationRevisionChanged,
                LivingProactiveNoteCancellationStage
                    .ActiveReconciliation,
                cancellationReason,
                LivingProactiveNotePrimaryPendingExecutionSubgateClassifier
                    .ForTerminalReason(
                        cancellationReason,
                        situation.PrimaryPendingExecutionSubgate));
        }
    }

    private sealed class LivingProactiveNoteSituationCapture
    {
        internal ProactiveRespondSituation Situation { get; }
        internal string Fingerprint { get; }
        internal LivingProactiveNotePrimaryPendingExecutionSubgate
            PrimaryPendingExecutionSubgate { get; }

        internal LivingProactiveNoteSituationCapture(
            ProactiveRespondSituation situation,
            string fingerprint,
            LivingProactiveNotePrimaryPendingExecutionSubgate
                primaryPendingExecutionSubgate)
        {
            Situation = situation;
            Fingerprint = fingerprint;
            PrimaryPendingExecutionSubgate =
                primaryPendingExecutionSubgate;
        }
    }

    private static LivingProactiveNoteSituationCapture
        CaptureLivingProactiveNoteSituation(
            CharacterRuntimeIdentity runtime,
            Guid situationId,
            long situationRevision,
            long configurationGeneration)
    {
        var state = UnityEngine.Object.FindObjectOfType<
            LilithStateManager>();
        var directControl = state?.IsDrag == true;
        var conversationBusy = _requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _aiPagesAwaitingAdvance;
        var actionShowcasePendingOperation =
            _actionShowcasePendingOperation
            != ActionShowcasePendingOperation.None;
        var actionShowcaseWindowWalkContinuation =
            !actionShowcasePendingOperation
            && _actionShowcaseWindowWalkContinuationActive;
        var nativeStateMachineLocked =
            !actionShowcasePendingOperation
            && !actionShowcaseWindowWalkContinuation
            && state?.IsStateMachineLocked == true;
        var nativeActionAnimationPlaying =
            !actionShowcasePendingOperation
            && !actionShowcaseWindowWalkContinuation
            && !nativeStateMachineLocked
            && state?.IsAnyActionAnimPlaying == true;
        var primaryPendingExecutionSubgate =
            LivingProactiveNotePrimaryPendingExecutionSubgateClassifier
                .FromFacts(
                actionShowcasePendingOperation,
                actionShowcaseWindowWalkContinuation,
                nativeStateMachineLocked,
                nativeActionAnimationPlaying);
        var pendingExecution =
            primaryPendingExecutionSubgate
            != LivingProactiveNotePrimaryPendingExecutionSubgate.None;
        var masterEnabled = Plugin.AiNotesEnabled.Value;
        var sourceEnabled = Plugin.Effective(
            Plugin.LivingContinuityProactiveNoteEnabled.Value);
        // F3 has no independent ambient-time sensor. Treat missing body
        // state, native sleep and the native sleepwear period as a
        // fail-closed quiet boundary.
        var quietPeriod = state == null
            || state.IsSleep
            || state.ClothingState == LilithClothingState.Pajamas;
        var situation = new ProactiveRespondSituation(
            runtime,
            situationId,
            situationRevision,
            masterEnabled,
            sourceEnabled,
            directControl,
            conversationBusy,
            pendingExecution,
            quietPeriod,
            LivingContinuityProcessEpochId);
        var fingerprint = LivingPromptHash.Of(
            string.Join(
                "|",
                runtime.RuntimeProfileId,
                runtime.RuntimeInstanceId,
                runtime.Generation.ToString(
                    CultureInfo.InvariantCulture),
                runtime.OrchestratorSessionId,
                runtime.OwnerIdentity,
                LivingContinuityProcessEpochId,
                configurationGeneration.ToString(
                    CultureInfo.InvariantCulture),
                masterEnabled ? "1" : "0",
                sourceEnabled ? "1" : "0",
                directControl ? "1" : "0",
                conversationBusy ? "1" : "0",
                pendingExecution ? "1" : "0",
                quietPeriod ? "1" : "0"));
        return new LivingProactiveNoteSituationCapture(
            situation,
            fingerprint,
            primaryPendingExecutionSubgate);
    }

    private static void RecordLivingProactiveNoteCancellation(
        Guid occurrenceId,
        Guid situationId,
        long situationRevision,
        long runtimeGeneration,
        long configurationGeneration,
        LivingProactiveNoteCancellationStage stage,
        LivingProactiveNoteCancellationReason reason,
        bool providerExecutionStarted,
        DateTimeOffset occurredAt,
        ProactiveRespondAdmission? decisionAdmission = null,
        DecisionReason? decisionReason = null,
        LivingProactiveNoteBridgeAdmission? bridgeAdmission = null,
        LivingPromptCompositionAdmission? promptAdmission = null,
        LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate =
                LivingProactiveNotePrimaryPendingExecutionSubgate.None)
    {
        // This side channel is deliberately fail-open. A diagnostics fault
        // must never change an already-selected cancellation path.
        try
        {
            var diagnostic =
                new LivingProactiveNoteCancellationDiagnostic(
                    occurredAt,
                    occurrenceId,
                    situationId,
                    situationRevision,
                    runtimeGeneration,
                    configurationGeneration,
                    stage,
                    reason,
                    providerExecutionStarted,
                    decisionAdmission,
                    decisionReason,
                    bridgeAdmission,
                    promptAdmission,
                    primaryPendingExecutionSubgate);
            var telemetry = Volatile.Read(
                ref _livingProactiveNoteCancellationTelemetry);
            if (telemetry == null)
            {
                var created =
                    new LivingProactiveNoteCancellationTelemetry();
                telemetry = Interlocked.CompareExchange(
                        ref _livingProactiveNoteCancellationTelemetry,
                        created,
                        null)
                    ?? created;
            }
            if (telemetry.TryRecordOnce(diagnostic)
                != LivingProactiveNoteTelemetryAdmission.Recorded)
            {
                return;
            }
            Plugin.PluginLog.LogInfo(
                LivingProactiveNoteCancellationLogFormatter.Format(
                    diagnostic));
        }
        catch (Exception exception)
        {
            try
            {
                Plugin.PluginLog.LogWarning(
                    "D-025 F3 cancellation telemetry fault was ignored: "
                    + exception.GetType().Name);
            }
            catch
            {
                // Observability must not become execution authority.
            }
        }
    }

    private static void RecordLivingProactiveNoteCancellation(
        ProactiveRespondOpportunity opportunity,
        long configurationGeneration,
        LivingProactiveNoteCancellationStage stage,
        LivingProactiveNoteCancellationReason reason,
        bool providerExecutionStarted,
        DateTimeOffset occurredAt,
        ProactiveRespondAdmission? decisionAdmission = null,
        DecisionReason? decisionReason = null,
        LivingProactiveNoteBridgeAdmission? bridgeAdmission = null,
        LivingPromptCompositionAdmission? promptAdmission = null,
        LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate =
                LivingProactiveNotePrimaryPendingExecutionSubgate.None)
        => RecordLivingProactiveNoteCancellation(
            opportunity.OccurrenceId,
            opportunity.SituationId,
            opportunity.SituationRevision,
            opportunity.RuntimeIdentity.Generation,
            configurationGeneration,
            stage,
            reason,
            providerExecutionStarted,
            occurredAt,
            decisionAdmission,
            decisionReason,
            bridgeAdmission,
            promptAdmission,
            primaryPendingExecutionSubgate);

    private static void RecordLivingProactiveNoteCancellation(
        LivingProactiveNotePluginOperation operation,
        LivingProactiveNoteCancellationStage stage,
        LivingProactiveNoteCancellationReason reason,
        DateTimeOffset occurredAt,
        LivingProactiveNoteBridgeAdmission? bridgeAdmission = null,
        LivingPromptCompositionAdmission? promptAdmission = null,
        LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate =
                LivingProactiveNotePrimaryPendingExecutionSubgate.None)
        => RecordLivingProactiveNoteCancellation(
            operation.Authorization.OccurrenceId,
            operation.SituationId,
            operation.SituationRevision,
            operation.RuntimeIdentity.Generation,
            operation.ConfigurationGeneration,
            stage,
            reason,
            operation.ProviderExecutionStarted,
            occurredAt,
            bridgeAdmission: bridgeAdmission,
            promptAdmission: promptAdmission,
            primaryPendingExecutionSubgate:
                primaryPendingExecutionSubgate);

    private static bool TryStartLivingProactiveNote(
        AiNoteEvent item,
        string language,
        DateTimeOffset now)
    {
        // Only new, successfully published Hermes conversation evidence may
        // enter. Existing legacy pending events are left untouched, not replayed.
        if (!item.HermesPublishedCandidate || !Plugin.AiNotesEnabled.Value)
            return false;
        var formal = Plugin.FormalIntegrationActive;
        if (!Plugin.Effective(
                Plugin.LivingContinuityProactiveNoteEnabled.Value))
            return false;
        if (!formal && !_livingProactiveNoteArmed)
            return false;

        lock (LivingProactiveNoteLock)
        {
            if (_livingProactiveNoteActive != null)
                return false;
        }
        var runtime = CurrentCharacterRuntimeIdentity();
        var sourceSequence = Interlocked.Increment(
            ref _livingProactiveNoteSourceSequence);
        var occurrenceId = LivingProactiveNoteGuid(
            "occurrence|" + item.Id);
        var situationId = CharacterLanguageStyleStageFBIdentity.Create(
            "d025-f3-situation",
            runtime,
            sourceSequence);
        var situationRevision = sourceSequence;
        var configurationGeneration =
            _livingProactiveNoteConfigurationGeneration;
        var capture = CaptureLivingProactiveNoteSituation(
            runtime,
            situationId,
            situationRevision,
            configurationGeneration);

        var opportunity = new ProactiveRespondOpportunity(
            occurrenceId,
            runtime.OrchestratorSessionId,
            runtime,
            situationId,
            situationRevision,
            ProactiveRespondPurpose.AcknowledgeBond,
            LivingPromptHash.Of(
                string.Join(
                    "|",
                    item.Id,
                    item.Category,
                    item.Topic,
                    item.LatestContext,
                    item.Emotion)),
            now.ToUniversalTime(),
            now.ToUniversalTime(),
            now.ToUniversalTime().AddSeconds(30),
            LivingContinuityProcessEpochId);
        var durableSuccessfulHistory =
            CaptureLivingProactiveNoteSuccessfulHistory(
                now.ToUniversalTime());
        ProactiveRespondRuntime decisionRuntime;
        var desiredMode = formal
            ? ProactiveRespondMode.Formal
            : ProactiveRespondMode.AssistPrepared;
        lock (LivingProactiveNoteLock)
        {
            if (_livingProactiveNoteDecisionRuntime == null
                || _livingProactiveNoteDecisionRuntimeIdentity == null
                || !_livingProactiveNoteDecisionRuntimeIdentity.Matches(
                    runtime)
                || _livingProactiveNoteDecisionRuntimeMode != desiredMode)
            {
                _livingProactiveNoteDecisionRuntime =
                    new ProactiveRespondRuntime(
                    new ProactiveRespondPolicy(
                        desiredMode,
                        explicitlyArmed: !formal),
                    LivingContinuityPromptOwnership,
                    runtime,
                    durableSuccessfulHistory);
                _livingProactiveNoteDecisionRuntimeIdentity = runtime;
                _livingProactiveNoteDecisionRuntimeMode = desiredMode;
            }
            decisionRuntime = _livingProactiveNoteDecisionRuntime;
        }
        decisionRuntime.RefreshSuccessfulOutcomeHistory(
            durableSuccessfulHistory,
            now.ToUniversalTime());
        var result = decisionRuntime.Process(
            opportunity,
            capture.Situation,
            now.ToUniversalTime());
        if (!result.SuppressLegacy)
            return false;
        if (!formal)
            _livingProactiveNoteArmed = false;
        if (!TryPersistLivingProactiveNoteOwnership(item))
        {
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage
                    .OwnershipPersistence,
                LivingProactiveNoteCancellationReason
                    .OwnershipPersistenceFailed,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason);
            return true;
        }
        if (result.Admission
                != ProactiveRespondAdmission.AuthorizationPrepared
            || result.Authorization == null)
        {
            var cancellationReason =
                LivingProactiveNoteCancellationClassifier.FromDecision(
                    result);
            MarkLivingProactiveNoteTerminal(item, "cancelled");
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage
                    .PostOwnershipDecision,
                cancellationReason,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason,
                primaryPendingExecutionSubgate:
                    LivingProactiveNotePrimaryPendingExecutionSubgateClassifier
                        .ForTerminalReason(
                            cancellationReason,
                            capture.PrimaryPendingExecutionSubgate));
            return true;
        }

        var bridge = new LivingProactiveNoteBridge(
            new LivingProactiveNoteBridgePolicy(
                LivingProactiveNoteBridgeMode.Prepared),
            runtime);
        var bridgePrepareAdmission = bridge.TryPrepare(
            result,
            opportunity,
            runtime,
            situationId,
            situationRevision,
            now.ToUniversalTime(),
            out var session);
        if (bridgePrepareAdmission
                != LivingProactiveNoteBridgeAdmission.Prepared
            || session == null)
        {
            RecordLivingProactiveNoteOutcome(
                decisionRuntime,
                result.Authorization,
                OutcomeStatus.Failed,
                runtime,
                situationId,
                situationRevision,
                now.ToUniversalTime());
            MarkLivingProactiveNoteTerminal(item, "cancelled");
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage.BridgePreparation,
                LivingProactiveNoteCancellationReason
                    .BridgePreparationRejected,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason,
                bridgePrepareAdmission);
            return true;
        }
        var promptHost = new LivingPromptCompositionHost(
            new LivingPromptCompositionPolicy(
                LivingPromptCompositionMode.Prepared),
            runtime,
            LivingContinuityPromptOwnership);
        var compositionId =
            "d025-f3-" + occurrenceId.ToString("N");
        var begin = promptHost.TryBegin(
            compositionId,
            session.PromptAuthorization,
            runtime,
            runtime.OrchestratorSessionId,
            situationId,
            situationRevision,
            now.ToUniversalTime());
        if (begin.Admission
                != LivingPromptCompositionAdmission.RootOwnershipAcquired
            || begin.RootOwnership == null)
        {
            RecordLivingProactiveNoteOutcome(
                decisionRuntime,
                result.Authorization,
                OutcomeStatus.Failed,
                runtime,
                situationId,
                situationRevision,
                now.ToUniversalTime());
            MarkLivingProactiveNoteTerminal(item, "cancelled");
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage
                    .PromptRootOwnership,
                LivingProactiveNoteCancellationReason
                    .PromptRootOwnershipRejected,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason,
                promptAdmission: begin.Admission);
            return true;
        }
        var prompt = BuildLivingProactiveNotePrompt(item, language);
        const string proactiveRequestText =
            "Write the one authorized private note now.";
        var compose = promptHost.TryCompose(
            new LivingPromptCompositionRequest(
                compositionId,
                session.PromptAuthorization,
                begin.RootOwnership,
                "Hermes",
                capture.Fingerprint,
                prompt,
                LivingPromptCharacterSlot.Empty,
                null,
                Array.Empty<LivingPromptTurn>(),
                new LivingPromptTurn(
                    session.PromptAuthorization.RequestIdentity,
                    LivingPromptTurnRole.User,
                    LivingPromptHash.Of(proactiveRequestText),
                    proactiveRequestText),
                now.ToUniversalTime()),
            runtime,
            runtime.OrchestratorSessionId,
            situationId,
            situationRevision,
            "Hermes",
            now.ToUniversalTime());
        if (compose.Admission
                != LivingPromptCompositionAdmission.Composed
            || compose.Envelope == null)
        {
            promptHost.Cancel(
                compositionId,
                ContinuityRetirementReason.Faulted,
                now.ToUniversalTime());
            RecordLivingProactiveNoteOutcome(
                decisionRuntime,
                result.Authorization,
                OutcomeStatus.Failed,
                runtime,
                situationId,
                situationRevision,
                now.ToUniversalTime());
            MarkLivingProactiveNoteTerminal(item, "cancelled");
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage.PromptComposition,
                LivingProactiveNoteCancellationReason
                    .PromptCompositionRejected,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason,
                promptAdmission: compose.Admission);
            return true;
        }
        var transport = new LivingProactiveNotePluginTransport();
        var dispatch = bridge.TryDispatch(
            session,
            promptHost,
            compose.Envelope,
            runtime,
            situationId,
            situationRevision,
            "Hermes",
            now.ToUniversalTime(),
            transport,
            out _);
        if (dispatch
                != LivingProactiveNoteBridgeAdmission.DispatchAccepted
            || transport.Request == null
            || transport.Calls != 1)
        {
            bridge.Cancel(
                session,
                promptHost,
                ContinuityRetirementReason.Faulted,
                now.ToUniversalTime());
            RecordLivingProactiveNoteOutcome(
                decisionRuntime,
                result.Authorization,
                OutcomeStatus.Failed,
                runtime,
                situationId,
                situationRevision,
                now.ToUniversalTime());
            MarkLivingProactiveNoteTerminal(item, "cancelled");
            RecordLivingProactiveNoteCancellation(
                opportunity,
                configurationGeneration,
                LivingProactiveNoteCancellationStage
                    .ProviderDispatchPreparation,
                LivingProactiveNoteCancellationReason
                    .ProviderDispatchRejected,
                providerExecutionStarted: false,
                now.ToUniversalTime(),
                result.Admission,
                result.Evaluation?.Outcome.Reason,
                dispatch);
            return true;
        }

        var operation = new LivingProactiveNotePluginOperation(
            item,
            decisionRuntime,
            result.Authorization,
            bridge,
            session,
            promptHost,
            transport,
            runtime,
            LivingContinuityProcessEpochId,
            situationId,
            situationRevision,
            capture.Fingerprint,
            configurationGeneration);
        item.Status = "generating";
        try
        {
            // Persist the already-owned state before publishing an active
            // operation. A persistence fault therefore cannot leave an
            // active session with no provider task capable of retiring it.
            SaveAiNoteState();
        }
        catch (Exception exception)
        {
            operation.Bridge.Cancel(
                operation.Session,
                operation.PromptHost,
                ContinuityRetirementReason.Faulted,
                DateTimeOffset.UtcNow);
            operation.TryRecordOutcome(
                OutcomeStatus.Failed,
                DateTimeOffset.UtcNow);
            operation.Item.Status =
                LivingProactiveNoteDeliveryPolicy.CancelledStatus;
            operation.DisposeCancellation();
            RecordLivingProactiveNoteCancellation(
                operation,
                LivingProactiveNoteCancellationStage
                    .GeneratingStatePersistence,
                LivingProactiveNoteCancellationReason
                    .GeneratingStatePersistenceFailed,
                DateTimeOffset.UtcNow);
            Plugin.PluginLog.LogWarning(
                "D-025 F3 could not persist its generating state; the "
                + "owned occurrence was retired before provider start: "
                + exception.GetType().Name);
            return true;
        }
        lock (LivingProactiveNoteLock)
            _livingProactiveNoteActive = operation;
        _aiNoteGenerationInFlight = true;
        _ = RunLivingProactiveNoteAsync(operation);
        return true;
    }

    private static bool RecordLivingProactiveNoteOutcome(
        ProactiveRespondRuntime decisionRuntime,
        ProactiveRespondAuthorization authorization,
        OutcomeStatus status,
        CharacterRuntimeIdentity runtime,
        Guid situationId,
        long situationRevision,
        DateTimeOffset now)
        => decisionRuntime.RecordOutcome(
                authorization,
                status,
                runtime,
                situationId,
                situationRevision,
                now)
            .Admission == ProactiveRespondAdmission.OutcomeRecorded;

    private static string BuildLivingProactiveNotePrompt(
        AiNoteEvent item,
        string language)
        => $"Write one private desktop-pet letter in {language} as Lilith. "
            + $"Event category: {item.Category}. User topic: {item.Topic}. "
            + $"Earlier Lilith reply: {item.LatestContext}. Emotional "
            + $"direction: {item.Emotion}. Write 45-110 natural words or "
            + "equivalent characters. Be warm, slightly playful and "
            + "intimate, with subtle themes of memory, choice, and shared "
            + "existence only when natural. Do not mention AI, scheduling, "
            + "stored memory, APIs, or monitoring. Do not give medical or "
            + "professional claims. Do not repeat sensitive details. End "
            + "with an em dash and Lilith's localized name. Output only "
            + "the letter text.";

    private static Guid LivingProactiveNoteGuid(string value)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(value));
        var bytes = new byte[16];
        Array.Copy(hash, bytes, bytes.Length);
        return new Guid(bytes);
    }

    private static async Task RunLivingProactiveNoteAsync(
        LivingProactiveNotePluginOperation operation)
    {
        try
        {
            var request =
                AssertLivingProactivePreparedRequest(operation);
            var text = await SendLivingProactiveNoteHermesAsync(
                    request,
                    operation,
                    operation.Cancellation.Token)
                .ConfigureAwait(false);
            PendingLivingProactiveNoteProviderResults.Enqueue(
                new LivingProactiveNoteProviderResult(
                    operation,
                    text,
                    null,
                    wasCancelled: false));
        }
        catch (OperationCanceledException)
            when (operation.Cancellation.IsCancellationRequested)
        {
            PendingLivingProactiveNoteProviderResults.Enqueue(
                new LivingProactiveNoteProviderResult(
                    operation,
                    null,
                    null,
                    wasCancelled: true));
        }
        catch (Exception exception)
        {
            PendingLivingProactiveNoteProviderResults.Enqueue(
                new LivingProactiveNoteProviderResult(
                    operation,
                    null,
                    exception,
                    wasCancelled: false));
        }
    }

    private static void ProcessLivingProactiveNoteProviderResults()
    {
        while (PendingLivingProactiveNoteProviderResults.TryDequeue(
                   out var result))
        {
            var operation = result.Operation;
            var nativeDeliveryPending = false;
            try
            {
                LivingProactiveNotePluginOperation? active;
                lock (LivingProactiveNoteLock)
                    active = _livingProactiveNoteActive;
                if (!ReferenceEquals(active, operation))
                {
                    RecordLivingProactiveNoteCancellation(
                        operation,
                        LivingProactiveNoteCancellationStage
                            .ProviderCompletion,
                        LivingProactiveNoteCancellationReason
                            .StaleProviderResult,
                        DateTimeOffset.UtcNow);
                    continue;
                }
                if (result.WasCancelled
                    || operation.Cancellation.IsCancellationRequested
                    || result.Fault != null
                    || string.IsNullOrWhiteSpace(result.Text))
                {
                    var cancellationObservedAt =
                        DateTimeOffset.UtcNow;
                    var cancellationReason =
                        LivingProactiveNoteCancellationClassifier
                            .FromProviderCompletion(
                                cancellationObservedAt,
                                operation.Session.CompletionExpiresAt,
                                operation.Cancellation
                                    .IsCancellationRequested,
                                result.WasCancelled,
                                result.Fault != null,
                                string.IsNullOrWhiteSpace(result.Text));
                    var timedOut = result.WasCancelled
                        || operation.Cancellation.IsCancellationRequested;
                    operation.Bridge.Cancel(
                        operation.Session,
                        operation.PromptHost,
                        timedOut
                            ? ContinuityRetirementReason.Expired
                            : ContinuityRetirementReason.Faulted,
                        DateTimeOffset.UtcNow);
                    operation.TryRecordOutcome(
                        timedOut
                            ? OutcomeStatus.TimedOut
                            : OutcomeStatus.Failed,
                        DateTimeOffset.UtcNow);
                    MarkLivingProactiveNoteTerminal(
                        operation.Item,
                        "cancelled");
                    ClearLivingProactiveNoteActive(operation);
                    RecordLivingProactiveNoteCancellation(
                        operation,
                        LivingProactiveNoteCancellationStage
                            .ProviderCompletion,
                        cancellationReason,
                        cancellationObservedAt);
                    if (result.Fault != null)
                    {
                        Plugin.PluginLog.LogWarning(
                            "D-025 F3 owned proactive note failed closed "
                            + "without retry, reschedule or legacy fallback: "
                            + result.Fault.GetType().Name);
                    }
                    continue;
                }

                var completedAt = DateTimeOffset.UtcNow;
                var runtime = CurrentCharacterRuntimeIdentity();
                var capture = CaptureLivingProactiveNoteSituation(
                    runtime,
                    operation.SituationId,
                    operation.SituationRevision,
                    operation.ConfigurationGeneration);
                if (!Plugin.LivingContinuityProactiveNoteEnabled.Value
                        && !Plugin.FormalIntegrationActive
                    || !_livingProactiveNoteLastEnabled
                    || operation.ConfigurationGeneration
                        != Interlocked.Read(
                            ref _livingProactiveNoteConfigurationGeneration)
                    || !runtime.Matches(operation.RuntimeIdentity)
                    || !string.Equals(
                        capture.Fingerprint,
                        operation.SituationFingerprint,
                        StringComparison.Ordinal)
                    || !capture.Situation.MasterEnabled
                    || !capture.Situation.SourceEnabled
                    || capture.Situation.IsAvatarUnderDirectPlayerControl
                    || capture.Situation.IsConversationBusy
                    || capture.Situation.HasPendingExecution
                    || capture.Situation.IsQuietPeriod
                    || completedAt
                        >= operation.Session.CompletionExpiresAt)
                {
                    var timedOut = completedAt
                        >= operation.Session.CompletionExpiresAt;
                    var cancellationReason =
                        LivingProactiveNoteCancellationClassifier
                            .FromGate(
                                new LivingProactiveNoteCancellationGateFacts(
                                    exactActiveOperation: true,
                                    configurationMatches:
                                        operation.ConfigurationGeneration
                                        == Interlocked.Read(
                                            ref
                                            _livingProactiveNoteConfigurationGeneration),
                                    runtimeMatches:
                                        runtime.Matches(
                                            operation.RuntimeIdentity),
                                    epochMatches: string.Equals(
                                        capture.Situation.EpochId,
                                        operation.EpochId,
                                        StringComparison.Ordinal),
                                    masterEnabled:
                                        capture.Situation.MasterEnabled,
                                    sourceEnabled:
                                        Plugin.Effective(
                                            Plugin
                                                .LivingContinuityProactiveNoteEnabled
                                                .Value)
                                        && _livingProactiveNoteLastEnabled
                                        && capture.Situation.SourceEnabled,
                                    isAvatarUnderDirectPlayerControl:
                                        capture.Situation
                                            .IsAvatarUnderDirectPlayerControl,
                                    isConversationBusy:
                                        capture.Situation
                                            .IsConversationBusy,
                                    hasPendingExecution:
                                        capture.Situation
                                            .HasPendingExecution,
                                    isQuietPeriod:
                                        capture.Situation.IsQuietPeriod,
                                    isCancellationRequested:
                                        operation.Cancellation
                                            .IsCancellationRequested,
                                    isBeforeCompletionDeadline:
                                        completedAt
                                        < operation.Session
                                            .CompletionExpiresAt,
                                    situationMatches: string.Equals(
                                        capture.Fingerprint,
                                        operation.SituationFingerprint,
                                        StringComparison.Ordinal)));
                    operation.Bridge.Cancel(
                        operation.Session,
                        operation.PromptHost,
                        timedOut
                            ? ContinuityRetirementReason.Expired
                            : ContinuityRetirementReason
                                .SituationRevisionChanged,
                        completedAt);
                    operation.TryRecordOutcome(
                        timedOut
                            ? OutcomeStatus.TimedOut
                            : OutcomeStatus.Interrupted,
                        completedAt);
                    MarkLivingProactiveNoteTerminal(
                        operation.Item,
                        "cancelled");
                    ClearLivingProactiveNoteActive(operation);
                    RecordLivingProactiveNoteCancellation(
                        operation,
                        LivingProactiveNoteCancellationStage
                            .ProviderCompletion,
                        cancellationReason,
                        completedAt,
                        primaryPendingExecutionSubgate:
                            LivingProactiveNotePrimaryPendingExecutionSubgateClassifier
                                .ForTerminalReason(
                                    cancellationReason,
                                    capture.PrimaryPendingExecutionSubgate));
                    continue;
                }

                var request =
                    AssertLivingProactivePreparedRequest(operation);
                var response = new LivingPreparedProviderResponse(
                    operation.Transport.ProviderRequestId,
                    request,
                    result.Text,
                    completedAt);
                var completionAdmission = operation.Bridge.TryComplete(
                    operation.Session,
                    operation.PromptHost,
                    response,
                    runtime,
                    operation.SituationId,
                    operation.SituationRevision,
                    completedAt,
                    out var projection);
                if (completionAdmission
                        == LivingProactiveNoteBridgeAdmission
                            .CompletionAccepted
                    && projection != null
                    && projection.MayWriteNativeInbox
                    && projection.ForbiddenEffectsAreZero)
                {
                    PendingAiNotes.Enqueue(
                        new GeneratedAiNote
                        {
                            EventId = operation.Item.Id,
                            Text = projection.ResponseText,
                            LivingContinuityOwned = true,
                            ConfigurationGeneration =
                                operation.ConfigurationGeneration,
                            RuntimeIdentity = operation.RuntimeIdentity,
                            Operation = operation
                        });
                    nativeDeliveryPending = true;
                    continue;
                }
                operation.TryRecordOutcome(
                    OutcomeStatus.Failed,
                    completedAt);
                MarkLivingProactiveNoteTerminal(
                    operation.Item,
                    "cancelled");
                ClearLivingProactiveNoteActive(operation);
                RecordLivingProactiveNoteCancellation(
                    operation,
                    LivingProactiveNoteCancellationStage
                        .CompletionProjection,
                    LivingProactiveNoteCancellationReason
                        .CompletionRejected,
                    completedAt,
                    completionAdmission);
            }
            finally
            {
                if (!nativeDeliveryPending)
                    operation.DisposeCancellation();
            }
        }
    }

    private static LivingPreparedProviderRequest
        AssertLivingProactivePreparedRequest(
            LivingProactiveNotePluginOperation operation)
        => operation.Transport.Request
            ?? throw new InvalidOperationException(
                "D-025 F3 prepared request is missing.");

    private static async Task<string>
        SendLivingProactiveNoteHermesAsync(
            LivingPreparedProviderRequest prepared,
            LivingProactiveNotePluginOperation operation,
            CancellationToken cancellationToken)
    {
        if (!string.Equals(
                prepared.ProviderRouteId,
                "Hermes",
                StringComparison.Ordinal)
            || prepared.SourceKind
                != LivingPromptSourceKind.BrainAuthorizedProactive
            || prepared.Destination
                != LivingPreparedCompletionDestination.ProactiveNote)
        {
            throw new InvalidOperationException(
                "Hermes note prepared request route mismatch.");
        }
        cancellationToken.ThrowIfCancellationRequested();
        // Transport-boundary telemetry: submission is not proof that a remote
        // model accepted or billed this request.
        operation.MarkProviderExecutionStarted();
        var response = await GameHermesClient.GenerateNoteDraftAsync(
                LivingProactiveNoteGuid(operation.Transport.ProviderRequestId),
                operation.Authorization.OccurrenceId,
                operation.Item.Category,
                CompactNoteContext(operation.Item.Topic, 360),
                CompactNoteContext(operation.Item.LatestContext, 360),
                operation.DisplayLocale,
                cancellationToken)
            .ConfigureAwait(false);
        cancellationToken.ThrowIfCancellationRequested();
        if (response.State != LilithGameBridgeNoteDraftState.Ready)
            throw new InvalidOperationException(
                "Hermes note draft did not authorize delivery: " + response.State);
        var text = response.Text.Trim();
        if (text.Length == 0 || text.Length > 1200
            || ContainsSensitiveNoteData(text))
            throw new InvalidOperationException(
                "Hermes note draft content was rejected.");
        return text;
    }

    private static void CancelLivingProactiveNote(
        ContinuityRetirementReason reason,
        LivingProactiveNoteCancellationStage stage,
        LivingProactiveNoteCancellationReason cancellationReason,
        LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate =
                LivingProactiveNotePrimaryPendingExecutionSubgate.None)
    {
        LivingProactiveNotePluginOperation? operation;
        lock (LivingProactiveNoteLock)
        {
            operation = _livingProactiveNoteActive;
            _livingProactiveNoteActive = null;
        }
        if (operation == null)
            return;
        operation.Cancellation.Cancel();
        operation.Bridge.Cancel(
            operation.Session,
            operation.PromptHost,
            reason,
            DateTimeOffset.UtcNow);
        operation.TryRecordOutcome(
            reason == ContinuityRetirementReason.Expired
                ? OutcomeStatus.TimedOut
                : reason == ContinuityRetirementReason.Faulted
                    ? OutcomeStatus.Failed
                    : OutcomeStatus.Interrupted,
            DateTimeOffset.UtcNow);
        MarkLivingProactiveNoteTerminal(operation.Item, "cancelled");
        _aiNoteGenerationInFlight = false;
        operation.DisposeCancellation();
        RecordLivingProactiveNoteCancellation(
            operation,
            stage,
            cancellationReason,
            DateTimeOffset.UtcNow,
            primaryPendingExecutionSubgate:
                primaryPendingExecutionSubgate);
    }

    private static void ClearLivingProactiveNoteActive(
        LivingProactiveNotePluginOperation operation)
    {
        lock (LivingProactiveNoteLock)
        {
            if (ReferenceEquals(
                    _livingProactiveNoteActive,
                    operation))
            {
                _livingProactiveNoteActive = null;
            }
        }
        operation.DisposeCancellation();
    }

    private static void MarkGeneratedLivingProactiveNoteRejected(
        GeneratedAiNote generated,
        LivingProactiveNoteCancellationReason cancellationReason,
        LivingProactiveNotePrimaryPendingExecutionSubgate
            primaryPendingExecutionSubgate =
                LivingProactiveNotePrimaryPendingExecutionSubgate.None)
    {
        var operation = generated.Operation;
        if (operation != null)
        {
            operation.TryRecordOutcome(
                OutcomeStatus.Interrupted,
                DateTimeOffset.UtcNow);
            ClearLivingProactiveNoteActive(operation);
        }
        lock (AiNoteLock)
        {
            var item = _aiNoteState.Pending.FirstOrDefault(
                value => value.Id == generated.EventId);
            if (item != null)
                item.Status = "cancelled";
            SaveAiNoteState();
        }
        if (operation != null)
        {
            RecordLivingProactiveNoteCancellation(
                operation,
                LivingProactiveNoteCancellationStage
                    .NativeDeliveryAdmission,
                cancellationReason,
                DateTimeOffset.UtcNow,
                primaryPendingExecutionSubgate:
                    primaryPendingExecutionSubgate);
        }
        Plugin.PluginLog.LogInfo(
            "D-025 F3 rejected an owned proactive note at final native "
            + "delivery admission; typed metadata reason="
            + cancellationReason
            + ".");
    }

    private static bool TryPersistLivingProactiveNoteOwnership(
        AiNoteEvent item)
    {
        try
        {
            lock (AiNoteLock)
            {
                item.LivingContinuityOwned = true;
                item.Status =
                    LivingProactiveNoteDeliveryPolicy.OwnedPendingStatus;
                SaveAiNoteState();
            }
            return true;
        }
        catch (Exception exception)
        {
            item.LivingContinuityOwned = true;
            item.Status =
                LivingProactiveNoteDeliveryPolicy.CancelledStatus;
            _aiNoteGenerationInFlight = false;
            Plugin.PluginLog.LogWarning(
                "D-025 F3 could not persist its no-fallback ownership "
                + "marker; the occurrence was retired in-process: "
                + exception.GetType().Name);
            return false;
        }
    }

    private static void MarkLivingProactiveNoteTerminal(
        AiNoteEvent item,
        string status)
    {
        lock (AiNoteLock)
        {
            item.Status = status;
            SaveAiNoteState();
        }
        _aiNoteGenerationInFlight = false;
    }

    private static bool OfficialNoteWasJustDelivered(DateTimeOffset now)
    {
        try
        {
            var directory = ResolveCurrentNativeNotesDirectory();
            if (!Directory.Exists(directory)) return false;
            var newest = Directory.GetFiles(directory, "note_*.png").OrderByDescending(File.GetLastWriteTimeUtc).FirstOrDefault();
            if (newest == null || now - File.GetLastWriteTime(newest) > TimeSpan.FromMinutes(30)) return false;
            return !_aiNoteState.DeliveredPaths.Any(path => string.Equals(Path.GetFullPath(path), Path.GetFullPath(newest), StringComparison.OrdinalIgnoreCase));
        }
        catch { return false; }
    }

    private static (
        bool CooldownActive,
        bool WeeklyCapacityAvailable) CaptureD029AiNoteCapacity(
            DateTimeOffset now)
    {
        lock (AiNoteLock)
        {
            var cooldown = TimeSpan.FromHours(
                Math.Clamp(
                    Plugin.AiNoteCooldownHours.Value,
                    1,
                    720));
            var cooldownActive =
                _aiNoteState.DeliveredAt.Count > 0
                && now - _aiNoteState.DeliveredAt.Max() < cooldown;
            var weeklyCapacityAvailable =
                _aiNoteState.DeliveredAt.Count(
                    value => value >= now.AddDays(-7))
                < Math.Clamp(Plugin.AiNoteWeeklyLimit.Value, 1, 20);
            return (cooldownActive, weeklyCapacityAvailable);
        }
    }

    private static DateTimeOffset[]
        CaptureLivingProactiveNoteSuccessfulHistory(
            DateTimeOffset now)
    {
        DateTimeOffset[] persisted;
        lock (AiNoteLock)
            persisted = _aiNoteState.DeliveredAt.ToArray();

        var nativeFiles = new List<DateTimeOffset>();
        try
        {
            var directory = ResolveCurrentNativeNotesDirectory();
            if (Directory.Exists(directory))
            {
                foreach (var path in Directory.GetFiles(
                             directory,
                             "note_*.png"))
                {
                    nativeFiles.Add(
                        new DateTimeOffset(
                            File.GetLastWriteTimeUtc(path)));
                }
            }
        }
        catch (Exception exception)
        {
            // The persisted scheduler history remains usable. Native files
            // are a conservative recovery source only when metadata failed
            // after the externally visible note write.
            Plugin.PluginLog.LogWarning(
                "D-025 F3 could not inspect native note timestamps for "
                + "durable budget recovery: "
                + exception.GetType().Name);
        }

        return LivingProactiveNoteDeliveryPolicy
            .CoalesceSuccessfulHistory(
                persisted.Concat(nativeFiles)
                    .Where(
                        value => value <= now
                            && value > now.Subtract(
                                ProactiveRespondPolicy.RollingWindow)),
                ProactiveRespondRuntime
                    .MaximumSeededSuccessfulOutcomes)
            .ToArray();
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct LastInputInfo
    {
        public uint Size;
        public uint Time;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct SystemPowerStatus
    {
        public byte ACLineStatus;
        public byte BatteryFlag;
        public byte BatteryLifePercent;
