    private static bool IsVirtualKeyDown(int virtualKey) =>
        OperatingSystem.IsWindows() && (GetAsyncKeyState(virtualKey) & 0x8000) != 0;

    private static bool IsKeyCurrentlyDown(KeyCode key)
    {
        if (TryGetWindowsVirtualKey(key, out var virtualKey))
            return IsVirtualKeyDown(virtualKey);
        try
        {
            return Input.GetKey(key);
        }
        catch
        {
            return false;
        }
    }

    private static bool TryGetWindowsVirtualKey(KeyCode key, out int virtualKey)
    {
        virtualKey = 0;
        if (!OperatingSystem.IsWindows())
            return false;

        var code = (int)key;
        if (code >= (int)KeyCode.Alpha0 && code <= (int)KeyCode.Alpha9)
        {
            virtualKey = 0x30 + code - (int)KeyCode.Alpha0;
            return true;
        }
        if (code >= (int)KeyCode.A && code <= (int)KeyCode.Z)
        {
            virtualKey = 0x41 + code - (int)KeyCode.A;
            return true;
        }
        if (code >= (int)KeyCode.Keypad0 && code <= (int)KeyCode.Keypad9)
        {
            virtualKey = 0x60 + code - (int)KeyCode.Keypad0;
            return true;
        }
        if (code >= (int)KeyCode.F1 && code <= (int)KeyCode.F15)
        {
            virtualKey = 0x70 + code - (int)KeyCode.F1;
            return true;
        }

        virtualKey = key switch
        {
            KeyCode.Backspace => 0x08,
            KeyCode.Tab => 0x09,
            KeyCode.Clear => 0x0C,
            KeyCode.Return => 0x0D,
            KeyCode.Pause => 0x13,
            KeyCode.Escape => 0x1B,
            KeyCode.Space => 0x20,
            KeyCode.PageUp => 0x21,
            KeyCode.PageDown => 0x22,
            KeyCode.End => 0x23,
            KeyCode.Home => 0x24,
            KeyCode.LeftArrow => 0x25,
            KeyCode.UpArrow => 0x26,
            KeyCode.RightArrow => 0x27,
            KeyCode.DownArrow => 0x28,
            KeyCode.Insert => 0x2D,
            KeyCode.Delete => 0x2E,
            KeyCode.KeypadMultiply => 0x6A,
            KeyCode.KeypadPlus => 0x6B,
            KeyCode.KeypadMinus => 0x6D,
            KeyCode.KeypadPeriod => 0x6E,
            KeyCode.KeypadDivide => 0x6F,
            KeyCode.Numlock => 0x90,
            KeyCode.ScrollLock => 0x91,
            KeyCode.LeftShift => 0xA0,
            KeyCode.RightShift => 0xA1,
            KeyCode.LeftControl => 0xA2,
            KeyCode.RightControl => 0xA3,
            KeyCode.LeftAlt => 0xA4,
            KeyCode.RightAlt => 0xA5,
            KeyCode.Semicolon => 0xBA,
            KeyCode.Equals => 0xBB,
            KeyCode.Comma => 0xBC,
            KeyCode.Minus => 0xBD,
            KeyCode.Period => 0xBE,
            KeyCode.Slash => 0xBF,
            KeyCode.BackQuote => 0xC0,
            KeyCode.LeftBracket => 0xDB,
            KeyCode.Backslash => 0xDC,
            KeyCode.RightBracket => 0xDD,
            KeyCode.Quote => 0xDE,
            _ => 0
        };
        return virtualKey != 0;
    }

    private static void SendVirtualKey(byte virtualKey)
    {
        if (!OperatingSystem.IsWindows())
            throw new PlatformNotSupportedException("Windows media keys are only available on Windows.");
        keybd_event(virtualKey, 0, 0, UIntPtr.Zero);
        keybd_event(virtualKey, 0, 0x0002, UIntPtr.Zero);
    }

    private static void SendShortcut(params byte[] virtualKeys)
    {
        if (!OperatingSystem.IsWindows())
            throw new PlatformNotSupportedException("Windows shortcuts are only available on Windows.");
        foreach (var key in virtualKeys)
            keybd_event(key, 0, 0, UIntPtr.Zero);
        for (var index = virtualKeys.Length - 1; index >= 0; index--)
            keybd_event(virtualKeys[index], 0, 0x0002, UIntPtr.Zero);
    }

    private static void ObserveForegroundWindow()
    {
        if (!OperatingSystem.IsWindows() || Time.unscaledTime < _nextForegroundWindowScanAt)
            return;
        _nextForegroundWindowScanAt = Time.unscaledTime + 0.25f;
        var window = GetForegroundWindow();
        if (window == IntPtr.Zero || !IsWindowVisible(window))
        {
            ClearForegroundProactiveObservation();
            return;
        }
        GetWindowThreadProcessId(window, out var processId);
        if (processId == (uint)Environment.ProcessId)
        {
            ClearForegroundProactiveObservation();
            return;
        }
        _lastExternalForegroundWindow = window;
        ObserveForegroundProactiveApplication(processId);
    }

    private static void ObserveForegroundProactiveApplication(uint processId)
    {
        if (processId == 0)
        {
            ClearForegroundProactiveObservation();
            return;
        }
        try
        {
            using var process = Process.GetProcessById((int)processId);
            if (!ForegroundProactiveApplicationPolicy.TryDescribe(
                    process.ProcessName,
                    out var application)
                || application == null)
            {
                ClearForegroundProactiveObservation();
                return;
            }

            var sameApplication =
                _foregroundProactiveObservedProcessId == processId
                && _foregroundProactiveObservedApplication != null
                && string.Equals(
                    _foregroundProactiveObservedApplication.ApplicationId,
                    application.ApplicationId,
                    StringComparison.Ordinal);
            if (!sameApplication)
            {
                _foregroundProactiveObservedProcessId = processId;
                _foregroundProactiveObservedApplication = application;
                _foregroundProactiveObservedStableSince = Time.unscaledTime;
            }
            _foregroundProactiveObservedAtUtc = DateTimeOffset.UtcNow;
        }
        catch (Exception exception) when (exception is ArgumentException
            or InvalidOperationException
            or System.ComponentModel.Win32Exception
            or NotSupportedException)
        {
            ClearForegroundProactiveObservation();
        }
    }

    private static void ClearForegroundProactiveObservation()
    {
        _foregroundProactiveObservedProcessId = 0;
        _foregroundProactiveObservedApplication = null;
        _foregroundProactiveObservedStableSince = -1f;
        _foregroundProactiveObservedAtUtc = default;
    }

    private static bool TryGetForegroundProactiveApplication(
        out ForegroundProactiveApplicationDescriptor? application,
        out long observedAtUnixMilliseconds)
    {
        application = _foregroundProactiveObservedApplication;
        observedAtUnixMilliseconds = 0;
        if (application == null
            || _foregroundProactiveObservedStableSince < 0f
            || Time.unscaledTime - _foregroundProactiveObservedStableSince
                < ForegroundProactiveMinimumStableSeconds)
        {
            return false;
        }
        var now = DateTimeOffset.UtcNow;
        var age = now - _foregroundProactiveObservedAtUtc;
        if (age < TimeSpan.Zero
            || age > ForegroundProactiveMaximumObservationAge)
        {
            return false;
        }
        observedAtUnixMilliseconds =
            _foregroundProactiveObservedAtUtc.ToUnixTimeMilliseconds();
        return observedAtUnixMilliseconds > 0;
    }

    private static bool ForegroundProactiveSafetyAllows(
        DialogueManager manager)
    {
        if (!OperatingSystem.IsWindows()
            || manager == null
            || manager.IsBusy
            || _requestInFlight
            || _transcriptionInFlight
            || _microphoneRecording
            || _activeGameHermesVoiceCapture != null
            || _pendingVoiceSubmitText != null
            || _aiPagesAwaitingAdvance
            || !PendingTranscripts.IsEmpty
            || (_inputBubble != null && _inputBubble.activeSelf)
            || (_conversationHistoryWindow != null
                && _conversationHistoryWindow.activeSelf)
            || D046GameControlCaptureLease.IsActive()
            || HasActivePublishedPlayerReplySpeech()
            || Volatile.Read(ref _activeReminderSpeechCount) > 0
            || Volatile.Read(ref _reminderSpeechPipelineBusy) != 0
            || !PendingReminderSpeech.IsEmpty
            || !PendingVoiceAudio.IsEmpty
            || Volatile.Read(ref _pendingGameHermesNotificationCount) > 0)
        {
            return false;
        }

        var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
        if (state == null || state.IsDrag || state.IsSleep)
            return false;
        var idleSeconds = GetWindowsIdleSeconds();
        return idleSeconds >= ForegroundProactiveMinimumStableSeconds;
    }

    private static void UpdateForegroundProactiveConversation(
        DialogueManager manager)
    {
        var machine = _foregroundProactiveStateMachine;
        if (machine == null)
            return;
        try
        {
            var enabled = EffectiveD046ProactiveDialogueEnabled();
            var snapshot = machine.GetSnapshot();
            if (!enabled)
            {
                if (snapshot.State != ForegroundProactiveState.Disabled)
                {
                    if (snapshot.State == ForegroundProactiveState.Dispatching)
                    {
                        _ = TryInterruptGameHermesTurnAsync(
                            GameHermesNativeContinuationStopTurnId);
                    }
                    CancelForegroundProactiveRequest();
                    machine.SetEnabled(false);
                    ClearForegroundProactiveDispatchContext();
                }
                return;
            }
            if (snapshot.State == ForegroundProactiveState.Disabled)
                snapshot = machine.SetEnabled(true);
            if (snapshot.State == ForegroundProactiveState.AwaitingPlayerReply
                || Volatile.Read(ref _foregroundProactiveRequestInFlight) != 0)
            {
                return;
            }
            if (_foregroundProactiveNextReconcileAt >= 0f
                && Time.unscaledTime < _foregroundProactiveNextReconcileAt)
            {
                return;
            }
            if (snapshot.State == ForegroundProactiveState.Armed
                && DateTimeOffset.UtcNow < snapshot.DueAtUtc!.Value)
            {
                return;
            }
            if (!ForegroundProactiveSafetyAllows(manager))
                return;

            ForegroundProactiveDispatchContext? dispatchContext = null;
            if (snapshot.State == ForegroundProactiveState.Armed)
            {
                if (!TryGetForegroundProactiveApplication(
                        out var currentApplication,
                        out var currentObservedAt)
                    || currentApplication == null)
                {
                    return;
                }
                var displayLocale = ToGameHermesDisplayLocale(
                    LilithGamePersonaLocaleProjector.Resolve(
                        GetAgentTurnLocale()).DisplayLocale);
                dispatchContext = new ForegroundProactiveDispatchContext(
                    currentApplication.ApplicationId,
                    currentApplication.DisplayName,
                    currentApplication.Category,
                    currentObservedAt,
                    LilithGameBridgeProtocol.DisplayLocaleToken(
                        displayLocale));
            }

            var dispatch = machine.TryBeginDueDispatch(dispatchContext);
            if (!dispatch.Started && !dispatch.RequiresReconciliation)
                return;
            var persistedContext = dispatch.Context
                ?? throw new InvalidDataException(
                    "Foreground proactive dispatch context was missing.");
            if (!Guid.TryParseExact(
                    dispatch.OperationId ?? string.Empty,
                    "N",
                    out var operationId))
            {
                machine.TryCompleteDispatch(
                    dispatch.OperationId ?? string.Empty,
                    ForegroundProactiveDispatchOutcome.Failed);
                ClearForegroundProactiveDispatchContext();
                return;
            }

            StartForegroundProactiveRequest(
                dispatch.OperationId!,
                operationId,
                persistedContext,
                dispatch.RequiresReconciliation);
            _foregroundProactiveFaultLogged = false;
        }
        catch (Exception exception)
        {
            _foregroundProactiveNextReconcileAt = Time.unscaledTime
                + (float)ForegroundProactiveReconcileDelay.TotalSeconds;
            if (!_foregroundProactiveFaultLogged)
            {
                _foregroundProactiveFaultLogged = true;
                Plugin.PluginLog.LogWarning(
                    "Foreground proactive coordination is deferred after "
                    + exception.GetType().Name
                    + ".");
            }
        }
    }

    // One immutable capture per existing proactive operation, including the
    // absence of a game. Reconciliation must never capture a different match.
    private static Guid _foregroundMiniGameOperation;
    private static LilithMiniGamePublicContext? _foregroundMiniGameContext;

    private static void StartForegroundProactiveRequest(
        string operationIdText,
        Guid operationId,
        ForegroundProactiveDispatchContext context,
        bool requiresReconciliation)
    {
        try
        {
            if (_foregroundMiniGameOperation != operationId)
            {
                if (_foregroundMiniGameOperation != Guid.Empty)
                    MiniGameConversationEvents.Shared.Release(_foregroundMiniGameOperation);
                _foregroundMiniGameOperation = operationId;
                _foregroundMiniGameContext = MiniGameConversationEvents.Shared.Reserve(
                    requiresReconciliation ? null : CaptureMiniGamePublicContext(), operationId);
            }
            var requestGeneration = Interlocked.Increment(
                ref _foregroundProactiveRequestGeneration);
            var cancellation = new CancellationTokenSource(
                ForegroundProactiveRequestTimeout);
            _foregroundProactiveRequestCancellation = cancellation;
            Interlocked.Exchange(ref _foregroundProactiveRequestInFlight, 1);
            _foregroundProactiveNextReconcileAt = -1f;
            var displayLocale = context.DisplayLocale switch
            {
                "zh-Hant" => LilithGameBridgeDisplayLocale.TraditionalChinese,
                "zh-Hans" => LilithGameBridgeDisplayLocale.SimplifiedChinese,
                "ja" => LilithGameBridgeDisplayLocale.Japanese,
                "en" => LilithGameBridgeDisplayLocale.English,
                _ => throw new InvalidDataException(
                    "Foreground proactive display locale was rejected.")
            };
            _ = RunForegroundProactiveRequestAsync(
                requestGeneration,
                operationIdText,
                operationId,
                context,
                displayLocale,
                cancellation.Token,
                _foregroundMiniGameContext);
        }
        catch
        {
            CancelForegroundProactiveRequest();
            ClearForegroundProactiveDispatchContext();
            throw;
        }
    }

    private static async Task RunForegroundProactiveRequestAsync(
        long requestGeneration,
        string operationIdText,
        Guid operationId,
        ForegroundProactiveDispatchContext context,
        LilithGameBridgeDisplayLocale displayLocale,
        CancellationToken cancellationToken,
        LilithMiniGamePublicContext? miniGameContext)
    {
        try
        {
            var response = await GameHermesClient
                .RequestForegroundProactiveAsync(
                    Guid.NewGuid(),
                    operationId,
                    context.ObservedAtUnixMilliseconds,
                    context.ApplicationId,
                    context.ApplicationDisplayName,
                    context.ApplicationCategory,
                    displayLocale,
                    cancellationToken,
                    miniGameContext)
                .ConfigureAwait(false);
            PendingForegroundProactiveBridgeResults.Enqueue(
                new PendingForegroundProactiveBridgeResult(
                    requestGeneration,
                    operationIdText,
                    response,
                    requestWasNotWritten: false,
                    faultType: string.Empty));
        }
        catch (Exception exception)
        {
            PendingForegroundProactiveBridgeResults.Enqueue(
                new PendingForegroundProactiveBridgeResult(
                    requestGeneration,
                    operationIdText,
                    response: null,
                    requestWasNotWritten:
                        LilithGameHermesClient.ProvesRequestWasNotWritten(
                            exception),
                    faultType: exception.GetType().Name));
        }
    }

    private static void ProcessPendingForegroundProactiveBridgeResults()
    {
        while (PendingForegroundProactiveBridgeResults.TryDequeue(
                   out var pending))
        {
            if (pending.RequestGeneration != Volatile.Read(
                    ref _foregroundProactiveRequestGeneration))
            {
                continue;
            }
            Interlocked.Exchange(ref _foregroundProactiveRequestInFlight, 0);
            _foregroundProactiveRequestCancellation?.Dispose();
            _foregroundProactiveRequestCancellation = null;
            var machine = _foregroundProactiveStateMachine;
            if (machine == null)
                continue;

            try
            {
                var response = pending.Response;
                if (response == null)
                {
                    if (pending.RequestWasNotWritten)
                    {
                        if (machine.TryCompleteDispatch(
                                pending.OperationId,
                                ForegroundProactiveDispatchOutcome.Failed))
                        {
                            ClearForegroundProactiveDispatchContext();
                        }
                    }
                    else
                    {
                        ScheduleForegroundProactiveReconciliation();
                    }
                    Plugin.PluginLog.LogInfo(
                        "Foreground proactive request is "
                        + (pending.RequestWasNotWritten
                            ? "re-armed after a pre-write failure"
                            : "waiting for exact reconciliation")
                        + ": fault="
                        + pending.FaultType
                        + ".");
                    continue;
                }

                if (response.State
                        == LilithGameBridgeForegroundProactiveState.Streaming
                    || (response.State
                            == LilithGameBridgeForegroundProactiveState.Abandoned
                        && response.Retryable))
                {
                    ScheduleForegroundProactiveReconciliation();
                    continue;
                }

                var outcome = response.State switch
                {
                    LilithGameBridgeForegroundProactiveState.Completed =>
                        ForegroundProactiveDispatchOutcome.ReplyCompleted,
                    LilithGameBridgeForegroundProactiveState.Silent =>
                        ForegroundProactiveDispatchOutcome.Silent,
                    LilithGameBridgeForegroundProactiveState.Abandoned =>
                        ForegroundProactiveDispatchOutcome.Abandoned,
                    _ => ForegroundProactiveDispatchOutcome.Failed
                };
                if (!machine.TryCompleteDispatch(
                        pending.OperationId,
                        outcome))
                {
                    continue;
                }
                if (outcome
                    == ForegroundProactiveDispatchOutcome.ReplyCompleted)
                {
                    if (response.MiniGameEventReceipt is { } receipt
                        && Guid.TryParseExact(pending.OperationId, "N", out var completedOperation))
                        MiniGameConversationEvents.Shared.Acknowledge(completedOperation, receipt);
                    Interlocked.Exchange(
                        ref _conversationHistoryRefreshRequested,
                        1);
                }
                ClearForegroundProactiveDispatchContext();
                Plugin.PluginLog.LogInfo(
                    "Foreground proactive operation reached "
                    + response.State
                    + ".");
            }
            catch (Exception exception)
            {
                ScheduleForegroundProactiveReconciliation();
                Plugin.PluginLog.LogWarning(
                    "Foreground proactive reconciliation was retained after "
                    + exception.GetType().Name
                    + ".");
            }
        }
    }

    private static void ScheduleForegroundProactiveReconciliation()
        => _foregroundProactiveNextReconcileAt = Time.unscaledTime
            + (float)ForegroundProactiveReconcileDelay.TotalSeconds;

    private static void RecordForegroundProactivePlayerTurn()
    {
        ContinuationPresentation.Invalidate(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        var machine = _foregroundProactiveStateMachine;
        if (machine == null)
            return;
        try
        {
            var snapshot = machine.GetSnapshot();
            if (snapshot.State == ForegroundProactiveState.Dispatching)
            {
                _ = TryInterruptGameHermesTurnAsync(
                    GameHermesNativeContinuationStopTurnId);
            }
            CancelForegroundProactiveRequest();
            machine.RecordGenuinePlayerTurn();
            ClearForegroundProactiveDispatchContext();
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Player turn continued while proactive timing failed closed: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void StopForegroundProactiveDispatch()
    {
        var machine = _foregroundProactiveStateMachine;
        if (machine == null)
            return;
        var snapshot = machine.GetSnapshot();
        if (snapshot.State != ForegroundProactiveState.Dispatching
            || string.IsNullOrWhiteSpace(snapshot.DispatchOperationId))
        {
            return;
        }
        CancelForegroundProactiveRequest();
        try
        {
            machine.TryCompleteDispatch(
                snapshot.DispatchOperationId,
                ForegroundProactiveDispatchOutcome.Abandoned);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Stopped foreground proactive dispatch remains available for "
                + "restart reconciliation after "
                + exception.GetType().Name
                + ".");
        }
        ClearForegroundProactiveDispatchContext();
    }

    private static void CancelForegroundProactiveRequest()
    {
        if (Interlocked.Exchange(
                ref _foregroundProactiveRequestInFlight,
                0) == 0
            && _foregroundProactiveRequestCancellation == null)
        {
            return;
        }
        Interlocked.Increment(ref _foregroundProactiveRequestGeneration);
        var cancellation = _foregroundProactiveRequestCancellation;
        _foregroundProactiveRequestCancellation = null;
        try
        {
            cancellation?.Cancel();
        }
        catch (ObjectDisposedException)
        {
        }
        finally
        {
            cancellation?.Dispose();
        }
    }

    private static void ClearForegroundProactiveDispatchContext()
    {
        _foregroundProactiveNextReconcileAt = -1f;
        if (_foregroundMiniGameOperation != Guid.Empty)
            MiniGameConversationEvents.Shared.Release(_foregroundMiniGameOperation);
        _foregroundMiniGameOperation = Guid.Empty;
        _foregroundMiniGameContext = null;
    }

    private static IntPtr GetControllableWindow()
    {
        var foreground = GetForegroundWindow();
        if (foreground != IntPtr.Zero && IsWindowVisible(foreground))
        {
            GetWindowThreadProcessId(foreground, out var processId);
            if (processId != (uint)Environment.ProcessId)
                return foreground;
        }
        if (_lastExternalForegroundWindow != IntPtr.Zero && IsWindowVisible(_lastExternalForegroundWindow))
            return _lastExternalForegroundWindow;
        return IntPtr.Zero;
    }

    private static void ProcessLocalTimers(DialogueManager manager)
    {
        if (LocalTimers.Count == 0)
        {
            _nextLocalTimerDeliveryAttempt = null;
            _nextLocalTimerDeliveryFallbackAt = -1f;
            ResetLocalTimerDeliveryRetryTelemetry();
            return;
        }
        if (_nextLocalTimerDeliveryAttempt == null
            && _nextLocalTimerDeliveryFallbackAt >= 0f)
        {
            if (Time.unscaledTime < _nextLocalTimerDeliveryFallbackAt)
                return;
            _nextLocalTimerDeliveryFallbackAt = -1f;
        }
        if (_nextLocalTimerDeliveryAttempt != null)
        {
            if (!AgentLanguageRuntime.IsDue(
                    _nextLocalTimerDeliveryAttempt))
            {
                return;
            }
            _nextLocalTimerDeliveryAttempt = null;
        }
        List<LocalTimer> due;
        try
        {
            due = LocalTimers
                .Where(timer => AgentLanguageRuntime.IsDue(timer.Deadline))
                .OrderBy(timer => timer.Deadline.DueTimestamp)
                .ThenBy(timer => timer.Deadline.Sequence)
                .Take(1)
                .ToList();
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Local timer readiness failed closed without removing timers: "
                + exception.GetType().Name
                + ".");
            return;
        }
        if (due.Count == 0)
            return;
        if (due[0].Continuation is { } continuation)
        {
            if (!ContinuationIsCurrent(continuation))
            {
                LocalTimers.Remove(due[0]);
                return;
            }
            // The original official voice shares this source. Never overwrite
            // it just because its typewriter/bubble has already completed.
            if (IsOfficialOrQueuedVoicePlaying()) return;
        }
        if (!TryAcquireAgentLanguageOutput(
                manager,
                AgentLanguageSourceKind.LocalTimer,
                due[0].Deadline.DeadlineId,
                out var lease,
                out var arbitration,
                logRejection: false)
            || lease == null)
        {
            if (arbitration?.Disposition
                == AgentLanguageArbitrationDisposition.Deferred)
            {
                ScheduleLocalTimerDeliveryRetrySafely();
                if (_lastLocalTimerDeferralReason != arbitration.Reason)
                {
                    Plugin.PluginLog.LogInfo(
                        "Deferred due local timer language output without "
                        + "removal: count="
                        + due.Count
                        + ", reason="
                        + arbitration.Reason
                        + ".");
                    _lastLocalTimerDeferralReason = arbitration.Reason;
                }
                _localTimerFaultRetryLogged = false;
                return;
            }
            if (arbitration == null
                || arbitration.Disposition
                    == AgentLanguageArbitrationDisposition.Selected)
            {
                ScheduleLocalTimerDeliveryRetrySafely();
                if (!_localTimerFaultRetryLogged)
                {
                    Plugin.PluginLog.LogWarning(
                        "Retained due local timer after Agent Runtime Host "
                        + "or exact-claim fault; boundedRetry=true, "
                        + "noFallback=true.");
                    _localTimerFaultRetryLogged = true;
                }
                _lastLocalTimerDeferralReason = null;
                return;
            }
            foreach (var timer in due)
                LocalTimers.Remove(timer);
            ResetLocalTimerDeliveryRetryTelemetry();
            Plugin.PluginLog.LogWarning(
                "Terminated due local timer after non-retryable language "
                + "arbitration rejection: disposition="
                + arbitration.Disposition
                + ", reason="
                + arbitration.Reason
                + ", noFallback=true.");
            return;
        }
        ResetLocalTimerDeliveryRetryTelemetry();
        var agentPublicationFinished = false;
        foreach (var timer in due)
            LocalTimers.Remove(timer);
        string? deliveredTimerSpeechMessage = null;
        LilithGameBridgeSpeechLocale? deliveredTimerSpeechLocale = null;
        try
        {
            var message = due[0].Message;
            var speechMessage = due[0].SpeechMessage ?? due[0].Message;
            ForceSaySynthetic(manager, message, string.Empty, 12f);
            agentPublicationFinished = TryRecordAgentLanguagePublication(
                lease,
                published: true);
            if (agentPublicationFinished)
            {
                deliveredTimerSpeechMessage = speechMessage;
                deliveredTimerSpeechLocale = due[0].SpeechLocale;
            }
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Local timer publication failed terminally without retry: "
                + exception.GetType().Name
                + ".");
        }
        finally
        {
            if (!agentPublicationFinished)
            {
                TryRecordAgentLanguagePublication(
                    lease,
                    published: false);
            }
        }
        if (agentPublicationFinished)
        {
            if (Plugin.VoiceEnabled.Value
                && !string.IsNullOrWhiteSpace(
                    deliveredTimerSpeechMessage))
            {
                var useJapanese = deliveredTimerSpeechLocale.HasValue
                    ? deliveredTimerSpeechLocale.Value
                        == LilithGameBridgeSpeechLocale.Japanese
                    : IsJapaneseVoiceMode();
                if (useJapanese == IsJapaneseVoiceMode())
                {
                    QueueReminderSpeech(
                    deliveredTimerSpeechMessage!,
                        CapturePoseContext().VoiceStyle,
                        useJapanese,
                        due[0].Continuation,
                        due[0].SpeechEmotion);
                }
            }
            Plugin.PluginLog.LogInfo(
                $"Delivered {due.Count} local Lilith timer(s).");
        }
    }

    private static void ScheduleLocalTimerDeliveryRetrySafely()
    {
        try
        {
            _nextLocalTimerDeliveryAttempt =
                AgentLanguageRuntime.CreateDeadline(
                    LocalTimerDeliveryRetryDelay);
            _nextLocalTimerDeliveryFallbackAt = -1f;
            _localTimerRetryScheduleFaultLogged = false;
        }
        catch (Exception exception)
        {
            _nextLocalTimerDeliveryAttempt = null;
            _nextLocalTimerDeliveryFallbackAt =
                Time.unscaledTime
                + (float)LocalTimerDeliveryRetryDelay.TotalSeconds;
            if (!_localTimerRetryScheduleFaultLogged)
            {
                Plugin.PluginLog.LogWarning(
                    "Local timer bounded retry scheduling used the Unity "
                    + "monotonic fallback after: "
                    + exception.GetType().Name
                    + ".");
                _localTimerRetryScheduleFaultLogged = true;
            }
        }
    }

    private static void ResetLocalTimerDeliveryRetryTelemetry()
    {
        _lastLocalTimerDeferralReason = null;
        _localTimerFaultRetryLogged = false;
        _localTimerRetryScheduleFaultLogged = false;
    }

    private static void ProcessPendingSystemAction()
    {
        var pending = _pendingSystemAction;
        if (pending == null)
            return;
        if (!FormalIntegrationStopBleedPolicy.Evaluate(
                Plugin.FormalIntegrationActive,
                Plugin.AdvancedComputerActionsEnabled.Value)
            .DesktopToolsEffective)
        {
            _pendingSystemAction = null;
            Plugin.PluginLog.LogWarning(
                "Cancelled a deferred legacy system action because desktop "
                + "tool authority is no longer admitted.");
            return;
        }
        if (_requestInFlight || !PendingReplies.IsEmpty)
        {
            pending.ExecuteAfter = Math.Max(pending.ExecuteAfter, Time.unscaledTime + 12f);
            return;
        }
        if (Time.unscaledTime < pending.ExecuteAfter)
            return;
        _pendingSystemAction = null;
        try
        {
            var success = pending.Action switch
            {
                "lock" => LockWorkStation(),
                "sleep" => SetSuspendState(false, false, false),
                _ => false
            };
            if (!success)
                Plugin.PluginLog.LogWarning($"Pending system action '{pending.Action}' was rejected by Windows or is unavailable on this PC.");
            else
                Plugin.PluginLog.LogInfo($"Executed explicit user-requested system action '{pending.Action}'.");
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Pending system action '{pending.Action}' failed: {exception.Message}");
        }
    }

    private static double GetWindowsIdleSeconds()
    {
        if (!OperatingSystem.IsWindows()) return 0;
        var info = new LastInputInfo { Size = (uint)Marshal.SizeOf<LastInputInfo>() };
        if (!GetLastInputInfo(ref info)) return 0;
        return unchecked((uint)Environment.TickCount - info.Time) / 1000d;
    }

    private sealed class GeneratedAiNote
    {
        public string EventId { get; set; } = string.Empty;
        public string Text { get; set; } = string.Empty;
        public bool LivingContinuityOwned { get; set; }
        public long ConfigurationGeneration { get; set; }
        public CharacterRuntimeIdentity RuntimeIdentity { get; set; } =
            null!;
        public LivingProactiveNotePluginOperation? Operation { get; set; }
    }

    internal static void InitializePlayerDataStorage()
    {
        var localApplicationData =
            Environment.GetFolderPath(
                Environment.SpecialFolder.LocalApplicationData);
        var environmentD029ProfileId =
            Environment.GetEnvironmentVariable(
                D029IsolatedTestProfile.EnvironmentVariableName);
        var d029IsolationRequested =
            !string.IsNullOrWhiteSpace(environmentD029ProfileId)
            || D029IsolatedTestProfile.HasActivationTicket(
                localApplicationData);
        string? requestedD029ProfileId = null;
        try
        {
            requestedD029ProfileId =
                D029IsolatedTestProfile.ResolveRequestedProfileId(
                    environmentD029ProfileId,
                    localApplicationData,
                    DateTimeOffset.UtcNow);
            PlayerDataStorageResult storage;
            if (D029IsolatedTestProfile.TryResolve(
                    requestedD029ProfileId,
                    localApplicationData,
                    out var isolated))
            {
                if (!Plugin.D029AggressiveIntegrationEnabled.Value)
                {
                    throw new InvalidOperationException(
                        "An isolated D-029 Profile was requested while "
                        + "the independently Default-Off coordinator was "
                        + "disabled.");
                }
                _d029IsolatedTestProfile = isolated;
                storage = PlayerDataStorage.PrepareIsolatedD029(
                    isolated!,
                    message => Plugin.PluginLog.LogInfo(message));
                ConfigureD029IsolatedNativeNotes(isolated!);
            }
            else
            {
                storage = PlayerDataStorage.Prepare(
                    MemoryDirectory,
                    localApplicationData,
                    message => Plugin.PluginLog.LogInfo(message),
                    message => Plugin.PluginLog.LogWarning(message));
            }
            PlayerDataRootDirectory = storage.RootDirectory;
            PlayerProfileDirectory = storage.ProfileDirectory;
            MemoryPath = storage.MemoryPath;
            MemoryCoreShadowDirectory = storage.MemoryCoreDirectory;
            AiNoteStatePath = storage.AiNoteStatePath;
            PlayerStateDirectory = storage.StateDirectory;
            ApplicationLauncherPath = storage.ApplicationLauncherPath;

            Plugin.PluginLog.LogInfo(
                $"Player data storage ready: state={storage.State}, filesCopied={storage.MigratedFileCount}, bytesCopied={storage.MigratedBytes}, legacyFallback={storage.UsesLegacyFallback}.");
        }
        catch (Exception exception)
        {
            if (d029IsolationRequested)
            {
                Plugin.D029AggressiveIntegrationEnabled.Value = false;
                Plugin.AiNotesEnabled.Value = false;
                Plugin.LivingContinuityProactiveNoteEnabled.Value = false;
                Plugin
                    .LivingContinuityUnifiedProactiveNoteProviderEnabled
                    .Value = false;
                _d029IsolatedNativeNotesReady = false;
                var failClosedRoot = Path.Combine(
                    localApplicationData,
                    PlayerDataStorage.ProductDirectoryName,
                    "TestData",
                    "D029",
                    "failed-closed",
                    Guid.NewGuid().ToString("N"));
                SetPlayerDataPathsToFailClosedRoot(failClosedRoot);
                Plugin.PluginLog.LogError(
                    "D-029 isolated Profile activation failed closed after "
                    + exception.GetType().Name
                    + ": "
                    + exception.Message
                    + "; coordinator disabled and production player data "
                    + "was not selected.");
                return;
            }
            PlayerDataRootDirectory = MemoryDirectory;
            PlayerProfileDirectory = MemoryDirectory;
            MemoryPath = Path.Combine(MemoryDirectory, "memory.json");
            MemoryCoreShadowDirectory = Path.Combine(MemoryDirectory, "memory-core-shadow-v1");
            AiNoteStatePath = Path.Combine(MemoryDirectory, "ai-note-state.json");
            PlayerStateDirectory = MemoryDirectory;
            ApplicationLauncherPath = Path.Combine(MemoryDirectory, "applications.json");
            Plugin.PluginLog.LogWarning(
                $"Could not initialize protected player-data storage; the original game-local copy remains authoritative: {exception.GetType().Name}.");
        }
        finally
        {
            InitializeForegroundProactiveStateMachine();
        }
    }

    private static void InitializeForegroundProactiveStateMachine()
    {
        try
        {
            var statePath = Path.Combine(
                PlayerStateDirectory,
                "foreground-proactive-v1.json");
            _foregroundProactiveStateMachine =
                new ForegroundProactiveStateMachine(
                    new AtomicJsonForegroundProactiveStateStore(statePath),
                    SystemForegroundProactiveClock.Instance,
                    SystemForegroundProactiveRandom.Instance);
            Plugin.PluginLog.LogInfo(
                "Foreground proactive lifecycle state is ready: load="
                + _foregroundProactiveStateMachine.LoadStatus
                + ".");
        }
        catch (Exception exception)
        {
            _foregroundProactiveStateMachine = null;
            Plugin.PluginLog.LogWarning(
                "Foreground proactive lifecycle state failed closed: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void ConfigureD029IsolatedNativeNotes(
        D029IsolatedTestProfile profile)
    {
        Directory.CreateDirectory(profile.NativeNotesDirectory);
        var expected = Path.GetFullPath(
            profile.NativeNotesDirectory);
        var expectedRoot = Path.GetFullPath(profile.ScopeDirectory)
            .TrimEnd(
                Path.DirectorySeparatorChar,
                Path.AltDirectorySeparatorChar)
            + Path.DirectorySeparatorChar;
        if (!expected.StartsWith(
                expectedRoot,
                StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "The D-029 Note sink escaped its isolated Profile root.");
        }
        _d029IsolatedNativeNotesReady = true;
        Plugin.PluginLog.LogInfo(
            "D-029 private bounded Note sink ready for this process; "
            + "native Note fields and production Notes remain untouched.");
    }

    private static string ResolveCurrentNativeNotesDirectory()
    {
        if (_d029IsolatedTestProfile != null
            && _d029IsolatedNativeNotesReady)
        {
            // NoteInbox.NotesDirectory is an IL2CPP native computed getter.
            // It may retain the original persistentDataPath even after its
            // NotesFolder field is safely redirected, and invoking it during
            // a two-stage Steam handoff has produced invalid wrapper lifetime
            // failures.  The isolated profile path is already typed, bounded,
            // private and verified against both native folder fields above.
            return _d029IsolatedTestProfile.NativeNotesDirectory;
        }

        return NoteInbox.NotesDirectory;
    }

    private static void SetPlayerDataPathsToFailClosedRoot(
        string root)
    {
        PlayerDataRootDirectory = root;
        PlayerProfileDirectory = Path.Combine(root, "player-data");
        MemoryPath = Path.Combine(
            PlayerProfileDirectory,
            "memory.json");
        MemoryCoreShadowDirectory = Path.Combine(
            PlayerProfileDirectory,
            "memory-core-shadow-v1");
        AiNoteStatePath = Path.Combine(
            PlayerProfileDirectory,
            "state",
            "ai-note-state.json");
        PlayerStateDirectory = Path.Combine(
            PlayerProfileDirectory,
            "state");
        ApplicationLauncherPath = Path.Combine(
            root,
            "config",
            "applications.json");
    }

    internal static void LoadMemory()
    {
        // Compatibility seam only: both legacy memory and transcript hosts are
        // retired. F10 reads Hermes through the authenticated game bridge.
        // Never import, create, read or write a local transcript from this seam.
        lock (MemoryLock)
            RecentConversation.Clear();
    }

    public sealed class ChatTurn
    {
        public string Role { get; set; } = string.Empty;
        public string Text { get; set; } = string.Empty;
    }

    private static string[] SplitIntoBubblePages(string text)
    {
        var completeText = text.Trim();
        return completeText.Length == 0 ? Array.Empty<string>() : new[] { completeText };
    }

    internal static bool TryAdvanceAiPage(DialogueManager manager)
    {
        if (!_aiPagesAwaitingAdvance)
            return false;
        var currentNode = manager.CurrentNode;
        if (currentNode == null || !string.Equals(currentNode.text, _currentAiPageText, StringComparison.Ordinal))
        {
            CancelPendingAiPages("Native dialogue took control.");
            return false;
        }
        if (!PendingReplies.TryDequeue(out var page))
        {
            _aiPagesAwaitingAdvance = false;
            return false;
        }
        RefreshMiniGameAnswerRepairLifetime();
        var currentRuntimeGeneration =
            CurrentPlayerTurnRuntimeGeneration();
        var publicationAdmission =
            PlayerTurnOperations.EvaluatePublication(
                page.Operation,
                page.PublicationKind,
                currentRuntimeGeneration);
        if (publicationAdmission
            != PlayerTurnPublicationAdmission.Admitted)
        {
            _aiPagesAwaitingAdvance = false;
            var retiredForRuntimeChange =
                TryRetireRuntimeChangedPlayerTurn(
                    page.Operation,
                    publicationAdmission,
                    currentRuntimeGeneration);
            var failedRejectedPhase = publicationAdmission
                    == PlayerTurnPublicationAdmission.PhaseRejected
                && TryFailAndReleasePlayerTurnPublication(page.Operation);
            if (publicationAdmission
                    == PlayerTurnPublicationAdmission.NoActiveOperation
                || retiredForRuntimeChange
                || failedRejectedPhase)
            {
                _requestInFlight = false;
            }
            Plugin.PluginLog.LogWarning(
                "Discarded a stale continuation page before "
                + "DialogueManager publication; admission="
                + publicationAdmission
                + ".");
            return false;
        }
        _aiPagesAwaitingAdvance = HasPendingPageForOperation(page.Operation);
        _currentAiPageText = page.Text;
        _currentAiPageOperation = page.Operation;
        _aiTypingFinishedAt = -1f;
        var operationEnded = false;
        AgentLanguagePublicationLease? languageLease = null;
        var agentPublicationFinished = false;
        try
        {
            if (!TryAcquireAgentLanguageOutput(
                    manager,
                    AgentLanguageSourceKind.OrdinaryPlayerTurn,
                    page.Operation.OperationId,
                    out languageLease,
                    out var languageArbitration)
                || languageLease == null)
            {
                operationEnded = TryFailAndReleasePlayerTurnPublication(
                    page.Operation);
                Plugin.PluginLog.LogWarning(
                    "Continuation language arbitration rejected publication "
                    + "before DialogueManager: reason="
                    + (languageArbitration?.Reason.ToString()
                        ?? "HostFaulted")
                    + ".");
            }
            else
            {
                ForceSaySynthetic(manager, page.Text, string.Empty, 30f);
                agentPublicationFinished =
                    TryRecordAgentLanguagePublication(
                        languageLease,
                        published: true);
                if (!agentPublicationFinished)
                {
                    operationEnded =
                        TryFailAndReleasePlayerTurnPublication(page.Operation);
                }
                else
                {
                    var publicationCommitGeneration =
                        CurrentPlayerTurnRuntimeGeneration();
                    if (PlayerTurnOperations.TryPublish(
                            page.Operation,
                            page.PublicationKind,
                            publicationCommitGeneration))
                    {
                        StartPublishedPlayerReplySpeech(
                            page,
                            publicationCommitGeneration,
                            languageLease.CycleSequence);
                        // Hermes owns persistence; no legacy memory mirror.
                        operationEnded = CompletePublishedPlayerTurn(page);
                    }
                    else
                    {
                        var commitAdmission =
                            PlayerTurnOperations.EvaluatePublication(
                                page.Operation,
                                page.PublicationKind,
                                publicationCommitGeneration);
                        operationEnded = commitAdmission
                                == PlayerTurnPublicationAdmission.NoActiveOperation
                            || TryRetireRuntimeChangedPlayerTurn(
                                page.Operation,
                                commitAdmission,
                                publicationCommitGeneration);
                        if (!operationEnded)
                        {
                            operationEnded =
                                TryFailAndReleasePlayerTurnPublication(
                                    page.Operation);
                        }
                    }
                }
            }
        }
        catch
        {
            if (languageLease != null && !agentPublicationFinished)
            {
                TryRecordAgentLanguagePublication(
                    languageLease,
                    published: false);
            }
            TryFailAndReleasePlayerTurnPublication(page.Operation);
            throw;
        }
        if (operationEnded)
            _requestInFlight = false;
        return true;
    }

    private static void CancelPendingAiPages(string reason)
    {
        while (PendingReplies.TryDequeue(out var cancelledPage))
            HermesNoteCandidates.Retire(cancelledPage.Operation);
        if (_currentAiPageOperation != null)
            HermesNoteCandidates.Retire(_currentAiPageOperation);
        _ = _currentAiPageOperation != null
            && PlayerTurnOperations.TryCancel(
                _currentAiPageOperation,
                PlayerTurnCancellationReason.NativeDialogueTookControl);
        _aiPagesAwaitingAdvance = false;
        _currentAiPageText = string.Empty;
        _currentAiPageOperation = null;
        Plugin.PluginLog.LogInfo($"Cancelled pending AI pages: {reason}");
    }

    internal static void NotifyAiTypingState(bool isTyping)
    {
        if (string.IsNullOrEmpty(_currentAiPageText))
            return;
        _aiTypingFinishedAt = isTyping ? -1f : Time.unscaledTime;
    }

    internal static bool ShouldDelayAiCompletion(DialogueManager manager)
    {
        var node = manager.CurrentNode;
        if (node == null || !string.Equals(node.text, _currentAiPageText, StringComparison.Ordinal))
            return false;
        if (HasActivePublishedPlayerReplySpeech())
            return true;
        // Keep the current bubble alive while another AI page is waiting for the
        // user's click. Speech is generated for the complete reply and may continue
        // past the first page, so allowing Unity to close here makes the text look
        // truncated even though the response itself is complete.
        if (_aiPagesAwaitingAdvance)
            return true;
        if (_aiTypingFinishedAt < 0f)
            return true;
        return Time.unscaledTime - _aiTypingFinishedAt < Math.Max(0f, Plugin.PostTypingHoldSeconds.Value);
    }

    internal static bool IsCurrentPublishedAiPageNode(DialogueNode? node)
        => node != null
            && _currentAiPageOperation != null
            && string.Equals(
                node.text,
                _currentAiPageText,
                StringComparison.Ordinal);

    private static void CloseInputBubble(bool clear)
    {
        if (_inputField != null)
        {
            _inputField.DeactivateInputField();
            if (clear)
                _inputField.text = string.Empty;
        }

        // TMP_InputField can retain a stale activation state after its parent is
        // hidden in this IL2CPP build. Recreate the lightweight bubble on the next
        // invocation so every F7 session starts with a clean input component.
        if (_inputBubble != null)
            UnityEngine.Object.Destroy(_inputBubble);
        _inputBubble = null;
        _inputField = null;
        _inputPlaceholder = null;
        _focusNextFrame = false;
    }
}

