[HarmonyPatch]
internal static class NativeNoteWriterOriginScopePatch
{
    private const int ExpectedTargetCount = 14;

    private static IEnumerable<MethodBase> TargetMethods()
    {
        var targets = new List<MethodBase>();
        var missing = new List<string>();
        AddTargets(
            targets,
            missing,
            typeof(WriteNoteBehavior),
            "Begin",
            "Tick");
        AddTargets(
            targets,
            missing,
            typeof(BirthdayNoteBehavior),
            "Begin",
            "Tick");
        AddTargets(targets, missing, typeof(AnniversaryNote), "Tick");
        AddTargets(targets, missing, typeof(PlaytimeMilestoneNote), "Tick");
        AddTargets(
            targets,
            missing,
            typeof(DialogueManager),
            "TrySaveNoteSilently");
        AddTargets(
            targets,
            missing,
            typeof(GameManagerSystem),
            "TriggerWriteNoteWithFeedback");
        AddTargets(
            targets,
            missing,
            typeof(LilithStateManager),
            "TrySaveSleepStartupNote",
            "SaveSleepStartupNoteNextFrame",
            "TrySaveSecondLaunchNote",
            "SaveSecondLaunchNoteNextFrame");

        var stateManager = typeof(LilithStateManager);
        var sleepCoroutineFound = false;
        var secondLaunchCoroutineFound = false;
        if (stateManager != null)
        {
            foreach (var nested in stateManager.GetNestedTypes(
                         BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (!nested.Name.StartsWith(
                        "_SaveSleepStartupNoteNextFrame_d__",
                        StringComparison.Ordinal)
                    && !nested.Name.StartsWith(
                        "_SaveSecondLaunchNoteNextFrame_d__",
                        StringComparison.Ordinal))
                {
                    continue;
                }

                var moveNext = AccessTools.Method(nested, "MoveNext");
                if (moveNext != null
                    && ReferenceEquals(moveNext.DeclaringType, nested))
                {
                    targets.Add(moveNext);
                    sleepCoroutineFound |= nested.Name.StartsWith(
                        "_SaveSleepStartupNoteNextFrame_d__",
                        StringComparison.Ordinal);
                    secondLaunchCoroutineFound |= nested.Name.StartsWith(
                        "_SaveSecondLaunchNoteNextFrame_d__",
                        StringComparison.Ordinal);
                }
            }
        }

        if (!sleepCoroutineFound)
            missing.Add("SleepStartupCoroutine.MoveNext");
        if (!secondLaunchCoroutineFound)
            missing.Add("SecondLaunchCoroutine.MoveNext");

        var distinctTargets = targets.Distinct().ToArray();
        if (missing.Count == 0
            && distinctTargets.Length == ExpectedTargetCount)
        {
            Plugin.PluginLog.LogInfo(
                "Native Note writer-origin coverage complete"
                + $" targets={distinctTargets.Length}.");
        }
        else
        {
            var missingDescription = missing.Count == 0
                ? "none"
                : string.Join("|", missing);
            Plugin.PluginLog.LogError(
                "Native Note writer-origin coverage incomplete"
                + $" targets={distinctTargets.Length}"
                + $" expected={ExpectedTargetCount}"
                + $" missing={missingDescription}.");
            throw new MissingMethodException(
                "Native Note writer-origin coverage is incomplete;"
                + " no writer-origin patch may be installed.");
        }

        return distinctTargets;
    }

    private static void Prefix(
        MethodBase __originalMethod,
        out NativeNoteWriterScope __state)
    {
        try
        {
            var origin = NativeNoteWriterOriginClassifier.FromEntryPoint(
                __originalMethod.DeclaringType?.Name,
                __originalMethod.Name);
            __state = NativeNoteWriteProvenanceRuntime.EnterWriter(
                Plugin.NativeNoteWriteProvenanceEnabled.Value
                    && Plugin.NativeNoteOfficialWriterScopesEnabled.Value,
                origin);
        }
        catch
        {
            __state = default;
        }
    }

    private static Exception? Finalizer(
        Exception? __exception,
        NativeNoteWriterScope __state)
    {
        try
        {
            __state.Dispose();
        }
        catch
        {
            // Origin attribution must never change official Note behavior.
        }
        return __exception;
    }

    private static void AddTargets(
        ICollection<MethodBase> targets,
        ICollection<string> missing,
        Type type,
        params string[] methodNames)
    {
        foreach (var methodName in methodNames)
        {
            var method = AccessTools.Method(type, methodName);
            if (method != null
                && ReferenceEquals(method.DeclaringType, type))
                targets.Add(method);
            else
                missing.Add(type.Name + "." + methodName);
        }
    }
}

[HarmonyPatch(typeof(NoteImageSaver), nameof(NoteImageSaver.SaveNote))]
internal static class NativeNoteWriteProvenanceSinkPatch
{
    private static void Prefix(out NativeNoteSinkAttempt __state)
    {
        try
        {
            __state = NativeNoteWriteProvenanceRuntime.BeginCommonSink(
                Plugin.NativeNoteWriteProvenanceEnabled.Value);
        }
        catch
        {
            __state = NativeNoteSinkAttempt.Disabled;
        }
    }

    private static void Postfix(
        string __result,
        NativeNoteSinkAttempt __state)
    {
        try
        {
            LogReceipt(
                NativeNoteWriteProvenanceRuntime
                    .TryCompleteSuccessfulExistingWrite(
                        __state,
                        __result,
                        NoteImageSaver.NotesFolder));
        }
        catch
        {
            // Provenance must never change a successful native Note result.
        }
    }

    private static Exception? Finalizer(
        Exception? __exception,
        NativeNoteSinkAttempt __state)
    {
        if (__exception != null)
        {
            try
            {
                LogReceipt(
                    NativeNoteWriteProvenanceRuntime
                        .TryCompleteSinkThrew(__state));
            }
            catch
            {
                // Provenance must preserve the original native exception.
            }
        }
        return __exception;
    }

    private static void LogReceipt(
        NativeNoteWriteProvenanceReceipt? receipt)
    {
        if (receipt == null)
            return;

        try
        {
            var artifact = receipt.TerminalStatus
                    == NativeNoteWriteTerminalStatus.Succeeded
                ? $" bytes={receipt.ByteSize} sha256={receipt.FileSha256}"
                : string.Empty;
            Plugin.PluginLog.LogInfo(
                "Native Note writer-origin receipt"
                + $" processEpoch={receipt.ProcessEpoch}"
                + $" sequence={receipt.Sequence}"
                + $" monotonicTicks={receipt.ObservedAtMonotonicTicks}"
                + $" origin={receipt.WriterOrigin}"
                + $" status={receipt.TerminalStatus}"
                + artifact
                + ".");
        }
        catch
        {
            // Provenance must never change the native Note result.
        }
    }
}

[HarmonyPatch(typeof(global::CharacterController), nameof(global::CharacterController.HideAwayUntilSummoned))]
internal static class CharacterControllerSafetyHidePatch
{
    private static bool _recovering;
    private static float _suppressRepeatedHideUntil = -1f;
    private static float _lastVisibleSuppressionLogAt = -10f;

    private static bool Prefix(global::CharacterController __instance)
    {
        if (__instance == null)
            return true;

        try
        {
            // The official neglect/relationship hide is a deliberate character state.
            // Only replace the safety watchdog's HiddenAway path.
            if (__instance.IsNeglectHidden
                || __instance.ControlMode == LilithControlMode.NeglectHidden)
            {
                return true;
            }

            // The native cannot-settle watchdog also fires during a long sequence
            // of valid catches and throws.  If any part of Lilith still intersects
            // the usable screen, there is nothing to rescue and resetting her to
            // the centre would be more disruptive than the watchdog condition.
            if (DialogueManagerUpdatePatch.IsCharacterStillInsideVisibleSafetyArea(
                    out var visibleBounds))
            {
                if (Time.unscaledTime - _lastVisibleSuppressionLogAt >= 1f)
                {
                    _lastVisibleSuppressionLogAt = Time.unscaledTime;
                    Plugin.PluginLog.LogInfo(
                        $"Suppressed native cannot-settle reset while Lilith remains visible: bounds={visibleBounds}.");
                }
                return false;
            }

            if (_recovering || Time.unscaledTime < _suppressRepeatedHideUntil)
                return false;

            _recovering = true;
            __instance.ResetPosition();
            var state = UnityEngine.Object.FindObjectOfType<LilithStateManager>();
            DialogueManagerUpdatePatch.NotifyAutomaticSafetyRecovery(__instance, state);
            _suppressRepeatedHideUntil = Time.unscaledTime + 0.5f;
            Plugin.PluginLog.LogInfo(
                "Replaced native safety hide with automatic position recovery; coherent showcase may continue.");
            return false;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Automatic safety-position recovery failed; allowing the native hide fallback: {exception.Message}");
            return true;
        }
        finally
        {
            _recovering = false;
        }
    }
}

[HarmonyPatch(typeof(LilithControlArbiter), nameof(LilithControlArbiter.EnterHiddenAway))]
internal static class LilithControlArbiterHiddenAwayPatch
{
    private static readonly System.Reflection.FieldInfo? OwnerField =
        AccessTools.Field(typeof(LilithControlArbiter), "_owner");

    private static bool Prefix(LilithControlArbiter __instance)
    {
        try
        {
            var character = OwnerField?.GetValue(__instance) as global::CharacterController;
            if (character == null)
            {
                Plugin.PluginLog.LogWarning(
                    "Low-level HiddenAway entry was observed, but its CharacterController owner could not be resolved.");
                return true;
            }

            var recovered = DialogueManagerUpdatePatch.RecoverCharacterFromHiddenState(
                character,
                "low-level control arbiter",
                cancelNeglect: false);
            if (recovered)
            {
                Plugin.PluginLog.LogInfo(
                    "Suppressed low-level LilithControlArbiter.EnterHiddenAway after automatic recovery.");
            }
            return !recovered;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                $"Low-level HiddenAway recovery failed; allowing the native fallback: {exception.Message}");
            return true;
        }
    }
}

