[HarmonyPatch(typeof(DialogueManager), "PlayNodeVoice")]
internal static class DialogueManagerPlayNodeVoicePatch
{
    private static bool Prefix(DialogueNode node)
    {
        try
        {
            if (DialogueManagerUpdatePatch
                    .HasActivePublishedPlayerReplySpeech())
            {
                Plugin.PluginLog.LogInfo(
                    "Suppressed lower-priority dialogue voice while F6/F7 "
                    + "reply speech owns the shared channel.");
                return false;
            }
            if (DialogueManagerUpdatePatch.IsCurrentPublishedAiPageNode(node))
                return false;
            if (DialogueManagerUpdatePatch.IsCurrentMiniGameDialogueNode(node))
                return false;
            DialogueManagerUpdatePatch.CancelMiniGameDialogueForNativeVoiceTakeover();
            DialogueManagerUpdatePatch.NotifyNativeVoiceTakeover();
            // Prerecorded voice, language selection and duration belong to the
            // official game. Language synchronization uses its settings model;
            // this audio seam never chooses or replaces prerecorded clips.
            return true;
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning($"Could not inspect native dialogue voice: {exception.Message}");
            return true;
        }
    }
}

internal static class NativeDialogueHermesCapturePatches
{
    internal static void Install(string harmonyId)
    {
        var showNode = RequiredDeclaredMethod(
            typeof(DialogueBubbleUI),
            "ShowNode");
        var typewriterPlay = RequiredDeclaredMethod(
            typeof(TypewriterEffect),
            "Play");
        var setIsTyping = RequiredDeclaredMethod(
            typeof(TypewriterEffect),
            "SetIsTyping");
        var typewriterStop = RequiredDeclaredMethod(
            typeof(TypewriterEffect),
            "Stop");
        var typewriterSkip = RequiredDeclaredMethod(
            typeof(TypewriterEffect),
            "Skip");
        var completeCurrentNode = RequiredDeclaredMethod(
            typeof(DialogueManager),
            "CompleteCurrentNode");
        var endDialogue = RequiredDeclaredMethod(
            typeof(DialogueManager),
            "EndDialogue");
        var forceEndDialogue = RequiredDeclaredMethod(
            typeof(DialogueManager),
            "ForceEndDialogue");
        var forceSay = RequiredDeclaredMethod(
            typeof(DialogueManager),
            "ForceSay");
        var sayMethods = RequiredDeclaredMethods(
            typeof(DialogueManager),
            "Say",
            expectedCount: 2);
        var officialAppSay = sayMethods.Single(method =>
        {
            var parameters = method.GetParameters();
            return parameters.Length == 5
                && parameters[0].ParameterType == typeof(string)
                && parameters[1].ParameterType == typeof(string)
                && parameters[2].ParameterType == typeof(float)
                && parameters[3].ParameterType == typeof(int)
                && parameters[4].ParameterType == typeof(bool);
        });

        var harmony = new Harmony(harmonyId);
        try
        {
            harmony.Patch(
                officialAppSay,
                prefix: Patch(nameof(OfficialAppSayPrefix)),
                postfix: Patch(nameof(OfficialAppSayPostfix)),
                finalizer: Patch(nameof(OfficialAppSayFinalizer)));
            harmony.Patch(
                forceSay,
                prefix: Patch(nameof(ForceSayPrefix)),
                postfix: Patch(nameof(ForceSayPostfix)),
                finalizer: Patch(nameof(ForceSayFinalizer)));
            harmony.Patch(
                showNode,
                prefix: Patch(nameof(ShowNodePrefix)),
                postfix: Patch(nameof(ShowNodePostfix)),
                finalizer: Patch(nameof(ShowNodeFinalizer)));
            harmony.Patch(
                typewriterPlay,
                prefix: Patch(nameof(TypewriterPlayPrefix)),
                postfix: Patch(nameof(TypewriterPlayPostfix)),
                finalizer: Patch(nameof(TypewriterPlayFinalizer)));
            harmony.Patch(
                setIsTyping,
                postfix: Patch(nameof(SetIsTypingPostfix)));
            harmony.Patch(
                typewriterStop,
                prefix: Patch(nameof(TypewriterStopPrefix)),
                postfix: Patch(nameof(TypewriterStopPostfix)),
                finalizer: Patch(nameof(TypewriterStopFinalizer)));
            harmony.Patch(
                typewriterSkip,
                prefix: Patch(nameof(TypewriterSkipPrefix)));
            harmony.Patch(
                completeCurrentNode,
                prefix: Patch(nameof(CompleteCurrentNodePrefix)),
                postfix: Patch(nameof(CompleteCurrentNodePostfix)),
                finalizer: Patch(nameof(CompleteCurrentNodeFinalizer)));
            harmony.Patch(
                endDialogue,
                prefix: Patch(nameof(EndDialoguePrefix)),
                postfix: Patch(nameof(EndDialoguePostfix)),
                finalizer: Patch(nameof(EndDialogueFinalizer)));
            harmony.Patch(
                forceEndDialogue,
                prefix: Patch(nameof(ForceEndDialoguePrefix)));
        }
        catch
        {
            Harmony.UnpatchID(harmonyId);
            throw;
        }
    }

    private static MethodInfo RequiredDeclaredMethod(
        Type declaringType,
        string name)
    {
        var methods = AccessTools.GetDeclaredMethods(declaringType)
            .Where(method => string.Equals(
                method.Name,
                name,
                StringComparison.Ordinal))
            .ToArray();
        return methods.Length == 1
            ? methods[0]
            : throw new MissingMethodException(
                declaringType.FullName,
                name);
    }

    private static MethodInfo[] RequiredDeclaredMethods(
        Type declaringType,
        string name,
        int expectedCount)
    {
        var methods = AccessTools.GetDeclaredMethods(declaringType)
            .Where(method => string.Equals(
                method.Name,
                name,
                StringComparison.Ordinal))
            .ToArray();
        return methods.Length == expectedCount
            ? methods
            : throw new MissingMethodException(
                declaringType.FullName,
                name);
    }

    private static HarmonyMethod Patch(string name)
        => new(
            typeof(NativeDialogueHermesCapturePatches),
            name);

    private static void OfficialAppSayPrefix(
        string __0,
        int __3,
        out NativeDialogueOfficialAppSpeechToken __state)
        => __state = DialogueManagerUpdatePatch
            .BeginNativeDialogueOfficialAppSpeech(__0, __3);

    private static void OfficialAppSayPostfix(
        DialogueManager __instance,
        NativeDialogueOfficialAppSpeechToken __state,
        bool __result)
        => DialogueManagerUpdatePatch
            .CompleteNativeDialogueOfficialAppSpeech(
                __instance,
                __state,
                __result);

    private static Exception? OfficialAppSayFinalizer(
        NativeDialogueOfficialAppSpeechToken __state,
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .FailNativeDialogueOfficialAppSpeech(__state);
        }
        return __exception;
    }

    private static void ForceSayPrefix(
        DialogueManager __instance,
        out NativeDialogueForceSayInvocationToken __state)
        => __state = DialogueManagerUpdatePatch
            .BeginNativeDialogueForceSayInvocation(__instance);

    private static void ForceSayPostfix(
        DialogueManager __instance,
        NativeDialogueForceSayInvocationToken __state,
        bool __result)
        => DialogueManagerUpdatePatch
            .CompleteNativeDialogueForceSayInvocation(
                __instance,
                __state,
                __result);

    private static Exception? ForceSayFinalizer(
        NativeDialogueForceSayInvocationToken __state,
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .FailNativeDialogueForceSayInvocation(__state);
        }
        return __exception;
    }

    private static void ShowNodePrefix(
        DialogueBubbleUI __instance,
        DialogueNode node,
        out long __state)
        => __state = DialogueManagerUpdatePatch
            .BeginNativeDialogueHermesCapture(__instance, node);

    private static void ShowNodePostfix(
        DialogueBubbleUI __instance,
        long __state)
        => DialogueManagerUpdatePatch
            .EndNativeDialogueHermesShowNode(
                __instance,
                __state,
                succeeded: true);

    private static Exception? ShowNodeFinalizer(
        DialogueBubbleUI __instance,
        long __state,
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .EndNativeDialogueHermesShowNode(
                    __instance,
                    __state,
                    succeeded: false);
        }
        return __exception;
    }

    private static void TypewriterPlayPrefix(
        TypewriterEffect __instance,
        out long __state)
        => __state = DialogueManagerUpdatePatch
            .BeginNativeDialogueTypewriterPlay(__instance);

    private static void TypewriterPlayPostfix(
        TypewriterEffect __instance,
        string text,
        long __state)
    {
        try
        {
            DialogueManagerUpdatePatch
                .ObserveNativeDialogueDisplayedText(
                    __instance,
                    __state,
                    text);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Could not observe completed native dialogue text: "
                + exception.GetType().Name
                + ".");
        }
        finally
        {
            DialogueManagerUpdatePatch
                .EndNativeDialogueTypewriterPlay(
                    __instance,
                    __state);
        }
    }

    private static Exception? TypewriterPlayFinalizer(
        TypewriterEffect __instance,
        long __state,
        Exception? __exception)
    {
        if (__exception != null && __state != 0)
        {
            DialogueManagerUpdatePatch
                .FailNativeDialogueTypewriterPlay(
                    __instance,
                    __state);
        }
        return __exception;
    }

    private static void SetIsTypingPostfix(
        TypewriterEffect __instance,
        bool value)
    {
        try
        {
            DialogueManagerUpdatePatch
                .NotifyNativeDialogueTypingState(
                    __instance,
                    value);
        }
        catch (Exception exception)
        {
            Plugin.PluginLog.LogWarning(
                "Could not observe native dialogue typing state: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void TypewriterStopPrefix(
        TypewriterEffect __instance,
        out NativeDialogueTypewriterStopPatchState __state)
        => __state = DialogueManagerUpdatePatch
            .BeginNativeDialogueTypewriterStop(__instance);

    private static void TypewriterStopPostfix(
        NativeDialogueTypewriterStopPatchState __state,
        bool __runOriginal)
        => DialogueManagerUpdatePatch
            .CompleteNativeDialogueTypewriterStop(
                __state,
                __runOriginal);

    private static Exception? TypewriterStopFinalizer(
        NativeDialogueTypewriterStopPatchState __state,
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .FailNativeDialogueTypewriterStop(__state);
        }
        return __exception;
    }

    private static void TypewriterSkipPrefix(
        TypewriterEffect __instance)
        => DialogueManagerUpdatePatch
            .InterruptNativeDialogueTypewriterSkip(__instance);

    private static void CompleteCurrentNodePrefix(
        DialogueManager __instance,
        out NativeDialogueHermesCompletionToken? __state)
    {
        try
        {
            __state = DialogueManagerUpdatePatch
                .BeginNativeDialogueHermesCompletion(__instance);
        }
        catch (Exception exception)
        {
            __state = null;
            DialogueManagerUpdatePatch
                .InterruptNativeDialogueHermesCapture();
            Plugin.PluginLog.LogWarning(
                "Could not close native dialogue memory capture: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void CompleteCurrentNodePostfix(
        NativeDialogueHermesCompletionToken? __state,
        bool __runOriginal)
        => DialogueManagerUpdatePatch
            .CompleteNativeDialogueHermesCapture(
                __state,
                __runOriginal);

    private static Exception? CompleteCurrentNodeFinalizer(
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .InterruptNativeDialogueHermesCapture();
        }
        return __exception;
    }

    private static void EndDialoguePrefix(
        DialogueManager __instance,
        bool naturalEnd,
        out NativeDialogueHermesCompletionToken? __state)
    {
        try
        {
            if (naturalEnd)
            {
                __state = DialogueManagerUpdatePatch
                    .BeginNativeDialogueHermesCompletion(__instance);
                return;
            }
            __state = null;
            DialogueManagerUpdatePatch
                .InterruptNativeDialogueHermesCapture();
        }
        catch (Exception exception)
        {
            __state = null;
            DialogueManagerUpdatePatch
                .InterruptNativeDialogueHermesCapture();
            Plugin.PluginLog.LogWarning(
                "Could not close native dialogue memory capture at natural dialogue end: "
                + exception.GetType().Name
                + ".");
        }
    }

    private static void EndDialoguePostfix(
        bool naturalEnd,
        NativeDialogueHermesCompletionToken? __state,
        bool __runOriginal)
    {
        if (naturalEnd)
        {
            DialogueManagerUpdatePatch
                .CompleteNativeDialogueHermesCapture(
                    __state,
                    __runOriginal);
        }
    }

    private static Exception? EndDialogueFinalizer(
        Exception? __exception)
    {
        if (__exception != null)
        {
            DialogueManagerUpdatePatch
                .InterruptNativeDialogueHermesCapture();
        }
        return __exception;
    }

    private static void ForceEndDialoguePrefix()
        => DialogueManagerUpdatePatch
            .InterruptNativeDialogueHermesCapture();
}

